/**
 * Cross-boundary guards: SynthParams keys, Note shape, drum tuning ranges.
 */
import { describe, expect, it } from 'vitest';
import type { SynthParams, Bass2Params, Note } from '../types';
import { RbsImporter } from '../importers/rbs/RbsImporter';
import { RbsParser } from '../importers/rbs/RbsParser';
import type { HyphonAutomationLane } from '../importers/rbs/types';
import { AUTOMATION_PARAMETER_MAP } from '../importers/rbs/types';

const SYNTH_PARAM_KEYS = new Set(Object.keys({
  waveform: 0,
  pitch: 0,
  filterCutoff: 0,
  filterResonance: 0,
  filterMode: 0,
  attack: 0,
  decay: 0,
  sustain: 0,
  release: 0,
  length: 0,
  volume: 0,
  pan: 0,
  delayTime: 0,
  delayFeedback: 0,
  delayMix: 0,
  engine303: 'open303',
  model303: 'stock-open303',
  model303Extra: undefined,
  pitchAttack: 0,
  pitchDecay: 0,
  pitchAmount: 0,
  vowel: 0,
  portamento: 0,
  formantShift: 0,
  cppFine: 0,
  drive: 0,
  formantPitchLink: 0,
  coarseTune: 0,
  fineTune: 0,
} satisfies Record<keyof SynthParams, unknown>));

const BASS2_PARAM_KEYS = new Set(Object.keys({
  waveform: '303-saw',
  cutoff: 0,
  resonance: 0,
  filterMode: 0,
  decay: 0,
  accent: 0,
  envMod: 0,
  volume: 0,
  pitch: 0,
  pan: 0,
  engine303: 'open303',
  model303: 'stock-open303',
  model303Extra: undefined,
  slideTime: 0,
  drive: 0,
} satisfies Record<keyof Bass2Params, unknown>));

const SYNTH_AUTOMATION_EXTENSIONS = new Set(['accent', 'slide']);

// Master lanes the AutomationScheduler can actually apply (PcfEffect endpoints).
// tempo/swing/volume/drumPcfModulation are intentionally not emitted — see
// convertAutomationLane / convertPcfToAutomation.
const MASTER_AUTOMATION_PARAMS = new Set([
  'pcfCutoff', 'pcfResonance', 'pcfEnvAmount',
]);

const KICK_BOUNDS = { pitch: [40, 80] as const, decay: [0.1, 1.0] as const, tone: [0, 1] as const };
const SNARE_BOUNDS = { tone: [100, 400] as const, noise: [1000, 5000] as const, decay: [0.1, 0.8] as const };
const HAT_BOUNDS = { pitch: [5000, 15000] as const, decay: [0.05, 0.8] as const };

function inRange(v: number, [lo, hi]: readonly [number, number]) {
  expect(v).toBeGreaterThanOrEqual(lo);
  expect(v).toBeLessThanOrEqual(hi);
}

function assertAutomationParameterValid(lane: HyphonAutomationLane) {
  const { target, parameter } = lane;
  if (target === 'synthA' || target === 'synthB') {
    expect(
      SYNTH_PARAM_KEYS.has(parameter) || SYNTH_AUTOMATION_EXTENSIONS.has(parameter)
    ).toBe(true);
  } else if (target === 'bass2') {
    expect(
      BASS2_PARAM_KEYS.has(parameter) || SYNTH_AUTOMATION_EXTENSIONS.has(parameter)
    ).toBe(true);
  } else if (target === 'master') {
    expect(MASTER_AUTOMATION_PARAMS.has(parameter)).toBe(true);
  } else if (target === 'kick') {
    expect(['pitch', 'decay', 'tone', 'volume'].includes(parameter)).toBe(true);
  } else if (target === 'snare') {
    expect(['decay', 'tone', 'noise', 'volume'].includes(parameter)).toBe(true);
  } else if (target === 'closedHat' || target === 'openHat') {
    expect(['pitch', 'decay', 'volume'].includes(parameter)).toBe(true);
  }
}

function collectAllNotes(song: ReturnType<RbsImporter['convertToHyphonSong']>['song']): Note[] {
  const notes: Note[] = [];
  for (const steps of [
    song.pattern.partA.steps,
    song.pattern.partB.steps,
    song.pattern.kick.steps,
  ]) {
    for (const s of steps) {
      if (s) notes.push(s);
    }
  }
  return notes;
}

describe('RbsImporter cross-boundary guards', () => {
  it('every emitted automation parameter is valid for its target', () => {
    const importer = new RbsImporter({ convertPcfToAutomation: true });
    const raw = new RbsParser().generateMockData('x.rbs');

    raw.automation = Object.entries(AUTOMATION_PARAMETER_MAP).map(([id, param], idx) => ({
      parameter: param as (typeof raw.automation)[0]['parameter'],
      name: `Lane ${idx}`,
      points: [[0, 64]] as [number, number][],
      interpolation: 'linear' as const,
      range: [0, 127] as [number, number],
    }));

    const result = importer.convertToHyphonSong(raw);
    expect((result.song.automation ?? []).length).toBeGreaterThan(0);
    for (const lane of result.song.automation ?? []) {
      assertAutomationParameterValid(lane);
    }
  });

  it('mapping report SynthParams.* targets are real SynthParams keys', () => {
    const importer = new RbsImporter();
    const raw = new RbsParser().generateMockData('x.rbs');
    const result = importer.convertToHyphonSong(raw);

    for (const m of result.report.mappings) {
      if (m.target.startsWith('SynthParams.')) {
        const key = m.target.replace('SynthParams.', '');
        expect(SYNTH_PARAM_KEYS.has(key)).toBe(true);
      }
      if (m.target.startsWith('Bass2Params.')) {
        const key = m.target.replace('Bass2Params.', '');
        expect(BASS2_PARAM_KEYS.has(key)).toBe(true);
      }
    }
  });

  it('imported Note objects match Note interface shape', () => {
    const importer = new RbsImporter();
    const raw = new RbsParser().generateMockData('x.rbs');
    const result = importer.convertToHyphonSong(raw);

    for (const note of collectAllNotes(result.song)) {
      expect(typeof note.note).toBe('string');
      expect(note.note.length).toBeGreaterThan(0);
      expect(typeof note.velocity).toBe('number');
      if (note.length !== undefined) expect(note.length).toBeGreaterThan(0);
    }
  });

  it('drum tuning/decay values stay within DrumKitEngine-acceptable ranges', () => {
    const importer = new RbsImporter({ drumKitMapping: 'auto' });
    const parser = new RbsParser();

    for (const kit of ['808', '909'] as const) {
      const raw = parser.generateMockData('drums.rbs');
      raw.drums.kitType = kit;
      raw.drums.tuning = { kick: -50, snare: 50, closedHat: -50, openHat: 50 };
      raw.drums.decay = { kick: 0, snare: 127, closedHat: 127, openHat: 0 };

      const { kick, snare, closedHat, openHat } = importer.convertToHyphonSong(raw).song.params;

      inRange(kick.pitch, KICK_BOUNDS.pitch);
      inRange(kick.decay, KICK_BOUNDS.decay);
      inRange(kick.tone, KICK_BOUNDS.tone);

      inRange(snare.tone, SNARE_BOUNDS.tone);
      inRange(snare.noise, SNARE_BOUNDS.noise);
      inRange(snare.decay, SNARE_BOUNDS.decay);

      inRange(closedHat.pitch, HAT_BOUNDS.pitch);
      inRange(closedHat.decay, HAT_BOUNDS.decay);
      inRange(openHat.pitch, HAT_BOUNDS.pitch);
      inRange(openHat.decay, HAT_BOUNDS.decay);
    }
  });
});

/**
 * Importer mapping fidelity: slides, ties, accents, PCF, drums, empty patterns.
 */
import { describe, expect, it } from 'vitest';
import type { Note } from '../types';
import { RbsImporter } from '../importers/rbs/RbsImporter';
import type { RawRbsData, Tb303Step } from '../importers/rbs/types';
import { buildLegacyRbsFile } from './rbs/fixtures';
import { RbsParser } from '../importers/rbs/RbsParser';

function makeRaw(overrides: Partial<RawRbsData> = {}): RawRbsData {
  const parser = new RbsParser();
  const base = parser.generateMockData('fixture.rbs');
  return { ...base, ...overrides };
}

function tb303Step(overrides: Partial<Tb303Step> & { index: number }): Tb303Step {
  return {
    note: 0,
    octave: 3,
    accent: false,
    slide: false,
    tie: false,
    gate: 100,
    ...overrides,
  };
}

/** Count distinct note triggers (non-null steps that start a new envelope). */
function countTriggers(steps: (Note | null)[]): number {
  return steps.filter((s) => s !== null).length;
}

/** Valid Note shape per src/types.ts */
function assertValidNote(note: Note) {
  expect(typeof note.note).toBe('string');
  expect(typeof note.velocity).toBe('number');
  expect(note.velocity).toBeGreaterThanOrEqual(0);
  expect(note.velocity).toBeLessThanOrEqual(1);
  if (note.length !== undefined) expect(note.length).toBeGreaterThan(0);
  if (note.slide !== undefined) expect(typeof note.slide).toBe('boolean');
}

describe('RbsImporter TB-303 fidelity', () => {
  it('sets stock model303 voice fields on imported 303 synth params', () => {
    const importer = new RbsImporter({ expandTo32Steps: false });
    const result = importer.convertToHyphonSong(makeRaw());
    expect(result.song.params.synthA.model303).toBe('stock-open303');
    expect(result.song.params.synthA.engine303).toBe('open303');
    expect(result.song.params.synthB.model303).toBe('stock-open303');
    expect(result.song.params.synthB.engine303).toBe('open303');
  });

  it('16→32 tied note sustains without re-triggering envelope', () => {
    const steps: Tb303Step[] = Array.from({ length: 16 }, (_, i) => {
      if (i === 0) return tb303Step({ index: 0, note: 0, accent: true });
      if (i === 1) return tb303Step({ index: 1, note: -1, tie: true });
      return tb303Step({ index: i, note: -1 });
    });

    const importer = new RbsImporter({ expandTo32Steps: true });
    const result = importer.convertToHyphonSong(
      makeRaw({
        tb303PatternA: { ...makeRaw().tb303PatternA, steps },
        project: { ...makeRaw().project, patternLength: 16 },
      })
    );

    const partA = result.song.pattern.partA.steps;
    expect(partA).toHaveLength(32);

    // Single trigger at sub-step 0; tie sub-steps 2–3 are null (sustain via length)
    expect(countTriggers(partA)).toBe(1);
    expect(partA[0]).not.toBeNull();
    expect(partA[1]).toBeNull();
    expect(partA[2]).toBeNull();
    expect(partA[3]).toBeNull();
    expect(partA[0]!.length).toBe(4);
    assertValidNote(partA[0]!);
  });

  it('preserves accent on first sub-step after 16→32 expansion', () => {
    const steps: Tb303Step[] = [
      tb303Step({ index: 0, note: 5, accent: true }),
      ...Array.from({ length: 15 }, (_, i) => tb303Step({ index: i + 1, note: -1 })),
    ];

    const importer = new RbsImporter({ expandTo32Steps: true });
    const result = importer.convertToHyphonSong(
      makeRaw({
        tb303PatternA: { ...makeRaw().tb303PatternA, steps },
        project: { ...makeRaw().project, patternLength: 16 },
      })
    );

    const note0 = result.song.pattern.partA.steps[0];
    expect(note0).not.toBeNull();
    expect(note0!.velocity).toBeGreaterThan(0.8);
    expect(result.song.pattern.partA.steps[1]).toBeNull();
  });

  it('maps slide to length 2 spanning both 32nd sub-steps', () => {
    const steps: Tb303Step[] = [
      tb303Step({ index: 0, note: 7, slide: true }),
      ...Array.from({ length: 15 }, (_, i) => tb303Step({ index: i + 1, note: -1 })),
    ];

    const importer = new RbsImporter({ expandTo32Steps: true });
    const result = importer.convertToHyphonSong(
      makeRaw({
        tb303PatternA: { ...makeRaw().tb303PatternA, steps },
        project: { ...makeRaw().project, patternLength: 16 },
      })
    );

    const s0 = result.song.pattern.partA.steps[0];
    expect(s0?.slide).toBe(true);
    expect(s0?.length).toBe(2);
    expect(result.song.pattern.partA.steps[1]).toBeNull();
    expect(countTriggers(result.song.pattern.partA.steps)).toBe(1);
  });

  it('PCF sweep 0–127 produces monotonic filter-cutoff automation curve', () => {
    const pcfPattern = Array.from({ length: 16 }, (_, i) => i * 8);
    const importer = new RbsImporter({ convertPcfToAutomation: true, expandTo32Steps: false });
    const result = importer.convertToHyphonSong(
      makeRaw({
        pcf: {
          enabled: true,
          filterType: 'lp',
          cutoff: 80,
          resonance: 40,
          envAmount: 60,
          decay: 40,
          pattern: pcfPattern,
          target: { tb303A: true, tb303B: false, drums: false },
        },
      })
    );

    const lane = result.song.automation?.find((l) => l.name === 'PCF → TB-303 A Filter');
    expect(lane).toBeDefined();
    expect(lane!.parameter).toBe('filterCutoff');
    const values = lane!.points.map((p) => p[1]);
    for (let i = 1; i < values.length; i++) {
      expect(values[i]).toBeGreaterThanOrEqual(values[i - 1]);
    }
  });

  it('808 vs 909 kit selection maps distinct drum params', () => {
    const importer808 = new RbsImporter({ drumKitMapping: '808' });
    const importer909 = new RbsImporter({ drumKitMapping: '909' });

    const raw808 = makeRaw({ drums: { ...makeRaw().drums, kitType: '808' } });
    const raw909 = makeRaw({ drums: { ...makeRaw().drums, kitType: '909' } });

    const song808 = importer808.convertToHyphonSong(raw808).song;
    const song909 = importer909.convertToHyphonSong(raw909).song;

    expect(song808.params.drumKit).toBe('808');
    expect(song909.params.drumKit).toBe('909');
    expect(song808.params.kick.tone).toBe(0.6);
    expect(song909.params.kick.tone).toBe(0.8);
    expect(song808.params.snare.tone).toBe(200);
    expect(song909.params.snare.tone).toBe(300);
  });

  it('empty patterns and blank automation produce valid empty structures', () => {
    const emptySteps: Tb303Step[] = Array.from({ length: 16 }, (_, i) =>
      tb303Step({ index: i, note: -1 })
    );
    const importer = new RbsImporter({
      convertPcfToAutomation: false,
      expandTo32Steps: false,
    });
    const result = importer.convertToHyphonSong(
      makeRaw({
        automation: [],
        pcf: {
          enabled: false,
          filterType: 'lp',
          cutoff: 0,
          resonance: 0,
          envAmount: 0,
          decay: 0,
          pattern: Array(16).fill(0),
          target: { tb303A: false, tb303B: false, drums: false },
        },
        tb303PatternA: { ...makeRaw().tb303PatternA, steps: emptySteps },
        tb303PatternB: { ...makeRaw().tb303PatternB, steps: emptySteps },
        drums: {
          kick: Array(16).fill(false),
          snare: Array(16).fill(false),
          closedHat: Array(16).fill(false),
          openHat: Array(16).fill(false),
          accent: Array(16).fill(0),
          kitType: '808',
          tuning: { kick: 0, snare: 0, closedHat: 0, openHat: 0 },
          decay: { kick: 64, snare: 64, closedHat: 64, openHat: 64 },
        },
      })
    );

    expect(result.success).toBe(true);
    expect(result.song.pattern.partA.steps.every((s) => s === null)).toBe(true);
    expect(result.song.automation).toBeUndefined();
    expect(result.report.automationLanesConverted).toBe(0);
  });

  it('round-trips legacy synthesized file through parser → importer', async () => {
    const bytes = buildLegacyRbsFile({ tempo: 140, kitType: '909' });
    const parsed = await new RbsParser().parseBytes(bytes, { filename: 't.rbs', requireExtension: false });
    expect(parsed.success).toBe(true);
    if (!parsed.success) return;

    const imported = new RbsImporter().convertToHyphonSong(parsed.data);
    expect(imported.song.tempo).toBe(140);
    expect(imported.song.params.drumKit).toBe('909');
    expect(imported.song.pattern.partA.steps).toHaveLength(32);
  });
});

import { describe, expect, it } from 'vitest';
