    expect(accentB?.name).toContain('TB-303 B');
  });
});

// ---------------------------------------------------------------------------
// Acceptance: notes and knob automation for TB-303 #2 land on the same track
// ---------------------------------------------------------------------------

/** Pattern key that receives notes for a given automation lane target. */
const PATTERN_KEY_FOR_TARGET = {
  synthA: 'partA',
  synthB: 'partB',
  bass2: 'bass2',
} as const;

describe('RbsImporter TB-303 #2 routing', () => {
  const rawWithBAutomation = () =>
    makeRawData({
      automation: [
        {
          parameter: 'tb303Bcutoff',
          name: 'Cutoff B',
          points: [
            [0, 0],
            [8, 127],
          ],
          interpolation: 'linear',
          range: [0, 127],
        },
      ],
    });

  it('routes tb303B notes and tb303B automation to the same track under default options', () => {
    const result = new RbsImporter().convertToHyphonSong(rawWithBAutomation());
    expect(result.success).toBe(true);

    const laneB = result.song.automation?.find(
      (lane: HyphonAutomationLane) => lane.name === 'Cutoff B',
    );
    expect(laneB).toBeDefined();

    // The lane target must be the track the option routes TB-303 #2 notes to.
    const expectedTarget = DEFAULT_RBS_IMPORT_OPTIONS.tb303BTarget === 'bass2'
      ? 'bass2'
      : DEFAULT_RBS_IMPORT_OPTIONS.tb303BTarget === 'partB' ? 'synthB' : 'synthA';
    expect(laneB?.target).toBe(expectedTarget);

    // …and that track must actually carry the TB-303 #2 notes.
    const patternKey = PATTERN_KEY_FOR_TARGET[expectedTarget];
    const notes = result.song.pattern[patternKey].steps.filter((s) => s !== null);
    expect(notes.length).toBeGreaterThan(0);
  });

  it('follows tb303BTarget when it is overridden to partB', () => {
    const result = new RbsImporter({ tb303BTarget: 'partB' })
      .convertToHyphonSong(rawWithBAutomation());

    const laneB = result.song.automation?.find(
      (lane: HyphonAutomationLane) => lane.name === 'Cutoff B',
    );
    expect(laneB?.target).toBe('synthB');
    expect(result.song.pattern.partB.steps.filter((s) => s !== null).length).toBeGreaterThan(0);
  });
});

/**
 * Per-track TRAK controller resolution + param automation split (#777).
 */
import { describe, expect, it, vi, beforeEach, afterEach } from 'vitest';
import { RbsParser } from '../importers/rbs/RbsParser';
import { RbsImporter } from '../importers/rbs/RbsImporter';
import { AutomationScheduler } from '../audio/automation/AutomationScheduler';
import {
  TB303_TRAK_CONTROLLER,
  resolveTrakEventKind,
  isTrakPatternSelectEvent,
  isTrakParamAutomationEvent,
} from '../importers/rbs/trakControllers';
import { TRAK_TRACK_INDEX } from '../importers/rbs/types';
import { buildSyntheticIffFile } from './rbs/fixtures';

function makeOpen303Manager() {
  return {
    isLead303Ready: () => true,
    isBass1Ready: () => true,
    isBass2Ready: () => true,
    scheduleParamAtTime: vi.fn(),
  };
}

describe('trakControllers', () => {
  it('classifies TB-303 #1 pattern select vs cutoff', () => {
    expect(resolveTrakEventKind(1, 0x01)).toBe('patternSelect');
    expect(resolveTrakEventKind(1, 0x03)).toBe('paramChange');
    expect(isTrakPatternSelectEvent(1, 0x01)).toBe(true);
    expect(isTrakParamAutomationEvent(1, 0x03)).toBe(true);
    expect(isTrakParamAutomationEvent(1, 0x01)).toBe(false);
  });

  it('does not treat mixer compressor ID as pattern select', () => {
    expect(resolveTrakEventKind(0, 0x01)).toBe('routing');
    expect(isTrakPatternSelectEvent(0, 0x01)).toBe(false);
  });
});

describe('IFF TRAK parse + importer split', () => {
  const mixedTb303Events = [
    { delta: 0, ctrl: TB303_TRAK_CONTROLLER.PATTERN_SELECT, value: 0 },
    { delta: 48, ctrl: TB303_TRAK_CONTROLLER.CUTOFF, value: 40 },
    { delta: 48, ctrl: TB303_TRAK_CONTROLLER.CUTOFF, value: 100 },
    { delta: 672, ctrl: TB303_TRAK_CONTROLLER.PATTERN_SELECT, value: 1 },
  ];

  it('tags events with trackIndex and eventKind', async () => {
    const bytes = buildSyntheticIffFile({
      trakTracks: [
        { events: [] },
        { events: mixedTb303Events },
        { events: [] },
        { events: [] },
        { events: [] },
        { events: [] },
      ],
    });
    const parser = new RbsParser();
    const result = await parser.parseBytes(bytes, { filename: 'trak_mixed.rbs' });
    expect(result.success).toBe(true);
    if (!result.success || !result.data.songData) return;

    const track = result.data.songData.tracks.find((t) => t.trackIndex === TRAK_TRACK_INDEX.TB303_1)!;
    expect(track.events[0].eventKind).toBe('patternSelect');
    expect(track.events[1].eventKind).toBe('paramChange');
    expect(track.events[1].trackIndex).toBe(TRAK_TRACK_INDEX.TB303_1);
  });

  it('splits trakParamEvents from arrangement events', async () => {
    const bytes = buildSyntheticIffFile({
      trakTracks: [
        { events: [] },
        { events: mixedTb303Events },
        { events: [] },
        { events: [] },
        { events: [] },
        { events: [] },
      ],
    });
    const parser = new RbsParser();
    const parseResult = await parser.parseBytes(bytes, { filename: 'trak_split.rbs' });
    expect(parseResult.success).toBe(true);
    if (!parseResult.success) return;

    const importer = new RbsImporter();
    const { song } = importer.convertToHyphonSong(parseResult.data);

    expect(song.songArrangement!.trakEvents!.length).toBe(4);
    expect(song.songArrangement!.trakParamEvents!.length).toBe(2);
    expect(song.songArrangement!.trakParamEvents!.every((e) => e.eventKind === 'paramChange')).toBe(true);
  });
});

describe('AutomationScheduler mixed TRAK stream', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });
  afterEach(() => {
    vi.useRealTimers();
  });

  it('schedules only cutoff param events at sub-step ticks', () => {
    const ctx = { currentTime: 0 } as AudioContext;
    const mgr = makeOpen303Manager();
    const scheduler = new AutomationScheduler(ctx, mgr as any, { ppq: 24 });

    const events = [
      { tick: 0, trackIndex: 1, ctrlId: 0x01, value: 2, eventKind: 'patternSelect' as const },
      { tick: 48, trackIndex: 1, ctrlId: 0x03, value: 40, eventKind: 'paramChange' as const },
      { tick: 96, trackIndex: 1, ctrlId: 0x03, value: 100, eventKind: 'paramChange' as const },
    ];

    scheduler.scheduleFromTrakEvents(events, 120, 0, 0, 768);
    vi.runAllTimers();

    expect(mgr.scheduleParamAtTime).toHaveBeenCalledTimes(2);
    expect(mgr.scheduleParamAtTime).not.toHaveBeenCalledWith(
      'lead303',
      'setCutoff',
      expect.closeTo(2 / 127, 3),
      expect.any(Number),
    );
    expect(mgr.scheduleParamAtTime).toHaveBeenCalledWith(
      'lead303',
      'setCutoff',
      expect.closeTo(40 / 127, 3),
      expect.any(Number),
    );
  });
});

import '@testing-library/jest-dom';
import { render } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { SamplerPanel } from '../components/SamplerPanel';
import type { SamplerParams } from '../types';
import { Knob } from '../components/Knob';

// Mock Knob to track renders
vi.mock('../components/Knob', () => ({
    Knob: vi.fn(() => <div data-testid="knob">Knob</div>)
}));

// Mock AudioContext
const mockAudioContext = {
    createBuffer: vi.fn((_channels: number, length: number) => ({
        getChannelData: () => new Float32Array(length)
    }))
} as any;

describe('SamplerPanel Memoization', () => {
    // Helper to create valid params
    const createParams = (): SamplerParams => Array(8).fill(null).map((_, i) => ({
        sampleName: `bank_${i}`,
        playbackSpeed: 1.0,
        volume: 1.0,
        filterCutoff: 20000,
        filterResonance: 0,
        drive: 0,
        delaySend: 0,
        mode: 'loop',
        grainSize: 4410
    }));

    const defaultProps = {
        params: createParams(),
        onChange: vi.fn(),
        onLoadSample: vi.fn(),
        audioContext: mockAudioContext,
        activeBankIdx: 0,
        onBankChange: vi.fn(),
        isVoiceEditorOpen: false,
        ttsPhrases: Array(8).fill("Hello World"),
        onTtsPhraseChange: vi.fn()
    };

    beforeEach(() => {
        vi.clearAllMocks();
    });

    /**
     * Renders SamplerPanel and captures how many knobs the initial render
     * produced. Asserting against this baseline (rather than a hard-coded
     * literal) keeps the test asserting the *relationship* the test name
     * promises — full re-render vs. no re-render — so it doesn't need
     * updating every time a knob is added to or removed from a bank.
     */
    function renderSampler() {
        const { rerender } = render(<SamplerPanel {...defaultProps} />);
        const initialKnobCount = (Knob as unknown as ReturnType<typeof vi.fn>).mock.calls.length;
        expect(initialKnobCount).toBeGreaterThan(0);
        vi.clearAllMocks();
        return { rerender, initialKnobCount };
    }

    it('re-renders children when active bank params change', () => {
        const { rerender, initialKnobCount } = renderSampler();

        // Update params for ACTIVE bank (0)
        // Maintain referential equality for other banks
        const newParams = [...defaultProps.params];
        newParams[0] = { ...newParams[0], volume: 0.5 };

        rerender(<SamplerPanel {...defaultProps} params={newParams} />);

        // Active bank changed: every knob for that bank re-renders.
        expect(Knob).toHaveBeenCalledTimes(initialKnobCount);
    });

    it('does NOT re-render children when inactive bank params change', () => {
        const { rerender } = renderSampler();

        // Update params for INACTIVE bank (1)
        // Maintain referential equality for active bank (0)
        const newParams = [...defaultProps.params];
        newParams[1] = { ...newParams[1], volume: 0.5 };

        rerender(<SamplerPanel {...defaultProps} params={newParams} />);

        // Optimization Verified: Should NOT have called Knob again
        expect(Knob).toHaveBeenCalledTimes(0);
    });

    it('re-renders children when activeBankIdx changes', () => {
        const { rerender, initialKnobCount } = renderSampler();

        rerender(<SamplerPanel {...defaultProps} activeBankIdx={1} />);

        // Switching banks re-renders the same number of knobs as the initial render.
        expect(Knob).toHaveBeenCalledTimes(initialKnobCount);
    });
});

