import { describe, it, expect } from 'vitest';
import { audioBufferToWav } from '../utils/audioExport';

// Mock AudioBuffer
class MockAudioBuffer {
    numberOfChannels: number;
    length: number;
    sampleRate: number;
    _data: Float32Array[];

    constructor(options: { numberOfChannels: number, length: number, sampleRate: number }) {
        this.numberOfChannels = options.numberOfChannels;
        this.length = options.length;
        this.sampleRate = options.sampleRate;
        this._data = Array.from({ length: this.numberOfChannels }, () => new Float32Array(this.length));
    }

    getChannelData(channel: number) {
        return this._data[channel];
    }
}

// Polyfill AudioBuffer for Node environment if needed
if (typeof AudioBuffer === 'undefined') {
    global.AudioBuffer = MockAudioBuffer as any;
}

describe('audioBufferToWav Performance', () => {
    it('benchmarks execution time', async () => {
        const length = 44100 * 5; // 5 seconds
        const buffer = new MockAudioBuffer({
            numberOfChannels: 2,
            length: length,
            sampleRate: 44100
        }) as unknown as AudioBuffer;

        // Fill with random data
        for (let ch = 0; ch < 2; ch++) {
            const data = buffer.getChannelData(ch);
            for (let i = 0; i < length; i++) {
                data[i] = Math.random() * 2 - 1;
            }
        }

        const start = performance.now();
        const iterations = 100;

        for (let i = 0; i < iterations; i++) {
            await audioBufferToWav(buffer);
        }

        const end = performance.now();
        const avgTime = (end - start) / iterations;

        console.log(`audioBufferToWav average time (${iterations} runs): ${avgTime.toFixed(3)}ms`);

        // Ensure it runs without error and returns reasonable metric
        expect(avgTime).toBeGreaterThan(0);
    });
});

import { describe, it, expect } from 'vitest';
import { copySteps, pasteSteps } from '../utils/clipboardUtils';
import type { Pattern } from '../types';

const emptySteps = Array(32).fill(null);
// Helper to create a fresh pattern
// @ts-expect-error - Auto-generated to fix CI build
const createEmptyPattern = (): Pattern => ({
    partA: { steps: [...emptySteps] },
    partB: { steps: [...emptySteps] },
    kick: { steps: [...emptySteps] },
    snare: { steps: [...emptySteps] },
    closedHat: { steps: [...emptySteps] },
    openHat: { steps: [...emptySteps] },
    sampler: Array.from({ length: 8 }, () => ({ steps: [...emptySteps] }))
});

describe('clipboardUtils', () => {
    it('copies steps from partA', () => {
        const pattern = createEmptyPattern();
        pattern.partA.steps[0] = { note: 'C4', velocity: 1, length: 1 };
        pattern.partA.steps[2] = { note: 'D4', velocity: 0.5, length: 2 };

        const selection = { trackKey: 'partA' as const, startStep: 0, endStep: 2 };
        const copied = copySteps(pattern, selection, 0);

        expect(copied).toHaveLength(3);
        expect(copied![0]).toEqual({ note: 'C4', velocity: 1, length: 1 });
        expect(copied![1]).toBeNull();
        expect(copied![2]).toEqual({ note: 'D4', velocity: 0.5, length: 2 });
    });

    it('pastes steps into partB', () => {
        const pattern = createEmptyPattern();
        const clipboard = [
             { note: 'C4', velocity: 1, length: 1 },
             null,
             { note: 'D4', velocity: 0.5, length: 2 }
        ];

        const newPattern = pasteSteps(pattern, clipboard, 'partB' as const, 0, 0);

        expect(newPattern.partB.steps[0]).toEqual(clipboard[0]);
        expect(newPattern.partB.steps[1]).toBeNull();
        expect(newPattern.partB.steps[2]).toEqual(clipboard[2]);
        expect(newPattern.partB.steps[3]).toBeNull();
    });

    it('handles sampler copy/paste correctly', () => {
        const pattern = createEmptyPattern();
        pattern.sampler[0].steps[0] = { note: 'C3', velocity: 1, length: 1 };

        const selection = { trackKey: 'sampler' as const, startStep: 0, endStep: 0 };
        const copied = copySteps(pattern, selection, 0);

        expect(copied).toHaveLength(1);
        expect(copied![0]).toEqual({ note: 'C3', velocity: 1, length: 1 });

        const newPattern = pasteSteps(pattern, copied!, 'sampler' as const, 1, 0);
        expect(newPattern.sampler[0].steps[1]).toEqual(copied![0]);
    });

    it('handles overflow', () => {
        const pattern = createEmptyPattern();
        const clipboard = [ { note: 'C4', velocity: 1, length: 1 }, { note: 'D4', velocity: 1, length: 1 } ];

        const newPattern = pasteSteps(pattern, clipboard, 'partA' as const, 31, 0);

        expect(newPattern.partA.steps[31]).toEqual(clipboard[0]);
        // Step 32 is out of bounds
    });

    it('deep clones on copy and paste', () => {
        const pattern = createEmptyPattern();
        const originalNote = { note: 'C4', velocity: 1, length: 1 };
        pattern.partA.steps[0] = originalNote;

        const selection = { trackKey: 'partA' as const, startStep: 0, endStep: 0 };
        const copied = copySteps(pattern, selection, 0);

        // Modify original
        originalNote.velocity = 0.5;

        // Copied should remain 1
        expect(copied![0]?.velocity).toBe(1);

        // Paste
        const newPattern = pasteSteps(pattern, copied!, 'partB' as const, 0, 0);

        // Modify clipboard note
        copied![0]!.velocity = 0.8;

        // Pasted should remain 1
        expect(newPattern.partB.steps[0]?.velocity).toBe(1);
    });
});

// Unit tests for the clock-processor step-timing arithmetic.
//
// The processor itself runs in an AudioWorkletGlobalScope (no DOM), so we test
// the step-duration math by extracting it as pure functions — same logic the
// class uses internally.

import { describe, it, expect } from 'vitest';

// ── Extracted pure helpers (mirrors clock-processor.ts internals) ─────────────

const SAMPLE_RATE = 44100;

function baseSamplesPerStep(tempo: number): number {
    return (SAMPLE_RATE * 60) / (tempo * 4);
}

// swing 0 = straight, 1 = max shuffle
function stepDuration(tempo: number, swing: number, parity: 0 | 1): number {
    const base = baseSamplesPerStep(tempo);
    const shift = swing * base * 0.5;
    return parity === 0 ? base + shift : base - shift;
}

// Build the sample indices at which each of `numSteps` steps fires, given tempo+swing.
function stepFireTimes(tempo: number, swing: number, numSteps: number): number[] {
    const times: number[] = [];
    let cursor = 0;
    for (let s = 0; s < numSteps; s++) {
        times.push(cursor);
        const parity = (s % 2) as 0 | 1;
        cursor += stepDuration(tempo, swing, parity);
    }
    return times;
}

// ── Tests ─────────────────────────────────────────────────────────────────────

describe('clock-processor step timing', () => {
    it('step duration is exactly 60/tempo/4 seconds at swing=0', () => {
        const tempo = 120;
        const expectedSec = 60 / (tempo * 4);
        const durSamples = stepDuration(tempo, 0, 0);
        expect(durSamples / SAMPLE_RATE).toBeCloseTo(expectedSec, 6);
        // Same for odd steps
        expect(stepDuration(tempo, 0, 1) / SAMPLE_RATE).toBeCloseTo(expectedSec, 6);
    });

    it('even and odd durations sum to 2× base step regardless of swing', () => {
        const tempo = 130;
        const base = baseSamplesPerStep(tempo);
        for (const swing of [0, 0.25, 0.5, 0.75, 1.0]) {
            const even = stepDuration(tempo, swing, 0);
            const odd = stepDuration(tempo, swing, 1);
            expect(even + odd).toBeCloseTo(base * 2, 3);
        }
    });

    it('swing=0 produces evenly-spaced steps', () => {
        const tempo = 120;
        const base = baseSamplesPerStep(tempo);
        const times = stepFireTimes(tempo, 0, 8);
        for (let i = 1; i < times.length; i++) {
            expect(times[i] - times[i - 1]).toBeCloseTo(base, 3);
        }
    });

    it('swing=1 delays every odd step by half a base step', () => {
        const tempo = 120;
        const base = baseSamplesPerStep(tempo);
        const times = stepFireTimes(tempo, 1, 4);
        // step 0 fires at 0
        expect(times[0]).toBe(0);
        // step 1 fires at base + 0.5*base = 1.5*base
        expect(times[1]).toBeCloseTo(base + base * 0.5, 3);
        // step 2 fires at step1 + (base - 0.5*base) = step1 + 0.5*base = 2*base
        expect(times[2]).toBeCloseTo(times[1] + base * 0.5, 3);
        // step 3 fires at step2 + 1.5*base = 3.5*base
        expect(times[3]).toBeCloseTo(times[2] + base * 1.5, 3);
    });

    it('32-step bar duration equals 2 seconds at 120 BPM regardless of swing', () => {
        const tempo = 120;
        const times = stepFireTimes(tempo, 0, 32);
        const base = baseSamplesPerStep(tempo);
        const barDuration = times[times.length - 1] + stepDuration(tempo, 0, (31 % 2) as 0 | 1);
        // 32 steps × (60/120/4 s) = 32 × 0.125 = 4 s  (one 4-bar phrase at 16ths)
        // but our bar above is just the 32 steps, = 4 seconds
        expect(barDuration / SAMPLE_RATE).toBeCloseTo(4.0, 4);
        // With full swing the total duration is the same (pairs cancel out)
        const timesSwing = stepFireTimes(tempo, 1, 32);
        const barSwing = timesSwing[timesSwing.length - 1] + stepDuration(tempo, 1, (31 % 2) as 0 | 1);
        expect(barSwing / SAMPLE_RATE).toBeCloseTo(4.0, 4);
    });

    it('step fire times are strictly monotonically increasing for any swing', () => {
        const times = stepFireTimes(140, 0.6, 16);
        for (let i = 1; i < times.length; i++) {
            expect(times[i]).toBeGreaterThan(times[i - 1]);
        }
    });

    it('step period scales inversely with tempo', () => {
        const t1 = baseSamplesPerStep(60);
        const t2 = baseSamplesPerStep(120);
        expect(t1 / t2).toBeCloseTo(2, 6); // 120 BPM is twice as fast as 60 BPM
    });
});

/**
 * engine303-roundtrip.test.ts
 *
 * Verifies that the engine303 and model303 fields are correctly preserved when
 * a song is serialised to and deserialised from the SavedSongData JSON format.
 *
 * This exercises the data-layer round-trip (JSON.stringify → JSON.parse)
 * that all storage paths (localStorage, cloud, AI importer) share.
 */

import { describe, it, expect } from 'vitest';
import type { SavedSongData, SynthParams, Bass2Params } from '../types';
import { DEFAULT_SYNTH_PARAMS_A, DEFAULT_SYNTH_PARAMS_B, DEFAULT_BASS2_PARAMS } from '../constants';
import { getAvailableTB303Models, normalizeTB303Model } from '../engines/TB303Models';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function makeSongData(overrides: {
    synthAEngine?: SynthParams['engine303'];
    synthBEngine?: SynthParams['engine303'];
    bass2Engine?: Bass2Params['engine303'];
    synthAModel?: SynthParams['model303'];
    synthBModel?: SynthParams['model303'];
    bass2Model?: Bass2Params['model303'];
}): SavedSongData {
    return {
        version: 1,
        pattern: {
            partA: { steps: Array(32).fill(null) },
            partB: { steps: Array(32).fill(null) },
            bass2: { steps: Array(32).fill(null) },
            kick: Array(32).fill(0),
            snare: Array(32).fill(0),
            closedHat: Array(32).fill(0),
            openHat: Array(32).fill(0),
            sampler: Array(32).fill(0),
        } as any,
        params: {
            synthA: {
                ...DEFAULT_SYNTH_PARAMS_A,
                engine303: overrides.synthAEngine,
                ...(overrides.synthAModel !== undefined && { model303: overrides.synthAModel }),
            },
            synthB: {
                ...DEFAULT_SYNTH_PARAMS_B,
                engine303: overrides.synthBEngine,
                ...(overrides.synthBModel !== undefined && { model303: overrides.synthBModel }),
            },
            // bass2 is not in the official SavedSongData params type, but is stored by useSongStorage
            ...(overrides.bass2Engine !== undefined || overrides.bass2Model !== undefined
                ? {
                    bass2: {
                        ...DEFAULT_BASS2_PARAMS,
                        ...(overrides.bass2Engine !== undefined && { engine303: overrides.bass2Engine }),
                        ...(overrides.bass2Model !== undefined && { model303: overrides.bass2Model }),
                    } as any,
                }
                : {}),
            kick: { pitch: 60, decay: 0.4, tone: 0.9, volume: 1 },
            snare: { decay: 0.2, tone: 150, noise: 5000, volume: 0.8 },
            closedHat: { pitch: 9000, decay: 0.05, volume: 0.4 },
            openHat: { pitch: 7000, decay: 0.4, volume: 0.4 },
            sampler: [] as any,
        },
        trackStorage: {},
        activeTrackSlots: {},
        songStructure: [],
        tempo: 120,
    };
}

function roundTrip<T>(data: T): T {
    return JSON.parse(JSON.stringify(data));
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('engine303 JSON round-trip (SavedSongData)', () => {
    it('synthA.engine303="jc303" survives JSON serialisation', () => {
        const song = makeSongData({ synthAEngine: 'jc303' });
        const restored = roundTrip(song);
        expect(restored.params.synthA.engine303).toBe('jc303');
    });

    it('synthA.engine303="open303" survives JSON serialisation', () => {
        const song = makeSongData({ synthAEngine: 'open303' });
        const restored = roundTrip(song);
        expect(restored.params.synthA.engine303).toBe('open303');
    });

    it('synthB.engine303="jc303" survives JSON serialisation', () => {
        const song = makeSongData({ synthBEngine: 'jc303' });
        const restored = roundTrip(song);
        expect(restored.params.synthB.engine303).toBe('jc303');
    });

    it('synthA.engine303=undefined is preserved as undefined through round-trip', () => {
        const song = makeSongData({ synthAEngine: undefined });
        const restored = roundTrip(song);
        // JSON drops undefined fields; the restored value will be undefined
        expect(restored.params.synthA.engine303).toBeUndefined();
    });

    it('bass2.engine303="jc303" survives JSON serialisation', () => {
        const song = makeSongData({ bass2Engine: 'jc303' });
        const restored = roundTrip(song);
        expect((restored.params as any).bass2?.engine303).toBe('jc303');
    });

    it('bass2.engine303="open303" survives JSON serialisation', () => {
        const song = makeSongData({ bass2Engine: 'open303' });
        const restored = roundTrip(song);
        expect((restored.params as any).bass2?.engine303).toBe('open303');
    });

    it('all three voices with jc303 survive a round-trip', () => {
        const song = makeSongData({
            synthAEngine: 'jc303',
            synthBEngine: 'jc303',
            bass2Engine: 'jc303',
        });
        const restored = roundTrip(song);
        expect(restored.params.synthA.engine303).toBe('jc303');
        expect(restored.params.synthB.engine303).toBe('jc303');
        expect((restored.params as any).bass2?.engine303).toBe('jc303');
    });

    it('engine303 field does not bleed between voices during round-trip', () => {
        const song = makeSongData({
            synthAEngine: 'jc303',
            synthBEngine: 'open303',
            bass2Engine: 'jc303',
        });
        const restored = roundTrip(song);
        expect(restored.params.synthA.engine303).toBe('jc303');
        expect(restored.params.synthB.engine303).toBe('open303');
        expect((restored.params as any).bass2?.engine303).toBe('jc303');
    });
});

describe('engine303 in SavedSongData version field', () => {
    it('a song with engine303="jc303" and version=1 is deserialised correctly', () => {
        const song = makeSongData({ synthAEngine: 'jc303' });
        expect(song.version).toBe(1);
        const restored = roundTrip(song);
        expect(restored.version).toBe(1);
        expect(restored.params.synthA.engine303).toBe('jc303');
    });
});

// ---------------------------------------------------------------------------
// model303 JSON round-trip (SavedSongData)
// ---------------------------------------------------------------------------

describe('model303 JSON round-trip (SavedSongData)', () => {
    it('synthA.model303="experimental-01" survives JSON serialisation', () => {
        const song = makeSongData({ synthAModel: 'experimental-01', synthAEngine: 'open303' });
        const restored = roundTrip(song);
        expect(restored.params.synthA.model303).toBe('experimental-01');
    });

    it('synthB.model303="jc303" survives JSON serialisation', () => {
        const song = makeSongData({ synthBModel: 'jc303', synthBEngine: 'jc303' });
        const restored = roundTrip(song);
        expect(restored.params.synthB.model303).toBe('jc303');
    });

    it('bass2.model303="1ink303-v1" survives JSON serialisation', () => {
        const song = makeSongData({ bass2Model: '1ink303-v1', bass2Engine: 'open303' });
        const restored = roundTrip(song);
        expect((restored.params as any).bass2?.model303).toBe('1ink303-v1');
    });

    it('all three parts with distinct model303 ids survive a round-trip', () => {
        const song = makeSongData({
            synthAModel: 'jc303',
            synthBModel: 'stock-open303',
            bass2Model: 'experimental-01',
            synthAEngine: 'jc303',
            synthBEngine: 'open303',
            bass2Engine: 'open303',
        });
        const restored = roundTrip(song);
        expect(restored.params.synthA.model303).toBe('jc303');
        expect(restored.params.synthB.model303).toBe('stock-open303');
        expect((restored.params as any).bass2?.model303).toBe('experimental-01');
    });

    it('model303 does not bleed between voices during round-trip', () => {
        const song = makeSongData({
            synthAModel: 'rebirth-338-1.5',
            synthBModel: 'mb33-mkii',
            bass2Model: 'raveolution',
        });
        const restored = roundTrip(song);
        expect(restored.params.synthA.model303).toBe('rebirth-338-1.5');
        expect(restored.params.synthB.model303).toBe('mb33-mkii');
        expect((restored.params as any).bass2?.model303).toBe('raveolution');
    });

    it('every available model id round-trips and normalizes to itself on load', () => {
        for (const m of getAvailableTB303Models()) {
            const song = makeSongData({ synthAModel: m.id });
            const restored = roundTrip(song);
            expect(restored.params.synthA.model303).toBe(m.id);
            expect(normalizeTB303Model(restored.params.synthA.model303, restored.params.synthA.engine303))
                .toBe(m.id);
        }
    });

    it('legacy engine303="open303" without model303 normalizes to stock-open303 on load', () => {
        const song = makeSongData({ synthAEngine: 'open303' });
        const restored = roundTrip(song);
        expect(restored.params.synthA.model303).toBeUndefined();
        expect(normalizeTB303Model(restored.params.synthA.model303, restored.params.synthA.engine303))
            .toBe('stock-open303');
    });
});

