import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import {
  AutomationScheduler,
} from '../audio/automation/AutomationScheduler';
import { automationStore, generateLaneId, resetLaneIdCounter } from '../stores/automationStore';
import {
