// AudioWorklet-based sequencer clock.
//
// Runs entirely on the audio rendering thread — immune to main-thread GC pauses,
// `setTimeout` jitter, and background-tab throttling (which collapses rAF to 1 Hz).
//
// Step messages include the precise AudioContext `audioTime` at which the step falls,
// so the main thread can schedule notes into the future without re-checking currentTime.
//
// Swing model (16th-note shuffle):
//   Even steps (on-beat)  fire after  T * (1 + swing/2)  samples
//   Odd steps  (off-beat) fire after  T * (1 - swing/2)  samples
//   swing = 0 → straight, swing = 1 → maximum shuffle (~66/34 split, classic triplet feel)
//   The pair duration (even + odd) always equals 2T regardless of swing.

import { WorkletPerfReporter } from './workletPerfReporter';

declare class AudioWorkletProcessor {
    readonly port: MessagePort;
    process(
        inputs: Float32Array[][],
        outputs: Float32Array[][],
        parameters: Record<string, Float32Array>,
    ): boolean;
}
declare function registerProcessor(name: string, ctor: new (options?: unknown) => AudioWorkletProcessor): void;
declare const sampleRate: number;
declare const currentTime: number;   // AudioWorkletGlobalScope: time of current block

interface ClockMessage {
    type: 'start' | 'stop' | 'setTempo' | 'setSwing' | 'setSteps';
    tempo?: number;
    swing?: number;
    steps?: number;
}

class ClockProcessor extends AudioWorkletProcessor {
    private running = false;
    private tempo = 120;
    private swing = 0;           // 0–1
    private numSteps = 32;
    private readonly perf = new WorkletPerfReporter(this.port, 'clock');

    // Accumulated sample count since playback start
    private sampleCursor = 0;
    // Sample index at which the *next* step fires (relative to playback start)
    private nextStepAtSample = 0;
    // The step that will fire next (0-indexed)
    private nextStep = 0;

    private readonly stepMessage: { type: 'step'; step: number; audioTime: number } = { type: 'step', step: 0, audioTime: 0 };

    constructor() {
        super();
        this.port.onmessage = (e: MessageEvent<ClockMessage>) => {
            const { type, tempo, swing, steps } = e.data;
            switch (type) {
                case 'start':
                    this.sampleCursor = 0;
                    this.nextStepAtSample = 0;
                    this.nextStep = 0;
                    this.running = true;
                    break;
                case 'stop':
                    this.running = false;
                    break;
                case 'setTempo':
                    if (tempo != null && Number.isFinite(tempo) && tempo > 0) {
                        this.tempo = tempo;
                    }
                    break;
                case 'setSwing':
                    if (swing != null && Number.isFinite(swing)) {
                        this.swing = Math.max(0, Math.min(1, swing));
                    }
                    break;
                case 'setSteps':
                    if (steps != null && steps > 0) {
                        this.numSteps = steps;
                    }
                    break;
            }
        };
    }

    // Duration in samples for a single 16th-note step at the current tempo,
    // applying swing for even/odd parity.
    // parity: 0 = on-beat (even step index), 1 = off-beat (odd step index).
    private stepDurationSamples(parity: 0 | 1): number {
        const baseSamples = (sampleRate * 60) / (this.tempo * 4);
        // swing shifts time from odd steps to even steps.
        // parity 0 (even/on-beat): gets extra time
        // parity 1 (odd/off-beat): loses the same time
        const shift = this.swing * baseSamples * 0.5;
        return parity === 0 ? baseSamples + shift : baseSamples - shift;
    }

    process(_inputs: Float32Array[][], outputs: Float32Array[][], _params: Record<string, Float32Array>): boolean {
        const output = outputs[0]?.[0];
        const blockSize = output?.length ?? 128;
        this.perf.beginProcess(blockSize);
        try {
            if (output) {
                output.fill(0);
            }

            if (!this.running) return true;

            for (let i = 0; i < blockSize; i++) {
                if (this.sampleCursor >= this.nextStepAtSample) {
                    // Exact AudioContext time for this sample (currentTime is the time of
                    // the first sample in the current block).
                    const audioTime = currentTime + i / sampleRate;

                    this.stepMessage.step = this.nextStep;
                    this.stepMessage.audioTime = audioTime;
                    this.port.postMessage(this.stepMessage);

                    // Advance to the next step.
                    const parity = (this.nextStep % 2) as 0 | 1;
                    this.nextStepAtSample += this.stepDurationSamples(parity);
                    this.nextStep = (this.nextStep + 1) % this.numSteps;
                }
                this.sampleCursor++;
            }

            return true; // keep processor alive
        } finally {
            this.perf.endProcess();
        }
    }
}

registerProcessor('clock-processor', ClockProcessor);

// src/audio-worklets/drumkit-processor.ts
// AudioWorklet for analog 808/909 drums. One hyphon_native instantiate per
// kit (kick/snare/CH/OH share C handles on that instance).

import {
    DRUMKIT_REQUIRED_WASM_EXPORTS,
    HYPHON_NATIVE_MIN_MEMORY_PAGES,
    buildHyphonWasmImports,
    formatMissingWasmExports,
    hasDrumkitApi,
    normalizeWasmExports,
} from './hyphonNativeImports';
import { DrumTriggerQueue } from './drumkit/triggerQueue';

declare class AudioWorkletProcessor {
    readonly port: MessagePort;
    process(inputs: Float32Array[][], outputs: Float32Array[][], parameters: Record<string, Float32Array>): boolean;
}

declare const currentTime: number;

declare function registerProcessor(name: string, processorCtor: new () => AudioWorkletProcessor): void;

const DrumkitState = {
    UNINITIALIZED: 'uninitialized',
    INITIALIZING: 'initializing',
    READY: 'ready',
    FAILED: 'failed',
} as const;

type DrumkitStateType = (typeof DrumkitState)[keyof typeof DrumkitState];

class DrumkitProcessor extends AudioWorkletProcessor {
    private wasmInstance: WebAssembly.Instance | null = null;
    private normalizedExports: Record<string, unknown> | null = null;
    private importedMemory: WebAssembly.Memory | null = null;
    private heapFloat32: Float32Array | null = null;
    private synthState: DrumkitStateType = DrumkitState.UNINITIALIZED;
    private isThreaded = false;
    private instanceHandle = 0;
    private readonly bufFrames = 128;
    private processErrorCount = 0;
    private allocationErrorCount = 0;
    private readonly triggers = new DrumTriggerQueue();

    constructor() {
        super();
        this.port.onmessage = this.handleMessage.bind(this);
    }

    private async handleMessage(event: MessageEvent): Promise<void> {
        const { type, data } = event.data;

        if (type === 'init-wasm') {
            await this.initializeWasm(data);
            return;
        }

        if (this.synthState !== DrumkitState.READY || !this.wasmInstance) return;

        const exports = this.getExports();

        switch (type) {
            case 'set-kit':
                try {
                    exports.drumkit_set_kit(this.instanceHandle, data.kit);
                } catch (e) {
                    console.error('[Drumkit] set-kit error:', e);
                }
                break;
            case 'trigger': {
                const audioTime = typeof data.audioTime === 'number' ? data.audioTime : 0;
                const entry = {
                    audioTime,
                    voice: data.voice,
                    velocity: data.velocity ?? 1,
                    a: data.a ?? 0,
                    b: data.b ?? 0,
                    c: data.c ?? 0,
                    d: data.d ?? 0,
                };
                if (typeof currentTime !== 'undefined' && audioTime <= currentTime) {
                    this.applyTrigger(exports, entry);
                } else {
                    this.triggers.schedule(entry);
                }
                break;
            }
            case 'choke-open-hat':
                try {
                    exports.drumkit_choke_open_hat(this.instanceHandle);
                } catch (e) {
                    console.error('[Drumkit] choke error:', e);
                }
                break;
            default:
                break;
        }
    }

    private applyTrigger(
        exports: Record<string, any>,
        entry: { voice: number; velocity: number; a: number; b: number; c: number; d: number },
    ): void {
        exports.drumkit_trigger(
            this.instanceHandle,
            entry.voice,
            entry.velocity,
            entry.a,
            entry.b,
            entry.c,
            entry.d,
        );
    }

    private async initializeWasm(data: {
        wasmBytes: ArrayBuffer;
        sampleRate: number;
        isThreaded: boolean;
        variant?: string;
        memoryPages?: number;
        exportMap?: Record<string, string>;
    }): Promise<void> {
        if (this.synthState === DrumkitState.INITIALIZING) return;
        this.synthState = DrumkitState.INITIALIZING;

        try {
            const { wasmBytes, sampleRate, isThreaded, memoryPages, exportMap } = data;
            this.isThreaded = !!isThreaded;

            const module = await WebAssembly.compile(wasmBytes);
            const importCtx = {
                getWasmInstance: () => this.wasmInstance,
                getImportedMemory: () => this.importedMemory,
                setImportedMemory: (m: WebAssembly.Memory) => {
                    this.importedMemory = m;
                },
                onHeapUpdate: () => this.updateHeap(),
                logPrefix: '[Drumkit]',
            };

            const { imports, memory } = buildHyphonWasmImports(module, importCtx, {
                memoryPages: memoryPages ?? HYPHON_NATIVE_MIN_MEMORY_PAGES,
                isThreaded: this.isThreaded,
            });

            const instance = await WebAssembly.instantiate(module, imports);
            this.wasmInstance = instance;
            this.normalizedExports = normalizeWasmExports(instance.exports, exportMap ?? {});
            this.configureWasmStack();

            const exp = this.getExports();
            const instanceExp = instance.exports as Record<string, any>;
            const mem: WebAssembly.Memory =
                memory ??
                (instanceExp.memory as WebAssembly.Memory) ??
                this.importedMemory;
            if (!mem) throw new Error('[Drumkit] No memory export/import found');
            this.importedMemory = mem;
            this.heapFloat32 = new Float32Array(mem.buffer);

            if (!hasDrumkitApi(exp)) {
                throw new Error(
                    '[Drumkit] drumkit_* API not found in WASM exports. ' +
                    formatMissingWasmExports(instance.exports, [...DRUMKIT_REQUIRED_WASM_EXPORTS]),
                );
            }

            this.instanceHandle = exp.drumkit_create();
            if (!this.instanceHandle) throw new Error('[Drumkit] drumkit_create() returned null handle');

            const ok = exp.drumkit_init(this.instanceHandle, sampleRate, this.bufFrames);
            if (ok !== 1) throw new Error(`[Drumkit] drumkit_init() returned ${ok}`);

            this.synthState = DrumkitState.READY;
            this.port.postMessage({ type: 'ready', heapCount: 1 });
        } catch (e: unknown) {
            this.synthState = DrumkitState.FAILED;
            const message = e instanceof Error ? e.message : String(e);
            console.error('[Drumkit] WASM init failed:', e);
            this.port.postMessage({ type: 'error', error: message });
        }
    }

    private getExports(): Record<string, any> {
        return (this.normalizedExports ?? {}) as Record<string, any>;
    }

    private updateHeap(): void {
        const memory =
            (this.wasmInstance?.exports as { memory?: WebAssembly.Memory } | undefined)?.memory ??
            this.importedMemory;
        if (memory) {
            this.heapFloat32 = new Float32Array(memory.buffer);
        }
    }

    private configureWasmStack(): void {
        const exports = this.getExports() as Record<string, (...args: number[]) => number>;
        if (typeof exports.emscripten_stack_init === 'function') {
            exports.emscripten_stack_init();
        }
        if (typeof exports.__wasm_call_ctors === 'function') {
            exports.__wasm_call_ctors();
        }
        if (
            typeof exports.__set_stack_limits === 'function' &&
            typeof exports.emscripten_stack_get_base === 'function'
        ) {
            const stackBase = exports.emscripten_stack_get_base();
            if (stackBase > 0) {
                exports.__set_stack_limits(stackBase, 0);
            }
        }
    }

    process(_inputs: Float32Array[][], outputs: Float32Array[][]): boolean {
        const output = outputs[0];
        if (!output) return true;

        const channelL = output[0];
        const channelR = output[1] ?? null;

        if (this.synthState !== DrumkitState.READY || !this.wasmInstance || !this.heapFloat32) {
            channelL?.fill(0);
            channelR?.fill(0);
            return true;
        }

        try {
            const exports = this.getExports();
            if (typeof currentTime !== 'undefined' && this.triggers.length > 0) {
                this.triggers.drain(currentTime, (entry) => this.applyTrigger(exports, entry));
            }

            const numFrames = channelL?.length ?? this.bufFrames;

            if (this.importedMemory && this.heapFloat32.buffer !== this.importedMemory.buffer) {
                this.heapFloat32 = new Float32Array(this.importedMemory.buffer);
            }

            const ptr: number = exports.drumkit_process(this.instanceHandle, numFrames);
            if (!ptr) {
                if (this.allocationErrorCount++ < 5) {
                    console.error('[Drumkit] drumkit_process returned null pointer');
                }
                channelL?.fill(0);
                channelR?.fill(0);
                return true;
            }

            const offset = ptr >>> 2;
            const heap = this.heapFloat32;

            if (offset >= 0 && offset + numFrames <= heap.length) {
                for (let i = 0; i < numFrames; i++) {
                    const s = heap[offset + i];
                    if (channelL) channelL[i] = s;
                    if (channelR) channelR[i] = s;
                }
            } else {
                if (this.processErrorCount++ < 5) {
                    console.error(`[Drumkit] Heap out-of-bounds: offset=${offset}, heapLen=${heap.length}`);
                }
                channelL?.fill(0);
                channelR?.fill(0);
            }
        } catch (e) {
            if (this.processErrorCount++ < 5) {
                console.error('[Drumkit] process() error:', e);
            }
            channelL?.fill(0);
            channelR?.fill(0);
        }

        return true;
    }
}

registerProcessor('drumkit-processor', DrumkitProcessor);

import { ExpressiveVoiceProcessor } from '../engines/rubberband/ExpressiveVoiceProcessor';
import { resolveWorkletSampleRate } from '../utils/workletSampleRate';

interface AudioWorkletProcessor {
  readonly port: MessagePort;
  process(
    inputs: Float32Array[][],
    outputs: Float32Array[][],
    parameters: Record<string, Float32Array>
  ): boolean;
}

declare var AudioWorkletProcessor: {
  prototype: AudioWorkletProcessor;
  new(options?: any): AudioWorkletProcessor;
};

declare function registerProcessor(
  name: string,
  processorCtor: new (options?: any) => AudioWorkletProcessor
): void;

declare const globalThis: {
  sampleRate: number;
  currentTime?: number;
};
declare const currentFrame: number;

const EPSILON = 1e-3;

class ExpressiveVoiceWorkletProcessor extends AudioWorkletProcessor {
  private expressiveProcessor: ExpressiveVoiceProcessor;
  private lastGate = 0;

  // Pre-allocated configuration for expressive processor to avoid per-block GC allocations
  private readonly currentExpressiveConfig = {
    vibrato: { rate: 0, depth: 0, enabled: false },
    tremolo: { rate: 0, depth: 0, enabled: false },
    breath: { amount: 0, filterCutoff: 2000, enabled: false },
    envelope: { attack: 0, decay: 0, sustain: 0, release: 0 }
  };

  static get parameterDescriptors() {
    return [
      { name: 'vibratoRate', defaultValue: 5.5, minValue: 0.0, maxValue: 10.0, automationRate: 'k-rate' as const },
      { name: 'vibratoDepth', defaultValue: 0.0, minValue: 0.0, maxValue: 1.0, automationRate: 'k-rate' as const },
      { name: 'tremoloRate', defaultValue: 5.0, minValue: 0.0, maxValue: 20.0, automationRate: 'k-rate' as const },
      { name: 'tremoloDepth', defaultValue: 0.0, minValue: 0.0, maxValue: 1.0, automationRate: 'k-rate' as const },
      { name: 'breathAmount', defaultValue: 0.0, minValue: 0.0, maxValue: 1.0, automationRate: 'k-rate' as const },
      { name: 'attack', defaultValue: 0.0, minValue: 0.0, maxValue: 2.0, automationRate: 'k-rate' as const },
      { name: 'decay', defaultValue: 0.0, minValue: 0.0, maxValue: 2.0, automationRate: 'k-rate' as const },
      { name: 'sustain', defaultValue: 1.0, minValue: 0.0, maxValue: 1.0, automationRate: 'k-rate' as const },
      { name: 'release', defaultValue: 0.1, minValue: 0.0, maxValue: 5.0, automationRate: 'k-rate' as const },
      { name: 'gate', defaultValue: 1.0, minValue: 0.0, maxValue: 1.0, automationRate: 'k-rate' as const },
    ];
  }

  constructor() {
    super();
    this.expressiveProcessor = new ExpressiveVoiceProcessor({
      sampleRate: resolveWorkletSampleRate(),
    });
    this.expressiveProcessor.noteOn();
  }

  process(inputs: Float32Array[][], outputs: Float32Array[][], parameters: Record<string, Float32Array>): boolean {
    const output = outputs[0]?.[0];
    if (!output) return true;

    const input = inputs[0]?.[0];
    if (!input) {
      output.fill(0);
      return true;
    }

    const vibratoRate = parameters.vibratoRate?.[0] ?? 5.5;
    const vibratoDepth = parameters.vibratoDepth?.[0] ?? 0;
    const tremoloRate = parameters.tremoloRate?.[0] ?? 5.0;
    const tremoloDepth = parameters.tremoloDepth?.[0] ?? 0;
    const breathAmount = parameters.breathAmount?.[0] ?? 0;
    const attack = parameters.attack?.[0] ?? 0;
    const decay = parameters.decay?.[0] ?? 0;
    const sustain = parameters.sustain?.[0] ?? 1;
    const release = parameters.release?.[0] ?? 0.1;
    const gate = parameters.gate?.[0] ?? 1;

    if (this.lastGate <= 0 && gate > 0) {
      this.expressiveProcessor.noteOn();
    } else if (this.lastGate > 0 && gate <= 0) {
      this.expressiveProcessor.noteOff();
    }
    this.lastGate = gate;

    const fullyOpenEnvelope =
      gate >= 1 - EPSILON &&
      attack <= EPSILON &&
      decay <= EPSILON &&
      sustain >= 1 - EPSILON &&
      release <= EPSILON;
    const isBypass =
      vibratoDepth <= EPSILON &&
      tremoloDepth <= EPSILON &&
      breathAmount <= EPSILON &&
      fullyOpenEnvelope;

    const frameCount = output.length;
    const copyCount = Math.min(frameCount, input.length);
    for (let i = 0; i < copyCount; i++) {
      output[i] = input[i];
    }
    for (let i = copyCount; i < frameCount; i++) {
      output[i] = 0;
    }

    if (isBypass) {
      return true;
    }

    const now =
      typeof globalThis.currentTime === 'number'
        ? globalThis.currentTime
        : (typeof currentFrame === 'number' ? currentFrame / resolveWorkletSampleRate() : 0);
    this.expressiveProcessor.setCurrentTime(now);

    const cfg = this.currentExpressiveConfig;
    cfg.vibrato.rate = vibratoRate;
    cfg.vibrato.depth = vibratoDepth;
    cfg.vibrato.enabled = vibratoDepth > 0;

    cfg.tremolo.rate = tremoloRate;
    cfg.tremolo.depth = tremoloDepth;
    cfg.tremolo.enabled = tremoloDepth > 0;

    cfg.breath.amount = breathAmount;
    cfg.breath.enabled = breathAmount > 0;

    cfg.envelope.attack = attack;
    cfg.envelope.decay = decay;
    cfg.envelope.sustain = sustain;
    cfg.envelope.release = release;

    this.expressiveProcessor.updateConfig(cfg);

    this.expressiveProcessor.process(output, output);
    return true;
  }
}

registerProcessor('expressive-voice', ExpressiveVoiceWorkletProcessor);

/// <reference lib="dom" />
/// <reference types="vite/client" />

import { resolveWorkletSampleRate } from '../utils/workletSampleRate';

/**
 * ExpressiveVoiceProcessor — AudioWorkletProcessor for formant-preserving
 * pitch-shift correction on harmony voices.
 *
 * Architecture: voice-level (one instance per harmony voice).
 *
 * DSP algorithm:
 *   Three cascaded IIR biquad peaking-EQ filters (Direct Form II Transposed)
 *   correct the spectral-envelope shift introduced when a harmony voice's
 *   pitch is transposed by AudioBufferSourceNode.playbackRate or rubberband.
 *   When pitch is shifted by N semitones, all formants shift proportionally.
 *   These filters boost or cut at the original formant positions to restore
 *   natural vowel character.
 *
 *   Filter coefficients are recomputed once per 128-sample block (k-rate) —
 *   never inside the per-sample loop.  All working memory is pre-allocated in
 *   the constructor; process() makes zero heap allocations.
 *
 *   A pre-allocated output FIFO (Float32Array ring buffer) ensures exactly
 *   128 frames are delivered per process() call and provides a safe
 *   over/underflow boundary.  No SharedArrayBuffer is used, so Safari
 *   AudioWorkletGlobalScope is fully supported.
 *
 * AudioParam:
 *   pitchShift  (k-rate, semitones)  The semitone offset already applied to
 *               this voice.  Used to compute the inverse formant correction.
 *               Range –24 … +24.  Default 0 (passthrough).
 *
 * Messages (via port):
 *   { type: 'TEARDOWN' }  Zero all state and deactivate the processor.
 *                          Call this when the source voice ends to avoid OOM
 *                          accumulation across many short harmony triggers.
 */

// AudioWorklet global declarations (not available in standard TS lib).
declare class AudioWorkletProcessor {
  readonly port: MessagePort;
  process(
    inputs: Float32Array[][],
    outputs: Float32Array[][],
    parameters: Record<string, Float32Array>
  ): boolean;
}

declare function registerProcessor(
  name: string,
  processorCtor: new (options?: AudioWorkletNodeOptions) => AudioWorkletProcessor
): void;

declare const globalThis: { sampleRate: number };

// ---------------------------------------------------------------------------
// Constants — all module-level, no runtime allocation.
// ---------------------------------------------------------------------------

/** AudioWorklet standard block size (samples). */
const FRAME_SIZE = 128;

/** Output FIFO capacity (must be ≥ 2 × FRAME_SIZE, power of 2). */
const FIFO_SIZE = 512;
const FIFO_MASK = FIFO_SIZE - 1;

/** Number of formant correction biquad stages. */
const N_FORMANTS = 3;

/** Typical neutral-vowel speech formant centre frequencies (Hz). */
const FORMANT_HZ: [number, number, number] = [500, 1500, 2500];

/** Q values for each formant stage (narrower Q at higher formants). */
const FORMANT_Q: [number, number, number] = [2.0, 3.0, 4.0];

/** Maximum correction gain per formant stage (dB) at ±24 semitone shift. */
const MAX_GAIN_DB = 6.0;

// ---------------------------------------------------------------------------
// ExpressiveVoiceWorkletProcessor
// ---------------------------------------------------------------------------

class ExpressiveVoiceWorkletProcessor extends AudioWorkletProcessor {
  static get parameterDescriptors() {
    return [
      {
        name: 'pitchShift',
        defaultValue: 0,
        minValue: -24,
        maxValue: 24,
        automationRate: 'k-rate',
      },
    ];
  }

  // ------------------------------------------------------------------
  // Pre-allocated output FIFO (no SharedArrayBuffer — Safari safe).
  // ------------------------------------------------------------------
  private readonly fifo: Float32Array;
  private fifoWritePos = 0; // monotonically increasing (mod applied on access)
  private fifoReadPos = 0;

  // Per-sample working scratch (used to avoid repeated indexing math).
  private readonly scratch: Float32Array;

  // ------------------------------------------------------------------
  // IIR biquad filter state and coefficients.
  // Layout: [z1_f0, z2_f0,  z1_f1, z2_f1,  z1_f2, z2_f2]
  // Coefficients: [b0, b1, b2, a1, a2] per formant stage.
  // ------------------------------------------------------------------
  private readonly filterState: Float32Array; // N_FORMANTS * 2
  private readonly filterCoeffs: Float32Array; // N_FORMANTS * 5

  // Cache the last applied pitchShift to avoid redundant coefficient updates.
  private lastPitchShift = NaN;

  // Lifecycle flag — set false by TEARDOWN message.
  private alive = true;

  // ---------------------------------------------------------------------------

  constructor() {
    super();

    this.fifo = new Float32Array(FIFO_SIZE);
    this.scratch = new Float32Array(FRAME_SIZE);
    this.filterState = new Float32Array(N_FORMANTS * 2);
    this.filterCoeffs = new Float32Array(N_FORMANTS * 5);

    // Initialise to identity (passthrough) coefficients.
    this._setPassthrough();

    this.port.onmessage = (event: MessageEvent) => {
      if (event.data?.type === 'TEARDOWN') {
        this._teardown();
      }
    };
  }

  // ---------------------------------------------------------------------------
  // Private helpers — no dynamic allocation.
  // ---------------------------------------------------------------------------

  /** Load identity (passthrough) coefficients into all filter stages. */
  private _setPassthrough(): void {
    for (let i = 0; i < N_FORMANTS; i++) {
      this.filterCoeffs[i * 5 + 0] = 1; // b0
      this.filterCoeffs[i * 5 + 1] = 0; // b1
      this.filterCoeffs[i * 5 + 2] = 0; // b2
      this.filterCoeffs[i * 5 + 3] = 0; // a1
      this.filterCoeffs[i * 5 + 4] = 0; // a2
    }
  }

  /**
   * Recompute peaking-EQ biquad coefficients for the given pitch shift.
   *
   * For a shift of +N semitones the voice's formants have been moved UP to
   * origF × ratio.  We apply a boost at the ORIGINAL frequency to restore
   * spectral energy to its natural position ("de-chipmunk").
   *
   * For a shift of −N semitones the formants have moved DOWN to origF / ratio.
   * We boost at the SHIFTED (lower) frequency to restore warmth ("de-monster").
   *
   * Coefficients are derived from the Audio EQ Cookbook (R. Bristow-Johnson).
   * Called once per 128-sample block (k-rate) — never per sample.
   */
  private _updateCoefficients(pitchShiftSemitones: number): void {
    if (pitchShiftSemitones === this.lastPitchShift) return;
    this.lastPitchShift = pitchShiftSemitones;

    if (Math.abs(pitchShiftSemitones) < 0.05) {
      this._setPassthrough();
      return;
    }

    const sr = resolveWorkletSampleRate();
    const ratio = Math.pow(2.0, pitchShiftSemitones / 12.0);

    for (let i = 0; i < N_FORMANTS; i++) {
      const origF = FORMANT_HZ[i];
      const Q = FORMANT_Q[i];

      // Scale gain with |pitchShift|: full MAX_GAIN_DB at ±24 semitones.
      const gainDb = Math.min(MAX_GAIN_DB, MAX_GAIN_DB * Math.abs(pitchShiftSemitones) / 24.0);

      // Choose centre frequency: boost at original position for up-shift;
      // boost at shifted (lower) position for down-shift.
      // For down-shift: ratio < 1, so origF * ratio < origF (lower frequency).
      const f0 = pitchShiftSemitones > 0
        ? origF               // formants went UP — pull energy back DOWN to origF
        : origF * ratio;      // formants went DOWN — boost at the lower shifted position

      const f0Clamped = Math.max(20.0, Math.min(sr * 0.45, f0));

      // Peaking EQ (Audio EQ Cookbook).
      const A = Math.pow(10.0, gainDb / 40.0);   // sqrt of linear gain
      const w0 = (2.0 * Math.PI * f0Clamped) / sr;
      const cosW = Math.cos(w0);
      const sinW = Math.sin(w0);
      const alpha = sinW / (2.0 * Q);

      const a0inv = 1.0 / (1.0 + alpha / A);
      this.filterCoeffs[i * 5 + 0] = (1.0 + alpha * A) * a0inv;  // b0 / a0
      this.filterCoeffs[i * 5 + 1] = (-2.0 * cosW) * a0inv;       // b1 / a0
      this.filterCoeffs[i * 5 + 2] = (1.0 - alpha * A) * a0inv;   // b2 / a0
      this.filterCoeffs[i * 5 + 3] = (-2.0 * cosW) * a0inv;       // a1 / a0
      this.filterCoeffs[i * 5 + 4] = (1.0 - alpha / A) * a0inv;   // a2 / a0
    }
  }

  /**
   * Apply N_FORMANTS cascaded peaking-EQ biquad filters in place on `buf[0..len)`.
   * Uses Direct Form II Transposed — numerically stable for audio.
   * No allocation; state is read from / written to `this.filterState`.
   */
  private _applyFilters(buf: Float32Array, len: number): void {
    for (let f = 0; f < N_FORMANTS; f++) {
      const b0 = this.filterCoeffs[f * 5 + 0];
      const b1 = this.filterCoeffs[f * 5 + 1];
      const b2 = this.filterCoeffs[f * 5 + 2];
      const a1 = this.filterCoeffs[f * 5 + 3];
      const a2 = this.filterCoeffs[f * 5 + 4];
      let z1 = this.filterState[f * 2 + 0];
      let z2 = this.filterState[f * 2 + 1];

      for (let n = 0; n < len; n++) {
        const x = buf[n];
        const y = b0 * x + z1;
        z1 = b1 * x - a1 * y + z2;
        z2 = b2 * x - a2 * y;
        buf[n] = y;
      }

      this.filterState[f * 2 + 0] = z1;
      this.filterState[f * 2 + 1] = z2;
    }
  }

  /**
   * Zero all state, silence the FIFO, and deactivate the processor.
   * Called when { type: 'TEARDOWN' } is received via the port.
   */
  private _teardown(): void {
    this.alive = false;
    this.fifo.fill(0);
    this.scratch.fill(0);
    this.filterState.fill(0);
    this.fifoWritePos = 0;
    this.fifoReadPos = 0;
  }

  // ---------------------------------------------------------------------------
  // AudioWorkletProcessor.process()
  // ---------------------------------------------------------------------------

  process(
    inputs: Float32Array[][],
    outputs: Float32Array[][],
    parameters: Record<string, Float32Array>
  ): boolean {
    if (!this.alive) return false;

    // k-rate: update filter coefficients at most once per block.
    // `pitchShift` is a k-rate AudioParam, so parameters.pitchShift always has
    // exactly one value per block.  The guard handles edge cases in test mocks.
    const pitchShift =
      parameters.pitchShift && parameters.pitchShift.length > 0
        ? parameters.pitchShift[0]
        : 0;
    this._updateCoefficients(pitchShift);

    const outputChannels = outputs[0];
    if (!outputChannels || outputChannels.length === 0) return true;

    const nFrames = outputChannels[0]?.length ?? FRAME_SIZE;
    const inputCh = inputs[0]?.[0];

    // --- Step 1: Copy input (or silence) into scratch, apply formant filters ---
    if (inputCh && inputCh.length >= nFrames) {
      for (let n = 0; n < nFrames; n++) {
        this.scratch[n] = inputCh[n];
      }
    } else {
      for (let n = 0; n < nFrames; n++) {
        this.scratch[n] = 0;
      }
    }
    this._applyFilters(this.scratch, nFrames);

    // --- Step 2: Write filtered samples into the output FIFO ---
    for (let n = 0; n < nFrames; n++) {
      this.fifo[(this.fifoWritePos + n) & FIFO_MASK] = this.scratch[n];
    }
    this.fifoWritePos += nFrames;

    // --- Step 3: Read exactly nFrames from FIFO → all output channels ---
    const available = this.fifoWritePos - this.fifoReadPos;
    const nRead = available >= nFrames ? nFrames : available;

    for (let ch = 0; ch < outputChannels.length; ch++) {
      const outCh = outputChannels[ch];
      if (!outCh) continue;
      for (let n = 0; n < nRead; n++) {
        outCh[n] = this.fifo[(this.fifoReadPos + n) & FIFO_MASK];
      }
      // Zero-pad if FIFO underflows (should not happen in steady state).
      for (let n = nRead; n < nFrames; n++) {
        outCh[n] = 0;
      }
    }
    this.fifoReadPos += nRead;

    return true;
  }
}

registerProcessor('expressive-voice-processor', ExpressiveVoiceWorkletProcessor);

// Shared Emscripten import wiring for hyphon_native.wasm inside AudioWorklets.
// Open303, Prophecy, and the analog drumkit instantiate the same threaded WASM
// module; memory imports use the minified namespace "a" / name "a", not env.memory.

/** WebAssembly page size (64 KiB). */
const WASM_PAGE_BYTES = 65536;

/**
 * Initial memory of the threaded hyphon_native.wasm build, in 64 KiB pages.
 *
 * MUST equal `hyphonNative.initialMemoryMb` in emscripten/wasm_memory_budget.json
 * (the value emscripten/build.sh passes as -s INITIAL_MEMORY): the worklets
 * instantiate the module with an *imported* memory, and a memory whose `initial`
 * is below the module's declared minimum fails instantiation outright.
 * src/__tests__/wasmMemoryBudget.test.ts enforces the match in CI.
 *
 * 128 MB rather than the previous 512 MB — see
 * docs/wasm/BUILD_NOTES.md#four-worlds-memory-budget. A 512 MB `shared: true`
 * allocation is a frequent SharedArrayBuffer failure on mobile Safari and low-RAM
 * Chromebooks even with correct COOP/COEP; the module grows on demand up to
 * HYPHON_NATIVE_MAX_MEMORY_PAGES.
 */
export const HYPHON_NATIVE_MIN_MEMORY_PAGES = (128 * 1024 * 1024) / WASM_PAGE_BYTES; // 2048

/** Growth ceiling, matching -s MAXIMUM_MEMORY in emscripten/build.sh (1 GB). */
export const HYPHON_NATIVE_MAX_MEMORY_PAGES = (1024 * 1024 * 1024) / WASM_PAGE_BYTES; // 16384

/**
 * Initial memory of the single-threaded hyphon_native.st.wasm build, in pages.
 * MUST equal `hyphonNativeSt.initialMemoryMb` (src/__tests__/wasmMemoryBudget.test.ts).
 * Non-shared, so this is an ordinary ArrayBuffer and growth is cheap.
 */
export const HYPHON_NATIVE_ST_MIN_MEMORY_PAGES = (16 * 1024 * 1024) / WASM_PAGE_BYTES; // 256

/** Growth ceiling of the ST build, matching `hyphonNativeSt.maximumMemoryMb` (512 MB). */
export const HYPHON_NATIVE_ST_MAX_MEMORY_PAGES = (512 * 1024 * 1024) / WASM_PAGE_BYTES; // 8192

/**
 * The two hyphon_native link profiles emitted by emscripten/build.sh.
 * See docs/wasm/BUILD_NOTES.md#threading-profiles.
 */
export type HyphonNativeThreading = 'pthread' | 'st';

export interface HyphonNativeArtifact {
  threading: HyphonNativeThreading;
  /** File names under public/. */
  wasm: string;
  glue: string;
  exportMap: string;
  /** Imported memory is `shared: true` (pthread) or a plain ArrayBuffer (st). */
  sharedMemory: boolean;
  minMemoryPages: number;
  maxMemoryPages: number;
}

export const HYPHON_NATIVE_ARTIFACTS: Readonly<Record<HyphonNativeThreading, HyphonNativeArtifact>> = {
  pthread: {
    threading: 'pthread',
    wasm: 'hyphon_native.wasm',
    glue: 'hyphon_native.js',
    exportMap: 'hyphon_wasm_export_map.json',
    sharedMemory: true,
    minMemoryPages: HYPHON_NATIVE_MIN_MEMORY_PAGES,
    maxMemoryPages: HYPHON_NATIVE_MAX_MEMORY_PAGES,
  },
  st: {
    threading: 'st',
    wasm: 'hyphon_native.st.wasm',
    glue: 'hyphon_native.st.js',
    exportMap: 'hyphon_wasm_export_map.st.json',
    sharedMemory: false,
    minMemoryPages: HYPHON_NATIVE_ST_MIN_MEMORY_PAGES,
    maxMemoryPages: HYPHON_NATIVE_ST_MAX_MEMORY_PAGES,
  },
};

export type WasmExportMap = Record<string, string>;

/**
 * Map minified WASM export names to the bare API names worklets use.
 * When wasm-opt minifies exports, `hyphon_wasm_export_map.json` (built from
 * hyphon_native.js) supplies the minified key for each logical export.
 */
export function normalizeWasmExports(
  exports: WebAssembly.Exports,
  map: WasmExportMap = {},
): Record<string, unknown> {
  const raw = exports as Record<string, unknown>;
  const normalized: Record<string, unknown> = { ...raw };

  for (const [bare, minified] of Object.entries(map)) {
    const fn = raw[minified];
    if (typeof fn === 'function') {
      normalized[bare] = fn;
      normalized[`_${bare}`] = fn;
    }
  }

  for (const [key, val] of Object.entries(raw)) {
    if (key.startsWith('_') && typeof val === 'function') {
      const bare = key.slice(1);
      if (normalized[bare] === undefined) normalized[bare] = val;
    }
  }

  return normalized;
}

/** How many raw WASM export names to include in mismatch errors. */
const WASM_EXPORT_NAME_PREVIEW = 48;

/**
 * Describe a missing-API failure with the actual (often minified) export names
 * present on the instantiated module, so a stale export map is obvious in logs.
 */
export function formatMissingWasmExports(
  rawExports: WebAssembly.Exports,
  requiredBareNames: readonly string[],
): string {
  const names = Object.keys(rawExports).sort();
  const preview = names.slice(0, WASM_EXPORT_NAME_PREVIEW).join(', ');
  const extra =
    names.length > WASM_EXPORT_NAME_PREVIEW
      ? ` … (+${names.length - WASM_EXPORT_NAME_PREVIEW} more)`
      : '';
  return (
    `missing ${requiredBareNames.join(', ')}. ` +
    `WASM exports (${names.length}): ${preview}${extra}`
  );
}

/** Bare export names the Open303 worklet must resolve via the export map. */
export const OPEN303_REQUIRED_WASM_EXPORTS = [
  'open303_create',
  'open303_init',
  // emscripten/jc303_wrapper.cpp exports the multi-instance *_handle ABI;
  // bare jc303_init/jc303_process have never existed in hyphon_native.wasm.
  'jc303_init_handle',
  'jc303_process_handle',
] as const;

/** Bare export names the Prophecy worklet must resolve via the export map. */
export const PROPHECY_REQUIRED_WASM_EXPORTS = [
  'prophecy_create',
  'prophecy_init',
  'prophecy_process',
] as const;

/** Bare export names the drumkit worklet must resolve via the export map. */
export const DRUMKIT_REQUIRED_WASM_EXPORTS = [
  'drumkit_create',
  'drumkit_init',
  'drumkit_set_kit',
  'drumkit_trigger',
  'drumkit_choke_open_hat',
  'drumkit_process',
] as const;

/**
 * Name-only snapshot of a compiled module's exports (for main-thread diagnostics).
 *
 * Values are inert placeholder *functions*, not `null`: the sufficiency
 * predicates below run `normalizeWasmExports` over this snapshot and ask
 * `typeof … === 'function'`. With `null` values every predicate answered
 * "insufficient" unconditionally, so a perfectly good binary was reported as
 * `export map did not resolve …` — pointing debugging at the artifact instead of
 * at the import table. A snapshot can only answer "is this name present", and
 * the placeholder is what lets it answer that honestly.
 */
export function wasmExportNameSnapshot(module: WebAssembly.Module): WebAssembly.Exports {
  const out: Record<string, unknown> = {};
  for (const entry of WebAssembly.Module.exports(module)) {
    out[entry.name] = () => undefined;
  }
  return out as WebAssembly.Exports;
}

/**
 * True when the export map fails to surface either the native open303_* API or
 * the legacy jc303_* API against the compiled module's raw export table.
 */
export function open303ExportMapInsufficient(
  module: WebAssembly.Module,
  exportMap: WasmExportMap,
): boolean {
  const normalized = normalizeWasmExports(wasmExportNameSnapshot(module), exportMap);
  const hasNative =
    typeof normalized.open303_create === 'function' &&
    typeof normalized.open303_init === 'function';
  const hasLegacy =
    typeof normalized.jc303_init_handle === 'function' &&
    typeof normalized.jc303_process_handle === 'function';
  return !hasNative && !hasLegacy;
}

/** True when prophecy_create/init cannot be resolved from the export map. */
export function prophecyExportMapInsufficient(
  module: WebAssembly.Module,
  exportMap: WasmExportMap,
): boolean {
  const normalized = normalizeWasmExports(wasmExportNameSnapshot(module), exportMap);
  return !hasProphecyApi(normalized);
}

export function hasProphecyApi(exports: Record<string, unknown>): boolean {
  return (
    typeof exports.prophecy_create === 'function' &&
    typeof exports.prophecy_init === 'function'
  );
}

/** True when drumkit_create/init/process cannot be resolved from the export map. */
export function drumkitExportMapInsufficient(
  module: WebAssembly.Module,
  exportMap: WasmExportMap,
): boolean {
  const normalized = normalizeWasmExports(wasmExportNameSnapshot(module), exportMap);
  return !hasDrumkitApi(normalized);
}

export function hasDrumkitApi(exports: Record<string, unknown>): boolean {
  return DRUMKIT_REQUIRED_WASM_EXPORTS.every(
    (name) => typeof exports[name] === 'function',
  );
}

export interface HyphonNativeImportContext {
  getWasmInstance: () => WebAssembly.Instance | null;
  getImportedMemory: () => WebAssembly.Memory | null;
  setImportedMemory: (memory: WebAssembly.Memory) => void;
  onHeapUpdate: () => void;
  logPrefix?: string;
}

function getTime(): number {
  if (typeof performance !== 'undefined' && performance.now) {
    return performance.now();
  }
  return Date.now();
}

export function createHyphonMemory(
  pages: number | undefined,
  shared: boolean,
  logPrefix = '[HyphonNative]',
): WebAssembly.Memory {
  const artifact = HYPHON_NATIVE_ARTIFACTS[shared ? 'pthread' : 'st'];
  const memoryImportPages = Math.max(pages ?? 0, artifact.minMemoryPages);
  const maxMemoryPages = artifact.maxMemoryPages;

  if (shared) {
    try {
      return new WebAssembly.Memory({
        initial: memoryImportPages,
        maximum: maxMemoryPages,
        shared: true,
      });
    } catch (err) {
      // Distinguish "no SAB at all" (COOP/COEP) from "SAB exists but this
      // reservation is too large for the device" — the latter is the common
      // mobile failure and is worth reporting with the actual sizes.
      const sizesMb = `initial=${(memoryImportPages * WASM_PAGE_BYTES) / 1048576}MB, ` +
        `maximum=${(maxMemoryPages * WASM_PAGE_BYTES) / 1048576}MB`;
      if (typeof SharedArrayBuffer === 'undefined') {
        throw new Error(
          `${logPrefix} SharedArrayBuffer not available. Ensure COOP/COEP headers are configured.`,
        );
      }
      throw new Error(
        `${logPrefix} shared WebAssembly.Memory allocation failed (${sizesMb}): ` +
        `${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }

  return new WebAssembly.Memory({
    initial: memoryImportPages,
    maximum: maxMemoryPages,
  });
}

function tableInvoke(
  ctx: HyphonNativeImportContext,
  index: number,
  args: number[],
): number {
  const exports = ctx.getWasmInstance()?.exports as Record<string, unknown> | undefined;
  const tbl = (exports?.wasmTable ?? exports?.table) as WebAssembly.Table | undefined;
  if (!tbl) return 0;
  const fn = tbl.get(index) as ((...a: number[]) => number) | null;
  if (!fn) return 0;
  try {
    return fn(...args) ?? 0;
  } catch {
    return 0;
  }
}

export function createEmscriptenEnv(ctx: HyphonNativeImportContext): Record<string, unknown> {
  const logPrefix = ctx.logPrefix ?? '[HyphonNative]';

  const resizeHeap = (size: number): number => {
    const memory =
      (ctx.getWasmInstance()?.exports as { memory?: WebAssembly.Memory } | undefined)?.memory ??
      ctx.getImportedMemory();
    if (!memory) {
      console.warn(`${logPrefix} emscripten_resize_heap called but no memory available yet`);
      return 0;
    }
    const currentPages = memory.buffer.byteLength / (64 * 1024);
    const targetPages = Math.ceil(size / (64 * 1024));
    const deltaPages = targetPages - currentPages;
    if (deltaPages > 0) {
      try {
        memory.grow(deltaPages);
        ctx.onHeapUpdate();
        return 1;
      } catch (e) {
        console.error(`${logPrefix} Failed to grow heap:`, e);
        return 0;
      }
    }
    return 1;
  };

  const handleStackOverflow = (): void => {
    throw new Error(`${logPrefix} Stack overflow detected in WASM`);
  };

  const env: Record<string, unknown> = {
    _abort_js: () => console.error('WASM Abort'),
    abort: () => console.error('WASM Abort'),
    __handle_stack_overflow: handleStackOverflow,
    segfault: () => {
      console.error(`${logPrefix} Segmentation fault`);
      return 0;
    },
    alignfault: () => {
      console.error(`${logPrefix} Alignment fault`);
      return 0;
    },
    emscripten_resize_heap: resizeHeap,
    _emscripten_resize_heap: resizeHeap,
    emscripten_notify_memory_growth: () => ctx.onHeapUpdate(),
    exp: Math.exp,
    pow: Math.pow,
    sin: Math.sin,
    cos: Math.cos,
    fmod: (x: number, y: number) => x % y,
    invoke_ii: (index: number, a1: number) => tableInvoke(ctx, index, [a1]),
    invoke_vi: (index: number, a1: number) => {
      tableInvoke(ctx, index, [a1]);
    },
    invoke_vii: (index: number, a1: number, a2: number) => {
      tableInvoke(ctx, index, [a1, a2]);
    },
    invoke_vid: (index: number, a1: number, a2: number) => {
      tableInvoke(ctx, index, [a1, a2]);
    },
    invoke_dddddd: (
      index: number,
      a1: number,
      a2: number,
      a3: number,
      a4: number,
      a5: number,
    ) => tableInvoke(ctx, index, [a1, a2, a3, a4, a5]),
    _emscripten_thread_set_strongref: () => {},
    emscripten_exit_with_live_runtime: () => {},
    _emscripten_notify_mailbox_postmessage: () => {},
    emscripten_check_blocking_allowed: () => {},
    _emscripten_receive_on_main_thread_js: () => {},
    _emscripten_init_main_thread_js: () => {},
    _emscripten_thread_mailbox_await: () => {},
    _emscripten_thread_cleanup: () => {},
    _setitimer_js: () => {},
    _emscripten_runtime_keepalive_clear: () => {},
    clock_time_get: () => Date.now() * 1_000_000,
    emscripten_get_now: () => getTime(),
    // Wall clock vs monotonic: Emscripten's glue maps these exactly this way.
    // Unknown env symbols are derived in buildHyphonWasmImports(); these two
    // stay explicit so the worklets do not run on a silent no-op stub.
    emscripten_date_now: () => Date.now(),
    _emscripten_get_now_is_monotonic: () => 1,
    __emscripten_init_main_thread_js: () => {},
    __emscripten_thread_cleanup: () => {},
    _embind_register_function: () => {},
    _embind_register_void: () => {},
    _embind_register_bool: () => {},
    _embind_register_std_string: () => {},
    _embind_register_std_wstring: () => {},
    _embind_register_emval: () => {},
    _embind_register_integer: () => {},
    _embind_register_bigint: () => {},
    _embind_register_float: () => {},
    _embind_register_memory_view: () => {},

    // hyphon_native.wasm links emscripten/main.cpp (the Pyodide bootstrap
    // orchestrator) alongside the DSP wrappers, so these come along even
    // though no worklet code path calls them. Explicit implementations here
    // are overrides on top of the derived import table; a *new* Emscripten
    // symbol no longer requires a source edit (see installDerivedFunctionStubs).
    //
    // main() runs on the main thread through the Emscripten glue; in a worklet
    // it must not run at all, hence the inert implementations.
    emscripten_run_script: () => 0,
    exit: () => {},
    __cxa_throw: (ptr: number, type: number, destructor: number) => {
      throw new Error(
        `${logPrefix} C++ exception thrown in WASM ` +
        `(ptr=${ptr}, type=${type}, destructor=${destructor})`,
      );
    },
  };

  const lowercaseAliases: Record<string, unknown> = {
    a: () => console.error('WASM Abort'),
    b: () => console.error('WASM Abort'),
    c: resizeHeap,
    d: resizeHeap,
    e: () => ctx.onHeapUpdate(),
    f: Math.exp,
    g: Math.pow,
    h: Math.sin,
    i: Math.cos,
    j: (x: number, y: number) => x % y,
  };

  for (let i = 0; i < 26; i++) {
    const key = String.fromCharCode(97 + i);
    if (env[key] === undefined) {
      env[key] = lowercaseAliases[key] ?? (() => {});
    }
  }

  // Emscripten minified invoke stubs (uppercase A–Z) — required by hyphon_native.wasm.
  const genericInvoke = (...args: number[]) => tableInvoke(ctx, args[0], args.slice(1));
  for (let i = 0; i < 26; i++) {
    const key = String.fromCharCode(65 + i);
    if (env[key] === undefined) {
      env[key] = genericInvoke;
    }
  }

  return env;
}

/**
 * Walk the compiled module's import section and install a typed no-op stub
 * (`() => 0`) for every `kind: 'function'` import that is not already a
 * callable. Explicit `createEmscriptenEnv` / `createWASIImports` entries win.
 *
 * This is the safety net for the #1176/#1177 class: an incomplete allowlist
 * used to make `WebAssembly.instantiate()` throw `function import requires a
 * callable`, after which every 303/Prophecy voice degraded to a JS fallback
 * that still made sound. A stub cannot fail instantiation; it warns once so
 * the missing symbol is visible in the worklet log.
 */
function installDerivedFunctionStubs(
  module: WebAssembly.Module,
  importsObject: Record<string, Record<string, unknown>>,
  logPrefix: string,
): void {
  for (const imp of WebAssembly.Module.imports(module)) {
    if (imp.kind !== 'function') continue;
    let bag = importsObject[imp.module];
    if (!bag) {
      bag = {};
      importsObject[imp.module] = bag;
    }
    if (typeof bag[imp.name] === 'function') continue;
    console.warn(
      `${logPrefix} unsatisfied WASM import ${imp.module}.${imp.name}; installing no-op stub (returns 0)`,
    );
    bag[imp.name] = (..._args: number[]): number => 0;
  }
}

export function createWASIImports(): Record<string, unknown> {
  return {
    proc_exit: () => {},
    fd_close: () => 0,
    fd_write: () => 0,
    fd_seek: () => 0,
    fd_read: () => 0,
    path_open: () => 0,
    path_filestat_get: () => 0,
    path_unlink_file: () => 0,
    path_create_directory: () => 0,
    path_remove_directory: () => 0,
    path_rename: () => 0,
    path_symlink: () => 0,
    path_readlink: () => 0,
    path_link: () => 0,
    path_filestat_set_times: () => 0,
    fd_fdstat_get: () => 0,
    fd_prestat_get: () => 0,
    fd_prestat_dir_name: () => 0,
    environ_sizes_get: () => 0,
    environ_get: () => 0,
    args_sizes_get: () => 0,
    args_get: () => 0,
    clock_res_get: () => 0,
    clock_time_get: () => 0,
    random_get: () => 0,
    sched_yield: () => 0,
    poll_oneoff: () => 0,
  };
}

export function buildHyphonWasmImports(
  module: WebAssembly.Module,
  ctx: HyphonNativeImportContext,
  options: { memoryPages?: number; isThreaded: boolean },
): { imports: WebAssembly.Imports; memory: WebAssembly.Memory | null } {
  const env = createEmscriptenEnv(ctx);
  const wasiImports = createWASIImports();

  const importsObject: Record<string, Record<string, unknown>> = {
    env: env as Record<string, unknown>,
    a: env as Record<string, unknown>,
    wasi_snapshot_preview1: wasiImports as Record<string, unknown>,
    wasi_unstable: wasiImports as Record<string, unknown>,
    '': env as Record<string, unknown>,
  };

  const requiredImports = WebAssembly.Module.imports(module);
  for (const mod of new Set(requiredImports.map((i) => i.module))) {
    if (!importsObject[mod]) {
      importsObject[mod] = env as Record<string, unknown>;
    }
  }

  let memory: WebAssembly.Memory | null = null;
  const memoryImport = requiredImports.find((i) => i.kind === 'memory');
  if (memoryImport) {
    memory = createHyphonMemory(options.memoryPages, options.isThreaded, ctx.logPrefix);
    ctx.setImportedMemory(memory);
    if (!importsObject[memoryImport.module]) {
      importsObject[memoryImport.module] = {};
    }
    importsObject[memoryImport.module][memoryImport.name] = memory;
  }

  installDerivedFunctionStubs(module, importsObject, ctx.logPrefix ?? '[HyphonNative]');

  return { imports: importsObject as WebAssembly.Imports, memory };
}

// src/audio-worklets/hyphonNativeSession.ts
// One hyphon_native.wasm instance per audio session, shared by every voice.
//
// Every AudioWorkletNode created on a BaseAudioContext runs in that context's
// single AudioWorkletGlobalScope, on the one render thread. Open303 (bass1 /
// bass2 / lead303, plus their lazily created live high-fid voices) and Prophecy
// (part A / part B) used to instantiate the module once per processor, and each
// instantiation imported its own 128 MB `shared: true` WebAssembly.Memory — five
// SharedArrayBuffers before a note played. The C wrappers already expose
// multi-instance handles (open303_create / jc303_create / prophecy_create /
// highfid303_create), so the processors now take handles on one instance instead.
//
// The session lives on `globalThis` under a registered Symbol rather than in
// module scope: open303-processor and prophecy-processor are bundled as separate
// worklet scripts, each with its own copy of this module, but both share the
// AudioWorkletGlobalScope's global object. Calls into the instance never overlap
// because every processor's message handler and process() run on that thread.

import {
    buildHyphonWasmImports,
    normalizeWasmExports,
    type HyphonNativeThreading,
    type WasmExportMap,
} from './hyphonNativeImports';

/** 64 KiB — WebAssembly page size. */
const WASM_PAGE_BYTES = 65536;

/** Instantiation budget; a stuck instantiate must not hang every voice forever. */
const INSTANTIATE_TIMEOUT_MS = 5000;

const REGISTRY_KEY = Symbol.for('hyphon.nativeSession');

export interface HyphonNativeInitData {
    wasmBytes?: ArrayBuffer;
    isThreaded?: boolean;
    memoryPages?: number;
    exportMap?: WasmExportMap;
}

/** Heap telemetry reported to the main thread (Engine HUD). */
export interface HyphonNativeHeapStats {
    /** hyphon_native memories alive in this audio session. Anything but 1 is a regression. */
    heapCount: number;
    initialPages: number;
    currentPages: number;
    growEvents: number;
    /** Voice processors currently holding handles on the shared instance. */
    voices: number;
    /** Link profile the instance was built from: pthread (shared memory) or st. */
    threading: HyphonNativeThreading;
}

interface SessionRegistry {
    pending: Promise<HyphonNativeSession> | null;
    /** Profile of the pending / live session, for mismatch warnings. */
    threading: HyphonNativeThreading | null;
    heapCount: number;
}

function getRegistry(): SessionRegistry {
    const g = globalThis as { [REGISTRY_KEY]?: SessionRegistry };
    let registry = g[REGISTRY_KEY];
    if (!registry) {
        registry = { pending: null, threading: null, heapCount: 0 };
        g[REGISTRY_KEY] = registry;
    }
    return registry;
}

export class HyphonNativeSession {
    readonly instance: WebAssembly.Instance;
    readonly exports: Record<string, any>;
    readonly memory: WebAssembly.Memory | null;
    readonly initialPages: number;
    readonly threading: HyphonNativeThreading;

    private growEvents = 0;
    private lastSeenPages: number;
    private voices = 0;
    private readonly heapListeners = new Set<(stats: HyphonNativeHeapStats) => void>();

    constructor(
        instance: WebAssembly.Instance,
        exports: Record<string, any>,
        memory: WebAssembly.Memory | null,
        threading: HyphonNativeThreading,
    ) {
        this.threading = threading;
        this.instance = instance;
        this.exports = exports;
        this.memory = memory;
        this.initialPages = memory ? memory.buffer.byteLength / WASM_PAGE_BYTES : 0;
        this.lastSeenPages = this.initialPages;
    }

    get stats(): HyphonNativeHeapStats {
        return {
            heapCount: getRegistry().heapCount,
            initialPages: this.initialPages,
            currentPages: this.memory ? this.memory.buffer.byteLength / WASM_PAGE_BYTES : 0,
            growEvents: this.growEvents,
            voices: this.voices,
            threading: this.threading,
        };
    }

    /** Register a voice processor as a user of this instance. */
    retain(): void {
        this.voices++;
    }

    /** A voice processor destroyed its handles. The instance itself stays up for
     *  the life of the audio context — later voices reuse it. */
    release(): void {
        this.voices = Math.max(0, this.voices - 1);
    }

    /** Called whenever the heap grows. Returns an unsubscribe function. */
    onHeapGrow(listener: (stats: HyphonNativeHeapStats) => void): () => void {
        this.heapListeners.add(listener);
        return () => this.heapListeners.delete(listener);
    }

    /** @internal — wired to emscripten_resize_heap / notify_memory_growth. */
    notifyHeapGrow(): void {
        // resize_heap and notify_memory_growth can both fire for one grow.
        const pages = this.memory ? this.memory.buffer.byteLength / WASM_PAGE_BYTES : 0;
        if (pages <= this.lastSeenPages) return;
        this.lastSeenPages = pages;
        this.growEvents++;
        const stats = this.stats;
        for (const listener of this.heapListeners) listener(stats);
    }
}

/**
 * Get this audio session's hyphon_native instance, instantiating it on first use.
 *
 * Concurrent callers share one in-flight promise, so five voices initialising in
 * parallel compile, allocate memory and instantiate exactly once. A failed
 * instantiation is not cached — the next caller (e.g. Open303's retry loop)
 * starts a fresh attempt.
 */
export function acquireHyphonNativeSession(
    data: HyphonNativeInitData,
    logPrefix = '[HyphonNative]',
): Promise<HyphonNativeSession> {
    const registry = getRegistry();
    const threading: HyphonNativeThreading = data.isThreaded ? 'pthread' : 'st';
    if (!registry.pending) {
        const attempt = createSession(data, logPrefix, registry);
        registry.pending = attempt;
        registry.threading = threading;
        attempt.catch(() => {
            if (registry.pending === attempt) {
                registry.pending = null;
                registry.threading = null;
            }
        });
    } else if (registry.threading !== threading) {
        // The main thread binds one profile per AudioContext
        // (src/engines/hyphonNativeVariant.ts), so this means a caller bypassed it.
        console.warn(
            `${logPrefix} asked for the ${threading} hyphon_native build but this audio session ` +
            `already runs ${registry.threading}; reusing it (one heap per session).`,
        );
    }
    return registry.pending;
}

/** Drop the session so the next acquire instantiates afresh. For tests only. */
export function resetHyphonNativeSessionForTests(): void {
    const g = globalThis as { [REGISTRY_KEY]?: SessionRegistry };
    delete g[REGISTRY_KEY];
}

async function createSession(
    data: HyphonNativeInitData,
    logPrefix: string,
    registry: SessionRegistry,
): Promise<HyphonNativeSession> {
    if (!data.wasmBytes || data.wasmBytes.byteLength === 0) {
        throw new Error('No WASM bytes received');
    }

    const module = await WebAssembly.compile(data.wasmBytes);

    let session: HyphonNativeSession | null = null;
    let pendingInstance: WebAssembly.Instance | null = null;
    let importedMemory: WebAssembly.Memory | null = null;

    const { imports, memory } = buildHyphonWasmImports(
        module,
        {
            getWasmInstance: () => session?.instance ?? pendingInstance,
            getImportedMemory: () => importedMemory,
            setImportedMemory: (m) => {
                importedMemory = m;
            },
            onHeapUpdate: () => session?.notifyHeapGrow(),
            logPrefix,
        },
        { memoryPages: data.memoryPages, isThreaded: !!data.isThreaded },
    );
    if (memory) registry.heapCount++;

    try {
        let timer: ReturnType<typeof setTimeout> | undefined;
        const timeout = new Promise<never>((_, reject) => {
            timer = setTimeout(
                () => reject(new Error(`WASM instantiation timeout (${INSTANTIATE_TIMEOUT_MS / 1000}s)`)),
                INSTANTIATE_TIMEOUT_MS,
            );
        });
        try {
            pendingInstance = await Promise.race([WebAssembly.instantiate(module, imports), timeout]);
        } finally {
            clearTimeout(timer);
        }

        const exports = normalizeWasmExports(pendingInstance.exports, data.exportMap ?? {}) as Record<string, any>;
        const ownMemory =
            memory ?? ((pendingInstance.exports as { memory?: WebAssembly.Memory }).memory ?? null);
        configureWasmStack(exports);

        session = new HyphonNativeSession(
            pendingInstance,
            exports,
            ownMemory,
            data.isThreaded ? 'pthread' : 'st',
        );
        console.log(
            `${logPrefix} hyphon_native (${session.threading}) instantiated once for this audio session ` +
            `(${session.initialPages} pages, heaps=${registry.heapCount})`,
        );
        return session;
    } catch (e) {
        // The memory is unreachable now; don't let it inflate the HUD's heap count.
        if (memory) registry.heapCount = Math.max(0, registry.heapCount - 1);
        throw e;
    }
}

/**
 * One-time runtime setup that previously ran inside each processor.
 *
 * - __wasm_call_ctors: hyphon_native.wasm is an Emscripten C++ module whose model
 *   registry, rosic wavetables and embind registrations live in global objects.
 *   The Emscripten glue runs the constructors on the main thread, but worklets
 *   instantiate by hand; skipping them left the statics zeroed, so
 *   open303_create() returned a null handle and Prophecy trapped on
 *   `unreachable`. Running them twice would re-construct live globals, which is
 *   one more reason the instance must be shared rather than re-initialised.
 * - __set_stack_limits(base, 0): the jc303 build calls __handle_stack_overflow
 *   during init even though sp never falls below the real limit; stackEnd=0
 *   makes the check (sp < 0) always false.
 */
function configureWasmStack(exports: Record<string, any>): void {
    if (typeof exports.emscripten_stack_init === 'function') {
        exports.emscripten_stack_init();
    }
    if (typeof exports.__wasm_call_ctors === 'function') {
        exports.__wasm_call_ctors();
    }
    if (typeof exports.__set_stack_limits === 'function' &&
        typeof exports.emscripten_stack_get_base === 'function') {
        const stackBase = exports.emscripten_stack_get_base();
        if (stackBase > 0) {
            exports.__set_stack_limits(stackBase, 0);
        }
    }
}

// src/audio-worklets/open303-processor.ts
// Hardened version with stack overflow protection and graceful degradation

import { WorkletPerfReporter } from './workletPerfReporter';
import { Open303EngineSession } from './open303/engineSession';
import { Open303EngineSelection } from './open303/engineSelection';
import { ParameterQueue } from './open303/parameterQueue';
import { SynthState, getTime, type EngineFamily } from './open303/shared';

// Definitions for the AudioWorklet scope
declare class AudioWorkletProcessor {
    readonly port: MessagePort;
    process(inputs: Float32Array[][], outputs: Float32Array[][], parameters: Record<string, Float32Array>): boolean;
}
declare const currentTime: number;

declare function registerProcessor(name: string, processorCtor: new () => AudioWorkletProcessor): void;

// Map from jc303_set* function name → open303 paramId
// (keeps the existing message protocol while supporting the new native API)
const JC303_PARAM_MAP: Record<string, number> = {
    jc303_setWaveform:   0,  // OPEN303_WAVEFORM
    jc303_setTuning:     1,  // OPEN303_TUNING
    jc303_setCutoff:     2,  // OPEN303_CUTOFF
    jc303_setResonance:  3,  // OPEN303_RESONANCE
    jc303_setEnvMod:     4,  // OPEN303_ENV_MOD
    jc303_setDecay:      5,  // OPEN303_DECAY
    jc303_setAccent:     6,  // OPEN303_ACCENT
    jc303_setVolume:     7,  // OPEN303_VOLUME
    jc303_setFilterMode: 8,  // OPEN303_FILTER_MODE
};

/** open303_* entry points the live A/B stock side (Phase L2) drives. */
interface StockSideExports {
    open303_note_on(handle: number | bigint, note: number, velocity: number): void;
    open303_note_off(handle: number | bigint, note: number): void;
    open303_all_notes_off(handle: number | bigint): void;
    open303_process(handle: number | bigint, outPtr: number | bigint, numFrames: number): void;
}

/** Payloads of the L2/L3 configuration messages. */
interface LiveHighFidMessageData {
    armed?: unknown;
    coefficients?: unknown;
    buffer?: unknown;
}

class Open303Processor extends AudioWorkletProcessor {
    private readonly session = new Open303EngineSession(this.port);
    private readonly engineSelection = new Open303EngineSelection(this.session, this.port, () => this.clearAllNotes());
    private readonly parameterQueue = new ParameterQueue(this.applyParamMessage.bind(this));
    private readonly perf = new WorkletPerfReporter(this.port, 'open303');

    // Mild makeup gain — hyphon_native 303 engines already run near full scale.
    private static readonly OUTPUT_GAIN = 1.0;

    // Stuck note protection
    private activeNotes = new Float64Array(128); // note (0-127) -> startTime (ms). 0 means inactive.
    private activeNoteCount = 0;
    private static readonly MAX_NOTE_DURATION_MS = 8000;
    private stuckNoteWarnings = 0;

    // Rate limiting
    private lastNoteOnTime = 0;
    private static readonly MIN_NOTE_INTERVAL_MS = 5;
    private static readonly MAX_NOTES_PER_SECOND = 50;
    private noteOnTimes: number[] = [];

    // Portamento/slide fix
    private pendingNote: { note: number; velocity: number } | null = null;
    private noteOffJustSent = false;

    // Error tracking (process() hot path)
    private processErrorCount = 0;
    private allocationErrorCount = 0;

    /** Set by 'dispose': handles are gone, process() lets the node be collected. */
    private disposed = false;

    /** Params/engine messages received before the worklet reaches READY. */
    private pendingMessages: Array<{ type: string; data: any }> = [];

    constructor() {
        super();
        this.port.onmessage = this.handleMessage.bind(this);
    }

    private async handleMessage(event: MessageEvent) {
        const { type, data } = event.data;

        if (type === 'init-wasm') {
            await this.session.initialize(data, () => this.flushPendingMessages());
            return;
        }

        if (type === 'dispose') {
            // The hyphon_native instance is shared by every voice in this audio
            // session, so a dead node must hand its handles back explicitly —
            // they are no longer freed with a per-processor heap.
            this.disposed = true;
            this.pendingMessages = [];
            this.engineSelection.dispose();
            this.session.dispose();
            return;
        }

        if (!this.session.isReady) {
            if (typeof type === 'string' && Open303Processor.QUEUED_BEFORE_READY.has(type)) {
                this.pendingMessages.push({ type, data });
            }
            return;
        }

        this.dispatchMessage(type, data);
    }

    /** Configuration messages replayed once the worklet reaches READY. */
    private static readonly QUEUED_BEFORE_READY = new Set([
        'set-engine',
        'set-303-model',
        'param',
        'set-live-ab',
        'set-highfid-coeffs',
        'attach-highfid-coeff-table',
    ]);

    private dispatchMessage(type: string, data: any): void {
        if (type === 'noteOn') {
            this.handleNoteOn(data.note, data.velocity);
        } else if (type === 'noteOff') {
            this.handleNoteOff(data.note);
        } else if (type === 'set-engine') {
            this.engineSelection.setEngine(data.engine as EngineFamily);
        } else if (type === 'set-303-model') {
            this.engineSelection.setModel(
                data.model as string,
                data.engine as EngineFamily | undefined,
                data.oversample as number | undefined,
            );
        } else if (type === 'param') {
            this.handleParam(data);
        } else if (type === 'set-live-ab' || type === 'set-highfid-coeffs' || type === 'attach-highfid-coeff-table') {
            this.handleLiveHighFidMessage(type, data as LiveHighFidMessageData | undefined);
        }
    }

    private handleLiveHighFidMessage(type: string, data: LiveHighFidMessageData | undefined): void {
        if (type === 'set-live-ab') {
            const wasShadowing = this.engineSelection.abActive;
            this.engineSelection.setLiveAb(data?.armed === true);
            // Side A stops rendering: don't leave its notes hanging for the next arm.
            if (wasShadowing && !this.engineSelection.abActive) this.stockAllNotesOff();
        } else if (type === 'set-highfid-coeffs') {
            this.engineSelection.setHighFidCoefficients(data?.coefficients ?? null);
        } else {
            this.engineSelection.attachCoefficientTable(data?.buffer);
        }
    }

    // ── Live A/B stock side (Phase L2) ────────────────────────────────────────
    // While A/B is active the custom open303 instance shadows the live high-fid
    // voice note for note, so both sides hear one MIDI stream.

    private get stockExports(): StockSideExports {
        return this.session.getExports() as StockSideExports;
    }

    private get stockHandle(): number | bigint {
        return this.session.toWasmHandle(this.session.instanceHandle);
    }

    private stockNoteOn(note: number, velocity: number): void {
        if (!this.engineSelection.abActive || !this.session.isNativeApi) return;
        this.stockExports.open303_note_on(this.stockHandle, note, velocity);
    }

    private stockNoteOff(note: number): void {
        if (!this.engineSelection.abActive || !this.session.isNativeApi) return;
        this.stockExports.open303_note_off(this.stockHandle, note);
    }

    private stockAllNotesOff(): void {
        if (!this.session.isInstantiated || !this.session.isNativeApi) return;
        try {
            this.stockExports.open303_all_notes_off(this.stockHandle);
        } catch (e) {
            console.error('[Open303] A/B stock all-notes-off failed:', e);
        }
    }

    private handleParam(data: { func: string; value: number; audioTime?: number }): void {
        const audioTime = data.audioTime ?? 0;

        // Immediate? (currentTime must be accessed on global scope in audio worklets, but TS types define it via currentTime. Actually, AudioWorkletGlobalScope exposes currentTime directly.)
        if (typeof currentTime !== 'undefined' && audioTime <= currentTime) {
            this.applyParamMessage(this.session.getExports(), data);
            return;
        }

        // Schedule
        this.parameterQueue.schedule({ func: data.func, value: data.value, audioTime });
    }

    private applyParamMessage(exports: Record<string, any>, data: { func: string; value: number }): void {
        if (this.session.isNativeApi) {
            const paramId = JC303_PARAM_MAP[data.func as string];
            if (paramId !== undefined) {
                // The live high-fid voice mirrors Open303Param ids, so the same
                // message keeps working. Params go to it whenever it exists,
                // and the custom open303 instance keeps receiving them too, so
                // a CPU-gate step-down lands on an already-in-sync stock voice.
                this.engineSelection.liveHighFid?.setParam(paramId, data.value);
                if (this.engineSelection.activeEngine === 'jc303' && this.session.hasJc303MultiApi && exports.jc303_set_param) {
                    exports.jc303_set_param(this.session.toWasmHandle(this.session.jc303Handle), paramId, data.value);
                } else if (exports.open303_set_param) {
                    exports.open303_set_param(this.session.toWasmHandle(this.session.instanceHandle), paramId, data.value);
                }
            }
        } else if (exports[data.func]) {
            exports[data.func](data.value);
        }
    }

    private flushPendingMessages(): void {
        const queue = this.pendingMessages;
        this.pendingMessages = [];
        for (const msg of queue) {
            this.dispatchMessage(msg.type, msg.data);
        }
    }

    private handleNoteOn(note: number, velocity: number): void {
        const now = getTime();

        // Rate limit check
        let keepCount = 0;
        for (let i = 0; i < this.noteOnTimes.length; i++) {
            if (now - this.noteOnTimes[i] < 1000) {
                this.noteOnTimes[keepCount++] = this.noteOnTimes[i];
            }
        }
        this.noteOnTimes.length = keepCount;
        if (this.noteOnTimes.length >= Open303Processor.MAX_NOTES_PER_SECOND) {
            console.warn(`[Open303] Rate limit exceeded, dropping note ${note}`);
            return;
        }

        const timeSinceLastNote = now - this.lastNoteOnTime;
        if (timeSinceLastNote < Open303Processor.MIN_NOTE_INTERVAL_MS) {
            console.warn(`[Open303] Note ${note} too soon (${timeSinceLastNote.toFixed(1)}ms), dropping`);
            return;
        }

        // Portamento fix
        if (this.noteOffJustSent || this.activeNoteCount > 0) {
            if (this.activeNoteCount > 0) {
                this.clearAllNotes();
            }
            this.pendingNote = { note, velocity };
            this.noteOffJustSent = true;
            return;
        }

        this.triggerNoteOn(note, velocity);
    }

    private handleNoteOff(note: number): void {
        if (!this.session.isInstantiated) return;
        const exports = this.session.getExports();

        try {
            if (this.engineSelection.activeEngine === 'highfid' && this.engineSelection.liveHighFid) {
                this.stockNoteOff(note);
                this.engineSelection.liveHighFid.noteOff(note);
            } else if (this.engineSelection.activeEngine === 'jc303' && this.session.hasJc303MultiApi) {
                exports.jc303_note_off(this.session.toWasmHandle(this.session.jc303Handle), note);
            } else if (this.session.isNativeApi) {
                exports.open303_note_off(this.session.toWasmHandle(this.session.instanceHandle), note);
            } else {
                exports.jc303_noteOff(note);
            }
            if (note >= 0 && note < 128 && this.activeNotes[note] !== 0) {
                this.activeNotes[note] = 0;
                this.activeNoteCount = Math.max(0, this.activeNoteCount - 1);
            }
            this.noteOffJustSent = true;
        } catch (e) {
            console.error('[Open303] noteOff failed:', e);
        }
    }

    private clearAllNotes(): void {
        if (!this.session.isInstantiated) return;
        const exports = this.session.getExports();

        try {
            if (this.engineSelection.activeEngine === 'highfid' && this.engineSelection.liveHighFid) {
                if (this.engineSelection.abActive) this.stockAllNotesOff();
                this.engineSelection.liveHighFid.allNotesOff();
            } else if (this.engineSelection.activeEngine === 'jc303' && this.session.hasJc303MultiApi) {
                exports.jc303_all_notes_off(this.session.toWasmHandle(this.session.jc303Handle));
            } else if (this.session.isNativeApi) {
                exports.open303_all_notes_off(this.session.toWasmHandle(this.session.instanceHandle));
            } else if (exports.jc303_allNotesOff) {
                exports.jc303_allNotesOff();
            } else {
                for (let note = 0; note < 128; note++) {
                    if (this.activeNotes[note] !== 0) {
                        exports.jc303_noteOff(note);
                    }
                }
            }
        } catch (e) {
            console.error('[Open303] clearAllNotes failed:', e);
        }
        this.activeNotes.fill(0);
        this.activeNoteCount = 0;
    }

    private triggerNoteOn(note: number, velocity: number): void {
        if (!this.session.isInstantiated) return;
        const exports = this.session.getExports();

        try {
            if (this.engineSelection.activeEngine === 'highfid' && this.engineSelection.liveHighFid) {
                this.stockNoteOn(note, velocity);
                this.engineSelection.liveHighFid.noteOn(note, velocity);
            } else if (this.engineSelection.activeEngine === 'jc303' && this.session.hasJc303MultiApi) {
                exports.jc303_note_on(this.session.toWasmHandle(this.session.jc303Handle), note, velocity);
            } else if (this.session.isNativeApi) {
                exports.open303_note_on(this.session.toWasmHandle(this.session.instanceHandle), note, velocity);
            } else {
                exports.jc303_noteOn(note, velocity);
            }
            const now = getTime();
            this.lastNoteOnTime = now;
            this.noteOnTimes.push(now);
            if (note >= 0 && note < 128 && this.activeNotes[note] === 0) {
                this.activeNotes[note] = now || 0.1; // Ensure non-zero
                this.activeNoteCount++;
            } else if (note >= 0 && note < 128) {
                this.activeNotes[note] = now || 0.1;
            }
        } catch (e: any) {
            console.error(`[Open303] noteOn failed:`, e);
        }
    }

    process(_inputs: Float32Array[][], outputs: Float32Array[][], _parameters: Record<string, Float32Array>): boolean {
        if (this.disposed) return false;
        const output = outputs[0];
        if (!output) return true;

        const channelL = output[0];
        const blockFrames = channelL ? channelL.length : 128;
        this.perf.beginProcess(blockFrames);
        try {
        const channelR = output[1];

        // Drain pending parameters
        if (this.parameterQueue.length > 0 && typeof currentTime !== 'undefined') {
            this.parameterQueue.drain(currentTime, this.session.getExports());
        }

        // Handle pending note (portamento fix)
        if (this.pendingNote && this.session.state === SynthState.READY) {
            this.triggerNoteOn(this.pendingNote.note, this.pendingNote.velocity);
            this.pendingNote = null;
            this.noteOffJustSent = false;
        }

        // Output silence if not ready
        if (!this.session.isReady || !this.session.heapFloat32) {
            if (channelL) channelL.fill(0);
            if (channelR) channelR.fill(0);
            return true;
        }

        try {
            const exports = this.session.getExports();
            const numFrames = channelL ? channelL.length : 128;
            const gain = Open303Processor.OUTPUT_GAIN;

            if (this.engineSelection.activeEngine === 'highfid' && this.engineSelection.liveHighFid?.isReady) {
                // ── Live diode-ladder high-fid voice (Phase L1) ──────────────
                if (this.session.isInvalidHandle(this.session.nativeOutputPtr)) {
                    if (channelL) channelL.fill(0);
                    if (channelR) channelR.fill(0);
                    return true;
                }

                // L3: pick up knob moves from the shared coefficient table.
                this.engineSelection.pollCoefficientTable();

                const quantumUs = (numFrames / this.session.sampleRateHz) * 1_000_000;
                const busB = outputs[1];
                if (this.engineSelection.abActive && busB) {
                    // ── Live A/B (Phase L2): stock → output 0, high-fid → output 1 ──
                    // One scratch buffer, rendered and copied out twice.
                    const tStock = getTime();
                    this.stockExports.open303_process(
                        this.stockHandle,
                        this.session.toWasmHandle(this.session.nativeOutputPtr),
                        numFrames,
                    );
                    const stockUs = (getTime() - tStock) * 1000;
                    if (!this.copyNativeOutput(numFrames, channelL, channelR, gain)) return true;

                    const tHigh = getTime();
                    this.engineSelection.liveHighFid.process(this.session.nativeOutputPtr, numFrames);
                    const renderUs = (getTime() - tHigh) * 1000;
                    if (!this.copyNativeOutput(numFrames, busB[0], busB[1], gain)) return true;

                    // Only the high-fid time feeds the gate — it can only trip side B.
                    this.engineSelection.recordAbTiming(stockUs, renderUs, quantumUs);
                } else {
                    const t0 = getTime();
                    this.engineSelection.liveHighFid.process(this.session.nativeOutputPtr, numFrames);
                    const renderUs = (getTime() - t0) * 1000;
                    if (!this.copyNativeOutput(numFrames, channelL, channelR, gain)) return true;

                    // CPU meter / glitch gate — degrade to stock rather than glitch.
                    this.engineSelection.recordHighFidTiming(renderUs, quantumUs);
                }
            } else if (this.engineSelection.activeEngine === 'jc303' && this.session.hasJc303MultiApi) {
                // ── Authentic rosic::Open303 multi-instance API ───────────────
                const ptr = exports.jc303_process_handle(
                    this.session.toWasmHandle(this.session.jc303Handle),
                    numFrames,
                );
                const floatOffset = this.session.getWasmSampleOffset(ptr, numFrames);
                if (floatOffset < 0) {
                    if (this.allocationErrorCount++ < 5) {
                        console.error('[Open303] jc303_process_handle returned invalid pointer');
                    }
                    if (channelL) channelL.fill(0);
                    if (channelR) channelR.fill(0);
                    return true;
                }
                this.session.writeOutputSamples(floatOffset, numFrames, channelL, channelR, gain);
            } else if (this.session.isNativeApi) {
                // ── Custom open303 multi-instance API ────────────────────────
                if (this.session.isInvalidHandle(this.session.nativeOutputPtr)) {
                    if (channelL) channelL.fill(0);
                    if (channelR) channelR.fill(0);
                    return true;
                }

                exports.open303_process(
                    this.session.toWasmHandle(this.session.instanceHandle),
                    this.session.toWasmHandle(this.session.nativeOutputPtr),
                    numFrames,
                );

                const floatOffset = this.session.getWasmSampleOffset(this.session.nativeOutputPtr, numFrames);
                if (floatOffset < 0) {
                    if (this.processErrorCount++ < 5) {
                        console.error('[Open303] open303_process output buffer unreadable');
                    }
                    if (channelL) channelL.fill(0);
                    if (channelR) channelR.fill(0);
                    return true;
                }
                this.session.writeOutputSamples(floatOffset, numFrames, channelL, channelR, gain);
            } else {
                // ── Legacy jc303_* API ───────────────────────────────────────
                const ptr = exports.jc303_process(numFrames);

                if (this.session.wasmPtrToOffset(ptr) < 0) {
                    if (this.allocationErrorCount++ < 5) {
                        console.error('[Open303] jc303_process returned invalid pointer');
                    }
                    if (channelL) channelL.fill(0);
                    if (channelR) channelR.fill(0);
                    return true;
                }

                const floatOffset = this.session.getWasmSampleOffset(ptr, numFrames);
                if (floatOffset < 0) {
                    if (this.processErrorCount++ < 5) {
                        console.error('[Open303] jc303_process buffer unreadable');
                    }
                    if (channelL) channelL.fill(0);
                    if (channelR) channelR.fill(0);
                    return true;
                }
                this.session.writeOutputSamples(floatOffset, numFrames, channelL, channelR, gain);

                if (exports.free) {
                    exports.free(ptr);
                }
            }

            // A/B still armed but side B is gone (CPU gate): mirror stock onto
            // bus B until the main thread collapses the blend to side A, so a
            // blend parked at high-fid never drops to silence.
            const busB = outputs[1];
            if (busB && this.engineSelection.isAbArmed && !this.engineSelection.abActive) {
                if (busB[0] && channelL) busB[0].set(channelL);
                if (busB[1] && channelR) busB[1].set(channelR);
            }

            // Stuck note detection (common to both APIs)
            this.checkStuckNotes(exports);

        } catch (e: any) {
            if (this.processErrorCount++ < 5) {
                console.error('[Open303] Process error:', e);
            }
            if (channelL) channelL.fill(0);
            if (channelR) channelR.fill(0);
        }

        return true;
        } finally {
            this.perf.endProcess();
        }
    }

    /** Copy the shared native scratch buffer to a stereo pair; false (and silence) if unreadable. */
    private copyNativeOutput(
        numFrames: number,
        left: Float32Array | undefined,
        right: Float32Array | undefined,
        gain: number,
    ): boolean {
        const floatOffset = this.session.getWasmSampleOffset(this.session.nativeOutputPtr, numFrames);
        if (floatOffset < 0) {
            if (this.processErrorCount++ < 5) {
                console.error('[Open303] live high-fid output buffer unreadable');
            }
            if (left) left.fill(0);
            if (right) right.fill(0);
            return false;
        }
        this.session.writeOutputSamples(floatOffset, numFrames, left, right, gain);
        return true;
    }

    private checkStuckNotes(exports: any): void {
        if (this.activeNoteCount === 0) return;
        const now = getTime();
        for (let note = 0; note < 128; note++) {
            const startTime = this.activeNotes[note];
            if (startTime !== 0) {
                const duration = now - startTime;
                if (duration > Open303Processor.MAX_NOTE_DURATION_MS) {
                    if (this.stuckNoteWarnings++ < 5) {
                        console.warn(`[Open303] Stuck note detected: ${note} held for ${duration.toFixed(0)}ms, auto-releasing`);
                    }
                    try {
                        if (this.engineSelection.activeEngine === 'highfid' && this.engineSelection.liveHighFid) {
                            this.stockNoteOff(note);
                            this.engineSelection.liveHighFid.noteOff(note);
                        } else if (this.engineSelection.activeEngine === 'jc303' && this.session.hasJc303MultiApi) {
                            exports.jc303_note_off(this.session.jc303Handle, note);
                        } else if (this.session.isNativeApi) {
                            exports.open303_note_off(this.session.instanceHandle, note);
                        } else {
                            exports.jc303_noteOff(note);
                        }
                    } catch { }
                    this.activeNotes[note] = 0;
                    this.activeNoteCount = Math.max(0, this.activeNoteCount - 1);
                }
            }
        }
    }
}

registerProcessor('open303-processor', Open303Processor);

// src/audio-worklets/open303/engineSelection.ts
// Which DSP engine (open303 / jc303 / live high-fid) is currently active for a
// processor instance, and the model-registry + live high-fid lifecycle that
// decides it. Delegates all WASM instance/handle access to Open303EngineSession.

import {
    LIVE_HIGHFID_MODEL_ID,
    LiveHighFid303Voice,
    LiveHighFidGuard,
    clampLiveOversample,
    supportsLiveHighFid,
    type LiveHighFidOversample,
} from '../liveHighFid303';
import {
    CANONICAL_HIGHFID_COEFFICIENTS,
    HIGHFID_COEFFICIENT_KEYS,
    HIGHFID_COEFFICIENT_PARAM_IDS,
    HighFidCoefficientTable,
    normalizeHighFidCoefficients,
    type HighFidCoefficients,
} from '../liveHighFidCoefficients';
import type { Open303EngineSession } from './engineSession';
import type { EngineFamily } from './shared';

/** Blocks between `live-ab-cpu` reports (~250 ms at 128 frames / 48 kHz). */
const AB_CPU_REPORT_BLOCKS = 94;
const AB_CPU_EMA_ALPHA = 0.2;

export class Open303EngineSelection {
    private engine: EngineFamily = 'open303';
    private model: string = 'stock-open303';

    /** Live high-fid voice — created lazily, only when a track selects it. */
    private highFid: LiveHighFid303Voice | null = null;
    private readonly highFidGuard = new LiveHighFidGuard();
    private highFidOversample: LiveHighFidOversample = 1;
    /** Set once the CPU/glitch gate has stepped this processor down to stock. */
    private highFidDegraded = false;

    /**
     * Live A/B (Phase L2): the custom open303 instance plays stock Open303 on
     * output 0 while the live diode ladder plays on output 1, from the same
     * note stream. Armed by the main thread only for a part on `live-highfid`.
     */
    private abArmed = false;
    private abStockCpuEma = 0;
    private abBlocks = 0;

    /** Diode-ladder coefficients (Phase L3) — canonical until the song says otherwise. */
    private coefficients: HighFidCoefficients = { ...CANONICAL_HIGHFID_COEFFICIENTS };
    /** UI-written table, polled once per high-fid block (crossOriginIsolated only). */
    private coefficientTable: HighFidCoefficientTable | null = null;

    private readonly session: Open303EngineSession;
    private readonly port: MessagePort;
    private readonly clearAllNotes: () => void;

    constructor(
        session: Open303EngineSession,
        port: MessagePort,
        clearAllNotes: () => void,
    ) {
        this.session = session;
        this.port = port;
        this.clearAllNotes = clearAllNotes;
    }

    get activeEngine(): EngineFamily {
        return this.engine;
    }

    get activeModel(): string {
        return this.model;
    }

    get liveHighFid(): LiveHighFid303Voice | null {
        return this.highFid;
    }

    /** A/B requested by the main thread (may outlive a CPU-gate step-down). */
    get isAbArmed(): boolean {
        return this.abArmed;
    }

    /** Both sides are audible: stock on output 0, live high-fid on output 1. */
    get abActive(): boolean {
        return this.abArmed && this.engine === 'highfid' && this.highFid?.isReady === true;
    }

    get highFidCoefficients(): HighFidCoefficients {
        return this.coefficients;
    }

    /** Switch the active DSP engine for this processor instance.
     *  Clears any held notes before switching to avoid stuck notes. */
    setEngine(engine: EngineFamily): void {
        if (engine === this.engine) return;

        if (engine === 'jc303' && !this.session.hasJc303MultiApi) {
            console.warn('[Open303] Authentic JC303 engine not available — ignoring set-engine request');
            return;
        }

        if (engine === 'highfid' && !this.ensureLiveHighFid()) {
            console.warn('[Open303] Live high-fid engine unavailable — ignoring set-engine request');
            return;
        }

        // Release any held notes on the current engine before switching
        this.clearAllNotes();

        this.engine = engine;
        console.log(`[Open303] Engine switched to: ${engine}`);
        this.port.postMessage({ type: 'engine-changed', data: { engine } });
    }

    /** Select the active 303 voice/model. Resolves the engine family from the
     *  native registry when available, otherwise trusts the fallbackEngine hint
     *  sent by Open303Oscillator (mirrored TS registry). */
    setModel(
        model: string,
        fallbackEngine?: EngineFamily,
        oversample?: number,
    ): void {
        const entry = this.session.modelRegistry?.get(model);
        const isLiveHighFid = model === LIVE_HIGHFID_MODEL_ID || fallbackEngine === 'highfid';
        const engine: EngineFamily = isLiveHighFid ? 'highfid' : entry?.engine ?? fallbackEngine ?? 'open303';

        if (engine === 'jc303' && !this.session.hasJc303MultiApi) {
            console.warn(`[Open303] Model "${model}" needs the JC303 engine which is unavailable — ignoring`);
            return;
        }

        if (engine === 'highfid') {
            if (oversample !== undefined) {
                this.highFidOversample = clampLiveOversample(oversample);
                this.highFid?.setOversample(this.highFidOversample);
            }
            // A previous CPU-gate step-down stays in force for the session:
            // re-arming it automatically would just glitch again.
            if (this.highFidDegraded) {
                console.warn('[Open303] Live high-fid stays disabled (CPU gate tripped this session)');
                this.reportLiveHighFidUnavailable(model, 'CPU gate tripped earlier this session');
                return;
            }
            if (!this.ensureLiveHighFid()) {
                this.reportLiveHighFidUnavailable(model, 'highfid303_* exports missing from this WASM build');
                return;
            }
        }

        const exports = this.session.getExports();

        // Apply the coefficient profile to the custom open303 instance.
        if (entry && engine === 'open303' && this.session.isNativeApi &&
            typeof exports.open303_set_model === 'function') {
            try {
                exports.open303_set_model(this.session.toWasmHandle(this.session.instanceHandle), entry.index);
            } catch (e) {
                console.warn(`[Open303] open303_set_model("${model}") failed:`, e);
            }
        }

        if (engine !== this.engine) {
            // Release any held notes on the current engine before switching
            this.clearAllNotes();
            this.engine = engine;
        }

        this.model = model;
        this.syncAbStockProfile();
        console.log(`[Open303] 303 model set to: ${model} (engine=${engine}, native=${entry !== undefined})`);
        this.port.postMessage({ type: 'model-changed', data: { model, engine } });
    }

    // ── Live high-fid (Phase L1) ─────────────────────────────────────────────

    /** Create the live diode-ladder voice on first use. Idempotent. */
    private ensureLiveHighFid(): boolean {
        if (this.highFid?.isReady) return true;
        if (this.highFidDegraded) return false;
        if (!this.session.isNativeApi || this.session.isInvalidHandle(this.session.nativeOutputPtr)) return false;

        const exports = this.session.getExports();
        if (!supportsLiveHighFid(exports)) {
            console.log('[Open303] Live high-fid engine not available in this WASM build');
            return false;
        }

        const voice = new LiveHighFid303Voice(exports, (h) => this.session.toWasmHandle(h));
        if (!voice.init(this.session.sampleRateHz, this.session.nativeBufFrames, this.highFidOversample)) {
            console.warn('[Open303] Live high-fid init failed');
            return false;
        }

        this.highFid = voice;
        this.highFidGuard.reset();
        this.pollCoefficientTable();
        this.applyCoefficients();
        console.log(`[Open303] Live high-fid voice ready (oversample=${voice.activeOversample}×)`);
        return true;
    }

    // ── Live A/B (Phase L2) ──────────────────────────────────────────────────

    /**
     * Arm / disarm A/B. Arming allocates nothing: the diode ladder already
     * exists (the part selected `live-highfid`) and the stock side is the
     * processor's own open303 instance, so stock-only sessions stay free.
     */
    setLiveAb(armed: boolean): void {
        if (armed === this.abArmed) return;
        this.abArmed = armed;
        this.abStockCpuEma = 0;
        this.abBlocks = 0;
        this.syncAbStockProfile();
        this.port.postMessage({ type: 'live-ab-changed', data: { armed } });
    }

    /** Side A is Stock Open303 — whatever profile the instance carried before. */
    private syncAbStockProfile(): void {
        if (this.abActive) this.applyStockProfile();
    }

    private applyStockProfile(): void {
        const stockEntry = this.session.modelRegistry?.get('stock-open303');
        const exports = this.session.getExports();
        if (stockEntry && this.session.isNativeApi && typeof exports.open303_set_model === 'function') {
            try {
                exports.open303_set_model(this.session.toWasmHandle(this.session.instanceHandle), stockEntry.index);
            } catch (e) {
                console.warn('[Open303] Applying the stock profile failed:', e);
            }
        }
    }

    /**
     * Per-side timing for one A/B block. The high-fid time alone still feeds
     * the CPU/glitch gate, so the gate can only ever trip side B.
     */
    recordAbTiming(stockUs: number, highFidUs: number, quantumUs: number): void {
        if (quantumUs > 0 && Number.isFinite(stockUs)) {
            const percent = Math.min(400, (stockUs / quantumUs) * 100);
            this.abStockCpuEma = this.abBlocks === 0
                ? percent
                : this.abStockCpuEma + AB_CPU_EMA_ALPHA * (percent - this.abStockCpuEma);
        }
        this.abBlocks += 1;
        if (this.abBlocks % AB_CPU_REPORT_BLOCKS === 0) {
            this.port.postMessage({
                type: 'live-ab-cpu',
                data: { stockPercent: this.abStockCpuEma, highFidPercent: this.highFidGuard.cpuPercent },
            });
        }
        this.recordHighFidTiming(highFidUs, quantumUs);
    }

    // ── Diode-ladder coefficients (Phase L3) ─────────────────────────────────

    /** `postMessage` path: `values` is a coefficient object, `null` = canonical. */
    setHighFidCoefficients(values: unknown): void {
        this.coefficients = normalizeHighFidCoefficients(values) ?? { ...CANONICAL_HIGHFID_COEFFICIENTS };
        this.applyCoefficients();
    }

    /** SharedArrayBuffer path: the UI morphs the table, the worklet polls it. */
    attachCoefficientTable(buffer: unknown): void {
        if (typeof SharedArrayBuffer === 'undefined' || !(buffer instanceof SharedArrayBuffer)) return;
        try {
            this.coefficientTable = new HighFidCoefficientTable(buffer);
        } catch (e) {
            console.warn('[Open303] High-fid coefficient table rejected:', e);
            return;
        }
        this.pollCoefficientTable();
    }

    /** One Atomics.load per high-fid block; applies only when the UI published. */
    pollCoefficientTable(): void {
        const next = this.coefficientTable?.readIfChanged();
        if (!next) return;
        this.coefficients = next;
        this.applyCoefficients();
    }

    /** Push the current coefficients into the live voice. Old WASM builds ignore the ids. */
    private applyCoefficients(): void {
        const voice = this.highFid;
        if (!voice?.isReady) return;
        for (const key of HIGHFID_COEFFICIENT_KEYS) {
            voice.setParam(HIGHFID_COEFFICIENT_PARAM_IDS[key], this.coefficients[key]);
        }
    }

    /** Destroy the live high-fid handle (processor teardown). */
    dispose(): void {
        this.highFid?.destroy();
        this.highFid = null;
        this.engine = 'open303';
        this.abArmed = false;
        this.coefficientTable = null;
    }

    /** Tell the main thread the requested live high-fid voice cannot be used. */
    private reportLiveHighFidUnavailable(model: string, reason: string): void {
        this.port.postMessage({
            type: 'live-highfid-unavailable',
            data: { model, reason, fallbackModel: 'stock-open303' },
        });
    }

    /** Feed one block's high-fid render timing to the CPU/glitch gate, and
     *  degrade to stock if it trips. Called once per block from process(). */
    recordHighFidTiming(renderUs: number, quantumUs: number): void {
        const verdict = this.highFidGuard.record(renderUs, quantumUs);
        if (verdict.degrade && verdict.reason) {
            this.degradeLiveHighFid(verdict.reason, verdict.cpuPercent, verdict.underruns);
        }
    }

    /**
     * CPU/glitch gate tripped — step down to the stock voice for the rest of
     * the session and tell the main thread which path is now audible.
     */
    private degradeLiveHighFid(reason: string, cpuPercent: number, underruns: number): void {
        const wasAb = this.abActive;
        this.highFidDegraded = true;
        if (wasAb) {
            // A/B: side A is already stock and already sounding — leave its
            // notes and profile alone, only silence side B.
            this.highFid?.allNotesOff();
        } else {
            this.clearAllNotes();
        }
        this.highFid?.destroy();
        this.highFid = null;
        this.engine = 'open303';
        this.model = 'stock-open303';
        // The custom open303 instance may still carry whatever coefficient
        // profile was selected before the high-fid voice — put it back on stock.
        if (!wasAb) this.applyStockProfile();
        console.warn(`[Open303] Live high-fid degraded to stock: ${reason}`);
        this.port.postMessage({
            type: 'live-highfid-degraded',
            data: { reason, cpuPercent, underruns, fallbackModel: 'stock-open303', ab: wasAb },
        });
        this.port.postMessage({
            type: 'model-changed',
            data: { model: 'stock-open303', engine: 'open303' },
        });
    }
}

// src/audio-worklets/open303/engineSession.ts
// The native/jc303 instance handles for one Open303Processor, on the audio
// session's shared hyphon_native.wasm instance (see ../hyphonNativeSession.ts):
// resolving which native API(s) the module exposes, the heap view used to read
// rendered samples back out, and handle teardown. Everything here either runs
// once at init or is called from the process() hot path — no allocation-adding
// indirection.

import { formatMissingWasmExports } from '../hyphonNativeImports';
import { acquireHyphonNativeSession, type HyphonNativeSession } from '../hyphonNativeSession';
import { resolveWorkletSampleRate } from '../../utils/workletSampleRate';
import { SynthState, type SynthStateType, getTime } from './shared';

export class Open303EngineSession {
    /** Shared per-audio-session instance; this processor only owns handles on it. */
    private native: HyphonNativeSession | null = null;
    private detachHeapListener: (() => void) | null = null;
    private disposed = false;
    private heap: Float32Array | null = null;
    private synthState: SynthStateType = SynthState.UNINITIALIZED;
    private isThreadedFlag: boolean = false;

    // When true the WASM exposes the open303_* instance-based API
    // (hyphon_native.wasm with open303_wrapper.cpp).  When false the legacy
    // jc303_* single-instance API is used (standalone jc303-single.wasm).
    private nativeApi: boolean = false;
    private handle: number | bigint = 0;
    // Caller-allocated output buffer pointer (malloc'd once, freed on cleanup)
    private outputPtr: number | bigint = 0;
    private readonly bufFrames: number = 128;

    // Authentic rosic::Open303 multi-instance API (jc303_wrapper.cpp).
    // Available alongside the custom open303_* API in hyphon_native.wasm.
    private jc303MultiApi: boolean = false;
    private jc303HandleValue: number | bigint = 0;

    private rateHz: number = 44100;

    /** Native 303 model registry (open303_get_model_* exports), discovered at
     *  init. null = the loaded WASM predates the voices architecture; model
     *  selection then degrades to plain engine-family switching. */
    private registry: Map<string, { index: number; engine: 'open303' | 'jc303' }> | null = null;

    // Error tracking
    private initAttempts = 0;
    private static readonly MAX_INIT_ATTEMPTS = 3;
    private lastErrorMessage: string = '';

    private readonly port: MessagePort;

    constructor(port: MessagePort) {
        this.port = port;
    }

    get state(): SynthStateType {
        return this.synthState;
    }

    /** True once the WASM module has instantiated successfully and the synth is live. */
    get isReady(): boolean {
        return this.synthState === SynthState.READY && this.native !== null;
    }

    get isInstantiated(): boolean {
        return this.native !== null;
    }

    get heapFloat32(): Float32Array | null {
        return this.heap;
    }

    get isNativeApi(): boolean {
        return this.nativeApi;
    }

    get hasJc303MultiApi(): boolean {
        return this.jc303MultiApi;
    }

    get instanceHandle(): number | bigint {
        return this.handle;
    }

    get jc303Handle(): number | bigint {
        return this.jc303HandleValue;
    }

    get nativeOutputPtr(): number | bigint {
        return this.outputPtr;
    }

    get nativeBufFrames(): number {
        return this.bufFrames;
    }

    get modelRegistry(): Map<string, { index: number; engine: 'open303' | 'jc303' }> | null {
        return this.registry;
    }

    get sampleRateHz(): number {
        return this.rateHz;
    }

    getExports(): Record<string, any> {
        return this.native?.exports ?? {};
    }

    /**
     * Pass a handle back to WASM in the representation the module handed us.
     *
     * WASM_BIGINT only changes how i64 values cross the boundary. The
     * open303 and jc303 handles are plain i32 in this wasm32 build —
     * open303_create() returns a JS number — so coercing to BigInt made every
     * call throw "Cannot convert a BigInt value to a number" and the engine fell
     * back to the JS voice. Preserving the representation keeps a future
     * MEMORY64 build (where these come back as bigint) working too.
     */
    toWasmHandle(handle: number | bigint): number | bigint {
        return handle;
    }

    isInvalidHandle(handle: number | bigint | null | undefined): boolean {
        if (handle == null) return true;
        if (typeof handle === 'bigint') return handle <= 0n;
        return !Number.isFinite(handle) || handle <= 0;
    }

    /** Convert a WASM heap pointer (number or bigint) to a Float32Array index. */
    wasmPtrToOffset(ptr: number | bigint | null | undefined): number {
        if (ptr == null) return -1;
        const n = typeof ptr === 'bigint' ? Number(ptr) : ptr;
        if (!Number.isFinite(n) || n <= 0) return -1;
        return n >>> 2;
    }

    /** Ensures the heap view is up to date and returns the Float32 offset, or -1 if invalid. */
    getWasmSampleOffset(ptr: number | bigint, numFrames: number): number {
        this.updateHeap();
        if (!this.heap) return -1;

        const byteOffset = typeof ptr === 'bigint' ? Number(ptr) : ptr;
        if (!Number.isFinite(byteOffset) || byteOffset <= 0) return -1;
        if (byteOffset + numFrames * 4 > this.heap.buffer.byteLength) return -1;

        return byteOffset >>> 2;
    }

    writeOutputSamples(
        floatOffset: number,
        numFrames: number,
        channelL: Float32Array | undefined,
        channelR: Float32Array | undefined,
        gain: number,
    ): void {
        const heap = this.heap;
        if (!heap) return;

        for (let i = 0; i < numFrames; i++) {
            const sample = heap[floatOffset + i] * gain;
            if (channelL) channelL[i] = sample;
            if (channelR) channelR[i] = sample;
        }
    }

    updateHeap(): void {
        const memory = this.native?.memory;
        if (memory && (!this.heap || this.heap.buffer !== memory.buffer)) {
            this.heap = new Float32Array(memory.buffer);
        }
    }

    /** Read a null-terminated UTF-8 string from the WASM heap. */
    readWasmCString(ptr: number | bigint | null | undefined): string | null {
        const memory = this.native?.memory;
        const start = typeof ptr === 'bigint' ? Number(ptr) : ptr;
        if (!memory?.buffer || !start || !Number.isFinite(start) || start <= 0) return null;

        const bytes = new Uint8Array(memory.buffer);
        let end = start;
        const limit = Math.min(bytes.length, start + 256); // model ids are short
        while (end < limit && bytes[end] !== 0) end++;
        if (end === start) return null;

        let str = '';
        for (let i = start; i < end; i++) str += String.fromCharCode(bytes[i]);
        return str;
    }

    /** Compile + instantiate the WASM module, retrying up to MAX_INIT_ATTEMPTS times.
     *  Posts 'ready'/'error' on the worklet port itself; `onReady` lets the
     *  caller flush anything it queued while waiting for init to finish. */
    async initialize(data: any, onReady: () => void): Promise<void> {
        if (this.synthState === SynthState.INITIALIZING) {
            console.log('[Open303] Initialization already in progress');
            return;
        }

        this.synthState = SynthState.INITIALIZING;

        while (this.initAttempts < Open303EngineSession.MAX_INIT_ATTEMPTS && !this.disposed) {
            this.initAttempts++;
            console.log(`[Open303] Initialization attempt ${this.initAttempts}/${Open303EngineSession.MAX_INIT_ATTEMPTS}`);

            try {
                const success = await this.tryInitialize(data);
                if (this.disposed) {
                    // The node was torn down while the shared instance was coming up.
                    this.releaseHandles();
                    return;
                }
                if (success) {
                    this.synthState = SynthState.READY;
                    console.log('[Open303] WASM initialized successfully');
                    this.attachToSession();
                    onReady();
                    this.port.postMessage({ type: 'ready', heap: this.native?.stats });
                    return;
                }
            } catch (e) {
                this.releaseHandles();
                const errorMsg = e instanceof Error ? e.message : String(e);
                console.warn(`[Open303] Init attempt ${this.initAttempts} failed:`, errorMsg);
                this.lastErrorMessage = errorMsg;

                // Small delay before retry to let stack/heap settle
                // Note: AudioWorklet doesn't have setTimeout, so we use a simple spin wait
                if (this.initAttempts < Open303EngineSession.MAX_INIT_ATTEMPTS) {
                    const start = getTime();
                    while (getTime() - start < 100) { /* spin wait */ }
                }
            }
        }

        if (this.disposed) return;

        // All attempts failed
        console.error('[Open303] All initialization attempts failed');
        this.synthState = SynthState.FAILED;
        this.port.postMessage({
            type: 'error',
            error: `Failed to initialize after ${Open303EngineSession.MAX_INIT_ATTEMPTS} attempts. Last error: ${this.lastErrorMessage}`,
            recoverable: false
        });
    }

    private async tryInitialize(data: any): Promise<boolean> {
        const variant = data.variant || (data.isThreaded ? 'pthread' : 'st');
        this.isThreadedFlag = data.isThreaded || false;

        console.log(`[Open303] Initializing with ${variant} WASM variant (threaded: ${this.isThreadedFlag})`);

        // Compile, allocate the imported memory, instantiate and run the C++
        // constructors — once per audio session. Every 303 and Prophecy voice
        // after the first gets the already-live instance and just creates handles.
        this.native = await acquireHyphonNativeSession(
            {
                wasmBytes: data.wasmBytes,
                isThreaded: this.isThreadedFlag,
                // createHyphonMemory floors this per profile (pthread / st).
                memoryPages: data.memoryPages,
                exportMap: data.exportMap,
            },
            '[Open303]',
        );
        const rawExports = this.native.instance.exports;
        this.updateHeap();

        // 4. Verify exports — accept either the native multi-instance API
        // (open303_create/open303_init, exported by hyphon_native.wasm) or the
        // legacy single-instance jc303_init/jc303_process API.
        const exports = this.getExports();
        const hasNative = typeof exports.open303_create === 'function'
                       && typeof exports.open303_init === 'function';
        const hasLegacy = typeof exports.jc303_init_handle === 'function'
                       && typeof exports.jc303_process_handle === 'function';

        if (!hasNative && !hasLegacy) {
            throw new Error(
                `Missing required exports: neither open303_* (native) nor jc303_* (legacy) found. ` +
                formatMissingWasmExports(rawExports, [
                    'open303_create',
                    'open303_init',
                    'jc303_init_handle',
                    'jc303_process_handle',
                ]),
            );
        }

        // 5. Initialize the synth with stack protection
        return this.initializeSynth(
            exports,
            resolveWorkletSampleRate({
                sampleRate: data.sampleRate ?? (globalThis as { sampleRate?: number }).sampleRate,
            }),
        );
    }

    private initializeSynth(exports: any, sampleRate: number): boolean {
        this.rateHz = resolveWorkletSampleRate({ sampleRate });
        // Prefer the new multi-instance native API (hyphon_native with open303_wrapper.cpp).
        // Fall back to the single-instance jc303_* API (standalone jc303-single.wasm).
        if (typeof exports.open303_create === 'function' &&
            typeof exports.open303_init   === 'function') {
            return this.initializeNativeApi(exports, sampleRate);
        }
        return this.initializeLegacyApi(exports, sampleRate);
    }

    private initializeNativeApi(exports: any, sampleRate: number): boolean {
        console.log('[Open303] Using native multi-instance API (open303_*)');
        try {
            // Create instance
            this.handle = exports.open303_create();
            if (this.isInvalidHandle(this.handle)) {
                throw new Error('open303_create() returned null handle');
            }

            const result = exports.open303_init(
                this.toWasmHandle(this.handle),
                sampleRate,
                this.bufFrames,
            );
            if (result !== 1) {
                throw new Error(`open303_init() returned ${result}`);
            }

            // Allocate the output buffer on the WASM heap (owned by the worklet)
            const mallocFn = exports._malloc ?? exports.malloc;
            if (mallocFn) {
                // 4 bytes per sample (Float32)
                this.outputPtr = mallocFn(this.bufFrames * 4);
                if (this.isInvalidHandle(this.outputPtr)) {
                    throw new Error('Failed to allocate native output buffer');
                }
            }

            this.nativeApi = true;
            console.log(`[Open303] Native instance created: handle=${this.handle}`);

            // Also initialise the authentic rosic::Open303 multi-instance (jc303_*)
            // so that per-voice engine switching works without a full reinit.
            this.initializeJc303MultiInstance(exports, sampleRate);

            this.discoverModelRegistry(exports);

            return true;
        } catch (e) {
            console.error('[Open303] Native API init failed:', e);
            this.nativeApi = false;
            // Leave this.handle set: initialize()'s catch destroys it on the shared
            // instance. Zeroing it here would leak the open303 handle there.
            // Rethrow: initialize()'s retry loop records the message, and a bare
            // `return false` here is what produced "Failed to initialize after 3
            // attempts. Last error: " with nothing after the colon.
            throw e instanceof Error ? e : new Error(String(e));
        }
    }

    /** Initialise the authentic rosic::Open303 multi-instance handle alongside
     *  the custom open303 instance.  Failures are non-fatal — the custom engine
     *  remains the default and engine switching will simply be unavailable. */
    private initializeJc303MultiInstance(exports: any, sampleRate: number): void {
        if (typeof exports.jc303_create !== 'function' ||
            typeof exports.jc303_init_handle !== 'function') {
            console.log('[Open303] jc303 multi-instance API not available in this WASM build');
            return;
        }
        try {
            this.jc303HandleValue = exports.jc303_create();
            if (this.isInvalidHandle(this.jc303HandleValue)) {
                console.warn('[Open303] jc303_create() returned null handle');
                return;
            }
            const res = exports.jc303_init_handle(
                this.toWasmHandle(this.jc303HandleValue),
                sampleRate,
                this.bufFrames,
            );
            if (res !== 1) {
                console.warn(`[Open303] jc303_init_handle() returned ${res}`);
                if (exports.jc303_destroy) {
                    exports.jc303_destroy(this.toWasmHandle(this.jc303HandleValue));
                }
                this.jc303HandleValue = 0;
                return;
            }
            this.jc303MultiApi = true;
            console.log(`[Open303] Authentic JC303 instance ready: handle=${this.jc303HandleValue}`);
        } catch (e) {
            console.warn('[Open303] JC303 multi-instance init failed (engine unavailable):', e);
            this.jc303HandleValue = 0;
            this.jc303MultiApi = false;
        }
    }

    /** Discover the native 303 model registry (open303_get_model_* exports).
     *  Absent on WASM builds that predate the voices architecture — model
     *  selection then falls back to plain engine-family switching. */
    private discoverModelRegistry(exports: any): void {
        if (typeof exports.open303_get_model_count !== 'function' ||
            typeof exports.open303_get_model_id !== 'function' ||
            typeof exports.open303_get_model_engine !== 'function') {
            console.log('[Open303] Native 303 model registry not available in this WASM build');
            return;
        }
        try {
            const count = Number(exports.open303_get_model_count());
            if (!Number.isFinite(count) || count <= 0 || count > 64) return;

            const registry = new Map<string, { index: number; engine: 'open303' | 'jc303' }>();
            for (let i = 0; i < count; i++) {
                const id = this.readWasmCString(exports.open303_get_model_id(i));
                if (!id) continue;
                const engine = Number(exports.open303_get_model_engine(i)) === 1 ? 'jc303' : 'open303';
                registry.set(id, { index: i, engine });
            }
            if (registry.size > 0) {
                this.registry = registry;
                console.log(`[Open303] Native 303 model registry: ${[...registry.keys()].join(', ')}`);
            }
        } catch (e) {
            console.warn('[Open303] Failed to read native 303 model registry:', e);
            this.registry = null;
        }
    }

    private initializeLegacyApi(exports: any, sampleRate: number): boolean {
        // Try with progressively smaller buffer sizes to reduce stack pressure
        const bufferSizes = [128, 64, 32, 16];

        for (const bufferSize of bufferSizes) {
            try {
                console.log(`[Open303] Attempting jc303_init with bufferSize=${bufferSize}...`);
                const result = exports.jc303_init(sampleRate, bufferSize);

                if (result === 1) {
                    console.log(`[Open303] Legacy API initialized with sampleRate=${sampleRate}, bufferSize=${bufferSize}`);
                    return true;
                } else {
                    console.warn(`[Open303] jc303_init returned ${result} with bufferSize=${bufferSize}`);
                }
            } catch (initError) {
                console.warn(`[Open303] init failed with bufferSize=${bufferSize}:`, initError);
            }
        }

        return false;
    }

    /** Subscribe to heap growth so the HUD sees grow events from the shared heap. */
    private attachToSession(): void {
        if (!this.native || this.detachHeapListener) return;
        this.native.retain();
        const unsubscribe = this.native.onHeapGrow((stats) => {
            this.updateHeap();
            this.port.postMessage({ type: 'hyphon-heap', data: stats });
        });
        const native = this.native;
        this.detachHeapListener = () => {
            unsubscribe();
            native.release();
        };
    }

    /** Destroy this processor's handles on the shared instance. The instance
     *  itself outlives the processor — other voices are still using it. */
    private releaseHandles(): void {
        const exports = this.getExports();
        try {
            if (!this.isInvalidHandle(this.handle)) exports.open303_destroy?.(this.toWasmHandle(this.handle));
            if (!this.isInvalidHandle(this.jc303HandleValue)) exports.jc303_destroy?.(this.toWasmHandle(this.jc303HandleValue));
            if (!this.isInvalidHandle(this.outputPtr)) (exports._free ?? exports.free)?.(this.outputPtr);
        } catch (e) {
            console.warn('[Open303] Handle teardown failed:', e);
        }
        this.handle = 0;
        this.jc303HandleValue = 0;
        this.outputPtr = 0;
        this.nativeApi = false;
        this.jc303MultiApi = false;
    }

    /** Tear down for good: free handles and detach from the shared session. */
    dispose(): void {
        if (this.disposed) return;
        this.disposed = true;
        this.releaseHandles();
        this.detachHeapListener?.();
        this.detachHeapListener = null;
        this.synthState = SynthState.FAILED;
        this.heap = null;
    }
}

// src/audio-worklets/open303/parameterQueue.ts

export interface ScheduledParam {
    func: string;
    value: number;
    audioTime: number;
}

/**
 * Time-ordered queue of parameter changes waiting for their scheduled
 * audioTime. `drain` runs once per audio block on the real-time thread, so it
 * shifts its backing array in place instead of using Array.shift()/splice()
 * (see #1206 — O(N) shift() per parameter was degrading the audio budget).
 */
export class ParameterQueue {
    private readonly pending: ScheduledParam[] = [];
    private readonly applyOne: (exports: Record<string, any>, entry: ScheduledParam) => void;

    constructor(applyOne: (exports: Record<string, any>, entry: ScheduledParam) => void) {
        this.applyOne = applyOne;
    }

    get length(): number {
        return this.pending.length;
    }

    schedule(entry: ScheduledParam): void {
        this.pending.push(entry);
        this.pending.sort((a, b) => a.audioTime - b.audioTime);
    }

    /** Applies every entry due by `now`, then compacts the remainder forward. */
    drain(now: number, exports: Record<string, any>): void {
        const len = this.pending.length;
        if (len === 0) return;

        let processedCount = 0;
        for (let i = 0; i < len; i++) {
            if (this.pending[i].audioTime <= now) {
                this.applyOne(exports, this.pending[i]);
                processedCount++;
            } else {
                break;
            }
        }

        if (processedCount === 0) return;
        if (processedCount === len) {
            this.pending.length = 0;
            return;
        }

        const remaining = len - processedCount;
        for (let i = 0; i < remaining; i++) {
            this.pending[i] = this.pending[i + processedCount];
        }
        this.pending.length = remaining;
    }
}

// src/audio-worklets/pcf-processor.ts
// Pattern Controlled Filter (PCF) AudioWorklet Processor
// Implements ReBirth-style pattern-driven filter modulation as a real-time audio effect.

declare class AudioWorkletProcessor {
    readonly port: MessagePort;
    process(inputs: Float32Array[][], outputs: Float32Array[][], parameters: Record<string, Float32Array>): boolean;
}

declare function registerProcessor(name: string, processorCtor: new () => AudioWorkletProcessor): void;
declare const sampleRate: number;

/** Clamp a value to the [0, 1] range. */
function clamp01(v: number): number { return v < 0 ? 0 : v > 1 ? 1 : v; }
/** Clamp a value to the [0, 127] MIDI range. */
function clampMidi(v: number): number { return v < 0 ? 0 : v > 127 ? 127 : v; }

/** Filter types matching ReBirth PCF */
const PCF_FILTER_LP = 0;
const PCF_FILTER_BP = 1;
const PCF_FILTER_HP = 2;

/** Maximum steps in PCF pattern */
const MAX_PATTERN_STEPS = 32;

/**
 * Payload for the `set-automation` port message.
 *
 * Each field is independently optional; the presence/absence of a key
 * controls whether the corresponding automation override is modified:
 *  - `key present, value is number`  → activate/update that override
 *  - `key present, value is null`    → clear (deactivate) that override
 *  - `key absent`                    → leave the override unchanged
 */
interface PcfAutomationData {
  /** Absolute cutoff frequency in Hz (overrides pattern-driven cutoff). */
  cutoffHz?: number | null;
  /** Resonance as a MIDI value 0–127 (overrides base resonance). */
  resonanceMidi?: number | null;
  /** Envelope amount as a normalised 0–1 value (overrides base envAmount). */
  envAmountNorm?: number | null;
}

/**
 * PCF Processor - Pattern Controlled Filter
 *
 * Implements a biquad filter (LP/BP/HP) whose cutoff frequency is modulated
 * by a step pattern synchronized to transport position. This reproduces the
 * characteristic ReBirth PCF sound: rhythmic filter sweeps driven by a
 * programmable 16-step (or 32-step) modulation pattern.
 *
 * Messages accepted via port:
 *  - { type: 'set-params', data: PcfParams }
 *  - { type: 'set-pattern', data: number[] }  (0-127 per step)
 *  - { type: 'set-transport', data: { playing, bpm, stepIndex } }
 *  - { type: 'set-enabled', data: boolean }
 *  - { type: 'set-automation', data: PcfAutomationData }
 */
class PcfProcessor extends AudioWorkletProcessor {
    // Filter state (Direct Form II Transposed)
    private z1L = 0;
    private z2L = 0;
    private z1R = 0;
    private z2R = 0;

    // Current biquad coefficients
    private b0 = 1;
    private b1 = 0;
    private b2 = 0;
    private a1 = 0;
    private a2 = 0;

    // PCF Parameters (0-127 MIDI-style, converted internally)
    private filterType: number = PCF_FILTER_LP;
    private baseCutoff = 80;       // 0-127
    private resonance = 40;        // 0-127
    private envAmount = 60;        // 0-127
    private decay = 40;            // 0-127

    // Modulation pattern (0-127 per step)
    private pattern: number[] = new Array(16).fill(0);
    private patternLength = 16;

    // Transport state
    private playing = false;
    private bpm = 120;
    private currentStep = 0;

    // Envelope state for decay
    private envelopeLevel = 0;
    private envelopeDecayRate = 0;

    // Smoothing for cutoff changes (avoid zipper noise)
    private targetCutoffHz = 1000;
    private currentCutoffHz = 1000;
    private smoothingCoeff = 0;

    // Sample counter for step timing
    private sampleCounter = 0;
    private samplesPerStep = 0;

    // Enable/disable
    private enabled = true;

    // Automation overrides (external values, bypass pattern/params)
    private automationCutoffHz = -1;      // -1 means no override (Hz)
    private automationResonanceMidi = -1; // -1 means no override (0-127)
    private automationEnvAmountNorm = -1; // -1 means no override (0-1)

    constructor() {
        super();
        this.port.onmessage = this.handleMessage.bind(this);
        this.updateSamplesPerStep();
        this.updateSmoothingCoeff();
        this.updateEnvelopeDecayRate();
        this.computeCoefficients(this.currentCutoffHz, this.resonance);
    }

    private handleMessage(event: MessageEvent): void {
        const { type, data } = event.data;

        switch (type) {
            case 'set-params': {
                if (data.filterType !== undefined) this.filterType = data.filterType;
                if (data.cutoff !== undefined) this.baseCutoff = clampMidi(data.cutoff);
                if (data.resonance !== undefined) this.resonance = clampMidi(data.resonance);
                if (data.envAmount !== undefined) this.envAmount = clampMidi(data.envAmount);
                if (data.decay !== undefined) {
                    this.decay = clampMidi(data.decay);
                    this.updateEnvelopeDecayRate();
                }
                break;
            }
            case 'set-pattern': {
                if (Array.isArray(data)) {
                    const length = Math.min(data.length, MAX_PATTERN_STEPS);
                    const newPattern: number[] = new Array<number>(length);
                    for (let i = 0; i < length; i++) {
                        newPattern[i] = clampMidi(data[i]);
                    }
                    this.pattern = newPattern;
                    this.patternLength = length;
                }
                break;
            }
            case 'set-transport': {
                if (data.playing !== undefined) this.playing = data.playing;
                if (data.bpm !== undefined) {
                    this.bpm = Math.max(20, Math.min(300, data.bpm));
                    this.updateSamplesPerStep();
                }
                if (data.stepIndex !== undefined) {
                    this.currentStep = data.stepIndex % this.patternLength;
                    this.sampleCounter = 0;
                    this.triggerStep();
                }
                break;
            }
            case 'set-enabled': {
                this.enabled = !!data;
                if (!this.enabled) {
                    // Reset filter state when disabled
                    this.z1L = this.z2L = this.z1R = this.z2R = 0;
                }
                break;
            }
            case 'set-automation': {
                const automation = data as PcfAutomationData | null;
                if (!automation) break;
                if ('cutoffHz' in automation) {
                    this.automationCutoffHz =
                        typeof automation.cutoffHz === 'number' ? automation.cutoffHz : -1;
                }
                if ('resonanceMidi' in automation) {
                    this.automationResonanceMidi =
                        typeof automation.resonanceMidi === 'number'
                            ? clampMidi(automation.resonanceMidi)
                            : -1;
                }
                if ('envAmountNorm' in automation) {
                    this.automationEnvAmountNorm =
                        typeof automation.envAmountNorm === 'number'
                            ? clamp01(automation.envAmountNorm)
                            : -1;
                }
                break;
            }
        }
    }

    /**
     * Convert MIDI-range cutoff (0-127) to frequency in Hz.
     * Uses exponential mapping: 20Hz to 20000Hz.
     */
    private midiToHz(midiValue: number): number {
        // Exponential mapping: 0→20Hz, 127→20000Hz
        const normalized = midiValue / 127;
        return 20 * Math.pow(1000, normalized);
    }

    /**
     * Convert MIDI resonance (0-127) to Q factor.
     * Maps 0→0.5, 127→30 (high resonance for acid sounds).
     */
    private midiToQ(midiResonance: number): number {
        const normalized = midiResonance / 127;
        return 0.5 + normalized * 29.5;
    }

    private updateSamplesPerStep(): void {
        // 16th note duration at current BPM
        // One beat = 60/bpm seconds, one 16th = beat/4
        const secondsPerStep = 60 / (this.bpm * 4);
        this.samplesPerStep = Math.floor(secondsPerStep * sampleRate);
    }

    private updateSmoothingCoeff(): void {
        // ~5ms smoothing time constant
        const smoothTimeMs = 5;
        const smoothTimeSamples = (smoothTimeMs / 1000) * sampleRate;
        this.smoothingCoeff = 1 - Math.exp(-1 / smoothTimeSamples);
    }

    private updateEnvelopeDecayRate(): void {
        // Map decay (0-127) to decay time: 0→5ms, 127→500ms
        const decayNorm = this.decay / 127;
        const decayTimeMs = 5 + decayNorm * 495;
        const decayTimeSamples = (decayTimeMs / 1000) * sampleRate;
        // Exponential decay rate per sample
        this.envelopeDecayRate = Math.exp(-1 / decayTimeSamples);
    }

    /**
     * Trigger a new step: read pattern value and set envelope.
     */
    private triggerStep(): void {
        const stepValue = this.pattern[this.currentStep % this.patternLength] || 0;
        // Envelope amplitude: automation override takes priority over the base envAmount.
        const envScale = this.automationEnvAmountNorm >= 0
            ? this.automationEnvAmountNorm
            : this.envAmount / 127;
        this.envelopeLevel = (stepValue / 127) * envScale;
    }

    /**
     * Compute biquad filter coefficients for the given cutoff and resonance.
     * Uses Robert Bristow-Johnson's Audio EQ Cookbook formulas.
     */
    private computeCoefficients(cutoffHz: number, resonanceMidi: number): void {
        const freq = Math.max(20, Math.min(sampleRate * 0.45, cutoffHz));
        const Q = this.midiToQ(resonanceMidi);

        const w0 = (2 * Math.PI * freq) / sampleRate;
        const cosW0 = Math.cos(w0);
        const sinW0 = Math.sin(w0);
        const alpha = sinW0 / (2 * Q);

        let b0: number, b1: number, b2: number, a0: number, a1: number, a2: number;

        switch (this.filterType) {
            case PCF_FILTER_BP:
                // Bandpass (constant skirt gain)
                b0 = alpha;
                b1 = 0;
                b2 = -alpha;
                a0 = 1 + alpha;
                a1 = -2 * cosW0;
                a2 = 1 - alpha;
                break;
            case PCF_FILTER_HP:
                // Highpass
                b0 = (1 + cosW0) / 2;
                b1 = -(1 + cosW0);
                b2 = (1 + cosW0) / 2;
                a0 = 1 + alpha;
                a1 = -2 * cosW0;
                a2 = 1 - alpha;
                break;
            case PCF_FILTER_LP:
            default:
                // Lowpass
                b0 = (1 - cosW0) / 2;
                b1 = 1 - cosW0;
                b2 = (1 - cosW0) / 2;
                a0 = 1 + alpha;
                a1 = -2 * cosW0;
                a2 = 1 - alpha;
                break;
        }

        // Normalize by a0
        this.b0 = b0 / a0;
        this.b1 = b1 / a0;
        this.b2 = b2 / a0;
        this.a1 = a1 / a0;
        this.a2 = a2 / a0;
    }

    process(inputs: Float32Array[][], outputs: Float32Array[][], _parameters: Record<string, Float32Array>): boolean {
        const input = inputs[0];
        const output = outputs[0];

        if (!input || !input[0] || !output || !output[0]) {
            return true;
        }

        const inputL = input[0];
        const inputR = input[1] || input[0];
        const outputL = output[0];
        const outputR = output[1] || output[0];
        const blockSize = inputL.length;

        // Bypass: pass through unmodified
        if (!this.enabled) {
            for (let i = 0; i < blockSize; i++) {
                outputL[i] = inputL[i];
                if (output[1]) outputR[i] = inputR[i];
            }
            return true;
        }

        // Advance transport and compute target cutoff at block rate
        // (recompute coefficients once per block to reduce CPU)
        if (this.playing) {
            this.sampleCounter += blockSize;
            while (this.sampleCounter >= this.samplesPerStep) {
                this.sampleCounter -= this.samplesPerStep;
                this.currentStep = (this.currentStep + 1) % this.patternLength;
                this.triggerStep();
            }
        }

        // Apply envelope decay for block duration
        this.envelopeLevel *= Math.pow(this.envelopeDecayRate, blockSize);

        // Calculate target cutoff for this block
        let targetHz: number;
        if (this.automationCutoffHz >= 0) {
            targetHz = this.automationCutoffHz;
        } else {
            const baseHz = this.midiToHz(this.baseCutoff);
            const maxHz = this.midiToHz(127);
            const modRange = (maxHz - baseHz) * this.envelopeLevel;
            targetHz = baseHz + modRange;
        }

        // Smooth cutoff and recompute coefficients once per block
        this.currentCutoffHz += (targetHz - this.currentCutoffHz) * this.smoothingCoeff * blockSize;
        if (Math.abs(this.currentCutoffHz - this.targetCutoffHz) > 0.5) {
            this.targetCutoffHz = this.currentCutoffHz;
            // Use automation resonance override when active, else the base resonance.
            const resonanceForCoeffs = this.automationResonanceMidi >= 0
                ? this.automationResonanceMidi
                : this.resonance;
            this.computeCoefficients(this.currentCutoffHz, resonanceForCoeffs);
        }

        // Apply biquad filter (Direct Form II Transposed)
        for (let i = 0; i < blockSize; i++) {
            // Left channel
            const xL = inputL[i];
            const yL = this.b0 * xL + this.z1L;
            this.z1L = this.b1 * xL - this.a1 * yL + this.z2L;
            this.z2L = this.b2 * xL - this.a2 * yL;
            outputL[i] = yL;

            // Right channel
            const xR = inputR[i];
            const yR = this.b0 * xR + this.z1R;
            this.z1R = this.b1 * xR - this.a1 * yR + this.z2R;
            this.z2R = this.b2 * xR - this.a2 * yR;
            if (output[1]) outputR[i] = yR;
        }

        return true;
    }
}

