import { RingBuffer } from "../utils/ringBuffer";
import { ExpressiveVoiceProcessor } from "../engines/rubberband/ExpressiveVoiceProcessor";
import { WorkletPerfReporter } from "./workletPerfReporter";
import { resolveWorkletSampleRate } from "../utils/workletSampleRate";
import { RUBBERBAND_PARAMETER_DESCRIPTORS } from "./rubberband/parameterDescriptors";
import { getPhonemeDataAtSample, type PhonemeSample } from "./rubberband/phonemeData";
import { GranularEngine } from "./rubberband/granularEngine";
import { SpectralBandProcessor } from "./rubberband/spectralEffects";
import { VocalChorusEffect } from "./rubberband/chorusEffect";
import { SubHarmonicsEffect } from "./rubberband/subHarmonics";
import { TransientExtractor } from "./rubberband/transientExtractor";
import { Bitcrusher } from "./rubberband/bitcrusher";
import { PhonemeToneFilter, SyllableVolumeFilter, TranceGate } from "./rubberband/toneFilters";
import { DrumDuckEnvelope } from "./rubberband/drumDuckEnvelope";
// @ts-ignore - The file is generated by the build script
import createRubberBandModule from "./rubberband-lib.js";


interface AudioWorkletProcessor {
  readonly port: MessagePort;
  process(inputs: Float32Array[][], outputs: Float32Array[][], parameters: Record<string, Float32Array>): boolean;
}

declare var AudioWorkletProcessor: {
  prototype: AudioWorkletProcessor;
  new(options?: any): AudioWorkletProcessor;
};

declare function registerProcessor(name: string, processorCtor: (new (options?: any) => AudioWorkletProcessor)): void;

declare const globalThis: {
  sampleRate: number;
};

class RubberBandProcessor extends AudioWorkletProcessor {
  private rubberBand: any = null;
  private inputRingBuffer: RingBuffer | null = null;
  private outputRingBuffer: RingBuffer | null = null;
  private expressiveProcessor: ExpressiveVoiceProcessor;
  private readonly perf = new WorkletPerfReporter(this.port, 'rubberband');

  // DSP effect modules (each owns its own state)
  private readonly granular = new GranularEngine();
  private readonly spectral = new SpectralBandProcessor();
  private readonly chorus = new VocalChorusEffect();
  private readonly subHarmonics = new SubHarmonicsEffect();
  private readonly transientExtractor = new TransientExtractor();
  private readonly bitcrusher = new Bitcrusher();
  private readonly phonemeToneFilter = new PhonemeToneFilter();
  private readonly syllableVolumeFilter = new SyllableVolumeFilter();
  private readonly tranceGate = new TranceGate();
  private readonly drumDuck = new DrumDuckEnvelope();

  // Pre-allocated configuration for expressive processor to avoid per-block GC allocations
  private readonly currentExpressiveConfig = {
    vibrato: { depth: 0, rate: 0, enabled: false },
    tremolo: { depth: 0, rate: 0, enabled: false },
    gate: { depth: 0, rate: 0, enabled: false },
    breath: { amount: 0, enabled: false, filterCutoff: 2000 },
    envelope: { attack: 0, decay: 0, sustain: 0, release: 0 },
    pitchEnvelope: { attack: 0, decay: 0, amount: 0 }
  };

  private readonly bandSplitParams = {
    outL: new Float32Array(0) as Float32Array | any,
    outR: undefined as Float32Array | any | undefined,
    hasStereo: false,
    spectralComp: 0,
    spectralCompression: 0,
    grainPanSpread: 0,
    grainPanL: [] as readonly number[],
    grainPanR: [] as readonly number[],
    sampleRate: 0
  };

  // WASM Memory Management
  private inputHeapPtr: number = 0;
  private outputHeapPtr: number = 0;
  private heapSizeFrames: number = 0;

  // Audio State
  private sampleRate = 44100;
  private initialized = false;
  private fullSampleBuffer: Float32Array | null = null;

  // Phoneme Data
  private phonemeData: Float32Array | null = null;
  private phonemeRatios: number[] | null = null;
  private readonly phonemeTuple = new Float32Array(9);

  // Drum Envelope Sidechain
  private drumSidechainSAB: Float32Array | null = null;

  // Playback State (Unified)
  private isPlaying = false;
  private isReverse = false;

  private readonly boundEnsureHeapSize = (frames: number) => this.ensureHeapSize(frames);
  private readonly boundGetInputHeapPtr = () => this.inputHeapPtr;
  private readonly frozenGrainParams = {
    rubberBand: null,
    ensureHeapSize: this.boundEnsureHeapSize,
    getInputHeapPtr: this.boundGetInputHeapPtr,
    fullSampleBuffer: new Float32Array(0) as Float32Array | null,
    sampleRate: 0,
    phonemeData: null as Float32Array | null,
    phonemeRatios: null as number[] | null,
    currentSamplePtr: 0,
    startSamplePtr: 0,
    endSamplePtr: 0,
    duckingScalar: 0,
    envelopeValue: 0,
    grainJitterParam: 0,
    grainEnvDepth: 0,
    windowShape: 0,
    grainLfoDepth: 0,
    grainPosLfoDepth: 0,
    samplesRequired: 0,
    velocity: 1.0
  };

  private currentSamplePtr = 0;
  private startSamplePtr = 0;
  private endSamplePtr = 0;
  private basePitch = 1.0;
  private targetHz: number = 0;
  private currentSampleVelocity = 1.0;
  static get parameterDescriptors() {
    return RUBBERBAND_PARAMETER_DESCRIPTORS;
  }

  // Pitch Correction State
  private pitchDetectState = {
    lastSample: 0,
    lastCrossIndex: 0,
    periods: new Float32Array(5),
    periodIndex: 0,
    lastValidF0: 0,
    smoothCorr: 1.0
  };

  // Auto-Tune State
  private autoTuneLastSign: number = 0;
  private autoTuneSamplesSinceZero: number = 0;
  private autoTuneSmoothedPeriod: number = 0;

  constructor() {
    super();
    this.port.onmessage = this.handleMessage.bind(this);
    // @ts-ignore
    this.sampleRate = resolveWorkletSampleRate();

    this.expressiveProcessor = new ExpressiveVoiceProcessor({
      sampleRate: this.sampleRate
    });
  }

  async handleMessage(event: MessageEvent) {
    const { type, data } = event.data;

    switch (type) {
      case 'INIT_WASM':
        try {
          const { inputBuffer, outputBuffer, wasmBinary, baseUrl, drumSidechainSAB } = event.data;

          this.inputRingBuffer = new RingBuffer(inputBuffer);
          this.outputRingBuffer = new RingBuffer(outputBuffer);

          if (drumSidechainSAB) {
            this.drumSidechainSAB = new Float32Array(drumSidechainSAB);
          }

          if (!wasmBinary) {
            throw new Error("WASM binary not provided in INIT_WASM message");
          }

          const wasmPath = `${baseUrl || '/'}rubberband.wasm`;
          // Instantiate WASM module with the provided binary
          // @ts-ignore
          const module = await createRubberBandModule({
            wasmBinary: wasmBinary,
            locateFile: (path: string) => {
              if (path.endsWith('.wasm')) return wasmPath;
              return path;
            }
          });

          const safeSampleRate = Math.floor(resolveWorkletSampleRate({ sampleRate: this.sampleRate }));

          // Options: RealTime (1) | Finer (32) | FormantPreserved (1048576) = 1048609
          const options = 1 | 32 | 1048576;

          console.log(`[RubberBandProcessor] Initializing with: Rate=${safeSampleRate}, Ch=1, Opts=${options}`);

          this.rubberBand = new module.RubberBandStretcher(
            safeSampleRate,
            1, // Mono
            options,
            1.0, // Initial Time Ratio
            1.0  // Initial Pitch Scale
          );

          this.rubberBand.module = module;
          this.initialized = true;
          this.port.postMessage({ type: 'READY' });
        } catch (e) {
          console.error("RubberBand WASM Failed:", e);
          this.port.postMessage({ type: 'ERROR', error: String(e) });
        }
        break;

      case 'loadBuffer':
        if (data && data.buffer) {
          this.fullSampleBuffer = new Float32Array(data.buffer);
        }
        break;

      case 'setCustomWindowShape':
        if (data.shape && data.shape.length > 0) {
          this.granular.setCustomWindowShape(new Float32Array(data.shape));
        } else {
          this.granular.setCustomWindowShape(null);
        }
        break;

      case 'setPhonemeData':
        if (data && data.sharedBuffer) {
          this.phonemeData = new Float32Array(data.sharedBuffer);
          this.phonemeRatios = data.ratios || null;
        }
        break;
      case 'noteOn':
        if (!this.initialized || !this.fullSampleBuffer || !data) return;
        this.rubberBand.reset();

        // Store base pitch for combination with parameters
        this.basePitch = data.pitch || 1.0;
        if (data.targetHz) {
           this.targetHz = data.targetHz;
        }
        this.currentSampleVelocity = data.velocity ?? 1.0;
        this.rubberBand.setPitchScale(this.basePitch);
        this.rubberBand.setTimeRatio(1.0);
        this.expressiveProcessor.reset();
        this.expressiveProcessor.noteOn();

        const startSample = Math.max(0, Math.floor(data.startSample || 0));
        const endSample = data.endSample
          ? Math.min(this.fullSampleBuffer.length, Math.floor(data.endSample))
          : this.fullSampleBuffer.length;

        if (startSample >= endSample) return;

        this.isReverse = !!data.reverse;

        // Initialize streaming state
        this.startSamplePtr = startSample;
        this.endSamplePtr = endSample;

        // Check if we are switching direction mid-playback
        const wasReverse = this.isReverse;
        this.isReverse = !!data.reverse;

        if (this.isPlaying && wasReverse !== this.isReverse) {
            // Apply a short envelope fade to smooth the transition
            // The ExpressiveVoiceProcessor handles envelope re-triggering smoothly
            // if we just call noteOn again without resetting envelope state to 0.
        } else {
            // Normal initialization
            if (this.isReverse) {
                this.currentSamplePtr = endSample - 1;
            } else {
                this.currentSamplePtr = startSample;
            }
        }

        this.isPlaying = true;
        this.syllableVolumeFilter.resetHoldState();
        break;

      case 'setReverse':
        if (data && typeof data.reverse === 'boolean') {
          this.isReverse = data.reverse;
        }
        break;

      case 'noteOff':
        const targetTime = data?.time;
        this.expressiveProcessor.noteOff(targetTime);
        break;

      case 'setStretchProfile':
        // Update RubberBand quality options (requires reset)
        if (data && typeof data.profile === 'string') {
          if (this.rubberBand) {
             const timeRatio = this.rubberBand.getTimeRatio();
             const pitchScale = this.rubberBand.getPitchScale();

             let options = 1 | 32 | 1048576; // Default to vocal

             if (data.profile === 'harmonic') {
                 options = 1 | 32 | 256 | 0x02000000; // OptionProcessRealTime | OptionEngineFiner | OptionTransientsMixed | OptionPitchHighQuality
             } else if (data.profile === 'fast') {
                 options = 1; // OptionProcessRealTime | OptionEngineFaster
             } else {
                 options = 1 | 32 | 256 | 1048576; // OptionProcessRealTime | OptionEngineFiner | OptionTransientsMixed | OptionFormantPreserved
             }

             // Free old buffers if they exist
             if (this.inputHeapPtr) this.rubberBand.module._free(this.inputHeapPtr);
             if (this.outputHeapPtr) this.rubberBand.module._free(this.outputHeapPtr);
             this.inputHeapPtr = 0;
             this.outputHeapPtr = 0;
             this.heapSizeFrames = 0;

             // Recreate Stretcher
             this.rubberBand = new this.rubberBand.module.RubberBandStretcher(
               this.sampleRate,
               1, // Mono
               options,
               1.0, // Initial Time Ratio
               1.0  // Initial Pitch Scale
             );



             this.rubberBand.setTimeRatio(timeRatio);
             this.rubberBand.setPitchScale(pitchScale);
          }
        }
        break;

      case 'setAutoFollow':
        // Enable/disable auto pitch following from sequencer
        if (data && typeof data.enabled === 'boolean') {
          // this.autoFollowEnabled = data.enabled;
        }
        break;

      case 'setCustomGrainEnvelope':
        if (data && Array.isArray(data.shape)) {
          this.granular.setCustomGrainEnvelope(data.shape);
        } else {
          this.granular.setCustomGrainEnvelope(null);
        }
        break;
    }
  }

  private getPhonemeDataAtSample(currentSample: number): Float32Array {
    return getPhonemeDataAtSample(this.phonemeData, this.phonemeRatios, currentSample, this.phonemeTuple);
  }

  process(_inputs: Float32Array[][], outputs: Float32Array[][], parameters: Record<string, Float32Array>): boolean {
    const outputChannel = outputs[0][0];
    const blockFrames = outputChannel?.length ?? 128;
    this.perf.beginProcess(blockFrames);
    try {
    outputChannel.fill(0);

    if (!this.initialized || !this.rubberBand || !this.outputRingBuffer) {
      return true;
    }

    // We need to pass the block's start time to ExpressiveVoiceProcessor for accurate timing.
    // In AudioWorklets, the current time is `globalThis.currentTime`.
    // @ts-ignore
    const currentTime = typeof globalThis.currentTime === 'number' ? globalThis.currentTime : 0;
    this.expressiveProcessor.setCurrentTime(currentTime);

    const envelopeValue = this.expressiveProcessor.getCurrentEnvelopeValue();

    const pitchEnvelopeValue = this.expressiveProcessor.getCurrentPitchEnvelopeValue();


    const pitch = parameters.pitchScale[0];
    const defaultTimeRatio = parameters.timeRatio[0];
    const vibDepth = parameters.vibratoDepth[0];
    const vibRate = parameters.vibratoRate[0];
    const tremDepth = parameters.tremoloDepth[0];
    const tremRate = parameters.tremoloRate ? parameters.tremoloRate[0] : 0;
    const gateDepth = parameters.gateDepth ? parameters.gateDepth[0] : 0;
    const gateRate = parameters.gateRate ? parameters.gateRate[0] : 4.0;
    const bitcrushAmount = parameters.bitcrush ? parameters.bitcrush[0] : 0.0;
    const spectralComp = parameters.spectralComp ? parameters.spectralComp[0] : 0.0;
    const subHarmonicsAmount = parameters.subHarmonics ? parameters.subHarmonics[0] : 0.0;
    const transientExtractionAmount = parameters.transientExtraction ? parameters.transientExtraction[0] : 0.0;
    const vocalChorusAmount = parameters.vocalChorus ? parameters.vocalChorus[0] : 0.0;
    const downsampleFactor = parameters.downsample ? parameters.downsample[0] : 1.0;
    const breath = parameters.breathIntensity[0];
    const drumDuckDepth = parameters.drumDuckDepth ? parameters.drumDuckDepth[0] : 0.0;

    const pitchAttack = parameters.pitchAttack ? parameters.pitchAttack[0] : 0.0;
    const pitchDecay = parameters.pitchDecay ? parameters.pitchDecay[0] : 0.0;
    const pitchAmount = parameters.pitchAmount ? parameters.pitchAmount[0] : 0.0;
    const attack = parameters.attack ? parameters.attack[0] : 0.05;
    const decay = parameters.decay ? parameters.decay[0] : 0.1;
    const sustain = parameters.sustain ? parameters.sustain[0] : 1.0;
    const release = parameters.release ? parameters.release[0] : 0.1;

    let currentVibDepth = vibDepth;
    let currentVibRate = vibRate;
    if (this.isPlaying && this.fullSampleBuffer && this.phonemeData && this.phonemeRatios) {
        const pData = this.getPhonemeDataAtSample(this.currentSamplePtr);
        const pVibDepth = pData[3];
        const pVibRate = pData[4];
        if (pVibDepth !== -1.0) currentVibDepth = pVibDepth;
        if (pVibRate !== -1.0) currentVibRate = pVibRate;
    }

    // Drum sidechain envelope follower
    const fsForDuck = resolveWorkletSampleRate({ sampleRate: this.sampleRate || globalThis.sampleRate });
    const { duckingScalar, isSnare: drumIsSnare } = this.drumDuck.process(
      this.drumSidechainSAB, drumDuckDepth, currentTime, blockFrames, fsForDuck
    );

    const cfg = this.currentExpressiveConfig;
    cfg.vibrato.depth = currentVibDepth;
    cfg.vibrato.rate = currentVibRate;
    cfg.vibrato.enabled = currentVibDepth > 0;

    cfg.tremolo.depth = tremDepth;
    cfg.tremolo.rate = tremRate;
    cfg.tremolo.enabled = tremDepth > 0;

    cfg.gate.depth = gateDepth;
    cfg.gate.rate = gateRate;
    cfg.gate.enabled = gateDepth > 0;

    cfg.breath.amount = breath;
    cfg.breath.enabled = breath > 0;

    cfg.envelope.attack = attack;
    cfg.envelope.decay = decay;
    cfg.envelope.sustain = sustain;
    cfg.envelope.release = release;

    cfg.pitchEnvelope.attack = pitchAttack;
    cfg.pitchEnvelope.decay = pitchDecay;
    cfg.pitchEnvelope.amount = pitchAmount;

    this.expressiveProcessor.updateConfig(cfg);

    // Combine note pitch with parameter modulation
    let finalPitch = this.isPlaying ? this.basePitch * pitch : pitch;


    // Apply Pitch Envelope
    if (pitchAmount !== 0.0 && pitchEnvelopeValue > 0.0) {
      // Amount is in semitones. Pitch envelope value is 0.0 to 1.0.
      const pitchEnvSemitones = pitchAmount * pitchEnvelopeValue;
      const pitchEnvRatio = Math.pow(2.0, pitchEnvSemitones / 12.0);
      finalPitch *= pitchEnvRatio;
    }

    // Granular Pitch Shift & Envelope
    let granularPitchShift = parameters.granularPitchShift ? parameters.granularPitchShift[0] : 0.0;

    // Apply Granular Pitch Envelope (maps envelope 0-1 to shift amount, similar to main pitch env)
    const grainPitchEnvDepth = parameters.grainPitchEnvDepth ? parameters.grainPitchEnvDepth[0] : 0.0;
    if (grainPitchEnvDepth !== 0.0 && pitchEnvelopeValue > 0.0) {
        const maxEnvShift = 24.0;
        granularPitchShift += (maxEnvShift * grainPitchEnvDepth * pitchEnvelopeValue);
    }

    if (granularPitchShift !== 0.0) {
      const pitchShiftRatio = Math.pow(2.0, granularPitchShift / 12.0);
      finalPitch *= pitchShiftRatio;
    }

    // Apply Phoneme Pitch Bend (if we're streaming from a buffer and have it calculated)
    if (this.isPlaying && this.fullSampleBuffer && this.phonemeData && this.phonemeRatios) {
        const pData = this.getPhonemeDataAtSample(this.currentSamplePtr);
        const pBend = pData[2];
        if (pBend !== 0.0) {
            const pitchBendRatio = Math.pow(2.0, pBend / 1200.0);
            finalPitch *= pitchBendRatio;
        }

        const microtonalVariance = parameters.microtonalVariance ? parameters.microtonalVariance[0] : 0.0;
        if (microtonalVariance > 0.0) {
            const phonemeIndex = pData[8];
            if (phonemeIndex !== -1.0) {
                // Generate a stable pseudo-random value between -1.0 and 1.0 based on phoneme index
                let variation = Math.sin(phonemeIndex * 12.9898 + 78.233) * 43758.5453;
                variation = variation - Math.floor(variation); // 0.0 to 1.0
                variation = (variation * 2.0) - 1.0; // -1.0 to 1.0

                const microtonalRatio = Math.pow(2.0, (variation * microtonalVariance) / 1200.0);
                finalPitch *= microtonalRatio;
            }
        }
    }

    // Pitch Correction (AutoTune)
    const autoTuneAmount = parameters.autoTune ? parameters.autoTune[0] : 0.0;
    const sRate = resolveWorkletSampleRate({ sampleRate: this.sampleRate || globalThis.sampleRate });

    if (autoTuneAmount > 0.0 && this.isPlaying && this.fullSampleBuffer && this.targetHz > 0) {
      const pData = this.getPhonemeDataAtSample(this.currentSamplePtr);
      const isVowel = pData[7] > 0;

      // Only attempt detection on voiced vowels with sufficient envelope
      if (isVowel && envelopeValue > 0.01) {
        // Fast zero-crossing period detector on the input buffer slice
        const searchFrames = Math.min(1024, this.fullSampleBuffer.length - this.currentSamplePtr);
        const minPeriod = Math.floor(sRate / 400); // 400 Hz max
        const maxPeriod = Math.floor(sRate / 70);  // 70 Hz min

        let crosses = 0;

        for (let i = 0; i < searchFrames; i++) {
          const idx = this.currentSamplePtr + i;
          const x = this.fullSampleBuffer[idx];

          // Hysteresis threshold to avoid noise false triggers
          if (x > 0.02 && this.pitchDetectState.lastSample <= 0.02) {
            // Positive edge crossing
            const currentCrossIndex = idx;
            if (this.pitchDetectState.lastCrossIndex > 0) {
              const period = currentCrossIndex - this.pitchDetectState.lastCrossIndex;
              if (period >= minPeriod && period <= maxPeriod) {
                 this.pitchDetectState.periods[this.pitchDetectState.periodIndex] = period;
                 this.pitchDetectState.periodIndex = (this.pitchDetectState.periodIndex + 1) % 5;
                 crosses++;
                 // We only need one valid period to update the state, but we can search for a few to fill the median buffer quickly if empty
                 if (crosses >= 2) break;
              }
            }
            this.pitchDetectState.lastCrossIndex = currentCrossIndex;
          }
          this.pitchDetectState.lastSample = x;
        }

        // Calculate median period if we have valid data
        let validPeriods = 0;
        let sum = 0;
        for (let i = 0; i < 5; i++) {
          if (this.pitchDetectState.periods[i] > 0) {
             validPeriods++;
             sum += this.pitchDetectState.periods[i];
          }
        }

        if (validPeriods > 0) {
           const avgPeriod = sum / validPeriods;
           this.pitchDetectState.lastValidF0 = sRate / avgPeriod;
        }
      }

      // Apply correction based on last valid F0 (held during consonants)
      if (this.pitchDetectState.lastValidF0 > 0) {
         const rawCorr = Math.max(0.5, Math.min(2.0, this.targetHz / this.pitchDetectState.lastValidF0));
         const corr = 1.0 + autoTuneAmount * (rawCorr - 1.0);

         // Medium-fast block rate smoothing (alpha ~0.2)
         this.pitchDetectState.smoothCorr = this.pitchDetectState.smoothCorr * 0.8 + corr * 0.2;
         finalPitch *= this.pitchDetectState.smoothCorr;
      } else {
         // Decay back to 1.0 if no valid F0 ever detected
         this.pitchDetectState.smoothCorr = this.pitchDetectState.smoothCorr * 0.8 + 1.0 * 0.2;
         finalPitch *= this.pitchDetectState.smoothCorr;
      }
    } else {
      // Decay back to 1.0 if bypassed
      this.pitchDetectState.smoothCorr = this.pitchDetectState.smoothCorr * 0.8 + 1.0 * 0.2;
      finalPitch *= this.pitchDetectState.smoothCorr;

      // Granular Pitch Quantization: snap pitch to intervals when active (only if autoTune is off to prevent fighting)
      const grainPitchQuantize = parameters.grainPitchQuantize ? parameters.grainPitchQuantize[0] : 0.0;
      if (grainPitchQuantize > 0.0 && finalPitch > 0.0) {
        const semitones = 12.0 * Math.log2(finalPitch);
        const quantizedSemitones = Math.round(semitones / grainPitchQuantize) * grainPitchQuantize;
        finalPitch = Math.pow(2.0, quantizedSemitones / 12.0);
      }
    }

    // Apply Auto-Tune Pitch Correction based on previous block's detected pitch
    const autoTune = parameters.autoTune ? parameters.autoTune[0] : 0.0;
    if (autoTune > 0.0 && this.autoTuneSmoothedPeriod > 0) {
      const fs = resolveWorkletSampleRate({ sampleRate: this.sampleRate || globalThis.sampleRate });
      const detectedFreq = fs / this.autoTuneSmoothedPeriod;

      // Quantize detected frequency to nearest MIDI note
      if (detectedFreq > 20 && detectedFreq < 20000) {
        const midiNote = 12.0 * Math.log2(detectedFreq / 440.0) + 69.0;
        const nearestMidiNote = Math.round(midiNote);
        const targetFreq = 440.0 * Math.pow(2.0, (nearestMidiNote - 69.0) / 12.0);

        const correctionRatio = targetFreq / detectedFreq;

        // Blend between uncorrected and fully corrected based on autoTune depth
        finalPitch *= (1.0 - autoTune) + (autoTune * correctionRatio);
      }
    }

    this.rubberBand.setPitchScale(finalPitch);

    try {
      // STREAMING INPUT LOGIC
      // If playing a note, stream from fullSampleBuffer with phoneme-aware time stretching
      if (this.isPlaying && this.fullSampleBuffer) {
        // Calculate dynamic time ratio based on phoneme data
        let ratio = defaultTimeRatio;
        if (this.phonemeData && this.phonemeRatios) {
          const pData = this.getPhonemeDataAtSample(this.currentSamplePtr);
          const pRatio = pData[0];
          ratio = pRatio;
        }

        // Apply Time-Stretch Envelope modulation
        const timeStretchEnvDepth = parameters.timeStretchEnvDepth ? parameters.timeStretchEnvDepth[0] : 0.0;
        const timeModulation = timeStretchEnvDepth * envelopeValue * 3.0; // scale factor
        ratio = Math.max(0.1, Math.min(4.0, ratio + timeModulation));

        this.rubberBand.setTimeRatio(ratio);

        const samplesRequired = this.rubberBand.getSamplesRequired();

        const freezeBase = parameters.freeze ? parameters.freeze[0] : 0.0;
        const freezeLfoRate = parameters.freezeLfoRate ? parameters.freezeLfoRate[0] : 0.0;
        const freezeLfoDepth = parameters.freezeLfoDepth ? parameters.freezeLfoDepth[0] : 0.0;
        const freezeEnvDepth = parameters.freezeEnvDepth ? parameters.freezeEnvDepth[0] : 0.0;
        const grainEnvDepth = parameters.grainEnvDepth ? parameters.grainEnvDepth[0] : 0.0;
        const windowShape = parameters.windowShape ? parameters.windowShape[0] : 0.0;
        const grainLfoRate = parameters.grainLfoRate ? parameters.grainLfoRate[0] : 0.0;
        const grainLfoDepth = parameters.grainLfoDepth ? parameters.grainLfoDepth[0] : 0.0;
        const grainPosLfoDepth = parameters.grainPosLfoDepth ? parameters.grainPosLfoDepth[0] : 0.0;

        // Advance LFO phase once per block (128 samples, standard Web Audio block size)
        const sRateFreeze = resolveWorkletSampleRate({ sampleRate: this.sampleRate || globalThis.sampleRate });
        const framesInBlock = 128;
        this.granular.advanceLfoPhases(freezeLfoRate, grainLfoRate, sRateFreeze, framesInBlock);

        const lfoValue = this.granular.getFreezeLfoValue();
        // Bipolar modulation: freezeBase + freezeLfoDepth * sin, plus envelope follower modulation
        let freezeAmt = freezeBase + (freezeLfoDepth * lfoValue) + (freezeEnvDepth * envelopeValue);
        freezeAmt = Math.max(0.0, Math.min(1.0, freezeAmt));

        const isFrozen = freezeAmt > 0.5;

        if (isFrozen) {
          this.granular.enterFreeze();

          // FREEZE STREAMING (Spectral Granulator)
          this.frozenGrainParams.rubberBand = this.rubberBand;
          this.frozenGrainParams.fullSampleBuffer = this.fullSampleBuffer;
          this.frozenGrainParams.sampleRate = resolveWorkletSampleRate({ sampleRate: this.sampleRate || globalThis.sampleRate });
          this.frozenGrainParams.phonemeData = this.phonemeData;
          this.frozenGrainParams.phonemeRatios = this.phonemeRatios;
          this.frozenGrainParams.currentSamplePtr = this.currentSamplePtr;
          this.frozenGrainParams.startSamplePtr = this.startSamplePtr;
          this.frozenGrainParams.endSamplePtr = this.endSamplePtr;
          this.frozenGrainParams.duckingScalar = duckingScalar;
          this.frozenGrainParams.envelopeValue = envelopeValue;
          this.frozenGrainParams.grainJitterParam = parameters.grainJitter ? parameters.grainJitter[0] : 0.0;
          this.frozenGrainParams.grainEnvDepth = grainEnvDepth;
          this.frozenGrainParams.windowShape = windowShape;
          this.frozenGrainParams.grainLfoDepth = grainLfoDepth;
          this.frozenGrainParams.grainPosLfoDepth = grainPosLfoDepth;
          this.frozenGrainParams.samplesRequired = samplesRequired;
          this.frozenGrainParams.velocity = this.currentSampleVelocity;

          this.granular.renderFrozenBlock(this.frozenGrainParams);
        } else {
          const wasUnfrozen = this.granular.exitFreeze();
          if (wasUnfrozen) {
            // Clear SVF states to avoid bleed from panned grains
            this.spectral.clearLegacyBandState();
          }

          if (this.isReverse) {
            // REVERSE STREAMING
            const samplesRemaining = this.currentSamplePtr - this.startSamplePtr + 1;

            if (samplesRemaining > 0 && samplesRequired > 0) {
              const samplesToFeed = Math.min(samplesRemaining, samplesRequired);
              this.ensureHeapSize(samplesToFeed);

              // Manually copy in reverse order
              const heap = this.rubberBand.module.HEAPF32;
              const ptr = this.inputHeapPtr >> 2;
              const buf = this.fullSampleBuffer;
              let readPtr = this.currentSamplePtr;

              for (let i = 0; i < samplesToFeed; i++) {
                heap[ptr + i] = buf[readPtr--];
              }

              this.rubberBand.process(this.inputHeapPtr, samplesToFeed, false);
              this.currentSamplePtr = readPtr;
            }
          } else {
            // FORWARD STREAMING
            const samplesRemaining = this.endSamplePtr - this.currentSamplePtr;

            if (samplesRemaining > 0 && samplesRequired > 0) {
              const samplesToFeed = Math.min(samplesRemaining, samplesRequired);
              this.ensureHeapSize(samplesToFeed);

              // Copy directly to WASM heap
              const heap = this.rubberBand.module.HEAPF32;
              const ptr = this.inputHeapPtr >> 2;
              for (let i = 0; i < samplesToFeed; i++) {
                heap[ptr + i] = this.fullSampleBuffer[this.currentSamplePtr + i];
              }

              this.rubberBand.process(this.inputHeapPtr, samplesToFeed, false);
              this.currentSamplePtr += samplesToFeed;
            }
          }
        }
      }
      // Fallback: Check RingBuffer input (for real-time mic usage if supported later)
      else if (this.inputRingBuffer && this.inputRingBuffer.availableRead() > 0) {
        const required = this.rubberBand.getSamplesRequired();
        const available = this.inputRingBuffer.availableRead();
        if (available >= required && required > 0) {
          this.ensureHeapSize(required);
          this.inputRingBuffer.pull(this.rubberBand.module.HEAPF32, this.inputHeapPtr >> 2);
          this.rubberBand.process(this.inputHeapPtr, required, false);
        }
      }

      // --- OUTPUT RETRIEVAL LOGIC ---
      const availOutput = this.rubberBand.available();
      if (availOutput > 0) {
        const framesToRead = Math.min(availOutput, outputChannel.length);
        this.ensureHeapSize(framesToRead);

        const retrieved = this.rubberBand.retrieve(this.outputHeapPtr, framesToRead);
        const heap = this.rubberBand.module.HEAPF32;
        const ptr = this.outputHeapPtr >> 2;
        for (let i = 0; i < retrieved; i++) {
          outputChannel[i] = heap[ptr + i];
        }

        const isVowelForExpressive = this.phonemeData && this.phonemeRatios
            ? this.getPhonemeDataAtSample(this.currentSamplePtr)[7]
            : 1.0;
        this.expressiveProcessor.process(outputChannel, outputChannel, isVowelForExpressive);

        // Zero-Crossing Pitch Detection for Auto-Tune
        if (autoTune > 0.0 && outputChannel.length > 0) {
            for (let i = 0; i < outputChannel.length; i++) {
                const sample = outputChannel[i];
                const currentSign = sample >= 0 ? 1 : -1;

                this.autoTuneSamplesSinceZero++;

                if (currentSign !== this.autoTuneLastSign) {
                    if (currentSign === 1) { // Positive edge
                        if (this.autoTuneSamplesSinceZero > 10) { // Filter out very high freq noise (> ~4kHz)
                            const currentPeriod = this.autoTuneSamplesSinceZero;
                            if (this.autoTuneSmoothedPeriod === 0) {
                                this.autoTuneSmoothedPeriod = currentPeriod;
                            } else {
                                // Smooth the period measurement
                                this.autoTuneSmoothedPeriod = this.autoTuneSmoothedPeriod * 0.9 + currentPeriod * 0.1;
                            }
                        }
                        this.autoTuneSamplesSinceZero = 0;
                    }
                    this.autoTuneLastSign = currentSign;
                }
            }
        }

        // Apply phoneme volume and filter mod
        const phonemeFilterMod = parameters.phonemeFilterMod ? parameters.phonemeFilterMod[0] : 0.0;
        const hasPhonemeContext = this.isPlaying && !!this.fullSampleBuffer && !!this.phonemeData && !!this.phonemeRatios;
        const phonemeVolume = hasPhonemeContext ? this.getPhonemeDataAtSample(this.currentSamplePtr)[1] : null;
        const sRateForPhonemeFilter = resolveWorkletSampleRate({ sampleRate: this.sampleRate || globalThis.sampleRate });
        this.phonemeToneFilter.process(outputChannel, phonemeFilterMod, phonemeVolume, sRateForPhonemeFilter);

        // Apply Syllable Volume Filter
        const volFilterMod = parameters.volumeFilterMod ? parameters.volumeFilterMod[0] : 0.0;
        if (volFilterMod > 0 && this.isPlaying && this.phonemeData) {
          const pData = this.getPhonemeDataAtSample(this.currentSamplePtr);
          this.syllableVolumeFilter.process(outputs, volFilterMod, pData[1], pData[7], this.sampleRate);
        }

        // Apply Rhythmic Gating (Trance Gate)
        const sRateForGate = resolveWorkletSampleRate({ sampleRate: this.sampleRate || globalThis.sampleRate });
        this.tranceGate.process(outputChannel, gateDepth, gateRate, sRateForGate);

        // Grain-triggered stereo pan spread
        const grainPanSpread = parameters.grainPanSpread ? parameters.grainPanSpread[0] : 0.0;
        const spectralCompression = parameters.spectralCompression
          ? parameters.spectralCompression[0]
          : 0.0;
        const isVowelForPan = (grainPanSpread > 0 && this.granular.grainWrapPending)
          ? this.getPhonemeDataAtSample(this.currentSamplePtr)[7]
          : 0;
        this.granular.updateGrainPan(grainPanSpread, isVowelForPan);

        const outL = outputs[0][0];
        const outR = outputs[0][1];
        const hasStereo = !!(outL && outR);
        const sRateForSpectral = resolveWorkletSampleRate({ sampleRate: this.sampleRate || globalThis.sampleRate });

        this.bandSplitParams.outL = outL;
        this.bandSplitParams.outR = outR;
        this.bandSplitParams.hasStereo = hasStereo;
        this.bandSplitParams.spectralComp = spectralComp;
        this.bandSplitParams.spectralCompression = spectralCompression;
        this.bandSplitParams.grainPanSpread = grainPanSpread;
        this.bandSplitParams.grainPanL = this.granular.grainPanL;
        this.bandSplitParams.grainPanR = this.granular.grainPanR;
        this.bandSplitParams.sampleRate = sRateForSpectral;
        this.spectral.applyBandSplitAndCompression(this.bandSplitParams);

        // Vocal Stack Chorus Effect (Post-Retrieve Micro-Delay Taps)
        if (vocalChorusAmount > 0) {
          const isVowelForChorus = this.getPhonemeDataAtSample(this.currentSamplePtr)[7];
          const fsForChorus = this.sampleRate || (globalThis as { sampleRate?: number }).sampleRate || 44100;
          this.chorus.process(outputs, vocalChorusAmount, isVowelForChorus, fsForChorus);
        }

        // Generate Sub-Harmonics (Vowels only)
        // Duck sub harmonics heavily on Kick (drumIsSnare === 0)
        const effectiveSubAmount = subHarmonicsAmount * (drumIsSnare === 0.0 ? Math.max(0, 1.0 - duckingScalar) : 1.0);
        if (effectiveSubAmount > 0) {
          const isVowelForSub = this.getPhonemeDataAtSample(this.currentSamplePtr)[7];
          const sRateForSub = resolveWorkletSampleRate({ sampleRate: this.sampleRate || globalThis.sampleRate });
          this.subHarmonics.process(outputs, effectiveSubAmount, isVowelForSub, sRateForSub);
        }

        if (transientExtractionAmount > 0) {
          const isVowelForTrans = this.getPhonemeDataAtSample(this.currentSamplePtr)[7];
          const sRateForTrans = resolveWorkletSampleRate({ sampleRate: this.sampleRate || globalThis.sampleRate });
          this.transientExtractor.process(outputs, transientExtractionAmount, isVowelForTrans, sRateForTrans);
        }

        if (duckingScalar > 0) {
          const isVowelForDuck = this.getPhonemeDataAtSample(this.currentSamplePtr)[7];
          const sRateForDuck = resolveWorkletSampleRate({ sampleRate: this.sampleRate || globalThis.sampleRate });
          this.drumDuck.applyMasterDuck(outputs, duckingScalar, isVowelForDuck, sRateForDuck);
        }

        // Apply Bitcrush & Downsample
        this.bitcrusher.process(outputs, bitcrushAmount, downsampleFactor);

        // Check for completion when no output is available but we're still marked as playing
        if (this.isReverse) {
          if (this.currentSamplePtr < this.startSamplePtr) this.isPlaying = false;
        } else {
          if (this.currentSamplePtr >= this.endSamplePtr) this.isPlaying = false;
        }
      }

    } catch (e) {
      console.error("DSP Error:", e);
    }

    return true;
    } finally {
      this.perf.endProcess();
    }
  }

  private ensureHeapSize(frames: number) {
    if (frames > this.heapSizeFrames) {
      if (this.inputHeapPtr) this.rubberBand.module._free(this.inputHeapPtr);
      if (this.outputHeapPtr) this.rubberBand.module._free(this.outputHeapPtr);

      this.inputHeapPtr = this.rubberBand.module._malloc(frames * 4);
      this.outputHeapPtr = this.rubberBand.module._malloc(frames * 4);
      this.heapSizeFrames = frames;
    }
  }
}

registerProcessor('RubberBandProcessor', RubberBandProcessor);

import { getPhonemeDataAtSample } from "./phonemeData";

interface Grain {
  phase: number;
  start: number;
  size: number;
  active: boolean;
}

export interface FrozenGrainParams {
  rubberBand: any;
  ensureHeapSize: (frames: number) => void;
  getInputHeapPtr: () => number;
  fullSampleBuffer: Float32Array | null;
  sampleRate: number;
  phonemeData: Float32Array | null;
  phonemeRatios: number[] | null;
  currentSamplePtr: number;
  startSamplePtr: number;
  endSamplePtr: number;
  duckingScalar: number;
  envelopeValue: number;
  grainJitterParam: number;
  grainEnvDepth: number;
  windowShape: number;
  grainLfoDepth: number;
  grainPosLfoDepth: number;
  samplesRequired: number;
  velocity: number;
}

/**
 * Spectral granulator used while the sample is frozen: loops a short,
 * windowed, jitterable grain (with 50% overlap between two voices) instead
 * of advancing the streaming pointer. Also owns the grain-triggered stereo
 * pan spread applied post-retrieve.
 */
export class GranularEngine {
  private readonly phonemeTuple = new Float32Array(9);
  private grains: [Grain, Grain] = [
    { phase: 0, start: 0, size: 0, active: false },
    { phase: 0, start: 0, size: 0, active: false }
  ];
  private customWindowShape: Float32Array | null = null;
  private customGrainEnvelope: number[] | null = null;
  private grainLpState = 0;
  private freezeLfoPhase = 0;
  private grainLfoPhase = 0;
  private wasFrozen = false;

  grainWrapPending = false;
  grainPanL: [number, number, number] = [Math.SQRT1_2, Math.SQRT1_2, Math.SQRT1_2];
  grainPanR: [number, number, number] = [Math.SQRT1_2, Math.SQRT1_2, Math.SQRT1_2];

  setCustomWindowShape(shape: Float32Array | null): void {
    this.customWindowShape = shape;
  }

  setCustomGrainEnvelope(shape: number[] | null): void {
    this.customGrainEnvelope = shape;
  }

  advanceLfoPhases(freezeLfoRate: number, grainLfoRate: number, sampleRate: number, framesInBlock: number): void {
    this.freezeLfoPhase += (2 * Math.PI * freezeLfoRate * framesInBlock) / sampleRate;
    if (this.freezeLfoPhase > 2 * Math.PI) {
      this.freezeLfoPhase -= 2 * Math.PI;
    }

    this.grainLfoPhase += (2 * Math.PI * grainLfoRate * framesInBlock) / sampleRate;
    if (this.grainLfoPhase > 2 * Math.PI) {
      this.grainLfoPhase -= 2 * Math.PI;
    }
  }

  getFreezeLfoValue(): number {
    return Math.sin(this.freezeLfoPhase);
  }

  enterFreeze(): void {
    if (!this.wasFrozen) {
      this.grainWrapPending = true;
    }
    this.wasFrozen = true;
  }

  /** Returns true if this call represents a frozen -> unfrozen transition. */
  exitFreeze(): boolean {
    this.grains[0].active = false;
    this.grains[1].active = false; // Reset phase when unfreezing
    if (this.wasFrozen) {
      this.grainWrapPending = false;
      this.wasFrozen = false;
      // Restore dual-mono on unfreeze
      this.grainPanL.fill(Math.SQRT1_2);
      this.grainPanR.fill(Math.SQRT1_2);
      return true;
    }
    return false;
  }

  updateGrainPan(grainPanSpread: number, isVowel: number): void {
    if (grainPanSpread > 0 && this.grainWrapPending) {
      this.grainWrapPending = false;
      const finalPanSpread = isVowel > 0 ? grainPanSpread : grainPanSpread * 0.3;

      // Pseudo-spiral LFO path mixed with random jitter for spectral bands
      const lfoPhase = this.grainLfoPhase;
      const phases = [
        lfoPhase,             // Band 0 follows cos(phase)
        lfoPhase - Math.PI / 2, // Band 1 follows sin(phase) (which is cos(phase - pi/2))
        lfoPhase + Math.PI / 4  // Band 2 offset
      ];

      for (let b = 0; b < 3; b++) {
        const spreadMod = b === 0 ? 0.4 : b === 1 ? 0.8 : 1.2;
        // Base LFO position between -1 and 1
        const lfoPos = Math.cos(phases[b]);

        // Add random jitter based on spread
        const jitter = (Math.random() * 2 - 1) * 0.2;

        // Combine LFO and jitter, clamped between -1 and 1, scaled by finalPanSpread
        const pan = Math.max(-1.0, Math.min(1.0, lfoPos + jitter)) * Math.min(1.0, finalPanSpread * spreadMod);

        const angle = ((pan + 1.0) * 0.5) * Math.PI / 2;
        this.grainPanL[b] = Math.cos(angle);
        this.grainPanR[b] = Math.sin(angle);
      }
    } else if (grainPanSpread === 0) {
      this.grainPanL.fill(Math.SQRT1_2);
      this.grainPanR.fill(Math.SQRT1_2);
    }
  }

  private initGrain(g: Grain, p: FrozenGrainParams, baseGrainSize: number, lfoMod: number, maxJitterSamples: number, posMod: number, sliceStart: number, sliceEnd: number, bufLength: number) {
    const duckedGrainSize = baseGrainSize * (1.0 - (p.duckingScalar * 0.5));
    const grainSizeSamplesActive = Math.max(100, Math.floor(duckedGrainSize * lfoMod * (1.0 - p.grainEnvDepth * p.envelopeValue)));
    const jitterOffsetActive = maxJitterSamples > 0 ? Math.floor((Math.random() * 2 - 1) * maxJitterSamples) : 0;
    const rawCenter = p.currentSamplePtr + jitterOffsetActive + posMod;
    const clampedCenter = Math.max(
      sliceStart + Math.floor(grainSizeSamplesActive / 2),
      Math.min(sliceEnd - Math.floor(grainSizeSamplesActive / 2), rawCenter)
    );
    const grainCenterActive = clampedCenter;
    g.start = Math.max(0, Math.min(bufLength - grainSizeSamplesActive, grainCenterActive - Math.floor(grainSizeSamplesActive / 2)));
    g.size = Math.min(bufLength, g.start + grainSizeSamplesActive) - g.start;
    g.phase = 0;
    g.active = g.size > 0;
  }

  renderFrozenBlock(p: FrozenGrainParams): void {
    if (p.samplesRequired <= 0) {
      return;
    }

    const samplesToFeed = p.samplesRequired;
    p.ensureHeapSize(samplesToFeed);

    const heap = p.rubberBand.module.HEAPF32;
    const ptr = p.getInputHeapPtr() >> 2;
    const buf = p.fullSampleBuffer;
    if (!buf) return;
    const sRate = p.sampleRate;

    // Define grain size: ~100ms
    let baseGrainSize = Math.floor(sRate * 0.1);

    // Scale grain jitter based on note velocity:
    // Lower velocity = more jitter, higher velocity = less jitter.
    // Velocity of 1.0 = normal jitter. Velocity < 1.0 increases it.
    const velocityJitterScale = Math.max(1.0, 1.5 - p.velocity * 0.5);

    let grainJitter = Math.min(1.0, p.grainJitterParam * velocityJitterScale);

    // Check for per-phoneme overrides
    if (p.phonemeData && p.phonemeRatios) {
      const pData = getPhonemeDataAtSample(p.phonemeData, p.phonemeRatios, p.currentSamplePtr, this.phonemeTuple);
      const pGrainJitter = pData[5];
      const pGrainSize = pData[6];
      if (pGrainJitter !== -1.0) {
        grainJitter = Math.min(1.0, pGrainJitter * velocityJitterScale);
      }
      if (pGrainSize !== -1.0) {
        baseGrainSize = Math.floor(sRate * (pGrainSize / 1000));
      }
    }

    const grainLfoValue = Math.sin(this.grainLfoPhase);
    // Apply unipolar LFO modulation to grain size (reduces size)
    const lfoMod = 1.0 - (p.grainLfoDepth * ((grainLfoValue + 1) * 0.5));

    // Position oscillation based on bipolar grainLfoValue
    const maxPosScanSamples = Math.floor(0.25 * sRate); // Max scan +/-250ms
    const hasActiveSlice = p.endSamplePtr > p.startSamplePtr;
    const sliceStart = hasActiveSlice ? p.startSamplePtr : 0;
    const sliceEnd = hasActiveSlice ? p.endSamplePtr : buf.length;
    const sliceLengthSamples = Math.max(0, sliceEnd - sliceStart);
    const allowedScanSamples = Math.min(maxPosScanSamples, Math.floor(sliceLengthSamples * 0.5));
    const posMod = Math.floor(grainLfoValue * p.grainPosLfoDepth * allowedScanSamples);

    const maxJitterSamples = Math.floor(0.05 * sRate * grainJitter);

    // Ensure at least one grain is active
    if (!this.grains[0].active && !this.grains[1].active) {
      this.initGrain(this.grains[0], p, baseGrainSize, lfoMod, maxJitterSamples, posMod, sliceStart, sliceEnd, buf.length);
    }

    const hasActiveGrain = this.grains[0].active || this.grains[1].active;

    if (hasActiveGrain) {
      // Map TTS syllable volume directly to filter cutoff in the granular engine
      let cutoff = 20000; // default bypassed
      if (p.phonemeData && p.phonemeRatios) {
        const pData = getPhonemeDataAtSample(p.phonemeData, p.phonemeRatios, p.currentSamplePtr, this.phonemeTuple);
        const pVol = pData[1];
        if (pVol < 1.0) {
          // Map volume [0, 1] to cutoff frequency [200, 20000] exponentially
          cutoff = 200 * Math.pow(100, pVol);
        }
      }

      // 1-pole IIR lowpass coefficients
      const dt = 1.0 / sRate;
      const rc = 1.0 / (2.0 * Math.PI * cutoff);
      const alpha = dt / (rc + dt);

      for (let i = 0; i < samplesToFeed; i++) {
        let sampleVal = 0;
        for (let gIdx = 0; gIdx < 2; gIdx++) {
          const g = this.grains[gIdx];
          if (g.active) {
            const phase = g.phase / (g.size - 1);
            let windowVal = 1.0;

            if (this.customWindowShape && this.customWindowShape.length > 0) {
              const index = phase * (this.customWindowShape.length - 1);
              const lower = Math.floor(index);
              const upper = Math.ceil(index);
              const weight = index - lower;
              windowVal = this.customWindowShape[lower] * (1 - weight) + this.customWindowShape[upper] * weight;
            } else if (this.customGrainEnvelope && this.customGrainEnvelope.length > 0) {
              const idx = phase * (this.customGrainEnvelope.length - 1);
              const lowerIdx = Math.floor(idx);
              const upperIdx = Math.ceil(idx);
              const fraction = idx - lowerIdx;

              const lowerVal = this.customGrainEnvelope[lowerIdx];
              const upperVal = this.customGrainEnvelope[upperIdx];

              windowVal = lowerVal + (upperVal - lowerVal) * fraction;
            } else {
              // 0: Hann, 1: Hamming, 2: Blackman, 3: Rectangular (None), 4: Gaussian, 5: Sharp Exponential
              if (p.windowShape < 0.5) {
                windowVal = 0.5 * (1 - Math.cos(2 * Math.PI * phase));
              } else if (p.windowShape < 1.5) {
                windowVal = 0.54 - 0.46 * Math.cos(2 * Math.PI * phase);
              } else if (p.windowShape < 2.5) {
                windowVal = 0.42 - 0.5 * Math.cos(2 * Math.PI * phase) + 0.08 * Math.cos(4 * Math.PI * phase);
              } else if (p.windowShape < 3.5) {
                windowVal = 1.0;
              } else if (p.windowShape < 4.5) {
                windowVal = Math.exp(-0.5 * Math.pow((phase - 0.5) / 0.15, 2));
              } else {
                windowVal = Math.pow(Math.sin(Math.PI * phase), 4);
              }
            }

            sampleVal += buf[g.start + g.phase] * windowVal;
            g.phase++;

            // Check if we should start the other grain (50% overlap)
            const otherIdx = gIdx === 0 ? 1 : 0;
            const otherG = this.grains[otherIdx];
            if (g.phase === Math.floor(g.size / 2) && !otherG.active) {
              this.initGrain(otherG, p, baseGrainSize, lfoMod, maxJitterSamples, posMod, sliceStart, sliceEnd, buf.length);
            }

            if (g.phase >= g.size) {
              g.active = false;
              if (gIdx === 0) {
                // Only trigger grain wrap panning when the primary grain finishes
                // to avoid double triggers that flutter the stereo field too much
                this.grainWrapPending = true;
              }
            }
          }
        }

        // Apply 1-pole lowpass filter to the combined grain signal
        this.grainLpState += alpha * (sampleVal - this.grainLpState);
        heap[ptr + i] = this.grainLpState;
      }
      p.rubberBand.process(p.getInputHeapPtr(), samplesToFeed, false);
    } else {
      // Fallback if grain is empty
      p.rubberBand.process(p.getInputHeapPtr(), 0, false);
    }
  }
}

import { RingBuffer } from "../utils/ringBuffer";
import { resolveWorkletSampleRate } from "../utils/workletSampleRate";
// @ts-ignore - The file is generated by the build script
import createRubberBandModule from "./rubberband-lib.js";

interface AudioWorkletProcessor {
  readonly port: MessagePort;
  process(inputs: Float32Array[][], outputs: Float32Array[][], parameters: Record<string, Float32Array>): boolean;
}

declare var AudioWorkletProcessor: {
  prototype: AudioWorkletProcessor;
  new (options?: any): AudioWorkletProcessor;
};

declare function registerProcessor(name: string, processorCtor: (new (options?: any) => AudioWorkletProcessor)): void;

declare const globalThis: {
  sampleRate: number;
};

// --- LCG (Linear Congruential Generator) Constants ---
// Standard parameters for GC-free pseudo-random number generation
const LCG_MULTIPLIER = 1103515245;
const LCG_INCREMENT = 12345;
const LCG_MODULUS = 0x7FFFFFFF;

class SustainProcessor extends AudioWorkletProcessor {
    private buffer: Float32Array | null = null;

    // Playback State
    private playhead = 0;
    private isPlaying = false;
    private basePitch = 1.0; // The pitch of the sample

    // Arpeggiator State
    private arpCounter = 0;     // Counts samples
    private arpStepIndex = 0;   // Which step of the pattern are we on?
    private arpPattern: number[] = [0, 4, 7, 12]; // Default: Major Triad + Octave (semitones)

    // Parameters
    private loopStart = 0;
    private loopEnd = 0;
    private grainSize = 4410; // Default grain size (~100ms at 44.1kHz)
    private grainOverlap = 0.5; // Overlap factor for smoother stretching

    // Wavetable
    private baseFrequency = 220; // Base Hz before pitch offsets

    // Stretch mode state (for crossfade grains)
    private grainPhase = 0;

    // Pre-computed zero-crossing positions (optional optimization)
    private zeroCrossings: Int32Array | null = null;

    // Rubber Band Integration
    private rubberBand: any = null;
    private inputRingBuffer: RingBuffer | null = null;
    private outputRingBuffer: RingBuffer | null = null;
    private inputHeapPtr: number = 0;
    private outputHeapPtr: number = 0;
    private heapSizeFrames: number = 0;
    private rubberBandInitialized = false;
    private useRubberBand = false; // Enable/disable Rubber Band mode

    constructor() {
        super();

        // Message handler for receiving buffer and settings
        this.port.onmessage = async (event: MessageEvent) => {
            const { type, data } = event.data;

            switch (type) {
                case 'INIT_WASM':
                    try {
                        // Initialize Rubber Band WASM module
                        const { inputBuffer, outputBuffer, wasmBinary } = event.data;

                        this.inputRingBuffer = new RingBuffer(inputBuffer);
                        this.outputRingBuffer = new RingBuffer(outputBuffer);

                        if (!wasmBinary) {
                            throw new Error("WASM binary not provided in INIT_WASM message");
                        }

                        // @ts-ignore
                        const module = await createRubberBandModule({
                            wasmBinary: wasmBinary,
                            locateFile: (path: string) => {
                                if (path.endsWith('.wasm')) return import.meta.env.BASE_URL + 'rubberband.wasm';
                                return path;
                            }
                        });

                        const safeSampleRate = Math.floor(resolveWorkletSampleRate());

                        // RealTime (1) | Finer (32) | FormantPreserved (1048576)
                        const options = 1 | 32 | 1048576;

                        this.rubberBand = new module.RubberBandStretcher(
                            safeSampleRate,
                            1, // Mono
                            options,
                            1.0, // Initial Time Ratio
                            1.0  // Initial Pitch Scale
                        );

                        this.rubberBand.module = module;
                        this.rubberBandInitialized = true;
                        this.port.postMessage({ type: 'READY' });
                    } catch (e) {
                        console.error("RubberBand WASM Failed:", e);
                        this.port.postMessage({ type: 'ERROR', error: String(e) });
                    }
                    break;

                case 'loadBuffer':
                    this.buffer = new Float32Array(data.buffer);
                    this.loopEnd = this.buffer.length;
                    this.loopStart = 0;
                    this.playhead = 0;
                    // Pre-compute zero crossings for this buffer
                    this.zeroCrossings = this.findZeroCrossings(this.buffer);
                    break;

                case 'setLoopPoints':
                    this.loopStart = data.start || 0;
                    this.loopEnd = data.end || (this.buffer ? this.buffer.length : 0);
                    break;

                case 'setArpPattern':
                    this.arpPattern = data.pattern || [0, 4, 7, 12];
                    this.arpStepIndex = 0;
                    break;

                case 'noteOn':
                    this.isPlaying = true;
                    this.playhead = this.loopStart;
                    this.basePitch = data.pitch || 1.0;
                    this.grainPhase = 0;

                    // If Rubber Band is initialized and enabled, feed the buffer to it
                    if (this.useRubberBand && this.rubberBandInitialized && this.rubberBand && this.buffer) {
                        this.rubberBand.reset();
                        this.rubberBand.setPitchScale(data.pitch || 1.0);
                        this.rubberBand.setTimeRatio(1.0);

                        // Support for slicing
                        const startSample = Math.max(0, Math.floor(this.loopStart));
                        const endSample = Math.min(this.buffer.length, Math.floor(this.loopEnd));

                        if (startSample < endSample) {
                            const sliceLength = endSample - startSample;
                            this.ensureHeapSize(sliceLength);

                            const heap = this.rubberBand.module.HEAPF32;
                            const ptr = this.inputHeapPtr >> 2;
                            for (let i = 0; i < sliceLength; i++) {
                                heap[ptr + i] = this.buffer[startSample + i];
                            }
                            this.rubberBand.process(this.inputHeapPtr, sliceLength, false);
                        }
                    }
                    break;

                case 'noteOff':
                    this.isPlaying = false;
                    break;

                case 'setGrainSize':
                    this.grainSize = data.size || 4410;
                    break;

                case 'enableRubberBand':
                    this.useRubberBand = data.enabled || false;
                    break;
            }
        };
    }

    static get parameterDescriptors() {
        return [
            { name: 'mode', defaultValue: 0, minValue: 0, maxValue: 3 }, // 0=LOOP, 1=STRETCH, 2=WAVETABLE, 3=RUBBERBAND
            { name: 'bpm', defaultValue: 120, minValue: 20, maxValue: 300 },
            { name: 'arp', defaultValue: 0, minValue: 0, maxValue: 1 }, // 0 = Off, 1 = On
            { name: 'pitch', defaultValue: 1.0, minValue: 0.25, maxValue: 4.0 },
            { name: 'frequency', defaultValue: 220, minValue: 20, maxValue: 20000 }
        ];
    }

    /**
     * Find zero-crossing positions in the buffer for clean loop points.
     * Uses a simple positive-going zero-crossing detection.
     */
    private findZeroCrossings(buffer: Float32Array): Int32Array {
        // Pre-allocate array (estimate ~sampleRate/100 crossings per second for typical audio)
        const crossings: number[] = [];
        for (let i = 1; i < buffer.length; i++) {
            if (buffer[i] >= 0 && buffer[i - 1] < 0) {
                crossings.push(i);
            }
        }
        return new Int32Array(crossings);
    }

    /**
     * Find the nearest zero-crossing to a given position.
     * Uses binary search for efficiency.
     */
    private findNearestZeroCrossing(position: number): number {
        if (!this.zeroCrossings || this.zeroCrossings.length === 0) {
            return Math.floor(position);
        }

        // Binary search for nearest zero crossing
        let low = 0;
        let high = this.zeroCrossings.length - 1;

        while (low < high) {
            const mid = (low + high) >>> 1;
            if (this.zeroCrossings[mid] < position) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        // Check which of the two closest is nearer
        if (low > 0) {
            const prev = this.zeroCrossings[low - 1];
            const curr = this.zeroCrossings[low];
            if (Math.abs(position - prev) < Math.abs(position - curr)) {
                return prev;
            }
        }

        return this.zeroCrossings[low] || Math.floor(position);
    }

    /**
     * Linear Interpolation for high-quality pitch/stretch.
     * Prevents aliasing at non-integer playback rates.
     */
    private getInterpolatedSample(position: number): number {
        if (!this.buffer || this.buffer.length === 0) return 0;

        const indexA = Math.floor(position);
        const indexB = indexA + 1;
        const fraction = position - indexA;

        // Safety check
        if (indexA < 0 || indexA >= this.buffer.length) return 0;

        const valA = this.buffer[indexA];
        const valB = (indexB < this.buffer.length) ? this.buffer[indexB] : 0;

        return valA + (valB - valA) * fraction;
    }

    /**
     * Generate a random position within the grain window for stretch mode.
     * Uses a simple LCG for GC-free random numbers.
     */
    private getStretchJumpPosition(): number {
        // LCG for deterministic randomness without GC
        this.grainPhase = (this.grainPhase * LCG_MULTIPLIER + LCG_INCREMENT) & LCG_MODULUS;
        const randomFactor = (this.grainPhase / LCG_MODULUS);

        // Jump to a position within the grain window
        const windowSize = this.grainSize * this.grainOverlap;
        return this.loopStart + (randomFactor * windowSize);
    }

    /**
     * Ensure WASM heap has enough space allocated for Rubber Band processing.
     */
    private ensureHeapSize(frames: number) {
        if (!this.rubberBand) return;

        if (frames > this.heapSizeFrames) {
            if (this.inputHeapPtr) this.rubberBand.module._free(this.inputHeapPtr);
            if (this.outputHeapPtr) this.rubberBand.module._free(this.outputHeapPtr);

            this.inputHeapPtr = this.rubberBand.module._malloc(frames * 4);
            this.outputHeapPtr = this.rubberBand.module._malloc(frames * 4);
            this.heapSizeFrames = frames;
        }
    }

    process(_inputs: Float32Array[][], outputs: Float32Array[][], parameters: Record<string, Float32Array>): boolean {
        const output = outputs[0];
        if (!output || output.length === 0) return true;

        const bpmParam = parameters['bpm'];
        const arpParam = parameters['arp'];
        const modeParam = parameters['mode'];
        const pitchParam = parameters['pitch'];
        const freqParam = parameters['frequency'];

        const arpConstant = arpParam.length === 1;
        // modeParam length check not needed - we read mode directly below
        const pitchConstant = pitchParam.length === 1;
        const freqConstant = freqParam.length === 1;
        const bpmConstant = bpmParam.length === 1;

        const blockSize = output[0].length;
        // Use global sampleRate or fallback
        const currentSampleRate = resolveWorkletSampleRate();

        // Get mode once for the entire block
        const mode = modeParam[0];

        // --- MODE D: RUBBERBAND (high-quality pitch shifting) ---
        // Mode 3 (value >= 2.5 to handle float parameter values between modes)
        if (mode >= 2.5 && this.rubberBandInitialized && this.rubberBand && this.inputRingBuffer && this.outputRingBuffer) {
            const outputChannel = output[0];
            const currentPitch = pitchParam[0];

            this.rubberBand.setPitchScale(currentPitch);
            this.rubberBand.setTimeRatio(1.0);

            try {
                const required = this.rubberBand.getSamplesRequired();
                const available = this.inputRingBuffer.availableRead();

                if (available >= required && required > 0) {
                    this.ensureHeapSize(required);
                    this.inputRingBuffer.pull(this.rubberBand.module.HEAPF32, this.inputHeapPtr >> 2);
                    this.rubberBand.process(this.inputHeapPtr, required, false);
                }

                const availOutput = this.rubberBand.available();
                if (availOutput > 0) {
                    const framesToRead = Math.min(availOutput, 128);
                    this.ensureHeapSize(framesToRead);

                    const retrieved = this.rubberBand.retrieve(this.outputHeapPtr, framesToRead);

                    const heap = this.rubberBand.module.HEAPF32;
                    const ptr = this.outputHeapPtr >> 2;
                    const limit = Math.min(retrieved, blockSize);
                    for(let i=0; i<limit; i++) {
                        outputChannel[i] = heap[ptr + i];
                    }

                    // Copy to all channels
                    for (let channel = 1; channel < output.length; channel++) {
                        output[channel].set(outputChannel);
                    }
                }
            } catch (e) {
                console.error("Rubber Band DSP Error:", e);
            }

            return true;
        }

        // --- ORIGINAL MODES (LOOP, STRETCH, WAVETABLE) ---
        for (let i = 0; i < blockSize; i++) {
            const arpOn = (arpConstant ? arpParam[0] : arpParam[i]) > 0.5;
            const currentPitch = pitchConstant ? pitchParam[0] : pitchParam[i];
            const currentFreq = freqConstant ? freqParam[0] : freqParam[i];
            const currentBpm = bpmConstant ? bpmParam[0] : bpmParam[i];

            // --- ARPEGGIATOR LOGIC ---
            if (arpOn && this.buffer) {
                const samplesPerStep = (currentSampleRate * 60) / (currentBpm * 4);
                this.arpCounter++;

                if (this.arpCounter >= samplesPerStep) {
                    this.arpCounter = 0;
                    const semiTone = this.arpPattern[this.arpStepIndex % this.arpPattern.length];
                    this.basePitch = Math.pow(2, semiTone / 12.0);
                    this.playhead = this.loopStart;
                    this.isPlaying = true;
                    this.arpStepIndex++;
                }
            }

            if (!this.buffer || !this.isPlaying) {
                for (let channel = 0; channel < output.length; channel++) {
                    output[channel][i] = 0;
                }
                continue;
            }

            let sampleValue = 0;

            if (mode < 0.5) {
                // --- MODE A: LOOP ---
                sampleValue = this.getInterpolatedSample(this.playhead);
                const speed = arpOn ? this.basePitch : (currentPitch || 1.0);
                this.playhead += speed;

                if (this.playhead >= this.loopEnd) {
                    const alignedStart = this.findNearestZeroCrossing(this.loopStart);
                    this.playhead = alignedStart;
                }
            } else if (mode < 1.5) {
                // --- MODE B: STRETCH (Granular Freeze) ---
                sampleValue = this.getInterpolatedSample(this.playhead);
                const speed = arpOn ? this.basePitch : (currentPitch || 1.0);
                this.playhead += speed;

                const freezeLimit = this.loopStart + this.grainSize;
                if (this.playhead >= freezeLimit) {
                    this.playhead = this.getStretchJumpPosition();
                }
            } else {
                // --- MODE C: WAVETABLE (single-cycle oscillator) ---
                const bufferLength = this.buffer.length;
                const phase = this.playhead % bufferLength;
                sampleValue = this.getInterpolatedSample(phase);

                const pitchRatio = arpOn ? this.basePitch : (currentPitch || 1.0);
                const targetFreq = (currentFreq || this.baseFrequency) * pitchRatio;
                const increment = (targetFreq * bufferLength) / currentSampleRate;
                this.playhead += increment;

                if (this.playhead >= bufferLength) {
                    // Maintain precision by wrapping instead of letting it grow
                    this.playhead = this.playhead % bufferLength;
                }
            }

            for (let channel = 0; channel < output.length; channel++) {
                output[channel][i] = sampleValue;
            }
        }

        return true;
    }
}

