/**
 * Patch serialization and the live PatchController.
 *
 * The persistence tests treat stored graphs as hostile input: they come from
 * localStorage and shared song files, so a malformed patch must degrade to the
 * preset rather than reaching the compiler.
 */

import { describe, expect, it, vi } from 'vitest';

import {
    CLASSIC_ELECTRIBE_GRAPH,
    GRAPH_SCHEMA_VERSION,
    PatchController,
    addConnection,
    buildPreset,
    compileAudioGraph,
    deserializeAudioGraph,
    graphsEqual,
    parseAudioGraphConfig,
    restorePatchFromSong,
    serializeAudioGraph,
    setActivePatchController,
    getActivePatchController,
} from '../index';
import type { AudioGraphConfig } from '../types';

describe('serialization', () => {
    it('stores only the preset id when the patch is stock', () => {
        const preset = buildPreset('classic-electribe');
        const stored = serializeAudioGraph(preset, false);
        expect(stored).toEqual({
            schemaVersion: GRAPH_SCHEMA_VERSION,
            presetId: 'classic-electribe',
        });
        expect(JSON.stringify(stored).length).toBeLessThan(120);
    });

    it('round-trips a modified patch without losing sends', () => {
        const edited = addConnection(buildPreset('classic-electribe'), 'synthABus', 'reverbHall', {
            gain: 0.42,
        }).config;

        const stored = JSON.parse(JSON.stringify(serializeAudioGraph(edited, true)));
        const { graph, presetId } = deserializeAudioGraph(stored, 'classic-electribe');

        expect(presetId).toBe('classic-electribe');
        expect(graph).not.toBeNull();
        expect(graphsEqual(graph!, edited)).toBe(true);
        expect(graph!.edges.find((e) => e.to === 'reverbHall' && e.from === 'synthABus')?.gain).toBe(
            0.42,
        );
    });

    it('round-trips the classic graph unchanged', () => {
        const stored = JSON.parse(JSON.stringify(serializeAudioGraph(CLASSIC_ELECTRIBE_GRAPH, true)));
        const { graph } = deserializeAudioGraph(stored, 'classic-electribe');
        expect(graphsEqual(graph!, CLASSIC_ELECTRIBE_GRAPH)).toBe(true);
        // Compiled routing must be identical too, not just structurally equal.
        const fromStored = compileAudioGraph(new AudioContext(), graph!);
        const fromSource = compileAudioGraph(new AudioContext(), CLASSIC_ELECTRIBE_GRAPH);
        expect(fromStored.connectionLog).toEqual(fromSource.connectionLog);
    });

    it('rejects malformed graphs instead of passing them to the compiler', () => {
        expect(parseAudioGraphConfig(null)).toBeNull();
        expect(parseAudioGraphConfig({ id: 'x', name: 'y' })).toBeNull();
        expect(
            parseAudioGraphConfig({ id: 'x', name: 'y', nodes: [{ id: 'a' }], edges: [] }),
        ).toBeNull();
        expect(
            parseAudioGraphConfig({
                id: 'x',
                name: 'y',
                nodes: [{ id: 'a', factory: 'evil-node' }],
                edges: [],
            }),
        ).toBeNull();
        // Structurally parseable but cyclic — still refused.
        expect(
            parseAudioGraphConfig({
                id: 'x',
                name: 'y',
                nodes: [
                    { id: 'a', factory: 'gain' },
                    { id: 'b', factory: 'gain' },
                ],
                edges: [
                    { from: 'a', to: 'b' },
                    { from: 'b', to: 'a' },
                    { from: 'b', to: 'destination' },
                ],
            }),
        ).toBeNull();
    });

    it('falls back to the preset for a future schema version', () => {
        const stored = { schemaVersion: GRAPH_SCHEMA_VERSION + 1, presetId: 'classic-electribe', graph: {} };
        expect(deserializeAudioGraph(stored, 'classic-electribe').graph).toBeNull();
    });

    it('survives undefined and junk', () => {
        expect(deserializeAudioGraph(undefined, 'classic-electribe')).toEqual({
            presetId: 'classic-electribe',
            graph: null,
        });
        expect(deserializeAudioGraph('nonsense', 'classic-electribe').graph).toBeNull();
    });
});

describe('restorePatchFromSong', () => {
    it('publishes a controller when the engine has not started yet', () => {
        setActivePatchController(null);
        const result = restorePatchFromSong(undefined);
        expect(getActivePatchController()).not.toBeNull();
        expect(result.config.presetId).toBe('classic-electribe');
        expect(result.fellBack).toBe(false);
        setActivePatchController(null);
    });

    it('reports a fallback when the stored patch was unusable', () => {
        setActivePatchController(null);
        const result = restorePatchFromSong({
            schemaVersion: GRAPH_SCHEMA_VERSION,
            presetId: 'classic-electribe',
            graph: { id: 'broken' } as unknown as AudioGraphConfig,
        });
        expect(result.fellBack).toBe(true);
        expect(result.config.presetId).toBe('classic-electribe');
        setActivePatchController(null);
    });

    it('replaces the config on an already-running controller', () => {
        const controller = new PatchController(buildPreset('classic-electribe'));
        setActivePatchController(controller);

        const edited = addConnection(buildPreset('classic-electribe'), 'synthBBus', 'delay', {
            gain: 0.3,
        }).config;
        const result = restorePatchFromSong(serializeAudioGraph(edited, true));

        expect(result.requiresRebuild).toBe(true);
        expect(controller.getConfig().edges.some((e) => e.from === 'synthBBus' && e.to === 'delay')).toBe(
            true,
        );
        setActivePatchController(null);
    });
});

/** Tracking stand-in for the live audio graph. */
function fakeCompiled() {
    const connections: string[] = [];
    const disconnections: string[] = [];
    const make = (id: string) => ({
        id,
        connect: (target: { id: string }) => connections.push(`${id}->${target.id}`),
        disconnect: (target?: { id: string }) =>
            disconnections.push(target ? `${id}->${target.id}` : `${id}->*`),
    });
    const nodes = new Map<string, ReturnType<typeof make>>();
    for (const id of ['synthABus', 'reverbPlate', 'masterGain']) nodes.set(id, make(id));

    const gainNodes: Array<{ id: string; gain: { value: number } }> = [];
    const context = {
        currentTime: 0,
        createGain: () => {
            const node = {
                ...make(`send${gainNodes.length}`),
                gain: {
                    value: 1,
                    setValueAtTime(value: number) {
                        this.value = value;
                    },
                    cancelScheduledValues: vi.fn(),
                    linearRampToValueAtTime(value: number) {
                        this.value = value;
                    },
                },
            };
            gainNodes.push(node as never);
            return node;
        },
        destination: make('destination'),
    } as unknown as AudioContext;

    const compiled = {
        nodes: nodes as unknown as ReadonlyMap<string, AudioNode>,
        sendGains: new Map<string, GainNode>(),
    } as never;

    return { context, compiled, connections, disconnections, gainNodes };
}

describe('PatchController live editing', () => {
    it('patches a send into the running graph without a rebuild', () => {
        const preset = buildPreset('classic-electribe');
        const controller = new PatchController(preset, preset);
        const { context, compiled, connections } = fakeCompiled();
        controller.attach(context, compiled);

        const outcome = controller.connect('synthABus', 'reverbPlate', 0.5);

        expect(outcome.ok).toBe(true);
        expect(outcome.requiresRebuild).toBeUndefined();
        expect(controller.needsRebuild()).toBe(false);
        // Routed through an implicit send gain: source → send → target.
        expect(connections).toContain('synthABus->send0');
        expect(connections).toContain('send0->reverbPlate');
        expect(controller.isModified()).toBe(true);
    });

    it('refuses a cycle and leaves the live graph alone', () => {
        const preset = buildPreset('classic-electribe');
        const controller = new PatchController(preset, preset);
        const { context, compiled, connections } = fakeCompiled();
        controller.attach(context, compiled);

        const outcome = controller.connect('masterPanner', 'masterGain');
        expect(outcome.ok).toBe(false);
        expect(outcome.rejected?.code).toBe('cycle');
        expect(connections).toHaveLength(0);
        expect(controller.isModified()).toBe(false);
    });

    it('rides a send level on the live gain node', () => {
        const preset = buildPreset('classic-electribe');
        const controller = new PatchController(preset, preset);
        const { context, compiled, gainNodes } = fakeCompiled();
        controller.attach(context, compiled);
        controller.connect('synthABus', 'reverbPlate', 0.5);

        const outcome = controller.setSendLevel('synthABus', 'reverbPlate', 0.8);
        expect(outcome.ok).toBe(true);
        expect(outcome.requiresRebuild).toBeUndefined();
        expect(gainNodes[0].gain.value).toBeCloseTo(0.8, 5);
    });

    it('tears down the send gain when unpatching', () => {
        const preset = buildPreset('classic-electribe');
        const controller = new PatchController(preset, preset);
        const { context, compiled, disconnections } = fakeCompiled();
        controller.attach(context, compiled);
        controller.connect('synthABus', 'reverbPlate', 0.5);

        expect(controller.disconnect('synthABus', 'reverbPlate').ok).toBe(true);
        expect(disconnections).toContain('synthABus->send0');
        expect(disconnections).toContain('send0->*');
        expect(controller.getConfig().edges.some((e) => e.to === 'reverbPlate' && e.from === 'synthABus')).toBe(
            false,
        );
    });

    it('stages node changes for the next rebuild', () => {
        const preset = buildPreset('classic-electribe');
        const controller = new PatchController(preset, preset);
        const { context, compiled } = fakeCompiled();
        controller.attach(context, compiled);

        const added = controller.addNode({ id: 'userDelay', factory: 'delay', label: 'Tape Delay' });
        expect(added.requiresRebuild).toBe(true);
        expect(controller.needsRebuild()).toBe(true);
        expect(controller.removeNode('masterGain').ok).toBe(false);
        expect(controller.removeNode('userDelay').ok).toBe(true);
    });

    it('detaching stops it from touching disposed nodes', () => {
        const preset = buildPreset('classic-electribe');
        const controller = new PatchController(preset, preset);
        const { context, compiled, connections } = fakeCompiled();
        controller.attach(context, compiled);
        controller.detach();

        const outcome = controller.connect('synthABus', 'reverbPlate', 0.5);
        expect(outcome.requiresRebuild).toBe(true);
        expect(connections).toHaveLength(0);
    });

    it('notifies subscribers on every committed edit', () => {
        const preset = buildPreset('classic-electribe');
        const controller = new PatchController(preset, preset);
        const seen: number[] = [];
        const unsubscribe = controller.subscribe((config) => seen.push(config.edges.length));

        const { context, compiled } = fakeCompiled();
        controller.attach(context, compiled);
        controller.connect('synthABus', 'reverbPlate', 0.5);
        controller.disconnect('synthABus', 'reverbPlate');
        unsubscribe();
        controller.connect('synthBBus', 'reverbPlate', 0.5);

        // Initial + add + remove, and nothing after unsubscribe.
        expect(seen).toHaveLength(3);
        expect(seen[1]).toBe(seen[0] + 1);
        expect(seen[2]).toBe(seen[0]);
    });
});

import { makeDistortionCurve } from '../../hooks/audioEngine/distortion';
import { createReverbImpulseResponse } from '../impulseResponses';
import { WamSlotPorts } from '../wam/WamSlotPorts';
import { assertSafeGraphCycles } from './cycleCheck';
import { edgeKey, validateGraph } from './graphOps';
import type {
    AnalyserConfig,
    AudioGraphConfig,
    BiquadFilterConfig,
    CompiledAudioGraph,
    ConvolverConfig,
    DelayConfig,
    DynamicsCompressorConfig,
    GainConfig,
    GraphConnectionRecord,
    GraphEdgeSpec,
    GraphNodeFactory,
    GraphNodeId,
    GraphNodeRole,
    GraphNodeSpec,
    GraphPortPair,
    StereoPannerConfig,
    TrackMonitorConfig,
    WaveShaperConfig,
} from './types';

export interface CompileGraphOptions {
    /** When false, skip masterPanner and connect masterGain → destination directly. */
    useStereoPanner?: boolean;
    createReverbImpulse?: (context: BaseAudioContext, preset: 'room' | 'plate' | 'hall') => AudioBuffer;
    /**
     * Supplies the master true-peak limiter / loudness-meter node.
     *
     * The stage is an AudioWorklet, so its module has to be loaded before the
     * graph is compiled — see `createMasterLoudnessStage`. Returning `null`
     * (the default) omits the node and bridges the chain straight to the
     * destination, so a browser that cannot register the worklet still plays.
     */
    createMasterLimiterNode?: (context: BaseAudioContext) => AudioNode | null;
    /**
     * Reject configs that fail `validateGraph` (cycles, dangling edges,
     * duplicate ids) instead of compiling them. On by default: a user-authored
     * patch must not be able to wire a runaway loop into the audio thread.
     * Disable only for tests that compile a deliberately partial subgraph.
     */
    validate?: boolean;
}

const DEFAULT_OPTIONS: Required<CompileGraphOptions> = {
    useStereoPanner: true,
    createMasterLimiterNode: () => null,
    validate: true,
    createReverbImpulse: (context, preset) => {
        switch (preset) {
            case 'room':
                return createReverbImpulseResponse(context, 0.5, 1.0);
            case 'plate':
                return createReverbImpulseResponse(context, 1.5, 2.0);
            case 'hall':
                return createReverbImpulseResponse(context, 3.5, 3.0);
        }
    },
};

function asConfig<T>(config: GraphNodeSpec['config']): T {
    return (config ?? {}) as T;
}

function createNode(
    context: BaseAudioContext,
    spec: GraphNodeSpec,
    options: Required<CompileGraphOptions>,
    analysers: Map<GraphNodeId, AnalyserNode>,
    ports: Map<GraphNodeId, GraphPortPair>,
): AudioNode | null {
    const { factory, id, config } = spec;

    switch (factory as GraphNodeFactory) {
        case 'waveShaper': {
            const cfg = asConfig<WaveShaperConfig>(config);
            const node = context.createWaveShaper();
            node.curve = makeDistortionCurve(cfg.drive ?? 0);
            node.oversample = cfg.oversample ?? '4x';
            return node;
        }
        case 'biquadFilter': {
            const cfg = asConfig<BiquadFilterConfig>(config);
            const node = context.createBiquadFilter();
            node.type = cfg.type;
            const t = context.currentTime;
            if (cfg.frequency !== undefined) {
                node.frequency.setValueAtTime(cfg.frequency, t);
            }
            if (cfg.Q !== undefined) {
                node.Q.setValueAtTime(cfg.Q, t);
            }
            if (cfg.gain !== undefined) {
                node.gain.setValueAtTime(cfg.gain, t);
            }
            return node;
        }
        case 'dynamicsCompressor': {
            const cfg = asConfig<DynamicsCompressorConfig>(config);
            const node = context.createDynamicsCompressor();
            const t = context.currentTime;
            if (cfg.threshold !== undefined) node.threshold.setValueAtTime(cfg.threshold, t);
            if (cfg.knee !== undefined) node.knee.setValueAtTime(cfg.knee, t);
            if (cfg.ratio !== undefined) node.ratio.setValueAtTime(cfg.ratio, t);
            if (cfg.attack !== undefined) node.attack.setValueAtTime(cfg.attack, t);
            if (cfg.release !== undefined) node.release.setValueAtTime(cfg.release, t);
            return node;
        }
        case 'gain': {
            const cfg = asConfig<GainConfig>(config);
            const node = context.createGain();
            node.gain.setValueAtTime(cfg.gain ?? 1, 0);
            return node;
        }
        case 'stereoPanner': {
            const cfg = asConfig<StereoPannerConfig>(config);
            if (!options.useStereoPanner || !context.createStereoPanner) {
                return null;
            }
            const node = context.createStereoPanner();
            node.pan.setValueAtTime(cfg.pan ?? 0, 0);
            return node;
        }
        case 'analyser': {
            const cfg = asConfig<AnalyserConfig>(config);
            const node = context.createAnalyser();
            if (cfg.fftSize !== undefined) node.fftSize = cfg.fftSize;
            if (cfg.smoothingTimeConstant !== undefined) {
                node.smoothingTimeConstant = cfg.smoothingTimeConstant;
            }
            return node;
        }
        case 'convolver': {
            const cfg = asConfig<ConvolverConfig>(config);
            const node = context.createConvolver();
            if (cfg.reverbPreset) {
                node.buffer = options.createReverbImpulse(context, cfg.reverbPreset);
            }
            return node;
        }
        case 'delay': {
            const cfg = asConfig<DelayConfig>(config);
            const node = context.createDelay(cfg.maxDelayTime ?? 2.0);
            node.delayTime.value = cfg.delayTime ?? 0.375;
            return node;
        }
        case 'trackMonitor': {
            const cfg = asConfig<TrackMonitorConfig>(config);
            const bus = context.createGain();
            bus.gain.value = cfg.busGain ?? 1;
            const analyser = context.createAnalyser();
            analyser.fftSize = cfg.analyserFftSize ?? 256;
            analyser.smoothingTimeConstant = cfg.analyserSmoothing ?? 0.55;
            bus.connect(analyser);
            analysers.set(id, analyser);
            return bus;
        }
        case 'masterLimiter':
            return options.createMasterLimiterNode(context);
        case 'destination':
            return context.destination;
        case 'wamInstrumentSlot':
        case 'wamTrackInsert':
        case 'wamMasterInsert':
        case 'wamSendReturn': {
            const slot = new WamSlotPorts(context);
            ports.set(id, { input: slot.input, output: slot.output, wamSlot: slot });
            return slot.output;
        }
        default:
            throw new Error(`Unknown graph node factory: ${factory}`);
    }
}

/**
 * Remove edges through nodes that were not compiled, splicing predecessor to
 * successor so the chain stays connected (used for the optional master limiter).
 * Edge order is preserved: the bridged edge takes the slot of the incoming one.
 */
function bridgeAbsentNodes(
    edges: readonly GraphEdgeSpec[],
    present: ReadonlySet<GraphNodeId>,
    optionalIds: readonly GraphNodeId[],
): GraphEdgeSpec[] {
    let result = [...edges];
    for (const id of optionalIds) {
        if (present.has(id)) continue;
        const successors = result.filter((edge) => edge.from === id).map((edge) => edge.to);
        const bridged: GraphEdgeSpec[] = [];
        for (const edge of result) {
            if (edge.from === id) continue;
            if (edge.to === id) {
                for (const to of successors) bridged.push({ from: edge.from, to });
                continue;
            }
            bridged.push(edge);
        }
        result = bridged;
    }
    return result;
}

function registerRole(
    roles: Map<GraphNodeRole, GraphNodeId | GraphNodeId[]>,
    role: GraphNodeRole,
    nodeId: GraphNodeId,
): void {
    const existing = roles.get(role);
    if (existing === undefined) {
        roles.set(role, nodeId);
        return;
    }
    if (Array.isArray(existing)) {
        existing.push(nodeId);
        return;
    }
    roles.set(role, [existing, nodeId]);
}

/**
 * Compile a declarative AudioGraphConfig into Web Audio nodes and connections.
 * Connection order follows the edges array — deterministic for testing.
 *
 * The context is a `BaseAudioContext`, not an `AudioContext`: the offline
 * render path (`compileOfflineGraph`) compiles the *same* patch into an
 * `OfflineAudioContext`, which is what keeps freeze / stems / preview on one
 * compiler instead of a second, quietly diverging one.
 */
export function compileAudioGraph(
    context: BaseAudioContext,
    config: AudioGraphConfig,
    options: CompileGraphOptions = {},
): CompiledAudioGraph {
    assertSafeGraphCycles(config);
    const resolved = { ...DEFAULT_OPTIONS, ...options };

    if (resolved.validate) {
        const validation = validateGraph(config);
        if (!validation.valid) {
            const detail = validation.issues.map((issue) => issue.message).join('; ');
            throw new Error(`AudioGraph compile failed: ${detail}`);
        }
    }

    const nodes = new Map<GraphNodeId, AudioNode>();
    const ports = new Map<GraphNodeId, GraphPortPair>();
    const sendGains = new Map<string, GainNode>();
    const analysers = new Map<GraphNodeId, AnalyserNode>();
    const roles = new Map<GraphNodeRole, GraphNodeId | GraphNodeId[]>();
    const connectionLog: GraphConnectionRecord[] = [];

    for (const spec of config.nodes) {
        const node = createNode(context, spec, resolved, analysers, ports);
        if (node) {
            nodes.set(spec.id, node);
            if (!ports.has(spec.id)) {
                ports.set(spec.id, { input: node, output: node });
            }
            if (spec.role) {
                registerRole(roles, spec.role, spec.id);
            }
        }
    }

    // When stereo panner node was not created, reroute masterGain → destination
    const hasStereoPanner = nodes.has('masterPanner');
    const optionalEdges = bridgeAbsentNodes(config.edges, new Set(nodes.keys()), ['masterLimiter']);

    const edges = optionalEdges.filter((edge) => {
        if (hasStereoPanner) return true;
        if (edge.from === 'masterGain' && edge.to === 'masterPanner') return false;
        if (edge.from === 'masterPanner') return false;
        return true;
    });

    if (!hasStereoPanner) {
        const masterGain = nodes.get('masterGain');
        const limiter = nodes.get('masterLimiter');
        if (masterGain) {
            masterGain.connect(limiter ?? context.destination);
            connectionLog.push({
                from: 'masterGain',
                to: limiter ? 'masterLimiter' : 'destination',
                order: connectionLog.length,
            });
        }
    }

    for (const edge of edges) {
        const fromPort = ports.get(edge.from);
        const toPort = ports.get(edge.to);
        const fromNode = fromPort?.output ?? nodes.get(edge.from);
        const toNode =
            toPort?.input ??
            nodes.get(edge.to) ??
            (edge.to === 'destination' ? context.destination : undefined);
        if (!fromNode || !toNode) {
            if (!hasStereoPanner && (edge.to === 'masterPanner' || edge.from === 'masterPanner')) {
                continue;
            }
            throw new Error(
                `AudioGraph compile failed: missing node for edge ${edge.from} → ${edge.to}`,
            );
        }
        if (edge.gain !== undefined && edge.gain !== 1) {
            // Web Audio connections carry no level, so a send amount becomes an
            // implicit GainNode. It is kept in `sendGains` so the patch bay can
            // ride the fader without recompiling the graph.
            const send = context.createGain();
            send.gain.setValueAtTime(edge.gain, context.currentTime);
            fromNode.connect(send);
            send.connect(toNode);
            sendGains.set(edgeKey(edge.from, edge.to), send);
        } else {
            fromNode.connect(toNode);
        }
        connectionLog.push({
            from: edge.from,
            to: edge.to,
            order: connectionLog.length,
        });
    }

    return {
        configId: config.id,
        configName: config.name,
        nodes,
        ports,
        analysers,
        roles,
        connectionLog,
        sendGains,
        getNode<T extends AudioNode = AudioNode>(id: GraphNodeId): T {
            const node = nodes.get(id);
            if (!node) {
                throw new Error(`AudioGraph node not found: ${id}`);
            }
            return node as T;
        },
        getPort(id: GraphNodeId): GraphPortPair {
            const pair = ports.get(id);
            if (!pair) {
                throw new Error(`AudioGraph port not found: ${id}`);
            }
            return pair;
        },
        getRoleNode(role: GraphNodeRole): AudioNode | undefined {
            const entry = roles.get(role);
            if (!entry) return undefined;
            const id = Array.isArray(entry) ? entry[0] : entry;
            return nodes.get(id);
        },
        getRoleNodes(role: GraphNodeRole): AudioNode[] {
            const entry = roles.get(role);
            if (!entry) return [];
            const ids = Array.isArray(entry) ? entry : [entry];
            return ids.map((nodeId) => nodes.get(nodeId)).filter((n): n is AudioNode => n !== undefined);
        },
    };
}

/** Extract in-series master chain connections from a compiled graph log. */
export function extractMasterChainConnections(
    log: readonly GraphConnectionRecord[],
): Array<{ from: string; to: string }> {
    const masterIds = new Set([
        'masterLimiter',
        'masterSaturation',
        'bassSidechainEQ',
        'sidechainGain',
        'masterCompressor',
        'masterGain',
        'masterPanner',
        'destination',
    ]);
    return log
        .filter((c) => masterIds.has(c.from) && masterIds.has(c.to))
        .map(({ from, to }) => ({ from, to }));
}

/**
 * Offline export path: loudness reporting, normalisation, live-vs-file parity.
 */

import { describe, expect, it } from 'vitest';

import { analyzeLoudness, normalizeToTarget, formatLufs } from '../offline';
import { LoudnessMeter } from '../loudnessMeter';
import { TruePeakLimiter } from '../limiter';
import { measureTruePeakDbtp } from '../truePeak';
import { LOUDNESS_TARGETS, SILENCE_LUFS } from '../types';
import {
    loadLimiterSettings,
    saveLimiterSettings,
    sanitizeLimiterSettings,
    LIMITER_STORAGE_KEY,
} from '../settings';
import { DEFAULT_LIMITER_SETTINGS } from '../types';

const SAMPLE_RATE = 48000;

/** Pseudo-music: a few partials plus transients, deterministic across runs. */
function mixdown(seconds: number, sampleRate = SAMPLE_RATE, amplitude = 0.5): Float32Array[] {
    const frames = Math.round(seconds * sampleRate);
    const left = new Float32Array(frames);
    const right = new Float32Array(frames);
    let seed = 12345;
    for (let i = 0; i < frames; i += 1) {
        seed = (seed * 1103515245 + 12345) & 0x7fffffff;
        const noise = (seed / 0x7fffffff) * 2 - 1;
        const fade = Math.min(1, i / 2000, (frames - i) / 2000);
        const tone =
            0.6 * Math.sin((2 * Math.PI * 110 * i) / sampleRate) +
            0.3 * Math.sin((2 * Math.PI * 440 * i) / sampleRate) +
            0.1 * Math.sin((2 * Math.PI * 3000 * i) / sampleRate);
        const transient = i % 12000 < 32 ? 0.8 * noise : 0.02 * noise;
        left[i] = fade * amplitude * (tone + transient);
        right[i] = fade * amplitude * (tone - transient);
    }
    return [left, right];
}

describe('offline loudness report', () => {
    it('reports integrated loudness, true peak and sample peak', () => {
        const report = analyzeLoudness(mixdown(6), SAMPLE_RATE);
        expect(Number.isFinite(report.integrated)).toBe(true);
        expect(report.truePeak).toBeGreaterThanOrEqual(report.samplePeak - 0.01);
        expect(report.maxShortTerm).toBeGreaterThanOrEqual(report.integrated - 5);
        expect(report.maxMomentary).toBeGreaterThanOrEqual(report.maxShortTerm - 5);
    });

    it('formats silence readably', () => {
        expect(formatLufs(SILENCE_LUFS)).toBe('-inf');
        expect(formatLufs(-13.94)).toBe('-13.9');
    });
});

describe('live vs offline parity', () => {
    // The worklet and the export path run the same DSP, so a mix limited in
    // 128-frame quanta must measure the same as the offline analysis of the
    // rendered result.
    it('matches within 0.1 LU and 0.1 dBTP', () => {
        const source = mixdown(8);

        // "Live": limit in render quanta, metering the limiter output.
        const limiter = new TruePeakLimiter(SAMPLE_RATE, 2, { ceilingDbtp: -1 });
        const meter = new LoudnessMeter({ sampleRate: SAMPLE_RATE, channelCount: 2 });
        const rendered = source.map((channel) => new Float32Array(channel.length));
        const inViews: Float32Array[] = [];
        const outViews: Float32Array[] = [];
        for (let offset = 0; offset < source[0].length; offset += 128) {
            const size = Math.min(128, source[0].length - offset);
            for (let ch = 0; ch < 2; ch += 1) {
                inViews[ch] = source[ch].subarray(offset, offset + size);
                outViews[ch] = rendered[ch].subarray(offset, offset + size);
            }
            limiter.process(inViews, outViews, size);
            meter.process(outViews, size);
        }

        // "File": analyse the rendered buffer in one pass.
        const offline = analyzeLoudness(rendered, SAMPLE_RATE);
        expect(Math.abs(offline.integrated - meter.integrated)).toBeLessThanOrEqual(0.1);
        expect(Math.abs(offline.truePeak - meter.truePeakDb)).toBeLessThanOrEqual(0.1);
    });
});

describe('normalizeToTarget', () => {
    it('brings a quiet mix up to the streaming target', () => {
        const channels = mixdown(8, SAMPLE_RATE, 0.05);
        const result = normalizeToTarget(channels, SAMPLE_RATE, 'streaming');
        expect(result.targetLufs).toBe(LOUDNESS_TARGETS.streaming);
        expect(result.appliedGain).toBeGreaterThan(1);
        expect(Math.abs(result.resultingIntegrated - LOUDNESS_TARGETS.streaming)).toBeLessThan(1);
    });

    it('brings a hot mix down and keeps the ceiling', () => {
        const channels = mixdown(8, SAMPLE_RATE, 0.9);
        const result = normalizeToTarget(channels, SAMPLE_RATE, -23, { ceilingDbtp: -1 });
        expect(result.appliedGain).toBeLessThan(1);
        expect(Math.abs(result.resultingIntegrated + 23)).toBeLessThan(1);
        expect(measureTruePeakDbtp(channels, SAMPLE_RATE, 8)).toBeLessThanOrEqual(-1);
    });

    it('accepts a numeric target and reports what was actually achieved', () => {
        const channels = mixdown(6, SAMPLE_RATE, 0.4);
        const result = normalizeToTarget(channels, SAMPLE_RATE, LOUDNESS_TARGETS.club, {
            ceilingDbtp: -1,
        });
        expect(result.targetLufs).toBe(-9);
        // A -9 LUFS target under a -1 dBTP ceiling may fall short; the caller is
        // told the truth rather than being left to assume the target was met.
        expect(result.resultingIntegrated).toBeLessThanOrEqual(-9 + 0.5);
        expect(measureTruePeakDbtp(channels, SAMPLE_RATE, 8)).toBeLessThanOrEqual(-1);
    });

    it('leaves silence alone instead of applying infinite gain', () => {
        const channels = [new Float32Array(48000), new Float32Array(48000)];
        const result = normalizeToTarget(channels, SAMPLE_RATE, 'streaming');
        expect(result.appliedGain).toBe(1);
        expect(channels[0].every((value) => value === 0)).toBe(true);
    });
});

describe('limiter settings persistence', () => {
    it('round-trips through storage as primitives only', () => {
        const store = new Map<string, string>();
        const storage = {
            getItem: (key: string) => store.get(key) ?? null,
            setItem: (key: string, value: string) => store.set(key, value),
        } as unknown as Storage;

        saveLimiterSettings({ ...DEFAULT_LIMITER_SETTINGS, ceilingDbtp: -2.5 }, storage);
        const raw = store.get(LIMITER_STORAGE_KEY)!;
        const parsed = JSON.parse(raw);
        for (const value of Object.values(parsed)) {
            expect(['number', 'boolean']).toContain(typeof value);
        }
        expect(loadLimiterSettings(storage).ceilingDbtp).toBe(-2.5);
    });

    it('falls back to defaults on corrupted or hostile values', () => {
        expect(sanitizeLimiterSettings(null)).toEqual(DEFAULT_LIMITER_SETTINGS);
        expect(sanitizeLimiterSettings({ ceilingDbtp: NaN }).ceilingDbtp).toBe(
            DEFAULT_LIMITER_SETTINGS.ceilingDbtp,
        );
        expect(sanitizeLimiterSettings({ ceilingDbtp: 40 }).ceilingDbtp).toBe(
            DEFAULT_LIMITER_SETTINGS.ceilingDbtp,
        );
        expect(sanitizeLimiterSettings({ lookaheadMs: -5 }).lookaheadMs).toBe(
            DEFAULT_LIMITER_SETTINGS.lookaheadMs,
        );
        expect(sanitizeLimiterSettings({ enabled: 'yes' }).enabled).toBe(
            DEFAULT_LIMITER_SETTINGS.enabled,
        );
    });

    it('survives a storage backend that throws', () => {
        const hostile = {
            getItem: () => {
                throw new Error('denied');
            },
            setItem: () => {
                throw new Error('quota');
            },
        } as unknown as Storage;
        expect(loadLimiterSettings(hostile)).toEqual(DEFAULT_LIMITER_SETTINGS);
        expect(() => saveLimiterSettings(DEFAULT_LIMITER_SETTINGS, hostile)).not.toThrow();
    });
});

/**
 * BS.1770-5 / EBU TECH 3341 conformance for the first-party loudness meter.
 *
 * The reference values are the ones published in the recommendations
 * themselves (tone tests, gating cases and the 48 kHz coefficient table), so
 * the DSP is validated against known-good numbers rather than against itself.
 * Tolerances follow TECH 3341: ±0.1 LU.
 */

import { describe, expect, it } from 'vitest';

import { LoudnessMeter, meanSquareToLufs } from '../loudnessMeter';
import { shelfCoefficients, highPassCoefficients } from '../kWeighting';
import { analyzeLoudness } from '../offline';
import { SILENCE_LUFS } from '../types';

const TOLERANCE_LU = 0.1;

/** Stereo sine at `db` dBFS, identical in both channels. */
function stereoSine(
    seconds: number,
    sampleRate: number,
    frequency = 1000,
    db = -20,
): Float32Array[] {
    const frames = Math.round(seconds * sampleRate);
    const amplitude = Math.pow(10, db / 20) * Math.SQRT2; // db is RMS, not peak
    const left = new Float32Array(frames);
    for (let i = 0; i < frames; i += 1) {
        left[i] = amplitude * Math.sin((2 * Math.PI * frequency * i) / sampleRate);
    }
    return [left, Float32Array.from(left)];
}

function silence(seconds: number, sampleRate: number): Float32Array[] {
    const frames = Math.round(seconds * sampleRate);
    return [new Float32Array(frames), new Float32Array(frames)];
}

function concat(...segments: Float32Array[][]): Float32Array[] {
    const channels = segments[0].length;
    const out: Float32Array[] = [];
    for (let ch = 0; ch < channels; ch += 1) {
        const total = segments.reduce((sum, segment) => sum + segment[ch].length, 0);
        const buffer = new Float32Array(total);
        let offset = 0;
        for (const segment of segments) {
            buffer.set(segment[ch], offset);
            offset += segment[ch].length;
        }
        out.push(buffer);
    }
    return out;
}

describe('K-weighting coefficients', () => {
    // ITU-R BS.1770-5 Tables 1 and 2 — the only rate the recommendation tabulates.
    it('matches the tabulated 48 kHz stage 1 (shelving) coefficients', () => {
        const c = shelfCoefficients(48000);
        expect(c.b0).toBeCloseTo(1.53512485958697, 6);
        expect(c.b1).toBeCloseTo(-2.69169618940638, 6);
        expect(c.b2).toBeCloseTo(1.19839281085285, 6);
        expect(c.a1).toBeCloseTo(-1.69065929318241, 6);
        expect(c.a2).toBeCloseTo(0.73248077421585, 6);
    });

    it('matches the tabulated 48 kHz stage 2 (RLB high-pass) coefficients', () => {
        const c = highPassCoefficients(48000);
        expect(c.b0).toBeCloseTo(1.0, 6);
        expect(c.b1).toBeCloseTo(-2.0, 6);
        expect(c.b2).toBeCloseTo(1.0, 6);
        expect(c.a1).toBeCloseTo(-1.99004745483398, 6);
        expect(c.a2).toBeCloseTo(0.99007225036621, 6);
    });

    it('produces different coefficients per sample rate (no hard-coded table)', () => {
        expect(shelfCoefficients(44100).b0).not.toBeCloseTo(shelfCoefficients(48000).b0, 5);
        expect(highPassCoefficients(96000).a1).not.toBeCloseTo(highPassCoefficients(48000).a1, 5);
    });
});

describe('LoudnessMeter — TECH 3341 tone cases', () => {
    // EBU TECH 3341 case 1: -23 LUFS 1 kHz stereo tone reads -23.0 ±0.1.
    it('reads -23 LUFS for a -23 dBFS 1 kHz stereo tone', () => {
        const report = analyzeLoudness(stereoSine(20, 48000, 1000, -26), 48000);
        // -26 dBFS per channel, summed over two channels → -23 LUFS.
        expect(report.integrated).toBeCloseTo(-23.0, 1);
        expect(Math.abs(report.integrated + 23.0)).toBeLessThanOrEqual(TOLERANCE_LU);
    });

    it('reads -33 LUFS for the same tone 10 dB quieter', () => {
        const report = analyzeLoudness(stereoSine(20, 48000, 1000, -36), 48000);
        expect(Math.abs(report.integrated + 33.0)).toBeLessThanOrEqual(TOLERANCE_LU);
    });

    it('agrees between momentary, short-term and integrated on steady tone', () => {
        const meter = new LoudnessMeter({ sampleRate: 48000, channelCount: 2 });
        const [left, right] = stereoSine(10, 48000, 1000, -26);
        meter.process([left, right], left.length);
        expect(Math.abs(meter.momentary + 23)).toBeLessThanOrEqual(TOLERANCE_LU);
        expect(Math.abs(meter.shortTerm + 23)).toBeLessThanOrEqual(TOLERANCE_LU);
        expect(Math.abs(meter.integrated + 23)).toBeLessThanOrEqual(TOLERANCE_LU);
    });

    it('reports silence rather than NaN or -0 for a zero signal', () => {
        const report = analyzeLoudness(silence(5, 48000), 48000);
        expect(report.integrated).toBe(SILENCE_LUFS);
        expect(report.maxMomentary).toBe(SILENCE_LUFS);
        expect(report.truePeak).toBe(SILENCE_LUFS);
    });
});

describe('LoudnessMeter — gating', () => {
    // TECH 3341 case 3: 20 s of -23 LUFS tone padded with -70 LUFS material
    // still reads -23.0 ±0.1 — the pad is below the absolute gate. The 20 s
    // length matters: the six blocks straddling each edge are legitimately part
    // of the measurement, so a shorter tone reads slightly low on any
    // compliant meter.
    it('ignores silence below the absolute gate', () => {
        const loud = stereoSine(20, 48000, 1000, -26);
        const signal = concat(silence(10, 48000), loud, silence(10, 48000));
        const report = analyzeLoudness(signal, 48000);
        expect(Math.abs(report.integrated + 23)).toBeLessThanOrEqual(TOLERANCE_LU);
    });

    // ... and a passage more than 10 LU below the ungated mean must be dropped
    // by the relative gate.
    it('drops blocks below the relative gate', () => {
        const loud = stereoSine(10, 48000, 1000, -26); // -23 LUFS
        const quiet = stereoSine(10, 48000, 1000, -56); // -53 LUFS, > 10 LU down
        const gated = analyzeLoudness(concat(loud, quiet), 48000).integrated;
        const loudOnly = analyzeLoudness(loud, 48000).integrated;
        expect(Math.abs(gated - loudOnly)).toBeLessThanOrEqual(TOLERANCE_LU);
    });

    it('keeps blocks within 10 LU of the mean', () => {
        // -23 and -28 LUFS: both survive gating, so the result sits between them.
        const a = stereoSine(10, 48000, 1000, -26);
        const b = stereoSine(10, 48000, 1000, -31);
        const integrated = analyzeLoudness(concat(a, b), 48000).integrated;
        expect(integrated).toBeLessThan(-23);
        expect(integrated).toBeGreaterThan(-28);
    });

    it('resets the integrated measurement on request without disturbing momentary', () => {
        const meter = new LoudnessMeter({ sampleRate: 48000, channelCount: 2 });
        const quiet = stereoSine(20, 48000, 1000, -46);
        meter.process(quiet, quiet[0].length);
        expect(Math.abs(meter.integrated + 43)).toBeLessThanOrEqual(TOLERANCE_LU);

        meter.resetIntegrated();
        expect(meter.integrated).toBe(SILENCE_LUFS);
        // Momentary keeps running across the reset — the UI must not blink.
        expect(Math.abs(meter.momentary + 43)).toBeLessThanOrEqual(TOLERANCE_LU);

        const loud = stereoSine(20, 48000, 1000, -26);
        meter.process(loud, loud[0].length);
        expect(Math.abs(meter.integrated + 23)).toBeLessThanOrEqual(TOLERANCE_LU);
    });
});

describe('LoudnessMeter — sample rate independence', () => {
    for (const sampleRate of [44100, 48000, 96000]) {
        it(`reads -23 LUFS at ${sampleRate} Hz`, () => {
            const report = analyzeLoudness(stereoSine(12, sampleRate, 1000, -26), sampleRate);
            expect(Math.abs(report.integrated + 23)).toBeLessThanOrEqual(TOLERANCE_LU);
        });
    }

    it('gives the same reading for the same signal at different rates', () => {
        const at44 = analyzeLoudness(stereoSine(12, 44100, 997, -26), 44100).integrated;
        const at96 = analyzeLoudness(stereoSine(12, 96000, 997, -26), 96000).integrated;
        expect(Math.abs(at44 - at96)).toBeLessThanOrEqual(TOLERANCE_LU);
    });
});

describe('LoudnessMeter — robustness', () => {
    it('treats NaN and Infinity as silence instead of poisoning the meter', () => {
        const frames = 48000;
        const left = new Float32Array(frames);
        const right = new Float32Array(frames);
        for (let i = 0; i < frames; i += 1) {
            const value = 0.1 * Math.sin((2 * Math.PI * 1000 * i) / 48000);
            left[i] = i === 12345 ? NaN : value;
            right[i] = i === 20000 ? Infinity : value;
        }
        const report = analyzeLoudness([left, right], 48000);
        expect(Number.isFinite(report.integrated)).toBe(true);
        expect(Number.isFinite(report.truePeak)).toBe(true);
        expect(report.truePeak).toBeLessThan(6);
    });

    it('maps a zero mean square to -Infinity, not NaN', () => {
        expect(meanSquareToLufs(0)).toBe(SILENCE_LUFS);
        expect(meanSquareToLufs(NaN)).toBe(SILENCE_LUFS);
        expect(meanSquareToLufs(-1)).toBe(SILENCE_LUFS);
    });

    it('allocates nothing per render quantum', () => {
        const meter = new LoudnessMeter({ sampleRate: 48000, channelCount: 2 });
        const block = [new Float32Array(128), new Float32Array(128)];
        for (let i = 0; i < 128; i += 1) {
            block[0][i] = 0.25;
            block[1][i] = 0.25;
        }
        const before = countAllocations(() => meter.process(block, 128));
        expect(before).toBe(0);
    });
});

/**
 * Count typed-array constructions performed by `fn`.
 * A real-time DSP path must not allocate on the audio thread.
 */
function countAllocations(fn: () => void): number {
    const constructors: Array<keyof typeof globalThis> = [
        'Float32Array',
        'Float64Array',
        'Int32Array',
        'Array',
    ];
    const originals = constructors.map((name) => [name, globalThis[name]] as const);
    let count = 0;
    for (const [name, original] of originals) {
        const proxy = new Proxy(original as unknown as object, {
            construct(target, args, newTarget) {
                count += 1;
                return Reflect.construct(target as never, args, newTarget);
            },
        });
        (globalThis as Record<string, unknown>)[name as string] = proxy;
    }
    try {
        fn();
    } finally {
        for (const [name, original] of originals) {
            (globalThis as Record<string, unknown>)[name as string] = original;
        }
    }
    return count;
}

/**
 * True-peak detection (BS.1770-5 Annex 2 / BS.2217) and brick-wall limiting.
 *
 * The headline case is the fs/4 sine with a 45° phase offset: its samples sit
 * at ±0.7071 while the underlying waveform reaches 1.0, so a compliant meter
 * must report +3.01 dBTP where a sample-peak meter reads 0 dBFS.
 */

import { describe, expect, it } from 'vitest';

import {
    TruePeakDetector,
    buildPolyphaseCoefficients,
    dbToLinear,
    linearToDb,
    measureTruePeakDbtp,
    oversamplingFactorFor,
} from '../truePeak';
import { TruePeakLimiter, MAX_LOOKAHEAD_MS } from '../limiter';
import { DEFAULT_LIMITER_SETTINGS } from '../types';

const TOLERANCE_DB = 0.1;

/**
 * Test tone, optionally with faded edges.
 *
 * The fade matters when a measurement has to be accurate to ±0.1 dB: a buffer
 * that starts or ends mid-cycle is a step discontinuity, and the band-limited
 * reconstruction of a step genuinely overshoots by ~1 dB. The limiter cases
 * below therefore use edges the way real program material has them; the
 * detector cases use raw tones whose exact true peak is known analytically.
 */
function sine(
    frames: number,
    sampleRate: number,
    frequency: number,
    amplitude = 1,
    phase = 0,
    fadeFrames = 0,
): Float32Array {
    const out = new Float32Array(frames);
    for (let i = 0; i < frames; i += 1) {
        const fade = fadeFrames > 0 ? Math.min(1, i / fadeFrames, (frames - i) / fadeFrames) : 1;
        out[i] = fade * amplitude * Math.sin((2 * Math.PI * frequency * i) / sampleRate + phase);
    }
    return out;
}

function samplePeakDb(channel: Float32Array): number {
    let peak = 0;
    for (const value of channel) {
        const magnitude = Math.abs(value);
        if (magnitude > peak) peak = magnitude;
    }
    return linearToDb(peak);
}

/** Run a signal through the limiter in 128-frame quanta, as the worklet does. */
function runLimiter(
    limiter: TruePeakLimiter,
    channels: Float32Array[],
): Float32Array[] {
    const frames = channels[0].length;
    const output = channels.map(() => new Float32Array(frames));
    const inViews: Float32Array[] = new Array(channels.length);
    const outViews: Float32Array[] = new Array(channels.length);
    for (let offset = 0; offset < frames; offset += 128) {
        const size = Math.min(128, frames - offset);
        for (let ch = 0; ch < channels.length; ch += 1) {
            inViews[ch] = channels[ch].subarray(offset, offset + size);
            outViews[ch] = output[ch].subarray(offset, offset + size);
        }
        limiter.process(inViews, outViews, size);
    }
    return output;
}

describe('polyphase oversampler', () => {
    it('keeps every branch at unit DC gain', () => {
        for (const factor of [2, 4, 8]) {
            for (const branch of buildPolyphaseCoefficients(factor)) {
                const sum = branch.reduce((acc, value) => acc + value, 0);
                expect(sum).toBeCloseTo(1, 5);
            }
        }
    });

    it('oversamples to at least 192 kHz at every supported rate', () => {
        expect(44100 * oversamplingFactorFor(44100)).toBeGreaterThanOrEqual(192000);
        expect(48000 * oversamplingFactorFor(48000)).toBeGreaterThanOrEqual(192000);
        expect(96000 * oversamplingFactorFor(96000)).toBeGreaterThanOrEqual(192000);
        expect(oversamplingFactorFor(48000)).toBe(4);
        expect(oversamplingFactorFor(96000)).toBe(2);
    });

    it('does not invent peaks on steady DC', () => {
        // Measured away from the buffer edges, where the step into DC produces a
        // real (and correctly reported) inter-sample overshoot.
        const detector = new TruePeakDetector(48000);
        for (let i = 0; i < 512; i += 1) detector.processSample(0.5);
        detector.resetPeak();
        for (let i = 0; i < 512; i += 1) detector.processSample(0.5);
        expect(linearToDb(detector.peak)).toBeCloseTo(linearToDb(0.5), 2);
    });
});

describe('true-peak detection', () => {
    it('reports +3.01 dBTP for a 0 dBFS fs/4 sine at 45°', () => {
        const signal = sine(20000, 48000, 12000, 1, Math.PI / 4);
        expect(samplePeakDb(signal)).toBeCloseTo(-3.01, 1);
        const truePeak = measureTruePeakDbtp([signal], 48000);
        expect(Math.abs(truePeak - 0)).toBeLessThanOrEqual(TOLERANCE_DB);
    });

    it('is close to 0 dBTP for a full-scale 997 Hz sine', () => {
        const signal = sine(48000, 48000, 997, 1);
        const truePeak = measureTruePeakDbtp([signal], 48000);
        expect(Math.abs(truePeak)).toBeLessThanOrEqual(TOLERANCE_DB);
    });

    it('beats linear interpolation on high-frequency content', () => {
        const signal = sine(20000, 48000, 12000, 1, Math.PI / 4);
        // Linear interpolation between samples of this signal never exceeds the
        // sample peak, i.e. it misses the ~3 dB of inter-sample energy entirely.
        const linearEstimate = samplePeakDb(signal);
        const truePeak = measureTruePeakDbtp([signal], 48000);
        expect(truePeak - linearEstimate).toBeGreaterThan(2.5);
    });

    it('takes the maximum across channels', () => {
        const quiet = sine(2048, 48000, 997, 0.1);
        const loud = sine(2048, 48000, 997, 0.9);
        expect(measureTruePeakDbtp([quiet, loud], 48000)).toBeCloseTo(
            measureTruePeakDbtp([loud], 48000),
            5,
        );
    });

    it('treats non-finite samples as silence', () => {
        const signal = sine(2048, 48000, 997, 0.5);
        signal[100] = NaN;
        signal[200] = Infinity;
        const truePeak = measureTruePeakDbtp([signal], 48000);
        expect(Number.isFinite(truePeak)).toBe(true);
        expect(truePeak).toBeLessThan(0);
    });

    it('detects nothing above 0 for silence', () => {
        const detector = new TruePeakDetector(48000);
        for (let i = 0; i < 1024; i += 1) detector.processSample(0);
        expect(detector.peak).toBe(0);
    });
});

describe('TruePeakLimiter', () => {
    const sampleRate = 48000;

    it('holds a -1 dBTP ceiling on a hot high-frequency signal', () => {
        const limiter = new TruePeakLimiter(sampleRate, 2, { ceilingDbtp: -1 });
        // Worst-case ISP material: full-scale fs/4 tone at 45°.
        const left = sine(48000, sampleRate, 12000, 1, Math.PI / 4, 2000);
        const right = Float32Array.from(left);
        const output = runLimiter(limiter, [left, right]);

        const truePeak = measureTruePeakDbtp(output, sampleRate, 8);
        expect(truePeak).toBeLessThanOrEqual(-1);
    });

    it('holds the ceiling on a hot broadband transient', () => {
        const limiter = new TruePeakLimiter(sampleRate, 2, { ceilingDbtp: -1 });
        const frames = 48000;
        const left = new Float32Array(frames);
        const right = new Float32Array(frames);
        for (let i = 0; i < frames; i += 1) {
            // Quiet bed with periodic full-scale clicks.
            const fade = Math.min(1, i / 2000, (frames - i) / 2000);
            const bed = 0.2 * Math.sin((2 * Math.PI * 220 * i) / sampleRate);
            const click = i > 4800 && i % 4800 < 8 ? (i % 2 === 0 ? 1 : -1) : 0;
            left[i] = fade * Math.max(-1, Math.min(1, bed + click));
            right[i] = left[i];
        }
        const output = runLimiter(limiter, [left, right]);
        expect(measureTruePeakDbtp(output, sampleRate, 8)).toBeLessThanOrEqual(-1);
    });

    it('honours a louder ceiling too', () => {
        const limiter = new TruePeakLimiter(sampleRate, 2, { ceilingDbtp: -3 });
        const signal = sine(24000, sampleRate, 8000, 1, Math.PI / 4, 2000);
        const output = runLimiter(limiter, [signal, Float32Array.from(signal)]);
        expect(measureTruePeakDbtp(output, sampleRate, 8)).toBeLessThanOrEqual(-3);
    });

    it('leaves signals below the ceiling untouched apart from the latency delay', () => {
        const limiter = new TruePeakLimiter(sampleRate, 2, { ceilingDbtp: -1 });
        const signal = sine(8192, sampleRate, 440, 0.25);
        const output = runLimiter(limiter, [signal, Float32Array.from(signal)]);

        const delay = Math.round(limiter.latencySeconds * sampleRate);
        expect(delay).toBeGreaterThan(0);
        for (let i = delay; i < 8192; i += 1) {
            expect(output[0][i]).toBeCloseTo(signal[i - delay], 5);
        }
        expect(limiter.takeStats().gainReductionDb).toBe(0);
    });

    it('passes audio through unchanged when bypassed', () => {
        const limiter = new TruePeakLimiter(sampleRate, 2, { enabled: false });
        const signal = sine(2048, sampleRate, 12000, 1, Math.PI / 4);
        const output = runLimiter(limiter, [signal, Float32Array.from(signal)]);
        expect(limiter.latencySeconds).toBe(0);
        for (let i = 0; i < signal.length; i += 1) {
            expect(output[0][i]).toBe(signal[i]);
        }
    });

    it('monitor-only mode is zero latency and clamps in the sample domain', () => {
        const limiter = new TruePeakLimiter(sampleRate, 2, {
            monitorOnly: true,
            ceilingDbtp: -6,
        });
        expect(limiter.latencySeconds).toBe(0);

        const signal = sine(2048, sampleRate, 997, 1);
        const output = runLimiter(limiter, [signal, Float32Array.from(signal)]);
        const ceiling = dbToLinear(-6);
        for (const value of output[0]) {
            expect(Math.abs(value)).toBeLessThanOrEqual(ceiling + 1e-6);
        }
        expect(limiter.takeStats().clipped).toBe(true);
    });

    it('reports gain reduction while limiting and clears it after reading', () => {
        const limiter = new TruePeakLimiter(sampleRate, 2, { ceilingDbtp: -6 });
        const signal = sine(24000, sampleRate, 997, 1, 0, 2000);
        runLimiter(limiter, [signal, Float32Array.from(signal)]);

        const stats = limiter.takeStats();
        expect(stats.gainReductionDb).toBeLessThan(-4);
        expect(limiter.takeStats().gainReductionDb).toBe(0);
    });

    it('reports lookahead as monitor latency and clamps absurd requests', () => {
        const limiter = new TruePeakLimiter(sampleRate, 2, { lookaheadMs: 1.5 });
        const lookaheadFrames = Math.round((1.5 / 1000) * sampleRate);
        // Latency is lookahead plus the detector's group delay.
        expect(limiter.latencySeconds * sampleRate).toBeGreaterThanOrEqual(lookaheadFrames);
        expect(limiter.latencySeconds).toBeLessThan((MAX_LOOKAHEAD_MS + 1) / 1000);

        limiter.setSettings({ lookaheadMs: 1000 });
        expect(limiter.latencySeconds).toBeLessThanOrEqual((MAX_LOOKAHEAD_MS + 1) / 1000);
    });

    it('survives NaN input without muting or latching the master', () => {
        const limiter = new TruePeakLimiter(sampleRate, 2);
        const signal = sine(8192, sampleRate, 440, 0.5);
        signal[1000] = NaN;
        signal[1001] = Infinity;
        const output = runLimiter(limiter, [signal, Float32Array.from(signal)]);
        for (const value of output[0]) {
            expect(Number.isFinite(value)).toBe(true);
        }
        // Audio after the glitch is still passing.
        const tail = output[0].subarray(4096);
        expect(Math.max(...tail)).toBeGreaterThan(0.1);
    });

    it('allocates nothing per render quantum', () => {
        const limiter = new TruePeakLimiter(sampleRate, 2, DEFAULT_LIMITER_SETTINGS);
        const input = [new Float32Array(128), new Float32Array(128)];
        const output = [new Float32Array(128), new Float32Array(128)];
        for (let i = 0; i < 128; i += 1) {
            input[0][i] = Math.sin(i);
            input[1][i] = Math.sin(i);
        }
        limiter.process(input, output, 128); // warm up

        let allocations = 0;
        const originals: Array<[string, unknown]> = [];
        for (const name of ['Float32Array', 'Float64Array', 'Int32Array', 'Array']) {
            const original = (globalThis as Record<string, unknown>)[name];
            originals.push([name, original]);
            (globalThis as Record<string, unknown>)[name] = new Proxy(original as object, {
                construct(target, args, newTarget) {
                    allocations += 1;
                    return Reflect.construct(target as never, args, newTarget);
                },
            });
        }
        try {
            limiter.process(input, output, 128);
        } finally {
            for (const [name, original] of originals) {
                (globalThis as Record<string, unknown>)[name] = original;
            }
        }
        expect(allocations).toBe(0);
    });
});

/**
 * Offline loudness analysis and normalisation for the export / freeze paths.
 *
 * Uses exactly the same DSP as the real-time master worklet, so the numbers a
 * user reads while monitoring and the numbers measured in the rendered file
 * agree (the only permitted difference is a higher true-peak oversampling
 * factor offline, which can only make the reported dBTP more accurate).
 */

import { LoudnessMeter } from './loudnessMeter';
import { TruePeakLimiter } from './limiter';
import { dbToLinear, linearToDb } from './truePeak';
import {
    DEFAULT_LIMITER_SETTINGS,
    LOUDNESS_TARGETS,
    SILENCE_LUFS,
    type LimiterSettings,
    type LoudnessTargetKey,
} from './types';

export interface LoudnessReport {
    /** Gated integrated loudness, LUFS (`-Infinity` for silence). */
    integrated: number;
    /** Maximum short-term loudness observed, LUFS. */
    maxShortTerm: number;
    /** Maximum momentary loudness observed, LUFS. */
    maxMomentary: number;
    /** True peak, dBTP. */
    truePeak: number;
    /** Sample peak, dBFS. */
    samplePeak: number;
}

function channelsOf(buffer: AudioBuffer): Float32Array[] {
    const channels: Float32Array[] = [];
    for (let ch = 0; ch < buffer.numberOfChannels; ch += 1) {
        channels.push(buffer.getChannelData(ch));
    }
    return channels;
}

/** Analysis chunk size — matches the render quantum so results match live. */
const ANALYSIS_BLOCK = 128;

/**
 * Measure BS.1770 loudness and true peak of raw channel data.
 *
 * `truePeakFactor` defaults to the real-time factor; pass 8 for a stricter
 * offline reading (the delta versus live stays well inside 0.1 dBTP).
 */
export function analyzeLoudness(
    channels: readonly Float32Array[],
    sampleRate: number,
    truePeakFactor?: number,
): LoudnessReport {
    const meter = new LoudnessMeter({
        sampleRate,
        channelCount: Math.max(1, channels.length),
        truePeakFactor,
    });

    const frames = channels[0]?.length ?? 0;
    const views: Float32Array[] = new Array(channels.length);
    let maxMomentary = SILENCE_LUFS;
    let maxShortTerm = SILENCE_LUFS;

    for (let offset = 0; offset < frames; offset += ANALYSIS_BLOCK) {
        const size = Math.min(ANALYSIS_BLOCK, frames - offset);
        for (let ch = 0; ch < channels.length; ch += 1) {
            views[ch] = channels[ch].subarray(offset, offset + size);
        }
        meter.process(views, size);
        if (meter.momentary > maxMomentary) maxMomentary = meter.momentary;
        if (meter.shortTerm > maxShortTerm) maxShortTerm = meter.shortTerm;
    }

    return {
        integrated: meter.integrated,
        maxShortTerm,
        maxMomentary,
        truePeak: meter.truePeakDb,
        samplePeak: meter.samplePeakDb,
    };
}

/** Convenience wrapper for an AudioBuffer (export / freeze render output). */
export function analyzeAudioBufferLoudness(
    buffer: AudioBuffer,
    truePeakFactor?: number,
): LoudnessReport {
    return analyzeLoudness(channelsOf(buffer), buffer.sampleRate, truePeakFactor);
}

export interface NormalizeResult extends LoudnessReport {
    /** Linear gain applied to reach the target. */
    appliedGain: number;
    /** Target the render was normalised to, LUFS. */
    targetLufs: number;
    /** Loudness after normalisation + limiting, LUFS. */
    resultingIntegrated: number;
    /** True peak after normalisation + limiting, dBTP. */
    resultingTruePeak: number;
}

/**
 * Normalise channel data in place to `target` LUFS, then run the true-peak
 * limiter so the ceiling still holds after the gain change.
 *
 * Returns the pre-normalisation report plus what was actually achieved —
 * a loud master pushed to -9 LUFS can fall short once the limiter engages,
 * and the caller should surface that rather than assume the target was met.
 */
export function normalizeToTarget(
    channels: Float32Array[],
    sampleRate: number,
    target: number | LoudnessTargetKey = 'streaming',
    limiterSettings: Partial<LimiterSettings> = {},
): NormalizeResult {
    const targetLufs = typeof target === 'number' ? target : LOUDNESS_TARGETS[target];
    const report = analyzeLoudness(channels, sampleRate);

    let appliedGain = 1;
    if (Number.isFinite(report.integrated)) {
        appliedGain = dbToLinear(targetLufs - report.integrated);
    }

    const settings: LimiterSettings = {
        ...DEFAULT_LIMITER_SETTINGS,
        ...limiterSettings,
        enabled: true,
        monitorOnly: false,
        detectOversample: 8,
    };
    const limiter = new TruePeakLimiter(sampleRate, Math.max(1, channels.length), settings);

    const frames = channels[0]?.length ?? 0;
    const scratch: Float32Array[] = channels.map(() => new Float32Array(ANALYSIS_BLOCK));
    const outViews: Float32Array[] = new Array(channels.length);

    for (let offset = 0; offset < frames; offset += ANALYSIS_BLOCK) {
        const size = Math.min(ANALYSIS_BLOCK, frames - offset);
        for (let ch = 0; ch < channels.length; ch += 1) {
            const source = channels[ch];
            const block = scratch[ch];
            for (let i = 0; i < size; i += 1) {
                block[i] = source[offset + i] * appliedGain;
            }
            outViews[ch] = source.subarray(offset, offset + size);
        }
        limiter.process(scratch, outViews, size);
    }

    const after = analyzeLoudness(channels, sampleRate);
    return {
        ...report,
        appliedGain,
        targetLufs,
        resultingIntegrated: after.integrated,
        resultingTruePeak: after.truePeak,
    };
}

export interface MasterLoudnessRenderResult {
    /** Reading of the mix as it arrived from the render. */
    before: LoudnessReport;
    /** Reading after the limiter ran (identical to `before` when it did not). */
    after: LoudnessReport;
    /** False when the settings say metering only — the samples are untouched. */
    limited: boolean;
    /** Settings the offline stage actually ran with. */
    settings: LimiterSettings;
}

/**
 * Run the master limiter over a rendered mix exactly where the live graph runs
 * it — last node before the destination (#1095).
 *
 * The live stage is an AudioWorklet; offline it is the same `TruePeakLimiter`
 * fed the same persisted `LimiterSettings`, so a bounce carries the ceiling the
 * user was monitoring with. `enabled: false` or `monitorOnly: true` measure
 * without touching a sample, which is what those modes mean live too.
 */
export function applyMasterLoudnessOffline(
    channels: Float32Array[],
    sampleRate: number,
    limiterSettings: Partial<LimiterSettings> = {},
): MasterLoudnessRenderResult {
    const settings: LimiterSettings = {
        ...DEFAULT_LIMITER_SETTINGS,
        ...limiterSettings,
        // Offline has no real-time budget to protect, so the detector runs at
        // the stricter factor. It can only make the reported dBTP more accurate.
        detectOversample: limiterSettings.detectOversample ?? 8,
    };
    const before = analyzeLoudness(channels, sampleRate, settings.detectOversample);

    if (!settings.enabled || settings.monitorOnly) {
        return { before, after: before, limited: false, settings };
    }

    const limiter = new TruePeakLimiter(sampleRate, Math.max(1, channels.length), settings);
    const frames = channels[0]?.length ?? 0;
    const scratch: Float32Array[] = channels.map(() => new Float32Array(ANALYSIS_BLOCK));
    const outViews: Float32Array[] = new Array(channels.length);

    for (let offset = 0; offset < frames; offset += ANALYSIS_BLOCK) {
        const size = Math.min(ANALYSIS_BLOCK, frames - offset);
        for (let ch = 0; ch < channels.length; ch += 1) {
            const source = channels[ch];
            const block = scratch[ch];
            for (let i = 0; i < size; i += 1) block[i] = source[offset + i];
            outViews[ch] = source.subarray(offset, offset + size);
        }
        limiter.process(scratch, outViews, size);
    }

    return {
        before,
        after: analyzeLoudness(channels, sampleRate, settings.detectOversample),
        limited: true,
        settings,
    };
}

/** Format a loudness value for UI/report text (`-inf` for silence). */
export function formatLufs(value: number, digits = 1): string {
    return Number.isFinite(value) ? value.toFixed(digits) : '-inf';
}

export { linearToDb, dbToLinear };

/**
 * Offline High-Fidelity TB-303 engine (Phase-2 / #975) — TypeScript port.
 *
 * Mirrors emscripten/highfid303_wrapper.cpp for the worker path:
 *   diode-ladder (mystran/kunn) + feedback HP + diode shape + PolyBLEP +
 *   coupled accent envelope + oversampling.
 *
 * Engine id: `highfid-cpu` (offline-only).
 */

import { LIVE_HIGHFID_MODEL_ID } from '../../audio-worklets/liveHighFid303';
import {
  CANONICAL_HIGHFID_COEFFICIENTS,
  normalizeHighFidCoefficients,
  type HighFidCoefficients,
} from '../../audio-worklets/liveHighFidCoefficients';
import type { OversampleFactor } from './OfflineOpen303Engine';
import {
  clampOversample,
  type Offline303Params,
  type Offline303PatternData,
  DEFAULT_OFFLINE_303_PARAMS,
} from './OfflineOpen303Engine';

const TWO_PI = Math.PI * 2;
const SQRT2 = Math.SQRT2;
const ACCENT_VELOCITY_THRESHOLD = 100;
const FEEDBACK_HP_HZ = 150;
// Phase L3 — must match MISMATCH_SPREAD / TRACKING_REF_HZ in highfid303_wrapper.cpp.
const MISMATCH_SPREAD = [0.08, -0.05, 0.06, -0.09] as const;
const TRACKING_REF_HZ = 261.6256;

function fastTanh(x: number): number {
  const x2 = x * x;
  return (x * (27 + x2)) / (27 + 9 * x2);
}

function clampf(x: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(hi, x));
}

function diodeShape(x: number): number {
  x = clampf(x, -SQRT2, SQRT2);
  return x - (x * x * x) / 6;
}

function polyBlep(t: number, dt: number): number {
  if (dt <= 0) return 0;
  if (t < dt) {
    t /= dt;
    return t + t - t * t - 1;
  }
  if (t > 1 - dt) {
    t = (t - 1) / dt;
    return t * t + t + t + 1;
  }
  return 0;
}

function midiToFreq(midiNote: number): number {
  return 440 * Math.pow(2, (midiNote - 69) / 12);
}

class OnePoleHP {
  private b0 = 1;
  private b1 = 0;
  private a1 = 0;
  private x1 = 0;
  private y1 = 0;

  setCutoff(hz: number, sampleRate: number): void {
    hz = clampf(hz, 1, sampleRate * 0.45);
    const wc = (TWO_PI * hz) / sampleRate;
    const t = Math.tan(wc * 0.5);
    const c = (1 - t) / (1 + t);
    this.a1 = c;
    this.b0 = (1 + c) * 0.5;
    this.b1 = -(1 + c) * 0.5;
  }

  process(x: number): number {
    const y = this.b0 * x + this.b1 * this.x1 + this.a1 * this.y1;
    this.x1 = x;
    this.y1 = y;
    return y;
  }

  reset(): void {
    this.x1 = this.y1 = 0;
  }
}

class DiodeLadderFilter {
  private y1 = 0;
  private y2 = 0;
  private y3 = 0;
  private y4 = 0;
  private b0 = 0.5;
  /** Per-stage coefficients; with mismatch 0 each is exactly b0. */
  private b0s = [0.5, 0.5, 0.5, 0.5];
  /** Transistor mismatch 0–1 (Phase L3). */
  mismatch = 0;
  private k = 0;
  private g = 1;
  private sampleRate = 44100;
  private feedbackHp = new OnePoleHP();
  private oscLpY = 0;
  private oscLpCoeff = 0.5;

  setSampleRate(sr: number): void {
    this.sampleRate = sr;
    this.feedbackHp.setCutoff(FEEDBACK_HP_HZ, sr);
  }

  reset(): void {
    this.y1 = this.y2 = this.y3 = this.y4 = 0;
    this.oscLpY = 0;
    this.feedbackHp.reset();
  }

  setCutoffResonance(cutoffHz: number, resonance01: number): void {
    cutoffHz = clampf(cutoffHz, 40, this.sampleRate * 0.45);
    const r = clampf(resonance01, 0, 1);
    const resonanceSkewed = (1 - Math.exp(-3 * r)) / (1 - Math.exp(-3));
    const wc = (TWO_PI * cutoffHz) / this.sampleRate;
    const fx = (wc * 0.7071067811865476) / TWO_PI;

    this.b0 =
      (0.00045522346 + 6.1922189 * fx) /
      (1.0 + 12.358354 * fx + 4.4156345 * (fx * fx));
    for (let s = 0; s < 4; s++) {
      this.b0s[s] = this.b0 * (1 + this.mismatch * MISMATCH_SPREAD[s]);
    }

    const kScale =
      fx *
        (fx *
          (fx * (fx * (fx * (fx + 7198.6997) - 5837.7917) - 476.47308) + 614.95611) +
          213.87126) +
      16.998792;
    this.g = kScale * 0.058823529411764705;
    this.g = (this.g - 1) * resonanceSkewed + 1;
    this.g = this.g * (1 + resonanceSkewed);
    this.k = kScale * resonanceSkewed;

    const lpHz = clampf(cutoffHz * 2.5, 200, this.sampleRate * 0.4);
    const lpWc = (TWO_PI * lpHz) / this.sampleRate;
    this.oscLpCoeff = lpWc / (1 + lpWc);
  }

  process(input: number): number {
    this.oscLpY += this.oscLpCoeff * (input - this.oscLpY);
    input = this.oscLpY;

    const fb = this.feedbackHp.process(this.k * diodeShape(this.y4));
    const y0 = input - fb;
    const b0s = this.b0s;
    this.y1 += 2 * b0s[0] * (y0 - this.y1 + this.y2);
    this.y2 += b0s[1] * (this.y1 - 2 * this.y2 + this.y3);
    this.y3 += b0s[2] * (this.y2 - 2 * this.y3 + this.y4);
    this.y4 += b0s[3] * (this.y3 - 2 * this.y4);
    this.y1 = clampf(this.y1, -8, 8);
    this.y2 = clampf(this.y2, -8, 8);
    this.y3 = clampf(this.y3, -8, 8);
    this.y4 = clampf(this.y4, -8, 8);
    const out = 2 * this.g * this.y4;
    if (!Number.isFinite(out)) {
      this.reset();
      return 0;
    }
    return out;
  }
};

export const HIGHFID_CPU_MODEL_ID = 'highfid-cpu' as const;

export class OfflineHighFid303Engine {
  private sampleRate: number;
  private oversample: OversampleFactor = 1;
  private params: Offline303Params;
  private filter = new DiodeLadderFilter();
  /** Phase L3 coefficients (filter.mismatch holds the fourth). */
  private decayCurve = CANONICAL_HIGHFID_COEFFICIENTS.decayCurve;
  private accentCoupling = CANONICAL_HIGHFID_COEFFICIENTS.accentCoupling;
  private filterTracking = CANONICAL_HIGHFID_COEFFICIENTS.filterTracking;

  private phase = 0;
  private currentFreq = 440;
  private targetFreq = 440;
  private slideCoeff = 1;
  private envLevel = 0;
  private envDecayRate = 0.999;
  private accentEnv = 0;
  private accentAttackRate = 0;
  private accentDecayRate = 0;
  private accentAttacking = false;
  private accented = false;
  private gateOpen = false;

  constructor(
    sampleRate = 44100,
    params: Partial<Offline303Params> = {},
  ) {
    this.sampleRate = sampleRate;
    this.params = { ...DEFAULT_OFFLINE_303_PARAMS, ...params };
    this.filter.setSampleRate(this.effectiveSampleRate());
    this.updateRates();
    this.updateFilterCoeffs();
  }

  setOversample(factor: OversampleFactor): void {
    this.oversample = clampOversample(factor);
    this.filter.setSampleRate(this.effectiveSampleRate());
    this.updateRates();
    this.updateFilterCoeffs();
  }

  getOversample(): OversampleFactor {
    return this.oversample;
  }

  setParams(partial: Partial<Offline303Params>): void {
    this.params = { ...this.params, ...partial };
    this.updateRates();
    this.updateFilterCoeffs();
  }

  /** Apply diode-ladder coefficients; `undefined` restores the canonical preset. */
  setCoefficients(coeffs: HighFidCoefficients | undefined): void {
    const c = normalizeHighFidCoefficients(coeffs) ?? CANONICAL_HIGHFID_COEFFICIENTS;
    this.filter.mismatch = c.transistorMismatch;
    this.decayCurve = c.decayCurve;
    this.accentCoupling = c.accentCoupling;
    this.filterTracking = c.filterTracking;
    this.updateFilterCoeffs();
  }

  getCoefficients(): HighFidCoefficients {
    return {
      transistorMismatch: this.filter.mismatch,
      decayCurve: this.decayCurve,
      accentCoupling: this.accentCoupling,
      filterTracking: this.filterTracking,
    };
  }

  private effectiveSampleRate(): number {
    return this.sampleRate * this.oversample;
  }

  private updateRates(): void {
    const sr = this.effectiveSampleRate();
    let timeS = 0.05 + this.params.decay * 1.95;
    if (this.accented) timeS *= 0.05 + this.params.accentDecay * 0.95;
    this.envDecayRate = Math.exp(-1 / (sr * timeS));
    this.accentAttackRate = 1 - Math.exp(-1 / (sr * 0.003));
    const accDecS = 0.04 + this.params.accent * 0.08;
    this.accentDecayRate = Math.exp(-1 / (sr * accDecS));
  }

  private updateFilterCoeffs(): void {
    // Canonical preset takes the unshaped / untracked branches — the exact
    // pre-L3 expression (mirrors highfid303_wrapper.cpp).
    const envShaped =
      this.decayCurve > 0 ? Math.pow(this.envLevel, 1 + 3 * this.decayCurve) : this.envLevel;
    const envBoost =
      this.params.envMod * envShaped +
      (this.accented ? this.params.accent * this.accentCoupling * this.accentEnv : 0);
    const total = clampf(this.params.cutoff + envBoost, 0, 1);
    let hz = 200 * Math.pow(4500 / 200, total);
    if (this.filterTracking > 0 && this.currentFreq > 0) {
      hz *= Math.pow(this.currentFreq / TRACKING_REF_HZ, this.filterTracking);
    }
    this.filter.setCutoffResonance(hz, this.params.resonance);
  }

  noteOn(midiNote: number, velocity: number): void {
    const freq = midiToFreq(midiNote);
    this.targetFreq = freq;
    if (this.gateOpen && this.params.slideTime > 0 && this.currentFreq > 0) {
      const slideSeconds = 0.01 + this.params.slideTime * 0.49;
      const ratio = this.targetFreq / this.currentFreq;
      if (ratio > 0 && ratio !== 1) {
        this.slideCoeff = Math.pow(ratio, 1 / (slideSeconds * this.effectiveSampleRate()));
      } else {
        this.slideCoeff = 1;
        this.currentFreq = this.targetFreq;
      }
    } else {
      this.currentFreq = freq;
      this.slideCoeff = 1;
    }
    this.accented = velocity > ACCENT_VELOCITY_THRESHOLD;
    this.gateOpen = true;
    this.envLevel = 1;
    if (this.accented) {
      this.accentEnv = 0;
      this.accentAttacking = true;
    } else {
      this.accentEnv = 0;
      this.accentAttacking = false;
    }
    this.updateRates();
    this.updateFilterCoeffs();
  }

  noteOff(_midiNote?: number): void {
    this.gateOpen = false;
  }

  allNotesOff(): void {
    this.gateOpen = false;
    this.envLevel = 0;
    this.accentEnv = 0;
    this.accentAttacking = false;
    this.currentFreq = this.targetFreq;
    this.slideCoeff = 1;
    this.filter.reset();
  }

  private renderOsc(srEff: number): number {
    const phaseInc = this.currentFreq / srEff;
    this.phase += phaseInc;
    if (this.phase >= 1) this.phase -= 1;

    if (this.params.waveform < 0.5) {
      let osc = 2 * this.phase - 1;
      osc -= polyBlep(this.phase, phaseInc);
      return osc;
    }
    let sq = this.phase < 0.5 ? 1 : -1;
    sq += polyBlep(this.phase, phaseInc);
    let t2 = this.phase + 0.5;
    if (t2 >= 1) t2 -= 1;
    sq -= polyBlep(t2, phaseInc);
    const drive = 1 + this.params.squareDrv * 2.5;
    return fastTanh(sq * drive);
  }

  private renderSampleAt(srEff: number): number {
    if (this.slideCoeff !== 1) {
      this.currentFreq *= this.slideCoeff;
      const reached =
        this.slideCoeff > 1
          ? this.currentFreq >= this.targetFreq
          : this.currentFreq <= this.targetFreq;
      if (reached) {
        this.currentFreq = this.targetFreq;
        this.slideCoeff = 1;
      }
    }

    this.envLevel *= this.envDecayRate;
    if (this.envLevel < 1e-6) this.envLevel = 0;

    if (this.accented) {
      if (this.accentAttacking) {
        this.accentEnv += (1 - this.accentEnv) * this.accentAttackRate;
        if (this.accentEnv > 0.995) {
          this.accentEnv = 1;
          this.accentAttacking = false;
        }
      } else {
        this.accentEnv *= this.accentDecayRate;
        if (this.accentEnv < 1e-6) this.accentEnv = 0;
      }
    }

    this.updateFilterCoeffs();
    const osc = this.renderOsc(srEff);
    const filtered = this.filter.process(osc);
    let gain = this.params.volume;
    if (this.accented) gain *= 1 + this.params.accent * 0.35 * this.accentEnv;
    const out = filtered * gain * 0.55;
    if (!Number.isFinite(out)) {
      this.filter.reset();
      return 0;
    }
    return clampf(out, -1.5, 1.5);
  }

  process(output: Float32Array, numFrames = output.length): void {
    const n = this.oversample;
    const srEff = this.sampleRate * n;
    if (n === 1) {
      for (let i = 0; i < numFrames; i++) {
        output[i] = this.renderSampleAt(srEff);
      }
      return;
    }
    const invN = 1 / n;
    for (let i = 0; i < numFrames; i++) {
      let acc = 0;
      for (let s = 0; s < n; s++) acc += this.renderSampleAt(srEff);
      output[i] = acc * invN;
    }
  }
}

/**
 * Models rendered by the diode-ladder CPU engine offline.
 * `live-highfid` (Phase-L1) is included so a freeze / export of a track that
 * plays the live diode ladder bounces through the same topology instead of
 * silently reverting to the stock voice.
 */
export function isHighFidCpuModel(modelId: string): boolean {
  return (
    modelId === HIGHFID_CPU_MODEL_ID ||
    modelId === 'highfid' ||
    modelId === LIVE_HIGHFID_MODEL_ID
  );
}

/** Render a pattern through the highfid-cpu diode-ladder engine. */
export function renderOfflineHighFid303Pattern(
  pattern: Offline303PatternData,
  options: {
    oversample?: OversampleFactor;
    sampleRate?: number;
    blockSize?: number;
  } = {},
): Float32Array {
  const sampleRate = options.sampleRate ?? 44100;
  const oversample = clampOversample(options.oversample);
  const blockSize = options.blockSize ?? 128;
  const tempo = pattern.tempo ?? 120;
  const stepDur = pattern.stepDurationSec ?? (60 / tempo) / 4;

  const engine = new OfflineHighFid303Engine(sampleRate, pattern.params);
  engine.setOversample(oversample);
  if (pattern.highFidCoefficients) engine.setCoefficients(pattern.highFidCoefficients);

  const framesPerStep = Math.max(1, Math.round(stepDur * sampleRate));
  const totalFrames = framesPerStep * pattern.steps.length;
  const out = new Float32Array(totalFrames);
  const block = new Float32Array(blockSize);

  let write = 0;
  let prevNote = -1;
  for (const step of pattern.steps) {
    if (!step.slide && prevNote >= 0) engine.noteOff(prevNote);
    const vel = step.velocity ?? (step.accent ? 120 : 90);
    engine.noteOn(step.note, vel);
    prevNote = step.note;

    let remaining = framesPerStep;
    while (remaining > 0) {
      const n = Math.min(blockSize, remaining);
      engine.process(block, n);
      out.set(block.subarray(0, n), write);
      write += n;
      remaining -= n;
    }
  }
  return out;
}

/**
 * Offline Open303-family soft engine (Phase-1 / #974).
 *
 * Faithful TypeScript port of the open303_wrapper.cpp DSP used by the
 * real-time worklet, with an explicit OVERSAMPLE_FACTOR (1|2|4).
 *
 * Designed for worker / freeze / export paths — never touches AudioWorklet.
 * Each instance owns its filter + envelope state (thread-local); concurrent
 * voices must use separate instances.
 */

