export default AISongModal;

import React, {
  useCallback,
  useRef,
  useState,
  useEffect,
  useMemo,
} from "react";
import {
  NOTES,
  noteToMidi,
  midiToNote,
  getScaleNotes,
  isMidiInScale,
  nextScaleNote,
} from "../utils/musicTheory";
import type { ScaleDefinition } from "../utils/musicTheory";
import { getNoteColor } from "../utils/noteColors";

const SHARP_KEYS = new Set(["C#", "D#", "F#", "G#", "A#"]);

/** Extract the note name (e.g. "C#") from a full note string (e.g. "C#4") */
const extractNoteName = (fullNote: string): string =>
  fullNote.replace(/\d+$/, "");

/** Whether a note name is a sharp (black key) */
const isSharpKey = (noteName: string): boolean => SHARP_KEYS.has(noteName);

interface AdvancedNoteSelectorProps {
  /** Current note value, e.g. "C4" */
  value: string;
  /** Called when the note changes (drag or flyout pick) */
  onChange: (note: string) => void;
  /** Optional track key for color-coding (e.g. 'partA', 'partB') */
  trackKey?: string;
  /** Minimum MIDI note (default: 36 = C2) */
  minMidi?: number;
  /** Maximum MIDI note (default: 84 = C6) */
  maxMidi?: number;
  /** Active scale definition for "Snap to Scale". When set, drag skips out-of-scale notes
   *  and the flyout greys out non-scale keys. */
  currentScale?: ScaleDefinition;
  /** Compact display label override */
  label?: string;
}

const DRAG_THRESHOLD = 4; // pixels before drag starts

// ⚡ Bolt: Added React.memo to prevent unnecessary re-renders when parent state changes.
export const AdvancedNoteSelector: React.FC<AdvancedNoteSelectorProps> =
  React.memo(
    ({
      value,
      onChange,
      trackKey,
      minMidi = 36,
      maxMidi = 84,
      currentScale,
      label,
    }) => {
      const [flyoutOpen, setFlyoutOpen] = useState(false);
      const [activeMidi, setActiveMidi] = useState<number | null>(null);
      const flyoutRef = useRef<HTMLDivElement>(null);

      const pointerActiveRef = useRef(false);
      const isDraggingRef = useRef(false);
      const didDragRef = useRef(false);
      const startYRef = useRef(0);
      const startMidiRef = useRef(0);
      const lastMidiRef = useRef(0);
      const buttonRef = useRef<HTMLButtonElement>(null);

      const currentMidi = noteToMidi(value) || 60;

      // Clamp MIDI to range
      const clamp = useCallback(
        (midi: number) => Math.max(minMidi, Math.min(maxMidi, midi)),
        [minMidi, maxMidi],
      );

      // --- Gestural Drag ---
      const handlePointerDown = useCallback(
        (e: React.PointerEvent<HTMLButtonElement>) => {
          if (e.button !== 0) return; // left-click only
          e.preventDefault();
          try {
            e.currentTarget.setPointerCapture(e.pointerId);
          } catch {
            /* jsdom compat */
          }

          pointerActiveRef.current = true;
          isDraggingRef.current = false;
          didDragRef.current = false;
          startYRef.current = e.clientY;
          startMidiRef.current = currentMidi;
          lastMidiRef.current = currentMidi;
        },
        [currentMidi],
      );

      const handlePointerMove = useCallback(
        (e: React.PointerEvent<HTMLButtonElement>) => {
          if (!pointerActiveRef.current) return;

          const dy = startYRef.current - e.clientY; // up = positive = higher pitch

          if (!isDraggingRef.current) {
            // Check threshold before starting drag
            if (Math.abs(dy) < DRAG_THRESHOLD) return;
            isDraggingRef.current = true;
            didDragRef.current = true;
          }

          // Sensitivity: ~8px per semitone
          const semitones = Math.round(dy / 8);
          let targetMidi = clamp(startMidiRef.current + semitones);

          // Snap to scale if active
          if (currentScale && !isMidiInScale(targetMidi, currentScale)) {
            // Determine drag direction from the mouse movement delta, not from position comparison
            const dragDirection = dy >= 0 ? 1 : -1;
            const direction =
              targetMidi !== lastMidiRef.current
                ? targetMidi > lastMidiRef.current
                  ? 1
                  : -1
                : dragDirection;
            targetMidi = nextScaleNote(
              targetMidi - direction,
              direction as 1 | -1,
              currentScale,
            );
            targetMidi = clamp(targetMidi);
          }

          if (targetMidi !== lastMidiRef.current) {
            lastMidiRef.current = targetMidi;
            onChange(midiToNote(targetMidi));
          }
        },
        [clamp, currentScale, onChange],
      );

      const handlePointerUp = useCallback(
        (e: React.PointerEvent<HTMLButtonElement>) => {
          if (!pointerActiveRef.current) return;
          try {
            e.currentTarget.releasePointerCapture(e.pointerId);
          } catch {
            /* jsdom compat */
          }
          pointerActiveRef.current = false;
          isDraggingRef.current = false;

          // If no drag happened, treat as a click → open flyout
          if (!didDragRef.current) {
            setFlyoutOpen((prev) => {
              if (!prev) setActiveMidi(currentMidi);
              return !prev;
            });
          }
          didDragRef.current = false;
        },
        [currentMidi],
      );

      // --- Flyout ---
      const closeFlyout = useCallback(() => {
        setFlyoutOpen(false);
        buttonRef.current?.focus();
      }, []);

      const handleFlyoutSelect = useCallback(
        (note: string) => {
          onChange(note);
          setFlyoutOpen(false);
        },
        [onChange],
      );

      useEffect(() => {
        if (!flyoutOpen) return;
        const handleKeyDown = (e: KeyboardEvent) => {
          if (e.key === "Escape") {
            closeFlyout();
          } else if (
            e.key === "ArrowUp" ||
            e.key === "ArrowDown" ||
            e.key === "ArrowLeft" ||
            e.key === "ArrowRight"
          ) {
            e.preventDefault();
            setActiveMidi((prev) => {
              const current = prev !== null ? prev : currentMidi;
              let target = current;

              // Up/Down changes pitch within same octave
              if (e.key === "ArrowUp") target = clamp(current + 1);
              if (e.key === "ArrowDown") target = clamp(current - 1);

              // Left/Right changes octave
              if (e.key === "ArrowLeft") target = clamp(current - 12);
              if (e.key === "ArrowRight") target = clamp(current + 12);

              return target;
            });
          } else if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            if (activeMidi !== null) {
              const activeNoteStr = midiToNote(activeMidi);
              const activeNoteName = extractNoteName(activeNoteStr);
              const currentScaleNotes = currentScale
                ? getScaleNotes(currentScale)
                : null;
              if (!currentScaleNotes || currentScaleNotes.has(activeNoteName)) {
                handleFlyoutSelect(activeNoteStr);
              }
            }
          } else if (e.key === "Tab") {
            e.preventDefault();
            closeFlyout();
          }
        };
        // Use capture phase to ensure we handle it before other elements
        window.addEventListener("keydown", handleKeyDown, true);

        // Trap focus to flyout
        flyoutRef.current?.focus();

        return () => window.removeEventListener("keydown", handleKeyDown, true);
      }, [
        flyoutOpen,
        closeFlyout,
        activeMidi,
        currentMidi,
        clamp,
        currentScale,
        handleFlyoutSelect,
      ]);

      // Determine octave range from minMidi/maxMidi
      const octaves = useMemo(() => {
        const minOctave = Math.floor(minMidi / 12) - 1;
        const maxOctave = Math.floor(maxMidi / 12) - 1;
        const octs: number[] = [];
        for (let o = minOctave; o <= maxOctave; o++) {
          octs.push(o);
        }
        return octs;
      }, [minMidi, maxMidi]);

      // Scale note set for filtering
      const scaleNotes = useMemo(
        () => (currentScale ? getScaleNotes(currentScale) : null),
        [currentScale],
      );

      const color = useMemo(
        () => getNoteColor(value, trackKey),
        [value, trackKey],
      );
      const currentNoteName = useMemo(() => extractNoteName(value), [value]);

      const handleKeyDown = useCallback(
        (e: React.KeyboardEvent<HTMLButtonElement>) => {
          if (e.key === "ArrowUp" || e.key === "ArrowRight") {
            e.preventDefault();
            let targetMidi = clamp(currentMidi + 1);
            if (currentScale && !isMidiInScale(targetMidi, currentScale)) {
              targetMidi = nextScaleNote(currentMidi, 1, currentScale);
              targetMidi = clamp(targetMidi);
            }
            if (targetMidi !== currentMidi) {
              onChange(midiToNote(targetMidi));
            }
          } else if (e.key === "ArrowDown" || e.key === "ArrowLeft") {
            e.preventDefault();
            let targetMidi = clamp(currentMidi - 1);
            if (currentScale && !isMidiInScale(targetMidi, currentScale)) {
              targetMidi = nextScaleNote(currentMidi, -1, currentScale);
              targetMidi = clamp(targetMidi);
            }
            if (targetMidi !== currentMidi) {
              onChange(midiToNote(targetMidi));
            }
          }
        },
        [currentMidi, clamp, currentScale, onChange],
      );

      return (
        <div className="relative inline-block">
          {/* Main button: displays current note, supports drag */}
          <button
            type="button"
            ref={buttonRef}
            className="px-1.5 py-0.5 text-[10px] font-mono font-bold rounded cursor-ns-resize select-none touch-none border border-transparent hover:border-cyan-500/50 transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-cyan-400"
            style={{
              backgroundColor: color,
              color: isSharpKey(currentNoteName) ? "#ddd" : "#000",
            }}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onKeyDown={handleKeyDown}
            aria-label={label ?? `Note ${value}`}
            aria-haspopup="true"
            aria-expanded={flyoutOpen}
            aria-controls="advanced-note-selector-listbox"
            title="Drag up/down to change pitch, click to open piano"
          >
            {value}
          </button>

          {/* Piano flyout */}
          {flyoutOpen && (
            <>
              {/* Backdrop */}
              <div
                className="fixed inset-0 z-40"
                onClick={closeFlyout}
                aria-hidden="true"
              />

              <div
                id="advanced-note-selector-listbox"
                ref={flyoutRef}
                role="listbox"
                tabIndex={-1}
                aria-label="Note picker"
                aria-activedescendant={
                  activeMidi !== null ? `note-option-${activeMidi}` : undefined
                }
                className="absolute z-50 left-full top-0 ml-1 bg-gray-900/95 backdrop-blur-sm border border-cyan-900/50 rounded-lg shadow-[0_0_16px_rgba(6,182,212,0.15)] p-1.5 flex gap-1 animate-in fade-in zoom-in-95 duration-100 outline-none"
                style={{ minWidth: "max-content" }}
              >
                {octaves.map((octave) => (
                  <div key={octave} className="flex flex-col gap-0.5">
                    {NOTES.slice()
                      .reverse()
                      .map((noteName) => {
                        const fullNote = `${noteName}${octave}`;
                        const midi = noteToMidi(fullNote);
                        if (midi < minMidi || midi > maxMidi) return null;

                        const noteColor = getNoteColor(fullNote, trackKey);
                        const isSelected = fullNote === value;
                        const isInScale = scaleNotes
                          ? scaleNotes.has(noteName)
                          : true;

                        const isFocused = activeMidi === midi;

                        return (
                          <button
                            type="button"
                            key={fullNote}
                            id={`note-option-${midi}`}
                            role="option"
                            aria-selected={isSelected}
                            aria-disabled={!isInScale}
                            disabled={!isInScale}
                            title={`${fullNote}${!isInScale ? " (Out of scale)" : ""}`}
                            aria-label={`${fullNote}${!isInScale ? " (Out of scale)" : ""}`}
                            onClick={() =>
                              isInScale && handleFlyoutSelect(fullNote)
                            }
                            onPointerEnter={() => setActiveMidi(midi)}
                            className={`w-8 h-5 text-[9px] font-mono rounded flex items-center justify-center transition-all focus:outline-none ${
                              isInScale
                                ? "hover:scale-110 cursor-pointer"
                                : "cursor-not-allowed disabled:opacity-35"
                            } ${isFocused ? "ring-2 ring-offset-1 ring-cyan-400 ring-offset-gray-900 z-10" : ""}`}
                            style={{
                              backgroundColor: isSelected
                                ? "#fff"
                                : isInScale
                                  ? noteColor
                                  : "#333",
                              color: isSelected
                                ? "#000"
                                : !isInScale
                                  ? "#666"
                                  : isSharpKey(noteName)
                                    ? "#ddd"
                                    : "#000",
                              border: isSelected
                                ? `2px solid ${noteColor}`
                                : "none",
                              boxShadow: isSelected
                                ? "0 0 6px rgba(255,255,255,0.5)"
                                : "none",
                            }}
                          >
                            {noteName}
                          </button>
                        );
                      })}
                    <div className="text-center text-[8px] text-cyan-800 font-bold mt-0.5">
                      {octave}
                    </div>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      );
    },
  );

import React, { memo, useCallback } from 'react'
import type { AiImportStage } from '../hooks/useSongStorage'
import type { ReverbType } from '../types'
import { registerMidiControlTouch, startMidiLearnForControl } from '../hooks/useMidi'
import { makeMidiControlId } from '../types/midi'
import { MidiBadge } from './MidiBadge'
import { useMidiMapStore } from '../stores/midiMapStore'
import { automationStore, useAutomationStore } from '../stores/automationStore'
import { useSurfaceTexture, type SurfaceTexture } from '../hooks/useSurfaceTexture'
import { helpDiscoveryStore } from '../stores/helpDiscoveryStore'
import { HelpTip } from './help/HelpTip'

interface BottomBarProps {
    viewMode: 'notes' | 'automation'
    setViewMode: React.Dispatch<React.SetStateAction<'notes' | 'automation'>>
    automationParam: string
    setAutomationParam: React.Dispatch<React.SetStateAction<string>>
    isLyricTrackVisible: boolean
    setIsLyricTrackVisible: React.Dispatch<React.SetStateAction<boolean>>
    isImportingAISong: boolean
    aiImportStage: AiImportStage
    aiImportProgress: number
    exportSongToFile: () => void
    exportRbsToFile: () => void
    exportSmfToFile: () => void
    importSongFromFile: () => void
    setIsRbsImportModalOpen: React.Dispatch<React.SetStateAction<boolean>>
    setIsSmfImportModalOpen: React.Dispatch<React.SetStateAction<boolean>>
    setIsExportModalOpen: React.Dispatch<React.SetStateAction<boolean>>
    setIsAISongModalOpen: React.Dispatch<React.SetStateAction<boolean>>
    setIsCloudLibraryOpen: React.Dispatch<React.SetStateAction<boolean>>
    handleAutoMix: () => void
    reverbType: ReverbType
    handleReverbType: (e: React.ChangeEvent<HTMLSelectElement>) => void
    masterSaturation: number
    handleMasterSaturation: (e: React.ChangeEvent<HTMLInputElement>) => void
    handleMasterSaturationKeyDown: (e: React.KeyboardEvent) => void
    handleMasterSaturationReset: () => void
    masterVolume: number
    handleMasterVolume: (e: React.ChangeEvent<HTMLInputElement>) => void
    handleMasterVolumeKeyDown: (e: React.KeyboardEvent) => void
    handleMasterVolumeReset: () => void
    globalPan: number
    handleGlobalPan: (e: React.ChangeEvent<HTMLInputElement>) => void
    handleGlobalPanKeyDown: (e: React.KeyboardEvent) => void
    handleGlobalPanReset: () => void
    audioEngine: any
    forceScriptProcessorFallback: boolean
    setForceScriptProcessorFallback: React.Dispatch<React.SetStateAction<boolean>>
    showToast: (message: string, type?: 'success' | 'error' | 'info') => void
    setShowGamepadDebug: React.Dispatch<React.SetStateAction<boolean>>
    setIsShortcutsHelpOpen: React.Dispatch<React.SetStateAction<boolean>>
    isAutomationRecording?: boolean
    setIsAutomationRecording?: React.Dispatch<React.SetStateAction<boolean>>
    isPlaying?: boolean
}

export const BottomBar = memo(function BottomBar({
    viewMode,
    setViewMode,
    automationParam,
    setAutomationParam,
    isLyricTrackVisible,
    setIsLyricTrackVisible,
    isImportingAISong,
    aiImportStage,
    aiImportProgress,
    exportSongToFile,
    exportRbsToFile,
    exportSmfToFile,
    importSongFromFile,
    setIsRbsImportModalOpen,
    setIsSmfImportModalOpen,
    setIsExportModalOpen,
    setIsAISongModalOpen,
    setIsCloudLibraryOpen,
    handleAutoMix,
    reverbType,
    handleReverbType,
    masterSaturation,
    handleMasterSaturation,
    handleMasterSaturationKeyDown,
    handleMasterSaturationReset,
    masterVolume,
    handleMasterVolume,
    handleMasterVolumeKeyDown,
    handleMasterVolumeReset,
    globalPan,
    handleGlobalPan,
    handleGlobalPanKeyDown,
    handleGlobalPanReset,
    audioEngine,
    forceScriptProcessorFallback,
    setForceScriptProcessorFallback,
    showToast,
    setShowGamepadDebug,
    setIsShortcutsHelpOpen,
    isAutomationRecording = false,
    setIsAutomationRecording,
    isPlaying = false,
}: BottomBarProps) {
    const { mappings, activeControls } = useMidiMapStore();
    const { showHardwareAutomation } = useAutomationStore();
    const { texture, cycleTexture } = useSurfaceTexture();

    const textureLabel: Record<SurfaceTexture, string> = {
        off: 'TX OFF',
        grain: 'GRAIN',
        circuit: 'PCB',
    };

    const masterMidiProps = useCallback((param: 'volume' | 'saturation' | 'pan') => {
        const controlId = makeMidiControlId('master', param);
        return {
            onPointerDown: () => registerMidiControlTouch('master', param),
            onContextMenu: (e: React.MouseEvent) => {
                e.preventDefault();
                startMidiLearnForControl('master', param);
            },
            'data-midi-control': controlId,
        };
    }, []);

    const isMasterMapped = (param: 'volume' | 'saturation' | 'pan') =>
        mappings.some((m) => m.controlId === makeMidiControlId('master', param));
    const isMasterActive = (param: 'volume' | 'saturation' | 'pan') =>
        activeControls[makeMidiControlId('master', param)] !== undefined;

    const handleAudioWorkletToggle = useCallback(() => {
        const newValue = !forceScriptProcessorFallback;
        setForceScriptProcessorFallback(newValue);
        localStorage.setItem('forceScriptProcessorFallback', String(newValue));
        showToast(
            newValue
                ? "ScriptProcessor fallback enabled. Refresh to apply."
                : "AudioWorklet mode enabled. Refresh to apply.",
            'success'
        );
    }, [forceScriptProcessorFallback, setForceScriptProcessorFallback, showToast]);

    return (
        <div className="fixed bottom-0 left-0 right-0 h-10 hyphon-toolbar-bottom z-40 flex items-center justify-between px-4">
            {/* Left: View Controls */}
            <div className="flex items-center gap-2">
                {/* Notes/Automation Toggle */}
                <div className="flex items-center hyphon-inset-well overflow-hidden" role="group" aria-label="Sequencer view mode">
                    <button type="button"
                        onClick={() => setViewMode('notes')}
                        aria-pressed={viewMode === 'notes'}
                        aria-label="Notes View"
                        title="Notes View"
                        className={`px-2.5 py-1 text-[10px] font-bold transition-all duration-150 focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] rounded ${viewMode === 'notes' ? 'bg-cyan-600 text-white hover:scale-105 active:scale-95' : 'text-gray-500 hover:text-gray-300 hover:scale-105 active:scale-95'}`}
                    >
                        NOTES
                    </button>
                    <button type="button"
                        onClick={() => setViewMode('automation')}
                        aria-pressed={viewMode === 'automation'}
                        aria-label="Automation View"
                        title="Automation View"
                        className={`px-2.5 py-1 text-[10px] font-bold transition-all duration-150 focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] rounded ${viewMode === 'automation' ? 'bg-pink-600 text-white hover:scale-105 active:scale-95' : 'text-gray-500 hover:text-gray-300 hover:scale-105 active:scale-95'}`}
                    >
                        AUTO
                    </button>
                </div>

                {viewMode === 'automation' && (
                    <select
                        value={automationParam}
                        onChange={(e) => setAutomationParam(e.target.value)}
                        aria-label="Automation Parameter"
                        title="Automation Parameter"
                        className="bg-zinc-950 text-[10px] text-gray-300 border border-zinc-800 px-1.5 py-1 transition-all duration-150 focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] rounded"
                    >
                        <option value="formantShift">Formant</option>
                        <option value="vibratoDepth">Vibrato</option>
                        <option value="chordInversion">Chord Inversion</option>
                        <option value="vowel">Vowel (Prophecy)</option>
                        <option value="portamento">Portamento (Prophecy)</option>
                    </select>
                )}

                <div className="w-px h-4 bg-gray-700 mx-1" />

                {/* Live Automation Record Toggle (for creating RBS songs with movement) */}
                {setIsAutomationRecording && (
                    <HelpTip topicId="automation-rec-auto" showOnFirstUse position="top">
                    <button type="button"
                        onClick={() => setIsAutomationRecording(!isAutomationRecording)}
                        disabled={!isPlaying}
                        aria-pressed={isAutomationRecording}
                        aria-label={
                            !isPlaying
                                ? 'Start playback to record automation'
                                : isAutomationRecording
                                    ? 'Stop automation recording'
                                    : 'Record automation'
                        }
                        title={
                            !isPlaying
                                ? 'Start playback to record automation'
                                : isAutomationRecording
                                    ? 'Stop Automation Recording (saves to song lanes)'
