  `;
  document.head.appendChild(style);

  let visible = new URLSearchParams(location.search).get('hud') === '1';
  let audioOutputDevices: MediaDeviceInfo[] = [];
  let sinkListError: string | null = null;
  let reinitError: string | null = null;

  function cpuClass(pct: number): string {
    if (pct >= 80) return 'cpu-hot';
    if (pct >= 50) return 'cpu-warn';
    return 'cpu-ok';
  }

  function render() {
    if (!visible) {
      container.style.display = 'none';
      // Keep it inert while hidden so it stays out of the a11y tree / input.
      if ('inert' in container) { (container as HTMLElement & { inert: boolean }).inert = true; }
      container.setAttribute('aria-hidden', 'true');
      return;
    }
    container.style.display = 'block';
    // Clear inert while shown so the action buttons are operable (inert blocks clicks).
    if ('inert' in container) { (container as HTMLElement & { inert: boolean }).inert = false; }
    container.removeAttribute('aria-hidden');

    const data = engineTelemetry.snapshot();
    const runtime = engineTelemetry.getRuntimeSnapshot();
    const keys = Object.keys(data).sort();

    const budgetClass = cpuClass(runtime.masterBudgetPercent);
    const summary = `<div class="subheader">Audio thread</div>
      <div class="row"><div style="flex:1">Master budget</div><div class="${budgetClass}" style="min-width:72px;text-align:right">${runtime.masterBudgetPercent.toFixed(1)}%</div></div>
      <div class="row"><div style="flex:1">Underruns</div><div style="min-width:72px;text-align:right">${runtime.totalUnderruns}</div></div>
      <div class="row"><div style="flex:1">Sample rate (actual)</div><div style="min-width:72px;text-align:right">${runtime.sampleRate != null ? runtime.sampleRate + ' Hz' : '—'}</div></div>
      <div class="row"><div style="flex:1">Sample rate (requested)</div><div style="min-width:72px;text-align:right">${runtime.requestedSampleRate != null ? runtime.requestedSampleRate + ' Hz' : 'native'}</div></div>
      ${runtime.sampleRateFallback ? `<div class="row"><div style="flex:1">Rate fallback</div><div class="cpu-warn" style="min-width:72px;text-align:right;font-size:10px;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${runtime.sampleRateFallback}">mismatch</div></div>` : ''}
      <div class="row"><div style="flex:1">Output sink</div><div style="min-width:72px;text-align:right;font-size:10px">${runtime.sinkLabel ?? (runtime.sinkId ? runtime.sinkId : 'default')}</div></div>
      <div class="row"><div style="flex:1">Base latency</div><div style="min-width:72px;text-align:right">${runtime.baseLatencyMs != null ? runtime.baseLatencyMs.toFixed(1) + ' ms' : '—'}</div></div>
      <div class="row"><div style="flex:1">Output latency</div><div style="min-width:72px;text-align:right">${runtime.outputLatencyMs != null ? runtime.outputLatencyMs.toFixed(1) + ' ms' : '—'}</div></div>
      <div class="row"><div style="flex:1">Latency hint (active)</div><div style="min-width:72px;text-align:right">${runtime.latencyHint ?? '—'}</div></div>
      <div class="row"><div style="flex:1">Render quantum</div><div style="min-width:72px;text-align:right" title="renderSizeHint requested: ${runtime.renderSizeHintRequested ?? 'default'}">${runtime.renderQuantumSize != null ? runtime.renderQuantumSize + ' fr' : '—'} (${runtime.renderSizeHintRequested ?? 'default'})</div></div>
      ${runtime.contextOptionFallback ? `<div class="row"><div style="flex:1">Option fallback</div><div class="cpu-warn" style="min-width:72px;text-align:right;font-size:10px;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${runtime.contextOptionFallback}">dropped</div></div>` : ''}
      <div class="row"><div style="flex:1">Glitches</div><div style="min-width:72px;text-align:right">${runtime.glitches.length}</div></div>`;

    const storedMode = getStoredLatencyMode();
    const modeButtons = LATENCY_MODES.map((mode) => {
      const active = mode === storedMode;
      const style = active
        ? 'background:#0ea5e9;border-color:#0ea5e9;'
        : '';
      return `<button type="button" aria-label="${mode} latency mode" class="hud-latency-btn" data-mode="${mode}" style="${style}">${mode}</button>`;
    }).join('');
    const storedRate = getStoredSampleRatePref();
    const rateButtons = SAMPLE_RATE_PREFS.map((pref) => {
      const active = pref === storedRate;
      const style = active ? 'background:#0ea5e9;border-color:#0ea5e9;' : '';
      const label = pref === 'native' ? 'native' : pref === 44100 ? '44.1 kHz' : '48 kHz';
      return `<button type="button" aria-label="${label} sample rate" class="hud-rate-btn" data-rate="${pref}" style="${style}">${label}</button>`;
    }).join('');
    const requestedMatchesStored = storedRate === 'native'
      ? runtime.requestedSampleRate == null
      : runtime.requestedSampleRate === storedRate;
    const renderSizeSupported = supportsRenderSizeHint();
    const storedRenderSize = getStoredRenderSizeHintPref();
    const renderSizeButtons = RENDER_SIZE_HINT_PREFS.map((pref) => {
      const active = pref === storedRenderSize;
      const style = active ? 'background:#0ea5e9;border-color:#0ea5e9;' : '';
      return `<button type="button" aria-label="${pref} render size" class="hud-rsize-btn" data-rsize="${pref}" style="${style}">${pref}</button>`;
    }).join('');
    const storedRenderHint = renderSizeSupported ? toAudioContextRenderSizeHint(storedRenderSize) ?? null : null;
    const needsRestart =
      (runtime.latencyHint != null && storedMode !== runtime.latencyHint)
      || (runtime.sampleRate != null && !requestedMatchesStored)
      || (runtime.sampleRate != null && storedRenderHint !== runtime.renderSizeHintRequested);
    const restartNote = needsRestart
      ? `<button type="button" id="hud-apply-restart" aria-label="Apply and re-initialise the audio engine" style="margin-top:4px">${canReinitAudioEngine() ? 'Apply (re-init engine)' : 'Apply &amp; reload'}</button>`
      : '';
    const latencySection = `<div class="subheader">Latency mode</div>
      <div class="row" style="gap:4px">${modeButtons}</div>
      <div class="subheader">Sample rate</div>
      <div class="row" style="gap:4px">${rateButtons}</div>${renderSizeSupported ? `
      <div class="subheader">Render size hint</div>
      <div class="row" style="gap:4px">${renderSizeButtons}</div>` : ''}${reinitError ? `
      <div style="font-size:10px;color:#f87171">${reinitError.replace(/</g, '&lt;')}</div>` : ''}${restartNote}`;

    const sinkSection = supportsSetSinkId()
      ? `<div class="subheader">Audio output</div>
      <div class="row" style="gap:4px;flex-wrap:wrap">
        <button type="button" id="hud-sink-grant" aria-label="List audio output devices">List outputs</button>
        <select id="hud-sink-select" aria-label="Audio output device" style="flex:1;min-width:140px;background:#111;color:#fff;border:1px solid rgba(255,255,255,0.2);font-size:11px">
          <option value="">Default device</option>
          ${audioOutputDevices.map((d) => `<option value="${d.deviceId.replace(/"/g, '&quot;')}">${(d.label || d.deviceId).replace(/</g, '&lt;')}</option>`).join('')}
        </select>
      </div>
      ${sinkListError ? `<div style="font-size:10px;color:#f87171">${sinkListError.replace(/</g, '&lt;')}</div>` : ''}`
      : '';

    const probe = getLastWebGpuProbe();
    const probeSnap = runtime.webgpuProbe;
    const probeTitle = probeSnap
      ? JSON.stringify(probeSnap).replace(/"/g, '&quot;')
      : '';
    const gpuSessionSection = (() => {
      if (!probeSnap && !probe) {
        return `<div class="subheader">WebGPU session</div>
      <div class="row"><div style="flex:1">Probe</div><div style="min-width:72px;text-align:right">—</div></div>`;
      }
      const snap = probeSnap ?? {
        ok: probe!.ok,
        reason: probe!.reason,
        browser: probe!.browser,
        adapter: probe!.adapter,
        ts: probe!.ts,
      };
      if (snap.ok) {
        const desc = snap.adapter?.description || snap.adapter?.vendor || 'adapter';
        return `<div class="subheader">WebGPU session</div>
      <div class="row" title="${probeTitle}"><div style="flex:1">Status</div><div class="cpu-ok" style="min-width:72px;text-align:right">device-ready</div></div>
      <div class="row"><div style="flex:1">Adapter</div><div style="min-width:72px;text-align:right;font-size:10px">${desc}</div></div>`;
      }
      const reason = (snap.reason ?? 'WebGPU unavailable').replace(/</g, '&lt;').replace(/"/g, '&quot;');
      const browser = snap.browser?.engineHint ?? 'unknown';
      return `<div class="subheader">WebGPU session</div>
      <div class="row" title="${probeTitle}"><div style="flex:1">Status</div><div class="cpu-hot" style="min-width:120px;text-align:right">WebGPU unavailable</div></div>
      <div class="row" title="${reason}"><div style="flex:1">Reason</div><div class="cpu-hot" style="min-width:72px;text-align:right;font-size:10px;max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${reason}</div></div>
      <div class="row"><div style="flex:1">Browser</div><div style="min-width:72px;text-align:right;font-size:10px">${browser}</div></div>`;
    })();

    const ts = runtime.transportSync;
    const syncSection = ts ? `<div class="subheader">Transport sync</div>
      <div class="row"><div style="flex:1">Mode</div><div style="min-width:72px;text-align:right">${ts.mode}</div></div>
      <div class="row"><div style="flex:1">State</div><div style="min-width:72px;text-align:right">${syncStateLabel(ts.state)}</div></div>
      <div class="row"><div style="flex:1">Device</div><div style="min-width:72px;text-align:right;font-size:10px">${ts.deviceName ?? '—'}</div></div>
      <div class="row"><div style="flex:1">Measured BPM</div><div style="min-width:72px;text-align:right">${ts.measuredBpm != null ? ts.measuredBpm.toFixed(1) : '—'}</div></div>
      <div class="row"><div style="flex:1">Phase err</div><div style="min-width:72px;text-align:right">${ts.phaseErrorMs.toFixed(1)} ms</div></div>
      <div class="row"><div style="flex:1">Jitter p95</div><div style="min-width:72px;text-align:right">${ts.jitterMs.toFixed(1)} ms</div></div>
      <div class="row"><div style="flex:1">Dropouts</div><div style="min-width:72px;text-align:right">${ts.droppedClocks}</div></div>
      <div class="hud-actions" style="margin-top:4px;border-top:none;padding-top:0"><button type="button" id="hud-resync-btn" aria-label="Resync transport clock">Resync</button></div>` : '';

    const offlineOs = runtime.offlineRenderOversample != null ? `${runtime.offlineRenderOversample}×` : '—';
    const offlineThreads = runtime.offlineRenderThreadCount != null ? String(runtime.offlineRenderThreadCount) : '—';
    const offlineLat = runtime.offlineRenderLatencyMs != null ? `${runtime.offlineRenderLatencyMs.toFixed(1)} ms` : '—';
    const gpuLat = runtime.gpuRenderLatencyMs != null ? `${runtime.gpuRenderLatencyMs.toFixed(1)} ms` : '—';
    const gpuBackend =
      runtime.gpuUsedGpu === true
        ? 'webgpu'
        : runtime.gpuUsedGpu === false
          ? 'cpu-fb'
          : '—';
    const gpuFb =
      runtime.gpuFallbackReason != null
        ? runtime.gpuFallbackReason.slice(0, 42)
        : '—';
    const gpuAvail =
      runtime.gpuAvailable === true ? 'yes' : runtime.gpuAvailable === false ? 'no' : '—';
    const hfReq = runtime.highFidRequested ?? '—';
    const hfActive = runtime.highFidActiveEngine ?? '—';
    const hfSelFb =
      runtime.highFidFallbackReason != null
        ? runtime.highFidFallbackReason.slice(0, 42)
        : '—';
    // Phase-L1 — which realtime 303 path is actually audible.
    const liveHfActive = runtime.liveHighFidActive === true;
    const liveHfBadge = liveHfActive
        ? 'LIVE HIFID'
        : runtime.liveHighFidActive === false
          ? 'stock (degraded)'
          : '—';
    const liveHfClass = liveHfActive ? 'cpu-ok' : runtime.liveHighFidActive === false ? 'cpu-hot' : '';
    const liveHfCpu =
        runtime.liveHighFidCpuPercent != null ? `${runtime.liveHighFidCpuPercent.toFixed(0)}%` : '—';
    const liveHfOs = runtime.liveHighFidOversample != null ? `${runtime.liveHighFidOversample}×` : '—';
    const liveHfReason = runtime.liveHighFidFallbackReason ?? '';
    // Phase-L2 — live A/B: one CPU row per side, the gate only ever trips B.
    const pct = (v: number | null) => (v != null ? `${v.toFixed(0)}%` : '—');
    const abMix = runtime.liveAbMix != null ? `${Math.round(runtime.liveAbMix * 100)}% B` : '—';
    const abRows = runtime.liveAbEngaged !== true ? '' : `
      <div class="row" title="Live A/B blend: 0% = stock Open303 (A), 100% = live high-fid (B)"><div style="flex:1">A/B blend</div><div style="min-width:72px;text-align:right">${abMix}</div></div>
      <div class="row"><div style="flex:1">A stock CPU</div><div style="min-width:72px;text-align:right">${pct(runtime.liveAbStockCpuPercent)}</div></div>
      <div class="row"><div style="flex:1">B hifi CPU</div><div style="min-width:72px;text-align:right">${pct(runtime.liveAbHighFidCpuPercent)}</div></div>`;
    const liveSection = runtime.liveHighFidActive == null ? '' : `<div class="subheader">Live 303 path</div>
      <div class="row" title="${liveHfReason}"><div style="flex:1">Audible</div><div class="${liveHfClass}" style="min-width:96px;text-align:right;font-size:10px">${liveHfBadge}</div></div>
      <div class="row"><div style="flex:1">HiFi CPU</div><div style="min-width:72px;text-align:right">${liveHfCpu} @ ${liveHfOs}</div></div>${abRows}
      ${liveHfReason ? `<div class="row" title="${liveHfReason}"><div style="flex:1">Fallback</div><div class="cpu-hot" style="min-width:72px;text-align:right;font-size:10px;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${liveHfReason}</div></div>` : ''}`;

    // One shared hyphon_native heap for 303 + Prophecy + live high-fid.
    const heap = runtime.hyphonNativeHeap;
    const heapMb = (pages: number) => `${Math.round((pages * 65536) / 1048576)} MB`;
    const heapSection = heap == null ? '' : `<div class="subheader">Voice WASM heap</div>
      <div class="row" title="hyphon_native link profile: pthread (shared memory, crossOriginIsolated) or single-threaded (WebKit / no COOP+COEP / forceSingleThreaded)"><div style="flex:1">Build</div><div style="min-width:72px;text-align:right">${heap.threading === 'st' ? 'single-threaded' : heap.threading}</div></div>
      <div class="row" title="hyphon_native memories in this audio session (expected 1)"><div style="flex:1">Heaps</div><div class="${heap.heapCount === 1 ? 'cpu-ok' : 'cpu-hot'}" style="min-width:72px;text-align:right">${heap.heapCount}</div></div>
      <div class="row"><div style="flex:1">Initial</div><div style="min-width:72px;text-align:right">${heap.initialPages} pg (${heapMb(heap.initialPages)})</div></div>
      <div class="row"><div style="flex:1">Current</div><div style="min-width:72px;text-align:right">${heapMb(heap.currentPages)} · ${heap.growEvents} grow</div></div>
      <div class="row"><div style="flex:1">Voices</div><div style="min-width:72px;text-align:right">${heap.voices}</div></div>`;

    const offlineSection = `<div class="subheader">Offline 303</div>
      <div class="row"><div style="flex:1">Oversample</div><div style="min-width:72px;text-align:right">${offlineOs}</div></div>
      <div class="row"><div style="flex:1">Threads</div><div style="min-width:72px;text-align:right">${offlineThreads}</div></div>
      <div class="row"><div style="flex:1">Last render</div><div style="min-width:72px;text-align:right">${offlineLat}</div></div>
      <div class="row"><div style="flex:1">WebGPU</div><div style="min-width:72px;text-align:right">${gpuAvail}</div></div>
      <div class="row"><div style="flex:1">HiFi select</div><div style="min-width:72px;text-align:right;font-size:10px" title="${runtime.highFidRequested ?? ''}">${hfReq}</div></div>
      <div class="row"><div style="flex:1">HiFi active</div><div style="min-width:72px;text-align:right;font-size:10px">${hfActive}</div></div>
      <div class="row" title="${runtime.highFidFallbackReason ?? ''}"><div style="flex:1">HiFi fallback</div><div style="min-width:72px;text-align:right;font-size:10px">${hfSelFb}</div></div>
      <div class="row"><div style="flex:1">GPU 303</div><div style="min-width:72px;text-align:right">${gpuBackend} ${gpuLat}</div></div>
      <div class="row" title="${runtime.gpuFallbackReason ?? ''}"><div style="flex:1">GPU fallback</div><div style="min-width:72px;text-align:right;font-size:10px">${gpuFb}</div></div>`;

    // Oscillator backend chain (#1034): shows every backend in preference order,
    // which one is active, and why the higher-preference ones were skipped.
    const registry = getOscillatorRegistry();
    const resolution = registry?.getLastResolution() ?? null;
    const backendSection = (() => {
      if (!resolution) return '';
      const attemptRows = resolution.attempts.map((a) => {
        const active = a.id === resolution.active;
        const state = active ? 'ACTIVE' : a.reason ?? (a.ready ? 'ready' : 'not ready');
        const color = active ? '#86efac' : a.reason ? '#f87171' : '#9ca3af';
        return `<div class="row" title="${a.reason ?? ''}">
          <div class="badge backend-${a.id}" title="${BACKEND_LABELS[a.id] ?? a.id}">${BACKEND_LABELS[a.id] ?? a.id}</div>
          <div style="flex:1"></div>
          <div style="color:${color};font-size:10px;text-align:right;max-width:190px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${state}</div>
        </div>`;
      }).join('');
      const header = resolution.degraded
        ? `<div style="font-size:11px;color:#fde047" title="${resolution.reason ?? ''}">fallback: ${resolution.requested} → ${resolution.active}</div>`
        : `<div style="font-size:11px;opacity:0.7">preferred backend active (${resolution.active})</div>`;
      return `<div class="subheader">Oscillator backends</div>${header}${attemptRows}`;
    })();

    const workletNames = ['clock', 'open303', 'rubberband', 'vocoder'];
    const workletRows = workletNames.map((name) => {
      const w = runtime.worklets[name];
      const cpu = w ? w.cpuPercent.toFixed(1) : '—';
      const und = w ? String(w.underruns) : '—';
      const cls = w ? cpuClass(w.cpuPercent) : '';
      return `<div class="row"><div style="flex:1">${name}</div><div class="${cls}" style="min-width:56px;text-align:right">${cpu}%</div><div style="width:48px;text-align:right" title="underruns">${und}</div></div>`;
    }).join('');

    const rows = keys.map(k => {
      const v = data[k];
      const backend = v?.resolution?.backend || 'unknown';
      const p50 = v?.p50 != null ? v.p50.toFixed(1) : '-';
      const p95 = v?.p95 != null ? v.p95.toFixed(1) : '-';
      const err = v?.errors?.count ? `${v.errors.count} err` : '';
      const wCpu = v?.worklet?.cpuPercent != null ? `${v.worklet.cpuPercent.toFixed(0)}%` : '';
      return `<div class="row"><div class="badge backend-${backend}">${backend}</div><div style="flex:1">${k}</div><div style="min-width:48px;text-align:right">${wCpu}</div><div style="min-width:72px;text-align:right">${p50}/${p95} ms</div><div style="width:48px;text-align:right">${err}</div></div>`;
    }).join('');

    const degradeNote = runtime.degradations.length
      ? `<div class="subheader">Degradations</div><div style="font-size:11px;opacity:0.85">${runtime.degradations.slice(-3).map(d => `${d.step}: ${d.active ? 'ON' : 'off'}`).join(' · ')}</div>`
      : '';

    const wamRows = (runtime.wam2Slots ?? []).map((slot) => {
      const cls = slot.status === 'ready' ? 'cpu-ok' : slot.status === 'bypassed' ? 'cpu-warn' : 'cpu-hot';
      const err = slot.lastError ? ` title="${slot.lastError.replace(/"/g, '&quot;')}"` : '';
      const freeze = slot.offline === 'native'
        ? '<span title="Renders natively in an OfflineAudioContext" style="opacity:0.7">freeze ok</span>'
        : '<span title="Cannot be rendered in an OfflineAudioContext — track freeze is unavailable for this slot" style="color:#fbbf24">no freeze</span>';
      const mounted = slot.status === 'ready' || slot.status === 'bypassed';
      const bypassLabel = slot.status === 'bypassed' ? 'Unbypass' : 'Bypass';
      const controls = `<button type="button" aria-label="${bypassLabel} slot ${slot.slotId}" class="hud-wam-bypass" data-slot="${slot.slotId}" ${mounted ? '' : 'disabled'}>${bypassLabel}</button><button type="button" aria-label="Restart slot ${slot.slotId}" class="hud-wam-restart" data-slot="${slot.slotId}">Restart</button>`;
      return `<div class="row"${err}><div class="badge backend-wam2">wam2</div><div style="flex:1">${slot.slotId}<div style="font-size:10px;opacity:0.7">${slot.packageId}@${slot.version} · ${slot.origin} · ${freeze}</div></div><div class="${cls}" style="min-width:72px;text-align:right">${slot.status}</div><div style="width:48px;text-align:right" title="${slot.cpuPercent == null ? 'no per-slot meter (plugin exposes none)' : 'plugin-reported DSP load'}">${slot.cpuPercent == null ? '—' : `${slot.cpuPercent.toFixed(0)}%`}</div><div style="width:56px;text-align:right">${slot.latencyMs.toFixed(1)}ms</div><div class="hud-wam-actions">${controls}</div></div>`;
    }).join('');
    const coop = runtime.wam2Constraints
      ? `<div class="row"><div style="flex:1">COOP isolated</div><div style="min-width:72px;text-align:right">${runtime.wam2Constraints.crossOriginIsolated ? 'yes' : 'no'}</div></div>
         <div class="row"><div style="flex:1">Worklet / Worker</div><div style="min-width:72px;text-align:right">${runtime.wam2Constraints.audioWorklet ? 'AW' : '—'} / ${runtime.wam2Constraints.worker ? 'W' : '—'}</div></div>
         <div class="row"><div style="flex:1">BASE_URL</div><div style="min-width:72px;text-align:right;font-size:10px">${runtime.wam2Constraints.baseUrl}</div></div>`
      : '';
    const wamSection = `<div class="subheader">WAM2 slots</div>${wamRows || '<div class="row"><div style="flex:1;opacity:0.7">none mounted</div></div>'}${coop}`;

    container.innerHTML = `<div class="header">Engine HUD</div>${summary}${syncSection}${latencySection}${sinkSection}${gpuSessionSection}${liveSection}${heapSection}${offlineSection}${backendSection}<div class="subheader">Worklets</div>${workletRows}${degradeNote}${wamSection}<div class="subheader">Subsystems</div>${rows}<div class="hud-actions"><button type="button" id="hud-export-btn" aria-label="Download engine telemetry report">Download Report</button><button type="button" id="hud-copy-btn" aria-label="Copy engine telemetry to clipboard">Copy JSON</button></div>`;
  }

  // Event delegation: render() replaces innerHTML every 500ms, so per-render
  // listeners would be discarded. Bind once on the persistent container instead.
  container.addEventListener('click', (e) => {
    const target = e.target as HTMLElement | null;
    if (!target) return;
    if (target.classList.contains('hud-wam-bypass') || target.classList.contains('hud-wam-restart')) {
      const slotId = target.getAttribute('data-slot');
      const host = getWamHost();
      if (!slotId || !host) return;
      if (target.classList.contains('hud-wam-bypass')) {
        // Read current state from the host rather than the rendered label: the
        // HUD re-renders on a timer and could be up to one tick stale.
        host.setBypass(slotId, host.getSlotStatus(slotId) !== 'bypassed');
        render();
      } else {
        target.setAttribute('disabled', 'true');
        void host.restartSlot(slotId).finally(render);
      }
      return;
    }
    if (target.id === 'hud-export-btn') {
      engineTelemetry.exportReport();
    } else if (target.id === 'hud-resync-btn') {
      transportSyncStore.resync();
      render();
    } else if (target.classList.contains('hud-latency-btn')) {
      const mode = target.getAttribute('data-mode') as LatencyMode | null;
      if (mode) {
        setStoredLatencyMode(mode);
        render();
      }
    } else if (target.classList.contains('hud-rate-btn')) {
      const raw = target.getAttribute('data-rate');
      const pref: SampleRatePref | null = raw === 'native' ? 'native' : raw === '44100' ? 44100 : raw === '48000' ? 48000 : null;
      if (pref) {
        setStoredSampleRatePref(pref);
        render();
      }
    } else if (target.classList.contains('hud-rsize-btn')) {
      const pref = parseRenderSizeHintPref(target.getAttribute('data-rsize'));
      if (pref) {
        setStoredRenderSizeHintPref(pref);
        render();
      }
    } else if (target.id === 'hud-apply-restart') {
      if (!canReinitAudioEngine()) {
        location.reload();
        return;
      }
      // Synchronous call from the click: the new context is built and
      // resumed inside this gesture, before any await (see audioEngineReinit).
      target.setAttribute('disabled', 'true');
      reinitError = null;
      reinitAudioEngineFromGesture()
        .catch((err: unknown) => {
          reinitError = err instanceof Error ? err.message : 'Audio engine re-init failed';
        })
        .finally(render);
    } else if (target.id === 'hud-sink-grant') {
      void (async () => {
        try {
          await requestAudioOutputPermission();
          audioOutputDevices = await listAudioOutputDevices();
          sinkListError = null;
        } catch (err) {
          sinkListError = err instanceof Error ? err.message : 'Could not list audio outputs';
        }
        render();
      })();
    } else if (target.id === 'hud-copy-btn') {
      const json = engineTelemetry.generateReportJSON();
      if (navigator.clipboard?.writeText) {
        const orig = target.textContent;
        navigator.clipboard.writeText(json).then(() => {
          target.textContent = 'Copied!';
          setTimeout(() => { target.textContent = orig; }, 1500);
        }).catch(() => { /* clipboard denied; no-op */ });
      }
    }
  });

  container.addEventListener('change', (e) => {
    const target = e.target as HTMLElement | null;
    if (!target || target.id !== 'hud-sink-select') return;
    const select = target as HTMLSelectElement;
    const deviceId = select.value;
    const device = audioOutputDevices.find((d) => d.deviceId === deviceId);
    setStoredAudioOutput(device ? { groupId: device.groupId, label: device.label, deviceId: device.deviceId } : null);
    const ctx = (window as Window & { audioContext?: AudioContext }).audioContext;
    if (ctx) {
      void applyAudioOutputSink(ctx, deviceId).then((sink) => {
        if (sink) engineTelemetry.recordAudioOutputSink(sink);
        render();
      });
    }
  });

  render();
  const timer = setInterval(render, 500);

  window.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key.toLowerCase() === 'e') {
      visible = !visible;
      render();
    }
  });

  // Cleanup not necessary for dev overlay; keep mounted for session lifetime.
}

import React, { useCallback, useEffect, useRef, useState } from 'react';
import { useFocusTrap } from '../hooks/useFocusTrap';
import type { Pattern, SynthParams, KickParams, SnareParams, HatParams, SamplerParams, Bass2Params } from '../types';
import type { TrackKey } from '../constants/appDefaults';
import {
    exportStemsDownload,
    type StemExportOptions,
    type StemExportReport,
    type StemMasterChain,
} from '../utils/stemExport';
import {
    getStoredSampleRatePref,
    resolveExportSampleRate,
    SAMPLE_RATE_PREFS,
    type SampleRatePref,
} from '../utils/audioContextPolicy';
import type { WavBitDepth } from '../utils/audioExport';
import type { RenderSynthEngines } from '../utils/renderAudio';

export interface ExportModalProps {
    isOpen: boolean;
    onClose: () => void;
    onShowToast: (message: string, type?: 'success' | 'error' | 'info') => void;
    songStructure: { [key in TrackKey]: number | null }[];
    trackStorage: Record<TrackKey, (import('../types').PartSequence | import('../types').PartSequence[] | null)[]>;
    currentPattern: Pattern;
    tempo: number;
    params: {
        synthA: SynthParams;
        synthB: SynthParams;
        bass2: Bass2Params;
        kick: KickParams;
        snare: SnareParams;
        closedHat: HatParams;
        openHat: HatParams;
        sampler: SamplerParams;
    };
    engines?: RenderSynthEngines;
    sampleBuffers: (AudioBuffer | null)[];
    /** Preferred sample rate from the live AudioContext when available. */
    preferredSampleRate?: number;
}

type ExportPhase = 'idle' | 'exporting' | 'done' | 'cancelled' | 'error';

/** Success toast: what the ZIP actually contains. */
function describeExport(report: StemExportReport | null): string {
    if (!report) return 'Stem ZIP downloaded';
    const master = report.routing === 'live-patch' ? 'live-patch master' : 'dry master';
    return `Stem ZIP downloaded · ${report.sampleRate} Hz · ${master}`;
}

/** Follow-up toast for anything the bounce could not honour. */
function describeExportWarning(report: StemExportReport | null): string | null {
    if (!report) return null;
    if (report.routing === 'dry-exclusive-fallback') return report.routingNote;

    const bypassed = report.offlineGraph?.slots.filter((slot) => slot.status === 'bypassed') ?? [];
    if (bypassed.length === 0) return null;
    const names = bypassed.map((slot) => slot.packageId ?? slot.nodeId).join(', ');
    return `${bypassed.length} WAM2 insert${bypassed.length === 1 ? '' : 's'} cannot render offline and `
        + `${bypassed.length === 1 ? 'was' : 'were'} bypassed in the master bounce: ${names}`;
}

export const ExportModal = React.memo(function ExportModal({
    isOpen,
    onClose,
    onShowToast,
    songStructure,
    trackStorage,
    currentPattern,
    tempo,
    params,
    engines,
    sampleBuffers,
    preferredSampleRate,
}: ExportModalProps) {
    const [phase, setPhase] = useState<ExportPhase>('idle');
    const [progress, setProgress] = useState(0);
    const [statusLabel, setStatusLabel] = useState('');
    const [useSongMode, setUseSongMode] = useState(true);
    // The export follows the same sample-rate policy the live context does
    // (#1136 / #1233): `native` means "whatever the running engine came up
    // with", not a second, silently different rate.
    const [sampleRatePref, setSampleRatePref] = useState<SampleRatePref>(() =>
        getStoredSampleRatePref(),
    );
    const [bitDepth, setBitDepth] = useState<WavBitDepth>(16);
    const [masterChain, setMasterChain] = useState<StemMasterChain>('live-patch');
    const sampleRate = resolveExportSampleRate(sampleRatePref, preferredSampleRate);
    const abortRef = useRef<AbortController | null>(null);
    const modalRef = useFocusTrap(isOpen, onClose);

    useEffect(() => {
        if (!isOpen) {
            abortRef.current?.abort();
            abortRef.current = null;
            setPhase('idle');
            setProgress(0);
            setStatusLabel('');
        }
    }, [isOpen]);

    const handleCancel = useCallback(() => {
        abortRef.current?.abort();
        abortRef.current = null;
        setPhase('cancelled');
        setStatusLabel('Export cancelled');
    }, []);

    const handleExport = useCallback(async () => {
        if (phase === 'exporting') return;

        const controller = new AbortController();
        abortRef.current = controller;
        setPhase('exporting');
        setProgress(0);
        setStatusLabel('Starting export…');

        let report: StemExportReport | null = null;

        const options: StemExportOptions = {
            onReport: (value) => {
                report = value;
            },
            sampleRatePref,
            liveSampleRate: preferredSampleRate ?? null,
            bitDepth,
            useSongMode,
            masterChain,
            signal: controller.signal,
            onProgress: (pct, label) => {
                setProgress(pct);
                setStatusLabel(label);
            },
        };

        try {
            await exportStemsDownload(
                {
                    songStructure,
                    trackStorage,
                    currentPattern,
                    tempo,
                    params,
                    engines,
                    sampleBuffers,
                },
                options,
            );

            if (controller.signal.aborted) return;

            setPhase('done');
            setProgress(1);
            setStatusLabel('Export complete');
            onShowToast(describeExport(report), 'success');

            // A bounce that had to drop an insert, or fall back to the dry sum,
            // says so rather than leaving it to be noticed inside the ZIP.
            const warning = describeExportWarning(report);
            if (warning) onShowToast(warning, 'info');
            onClose();
        } catch (err) {
            if (controller.signal.aborted || (err instanceof DOMException && err.name === 'AbortError')) {
                setPhase('cancelled');
                setStatusLabel('Export cancelled');
                return;
            }
            console.error('Stem export failed:', err);
            setPhase('error');
            setStatusLabel(err instanceof Error ? err.message : 'Export failed');
            onShowToast('Stem export failed', 'error');
        } finally {
            abortRef.current = null;
        }
    }, [
        phase,
        sampleRatePref,
        preferredSampleRate,
        masterChain,
        bitDepth,
        useSongMode,
        songStructure,
        trackStorage,
        currentPattern,
        tempo,
        params,
        engines,
        sampleBuffers,
        onShowToast,
        onClose,
    ]);

    if (!isOpen) return null;

    const isExporting = phase === 'exporting';

    return (
        <div
            className="fixed inset-0 z-[200] flex items-center justify-center bg-black/70 backdrop-blur-sm"
            role="dialog"
            aria-modal="true"
            aria-labelledby="export-modal-title"
            ref={modalRef}
        >
            <div className="absolute inset-0 z-0" onClick={onClose} aria-hidden="true" />
            <div className="w-full max-w-md mx-4 bg-[#0f1218] border border-cyan-800/40 rounded-xl shadow-2xl overflow-hidden relative z-10">
                <div className="px-5 py-4 border-b border-gray-800 flex items-center justify-between">
                    <h2 id="export-modal-title" className="text-sm font-bold text-cyan-300 tracking-wider">
                        EXPORT STEMS
                    </h2>
                    <button
                        type="button"
                        onClick={onClose}
                        disabled={isExporting}
                        aria-label="Close export dialog"
                        title={isExporting ? "Cannot close while exporting" : "Close export dialog"}
                        className="text-gray-400 hover:text-white disabled:opacity-40"
                    >
                        <span aria-hidden="true">✕</span>
                    </button>
                </div>

                <div className="px-5 py-4 space-y-4">
                    <p className="text-xs text-gray-400">
                        Dry per-track WAVs (partA, partB, bass2, drums, 8 sampler banks, master) packaged as a ZIP.
                        {masterChain === 'live-patch'
                            ? ' Master is the dry sum bounced through the live patch bay (master FX + loudness stage).'
                            : ' Master is the sum of dry stems without master FX.'}
                    </p>

                    <label className="flex items-center gap-2 text-xs text-gray-300">
                        <input
                            type="checkbox"
                            checked={useSongMode}
                            onChange={(e) => setUseSongMode(e.target.checked)}
                            disabled={isExporting}
                            className="accent-cyan-500"
                        />
                        Use song arrangement (uncheck for current pattern only)
                    </label>

                    <div className="grid grid-cols-2 gap-3">
                        <label className="text-xs text-gray-400">
                            Sample rate
                            <select
                                value={String(sampleRatePref)}
                                onChange={(e) =>
                                    setSampleRatePref(
                                        e.target.value === 'native'
                                            ? 'native'
                                            : (Number(e.target.value) as SampleRatePref),
                                    )
                                }
                                disabled={isExporting}
                                className="mt-1 w-full bg-gray-900 border border-gray-700 rounded px-2 py-1.5 text-gray-200 text-xs"
                            >
                                {SAMPLE_RATE_PREFS.map((pref) => (
                                    <option key={String(pref)} value={String(pref)}>
                                        {pref === 'native'
                                            ? `Match live (${sampleRate} Hz)`
                                            : pref === 44100
                                              ? '44.1 kHz'
                                              : '48 kHz'}
                                    </option>
                                ))}
                            </select>
                        </label>
                        <label className="text-xs text-gray-400">
                            Bit depth
                            <select
                                value={bitDepth}
                                onChange={(e) => setBitDepth(Number(e.target.value) as WavBitDepth)}
                                disabled={isExporting}
                                className="mt-1 w-full bg-gray-900 border border-gray-700 rounded px-2 py-1.5 text-gray-200 text-xs"
                            >
                                <option value={16}>16-bit</option>
                                <option value={24}>24-bit</option>
                            </select>
                        </label>
                    </div>

                    <label className="flex items-center gap-2 text-xs text-gray-300">
                        <input
                            type="checkbox"
                            checked={masterChain === 'live-patch'}
                            onChange={(e) =>
                                setMasterChain(e.target.checked ? 'live-patch' : 'dry-exclusive')
                            }
                            disabled={isExporting}
                            className="accent-cyan-500"
                        />
                        Bounce master through the live patch (what you hear)
                    </label>

                    {preferredSampleRate && preferredSampleRate !== sampleRate && (
                        <p className="text-[10px] text-amber-400/90">
                            Live AudioContext is {preferredSampleRate} Hz — exporting at {sampleRate} Hz
                            resamples. Pick “Match live” to bounce at the monitored rate.
                        </p>
                    )}

                    {(isExporting || phase === 'cancelled' || phase === 'error') && (
                        <div className="space-y-2">
                            <div className="h-2 bg-gray-800 rounded-full overflow-hidden">
                                <div
                                    className="h-full bg-gradient-to-r from-cyan-600 to-cyan-400 transition-all duration-200"
                                    style={{ width: `${Math.round(progress * 100)}%` }}
                                />
                            </div>
                            <p className="text-[10px] text-gray-400 font-mono" aria-live="polite">
                                {statusLabel || 'Preparing…'}
                            </p>
                        </div>
                    )}
                </div>

                <div className="px-5 py-4 border-t border-gray-800 flex justify-end gap-2">
                    {isExporting ? (
                        <button
                            type="button"
                            onClick={handleCancel}
                            className="px-4 py-2 text-xs font-bold rounded-lg border border-red-700/50 text-red-300 hover:bg-red-900/30"
                        >
                            Cancel
                        </button>
                    ) : (
                        <>
                            <button
                                type="button"
                                onClick={onClose}
                                className="px-4 py-2 text-xs font-bold rounded-lg border border-gray-700 text-gray-400 hover:text-white"
                            >
                                Close
                            </button>
                            <button
                                type="button"
                                onClick={handleExport}
                                className="px-4 py-2 text-xs font-bold rounded-lg bg-gradient-to-r from-cyan-900/60 to-cyan-800/60 text-cyan-300 border border-cyan-700/50 hover:from-cyan-800/80 hover:to-cyan-700/80"
                            >
                                Download ZIP
                            </button>
                        </>
                    )}
                </div>
            </div>
        </div>
    );
});

export default ExportModal;

