            </div>
        </div>
    );
};

// --- PIANO KEY COMPONENT ---
interface PianoKeyProps {
    note: string;
    /** Semitone offset from the base octave's C — what the handlers receive. */
    offset: number;
    x: number;
    y: number;
    width: number;
    height: number;
    label: string | null;
    isBlack: boolean;
    isActive: boolean;
    isHeldByMouse: boolean;
    activeColor: string;
    onMouseDown: (offset: number) => void;
    onMouseEnter: (offset: number) => void;
    onStopMouse: () => void;
}

const PianoKey = memo(({
    note, offset, x, y, width, height, label, isBlack,
    isActive, activeColor, onMouseDown, onMouseEnter, onStopMouse
}: PianoKeyProps) => {
    const noteBase = getNoteBase(note);
    const noteColor = NOTE_COLORS[noteBase] || '#94a3b8';

    // Active state with glow
    const glowColor = isActive ? activeColor : noteColor;
    const pressOffset = isActive ? 3 : 0;

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            onMouseDown(offset);
        } else if (e.key === 'Escape') {
            e.preventDefault();
            onStopMouse();
        }
    };

    return (
        <g
            transform={`translate(${x}, ${y})`}
            role="button"
            aria-label={`Play ${note}`}
            aria-pressed={isActive}
            tabIndex={0}
            onMouseDown={(e) => { if (e.button === 0) onMouseDown(offset); }}
            onMouseEnter={(e) => { if (e.buttons === 1) onMouseEnter(offset); else onStopMouse(); }}
            onMouseUp={onStopMouse}
            onMouseLeave={onStopMouse}
            onTouchStart={(e) => { e.preventDefault(); onMouseDown(offset); }}
            onTouchEnd={(e) => { e.preventDefault(); onStopMouse(); }}
            onKeyDown={handleKeyDown}
            cursor="pointer"
            className="focus:outline-none"
        >
            {/* Shadow underneath */}
            <rect 
                x={isBlack ? 2 : 2} 
                y={height - 6 + pressOffset} 
                width={width - 4} 
                height={isBlack ? 6 : 8} 
                rx={isBlack ? 2 : 4} 
                fill="#000" 
                opacity={0.4} 
            />

            <g transform={`translate(0, ${pressOffset})`} style={{ transition: 'transform 0.03s ease-out' }}>
                {/* Key body */}
                <rect 
                    x={0} 
                    y={0} 
                    width={width} 
                    height={height} 
                    rx={isBlack ? 3 : 4} 
                    fill={isBlack ? '#0f172a' : '#f8fafc'}
                    stroke={isBlack ? '#000' : '#cbd5e1'}
                    strokeWidth={2}
                />

                {/* Key face (main surface) */}
                <rect 
                    x={2} 
                    y={2} 
                    width={width - 4} 
                    height={height - 8} 
                    rx={isBlack ? 2 : 3} 
                    fill={isActive ? activeColor : (isBlack ? '#1f2937' : '#f8fafc')}
                />

                {/* Specular highlight */}
                {!isBlack && (
                    <rect 
                        x={4} 
                        y={3} 
                        width={width - 8} 
                        height={4} 
                        rx={1} 
                        fill="rgba(255,255,255,0.8)"
                        opacity={0.7}
                    />
                )}

                {/* LED rim glow when active */}
                {isActive && (
                    <rect 
                        x={2} 
                        y={2} 
                        width={width - 4} 
                        height={height - 8} 
                        rx={isBlack ? 2 : 3} 
                        fill="transparent" 
                        stroke={glowColor}
                        strokeWidth={3}
                        style={{ filter: `drop-shadow(0 0 12px ${glowColor}) drop-shadow(0 0 4px #fff)` }}
                    />
                )}

                {/* Note name */}
                <text 
                    x={width / 2} 
                    y={height / 2 + (isBlack ? 3 : 5)} 
                    fill={isActive ? '#fff' : (isBlack ? '#e2e8f0' : noteColor)}
                    fontSize={isBlack ? 12 : 16} 
                    fontWeight="bold"
                    textAnchor="middle" 
                    pointerEvents="none"
                    style={{ textShadow: isActive ? '0 0 8px rgba(255,255,255,0.8)' : 'none' }}
                >
                    {note}
                </text>

                {/* PC Key label */}
                {label && (
                    <text 
                        x={width / 2} 
                        y={height - (isBlack ? 8 : 12)} 
                        fill={isBlack ? '#94a3b8' : '#475569'}
                        fontSize={isBlack ? 9 : 10} 
                        textAnchor="middle" 
                        fontFamily="monospace"
                        fontWeight="bold"
                        pointerEvents="none"
                        opacity={0.9}
                    >
                        {isBlack ? `[${label}]` : label}
                    </text>
                )}
            </g>
        </g>
    );
});

export const LiveKeyboard = memo(({ onPlayNote, onStopNote, activeTrackColor: _activeTrackColor }: LiveKeyboardProps) => {
    // A held key stores the note name resolved at the moment it was pressed,
    // keyed by the semitone offset that keyup will look it up by. Because the
    // sounding pitch is captured at press time rather than re-derived from the
    // live octave, shifting mid-hold leaves every voice alone: nothing retunes,
    // and the eventual note-off matches the note-on that started it.
    const [heldByKeys, setHeldByKeys] = useState<Map<number, string>>(() => new Map());
    const [heldByMouse, setHeldByMouse] = useState<{ offset: number; note: string } | null>(null);
    const [showGuide, setShowGuide] = useState(false);
    const [octave, setOctave] = useState(() => loadStoredOctave());

    const heldByMouseRef = useRef(heldByMouse);
    useEffect(() => { heldByMouseRef.current = heldByMouse; }, [heldByMouse]);

    // Read by the press handlers so they resolve pitches against the current
    // octave without re-subscribing the window listeners on every shift.
    const octaveRef = useRef(octave);
    useEffect(() => { octaveRef.current = octave; }, [octave]);

    const playingNotesRef = useRef<Set<string>>(new Set());

    useEffect(() => { storeOctave(octave); }, [octave]);

    const shiftOctave = useCallback((delta: number) => {
        setOctave(prev => clampOctave(prev + delta));
    }, []);

    // Deliberately independent of `octave`: the set only changes when a key is
    // pressed or released, so an octave shift cannot add or drop a voice.
    const targetActiveNotes = useMemo(() => {
        const active = new Set<string>();
        heldByKeys.forEach(note => active.add(note));
        if (heldByMouse !== null) active.add(heldByMouse.note);
        return active;
    }, [heldByKeys, heldByMouse]);

    useEffect(() => {
        const currentlyPlaying = playingNotesRef.current;
        const target = targetActiveNotes;

        currentlyPlaying.forEach(note => {
            if (!target.has(note)) {
                if (onStopNote) onStopNote(note);
                currentlyPlaying.delete(note);
            }
        });

        target.forEach(note => {
            if (!currentlyPlaying.has(note)) {
                onPlayNote(note);
                currentlyPlaying.add(note);
            }
        });
    }, [targetActiveNotes, onPlayNote, onStopNote]);

    // --- KEYBOARD INTERACTION ---
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
            if (e.target instanceof HTMLElement && e.target.isContentEditable) return;

            if (e.code === OCTAVE_DOWN_CODE || e.code === OCTAVE_UP_CODE) {
                e.preventDefault();
                if (!e.repeat) shiftOctave(e.code === OCTAVE_UP_CODE ? 1 : -1);
                return;
            }

            const offset = PC_KEY_MAPPING[e.code];
            if (offset !== undefined && !e.repeat) {
                e.preventDefault();
                setHeldByKeys(prev => {
                    if (prev.has(offset)) return prev;
                    const next = new Map(prev);
                    next.set(offset, noteForOffset(offset, octaveRef.current));
                    return next;
                });
            }
        };
        const handleKeyUp = (e: KeyboardEvent) => {
            if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
            if (e.target instanceof HTMLElement && e.target.isContentEditable) return;
            const offset = PC_KEY_MAPPING[e.code];
            if (offset !== undefined) {
                e.preventDefault();
                setHeldByKeys(prev => {
                    if (!prev.has(offset)) return prev;
                    const next = new Map(prev);
                    next.delete(offset);
                    return next;
                });
            }
        };
        const handleBlur = () => setHeldByKeys(new Map());

        window.addEventListener('keydown', handleKeyDown);
        window.addEventListener('keyup', handleKeyUp);
        window.addEventListener('blur', handleBlur);

        return () => {
            window.removeEventListener('keydown', handleKeyDown);
            window.removeEventListener('keyup', handleKeyUp);
            window.removeEventListener('blur', handleBlur);
        };
    }, [shiftOctave]);

    // --- MOUSE EVENT HANDLERS ---
    const handleMouseDownStable = useCallback((offset: number) => {
        setHeldByMouse({ offset, note: noteForOffset(offset, octaveRef.current) });
    }, []);
    const handleMouseEnterStable = useCallback((offset: number) => {
        // Gliding onto a new key is a fresh press, so it takes the current octave.
        if (heldByMouseRef.current !== null) {
            setHeldByMouse({ offset, note: noteForOffset(offset, octaveRef.current) });
        }
    }, []);
    const handleStopMouseStable = useCallback(() => setHeldByMouse(null), []);

    // --- CLASSIC PIANO LAYOUT ---
    // 8 white keys on bottom, 5 black keys on top (staggered between white keys)
    const totalWidth = 800;
    const numWhiteKeys = 8;
    const fKeyGap = 30; // Gap between F5 and F4 key groups
    const whiteKeyWidth = (totalWidth - fKeyGap) / numWhiteKeys; // Adjusted for gap
    const whiteKeyHeight = 90;
    const blackKeyWidth = whiteKeyWidth * 0.85; // Increased from 0.65 to 0.85
    const blackKeyHeight = whiteKeyHeight * 0.75; // Increased from 0.65 to 0.75
    const rowGap = 5;

    // White keys (bottom row) — semitone offsets from the base octave's C
    const whiteOffsets = [0, 2, 4, 5, 7, 9, 11, 12];
    const whiteKeyCodes = ['F8', 'F7', 'F6', 'F5', 'F4', 'F3', 'F2', 'F1'];

    // Black keys (top row) - positioned between specific white keys
    // C# between C-D, D# between D-E, F# between F-G, G# between G-A, A# between A-B
    // Positions: after key 0 (C), after key 1 (D), after key 3 (F), after key 4 (G), after key 5 (A)
    const blackKeyData = [
        { offset: 1,  keyCode: 'Digit9', position: 0 }, // C# between C and D
        { offset: 3,  keyCode: 'Digit8', position: 1 }, // D# between D and E
        { offset: 6,  keyCode: 'Digit6', position: 3 }, // F# between F and G
        { offset: 8,  keyCode: 'Digit5', position: 4 }, // G# between G and A
        { offset: 10, keyCode: 'Digit4', position: 5 }, // A# between A and B
    ];

    const whiteRowY = blackKeyHeight + rowGap;
    const svgHeight = whiteRowY + whiteKeyHeight + 10;

    return (
        <div className="w-full max-w-[820px] mx-auto mt-4 select-none relative">
            {/* OCTAVE CONTROLS + PIANO LAYOUT INFO Banner */}
            <div className="absolute -top-7 left-0 flex items-center gap-1 z-40">
                <button
                    type="button"
                    onClick={() => shiftOctave(-1)}
                    disabled={isOctaveAtEdge(octave, -1)}
                    aria-label="Octave down"
                    title="Octave down ( [ )"
                    className="text-[10px] text-cyan-500/80 hover:text-cyan-400 disabled:text-gray-700 disabled:hover:text-gray-700 font-mono px-2 py-1 rounded border border-cyan-900/30 bg-black/20 hover:bg-black/40 disabled:bg-black/10 transition-all"
                >
                    <span aria-hidden="true">−</span>
                </button>
                <span className="text-[10px] font-mono tracking-wider text-cyan-400 px-2 py-1 rounded border border-cyan-900/30 bg-black/30 tabular-nums">
                    OCT {octave}
                </span>
                <button
                    type="button"
                    onClick={() => shiftOctave(1)}
                    disabled={isOctaveAtEdge(octave, 1)}
                    aria-label="Octave up"
                    title="Octave up ( ] )"
                    className="text-[10px] text-cyan-500/80 hover:text-cyan-400 disabled:text-gray-700 disabled:hover:text-gray-700 font-mono px-2 py-1 rounded border border-cyan-900/30 bg-black/20 hover:bg-black/40 disabled:bg-black/10 transition-all"
                >
                    <span aria-hidden="true">+</span>
                </button>
                <span role="status" aria-live="polite" className="sr-only">
                    {`Octave ${octave}, keys ${noteForOffset(0, octave)} to ${noteForOffset(12, octave)}`}
                </span>
            </div>

            <div className="absolute -top-7 right-0 flex items-center gap-2 z-40">
                <button type="button" onClick={() => setShowGuide(true)} aria-label="Show Keyboard Layout Guide" title="Show Keyboard Layout Guide" className="flex items-center gap-1 text-[10px] text-cyan-500/80 hover:text-cyan-400 font-mono tracking-wider px-2 py-1 rounded border border-cyan-900/30 bg-black/20 hover:bg-black/40 transition-all">
                    <span className="text-xs" aria-hidden="true">⌨</span> PIANO LAYOUT INFO
                </button>
            </div>

            {showGuide && <KeyboardGuide onClose={() => setShowGuide(false)} />}

            {/* Piano Keyboard SVG */}
            <svg aria-hidden="true" viewBox={`0 0 ${totalWidth} ${svgHeight}`} className="w-full drop-shadow-2xl bg-black/20 rounded-lg p-2">
                {/* White keys (bottom row) — group 1: C D E F (i=0–3), group 2: G A B C (i=4–7) */}
                {whiteOffsets.map((offset, i) => {
                    const note = noteForOffset(offset, octave);
                    return (
                        <PianoKey
                            key={offset}
                            note={note}
                            offset={offset}
                            x={i < 4 ? i * whiteKeyWidth : i * whiteKeyWidth + fKeyGap}
                            y={whiteRowY}
                            width={whiteKeyWidth - 2}
                            height={whiteKeyHeight}
                            label={whiteKeyCodes[i]}
                            isBlack={false}
                            isActive={targetActiveNotes.has(note)}
                            isHeldByMouse={heldByMouse?.offset === offset}
                            activeColor={getNoteColor(note)}
                            onMouseDown={handleMouseDownStable}
                            onMouseEnter={handleMouseEnterStable}
                            onStopMouse={handleStopMouseStable}
                        />
                    );
                })}

                {/* Black keys (top row) - positioned between white keys */}
                {/* positions 0,1 → left group (C#,D#); positions 3,4,5 → right group (F#,G#,A#) */}
                {blackKeyData.map(({ offset, keyCode, position }) => {
                    const note = noteForOffset(offset, octave);
                    // Shift right-group black keys by fKeyGap to align with the offset white keys
                    const x = (position + 1) * whiteKeyWidth - (blackKeyWidth / 2) + (position >= 3 ? fKeyGap : 0);
                    return (
                        <PianoKey
                            key={offset}
                            note={note}
                            offset={offset}
                            x={x}
                            y={0}
                            width={blackKeyWidth}
                            height={blackKeyHeight}
                            label={keyCode.replace('Digit', '')}
                            isBlack={true}
                            isActive={targetActiveNotes.has(note)}
                            isHeldByMouse={heldByMouse?.offset === offset}
                            activeColor={getNoteColor(note)}
                            onMouseDown={handleMouseDownStable}
                            onMouseEnter={handleMouseEnterStable}
                            onStopMouse={handleStopMouseStable}
                        />
                    );
                })}
            </svg>
        </div>
    );
});

import React, { useMemo, useCallback, useImperativeHandle, forwardRef, memo, useRef, useLayoutEffect, useEffect, useState } from 'react';
import { MelodicSequencerRow, type MelodicSequencerRowHandle } from './MelodicSequencerRow';
import { PhonemePainter } from './PhonemePainter';
import type { Pattern, PartSequence, TrackKey, PhonemeData } from '../types';
import type { AlignmentResult } from '../engines/rubberband/PhonemeAligner';
import { useTimelineZoom } from '../hooks/useTimelineZoom';
import { DEFAULT_ZOOM, ROWS, SEQUENCER_STYLES } from './sequencer/constants';
import { AutomationStep } from './sequencer/AutomationStep';
import { SequencerRow, type SequencerRowHandle } from './sequencer/SequencerRow';
import { SequencerRowWrapper } from './sequencer/SequencerRowWrapper';
import { noop } from '../utils/noop';
import {
    getAdjacentSequencerCell,
    keyToGridDirection,
    sequencerCellKey,
    type SequencerCellCoord,
} from '../utils/sequencerGridKeyboard';
import { RackPanelChrome } from './ui/RackPanelChrome';

export { ROWS };
export { AutomationStep };
export type { SequencerRowHandle };

export interface MainSequencerHandle {
    setHighlight: (step: number) => void;
}

export interface MainSequencerProps {
    pattern: Pattern;
    activeSamplerBank: number;
    selectedTrack: TrackKey;
    activeTrackSlots: Record<TrackKey, number>;
    trackStorage: Record<TrackKey, (PartSequence | PartSequence[] | null)[]>;
    selection: { trackKey: TrackKey; startStep: number; endStep: number; } | null;
    // Handlers
    onToggle: (rowKey: TrackKey, index: number, e: any) => void;
    onRightMouseDown: (rowKey: TrackKey, index: number, e: React.MouseEvent) => void;
    onEditLength: (rowKey: TrackKey, index: number, len: number) => void;
    onSelectRow: (rowKey: TrackKey) => void;
    onSelectSlot: (rowKey: TrackKey, slotIndex: number) => void;
    onSelectionStart: (rowKey: TrackKey, index: number) => void;
    onSelectionEnter: (rowKey: TrackKey, index: number) => void;
    // Phase 2: Melodic Lyric Mode
    melodicMode?: boolean; // Enable pitch-per-step visualization for sampler
    onPitchChange?: (trackKey: TrackKey, step: number, pitch: number) => void;
    // Automation
    viewMode?: 'notes' | 'automation';
    automationParam?: string;
    onAutomationChange?: (trackKey: TrackKey, step: number, value: number) => void;
    alignment?: AlignmentResult | null;
    // Phase 3: Phoneme Painter
    onPhonemeUpdate?: (trackKey: TrackKey, bankIndex: number, step: number, phonemes: PhonemeData[] | undefined) => void;
    samplerAudioBuffer?: AudioBuffer | null;
    // Zoom: controlled via props (persisted in app state), with gestures handled locally
    zoomLevel?: number;
    onZoomChange?: (z: number) => void;
    // Children are rendered after SVG (e.g. NoteSelector)
    children?: React.ReactNode;
}

export const MainSequencer = memo(forwardRef<MainSequencerHandle, MainSequencerProps>((props, ref) => {
    const { pattern, activeSamplerBank, selectedTrack, activeTrackSlots, trackStorage, selection, onToggle, onRightMouseDown, onEditLength, onSelectRow, onSelectSlot, onSelectionStart, onSelectionEnter, children,
        melodicMode = false, onPitchChange, viewMode = 'notes', automationParam, onAutomationChange, alignment, onPhonemeUpdate, samplerAudioBuffer,
        zoomLevel = DEFAULT_ZOOM, onZoomChange } = props;

    const rowRefs = useRef<(SequencerRowHandle | null)[]>([]);
    const melodicRowRef = useRef<MelodicSequencerRowHandle | null>(null);

    // Zoom state: driven by prop (for persistence), updated via gesture/wheel events.
    const [zoom, setZoom] = useState(zoomLevel);

    const containerRef = useRef<HTMLDivElement>(null);

    // Sync external zoomLevel prop → local state (e.g. when app state loads a saved value).
    const [prevZoomLevel, setPrevZoomLevel] = useState(zoomLevel);
    if (zoomLevel !== prevZoomLevel) {
        setPrevZoomLevel(zoomLevel);
        setZoom(zoomLevel);
    }
    const appliedZoomLevelRef = useRef(zoomLevel);
    useLayoutEffect(() => {
        if (zoomLevel !== appliedZoomLevelRef.current) {
            appliedZoomLevelRef.current = zoomLevel;
            // Also sync the CSS variable immediately if the external prop changes
            if (containerRef.current) {
                containerRef.current.style.setProperty('--zoom-level', zoomLevel.toString());
            }
        }
    }, [zoomLevel]);

    // Wrap setZoom to also notify parent (persist to app state).
    const handleZoomChange = useCallback((newZoom: number) => {
        setZoom(newZoom);
        onZoomChange?.(newZoom);
    }, [onZoomChange]);


    // Attach Ctrl+wheel and pointer-based pinch-to-zoom.
    const { handleDoubleClick } = useTimelineZoom({
        containerRef: containerRef as React.RefObject<HTMLElement | null>,
        zoom,
        onZoomChange: handleZoomChange,
    });



    // Phase 3: Phoneme Painter state
    const [phonemePainterState, setPhonemePainterState] = useState<{
        isOpen: boolean;
        stepIndex: number;
        note: any | null;
    }>({ isOpen: false, stepIndex: 0, note: null });

    useImperativeHandle(ref, () => ({
        setHighlight: (step: number) => {
            rowRefs.current.forEach(r => r?.setHighlight(step));
            melodicRowRef.current?.setHighlight(step);
        }
    }));

    // Handle Alt+Click on sampler steps to open Phoneme Painter
    // PERFORMANCE: Use a ref to store the latest pattern.sampler to avoid re-creating this callback
    // and causing all SequencerRows (256 steps) to re-render whenever any sampler note changes.
    const patternSamplerRef = useRef(pattern.sampler);
    useLayoutEffect(() => {
        patternSamplerRef.current = pattern.sampler;
    }, [pattern.sampler]);

    const activeSamplerBankRef = useRef(activeSamplerBank);
    useLayoutEffect(() => {
        activeSamplerBankRef.current = activeSamplerBank;
    }, [activeSamplerBank]);

    const handleStepPointerDown = useCallback((rowKey: TrackKey, stepIndex: number, e: React.PointerEvent | React.KeyboardEvent) => {
        // Check for Alt+Click (or Option+Click on Mac)
        if (rowKey === 'sampler' && e.altKey && onPhonemeUpdate) {
            const stepData = patternSamplerRef.current[activeSamplerBankRef.current].steps[stepIndex];
            if (stepData) {
                e.preventDefault();
                e.stopPropagation();
                setPhonemePainterState({
                    isOpen: true,
                    stepIndex,
                    note: stepData
                });
                return;
            }
        }
        // Otherwise pass to normal toggle handler
        onToggle(rowKey, stepIndex, e);
    }, [onToggle, onPhonemeUpdate]);

    // Handle save from Phoneme Painter
    const handlePhonemeSave = useCallback((stepIndex: number, phonemes: PhonemeData[] | undefined) => {
        if (onPhonemeUpdate) {
            onPhonemeUpdate('sampler', activeSamplerBank, stepIndex, phonemes);
        }
    }, [onPhonemeUpdate, activeSamplerBank]);

    // Close phoneme painter
    const handleClosePhonemePainter = useCallback(() => {
        setPhonemePainterState(prev => ({ ...prev, isOpen: false }));
    }, []);

    // PERFORMANCE: Memoize selection range map to prevent object recreation and unnecessary row re-renders
    const selectionRangeMap = useMemo(() => {
        if (!selection) return null;
        return { [selection.trackKey]: { start: selection.startStep, end: selection.endStep } };
    }, [selection]);

    const [focusedCell, setFocusedCell] = useState<SequencerCellCoord>(() => ({
        rowKey: selectedTrack,
        step: 0,
    }));
    const stepFocusRefs = useRef(new Map<string, SVGGElement>());
    const selectionRef = useRef(selection);
    useLayoutEffect(() => {
        selectionRef.current = selection;
    }, [selection]);

    const [prevSelectedTrack, setPrevSelectedTrack] = useState(selectedTrack);
    if (prevSelectedTrack !== selectedTrack) {
        setPrevSelectedTrack(selectedTrack);
        if (focusedCell.rowKey !== selectedTrack) {
            setFocusedCell({ rowKey: selectedTrack, step: focusedCell.step });
        }
    }

    const focusSequencerCell = useCallback((coord: SequencerCellCoord) => {
        setFocusedCell(coord);
        stepFocusRefs.current.get(sequencerCellKey(coord.rowKey, coord.step))?.focus();
    }, []);

    const handleStepRef = useCallback((rowKey: TrackKey, step: number, el: SVGGElement | null) => {
        const key = sequencerCellKey(rowKey, step);
        if (el) stepFocusRefs.current.set(key, el);
        else stepFocusRefs.current.delete(key);
    }, []);

    const handleStepGridKeyDown = useCallback(
        (rowKey: TrackKey, step: number, e: React.KeyboardEvent) => {
            const direction = keyToGridDirection(e.key);
            if (!direction) return;
            e.preventDefault();
            const next = getAdjacentSequencerCell(rowKey, step, direction);
            if (e.shiftKey) {
                const sel = selectionRef.current;
                if (!sel) onSelectionStart(rowKey, step);
                onSelectionEnter(next.rowKey, next.step);
            }
            focusSequencerCell(next);
        },
        [onSelectionStart, onSelectionEnter, focusSequencerCell],
    );


    const baseWidth = 1050;
    const timelineWidth = 830;

    return (
        <div
            id="main-sequencer"
            className="w-full h-full p-4 hyphon-sequencer-shell relative overflow-x-auto overflow-y-hidden scrollbar-thin hyphon-sequencer-scroll touch-pan-x"
            ref={containerRef}
            onDoubleClick={handleDoubleClick}
            role="grid"
            aria-label="Step sequencer"
            aria-describedby="sequencer-kbd-hint"
            style={{ '--zoom-level': zoom } as React.CSSProperties}
        >
            <p id="sequencer-kbd-hint" className="sr-only">
                Arrow keys move between steps and tracks. Space or Enter toggles a step. Shift plus arrow extends the selection range.
            </p>
            <style>{SEQUENCER_STYLES}</style>
            <div className="absolute inset-0 rounded-xl border-2 border-cyan-900/10 pointer-events-none" aria-hidden="true" />
            <RackPanelChrome stickyScrews />

            {/* Alt+Click hint for sampler */}
            {onPhonemeUpdate && (
                <div className="absolute top-3 left-1/2 -translate-x-1/2 text-[10px] text-cyan-500/60 font-mono pointer-events-none" style={{ position: 'sticky', left: '50%' }}>
                    Alt+Click sampler step for Phoneme Painter
                </div>
            )}

            <svg viewBox="0 0 1050 680" style={{ width: 'calc(220px + 830px * var(--zoom-level))', height: '100%', minWidth: '100%' }} preserveAspectRatio="xMinYMid meet" onContextMenu={(e) => e.preventDefault()}>
                <defs><linearGradient id="glassGrad" x1="0%" y1="0%" x2="0%" y2="100%"><stop offset="0%" stopColor="white" stopOpacity="0.5" /><stop offset="100%" stopColor="white" stopOpacity="0" /></linearGradient></defs>
                <g transform="translate(100, 40)">
                    {ROWS.map((row, rIdx) => {
                        // Use MelodicSequencerRow for sampler when in melodic mode
                        const isSamplerMelodic = row.key === 'sampler' && melodicMode;

                        if (isSamplerMelodic) {
                            return (
                                <MelodicSequencerRow
                                    key={row.key}
                                    ref={melodicRowRef}
                                    rowKey={row.key}
                                    label={`SMP ${activeSamplerBank + 1}`}
                                    rowIndex={rIdx}
                                    steps={pattern.sampler[activeSamplerBank].steps}
                                    isSelected={selectedTrack === row.key}
                                    activeSlot={activeTrackSlots[row.key]}
                                    trackSlots={trackStorage[row.key]}
                                    onToggle={handleStepPointerDown}
                                    onPitchChange={onPitchChange || noop}
                                    onEditLength={onEditLength}
                                    onSelectRow={onSelectRow}
                                    onSelectSlot={onSelectSlot}
                                />
                            );
                        }


                        return (
                            <SequencerRowWrapper
                                key={row.key}
                                row={row}
                                rIdx={rIdx}
                                rowRefs={rowRefs}
                                steps={(row.key === 'sampler' ? pattern.sampler[activeSamplerBank].steps : (pattern as any)[row.key].steps)}
                                automation={(row.key === 'sampler' ? pattern.sampler[activeSamplerBank].automation : (pattern as any)[row.key].automation)}
                                isSelected={selectedTrack === row.key}
                                activeSlot={activeTrackSlots[row.key]}
                                trackSlots={trackStorage[row.key]}
                                selectionRange={selectionRangeMap?.[row.key] || null}
                                activeSamplerBank={activeSamplerBank}
                                handleStepPointerDown={handleStepPointerDown}
                                onRightMouseDown={onRightMouseDown}
                                onEditLength={onEditLength}
                                onSelectRow={onSelectRow}
                                onSelectSlot={onSelectSlot}
                                onSelectionStart={onSelectionStart}
                                onSelectionEnter={onSelectionEnter}
                                viewMode={viewMode}
                                automationParam={automationParam}
                                onAutomationChange={onAutomationChange}
                                alignment={row.key === 'sampler' ? alignment : null}
                                focusedCell={focusedCell}
                                onStepRef={handleStepRef}
                                onStepGridKeyDown={handleStepGridKeyDown}
                            />
                        );
                    })}
                </g>
            </svg>
            {children}

            {/* Phoneme Painter Popover */}
            <PhonemePainter
                isOpen={phonemePainterState.isOpen}
                onClose={handleClosePhonemePainter}
                stepIndex={phonemePainterState.stepIndex}
                note={phonemePainterState.note}
                // @ts-expect-error - Auto-generated to fix CI build
                audioBuffer={samplerAudioBuffer}
                alignment={alignment}
                onSave={handlePhonemeSave}
            />
        </div>
    );
}));

import React, { forwardRef, useImperativeHandle, useRef, useCallback, useLayoutEffect, memo, useMemo } from 'react';
import { MelodicStep } from './MelodicStep';
import { GridIndicators } from './GridIndicators';
import { TrackSlotStrip } from './sequencer/TrackSlotButton';
import { TrackMuteSoloButtons } from './sequencer/TrackMuteSoloButtons';
import { noteToMidi } from '../utils/musicTheory';
import type { PartSequence, TrackKey } from '../types';

/**
 * MelodicSequencerRow - Sequencer row for Melodic Lyric Mode
 * 
 * Displays sampler steps with pitch-based height visualization.
 * Each step shows the note pitch and can be dragged to change pitch.
 */

export interface MelodicSequencerRowHandle {
  setHighlight: (step: number) => void;
}

interface MelodicSequencerRowProps {
  rowKey: TrackKey;
  label: string;
  rowIndex: number;
  steps: (any | null)[];
  isSelected: boolean;
  activeSlot: number;
  trackSlots: (PartSequence | PartSequence[] | null)[];
  onToggle: (k: TrackKey, i: number, e: React.PointerEvent) => void;
  onPitchChange?: (k: TrackKey, i: number, pitch: number) => void;
  onEditLength: (k: TrackKey, i: number, len: number) => void;
  onSelectRow: (k: TrackKey) => void;
  onSelectSlot: (k: TrackKey, slot: number) => void;
}

export const MelodicSequencerRow = memo(forwardRef<MelodicSequencerRowHandle, MelodicSequencerRowProps>(
  (props, ref) => {
    const {
      rowKey,
      label,
      rowIndex,
      steps,
      isSelected,
      activeSlot,
      trackSlots,
      onToggle,
      onPitchChange,
      onEditLength,
      onSelectRow,
      onSelectSlot
    } = props;

    const stepRefs = useRef<(SVGGElement | null)[]>([]);
    const lastStepRef = useRef(-1);
    const lastActiveIndexRef = useRef(-1);
    const stepsRef = useRef(steps);
    const rafRef = useRef<number | null>(null);

    useLayoutEffect(() => {
      stepsRef.current = steps;
    }, [steps]);

    const updateClasses = useCallback((step: number) => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }

      rafRef.current = requestAnimationFrame(() => {
        let newActiveIndex = -1;

        // Find which step should be highlighted based on current sequencer step
        for (let i = step; i >= 0; i--) {
          if (stepRefs.current[i]) {
            const length = stepsRef.current[i]?.length || 1;
            if (i + length > step) {
              newActiveIndex = i;
            }
            break;
          }
        }

        if (newActiveIndex !== lastActiveIndexRef.current) {
          if (lastActiveIndexRef.current !== -1) {
            stepRefs.current[lastActiveIndexRef.current]?.classList.remove('is-current');
          }
          if (newActiveIndex !== -1) {
            stepRefs.current[newActiveIndex]?.classList.add('is-current');
          }
          lastActiveIndexRef.current = newActiveIndex;
        }
      });
    }, []);

    useLayoutEffect(() => {
      return () => {
        if (rafRef.current) {
          cancelAnimationFrame(rafRef.current);
        }
      };
    }, []);

    useImperativeHandle(ref, () => ({
      setHighlight: (step: number) => {
        if (step === -1) {
          if (lastActiveIndexRef.current !== -1) {
            stepRefs.current[lastActiveIndexRef.current]?.classList.remove('is-current');
            lastActiveIndexRef.current = -1;
          }
          lastStepRef.current = -1;
          return;
        }
        lastStepRef.current = step;
        updateClasses(step);
      }
    }));

    useLayoutEffect(() => {
      const currentActive = lastActiveIndexRef.current;
      lastActiveIndexRef.current = -1;
      if (lastStepRef.current !== -1) {
        updateClasses(lastStepRef.current);
      } else {
        lastActiveIndexRef.current = currentActive;
      }
    }, [updateClasses]);

    // Render steps
    const renderedSteps = useMemo(() => {
        const stepsArray = [];
        let skipCount = 0;

        for (let i = 0; i < 32; i++) {
          if (skipCount > 0) {
            skipCount--;
            continue;
          }

          const stepData = steps[i];
          const length = stepData?.length || 1;
          const isActive = !!stepData;

          // Default pitch for new notes is C4 (60)
          // If note string exists but pitch doesn't, convert
          let pitch = 60;
          if (stepData?.pitch !== undefined) {
              pitch = stepData.pitch;
          } else if (stepData?.note) {
              pitch = noteToMidi(stepData.note);
          }

          const phonemeIndex = stepData?.sliceIndex; // Use sliceIndex as phoneme index
          const phonemes = stepData?.phonemes; // Pass phoneme data for display

          stepsArray.push(
            <MelodicStep
              key={i}
              stepIndex={i}
              active={isActive}
              note={stepData?.note || null}
              pitch={pitch}
              phonemeIndex={phonemeIndex}
              phonemes={phonemes}
              length={length}
              isSlide={!!stepData?.slide}
              isCurrent={false} /* Handled by ref manipulation below */
              rowLabel={label}
              rowKey={rowKey}
              refsArray={stepRefs}
              onToggle={onToggle}
              onPitchChange={onPitchChange}
              onEditLength={onEditLength}
              reverse={stepData?.reverse}
            />
          );

          if (stepData && length > 1) {
            skipCount = length - 1;
          }
        }
        return stepsArray;
    }, [steps, label, rowKey, onToggle, onPitchChange, onEditLength]);

      const handleRowClick = useCallback(() => onSelectRow(rowKey), [onSelectRow, rowKey]);
      const handleRowKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onSelectRow(rowKey);
        }
      }, [onSelectRow, rowKey]);

    const renderedTrackSlots = useMemo(() => (
      <TrackSlotStrip
        activeSlot={activeSlot}
        trackSlots={trackSlots}
        trackKey={rowKey}
        onSelect={onSelectSlot}
      />
    ), [activeSlot, trackSlots, rowKey, onSelectSlot]);

    return (
      <g transform={`translate(0, ${rowIndex * 80})`}>
        {/* Track label */}
        <g
          className="track-label"
            onClick={handleRowClick}
          cursor="pointer"
          role="button"
          tabIndex={0}
          aria-label={`Select ${label} track`}
          aria-description="Left-click to select row. Right-click for options."
          aria-pressed={isSelected}
          onKeyDown={handleRowKeyDown}
        >
          {isSelected && (
            <rect x={-10} y={8} width={4} height={36} fill="#3fa34d" rx={2} />
          )}
          <text
            x={-20}
            y={30}
            textAnchor="end"
            fontFamily="Orbitron, monospace"
            fontSize={12}
            fill={isSelected ? '#3fa34d' : '#5a6b60'}
            fontWeight={isSelected ? 'bold' : 'normal'}
            style={{ textShadow: isSelected ? '0 0 8px rgba(63,163,77,0.5)' : 'none' }}
          >
            {label.toUpperCase()}
          </text>
        </g>

        {/* Mute / solo */}
        <g transform="translate(0, 16)">
          <TrackMuteSoloButtons trackKey={rowKey} label={label} />
        </g>

        {/* Pattern slots */}
        <g transform="translate(30, 16)">
          {renderedTrackSlots}
        </g>

        {/* Grid indicators and Steps wrapped in zoom scale */}
        <g style={{ transform: 'scaleX(var(--zoom-level))', transformOrigin: 'left' }} transform="translate(220, 0)">
            <GridIndicators />
            {renderedSteps}
        </g>
      </g>
    );
  }
), (prev: any, next: any) => {
    return (
        prev.rowKey === next.rowKey &&
        prev.label === next.label &&
        prev.rowIndex === next.rowIndex &&
        prev.isSelected === next.isSelected &&
        prev.activeSlot === next.activeSlot &&
        // ⚡ Bolt: Relying on reference equality since useAppState performs immutable updates via shallow cloning.
        // This avoids deep arraysEqual checks on 256 items per row per render.
        prev.steps === next.steps &&
        prev.trackSlots === next.trackSlots
    );
});

export default MelodicSequencerRow;

