// PerformanceMode — full-screen reactive step grid overlay.
//
// Shows a 4×8 grid of large circles (32 steps: 2 rows × 16) with per-track
// color and beat-reactive animations. Intended for live performance where the
// primary need is visual feedback rather than parameter editing.
//
// Architecture:
// - Uses the same imperative DOM-mutation pattern as SequencerRow: the parent
//   calls handle.setStep(step) from the existing onStep callback path,
//   avoiding any React re-renders during playback.
// - Level meter drawn via Canvas, driven by useLevelMeter.
// - Keyboard shortcut: Ctrl/Cmd+Shift+P (managed by the parent calling setOpen).

import React, {
    memo, forwardRef, useImperativeHandle,
    useRef, useEffect, useCallback,
} from 'react';
import { useFocusTrap } from '../hooks/useFocusTrap';
import { LevelMeter } from './LevelMeter';

// ── Track definitions ─────────────────────────────────────────────────────────

interface TrackDef {
    key: string;
    label: string;
    color: string;
}

const TRACKS: TrackDef[] = [
    { key: 'partA',     label: 'LEAD',  color: '#06b6d4' },
    { key: 'partB',     label: 'BASS',  color: '#d946ef' },
    { key: 'kick',      label: 'KICK',  color: '#f97316' },
    { key: 'snare',     label: 'SNR',   color: '#22c55e' },
    { key: 'closedHat', label: 'CH',    color: '#eab308' },
    { key: 'openHat',   label: 'OH',    color: '#f59e0b' },
    { key: 'sampler',   label: 'SMP',   color: '#a855f7' },
];

const STEPS = 32;

// ── Handle interface ──────────────────────────────────────────────────────────

export interface PerformanceModeHandle {
    /** Called from the step callback path — triggers DOM mutations, no React renders. */
    setStep: (step: number) => void;
}

// ── Props ─────────────────────────────────────────────────────────────────────

interface PerformanceModeProps {
    isOpen: boolean;
    onClose: () => void;
    analyserNode?: AnalyserNode | null;
    /** Which steps are active per track key (derived from pattern). */
    activeSteps?: Partial<Record<string, boolean[]>>;
    tempo?: number;
}

// ── Component ─────────────────────────────────────────────────────────────────

export const PerformanceMode = memo(forwardRef<PerformanceModeHandle, PerformanceModeProps>((
    { isOpen, onClose, analyserNode, activeSteps = {}, tempo = 120 },
    ref,
) => {
    const stepCircleRefs = useRef<(HTMLDivElement | null)[][]>(
        TRACKS.map(() => Array(STEPS).fill(null)),
    );
    const beatBarRef = useRef<HTMLDivElement | null>(null);
    const lastStepRef = useRef(-1);
    const modalRef = useFocusTrap<HTMLDivElement>(isOpen, onClose);

    useImperativeHandle(ref, () => ({
        setStep(step: number) {
            if (!isOpen) return;

            // Remove highlight from previous step across all tracks
            const prev = lastStepRef.current;
            if (prev >= 0) {
                for (let t = 0; t < TRACKS.length; t++) {
                    stepCircleRefs.current[t]?.[prev]?.classList.remove('pm-current');
                }
            }

            // Add highlight to new step
            if (step >= 0) {
                for (let t = 0; t < TRACKS.length; t++) {
                    stepCircleRefs.current[t]?.[step]?.classList.add('pm-current');
                }
            }

            // Animate the beat bar on every beat (steps 0, 4, 8, 12, …)
            if (step % 4 === 0 && beatBarRef.current) {
                beatBarRef.current.classList.remove('pm-beat-flash');
                // Trigger reflow so the animation restarts cleanly.
                void beatBarRef.current.offsetWidth;
                beatBarRef.current.classList.add('pm-beat-flash');
            }

            lastStepRef.current = step;
        },
    }), [isOpen]);

    // Reset highlights when closed.
    useEffect(() => {
        if (!isOpen) {
            for (let t = 0; t < TRACKS.length; t++) {
                for (let s = 0; s < STEPS; s++) {
                    stepCircleRefs.current[t]?.[s]?.classList.remove('pm-current');
                }
            }
            lastStepRef.current = -1;
        }
    }, [isOpen]);

    const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (e.key === 'Escape') onClose();
    }, [onClose]);

    if (!isOpen) return null;

    const stepDuration = 60 / (tempo * 4);
    const animDuration = `${(stepDuration * 0.8 * 1000).toFixed(0)}ms`;

    return (
        <div
            ref={modalRef}
            className="fixed inset-0 z-50 bg-black/95 flex flex-col items-center justify-center gap-6 select-none"
            role="dialog"
            aria-modal="true"
            aria-label="Performance Mode"
            tabIndex={-1}
            onKeyDown={handleKeyDown}
        >
            {/* Beat bar — flashes on every beat */}
            <div
                ref={beatBarRef}
                className="pm-beat-bar w-full h-0.5 absolute top-0 left-0 bg-white/0"
                style={{ '--pm-anim-dur': animDuration } as React.CSSProperties}
            />

            {/* Header */}
            <div className="absolute top-4 right-4 flex items-center gap-4">
                <span className="text-zinc-500 font-mono text-xs uppercase tracking-widest">
                    Performance Mode
                </span>
                <button
                    type="button"
                    onClick={onClose}
                    aria-label="Exit performance mode"
                    className="text-zinc-500 hover:text-white transition-colors font-mono text-xs border border-zinc-700 hover:border-zinc-400 px-2 py-1 rounded"
                >
                    ESC
                </button>
            </div>

            {/* Level meter */}
            <div className="absolute top-4 left-6 flex items-center gap-2">
                <span className="text-zinc-600 font-mono text-[9px] uppercase tracking-widest">Level</span>
                <LevelMeter
                    analyserNode={analyserNode}
                    segments={16}
                    width={160}
                    height={6}
                />
            </div>

            {/* Track grids */}
            <div className="flex flex-col gap-4 w-full max-w-5xl px-8">
                {TRACKS.map((track, trackIdx) => {
                    const steps = activeSteps[track.key] ?? Array(STEPS).fill(false);
                    return (
                        <div key={track.key} className="flex items-center gap-3">
                            {/* Track label */}
                            <div
                                className="w-14 text-right font-mono text-xs font-bold uppercase tracking-widest"
                                style={{ color: track.color }}
                            >
                                {track.label}
                            </div>

                            {/* Step circles */}
                            <div className="flex gap-1.5 flex-1">
                                {Array.from({ length: STEPS }, (_, stepIdx) => {
                                    const isActive = steps[stepIdx] ?? false;
                                    const isBeat = stepIdx % 4 === 0;
                                    return (
                                        <div
                                            key={stepIdx}
                                            ref={(el) => {
                                                if (!stepCircleRefs.current[trackIdx]) return;
                                                stepCircleRefs.current[trackIdx]![stepIdx] = el;
                                            }}
                                            className="pm-step flex-1 aspect-square rounded-sm transition-none"
                                            data-active={isActive ? 'true' : undefined}
                                            data-beat={isBeat ? 'true' : undefined}
                                            style={{
                                                '--track-color': track.color,
                                                backgroundColor: isActive ? track.color + '60' : isBeat ? '#1a2026' : '#111518',
                                                boxShadow: isActive ? `0 0 4px ${track.color}40` : 'none',
                                            } as React.CSSProperties}
                                        />
                                    );
                                })}
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* Tempo + position indicator */}
            <div className="absolute bottom-4 left-0 right-0 flex justify-center">
                <span className="text-zinc-700 font-mono text-xs tabular-nums">
                    {tempo} BPM
                </span>
            </div>

            {/* Injected CSS — scoped to this overlay */}
            <style>{`
                @keyframes pm-beat-flash-kf {
                    0%   { background: rgba(255,255,255,0.9); }
                    100% { background: rgba(255,255,255,0); }
                }
                .pm-beat-flash {
                    animation: pm-beat-flash-kf var(--pm-anim-dur, 150ms) ease-out forwards;
                }

                @keyframes pm-step-fire-kf {
                    0%   { opacity: 1; transform: scale(1.15); }
                    60%  { opacity: 0.9; transform: scale(1.05); }
                    100% { opacity: 1; transform: scale(1); }
                }
                .pm-step.pm-current {
                    background-color: var(--track-color) !important;
                    box-shadow: 0 0 12px var(--track-color), 0 0 24px var(--track-color, #fff)40 !important;
                    animation: pm-step-fire-kf 120ms ease-out forwards;
                }
                .pm-step.pm-current[data-active='true'] {
                    box-shadow: 0 0 16px var(--track-color), 0 0 32px var(--track-color) !important;
                }
            `}</style>
        </div>
    );
}));

PerformanceMode.displayName = 'PerformanceMode';

/**
 * PhonemePainter - Live Phoneme Painter Popover Component
 *
 * Phase 3 of the Vocal Workstation implementation.
 * A popover/modal interface for editing phonemes on melodic sampler steps.
 *
 * Features:
 * - Draggable phoneme blocks with timing offset
 * - Resize handles for duration adjustment
 * - Per-phoneme pitch bend controls
 * - Waveform visualization
 * - Auto-Align using PhonemeAligner
 * - Add/Delete phonemes
 * - Holographic/faux-plastic aesthetic
 * - Keyboard navigation support (WCAG 2.1 AA)
 */

import React, { useState, useRef, useCallback, useEffect, useMemo } from 'react';
import { useFocusTrap } from '../hooks/useFocusTrap';
import type { PhonemeData, Note } from '../types';
import type { AlignmentResult } from '../engines/rubberband/PhonemeAligner';
import { PHONEME_NAMES, COMMON_PHONEMES, getPhonemeColor, generateId } from '../constants/phonemes';
import { PhonemeBlock } from './phoneme/PhonemeBlock';
import { PhonemeWaveformDisplay } from './phoneme/PhonemeWaveformDisplay';

// --- MAIN COMPONENT ---

export interface PhonemePainterProps {
  isOpen: boolean;
  onClose: () => void;
  stepIndex: number;
  note: Note | null;
  audioBuffer: AudioBuffer | null;
  onSave: (stepIndex: number, phonemes: PhonemeData[] | undefined) => void;
  alignment?: AlignmentResult | null;
  onLoadSample?: () => void;
}

// ⚡ Bolt: Added React.memo to prevent unnecessary re-renders when parent state changes.
export const PhonemePainter: React.FC<PhonemePainterProps> = React.memo(({
  isOpen,
  onClose,
  stepIndex,
  note,
  audioBuffer,
  onSave,
  alignment,
  onLoadSample
}) => {
  const [phonemes, setPhonemes] = useState<PhonemeData[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [showAddMenu, setShowAddMenu] = useState(false);
  const [isAutoAligning, setIsAutoAligning] = useState(false);

  const timelineRef = useRef<HTMLDivElement>(null);
    const phonemeButtonRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const addMenuRef = useRef<HTMLDivElement>(null);
  const containerRef = useFocusTrap<HTMLDivElement>(isOpen, onClose);
  const resizeState = useRef<{ id: string; side: 'left' | 'right'; startX: number; startValue: number } | null>(null);

  const TIMELINE_WIDTH = 600;

  // Initialize phonemes from note when opened
  useEffect(() => {
    if (isOpen && note) {
      if (note.phonemes && note.phonemes.length > 0) {
        setPhonemes(note.phonemes);
      } else if (alignment && alignment.phonemes.length > 0) {
        const totalDuration = audioBuffer?.duration || alignment.duration || 1;
        const alignedPhonemes: PhonemeData[] = alignment.phonemes.map((ph) => ({
          id: generateId(),
          symbol: ph.phoneme,
          start: Math.max(0, Math.min(1, ph.start / totalDuration)),
          end: Math.max(0, Math.min(1, ph.end / totalDuration)),
          pitchBend: 0,
          volume: 1
        }));
        setPhonemes(alignedPhonemes);
      } else {
        // Default empty phoneme
        setPhonemes([
          { id: generateId(), symbol: 'AA', start: 0, end: 1, pitchBend: 0, volume: 1 }
        ]);
      }
      setSelectedId(null);
    }
  }, [isOpen, note, alignment, audioBuffer]);

  // Focus trap and escape key handling
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      // Escape to close
      if (e.key === 'Escape') {
        if (showAddMenu) {
          setShowAddMenu(false);
        } else {
          onClose();
        }
        return;
      }

      // Focus management
      if (e.key === 'Tab') {
        // Let default tab behavior work, but ensure focus stays in modal
        const focusableElements = containerRef.current?.querySelectorAll(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        if (!focusableElements || focusableElements.length === 0) return;

        const firstElement = focusableElements[0] as HTMLElement;
        const lastElement = focusableElements[focusableElements.length - 1] as HTMLElement;

        if (e.shiftKey && document.activeElement === firstElement) {
          e.preventDefault();
          lastElement.focus();
        } else if (!e.shiftKey && document.activeElement === lastElement) {
          e.preventDefault();
          firstElement.focus();
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    // Focus first element when opened
    const timer = setTimeout(() => {
      containerRef.current?.querySelector('button')?.focus();
    }, 100);

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      clearTimeout(timer);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, onClose, showAddMenu]);

  // Keyboard navigation for phoneme blocks
  const handlePhonemeKeyDown = (e: React.KeyboardEvent, phonemeId: string) => {
    const phoneme = phonemes.find(p => p.id === phonemeId);
    if (!phoneme) return;

    const phonemeIndex = phonemes.findIndex(p => p.id === phonemeId);
    const STEP_SIZE = 0.01; // 1% increments
    const BIG_STEP = 0.05;  // 5% increments

    switch (e.key) {
      case 'ArrowRight':
        e.preventDefault();
        if (e.shiftKey) {
          // Extend right
          setPhonemes(prev => {
            const idx = prev.findIndex(p => p.id === phonemeId);
            if (idx === -1) return prev;
            const newPhonemes = [...prev];
            newPhonemes[idx] = { ...newPhonemes[idx], end: Math.min(1, newPhonemes[idx].end + BIG_STEP) };
            return newPhonemes;
          });
        } else {
          // Move right
          setPhonemes(prev => {
            const idx = prev.findIndex(p => p.id === phonemeId);
            if (idx === -1) return prev;
            const newPhonemes = [...prev];
            const p = newPhonemes[idx];
            const duration = p.end - p.start;
            const newStart = Math.min(1 - duration, p.start + STEP_SIZE);
            newPhonemes[idx] = { ...p, start: newStart, end: newStart + duration };
            return newPhonemes;
          });
        }
        break;
      case 'ArrowLeft':
        e.preventDefault();
        if (e.shiftKey) {
          // Shrink from right
          setPhonemes(prev => {
            const idx = prev.findIndex(p => p.id === phonemeId);
            if (idx === -1) return prev;
            const newPhonemes = [...prev];
            const p = newPhonemes[idx];
            newPhonemes[idx] = { ...p, end: Math.max(p.start + 0.05, p.end - BIG_STEP) };
            return newPhonemes;
          });
        } else {
          // Move left
          setPhonemes(prev => {
            const idx = prev.findIndex(p => p.id === phonemeId);
            if (idx === -1) return prev;
            const newPhonemes = [...prev];
            const p = newPhonemes[idx];
            const duration = p.end - p.start;
            const newStart = Math.max(0, p.start - STEP_SIZE);
            newPhonemes[idx] = { ...p, start: newStart, end: newStart + duration };
            return newPhonemes;
          });
        }
        break;
      case 'ArrowUp':
        e.preventDefault();
        // Increase pitch bend
        setPhonemes(prev => {
          const idx = prev.findIndex(p => p.id === phonemeId);
          if (idx === -1) return prev;
          const newPhonemes = [...prev];
          const p = newPhonemes[idx];
          newPhonemes[idx] = { ...p, pitchBend: Math.min(100, p.pitchBend + (e.shiftKey ? 20 : 5)) };
          return newPhonemes;
        });
        break;
      case 'ArrowDown':
        e.preventDefault();
        // Decrease pitch bend
        setPhonemes(prev => {
          const idx = prev.findIndex(p => p.id === phonemeId);
          if (idx === -1) return prev;
          const newPhonemes = [...prev];
          const p = newPhonemes[idx];
          newPhonemes[idx] = { ...p, pitchBend: Math.max(-100, p.pitchBend - (e.shiftKey ? 20 : 5)) };
          return newPhonemes;
        });
        break;
      case 'Home':
        e.preventDefault();
        // Move to start
        setPhonemes(prev => {
          const idx = prev.findIndex(p => p.id === phonemeId);
          if (idx === -1) return prev;
          const newPhonemes = [...prev];
          const p = newPhonemes[idx];
          const duration = p.end - p.start;
          newPhonemes[idx] = { ...p, start: 0, end: duration };
          return newPhonemes;
        });
        break;
      case 'End':
        e.preventDefault();
        // Move to end
        setPhonemes(prev => {
          const idx = prev.findIndex(p => p.id === phonemeId);
          if (idx === -1) return prev;
          const newPhonemes = [...prev];
          const p = newPhonemes[idx];
          const duration = p.end - p.start;
          newPhonemes[idx] = { ...p, start: 1 - duration, end: 1 };
          return newPhonemes;
        });
        break;
      case 'Delete':
      case 'Backspace': {
        e.preventDefault();
        handleDelete(phonemeId);
        // Focus next phoneme or add button
        const nextPhoneme = phonemes[phonemeIndex + 1];
        if (nextPhoneme) {
          setSelectedId(nextPhoneme.id);
        }
        break;
      }
      case 'Tab':
        // Navigate between phonemes
        if (e.shiftKey) {
          const prevPhoneme = phonemes[phonemeIndex - 1];
          if (prevPhoneme) {
            e.preventDefault();
            setSelectedId(prevPhoneme.id);
          }
        } else {
          const nextPhoneme = phonemes[phonemeIndex + 1];
          if (nextPhoneme) {
            e.preventDefault();
            setSelectedId(nextPhoneme.id);
          }
        }
        break;
    }
  };

  // Handle drag
  const handleDrag = useCallback((id: string, deltaX: number) => {
    setPhonemes(prev => {
      const idx = prev.findIndex(p => p.id === id);
      if (idx === -1) return prev;

      const ph = prev[idx];
      const duration = ph.end - ph.start;
      const deltaNormalized = deltaX / TIMELINE_WIDTH;

      const newStart = Math.max(0, Math.min(1 - duration, ph.start + deltaNormalized));

      const newPhonemes = [...prev];
      newPhonemes[idx] = { ...ph, start: newStart, end: newStart + duration };
      return newPhonemes;
    });
  }, []);

  // Handle resize start
  const handleResizeStart = useCallback((id: string, side: 'left' | 'right') => {
    const ph = phonemes.find(p => p.id === id);
    if (!ph) return;

    let initialX = 0;
    const startValue = side === 'left' ? ph.start : ph.end;

    resizeState.current = {
      id,
      side,
      startX: 0,
      startValue
    };

    const handlePointerMove = (e: PointerEvent) => {
      if (!resizeState.current) return;
      if (resizeState.current.startX === 0) {
        resizeState.current.startX = e.clientX;
        initialX = e.clientX;
        return;
      }

      const deltaX = e.clientX - initialX;
      const deltaNormalized = deltaX / TIMELINE_WIDTH;

      setPhonemes(prev => {
        const idx = prev.findIndex(p => p.id === resizeState.current!.id);
        if (idx === -1) return prev;

        const p = prev[idx];
        const newPhonemes = [...prev];

        if (resizeState.current!.side === 'left') {
          const newStart = Math.max(0, Math.min(p.end - 0.05, startValue + deltaNormalized));
          newPhonemes[idx] = { ...p, start: newStart };
        } else {
          const newEnd = Math.max(p.start + 0.05, Math.min(1, startValue + deltaNormalized));
          newPhonemes[idx] = { ...p, end: newEnd };
        }
        return newPhonemes;
      });
    };

    const handlePointerUp = () => {
      resizeState.current = null;
      document.removeEventListener('pointermove', handlePointerMove);
      document.removeEventListener('pointerup', handlePointerUp);
    };

    document.addEventListener('pointermove', handlePointerMove);
    document.addEventListener('pointerup', handlePointerUp);
  }, [phonemes]);

  // Add new phoneme
  const handleAddPhoneme = useCallback((symbol: string) => {
    setPhonemes(prev => {
      // Find gap or append at end
      let newStart = 0;
      if (prev.length > 0) {
        // ⚡ Bolt: Replace Math.max(...prev.map(p => p.end)) with O(n) loop
        // Prevents intermediate array allocation and avoids call stack size limits on large phoneme sequences
        let lastEnd = -Infinity;
        for (let i = 0; i < prev.length; i++) {
          if (prev[i].end > lastEnd) {
            lastEnd = prev[i].end;
          }
        }
        newStart = Math.min(lastEnd, 0.9);
      }
      const newEnd = Math.min(1, newStart + 0.2);

      return [...prev, {
        id: generateId(),
        symbol,
        start: newStart,
        end: newEnd,
        pitchBend: 0,
        volume: 1
      }];
    });
    setShowAddMenu(false);
  }, []);

  // Delete phoneme
  const handleDelete = useCallback((id: string) => {
    setPhonemes(prev => prev.filter(p => p.id !== id));
    if (selectedId === id) setSelectedId(null);
  }, [selectedId]);

  // Update pitch bend
  const handlePitchBendChange = useCallback((id: string, bend: number) => {
    setPhonemes(prev => {
      const idx = prev.findIndex(p => p.id === id);
      if (idx === -1) return prev;
      const newPhonemes = [...prev];
      newPhonemes[idx] = { ...newPhonemes[idx], pitchBend: bend };
      return newPhonemes;
    });
  }, []);

  // Auto-align using PhonemeAligner
  const handleAutoAlign = useCallback(async () => {
    if (!audioBuffer || !alignment) return;

    setIsAutoAligning(true);
    try {
      // Use the alignment data to redistribute phonemes
      const totalDuration = audioBuffer.duration;

      const alignedPhonemes: PhonemeData[] = alignment.phonemes.map((ph) => {
        // Normalize to 0-1 range
        const start = ph.start / totalDuration;
        const end = ph.end / totalDuration;

        return {
          id: generateId(),
          symbol: ph.phoneme,
          start: Math.max(0, Math.min(1, start)),
          end: Math.max(0, Math.min(1, end)),
          pitchBend: 0,
          volume: 1
        };
      });

      setPhonemes(alignedPhonemes);
    } finally {
      setIsAutoAligning(false);
    }
  }, [audioBuffer, alignment]);

  // Save changes
  const handleSave = useCallback(() => {
    onSave(stepIndex, phonemes.length > 0 ? phonemes : undefined);
    onClose();
  }, [onSave, onClose, stepIndex, phonemes]);

  // Clear all phonemes
  const handleClear = useCallback(() => {
    setPhonemes([]);
    setSelectedId(null);
  }, []);

  // Get selected phoneme
  const selectedPhoneme = useMemo(() =>
