                  <span className="flex items-center gap-1">+ Add Phoneme</span>
                </button>
              </div>
            </div>

            {/* Keyboard shortcuts hint */}
            <div className="text-[9px] text-zinc-600 font-mono mb-2 flex items-center gap-2">
