                style={{
                  background: 'linear-gradient(145deg, rgba(24,24,27,0.98), rgba(9,9,11,0.99))',
                  border: '1px solid rgba(6,182,212,0.3)',
                  boxShadow: '0 12px 40px rgba(0,0,0,0.6), 0 0 20px rgba(6,182,212,0.1)'
