                      {PHONEME_NAMES[selectedPhoneme.symbol.toUpperCase()] || selectedPhoneme.symbol}
                    </div>
                    <div className="text-[10px] text-zinc-600 font-mono">
                      {((selectedPhoneme.end - selectedPhoneme.start) * 100).toFixed(0)}ms
                    </div>
                  </div>
                </div>

                {/* Pitch Bend Control */}
                <div className="flex items-center gap-3">
                  <span className="text-xs text-zinc-400 font-mono">Pitch Bend</span>
                  <div className="relative w-32 h-6 bg-zinc-800 rounded-full overflow-hidden border border-zinc-700">
                    <div
                      className="absolute top-0 bottom-0 bg-gradient-to-r from-purple-500/50 via-transparent to-cyan-500/50"
                      style={{
                        right: selectedPhoneme.pitchBend >= 0 ? `${50 - (selectedPhoneme.pitchBend / 200) * 50}%` : '50%',
                        left: selectedPhoneme.pitchBend <= 0 ? `${50 + (selectedPhoneme.pitchBend / 200) * 50}%` : '50%'
                      }}
                    />
                    <input
                      type="range"
                      min="-100"
                      max="100"
                      value={selectedPhoneme.pitchBend}
                      onChange={(e) => handlePitchBendChange(selectedPhoneme.id, parseInt(e.target.value))}
                      className="absolute inset-0 w-full h-full opacity-0 cursor-ns-resize"
                      aria-label="Pitch Bend"
                      aria-valuetext={`${selectedPhoneme.pitchBend > 0 ? '+' : ''}${selectedPhoneme.pitchBend} cents`}
                    />
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                      <span className={`text-[10px] font-mono ${selectedPhoneme.pitchBend !== 0 ? 'text-white' : 'text-zinc-600'}`}>
                        {selectedPhoneme.pitchBend > 0 ? '+' : ''}{selectedPhoneme.pitchBend}¢
                      </span>
                    </div>
                  </div>
                  {/* Fine adjustment buttons */}
                  <div className="flex gap-1">
                    <button type="button"
                      onClick={() => handlePitchBendChange(selectedPhoneme.id, selectedPhoneme.pitchBend - 10)}
                      className="w-6 h-6 rounded bg-zinc-800 hover:bg-zinc-700 text-zinc-400 text-xs border border-zinc-700 focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-zinc-950 focus-visible:ring-cyan-500"
                      aria-label="Decrease pitch bend"
                      title="Decrease pitch bend"
                    >
                      -
                    </button>
                    <button type="button"
                      onClick={() => handlePitchBendChange(selectedPhoneme.id, selectedPhoneme.pitchBend + 10)}
                      className="w-6 h-6 rounded bg-zinc-800 hover:bg-zinc-700 text-zinc-400 text-xs border border-zinc-700 focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-zinc-950 focus-visible:ring-cyan-500"
                      aria-label="Increase pitch bend"
                      title="Increase pitch bend"
                    >
                      +
                    </button>
                  </div>
                </div>

                {/* Volume Control */}
                <div className="flex items-center gap-3">
                  <span className="text-xs text-zinc-400 font-mono">Volume</span>
                  <input
                    type="range"
                    min="0"
                    max="100"
                    value={(selectedPhoneme.volume || 1) * 100}
                    onChange={(e) => {
                      const vol = parseInt(e.target.value) / 100;
                      setPhonemes(prev => {
                        const idx = prev.findIndex(p => p.id === selectedPhoneme.id);
                        if (idx === -1) return prev;
                        const newPhonemes = [...prev];
                        newPhonemes[idx] = { ...newPhonemes[idx], volume: vol };
                        return newPhonemes;
                      });
                    }}
                    className="w-24 h-1 bg-zinc-700 rounded-lg appearance-none focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-zinc-950 focus-visible:ring-cyan-500"
                    aria-label="Volume"
                    aria-valuetext={`${Math.round((selectedPhoneme.volume || 1) * 100)}%`}
                  />
                </div>

                {/* Timing info */}
                <div className="flex items-center gap-4 text-[10px] text-zinc-500 font-mono">
                  <span>Start: {(selectedPhoneme.start * 100).toFixed(1)}%</span>
                  <span>End: {(selectedPhoneme.end * 100).toFixed(1)}%</span>
                </div>
              </div>
            </div>
          )}

          {/* Legend - improved styling */}
          <div className="flex items-center gap-4 text-[10px] text-zinc-500 font-mono flex-wrap">
            <span className="text-zinc-500 uppercase tracking-wider">Legend:</span>
            <span className="flex items-center gap-1.5 px-2 py-1 rounded bg-zinc-950/50 border border-zinc-800"><span className="w-2 h-2 rounded-sm bg-purple-500 shadow-[0_0_6px_rgba(168,85,247,0.6)]" />Vowel</span>
            <span className="flex items-center gap-1.5 px-2 py-1 rounded bg-zinc-950/50 border border-zinc-800"><span className="w-2 h-2 rounded-sm bg-red-500 shadow-[0_0_6px_rgba(239,68,68,0.6)]" />Plosive</span>
            <span className="flex items-center gap-1.5 px-2 py-1 rounded bg-zinc-950/50 border border-zinc-800"><span className="w-2 h-2 rounded-sm bg-green-500 shadow-[0_0_6px_rgba(34,197,94,0.6)]" />Fricative</span>
            <span className="flex items-center gap-1.5 px-2 py-1 rounded bg-zinc-950/50 border border-zinc-800"><span className="w-2 h-2 rounded-sm bg-orange-500 shadow-[0_0_6px_rgba(249,115,22,0.6)]" />Affricate</span>
            <span className="flex items-center gap-1.5 px-2 py-1 rounded bg-zinc-950/50 border border-zinc-800"><span className="w-2 h-2 rounded-sm bg-blue-500 shadow-[0_0_6px_rgba(59,130,246,0.6)]" />Nasal</span>
            <span className="flex items-center gap-1.5 px-2 py-1 rounded bg-zinc-950/50 border border-zinc-800"><span className="w-2 h-2 rounded-sm bg-cyan-500 shadow-[0_0_6px_rgba(6,182,212,0.6)]" />Liquid</span>
          </div>
        </div>

        {/* Footer Actions - hardware style */}
        <div className="border-t border-zinc-800 bg-zinc-950/50 px-6 py-4 flex items-center justify-between relative">
          <button type="button"
            onClick={handleClear}
            className="px-4 py-2 text-xs font-mono text-red-400 hover:text-red-300 rounded-md border border-red-900/30 bg-gradient-to-b from-red-950/30 to-red-950/10 hover:from-red-950/50 hover:to-red-950/20 transition-all shadow-[inset_0_1px_0_rgba(255,255,255,0.05)] focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-zinc-950 focus-visible:ring-red-500"
            aria-label="Clear all phonemes"
            title="Clear all phonemes"
          >
            Clear All
          </button>

          <div className="flex items-center gap-3">
            <button type="button"
              onClick={onClose}
              className="px-4 py-2 text-xs font-mono text-zinc-400 hover:text-white rounded-md bg-gradient-to-b from-zinc-800 to-zinc-900 hover:from-zinc-700 hover:to-zinc-800 border border-zinc-700 transition-all shadow-[inset_0_1px_0_rgba(255,255,255,0.05)] focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-zinc-950 focus-visible:ring-zinc-500"
              aria-label="Cancel changes"
              title="Cancel changes"
            >
              Cancel
            </button>
            <button type="button"
              onClick={handleSave}
              className="px-6 py-2 text-xs font-mono font-bold text-black rounded-md bg-gradient-to-b from-cyan-400 to-cyan-500 hover:from-cyan-300 hover:to-cyan-400 border border-cyan-400 transition-all shadow-[0_4px_16px_rgba(6,182,212,0.4),inset_0_1px_0_rgba(255,255,255,0.3)] relative overflow-hidden group focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-zinc-950 focus-visible:ring-cyan-500"
              aria-label="Save changes"
              title="Save changes"
            >
              <span className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-500" />
              <span className="relative">Save Changes</span>
            </button>
          </div>
        </div>

        {/* Screen reader announcements */}
        <div role="status" aria-live="polite" aria-atomic="true" className="sr-only">
          {phonemes.length} phonemes in timeline
          {selectedPhoneme && `, ${selectedPhoneme.symbol} selected`}
        </div>
      </div>
    </div>
  );
});

export default PhonemePainter;

import React, { memo } from 'react'
import { ROWS } from './MainSequencer'
import type { TrackKey } from '../constants/appDefaults'

interface RackProps {
    is3DMode: boolean;
    selectedTrack: TrackKey;
    onSelectTrack: (track: TrackKey) => void;
    modules: Record<TrackKey, React.ReactNode>;
}

export const Rack = memo(({ is3DMode, selectedTrack, onSelectTrack, modules }: RackProps) => {
    return (
        <div className="w-full h-full hyphon-rack-shell relative flex flex-col">
            <div className="absolute inset-0 rounded-2xl border-2 border-cyan-900/10 pointer-events-none z-[1]" aria-hidden="true" />
            {is3DMode && (
                <div className="flex items-center justify-center gap-2 p-2 bg-[#050709] border-b border-gray-800 shrink-0 z-50 relative pointer-events-auto">
                    {ROWS.map((row: any) => (
                        <button type="button"
                            key={row.key}
                            onClick={() => onSelectTrack(row.key as TrackKey)}
                            aria-label={`Select ${row.label} track`}
                            className={`px-4 py-2 rounded text-xs font-bold font-orbitron border transition-all hyphon-btn ${selectedTrack === row.key ? 'hyphon-btn--accent-active' : 'hyphon-btn--ghost'}`}
                        >
                            {row.label.toUpperCase()}
                        </button>
                    ))}
                </div>
            )}
            <div className="flex-1 relative overflow-hidden">
                {modules[selectedTrack]}
            </div>
        </div>
    );
}, (prev, next) => {
    if (prev.is3DMode !== next.is3DMode) return false;
    if (prev.selectedTrack !== next.selectedTrack) return false;
    if (prev.onSelectTrack !== next.onSelectTrack) return false;
    return prev.modules[prev.selectedTrack] === next.modules[next.selectedTrack];
});

/**
 * RbsImportModal - Import ReBirth RB-338 .rbs files
 * 
 * A modal dialog for importing .rbs pattern files from ReBirth RB-338
 * with preview, import options, and pattern visualization.
 * 
 * Features:
 * - Drag & drop .rbs files
 * - Parse progress display with stage labels
 * - Preview pane with pattern visualization
 * - Import options panel (expand 16→32, swing, PCF conversion, etc.)
 * - Error handling with "Try Example" feature
 */

import { ImportOptionsPanel } from './rbs-import-modal/ImportOptionsPanel';
import { ImportReportPanel } from './rbs-import-modal/ImportReportPanel';
import { SongMetadataPanel } from './rbs-import-modal/SongMetadataPanel';
import { PatternVisualization } from './rbs-import-modal/PatternVisualization';
import { ParameterSummaryPanel } from './rbs-import-modal/ParameterSummaryPanel';
import React, { useState, useRef, useCallback, useEffect, useMemo } from 'react';
import { useFocusTrap } from '../hooks/useFocusTrap';
import {
  RbsParser,
  RbsImporter,
  parseRbsFile,
  convertToHyphonSong,
  type RawRbsData,
  type HyphonSong,
  type RbsImportOptions,
  type RbsParserResult,
  type RbsParserError,
  DEFAULT_RBS_IMPORT_OPTIONS
} from '../importers/rbs';
import type { ImportReport } from '../importers/rbs';
import {
  formatFileSize,
  categorizeError,
  getErrorMessage,
  getErrorSuggestions,
  getProgressColor,
  noteToName,
  generateExampleRbsFile,
  type ParseStage,
  type ErrorCategory,
  type ParseState,
} from '../utils/rbsImportUtils';

// ============================================================================
// TYPES
// ============================================================================

interface RbsImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (song: HyphonSong) => void;
  onShowToast: (message: string, type: 'success' | 'error' | 'info') => void;
}

// ============================================================================
// COMPONENT
// ============================================================================

export const RbsImportModal = React.memo(function RbsImportModal({ isOpen, onClose, onImport, onShowToast }: RbsImportModalProps) {
  // File state
  const [droppedFile, setDroppedFile] = useState<File | null>(null);
  const [isDragging, setIsDragging] = useState(false);

  // Parse state
  const [parseState, setParseState] = useState<ParseState>({
    stage: 'idle',
    progress: 0,
    stageLabel: 'Waiting for file...'
  });

  // Parsed data
  const [parsedData, setParsedData] = useState<RawRbsData | null>(null);

  // Import options
  const [importOptions, setImportOptions] = useState<RbsImportOptions>(DEFAULT_RBS_IMPORT_OPTIONS);
  const [showOptions, setShowOptions] = useState(false);

  // Importing state
  const [isImporting, setIsImporting] = useState(false);

  // Import report state — populated after successful import
  const [importReport, setImportReport] = useState<ImportReport | null>(null);
  const [importedSongName, setImportedSongName] = useState<string>('');

  // Refs
  const fileInputRef = useRef<HTMLInputElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);
  const modalRef = useFocusTrap<HTMLDivElement>(isOpen, onClose);

  // Reset state when modal closes (derived during render, not in an effect)
  const [prevIsOpen, setPrevIsOpen] = useState(isOpen);
  if (prevIsOpen !== isOpen) {
    setPrevIsOpen(isOpen);
    if (!isOpen) {
      setDroppedFile(null);
      setParsedData(null);
      setParseState({
        stage: 'idle',
        progress: 0,
        stageLabel: 'Waiting for file...'
      });
      setImportOptions(DEFAULT_RBS_IMPORT_OPTIONS);
      setShowOptions(false);
      setIsImporting(false);
      setImportReport(null);
      setImportedSongName('');
    }
  }
  useEffect(() => {
    if (!isOpen && abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
    }
  }, [isOpen]);

  // Keyboard shortcuts
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  // Parse file with progress
  const parseFile = useCallback(async (file: File) => {
    abortControllerRef.current = new AbortController();
    const signal = abortControllerRef.current.signal;

    try {
      // Stage 1: Reading
      setParseState({
        stage: 'reading',
        progress: 10,
        stageLabel: 'Reading header...'
      });
      await new Promise(resolve => setTimeout(resolve, 100));
      if (signal.aborted) return;

      // Stage 2: Parsing TB-303 A
      setParseState({
        stage: 'parsing',
        progress: 30,
        stageLabel: 'Parsing TB-303 A...'
      });
      await new Promise(resolve => setTimeout(resolve, 150));
      if (signal.aborted) return;

      // Stage 3: Parsing TB-303 B
      setParseState({
        stage: 'parsing',
        progress: 50,
        stageLabel: 'Parsing TB-303 B...'
      });
      await new Promise(resolve => setTimeout(resolve, 150));
      if (signal.aborted) return;

      // Stage 4: Parsing drums
      setParseState({
        stage: 'parsing',
        progress: 70,
        stageLabel: 'Parsing drum patterns...'
      });
      await new Promise(resolve => setTimeout(resolve, 150));
      if (signal.aborted) return;

      // Stage 5: Parsing PCF and automation
      setParseState({
        stage: 'parsing',
        progress: 85,
        stageLabel: 'Parsing PCF settings...'
      });
      await new Promise(resolve => setTimeout(resolve, 100));
      if (signal.aborted) return;

      // Actual parse
      const result = await parseRbsFile(file, (progress) => {
        setParseState(prev => ({
          ...prev,
          progress: Math.min(95, 85 + progress * 0.1)
        }));
      });

      if (signal.aborted) return;

      if (!result.success) {
        setParseState({
          stage: 'error',
          progress: 0,
          stageLabel: 'Parse failed',
          error: result.error,
          category: categorizeError(result.error)
        });
        onShowToast(getErrorMessage(result.error), 'error');
        return;
      }

      // Complete
      setParseState({
        stage: 'complete',
        progress: 100,
        stageLabel: 'Parse complete!'
      });
      setParsedData(result.data);
      onShowToast(`Successfully parsed "${file.name}"`, 'success');

    } catch (error) {
      if (signal.aborted) return;
      setParseState({
        stage: 'error',
        progress: 0,
        stageLabel: 'Parse error',
        error: {
          type: 'READ_ERROR',
          message: error instanceof Error ? error.message : 'Unknown error'
        },
        category: 'READ_ERROR'
      });
      onShowToast('Failed to parse file', 'error');
    }
  }, [onShowToast]);

  // Handle file drop
  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    const file = e.dataTransfer.files[0];
    if (!file) return;

    // Validate extension
    if (!file.name.toLowerCase().endsWith('.rbs')) {
      setParseState({
        stage: 'error',
        progress: 0,
        stageLabel: 'Invalid file type',
        error: {
          type: 'INVALID_FORMAT',
          message: `File "${file.name}" does not have .rbs extension`
        },
        category: 'INVALID_FORMAT'
      });
      onShowToast('Please drop a .rbs file', 'error');
      return;
    }

    setDroppedFile(file);
    parseFile(file);
  }, [parseFile, onShowToast]);

  // Handle file select
  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.name.toLowerCase().endsWith('.rbs')) {
      setParseState({
        stage: 'error',
        progress: 0,
        stageLabel: 'Invalid file type',
        error: {
          type: 'INVALID_FORMAT',
          message: `File "${file.name}" does not have .rbs extension`
        },
        category: 'INVALID_FORMAT'
      });
      onShowToast('Please select a .rbs file', 'error');
      return;
    }

    setDroppedFile(file);
    parseFile(file);
  }, [parseFile, onShowToast]);

  // Cancel parsing
  const handleCancel = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
    }
    setParseState({
      stage: 'idle',
      progress: 0,
      stageLabel: 'Waiting for file...'
    });
    setDroppedFile(null);
    setParsedData(null);
  }, []);

  // Load example file
  const handleLoadExample = useCallback(() => {
    const exampleFile = generateExampleRbsFile();
    setDroppedFile(exampleFile);
    parseFile(exampleFile);
    onShowToast('Loaded example RBS file', 'info');
  }, [parseFile, onShowToast]);

  // Handle import
  const handleImport = useCallback(() => {
    if (!parsedData) return;

    setIsImporting(true);
    setParseState(prev => ({
      ...prev,
      stage: 'converting',
      stageLabel: 'Converting to Hyphon format...'
    }));

    // Small delay to show the converting state
    setTimeout(() => {
      try {
        const result = convertToHyphonSong(parsedData, importOptions);

        if (result.success) {
          onImport(result.song);
          // Store report and song name to show in the success panel
          setImportReport(result.report);
          setImportedSongName(result.song.metadata.name);
          setIsImporting(false);
          // Show a brief summary in the toast
          const warnCount = result.report.warnings.length;
          const autoCount = result.report.automationLanesConverted;
          const summaryParts: string[] = [`${result.report.stepsConverted} steps`];
          if (autoCount > 0) summaryParts.push(`${autoCount} automation lane${autoCount !== 1 ? 's' : ''}`);
          if (warnCount > 0) summaryParts.push(`${warnCount} warning${warnCount !== 1 ? 's' : ''}`);
          onShowToast(`Imported "${result.song.metadata.name}" — ${summaryParts.join(', ')}`, 'success');
        } else {
          onShowToast('Import conversion failed', 'error');
          setIsImporting(false);
          setParseState(prev => ({
            ...prev,
            stage: 'complete',
            stageLabel: 'Parse complete!'
          }));
        }
      } catch (error) {
        onShowToast(`Import error: ${error instanceof Error ? error.message : 'Unknown'}`, 'error');
        setIsImporting(false);
        setParseState(prev => ({
          ...prev,
          stage: 'complete',
          stageLabel: 'Parse complete!'
        }));
      }
    }, 300);
  }, [parsedData, importOptions, onImport, onShowToast]);

  // Update import option
  const updateOption = useCallback(<K extends keyof RbsImportOptions>(
    key: K,
    value: RbsImportOptions[K]
  ) => {
    setImportOptions(prev => ({ ...prev, [key]: value }));
  }, []);

  // Derived state
  const hasError = parseState.stage === 'error';
  const isComplete = parseState.stage === 'complete';
  const isParsing = parseState.stage === 'reading' || parseState.stage === 'parsing';

  // Pattern visualization data
  const patternVisualization = useMemo(() => {
    if (!parsedData) return null;

    return {
      tb303A: parsedData.tb303PatternA.steps.slice(0, 16),
      tb303B: parsedData.tb303PatternB.steps.slice(0, 16),
      drums: {
        kick: parsedData.drums.kick.slice(0, 16),
        snare: parsedData.drums.snare.slice(0, 16),
        closedHat: parsedData.drums.closedHat.slice(0, 16),
        openHat: parsedData.drums.openHat.slice(0, 16)
      },
      pcf: parsedData.pcf.enabled ? parsedData.pcf.pattern.slice(0, 16) : null
    };
  }, [parsedData]);

  // Parameter summary
  const paramSummary = useMemo(() => {
    if (!parsedData) return null;

    return {
      tb303A: {
        cutoff: parsedData.tb303PatternA.cutoff,
        resonance: parsedData.tb303PatternA.resonance,
        decay: parsedData.tb303PatternA.decay,
        waveform: parsedData.tb303PatternA.waveform === 0 ? 'saw' : 'square'
      },
      tb303B: {
        cutoff: parsedData.tb303PatternB.cutoff,
        resonance: parsedData.tb303PatternB.resonance,
        decay: parsedData.tb303PatternB.decay,
        waveform: parsedData.tb303PatternB.waveform === 0 ? 'saw' : 'square'
      },
      pcfEnabled: parsedData.pcf.enabled,
      kitType: parsedData.drums.kitType
    };
  }, [parsedData]);

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4"
    >
      <div
        className="absolute inset-0 z-0"
        onClick={onClose}
        aria-hidden="true"
      />
      <div ref={modalRef} role="dialog" aria-modal="true" aria-labelledby="rbs-import-title" aria-describedby="rbs-import-desc" tabIndex={-1} className="relative z-10 bg-[#0f1115] border border-amber-500/30 rounded-xl shadow-[0_0_60px_rgba(245,158,11,0.2)] w-full max-w-4xl max-h-[90vh] flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-800">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-lg bg-amber-500/10 border border-amber-500/30 flex items-center justify-center">
              <span className="text-2xl">🎹</span>
            </div>
            <div>
              <h2 id="rbs-import-title" className="text-lg font-bold text-white">Import ReBirth RB-338 File</h2>
              <p id="rbs-import-desc" className="text-xs text-gray-400">Import .rbs pattern files from ReBirth RB-338</p>
            </div>
          </div>
          <button type="button"
            onClick={onClose}
            className="w-8 h-8 rounded-lg bg-gray-800 hover:bg-gray-700 text-gray-400 hover:text-white transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-amber-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0f1115]"
            title="Close (Esc)"
            aria-label="Close modal"
          ><span aria-hidden="true">✕</span></button>
        </div>

        {/* Progress Bar */}
        <div className={`h-1 w-full transition-colors duration-300 ${getProgressColor(parseState.stage)}`}>
          <div
