const NOTES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

const midiToNote = (midi: number) => {
    const noteIndex = midi % 12;
    const octave = Math.floor(midi / 12) - 1; // MIDI 0 = C-1, we want C1 = MIDI 24
    return `${NOTES[noteIndex]}${octave}`;
};


