// ⚡ Bolt: Added React.memo to prevent unnecessary re-renders when parent state changes.
export const SamplerVoicePanel: React.FC<SamplerVoicePanelProps> = React.memo(({
    title,
    colorHex,
    controls,
    onParamChange,
    onRecordToggle,
    is3D = false,
    children,
    onMidiTouch,
    onMidiLearnStart,
    isMidiMapped,
    isMidiActive,
    automationTarget,
    patternIndex,
    onAutomationNudge,
    onAutomationPunchIn,
    onAutomationLaneAction,
    expressionLedTarget,
    expressionLedAnalyser,
    expressionLedFallbackColor,
    rootNote = 60, // C4 default
    coarseTune = 0,
    fineTune = 0,
    formantShift = 0,
    pitchAttack = 0,
    pitchDecay = 0.5,
    vibratoRate = 5.5,
    vibratoDepth = 0,
    tremoloDepth = 0,
    breathAmount = 0,
    vocoderMix = 0,
    quality = 'good',
    vocoderFormantShift = 0,
    vocoderPreservation = 1.0,
    vocoderAttack = 0.01,
    vocoderRelease = 0.05,
    stretchProfile = 'vocal',
    stretchMode = 'Time',
    lockToSequencer = false,
    onSamplerParamChange,
    harmonizerConfig,
    onHarmonizerConfigChange,
    isHarmonizeActive = false
}) => {
    const [localRootNote, setLocalRootNote] = useState(rootNote);
    const [localCoarse, setLocalCoarse] = useState(coarseTune);
    const [localFine, setLocalFine] = useState(fineTune);
    const [localFormant, setLocalFormant] = useState(formantShift);
    const [localPitchAtk, setLocalPitchAtk] = useState(pitchAttack);
    const [localPitchDec, setLocalPitchDecay] = useState(pitchDecay);
    const [localVibratoRate, setLocalVibratoRate] = useState(vibratoRate);
    const [localVibratoDepth, setLocalVibratoDepth] = useState(vibratoDepth);
    const [localTremoloDepth, setLocalTremoloDepth] = useState(tremoloDepth);
    const [localBreathAmount, setLocalBreathAmount] = useState(breathAmount);
    const [localVocoderMix, setLocalVocoderMix] = useState(vocoderMix);
    const [localVocoderFormantShift, setLocalVocoderFormantShift] = useState(vocoderFormantShift);
    const [localVocoderPreservation, setLocalVocoderPreservation] = useState(vocoderPreservation);
    const [localVocoderAttack, setLocalVocoderAttack] = useState(vocoderAttack);
    const [localVocoderRelease, setLocalVocoderRelease] = useState(vocoderRelease);
    const [localQuality, setLocalQuality] = useState<typeof stretchProfile>(stretchProfile);
    const [localStretch, setLocalStretch] = useState<typeof stretchMode>(stretchMode);
    const [localLock, setLocalLock] = useState(lockToSequencer);
    const [isHarmonizerOpen, setIsHarmonizerOpen] = useState(false);

    const ladderButtonRefs = useRef<Map<number, HTMLButtonElement>>(new Map());
    const harmonizeTriggerRef = useRef<HTMLButtonElement>(null);

    const handleHarmonizerClose = useCallback(() => {
        setIsHarmonizerOpen(false);
        harmonizeTriggerRef.current?.focus();
    }, []);

    const handleRootNoteChange = (midi: number) => {
        setLocalRootNote(midi);
        onSamplerParamChange?.('rootNote', midi);
    };

    const handleParamChange = (param: string, value: number | string | boolean) => {
        switch (param) {
            case 'coarseTune': setLocalCoarse(value as number); break;
            case 'fineTune': setLocalFine(value as number); break;
            case 'formantShift': setLocalFormant(value as number); break;
            case 'pitchAttack': setLocalPitchAtk(value as number); break;
            case 'pitchDecay': setLocalPitchDecay(value as number); break;
            case 'vibratoRate': setLocalVibratoRate(value as number); break;
            case 'vibratoDepth': setLocalVibratoDepth(value as number); break;
            case 'tremoloDepth': setLocalTremoloDepth(value as number); break;
            case 'breathAmount': setLocalBreathAmount(value as number); break;
            case 'vocoderMix': setLocalVocoderMix(value as number); break;
            case 'vocoderFormantShift': setLocalVocoderFormantShift(value as number); break;
            case 'vocoderPreservation': setLocalVocoderPreservation(value as number); break;
            case 'vocoderAttack': setLocalVocoderAttack(value as number); break;
            case 'vocoderRelease': setLocalVocoderRelease(value as number); break;
            case 'stretchProfile': setLocalQuality(value as typeof stretchProfile); break;
            case 'stretchMode': setLocalStretch(value as typeof stretchMode); break;
            case 'lockToSequencer': setLocalLock(value as boolean); break;
        }
        onSamplerParamChange?.(param, value);
    };

    // Generate root note ladder (C1 = 24 to C8 = 108, showing range around current)
    const ladderNotes = React.useMemo(() => {
        const center = localRootNote;
        const start = Math.max(24, center - 6);
        const end = Math.min(108, center + 6);
        const notes = [];
        for (let i = start; i <= end; i++) {
            notes.push({ midi: i, note: midiToNote(i) });
        }
        return notes;
    }, [localRootNote]);

    const color = `rgba(${colorHex[0] * 255}, ${colorHex[1] * 255}, ${colorHex[2] * 255}, 1)`;

    const handleRootNoteKeyDown = (e: React.KeyboardEvent) => {
        let nextNote = localRootNote;
        let handled = false;

        if (e.key === 'ArrowUp') {
            nextNote = localRootNote + 1;
            handled = true;
        } else if (e.key === 'ArrowDown') {
            nextNote = localRootNote - 1;
            handled = true;
        } else if (e.key === 'PageUp') {
            nextNote = localRootNote + 12;
            handled = true;
        } else if (e.key === 'PageDown') {
            nextNote = localRootNote - 12;
            handled = true;
        }

        if (handled) {
            e.preventDefault();
            // Restrict to the visible range or absolute bounds if needed
            // Currently ladderNotes is computed relative to localRootNote
            // but we can clamp to 0-127 MIDI bounds
            const clamped = Math.max(0, Math.min(127, nextNote));
            if (clamped !== localRootNote) {
                handleRootNoteChange(clamped);
                // Focus the newly selected button on next render cycle
                setTimeout(() => {
