import React, { memo } from 'react';
import { NOTES, SCALE_NAMES, TUNING_NAMES } from '../utils/musicTheory';
import type { ScaleDefinition } from '../utils/musicTheory';

interface ScaleSelectorProps {
    /** Current scale definition, or null if no scale lock is active */
    currentScale: ScaleDefinition | null;
    /** Callback when the user changes the scale (null = off) */
    onChange: (scale: ScaleDefinition | null) => void;
}

export const ScaleSelector: React.FC<ScaleSelectorProps> = memo(({ currentScale, onChange }) => {
    const isActive = currentScale !== null;

    const handleToggle = () => {
        if (isActive) {
            onChange(null);
        } else {
            onChange({ root: 'C', scale: 'Minor', tuning: '12-TET' });
        }
    };

    const handleTuningChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        if (!currentScale) return;
        onChange({ ...currentScale, tuning: e.target.value });
    };

    const handleRootChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        if (!currentScale) return;
        onChange({ ...currentScale, root: e.target.value });
    };

    const handleScaleChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        if (!currentScale) return;
        onChange({ ...currentScale, scale: e.target.value });
    };

    return (
        <div className="flex items-center gap-1.5 bg-gray-900/80 border border-gray-700 rounded-lg px-2 py-1">
            <button type="button"
                onClick={handleToggle}
                className={`px-2 py-0.5 text-[10px] font-bold font-orbitron rounded transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] focus-visible:ring-cyan-500 ${
                    isActive
                        ? 'bg-amber-500 text-black hover:bg-amber-400'
                        : 'bg-gray-700 text-gray-400 hover:bg-gray-600 hover:text-gray-200'
                }`}
                aria-pressed={isActive}
                aria-label="Key Lock"
                title="Enable Scale Lock — constrain notes to a musical key"
            >
                🔑 KEY
            </button>

            {isActive && (
                <fieldset className="flex items-center gap-1.5">
                    <legend className="sr-only">Scale Configuration</legend>
                    <select
                        value={currentScale!.root}
                        onChange={handleRootChange}
                        className="bg-gray-800 text-cyan-400 text-[10px] font-mono border border-gray-600 rounded px-1 py-0.5 focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] focus-visible:ring-cyan-500"
                        aria-label="Root note"
                    >
                        {NOTES.map(note => (
                            <option key={note} value={note}>{note}</option>
                        ))}
                    </select>

                    <select
                        value={currentScale!.scale}
                        onChange={handleScaleChange}
                        className="bg-gray-800 text-cyan-400 text-[10px] font-mono border border-gray-600 rounded px-1 py-0.5 focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] focus-visible:ring-cyan-500"
                        aria-label="Scale type"
                    >
                        {SCALE_NAMES.map(name => (
                            <option key={name} value={name}>{name}</option>
                        ))}
                    </select>

                    <select
                        value={currentScale!.tuning || '12-TET'}
                        onChange={handleTuningChange}
                        className="bg-gray-800 text-cyan-400 text-[10px] font-mono border border-gray-600 rounded px-1 py-0.5 focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] focus-visible:ring-cyan-500"
                        aria-label="Tuning System"
                    >
                        {TUNING_NAMES.map(tuning => (
                            <option key={tuning} value={tuning}>{tuning}</option>
                        ))}
                    </select>
                </fieldset>
            )}
        </div>
    );
});

import React, { memo, useCallback, useEffect, useMemo, useState } from 'react';
import { TRACK_KEYS } from '../constants';
import type { TrackKey } from '../constants/appDefaults';
import { midiMapStore } from '../stores/midiMapStore';
import { SESSION_PACKS } from '../session/packs';
import { LAUNCH_QUANTIZATIONS, SESSION_TRACK_LABELS, type LaunchQuantization, type SessionDocument } from '../session/types';
import { moveSessionFocus, type SessionGridFocus } from '../session/gridKeyboard';
import { sessionClipControlId, sessionSceneControlId } from '../session/midiMap';
import { startMidiLearnForControl } from '../hooks/useMidi';
import { useFocusTrap } from '../hooks/useFocusTrap';
import { a11yAnnouncerStore } from '../stores/a11yAnnouncerStore';

interface SessionLauncherProps {
  isVisible: boolean;
  document: SessionDocument;
  playingSlots: Record<TrackKey, number | null>;
  currentStep: number;
  isCapturing: boolean;
  quantization: LaunchQuantization;
  onClose: () => void;
  onLaunchClip: (track: TrackKey, row: number) => void;
  onLaunchScene: (row: number) => void;
  onStopTrack: (track: TrackKey) => void;
  onStopAll: () => void;
  onSetQuantization: (q: LaunchQuantization) => void;
  onBeginCapture: () => void;
  onFinishCapture: () => void;
  onUndo: () => void;
  onRedo: () => void;
  canUndo: boolean;
  canRedo: boolean;
  onLoadPack: (id: string) => void;
  onUpdateDocument: (next: SessionDocument) => void;
}

export const SessionLauncher = memo(function SessionLauncher({
  isVisible,
  document,
  playingSlots,
  currentStep,
  isCapturing,
  quantization,
  onClose,
  onLaunchClip,
  onLaunchScene,
  onStopTrack,
  onStopAll,
  onSetQuantization,
  onBeginCapture,
  onFinishCapture,
  onUndo,
  onRedo,
  canUndo,
  canRedo,
  onLoadPack,
  onUpdateDocument,
}: SessionLauncherProps) {
  const [focus, setFocus] = useState<SessionGridFocus>({ kind: 'scene', row: 0 });
  const rowCount = document.columns.partA.clips.length;

  const containerRef = useFocusTrap<HTMLDivElement>(isVisible, onClose);

  useEffect(() => {
    if (!isVisible || !containerRef.current) return;
    const selector = focus.kind === 'scene'
      ? `[data-testid="session-scene-${focus.row}"]`
      : `[data-testid="session-clip-${focus.track}-${focus.row}"]`;
    const el = containerRef.current.querySelector<HTMLElement>(selector);
    if (el) {
      el.focus();
    }
  }, [focus, isVisible, containerRef]);

  const queuedHint = useMemo(() => `Step ${currentStep + 1}`, [currentStep]);

  const handleLaunchScene = useCallback((row: number) => {
    onLaunchScene(row);
    a11yAnnouncerStore.announce(`launched scene ${row + 1}`);
  }, [onLaunchScene]);

  const handleLaunchClip = useCallback((track: TrackKey, row: number) => {
    onLaunchClip(track, row);
    a11yAnnouncerStore.announce(`clip ${SESSION_TRACK_LABELS[track]} playing`);
  }, [onLaunchClip]);

  const onGridKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      const next = moveSessionFocus(focus, e.key, rowCount);
      if (next !== focus && (e.key.startsWith('Arrow'))) {
        e.preventDefault();
        setFocus(next);
        return;
      }
      if (e.key === 'Enter' || e.key === ' ' || e.code === 'ControlLeft') {
        e.preventDefault();
        if (focus.kind === 'scene') handleLaunchScene(focus.row);
        else handleLaunchClip(focus.track, focus.row);
      }
      if (e.code === 'AltLeft') {
        e.preventDefault();
        handleLaunchScene(focus.kind === 'scene' ? focus.row : focus.row);
      }
      if (e.key === 'Backspace' || e.key === 'Delete') {
        e.preventDefault();
        if (focus.kind === 'clip') onStopTrack(focus.track);
        else onStopAll();
      }
    },
    [focus, rowCount, handleLaunchClip, handleLaunchScene, onStopTrack, onStopAll],
  );

  if (!isVisible) return null;

  return (
    <div
      className="fixed inset-0 z-40 flex items-end sm:items-center justify-center bg-black/70 p-2 sm:p-4"
      role="presentation"
      onClick={onClose}
    >
      <div
        ref={containerRef}
        className="w-full max-w-[1000px] max-h-[min(78vh,640px)] bg-[#0c1014] border border-cyan-900/50 rounded-xl shadow-[0_0_40px_rgba(6,182,212,0.15)] flex flex-col overflow-hidden"
        role="dialog"
        aria-modal="true"
        aria-labelledby="session-launcher-title"
        onClick={(e) => e.stopPropagation()}
        onKeyDown={onGridKeyDown}
      >
        <header className="flex flex-wrap items-center gap-2 p-3 border-b border-gray-800 bg-gray-900/40">
          <h2 id="session-launcher-title" className="font-orbitron text-cyan-400 tracking-widest text-sm font-bold mr-auto">
            SESSION
          </h2>
