          </label>
          <span className="text-[10px] font-mono text-gray-500" aria-live="polite">{queuedHint}</span>
          <button type="button" className="h-7 px-2 text-[10px] font-orbitron border border-zinc-700 rounded transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] hover:bg-zinc-800 disabled:opacity-50" onClick={onUndo} disabled={!canUndo} aria-label="Undo session edit">UNDO</button>
          <button type="button" className="h-7 px-2 text-[10px] font-orbitron border border-zinc-700 rounded transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] hover:bg-zinc-800 disabled:opacity-50" onClick={onRedo} disabled={!canRedo} aria-label="Redo session edit">REDO</button>
          <button
            type="button"
            className={`h-7 px-2 text-[10px] font-orbitron border rounded transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] hover:scale-105 active:scale-95 ${isCapturing ? 'bg-red-700 text-white border-red-400' : 'border-zinc-700 text-gray-300 hover:bg-zinc-800'}`}
            aria-pressed={isCapturing}
            aria-label={isCapturing ? 'Stop capturing launches into Song Mode' : 'Capture launches into Song Mode'}
            onClick={() => (isCapturing ? onFinishCapture() : onBeginCapture())}
          >
            {isCapturing ? 'CAPTURING' : 'CAPTURE'}
          </button>
          <button type="button" className="h-7 px-2 text-[10px] font-orbitron border border-zinc-700 rounded transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] hover:bg-zinc-800 disabled:opacity-50" onClick={onStopAll} aria-label="Stop all clips">STOP</button>
          <button type="button" className="h-7 w-7 text-gray-400 transition-colors hover:text-white focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] rounded" onClick={onClose} aria-label="Close Session Launcher" title="Close Session Launcher"><span aria-hidden="true">✕</span></button>
        </header>

        <div className="px-3 py-2 flex gap-2 overflow-x-auto border-b border-gray-800">
          {SESSION_PACKS.map((pack) => (
            <button
              key={pack.id}
              type="button"
              className="shrink-0 h-7 px-2 text-[10px] font-orbitron border border-cyan-900/60 text-cyan-300 rounded transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] hover:bg-cyan-900/30 hover:scale-105 active:scale-95"
              onClick={() => onLoadPack(pack.id)}
              aria-label={`Load starter pack ${pack.name}`}
            >
              {pack.name}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-auto custom-scrollbar p-2" data-testid="session-grid">
          {rowCount === 0 ? (
            <div role="status" className="flex flex-col items-center justify-center py-12 px-4 text-center bg-gray-800/20 border border-dashed border-gray-700 rounded-lg h-full min-h-[300px]">
              <div className="w-12 h-12 rounded-full bg-cyan-900/30 flex items-center justify-center mb-4 text-cyan-500" aria-hidden="true">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" />
                </svg>
              </div>
              <h3 className="text-gray-300 font-bold mb-2 text-sm">No clips in session</h3>
              <p className="text-gray-500 text-xs mb-6 max-w-[250px]">
                Your session is empty. Load a starter pack from the bar above or record your own clips.
              </p>
            </div>
          ) : (
          <div
            role="grid"
            aria-label="Clip launcher"
            className="min-w-[640px]"
          >
            <div role="row" className="flex text-[9px] uppercase tracking-wider text-gray-500 mb-1">
              <div role="columnheader" className="w-16 shrink-0 px-1">Scene</div>
              {TRACK_KEYS.map((track) => (
                <div key={track} role="columnheader" className="flex-1 min-w-[72px] px-1 text-center">
                  {SESSION_TRACK_LABELS[track]}
                </div>
              ))}
            </div>
            {Array.from({ length: rowCount }, (_, row) => (
              <div key={row} role="row" className="flex gap-1 mb-1">
                <button
                  type="button"
                  role="gridcell"
                  data-testid={`session-scene-${row}`}
                  tabIndex={focus.kind === 'scene' && focus.row === row ? 0 : -1}
                  aria-label={`Launch ${document.scenes[row]?.name ?? `scene ${row + 1}`}`}
                  className={`w-16 shrink-0 h-10 text-[10px] font-bold rounded border ${
                    focus.kind === 'scene' && focus.row === row
                      ? 'border-cyan-400 bg-cyan-950 text-cyan-200'
                      : 'border-zinc-800 bg-zinc-900 text-gray-300'
                  }`}
                  onFocus={() => setFocus({ kind: 'scene', row })}
                  onClick={() => handleLaunchScene(row)}
                  onContextMenu={(e) => {
                    e.preventDefault();
                    startMidiLearnForControl('session', `scene:${row}`);
                    midiMapStore.touchControl(sessionSceneControlId(row));
                  }}
                >
                  {document.scenes[row]?.name ?? row + 1}
                </button>
                {TRACK_KEYS.map((track) => {
                  const clip = document.columns[track].clips[row];
                  const playing = playingSlots[track] === clip?.slotIndex && clip && !clip.empty;
                  const focused = focus.kind === 'clip' && focus.track === track && focus.row === row;
                  return (
                    <button
                      key={track}
                      type="button"
                      role="gridcell"
                      data-testid={`session-clip-${track}-${row}`}
                      tabIndex={focused ? 0 : -1}
                      disabled={!clip || clip.empty}
                      aria-label={`${SESSION_TRACK_LABELS[track]} clip ${clip?.name ?? row + 1}${playing ? ', playing' : clip?.empty ? ', empty' : ''}`}
                      aria-pressed={!!playing}
                      className={`flex-1 min-w-[72px] h-10 text-[10px] rounded border truncate px-1 ${
                        playing
                          ? 'bg-cyan-600 text-black border-cyan-300'
                          : clip?.empty
                            ? 'bg-transparent border-zinc-800 text-zinc-600'
                            : focused
                              ? 'bg-zinc-800 border-cyan-400 text-white'
                              : 'bg-zinc-900 border-zinc-700 text-gray-200'
                      }`}
                      onFocus={() => setFocus({ kind: 'clip', track, row })}
                      onClick={() => handleLaunchClip(track, row)}
                      onContextMenu={(e) => {
                        e.preventDefault();
                        startMidiLearnForControl('session', `clip:${track}:${row}`);
                        midiMapStore.touchControl(sessionClipControlId(track, row));
                      }}
                    >
                      {clip?.empty ? '·' : clip?.name}
                    </button>
                  );
                })}
              </div>
            ))}
          </div>
          )}
        </div>

        <p className="sr-only">
          Arrow keys move focus. Enter or Space launches the focused clip or scene.
          Delete stops the focused track. Gamepad D-pad navigates; Attack launches the clip;
          Jump launches the scene. Right-click a cell to MIDI-learn.
        </p>
      </div>
    </div>
  );
});

