            </Float>

            {/* Sequencer - Main Desk */}
            <Panel position={[0, 0, 0]} rotation={[-0.2, 0, 0]} scale={0.3}>
              {sequencer}
            </Panel>

            {/* Keyboard - Lower Desk */}
            <Panel position={[0, -3.5, 1.5]} rotation={[-0.4, 0, 0]} scale={0.3}>
              {keyboard}
            </Panel>

            {/* Hardware Rack - Bottom/Front */}
            <Panel position={[0, -6.5, 3]} rotation={[-0.6, 0, 0]} scale={0.3}>
              {rack}
            </Panel>

          </group>

          {/* Floor Reflection */}
          <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -10, 0]}>
            <planeGeometry args={[50, 50]} />
            <meshStandardMaterial color="#0a0a0a" roughness={0.1} metalness={0.8} />
          </mesh>
          <ContactShadows position={[0, -10, 0]} opacity={0.6} scale={40} blur={2} far={4} />
        </Suspense>
      </Canvas>

      {/* HUD Instructions */}
      <div className="absolute bottom-4 right-4 text-gray-500 text-xs font-mono pointer-events-none opacity-50">
          <p>WASD to Move • Shift/Space Up/Down</p>
      </div>
    </div>
  );
});

import React, { memo, useCallback, useMemo } from 'react';
import { LoadingButton } from './LoadingButton';
import type { SynthParams } from '../types';
import { Knob } from './Knob';
import { OscillatorModuleSelector } from './OscillatorModuleSelector';

const FILTER_MODE_18_DB = 18;
const FILTER_MODE_24_DB = 24;
const FILTER_MODE_STEP_DB = FILTER_MODE_24_DB - FILTER_MODE_18_DB;

interface SynthPartProps {
  title: string;
  accentColor: 'cyan' | 'pink';
  params: SynthParams;
  onParamChange: (id: string, value: number) => void;
  isFrozen: boolean;
  isRendering: boolean;
  onMixdown: () => void;
  onUnfreeze: () => void;
}

export const SynthPart: React.FC<SynthPartProps> = memo(({ title, accentColor, params, onParamChange, isFrozen, isRendering, onMixdown, onUnfreeze }) => {
  const handleParamChange = useCallback(<K extends keyof SynthParams>(param: K, value: SynthParams[K]) => {
    onParamChange(param as string, value as number);
  }, [onParamChange]);

  const filterModeValue = (params.filterMode ?? 0) > 0 ? FILTER_MODE_24_DB : FILTER_MODE_18_DB;

  const accentClasses = {
    cyan: { border: 'border-cyan-500', text: 'text-cyan-400', knob: 'cyan' as const, ring: 'focus-visible:ring-cyan-400' },
    pink: { border: 'border-pink-500', text: 'text-pink-400', knob: 'pink' as const, ring: 'focus-visible:ring-pink-400' },
  };
  const isDisabled = isFrozen || isRendering;

  const handlers = useMemo(() => {
    return {
      waveform: (val: any) => handleParamChange('waveform', val as any),
      pitch: (val: number) => handleParamChange('pitch', val),
      filterCutoff: (val: number) => handleParamChange('filterCutoff', val),
      filterResonance: (val: number) => handleParamChange('filterResonance', val),
      filterMode: (val: number) => handleParamChange('filterMode', val >= FILTER_MODE_24_DB ? 1 : 0),
      attack: (val: number) => handleParamChange('attack', val),
      decay: (val: number) => handleParamChange('decay', val),
      volume: (val: number) => handleParamChange('volume', val),
      delayTime: (val: number) => handleParamChange('delayTime', val),
      delayFeedback: (val: number) => handleParamChange('delayFeedback', val),
      delayMix: (val: number) => handleParamChange('delayMix', val),
    };
  }, [handleParamChange]);

  return (
    <div className={`relative bg-gray-900/50 p-4 rounded-lg border-2 space-y-4 hyphon-legacy-panel hyphon-legacy-panel--${accentColor}`}>
      <div className="flex justify-between items-start">
        <h2 className={`font-orbitron text-xl font-bold ${accentClasses[accentColor].text}`}>{title}</h2>
        <LoadingButton
          aria-label={isFrozen ? "Unfreeze Track" : "Mixdown Track"}
          onClick={isFrozen ? onUnfreeze : onMixdown}
          isLoading={isRendering}
          loadingText="Rendering..."
          spinnerColor="text-gray-400"
          title={isRendering ? 'Rendering audio to track, please wait...' : isFrozen ? 'Unfreeze to edit track parameters (uses more CPU)' : 'Mixdown to freeze track (saves CPU)'}
          className={`px-3 py-1 text-xs font-bold rounded-md flex items-center gap-1.5 focus-visible:ring-offset-gray-900 ${accentClasses[accentColor].ring} ${
            isRendering ? 'bg-gray-600 text-gray-400' :
            isFrozen ? 'bg-yellow-500 hover:bg-yellow-600 text-gray-900' :
            'bg-indigo-500 hover:bg-indigo-600 text-white'
          }`}
        >
          {isFrozen ? 'Unfreeze' : 'Mixdown'}
        </LoadingButton>
      </div>

      <div className={`relative transition-opacity duration-300 ${isDisabled ? 'opacity-40 pointer-events-none' : ''}`}>
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-4">
          <fieldset className="space-y-2 border border-gray-800 rounded p-1">
            <legend className="sr-only">Oscillator</legend>
            <div className="text-center text-sm uppercase tracking-wider text-gray-400 mx-auto px-1 -mt-3 bg-gray-900 w-max" aria-hidden="true">Oscillator</div>
            <OscillatorModuleSelector selected={params.waveform} onChange={handlers.waveform} accentColor={accentColor} />
            <Knob label="Pitch" value={params.pitch} onChange={handlers.pitch} min={-24} max={24} step={1} color={accentClasses[accentColor].knob} unit="st" />
          </fieldset>
          <fieldset className="space-y-2 border border-gray-800 rounded p-1">
            <legend className="sr-only">Filter</legend>
            <div className="text-center text-sm uppercase tracking-wider text-gray-400 mx-auto px-1 -mt-3 bg-gray-900 w-max" aria-hidden="true">Filter</div>
            <Knob label="Cutoff" value={params.filterCutoff} onChange={handlers.filterCutoff} min={20} max={15000} color={accentClasses[accentColor].knob} unit="Hz" logarithmic />
            <Knob label="Resonance" value={params.filterResonance} onChange={handlers.filterResonance} min={0.1} max={30} color={accentClasses[accentColor].knob} unit="Q" />
            <Knob label="Mode" value={filterModeValue} onChange={handlers.filterMode} min={FILTER_MODE_18_DB} max={FILTER_MODE_24_DB} step={FILTER_MODE_STEP_DB} color={accentClasses[accentColor].knob} unit="dB" />
          </fieldset>
          <fieldset className="space-y-2 border border-gray-800 rounded p-1">
            <legend className="sr-only">Envelope</legend>
            <div className="text-center text-sm uppercase tracking-wider text-gray-400 mx-auto px-1 -mt-3 bg-gray-900 w-max" aria-hidden="true">Envelope</div>
            <Knob label="Attack" value={params.attack} onChange={handlers.attack} min={0.005} max={2} step={0.001} color={accentClasses[accentColor].knob} unit="s" logarithmic />
            <Knob label="Decay" value={params.decay} onChange={handlers.decay} min={0.01} max={2} step={0.001} color={accentClasses[accentColor].knob} unit="s" logarithmic />
          </fieldset>
          <fieldset className="space-y-2 border border-gray-800 rounded p-1">
            <legend className="sr-only">Output</legend>
            <div className="text-center text-sm uppercase tracking-wider text-gray-400 mx-auto px-1 -mt-3 bg-gray-900 w-max" aria-hidden="true">Output</div>
            <Knob label="Volume" value={params.volume} onChange={handlers.volume} min={0} max={1} step={0.01} color={accentClasses[accentColor].knob} />
          </fieldset>
          <fieldset className="space-y-2 border border-gray-800 rounded p-1">
            <legend className="sr-only">Delay</legend>
            <div className="text-center text-sm uppercase tracking-wider text-gray-400 mx-auto px-1 -mt-3 bg-gray-900 w-max" aria-hidden="true">Delay</div>
            <Knob label="Time" value={params.delayTime} onChange={handlers.delayTime} min={0} max={1} step={0.01} color={accentClasses[accentColor].knob} unit="s" />
            <Knob label="Feedback" value={params.delayFeedback} onChange={handlers.delayFeedback} min={0} max={0.95} step={0.01} color={accentClasses[accentColor].knob} />
            <Knob label="Mix" value={params.delayMix} onChange={handlers.delayMix} min={0} max={1} step={0.01} color={accentClasses[accentColor].knob} />
          </fieldset>
        </div>
      </div>
      {isFrozen && (
        <div className="absolute inset-0 bg-black/30 rounded-lg flex items-center justify-center">
            <span className="font-orbitron text-2xl font-bold text-yellow-400 transform -rotate-12">FROZEN</span>
        </div>
      )}
    </div>
  );
});

import React, { memo } from 'react'
import { CloudStatus } from './CloudStatus'
import { ScaleSelector } from './ScaleSelector'
import type { ScaleDefinition } from '../utils/musicTheory'
import type { SongSnapshot } from '../constants/appDefaults'
import { midiMapStore, useMidiMapStore } from '../stores/midiMapStore'
import { useTransportSyncStore } from '../stores/transportSyncStore'
import { HelpTip } from './help/HelpTip'
import { TransportSyncControls } from './TransportSyncControls'

interface TransportToolbarProps {
    songStorage: (SongSnapshot | null)[]
    activeSongSlot: number | null
    tempo: number
    isRecording: boolean
    isPlaying: boolean
    isSongModeOpen: boolean
    isSessionOpen?: boolean
    is3DMode: boolean
    loadSong: (slot: number) => void
    handleSaveSong: (slot: number) => Promise<void>
    handleClearPattern: () => void
    handleTempoHoldStart: (direction: number) => void
    handleTempoHoldEnd: () => void
    handleTempoKeyDown: (e: React.KeyboardEvent, direction: number) => void
    handlePanic: () => void
    handlePlayToggle: () => void
    setIsRecording: React.Dispatch<React.SetStateAction<boolean>>
    setIsSongModeOpen: React.Dispatch<React.SetStateAction<boolean>>
    setIsSessionOpen?: React.Dispatch<React.SetStateAction<boolean>>
    setIs3DMode: React.Dispatch<React.SetStateAction<boolean>>
    currentScale: ScaleDefinition | null
    setCurrentScale: (scale: ScaleDefinition | null) => void
    /** Optional always-visible engine status indicator rendered in the left cluster. */
    engineStatus?: React.ReactNode
    /** Toggle compact touch layout (mobile-friendly). */
    onToggleCompact?: () => void
    /** When true, tempo controls are read-only (MIDI slave). */
    tempoLocked?: boolean
    /** Override play button label in slave mode. */
    playLabel?: string
    isCompactLayout?: boolean
}

export const TransportToolbar = memo(function TransportToolbar({
    songStorage,
    activeSongSlot,
    tempo,
    isRecording,
    isPlaying,
    isSongModeOpen,
    isSessionOpen = false,
    is3DMode,
    loadSong,
    handleSaveSong,
    handleClearPattern,
    handleTempoHoldStart,
    handleTempoHoldEnd,
    handleTempoKeyDown,
    handlePanic,
    handlePlayToggle,
    setIsRecording,
    setIsSongModeOpen,
    setIsSessionOpen,
    setIs3DMode,
    currentScale,
    setCurrentScale,
    engineStatus,
    onToggleCompact,
    isCompactLayout = false,
    tempoLocked = false,
    playLabel,
}: TransportToolbarProps) {
    const { learnMode, inputAvailable } = useMidiMapStore();
    const { telemetry } = useTransportSyncStore();
    const displayTempo =
        tempoLocked && telemetry.measuredBpm != null
            ? Math.round(telemetry.measuredBpm)
            : tempo;

    const handleSongSlotKeyDown = (e: React.KeyboardEvent, slot: number, isSaved: boolean) => {
        if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            if (isSaved) loadSong(slot);
            else void handleSaveSong(slot);
            return;
        }
        let next = -1;
        if (e.key === 'ArrowRight') next = (slot + 1) % 4;
        else if (e.key === 'ArrowLeft') next = (slot - 1 + 4) % 4;
        else if (e.key === 'Home') next = 0;
        else if (e.key === 'End') next = 3;
        if (next !== -1) {
            e.preventDefault();
            (e.currentTarget.parentElement?.querySelector(`[data-song-slot="${next}"]`) as HTMLButtonElement | null)?.focus();
        }
    };

    return (
        <header className="transport-toolbar h-12 flex items-center justify-between px-2 sm:px-4 hyphon-toolbar-shell border-b shrink-0 relative w-full z-30">
            {/* Left: Logo + Song Tabs */}
            <div className="flex items-center gap-4">
                <h1 className="text-lg font-bold font-orbitron text-cyan-400 tracking-widest hidden md:block drop-shadow-[0_0_8px_rgba(6,182,212,0.6)]">HYPHON</h1>

                {/* Song Slots */}
                <div className="flex items-center gap-1 hyphon-inset-well p-1.5" role="group" aria-label="Song slots">
                    <span className="text-[9px] text-gray-600 font-mono uppercase px-1 mr-1">SONG</span>
                    {[0, 1, 2, 3].map(slot => {
                        const isSaved = !!songStorage[slot];
                        const isActive = activeSongSlot === slot;
                        return (
                            <button type="button"
                                key={slot}
                                data-song-slot={slot}
                                onClick={() => { if (isSaved) loadSong(slot); else handleSaveSong(slot); }} 
                                onContextMenu={(e) => { e.preventDefault(); handleSaveSong(slot); }}
                                onKeyDown={(e) => handleSongSlotKeyDown(e, slot, isSaved)}
                                title={`Song Slot ${slot + 1}`}
                                className={`w-7 h-6 text-xs font-mono transition-all duration-150 focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] rounded hover:scale-105 active:scale-95 ${isActive ? 'bg-cyan-500 text-black font-bold shadow-[0_0_10px_rgba(6,182,212,0.6)]' : (isSaved ? 'bg-cyan-900/40 text-cyan-300 border border-cyan-700/50 hover:bg-cyan-800/50' : 'bg-zinc-900 text-zinc-600 border border-zinc-800 hover:border-zinc-700')}`}
                                aria-label={`Song Slot ${slot + 1}`} 
                                aria-pressed={isActive}
                            >
                                {slot + 1}
                            </button>
                        );
                    })}
                </div>

                {/* Cloud Status */}
                <div className="flex items-center gap-2">
                    <CloudStatus />
                </div>

                {/* Engine Status Pills */}
                {engineStatus && (
                    <div className="flex items-center">
                        {engineStatus}
                    </div>
                )}
            </div>

            {/* Center: Transport Controls (desktop / tablet) */}
            <div className="hidden sm:flex items-center gap-3">
                {/* Play/Stop Button */}
                <button type="button"
                    onClick={handlePlayToggle}
                    aria-pressed={isPlaying}
                    aria-label={isPlaying ? "Stop Playback" : "Start Playback"}
                    title={isPlaying ? "Stop Playback (Space)" : "Start Playback (Space)"}
                    className={`h-8 px-5 font-orbitron text-sm font-bold tracking-wider transition-all duration-150 shadow-lg focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] rounded-md hover:scale-105 active:scale-95 ${isPlaying ? 'bg-red-600 hover:bg-red-500 text-white shadow-[0_0_15px_rgba(220,38,38,0.5)] border border-red-400' : 'bg-green-600 hover:bg-green-500 text-white shadow-[0_0_15px_rgba(22,163,74,0.4)] border border-green-400'}`}
                >
                    {isPlaying ? '■ STOP' : (playLabel ?? '▶ PLAY')}
                </button>

                {/* Record Button */}
                <button type="button"
                    onClick={() => setIsRecording(!isRecording)}
                    aria-pressed={isRecording} 
                    aria-label="Toggle Recording" 
                    title={isRecording ? "Stop Recording" : "Toggle Recording"}
                    className={`h-8 w-10 font-orbitron text-xs font-bold tracking-wide transition-all duration-150 focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] rounded-md hover:scale-105 active:scale-95 ${isRecording ? 'bg-red-600 text-white animate-pulse shadow-[0_0_15px_rgba(220,38,38,0.6)] border border-red-400' : 'bg-zinc-800 hover:bg-zinc-700 text-red-500 border border-zinc-700 hover:border-red-900/50'}`}
                >
                    REC
                </button>

                {/* Divider */}
                <div className="w-px h-5 bg-gray-700 mx-1" />

                {/* BPM Control */}
                <div className="flex items-center gap-1.5">
                    <span className="text-[9px] text-gray-500 font-mono uppercase tracking-wider">BPM</span>
                    <div className="flex items-center bg-zinc-950 rounded-md border border-zinc-800 shadow-[inset_0_1px_2px_rgba(0,0,0,0.5)]">
                        <button type="button"
                            onMouseDown={() => !tempoLocked && handleTempoHoldStart(-1)}
                            onMouseUp={handleTempoHoldEnd}
                            onMouseLeave={handleTempoHoldEnd}
                            onKeyDown={(e) => !tempoLocked && handleTempoKeyDown(e, -1)}
                            disabled={tempoLocked}
                            className="w-6 h-7 text-cyan-500 hover:text-cyan-400 font-bold text-sm border-r border-zinc-800 transition-all duration-150 focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] rounded-l-md hover:bg-zinc-900/50 hover:scale-105 active:scale-95 disabled:opacity-40 disabled:pointer-events-none"
                            title="Decrease Tempo"
                            aria-label="Decrease Tempo"
                        >
                            −
                        </button>
                        <span 
                            className="w-12 text-center font-mono text-cyan-300 text-sm font-semibold" 
                            role="status" 
                            aria-live="polite" 
                            aria-label={`Tempo: ${displayTempo} BPM`}
                        >
                            {displayTempo}
                        </span>
                        <button type="button"
                            onMouseDown={() => !tempoLocked && handleTempoHoldStart(1)}
                            onMouseUp={handleTempoHoldEnd}
                            onMouseLeave={handleTempoHoldEnd}
                            onKeyDown={(e) => !tempoLocked && handleTempoKeyDown(e, 1)}
                            disabled={tempoLocked}
                            className="w-6 h-7 text-cyan-500 hover:text-cyan-400 font-bold text-sm border-l border-zinc-800 transition-all duration-150 focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] rounded-r-md hover:bg-zinc-900/50 hover:scale-105 active:scale-95 disabled:opacity-40 disabled:pointer-events-none"
                            title="Increase Tempo"
                            aria-label="Increase Tempo"
                        >
                            +
                        </button>
                    </div>
                </div>

                {/* Divider */}
                <div className="w-px h-5 bg-gray-700 mx-1 hidden lg:block" />

                <TransportSyncControls />

                {/* Divider */}
                <div className="w-px h-5 bg-gray-700 mx-1" />

                {/* Key Lock / Scale Selector */}
                <ScaleSelector currentScale={currentScale} onChange={setCurrentScale} />

                <div className="w-px h-5 bg-gray-700 mx-1" />

                <button
                    type="button"
                    onClick={() => midiMapStore.toggleLearnMode()}
                    aria-pressed={learnMode}
                    aria-label="Toggle MIDI Learn"
                    title={learnMode ? 'MIDI Learn ON — touch a control, then move a controller knob' : 'MIDI Learn — map controller knobs to parameters'}
                    className={`h-7 px-2 font-orbitron text-[9px] font-bold tracking-wide transition-all duration-150 focus:outline-none focus-visible:ring-2 focus-visible:ring-purple-500 rounded-md ${
                        learnMode
                            ? 'bg-purple-600 text-white animate-pulse border border-purple-400 shadow-[0_0_10px_rgba(168,85,247,0.5)]'
                            : 'bg-zinc-800 text-purple-400 border border-zinc-700 hover:bg-purple-950/40'
                    }`}
                >
                    MIDI{inputAvailable ? '' : ' ○'}
                </button>
                <button
                    type="button"
                    onClick={() => midiMapStore.setPanelOpen(true)}
                    aria-label="Open MIDI Map"
                    title="View / clear MIDI mappings"
                    className="h-7 px-2 text-[9px] font-bold text-purple-300 bg-zinc-900 border border-purple-900/50 rounded-md hover:bg-purple-950/40"
                >
                    MAP
                </button>
            </div>
            <div className="flex items-center gap-1 sm:gap-2">
                {onToggleCompact && (
                    <button
                        type="button"
                        onClick={onToggleCompact}
                        aria-pressed={isCompactLayout}
                        aria-label={isCompactLayout ? 'Switch to comfortable layout' : 'Switch to compact touch layout'}
                        title={isCompactLayout ? 'Comfortable layout' : 'Compact touch layout'}
                        className={`h-8 min-w-[2.5rem] px-2 text-[10px] font-bold border rounded-md touch-manipulation focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 ${
                            isCompactLayout
                                ? 'bg-cyan-900/50 text-cyan-200 border-cyan-600'
                                : 'bg-zinc-900 text-gray-400 border-zinc-700'
                        }`}
                    >
                        {isCompactLayout ? 'CMP' : 'FIT'}
                    </button>
                )}
                {/* Clear Button */}
                <button type="button"
                    onClick={handleClearPattern} 
                    className="h-7 px-3 text-xs font-bold text-red-400 border border-red-900/50 bg-gradient-to-r from-red-950/30 to-red-900/20 hover:bg-red-900/30 transition-all duration-150 focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] rounded-md hover:scale-105 active:scale-95"
                    aria-label="Clear Current Pattern" 
                    title="Clear Current Pattern"
                >
                    CLEAR
                </button>

                {/* Divider */}
                <div className="w-px h-5 bg-gray-700 mx-1" />

                {/* Song Mode Toggle */}
                <HelpTip topicId="song-mode" position="bottom">
                <button type="button"
                    onClick={() => setIsSongModeOpen(!isSongModeOpen)}
                    aria-pressed={isSongModeOpen} 
                    aria-label="Toggle Song Mode" 
                    title={isSongModeOpen ? "Close Song Mode" : "Open Song Mode"}
                    className={`h-7 px-3 font-orbitron text-xs font-bold tracking-wide transition-all duration-150 focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] rounded-md hover:scale-105 active:scale-95 ${isSongModeOpen ? 'bg-purple-600 text-white shadow-[0_0_10px_rgba(147,51,234,0.5)] border border-purple-400' : 'bg-zinc-800 text-gray-400 border border-zinc-700 hover:bg-zinc-700 hover:text-gray-300'}`}
                >
                    SONG
                </button>
                </HelpTip>

                {setIsSessionOpen && (
                <HelpTip topicId="session-launcher" position="bottom">
                <button type="button"
                    onClick={() => setIsSessionOpen(!isSessionOpen)}
                    aria-pressed={isSessionOpen}
                    aria-label="Toggle Session Launcher"
                    title={isSessionOpen ? "Close Session Launcher" : "Open Session Launcher"}
                    className={`h-7 px-3 font-orbitron text-xs font-bold tracking-wide transition-all duration-150 focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] rounded-md hover:scale-105 active:scale-95 ${isSessionOpen ? 'bg-cyan-600 text-white shadow-[0_0_10px_rgba(6,182,212,0.5)] border border-cyan-400' : 'bg-zinc-800 text-gray-400 border border-zinc-700 hover:bg-zinc-700 hover:text-gray-300'}`}
                >
                    CLIP
                </button>
                </HelpTip>
                )}

                {/* 3D Toggle */}
                <button type="button"
                    onClick={() => setIs3DMode(!is3DMode)}
                    aria-pressed={is3DMode}
                    aria-label="Toggle 3D Studio View"
                    title={is3DMode ? "Exit 3D Studio" : "Enter 3D Studio"}
                    className={`h-7 w-8 font-orbitron text-xs font-bold transition-all duration-150 focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0d1014] rounded-md hover:scale-105 active:scale-95 ${is3DMode ? 'bg-cyan-600 text-white border border-cyan-400 shadow-[0_0_10px_rgba(6,182,212,0.5)]' : 'bg-zinc-800 text-cyan-500 border border-zinc-700 hover:bg-zinc-700'}`}
                >
                    3D
                </button>

                {/* Panic Button */}
                <button type="button"
                    onClick={handlePanic} 
                    aria-label="Panic Stop All Notes" 
