import React, { useRef, useEffect, useState } from 'react';
import { VoiceDesigner } from '../services/VoiceDesigner';
import { SupertonicService } from '../services/Supertonic';
import { useFocusTrap } from '../hooks/useFocusTrap';

interface VoiceEditorProps {
    onClose: () => void;
}

// ⚡ Bolt: Added React.memo to prevent unnecessary re-renders when parent state changes.
export const VoiceEditor: React.FC<VoiceEditorProps> = React.memo(({ onClose }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const designerRef = useRef<VoiceDesigner | null>(null);
    const [status, setStatus] = useState("Ready");
    const [isApplying, setIsApplying] = useState(false);

    // Initialize focus trap
    const trapRef = useFocusTrap<HTMLDivElement>(true, onClose);

    useEffect(() => {
        if (!canvasRef.current) return;

        const initDesigner = () => {
            designerRef.current = new VoiceDesigner();
            const service = SupertonicService.getInstance();

            if (!service.isServiceReady()) {
                setStatus("TTS Service Not Ready");
                return;
            }

            const currentStyle = service.getStyle();

            if (currentStyle) {
                designerRef.current.setCanvas(canvasRef.current!);
                designerRef.current.loadFromStyle(currentStyle);
                setStatus("Voice Loaded");
            } else {
                setStatus("No Voice Loaded");
            }
        };

        initDesigner();
    }, []);

    // Dev-only: expose purge action on window.__devtools
    useEffect(() => {
        if (import.meta.env.DEV) {
            const service = SupertonicService.getInstance();
            (window as any).__devtools = (window as any).__devtools || {};
            (window as any).__devtools.purgeTTSCache = () => {
                service.purgeCache();
            };
        }
    }, []);

    const handlePurgeCache = () => {
        const service = SupertonicService.getInstance();
        service.purgeCache();
        setStatus("ONNX cache purged");
    };

    const handleOp = async (op: keyof VoiceDesigner) => {
        const d = designerRef.current;
        if (d && typeof d[op] === 'function') {
            await (d[op] as () => Promise<void>)();
            setStatus(`Applied: ${op}`);
        }
    };

    const handleApply = () => {
        if (!designerRef.current) return;

        const service = SupertonicService.getInstance();
        if (!service.isServiceReady()) {
            setStatus("Cannot apply: TTS not ready");
            return;
        }

        const raw = designerRef.current.getRawData();
        if (raw.ttl && raw.dp) {
            setIsApplying(true);
            setStatus("Applying...");
            service.updateStyleFromRaw(raw.ttl, raw.dp, raw.ttlDims, raw.dpDims);
            setStatus("Style Applied to Engine!");
            setTimeout(onClose, 500);
        }
    };

    const btnClass = "text-xs py-2 rounded focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-gray-900 focus-visible:ring-purple-400 transition-colors";

    return (
        <div
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm"
        >
            <div
                className="absolute inset-0 z-0"
                onClick={onClose}
                aria-hidden="true"
            />
            <div
                ref={trapRef}
                className="relative z-10 bg-gray-900 border border-purple-500 rounded-xl p-6 w-[600px] shadow-2xl outline-none"
                role="dialog"
                aria-modal="true"
                aria-labelledby="voice-designer-title"
                tabIndex={-1}
            >
                <div className="flex justify-between items-center mb-4">
                    <h2 id="voice-designer-title" className="text-xl font-orbitron text-purple-400">VOICE DESIGNER <span className="text-xs text-gray-500 ml-2">(WebGPU)</span></h2>
                    <button type="button" onClick={onClose} className="text-gray-400 hover:text-white focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-gray-900 focus-visible:ring-purple-400 rounded" aria-label="Close Voice Designer" title="Close Voice Designer"><span aria-hidden="true">✕</span></button>
                </div>

                {/* Heatmap Area */}
                <div className="border border-gray-700 bg-black mb-4 h-48 relative rounded overflow-hidden">
                    {status === "No Voice Loaded" || status === "Ready" ? (
                        <div role="status" className="absolute inset-0 flex flex-col items-center justify-center p-4 text-center bg-gray-800/20 border border-dashed border-gray-700">
                            <div className="w-12 h-12 rounded-full bg-purple-900/30 flex items-center justify-center mb-4 text-purple-500" aria-hidden="true">
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                                </svg>
                            </div>
                            <h3 className="text-gray-300 font-bold mb-2 text-sm">No Voice Loaded</h3>
                            <p className="text-gray-500 text-xs max-w-[250px]">
                                Select a TTS voice from the library to view and edit its characteristics.
                            </p>
                        </div>
                    ) : null}
                    <canvas
                        ref={canvasRef}
                        className="w-full h-full block"
                        style={{
                            imageRendering: 'pixelated',
                            display: (status === "No Voice Loaded" || status === "Ready") ? 'none' : 'block'
                        }}
                        role="img"
                        aria-label="Voice Heatmap Visualization - Interactive Canvas"
                    />
                </div>

                {/* Controls */}
                <div className="grid grid-cols-4 gap-2 mb-6 font-mono">
                    <button type="button" onClick={() => handleOp('mirrorX')} className={`${btnClass} bg-gray-800 hover:bg-gray-700 text-gray-300`} aria-label="Mirror the voice pattern horizontally" title="Mirror the voice pattern horizontally">Mirror X</button>
                    <button type="button" onClick={() => handleOp('mirrorY')} className={`${btnClass} bg-gray-800 hover:bg-gray-700 text-gray-300`} aria-label="Mirror the voice pattern vertically" title="Mirror the voice pattern vertically">Mirror Y</button>
                    <button type="button" onClick={() => handleOp('invertSign')} className={`${btnClass} bg-gray-800 hover:bg-gray-700 text-gray-300`} aria-label="Invert the phase of the voice pattern" title="Invert the phase of the voice pattern">Invert</button>
                    <button type="button" onClick={() => handleOp('randomShift')} className={`${btnClass} bg-gray-800 hover:bg-gray-700 text-gray-300`} aria-label="Randomly shift voice characteristics" title="Randomly shift voice characteristics">Rand Shift</button>

                    <button type="button" onClick={() => handleOp('dspSharpen')} className={`${btnClass} bg-purple-900/30 hover:bg-purple-900/50 text-purple-300 border border-purple-900/50`} aria-label="Enhance contrast in voice features" title="Enhance contrast in voice features">Sharpen</button>
                    <button type="button" onClick={() => handleOp('dspTremolo')} className={`${btnClass} bg-purple-900/30 hover:bg-purple-900/50 text-purple-300 border border-purple-900/50`} aria-label="Apply amplitude modulation" title="Apply amplitude modulation">Tremolo</button>
                    <button type="button" onClick={() => handleOp('dspEcho')} className={`${btnClass} bg-purple-900/30 hover:bg-purple-900/50 text-purple-300 border border-purple-900/50`} aria-label="Add delay/echo effect" title="Add delay/echo effect">Echo</button>
                    <button type="button" onClick={() => handleOp('reset')} className={`${btnClass} bg-red-900/30 hover:bg-red-900/50 text-red-300 border border-red-900/50`} aria-label="Reset to original voice style" title="Reset to original voice style">Reset</button>
                </div>

                <div className="flex justify-between items-center">
                    <span
                        className="text-xs text-gray-500 font-mono"
                        role="status"
                        aria-live="polite"
                    >
                        {status}
                    </span>
                    <button type="button"
                        onClick={handleApply}
                        disabled={isApplying}
                        title={isApplying ? "Applying changes..." : "Apply changes"}
                        className={`px-6 py-2 bg-green-600 hover:bg-green-500 text-white font-bold rounded shadow-[0_0_15px_rgba(34,197,94,0.3)] font-mono text-sm focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-gray-900 focus-visible:ring-white disabled:opacity-50 disabled:cursor-wait`}
                        aria-busy={isApplying}
                    >
                        {isApplying ? (
                           <span className="flex items-center gap-2">
                               <svg aria-hidden="true" className="animate-spin h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                   <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                   <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                               </svg>
                               APPLYING...
                           </span>
                        ) : "APPLY TO ENGINE"}
                    </button>
                </div>

                {import.meta.env.DEV && (
                    <div className="mt-4 pt-4 border-t border-red-900/30">
                        <div className="flex justify-between items-center">
                            <span className="text-xs text-red-400/70 font-mono">Dev Tools</span>
                            <button type="button"
                                onClick={handlePurgeCache}
                                className="px-4 py-1.5 bg-red-900/20 hover:bg-red-900/40 text-red-300 border border-red-900/40 rounded font-mono text-xs focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-gray-900 focus-visible:ring-red-400 transition-colors"
                                aria-label="Purge ONNX TTS cache"
                                title="Purge ONNX TTS cache"
                            >
                                Purge ONNX Cache (Dev)
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
});

import React from 'react';
import type { WamHost } from '../audio/wam/WamHost';
import type { Wam2PackageDescriptor, Wam2ParamDesc } from '../audio/wam/types';
import {
  deletePreset,
  listPresets,
  savePreset,
  type Wam2StoredPreset,
} from '../audio/wam/presets';
import { automationStore, generateLaneId } from '../stores/automationStore';
import type { UnifiedAutomationLane } from '../types';

/**
 * Fallback editor for a WAM2 plugin that ships no UI of its own.
 *
 * The param list comes from the descriptor, so this works identically for a
 * bundled fixture and an allowlisted community package — a package does not have
 * to ship a UI to be usable or automatable.
 *
 * Accessibility: every control is a native `<input>`/`<button>` with a real
 * `<label htmlFor>`, so the whole panel is reachable and operable by keyboard
 * with no custom key handling. Range inputs already support arrows/Home/End.
 * Live values are announced through `aria-valuetext` rather than a separate
 * live region, which would fire on every drag frame.
 */

export interface Wam2GenericEditorProps {
  host: WamHost;
  slotId: string;
  descriptor: Wam2PackageDescriptor;
  /** Pattern the created automation lane belongs to. */
  patternIndex?: number;
  onChange?: (paramId: string, value: number) => void;
}

function formatValue(param: Wam2ParamDesc, value: number): string {
  const span = param.max - param.min;
  if (span >= 100) return value.toFixed(0);
  if (span >= 2) return value.toFixed(2);
  return value.toFixed(3);
}

/** Lane id for a WAM2 param, per AutomationScheduler: `slotId/paramId`. */
export function wam2LaneParameter(slotId: string, paramId: string): string {
  return `${slotId}/${paramId}`;
}

/** Map a param's real-world value into the [0, 1] automation lane domain. */
function normaliseParamValue(param: Wam2ParamDesc, value: number): number {
  const span = param.max - param.min;
  if (!Number.isFinite(span) || span === 0) return 0;
  return Math.min(1, Math.max(0, (value - param.min) / span));
}

function stepFor(param: Wam2ParamDesc): number {
  const span = param.max - param.min;
  // 1000 steps across the range, rounded to something a keyboard user can land on.
  if (span >= 1000) return 1;
  if (span >= 10) return 0.1;
  return span / 1000;
}

export const Wam2GenericEditor: React.FC<Wam2GenericEditorProps> = ({
  host,
  slotId,
  descriptor,
  patternIndex = 0,
  onChange,
}) => {
  const [values, setValues] = React.useState<Record<string, number>>(() => {
    const initial: Record<string, number> = {};
    for (const param of descriptor.params) {
      initial[param.id] = host.getParam(slotId, param.id) ?? param.defaultValue;
    }
    return initial;
  });
  /**
   * Text the user is part-way through typing in a number field.
   *
   * The number inputs cannot clamp on every keystroke: typing "5000" into a
   * field whose min is 80 passes through "5", which would clamp to 80 and leave
   * the caret in a field reading "80" — the intended value becomes untypeable.
   * So a draft is held verbatim while the field has focus and only committed
   * (and clamped) on blur or Enter. In-range keystrokes still apply live, so
   * dragging-by-typing keeps working.
   */
  const [drafts, setDrafts] = React.useState<Record<string, string>>({});
  const [presets, setPresets] = React.useState<Wam2StoredPreset[]>(() =>
    listPresets(descriptor.id),
  );
  const [presetName, setPresetName] = React.useState('');
  const [status, setStatus] = React.useState<string>('');

  const setParam = React.useCallback(
    (param: Wam2ParamDesc, raw: number) => {
      const value = Math.min(param.max, Math.max(param.min, raw));
      host.setParam(slotId, param.id, value);
      setValues((prev) => ({ ...prev, [param.id]: value }));
      onChange?.(param.id, value);
      return value;
    },
    [host, slotId, onChange],
  );

  /** Clamp and apply whatever is in the draft, then drop it. */
  const commitDraft = React.useCallback(
    (param: Wam2ParamDesc) => {
      setDrafts((prev) => {
        const text = prev[param.id];
        if (text === undefined) return prev;
        const parsed = Number(text);
        setParam(param, Number.isFinite(parsed) && text !== '' ? parsed : (values[param.id] ?? param.defaultValue));
        const next = { ...prev };
        delete next[param.id];
        return next;
      });
    },
    [setParam, values],
  );

  const addAutomationLane = React.useCallback(
    (param: Wam2ParamDesc) => {
      const parameter = wam2LaneParameter(slotId, param.id);
      const existing = automationStore
        .getState()
        .lanes.find((lane) => lane.target === 'wam' && lane.parameter === parameter);
      if (existing) {
        setStatus(`Automation lane for ${param.label} already exists`);
        return;
      }
      const lane: UnifiedAutomationLane = {
        id: generateLaneId(),
        target: 'wam',
        parameter,
        name: `${descriptor.title} · ${param.label}`,
        // AutomationLanePoint.value is normalised to [0, 1]; param.min/max is
        // carried as display metadata in originalRange.
        points: [{ step: 0, value: normaliseParamValue(param, values[param.id] ?? param.defaultValue) }],
        interpolation: 'linear',
        source: 'manual',
        scope: 'pattern',
        patternIndex,
        enabled: true,
        originalRange: [param.min, param.max],
      };
      automationStore.addLane(lane);
      setStatus(`Automation lane created for ${param.label}`);
    },
    [slotId, descriptor.title, values, patternIndex],
  );

  const onSavePreset = React.useCallback(() => {
    const preset = host.capturePreset(slotId);
    if (!preset) {
      setStatus('Slot is not mounted — nothing to save');
      return;
    }
    const stored = savePreset(presetName, preset);
    setPresets(listPresets(descriptor.id));
    setPresetName('');
    setStatus(`Saved preset "${stored.name}"`);
  }, [host, slotId, presetName, descriptor.id]);

  const onLoadPreset = React.useCallback(
    (preset: Wam2StoredPreset) => {
      if (!host.applyPreset(slotId, preset)) {
        // applyPreset refuses a preset from a different package rather than
        // half-applying it.
        setStatus(`Preset "${preset.name}" does not belong to ${descriptor.id}`);
        return;
      }
      const next: Record<string, number> = {};
      for (const param of descriptor.params) {
        next[param.id] = host.getParam(slotId, param.id) ?? param.defaultValue;
      }
      setValues(next);
      setDrafts({});
      setStatus(`Loaded preset "${preset.name}"`);
    },
    [host, slotId, descriptor],
  );

  const onDeletePreset = React.useCallback(
    (preset: Wam2StoredPreset) => {
      deletePreset(descriptor.id, preset.name);
      setPresets(listPresets(descriptor.id));
      setStatus(`Deleted preset "${preset.name}"`);
    },
    [descriptor.id],
  );

  const headingId = `wam2-editor-${slotId}-heading`;

  return (
    <section
      className="flex flex-col gap-3 rounded border border-gray-700 bg-gray-900 p-3"
      aria-labelledby={headingId}
    >
      <header className="flex items-baseline justify-between gap-2">
        <h3 id={headingId} className="font-orbitron text-sm text-gray-100">
          {descriptor.title}
        </h3>
        <p className="text-xs text-gray-400">
          {descriptor.id}@{descriptor.version} · {descriptor.origin}
          {descriptor.offline === 'unsupported' && (
            <>
              {' · '}
              <span
                className="rounded bg-amber-900/60 px-1 text-amber-200"
                title="This plugin cannot be rendered in an OfflineAudioContext, so track freeze is unavailable for it."
              >
                no freeze
              </span>
            </>
          )}
        </p>
      </header>

      {descriptor.params.length === 0 ? (
        <div role="status" className="flex flex-col items-center justify-center py-12 px-4 text-center bg-gray-800/20 border border-dashed border-gray-700 rounded-lg">
          <div className="w-12 h-12 rounded-full bg-cyan-900/30 flex items-center justify-center mb-4 text-cyan-500" aria-hidden="true">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" />
            </svg>
          </div>
          <h3 className="text-gray-300 font-bold mb-2 text-sm">No automatable parameters</h3>
          <p className="text-gray-500 text-xs mb-6 max-w-[250px]">
            This plugin declares no automatable parameters.
          </p>
        </div>
      ) : (
        <ul className="flex list-none flex-col gap-3 p-0">
          {descriptor.params.map((param) => {
            const inputId = `wam2-${slotId}-${param.id}`;
            const value = values[param.id] ?? param.defaultValue;
            return (
              <li key={param.id} className="flex flex-col gap-1">
                <label htmlFor={inputId} className="text-xs text-gray-300">
                  {param.label}
                </label>
                <div className="flex items-center gap-2">
                  <input
                    id={inputId}
                    type="range"
                    className="flex-1"
                    min={param.min}
                    max={param.max}
                    step={stepFor(param)}
                    value={value}
                    aria-valuetext={formatValue(param, value)}
                    onChange={(e) => setParam(param, Number(e.target.value))}
                  />
                  {/* Number input as well as the slider: a range input alone is
                      awkward for precise values with a keyboard or a screen reader. */}
                  <input
                    type="number"
                    className="w-20 rounded border border-gray-700 bg-gray-800 px-1 text-xs text-gray-100"
                    min={param.min}
                    max={param.max}
                    step={stepFor(param)}
                    value={drafts[param.id] ?? String(value)}
                    aria-label={`${param.label} value`}
                    onChange={(e) => {
                      const text = e.target.value;
                      setDrafts((prev) => ({ ...prev, [param.id]: text }));
                      const parsed = Number(text);
                      // Apply live only while the typed value is already legal;
                      // anything else waits for commit.
                      if (text !== '' && Number.isFinite(parsed) && parsed >= param.min && parsed <= param.max) {
                        setParam(param, parsed);
                      }
                    }}
                    onBlur={() => commitDraft(param)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') commitDraft(param);
                    }}
                  />
                  <button
                    type="button"
                    className="rounded border border-gray-700 px-2 py-1 text-xs text-gray-200 hover:bg-gray-800"
                    onClick={() => addAutomationLane(param)}
                  >
                    Automate
                  </button>
                </div>
              </li>
            );
          })}
        </ul>
      )}

      <div className="flex flex-col gap-2 border-t border-gray-800 pt-2">
        <div className="flex items-end gap-2">
          <div className="flex flex-1 flex-col gap-1">
            <label htmlFor={`wam2-${slotId}-preset-name`} className="text-xs text-gray-300">
              Preset name
            </label>
            <input
              id={`wam2-${slotId}-preset-name`}
              type="text"
              className="rounded border border-gray-700 bg-gray-800 px-2 py-1 text-xs text-gray-100"
              value={presetName}
              onChange={(e) => setPresetName(e.target.value)}
            />
          </div>
          <button
            type="button"
            className="rounded border border-gray-700 px-2 py-1 text-xs text-gray-200 hover:bg-gray-800"
            onClick={onSavePreset}
          >
            Save preset
          </button>
        </div>

        {presets.length > 0 && (
          <ul aria-label="Saved presets" className="flex list-none flex-col gap-1 p-0">
            {presets.map((preset) => (
              <li key={preset.name} className="flex items-center gap-2 text-xs">
                <span className="flex-1 truncate text-gray-300">{preset.name}</span>
                <button
                  type="button"
                  className="rounded border border-gray-700 px-2 py-0.5 text-gray-200 hover:bg-gray-800"
                  onClick={() => onLoadPreset(preset)}
                >
                  Load
                </button>
                <button
                  type="button"
                  className="rounded border border-gray-700 px-2 py-0.5 text-gray-200 hover:bg-gray-800"
                  onClick={() => onDeletePreset(preset)}
                >
                  Delete
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Polite, and only for discrete actions — param drags do not write here. */}
      <p role="status" className="min-h-[1rem] text-xs text-gray-400">
        {status}
      </p>
    </section>
  );
};

export default Wam2GenericEditor;

import React, { useRef, useEffect, memo } from 'react';
import type { AlignmentResult } from '../engines/rubberband/PhonemeAligner';

interface WaveformDisplayProps {
    buffer: AudioBuffer | null;
    alignment: AlignmentResult | null;
    sliceHighlightRef: React.MutableRefObject<((slice: number) => void) | null>;
    onAlignmentChange?: (alignment: AlignmentResult) => void;
    onAutoSlice?: () => void;
    autoSliceSensitivity?: number;
    onAutoSliceSensitivityChange?: (val: number) => void;
    onLoadSample?: () => void;
}

export const WaveformDisplay: React.FC<WaveformDisplayProps> = memo(({ buffer, alignment, sliceHighlightRef, onAlignmentChange, onAutoSlice, autoSliceSensitivity = 50, onAutoSliceSensitivityChange, onLoadSample }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    // ⚡ Bolt: Cache DOMRect to prevent forced synchronous layout
    const cachedCanvasRectRef = useRef<DOMRect | null>(null);
    const cachedContainerRectRef = useRef<DOMRect | null>(null);
    const activeSliceRef = useRef<number>(-1);

    // Custom Slicing State
    const [dragState, setDragState] = React.useState<{ index: number, isStart: boolean } | null>(null);
    const [hoverState, setHoverState] = React.useState<{ index: number, isStart: boolean } | null>(null);
