import React, { memo, useCallback, useEffect, useId, useRef, useState } from 'react';
import { getHelpTopic } from '../../content/helpTopics';
import { helpDiscoveryStore } from '../../stores/helpDiscoveryStore';

type HelpTipPosition = 'top' | 'bottom' | 'left' | 'right';

export interface HelpTipProps {
  /** Help topic id from helpTopics.ts */
  topicId: string;
  children: React.ReactElement;
  position?: HelpTipPosition;
  /** Show once until user interacts or dismisses. */
  showOnFirstUse?: boolean;
  className?: string;
}

const POSITION_CLASSES: Record<HelpTipPosition, string> = {
  top: 'bottom-full left-1/2 -translate-x-1/2 mb-2',
  bottom: 'top-full left-1/2 -translate-x-1/2 mt-2',
  left: 'right-full top-1/2 -translate-y-1/2 mr-2',
  right: 'left-full top-1/2 -translate-y-1/2 ml-2',
};

/**
 * Accessible contextual tooltip tied to the help topic catalog.
 * Visible on hover and keyboard focus; respects prefers-reduced-motion.
 */
export const HelpTip = memo(({
  topicId,
  children,
  position = 'top',
  showOnFirstUse = false,
  className = '',
}: HelpTipProps) => {
  const topic = getHelpTopic(topicId);
  const tipId = useId();
  const shouldPinFirstUse = () =>
    showOnFirstUse && !!topic && !helpDiscoveryStore.hasSeenTip(topicId);
  const [open, setOpen] = useState(shouldPinFirstUse);
  const [firstUsePinned, setFirstUsePinned] = useState(shouldPinFirstUse);
  const [firstUseKey, setFirstUseKey] = useState({ showOnFirstUse, topicId, hasTopic: !!topic });
  if (
    firstUseKey.showOnFirstUse !== showOnFirstUse ||
    firstUseKey.topicId !== topicId ||
    firstUseKey.hasTopic !== !!topic
  ) {
    setFirstUseKey({ showOnFirstUse, topicId, hasTopic: !!topic });
    if (shouldPinFirstUse()) {
      setFirstUsePinned(true);
      setOpen(true);
    }
  }
  const wrapRef = useRef<HTMLSpanElement>(null);

  const dismissFirstUse = useCallback(() => {
    helpDiscoveryStore.markTipSeen(topicId);
    setFirstUsePinned(false);
    setOpen(false);
  }, [topicId]);

  const openMore = useCallback(() => {
    dismissFirstUse();
    helpDiscoveryStore.openHelp({ tab: 'guides', topicId });
  }, [dismissFirstUse, topicId]);

  if (!topic) return children;

  const child = React.cloneElement(children, {
    'aria-describedby': open ? tipId : undefined,
    onFocus: (e: React.FocusEvent) => {
      (children.props as { onFocus?: (ev: React.FocusEvent) => void }).onFocus?.(e);
      setOpen(true);
    },
    onBlur: (e: React.FocusEvent) => {
      (children.props as { onBlur?: (ev: React.FocusEvent) => void }).onBlur?.(e);
      if (!firstUsePinned) setOpen(false);
    },
    onMouseEnter: (e: React.MouseEvent) => {
      (children.props as { onMouseEnter?: (ev: React.MouseEvent) => void }).onMouseEnter?.(e);
      setOpen(true);
    },
    onMouseLeave: (e: React.MouseEvent) => {
      (children.props as { onMouseLeave?: (ev: React.MouseEvent) => void }).onMouseLeave?.(e);
      if (!firstUsePinned) setOpen(false);
    },
  } as React.HTMLAttributes<HTMLElement>);

  return (
    <span
      ref={wrapRef}
      className={`relative inline-flex items-center ${className}`}
      onMouseLeave={() => { if (!firstUsePinned) setOpen(false); }}
    >
      {child}
      <span
        id={tipId}
        role="tooltip"
        className={`absolute z-[80] w-56 px-2.5 py-2 rounded-md border border-cyan-900/50 bg-zinc-950/95 text-[11px] text-gray-200 shadow-hyphon-panel pointer-events-auto motion-safe:transition-opacity motion-safe:duration-150 ${
          POSITION_CLASSES[position]
        } ${open ? 'opacity-100 visible' : 'opacity-0 invisible pointer-events-none'}`}
      >
        <span className="block font-bold text-cyan-300/90 mb-1">{topic.title}</span>
        <span className="block text-gray-400 leading-snug">{topic.summary}</span>
        <span className="mt-2 flex gap-2">
          <button
            type="button"
            onClick={openMore}
            className="text-[10px] font-bold text-cyan-400 hover:text-cyan-300 underline focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 rounded"
          >
            Learn more
          </button>
          {firstUsePinned && (
            <button
              type="button"
              onClick={dismissFirstUse}
              className="text-[10px] text-gray-500 hover:text-gray-300 focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500 rounded"
            >
              Dismiss
            </button>
          )}
        </span>
      </span>
    </span>
  );
});

