import React, { createContext, useContext } from 'react';
import { useAppState } from '../hooks/useAppState';

type AppState = ReturnType<typeof useAppState>;

const AppStateContext = createContext<AppState | undefined>(undefined);

/**
 * Provides the global application state (created once) to the entire tree.
 * Wrap the root of the app with this provider so that all sub-components
 * consume the same state instance via `useAppStateContext()`.
 */
export const AppStateProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const state = useAppState();
    return <AppStateContext.Provider value={state}>{children}</AppStateContext.Provider>;
};

/**
 * Consume the shared application state.
 * Must be used inside an `AppStateProvider`.
 */
export function useAppStateContext(): AppState {
    const ctx = useContext(AppStateContext);
    if (ctx === undefined) {
        throw new Error('useAppStateContext must be used within an AppStateProvider');
    }
    return ctx;
}

import React, { createContext, useContext } from 'react';
import { useCompactLayout, type CompactLayoutState } from '../hooks/useCompactLayout';

const CompactLayoutContext = createContext<CompactLayoutState | null>(null);

export function CompactLayoutProvider({ children }: { children: React.ReactNode }) {
    const value = useCompactLayout();
    return (
        <CompactLayoutContext.Provider value={value}>
            {children}
        </CompactLayoutContext.Provider>
    );
}

export function useCompactLayoutContext(): CompactLayoutState {
    const ctx = useContext(CompactLayoutContext);
    if (!ctx) {
        throw new Error('useCompactLayoutContext must be used within CompactLayoutProvider');
    }
    return ctx;
}

/** Safe fallback when provider is absent (tests / Storybook). */
export function useCompactLayoutOptional(): CompactLayoutState | null {
    return useContext(CompactLayoutContext);
}

declare module '*.wasm' {
  const init: (imports: WebAssembly.Imports) => Promise<WebAssembly.Instance>;
  export default init;
}

declare global {

  var hyphonPyodide: any;

  var hyphonPyodideReady: boolean;
}

export {};

/**
 * Drum Kit Engine
 *
 * Message façade for analog 808/909 drums. Live hits go to `drumkit-processor`
 * (hyphon_native `drumkit_*` handles). If the worklet/WASM path fails, the
 * existing Web Audio oscillator kit remains the fallback (HUD reason, non-silent).
 */

import type { KickParams, SnareParams, HatParams, DrumSound, DrumKitType } from '@/types';
import { KIT_CHARACTER, kitToNativeId, DRUMKIT_VOICE, type KitSynthCharacter } from './DrumKitCharacter';
import {
    engineTelemetry,
    isAppleWebKit,
    loadHyphonWasmExportMap,
    logEngineFallback,
    resolvePublicAsset,
} from '@/utils/engineTelemetry';
import {
    DRUMKIT_REQUIRED_WASM_EXPORTS,
    drumkitExportMapInsufficient,
    formatMissingWasmExports,
    HYPHON_NATIVE_MIN_MEMORY_PAGES,
    wasmExportNameSnapshot,
} from '@/audio-worklets/hyphonNativeImports';

const HYPHON_NATIVE_WASM_URL = resolvePublicAsset('hyphon_native.wasm');
const DRUMKIT_INIT_TIMEOUT_MS = 8000;

export class DrumKitEngine {
  private _kitType: DrumKitType;
  private _character: KitSynthCharacter;
  private workletNode: AudioWorkletNode | null = null;
  private audioContext: AudioContext | null = null;
  private wasmReady = false;
  private workletNodesCreated = 0;
  fallbackReason: string | null = null;

  constructor(kitType: DrumKitType = '808') {
    this._kitType = kitType;
    this._character = KIT_CHARACTER[kitType];
  }

  get kitType(): DrumKitType {
    return this._kitType;
  }

  /** True when hits are rendered inside the AudioWorklet (no per-hit OscillatorNode). */
  get isWorkletReady(): boolean {
    return this.wasmReady;
  }

  setKit(kitType: DrumKitType): void {
    this._kitType = kitType;
    this._character = KIT_CHARACTER[kitType];
    if (this.wasmReady && this.workletNode) {
      this.workletNode.port.postMessage({
        type: 'set-kit',
        data: { kit: kitToNativeId(kitType) },
      });
    }
  }

  /**
   * Load drumkit-processor and instantiate hyphon_native once for the whole kit.
   * Returns false when the Web Audio fallback should handle hits.
   */
  async init(
    audioContext: AudioContext,
    workletUrl: string,
    destination: AudioNode,
  ): Promise<boolean> {
    this.audioContext = audioContext;

    if (isAppleWebKit()) {
      this.useFallback('threaded hyphon_native.wasm is unsafe in WebKit AudioWorklet');
      return false;
    }

    if (!audioContext.audioWorklet || !workletUrl) {
      this.useFallback(
        !audioContext.audioWorklet ? 'AudioWorklet unavailable' : 'worklet URL missing',
      );
      return false;
    }

    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), DRUMKIT_INIT_TIMEOUT_MS);
      let response: Response;
      try {
        response = await fetch(HYPHON_NATIVE_WASM_URL, { signal: controller.signal });
      } finally {
        clearTimeout(timeoutId);
      }
      if (!response.ok) {
        this.useFallback(`hyphon_native.wasm fetch HTTP ${response.status} (${HYPHON_NATIVE_WASM_URL})`);
        return false;
      }
      const wasmBytes = await response.arrayBuffer();
      const exportMap = await this.fetchExportMap(wasmBytes);
      return this.initWithWasmBytes(audioContext, workletUrl, destination, wasmBytes, exportMap);
    } catch (e) {
      const aborted =
        (typeof DOMException !== 'undefined' && e instanceof DOMException && e.name === 'AbortError') ||
        (e instanceof Error && e.name === 'AbortError');
      this.useFallback(
        aborted
          ? `hyphon_native.wasm fetch timeout (${DRUMKIT_INIT_TIMEOUT_MS}ms)`
          : 'init exception before worklet load',
        aborted ? undefined : e,
      );
      return false;
    }
  }

  private async fetchExportMap(wasmBytes: ArrayBuffer): Promise<Record<string, string>> {
    const map = await loadHyphonWasmExportMap();
    const mapUrl = resolvePublicAsset('hyphon_wasm_export_map.json');
    const glueUrl = resolvePublicAsset('hyphon_native.js');
    const wasmModule = await WebAssembly.compile(wasmBytes);
    const rawExports = wasmExportNameSnapshot(wasmModule);

    if (Object.keys(map).length === 0) {
      logEngineFallback(
        'drumkit',
        'wasm-worklet',
        `hyphon_wasm_export_map.json empty and glue parse found no exports ` +
        `(tried ${mapUrl} and ${glueUrl}). ` +
        formatMissingWasmExports(rawExports, [...DRUMKIT_REQUIRED_WASM_EXPORTS]),
      );
      return map;
    }

    if (drumkitExportMapInsufficient(wasmModule, map)) {
      logEngineFallback(
        'drumkit',
        'wasm-worklet',
        `export map did not resolve drumkit_* against WASM. ` +
        formatMissingWasmExports(rawExports, [...DRUMKIT_REQUIRED_WASM_EXPORTS]),
      );
    }

    return map;
  }

  async initWithWasmBytes(
    audioContext: AudioContext,
    workletUrl: string,
    destination: AudioNode,
    wasmBytes: ArrayBuffer,
    exportMap: Record<string, string> = {},
  ): Promise<boolean> {
    try {
      await audioContext.audioWorklet.addModule(workletUrl);

      this.workletNode = new AudioWorkletNode(audioContext, 'drumkit-processor', {
        outputChannelCount: [2],
      });
      this.workletNodesCreated += 1;

      const module = await WebAssembly.compile(wasmBytes);
      const imports = WebAssembly.Module.imports(module);
      const isThreaded = imports.some((i) => i.kind === 'memory');
      const memoryPages = isThreaded ? HYPHON_NATIVE_MIN_MEMORY_PAGES : undefined;

      this.workletNode.port.postMessage({
        type: 'init-wasm',
        data: {
          wasmBytes,
          sampleRate: audioContext.sampleRate,
          isThreaded,
          variant: isThreaded ? 'threaded' : 'single',
          memoryPages,
          exportMap,
        },
      });

      this.workletNode.connect(destination);

      const initSuccess = await new Promise<boolean>((resolve) => {
        let readyReceived = false;
        this.workletNode!.port.onmessage = (e: MessageEvent<{ type?: string; error?: unknown }>) => {
          if (e.data.type === 'ready') {
            readyReceived = true;
            resolve(true);
          } else if (e.data.type === 'error') {
            const errDetail =
              typeof e.data.error === 'string'
                ? e.data.error
                : e.data.error != null
                  ? String(e.data.error)
                  : 'unknown worklet error';
            this.useFallback(`worklet init-wasm error: ${errDetail}`);
            resolve(false);
          }
        };
        setTimeout(() => {
          if (!readyReceived) {
            this.useFallback(`worklet ready timeout (${DRUMKIT_INIT_TIMEOUT_MS}ms)`);
            resolve(false);
          }
        }, DRUMKIT_INIT_TIMEOUT_MS);
      });

      if (!initSuccess) {
        this.cleanupWorklet();
        return false;
      }

      this.wasmReady = true;
      this.fallbackReason = null;
      this.workletNode.port.postMessage({
        type: 'set-kit',
        data: { kit: kitToNativeId(this._kitType) },
      });
      try {
        engineTelemetry.registerResolution('drumkit', 'wasm-worklet', 'worklet-ready heapCount=1');
      } catch {
        /* telemetry must never break audio */
      }
      return true;
    } catch (e) {
      this.useFallback('AudioWorklet.addModule or node creation failed', e);
      this.cleanupWorklet();
      return false;
    }
  }

  /**
   * Play a drum sound. Worklet path posts a trigger at `audioTime`; fallback
   * allocates Web Audio oscillators (legacy kit).
   */
  play(
    context: AudioContext,
    masterGain: GainNode,
    noiseBuffer: AudioBuffer | null,
    sound: DrumSound,
    params: KickParams | SnareParams | HatParams,
    time: number,
  ): void {
    if (this.wasmReady && this.workletNode) {
      this.triggerWorklet(sound, params, time);
      return;
    }
    this.playFallback(context, masterGain, noiseBuffer, sound, params, time);
  }

  /** Tests: how many AudioWorkletNodes this engine constructed. */
  get workletInstanceCount(): number {
    return this.workletNodesCreated;
  }

  private triggerWorklet(
    sound: DrumSound,
    params: KickParams | SnareParams | HatParams,
    audioTime: number,
  ): void {
    const voice = DRUMKIT_VOICE[sound];
    let a = 0;
    let b = 0;
    let c = 0;
    let d = 0;
    if (sound === 'kick') {
      const p = params as KickParams;
      a = p.pitch;
      b = p.decay;
      c = p.tone;
      d = p.volume;
    } else if (sound === 'snare') {
      const p = params as SnareParams;
      a = p.tone;
      b = p.decay;
      c = p.noise;
      d = p.volume;
    } else {
      const p = params as HatParams;
      a = p.pitch;
      b = p.decay;
      c = p.volume;
      d = 0;
    }
    this.workletNode!.port.postMessage({
      type: 'trigger',
      data: { voice, velocity: 1, a, b, c, d, audioTime },
    });
  }

  private useFallback(reason: string, err?: unknown): void {
    this.wasmReady = false;
    this.fallbackReason = reason;
    logEngineFallback('drumkit', 'wasm-worklet', reason, err);
  }

  /** Release the worklet node (engine re-init / teardown). */
  dispose(): void {
    this.cleanupWorklet();
    this.wasmReady = false;
  }

  private cleanupWorklet(): void {
    if (this.workletNode) {
      this.workletNode.disconnect();
      this.workletNode.port.close();
      this.workletNode = null;
    }
  }

  private playFallback(
    context: AudioContext,
    masterGain: GainNode,
    noiseBuffer: AudioBuffer | null,
    sound: DrumSound,
    params: KickParams | SnareParams | HatParams,
    time: number,
  ): void {
    switch (sound) {
      case 'kick':
        this.playKick(context, masterGain, params as KickParams, time);
        break;
      case 'snare':
        this.playSnare(context, masterGain, noiseBuffer, params as SnareParams, time);
        break;
      case 'closedHat':
      case 'openHat':
        this.playHat(context, masterGain, noiseBuffer, params as HatParams, time);
        break;
    }
  }

  private playKick(context: AudioContext, masterGain: GainNode, params: KickParams, time: number): void {
    const c = this._character;
    const osc = context.createOscillator();
    const gain = context.createGain();

    osc.type = c.kickWaveform;

    const startFreq = params.pitch * c.kickFreqStart * 3;
    const endFreq = Math.max(0.01, params.pitch * c.kickFreqEnd);
    const sweepTime = params.decay * c.kickPitchCurve;

    osc.frequency.setValueAtTime(startFreq, time);
    osc.frequency.exponentialRampToValueAtTime(endFreq, time + sweepTime);

    const clickLevel = params.tone * 0.3;
    gain.gain.setValueAtTime(params.volume + clickLevel, time);
    gain.gain.setValueAtTime(params.volume, time + 0.005);
    gain.gain.exponentialRampToValueAtTime(0.001, time + params.decay);

    osc.connect(gain);
    gain.connect(masterGain);

    osc.start(time);
    osc.stop(time + params.decay + 0.01);
  }

  private playSnare(
    context: AudioContext,
    masterGain: GainNode,
    noiseBuffer: AudioBuffer | null,
    params: SnareParams,
    time: number,
  ): void {
    const c = this._character;

    const osc = context.createOscillator();
    const oscGain = context.createGain();
    osc.type = c.snareWaveform;
    osc.frequency.setValueAtTime(params.tone, time);
    osc.frequency.exponentialRampToValueAtTime(params.tone * 0.5, time + params.decay * 0.3);

    const toneLevel = params.volume * 0.6;
    oscGain.gain.setValueAtTime(toneLevel, time);
    oscGain.gain.exponentialRampToValueAtTime(0.001, time + params.decay * 0.5);

    osc.connect(oscGain);
    oscGain.connect(masterGain);
    osc.start(time);
    osc.stop(time + params.decay + 0.01);

    if (noiseBuffer) {
      const noise = context.createBufferSource();
      noise.buffer = noiseBuffer;

      const noiseFilter = context.createBiquadFilter();
      noiseFilter.type = 'bandpass';
      noiseFilter.frequency.value = c.snareNoiseFreq;
      noiseFilter.Q.value = c.snareNoiseQ;

      const noiseGain = context.createGain();
      const noiseLevel = Math.min(1.0, params.noise / 5000) * params.volume;
      noiseGain.gain.setValueAtTime(noiseLevel, time);
      noiseGain.gain.exponentialRampToValueAtTime(0.001, time + params.decay);

      noise.connect(noiseFilter);
      noiseFilter.connect(noiseGain);
      noiseGain.connect(masterGain);
      noise.start(time);
      noise.stop(time + params.decay + 0.01);
    }
  }

  private playHat(
    context: AudioContext,
    masterGain: GainNode,
    noiseBuffer: AudioBuffer | null,
    params: HatParams,
    time: number,
  ): void {
    const c = this._character;

    if (noiseBuffer) {
      const src = context.createBufferSource();
      src.buffer = noiseBuffer;

      const hpFilter = context.createBiquadFilter();
      hpFilter.type = 'highpass';
      hpFilter.frequency.value = params.pitch;
      hpFilter.Q.value = c.hatResonance;

      const bpFilter = context.createBiquadFilter();
      bpFilter.type = 'bandpass';
      bpFilter.frequency.value = params.pitch * 1.5;
      bpFilter.Q.value = c.hatResonance * 0.5;

      const gain = context.createGain();
      gain.gain.setValueAtTime(params.volume, time);
      gain.gain.exponentialRampToValueAtTime(0.001, time + params.decay);

      src.connect(hpFilter);
      hpFilter.connect(bpFilter);
      bpFilter.connect(gain);
      gain.connect(masterGain);
      src.start(time);
      src.stop(time + params.decay + 0.01);
    }
  }
}

/**
 * FallbackBassSynth - Simple TB-303-style bass synth
 * 
 * Used when the JC-303 WASM fails to load due to stack overflow.
 * Provides similar sound characteristics using standard Web Audio API.
 */

type BassOscillatorNode = OscillatorNode & { envGain?: GainNode };

function createStubBiquadFilter(): BiquadFilterNode {
    return {
        type: 'lowpass',
        frequency: {
            value: 1000,
            cancelScheduledValues: () => {},
            setValueAtTime: () => {},
            setTargetAtTime: () => {},
        },
        Q: { value: 10 },
        connect: () => {},
        disconnect: () => {},
    } as unknown as BiquadFilterNode;
}

function createStubOscillator(): BassOscillatorNode {
    return {
        type: 'sawtooth',
        frequency: { value: 440, setTargetAtTime: () => {} },
        start: () => {},
        stop: () => {},
        connect: () => {},
        disconnect: () => {},
    } as unknown as BassOscillatorNode;
}

function createStubGain(): GainNode {
    return {
        gain: {
            value: 0,
            setTargetAtTime: () => {},
            cancelScheduledValues: () => {},
        },
        connect: () => {},
        disconnect: () => {},
    } as unknown as GainNode;
}

export class FallbackBassSynth {
    private audioContext: AudioContext;
    private outputNode: GainNode;
    private filterNode: BiquadFilterNode;
    private currentOscillator: BassOscillatorNode | null = null;
    private currentNote: number = -1;
    // private filterEnvAmount: number = 0; // Reserved for future filter envelope
    private isSlide: boolean = false;

    // Parameters (0-1 range, matching Open303 interface)
    private params = {
        waveform: 1.0,      // 0 = saw, 1 = square
        cutoff: 0.3,        // Filter cutoff (0-1)
        resonance: 0.5,     // Filter resonance (0-1)
        decay: 0.3,         // Envelope decay (0-1)
        envMod: 0.5,        // Envelope amount (0-1)
        accent: 0.5,        // Accent amount (0-1)
        volume: 0.75        // Output volume (0-1)
    };

    constructor(audioContext: AudioContext) {
        this.audioContext = audioContext;

        // Create filter
        this.filterNode = typeof audioContext.createBiquadFilter === 'function'
            ? audioContext.createBiquadFilter()
            : createStubBiquadFilter();
        this.filterNode.type = 'lowpass';
        this.filterNode.frequency.value = 1000;
        this.filterNode.Q.value = 10;

        // Create output
        this.outputNode = audioContext.createGain();
        this.outputNode.gain.value = 0.5;

        // Connect
        this.filterNode.connect(this.outputNode);
    }

    connect(destination: AudioNode): void {
        this.outputNode.connect(destination);
    }

    disconnect(): void {
        this.outputNode.disconnect();
    }

    setWaveform(value: number): void {
        this.params.waveform = value;
        if (this.currentOscillator) {
            this.currentOscillator.type = value > 0.5 ? 'square' : 'sawtooth';
        }
    }

    setCutoff(value: number): void {
        this.params.cutoff = value;
        // Map 0-1 to 100-5000 Hz
        this.filterNode.frequency.value = 100 + value * 4900;
    }

    setResonance(value: number): void {
        this.params.resonance = value;
        // Map 0-1 to Q of 0-20
        this.filterNode.Q.value = value * 20;
    }

    setDecay(value: number): void {
        this.params.decay = value;
    }

    setEnvMod(value: number): void {
        this.params.envMod = value;
    }

    setAccent(value: number): void {
        this.params.accent = value;
    }

    setVolume(value: number): void {
        this.params.volume = value;
        this.outputNode.gain.value = value * 0.5;
    }

    noteOn(midiNote: number, velocity: number = 100): void {
        const now = this.audioContext.currentTime;
        const freq = 440 * Math.pow(2, (midiNote - 69) / 12);

        // Determine if this is an accented note
        const isAccent = velocity > 100;
        const accentBoost = isAccent ? this.params.accent : 0;

        // Release previous note
        if (this.currentOscillator) {
            if (this.isSlide) {
                // Slide mode - don't cut off, just change frequency
                this.currentOscillator.frequency.setTargetAtTime(freq, now, 0.06);
            } else {
                // Normal mode - quick release then new note
                this.releaseNote(now);
            }
        }

        if (!this.isSlide || !this.currentOscillator) {
            // Create new oscillator
            const osc: BassOscillatorNode = typeof this.audioContext.createOscillator === 'function'
                ? (this.audioContext.createOscillator() as BassOscillatorNode)
                : createStubOscillator();
            osc.type = this.params.waveform > 0.5 ? 'square' : 'sawtooth';
            osc.frequency.value = freq;

            // Create envelope gain
            const envGain = typeof this.audioContext.createGain === 'function'
                ? this.audioContext.createGain()
                : createStubGain();
            envGain.gain.value = 0;

            // Connect
            osc.connect(envGain);
            envGain.connect(this.filterNode);

            // Start
            osc.start(now);

            // Attack
            const attackTime = 0.005;
            const initialLevel = 0.3 + accentBoost * 0.4;
            envGain.gain.setTargetAtTime(initialLevel, now, attackTime);

            // Decay
            const decayTime = 0.1 + this.params.decay * 0.5;
            envGain.gain.setTargetAtTime(0.1, now + attackTime, decayTime * 0.3);

            // Filter envelope
            const baseFreq = 100 + this.params.cutoff * 4900;
            const envAmount = this.params.envMod * 3000;
            const peakFreq = Math.min(20000, baseFreq + envAmount * (1 + accentBoost));

            this.filterNode.frequency.cancelScheduledValues(now);
            this.filterNode.frequency.setValueAtTime(baseFreq, now);
            this.filterNode.frequency.setTargetAtTime(peakFreq, now, attackTime);
            this.filterNode.frequency.setTargetAtTime(baseFreq, now + attackTime, decayTime * 0.4);

            this.currentOscillator = osc;
            this.currentNote = midiNote;

            // Store envelope gain for release
            osc.envGain = envGain;
        }
    }

    noteOff(midiNote: number): void {
        if (this.currentNote === midiNote) {
            this.releaseNote(this.audioContext.currentTime);
        }
    }

    private releaseNote(time: number): void {
        if (!this.currentOscillator) return;

        const osc = this.currentOscillator;
        const envGain = osc.envGain;

        if (envGain) {
            // Quick release
            envGain.gain.cancelScheduledValues(time);
            envGain.gain.setTargetAtTime(0, time, 0.05);
        }

        // Stop after release
        const stopTime = time + 0.1;
        try {
            osc.stop(stopTime);
        } catch (e) {
            // Ignore if already stopped
        }

        // Cleanup
        setTimeout(() => {
            try {
                osc.disconnect();
                envGain?.disconnect();
            } catch (e) {
                // Ignore cleanup errors
            }
        }, 200);

        this.currentOscillator = null;
        this.currentNote = -1;
    }

    allNotesOff(): void {
        this.releaseNote(this.audioContext.currentTime);
    }

    cleanup(): void {
        this.allNotesOff();
        this.outputNode.disconnect();
    }
}

export default FallbackBassSynth;

import type { Bass2Params } from '../types';
import type { TB303ModelId } from './TB303Models';
import type { TB303VoiceExtra } from './tb303VoiceExtra';
import type { HighFidCoefficients } from '../audio-worklets/liveHighFidCoefficients';
import type { LiveAbSettings } from './LiveHighFidAbPair';
import { Open303Oscillator } from './Open303Oscillator';
import { engineTelemetry, logEngineFallback } from '../utils/engineTelemetry';
import type { Open303Config } from './Open303Params';
import { makeDistortionCurve } from '../hooks/audioEngine/distortion';

/**
 * Manages three Open303 (TB-303) instances for independent synth tracks
 * - bass1: Used by partB (SYNTH B // BASS)
 * - bass2: Independent second bass track
 * - lead303: Used by partA (SYNTH A // LEAD) when a 303 waveform is selected
 */
export class Open303Manager {
    private bass1: Open303Oscillator | null = null;
    private bass2: Open303Oscillator | null = null;
    private lead303: Open303Oscillator | null = null;
    private audioContext: AudioContext | null = null;
    private workletUrl: string | undefined;

    // Mixer nodes for independent routing
    private bass1Gain: GainNode | null = null;
    private bass2Gain: GainNode | null = null;
    private lead303Gain: GainNode | null = null;
    private bass1Drive: WaveShaperNode | null = null;
    private bass2Drive: WaveShaperNode | null = null;
    private lead303Drive: WaveShaperNode | null = null;

    // Drive routing gains
    private bass1DryGain: GainNode | null = null;
    private bass1WetGain: GainNode | null = null;
    private bass2DryGain: GainNode | null = null;
    private bass2WetGain: GainNode | null = null;
    private lead303DryGain: GainNode | null = null;
    private lead303WetGain: GainNode | null = null;
    private bass1Panner: StereoPannerNode | null = null;
    private bass2Panner: StereoPannerNode | null = null;
    private lead303Panner: StereoPannerNode | null = null;

    // State tracking
    public isReady: boolean = false;
    private bass1Ready: boolean = false;
    private bass2Ready: boolean = false;
    private lead303Ready: boolean = false;

    /**
     * Initialize both Open303 instances
     */
    async init(
        audioContext: AudioContext, 
        workletUrl?: string, 
        config?: Open303Config
    ): Promise<boolean> {
        this.audioContext = audioContext;
        this.workletUrl = workletUrl;

        try {
            // Create mixer nodes for independent routing
            this.bass1Gain = audioContext.createGain();
            this.bass1Gain.gain.value = 1.0;

            this.bass2Gain = audioContext.createGain();
            this.bass2Gain.gain.value = 1.0;

            this.lead303Gain = audioContext.createGain();
            this.lead303Gain.gain.value = 1.0;

            // Create panners for stereo positioning
            if (audioContext.createStereoPanner) {
                this.bass1Panner = audioContext.createStereoPanner();
                this.bass1Panner.pan.value = -0.2; // Slightly left
                this.bass1Gain.connect(this.bass1Panner);

                this.bass2Panner = audioContext.createStereoPanner();
                this.bass2Panner.pan.value = 0.2; // Slightly right
                this.bass2Gain.connect(this.bass2Panner);

                this.lead303Panner = audioContext.createStereoPanner();
                this.lead303Panner.pan.value = 0.0; // Centre (LEAD)
                this.lead303Gain.connect(this.lead303Panner);
            }


            this.bass1DryGain = audioContext.createGain();
            this.bass1WetGain = audioContext.createGain();
            this.bass1DryGain.gain.value = 1.0;
            this.bass1WetGain.gain.value = 0.0;
            this.bass1Drive = audioContext.createWaveShaper();
            this.bass1Drive.curve = makeDistortionCurve(100); // Fixed curve
            this.bass1DryGain.connect(this.bass1Gain);
            this.bass1WetGain.connect(this.bass1Drive);
            this.bass1Drive.connect(this.bass1Gain);

            this.bass2DryGain = audioContext.createGain();
            this.bass2WetGain = audioContext.createGain();
            this.bass2DryGain.gain.value = 1.0;
            this.bass2WetGain.gain.value = 0.0;
            this.bass2Drive = audioContext.createWaveShaper();
            this.bass2Drive.curve = makeDistortionCurve(100); // Fixed curve
            this.bass2DryGain.connect(this.bass2Gain);
            this.bass2WetGain.connect(this.bass2Drive);
            this.bass2Drive.connect(this.bass2Gain);

            this.lead303DryGain = audioContext.createGain();
            this.lead303WetGain = audioContext.createGain();
            this.lead303DryGain.gain.value = 1.0;
            this.lead303WetGain.gain.value = 0.0;
            this.lead303Drive = audioContext.createWaveShaper();
            this.lead303Drive.curve = makeDistortionCurve(100); // Fixed curve
            this.lead303DryGain.connect(this.lead303Gain);
            this.lead303WetGain.connect(this.lead303Drive);
            this.lead303Drive.connect(this.lead303Gain);

            // Initialize bass1, bass2 and lead303 in parallel — the browser dedupes
            // the addModule call for the same URL so all three share one worklet load.
            this.bass1 = new Open303Oscillator();
            this.bass2 = new Open303Oscillator();
            this.lead303 = new Open303Oscillator();
            // Pass the caller's config through untouched: the three voices share one
            // hyphon_native instance, and the profile it loads is decided from this.
            const initConfig = config;
            const results = await Promise.allSettled([
                this.bass1.init(audioContext, workletUrl, initConfig),
                this.bass2.init(audioContext, workletUrl, initConfig),
                this.lead303.init(audioContext, workletUrl, initConfig),
            ]);
            this.bass1Ready = results[0].status === 'fulfilled' ? results[0].value : false;
            this.bass2Ready = results[1].status === 'fulfilled' ? results[1].value : false;
            this.lead303Ready = results[2].status === 'fulfilled' ? results[2].value : false;

            if (!this.lead303Ready) {
                logEngineFallback('open303', 'wasm-worklet', 'lead303 voice failed to initialise');
            }
            if (!this.bass1Ready) {
                logEngineFallback('open303', 'wasm-worklet', 'bass1 (SYNTH B) voice failed to initialise');
            }
            if (!this.bass2Ready) {
                logEngineFallback('open303', 'wasm-worklet', 'bass2 voice failed to initialise');
            }

            if (this.bass1Ready) {
                this.bass1!.connect(this.bass1DryGain!);
                this.bass1!.connect(this.bass1WetGain!);
            }
            if (this.bass2Ready) {
                this.bass2!.connect(this.bass2DryGain!);
                this.bass2!.connect(this.bass2WetGain!);
            }
            if (this.lead303Ready) {
                this.lead303!.connect(this.lead303DryGain!);
                this.lead303!.connect(this.lead303WetGain!);
            }

            this.isReady = this.bass1Ready || this.bass2Ready || this.lead303Ready;

            if (this.isReady) {
                console.log('[Open303Manager] Triple 303 instances initialized:', {
                    bass1: this.bass1Ready,
                    bass2: this.bass2Ready,
                    lead303: this.lead303Ready,
                });
                try {
                    const b1 = this.bass1?.isFallback ? 'js' : (this.bass1Ready ? 'wasm' : 'none');
                    const b2 = this.bass2?.isFallback ? 'js' : (this.bass2Ready ? 'wasm' : 'none');
                    const lead = this.lead303?.isFallback ? 'js' : (this.lead303Ready ? 'wasm' : 'none');
                    let backend = 'none';
                    if (b1 === b2 && b2 === lead) backend = b1;
                    else backend = 'mixed';
                    engineTelemetry.registerResolution('jc303', backend, `bass1:${b1},bass2:${b2},lead303:${lead}`);
                } catch (_) {}
            }

            return this.isReady;

        } catch (e) {
            logEngineFallback('open303', 'wasm-worklet', 'Open303Manager initialization threw', e);
            this.isReady = false;
            return false;
        }
    }

    /**
     * Connect all three instances to a destination
     */
    connect(dest: AudioNode): void {
        if (this.bass1Panner) {
            this.bass1Panner.connect(dest);
        } else if (this.bass1Gain) {
            this.bass1Gain.connect(dest);
        }

        if (this.bass2Panner) {
            this.bass2Panner.connect(dest);
        } else if (this.bass2Gain) {
            this.bass2Gain.connect(dest);
        }

        if (this.lead303Panner) {
            this.lead303Panner.connect(dest);
        } else if (this.lead303Gain) {
            this.lead303Gain.connect(dest);
        }
    }

    /**
     * Disconnect from all destinations
     */
    disconnect(): void {
        if (this.bass1Panner) {
            this.bass1Panner.disconnect();
        }
        if (this.bass2Panner) {
            this.bass2Panner.disconnect();
        }
        if (this.lead303Panner) {
            this.lead303Panner.disconnect();
        }
    }

    /**
     * Apply parameters to bass1 (used by partB)
     */
    applyBass1Params(params: { filterCutoff: number; filterResonance: number; filterMode?: number; decay: number; volume: number; pan?: number }, waveform: 'saw' | 'sqr'): void {
        if (!this.bass1Ready || !this.bass1) return;

        this.bass1.setWaveform(waveform === 'sqr' ? 1.0 : 0.0);
        this.bass1.setCutoff(Math.max(0, Math.min(1, params.filterCutoff / 8000)));
        this.bass1.setResonance(Math.max(0, Math.min(1, params.filterResonance / 20)));
        this.bass1.setFilterMode(Math.max(0, Math.min(1, params.filterMode ?? 0)));
        this.bass1.setDecay(Math.max(0, Math.min(1, params.decay)));
        this.bass1.setVolume(params.volume);

        if (params.pan !== undefined) {
            this.setBass1Pan(params.pan);
        }
    }

    /**
     * Apply parameters to bass2 (independent bass track)
     */
    applyBass2Params(params: Bass2Params): void {
        if (!this.bass2Ready || !this.bass2) return;

        this.bass2.setWaveform(params.waveform === '303-sqr' ? 1.0 : 0.0);
        this.bass2.setCutoff(Math.max(0, Math.min(1, params.cutoff / 8000)));
        this.bass2.setResonance(Math.max(0, Math.min(1, params.resonance / 20)));
        this.bass2.setFilterMode(Math.max(0, Math.min(1, params.filterMode)));
        this.bass2.setDecay(Math.max(0, Math.min(1, params.decay)));
        this.bass2.setAccent(params.accent);
        this.bass2.setEnvMod(params.envMod);
        this.bass2.setVolume(params.volume);

        if (params.pan !== undefined) {
            this.setBass2Pan(params.pan);
        }
    }

    /**
     * Apply parameters to lead303 (used by partA / SYNTH A LEAD).
     * Shares the same SynthParams shape as applyBass1Params.
     */
    applyLead303Params(params: { filterCutoff: number; filterResonance: number; filterMode?: number; decay: number; volume: number; pan?: number }, waveform: 'saw' | 'sqr'): void {
        if (!this.lead303Ready || !this.lead303) return;

        this.lead303.setWaveform(waveform === 'sqr' ? 1.0 : 0.0);
        this.lead303.setCutoff(Math.max(0, Math.min(1, params.filterCutoff / 8000)));
        this.lead303.setResonance(Math.max(0, Math.min(1, params.filterResonance / 20)));
        this.lead303.setFilterMode(Math.max(0, Math.min(1, params.filterMode ?? 0)));
        this.lead303.setDecay(Math.max(0, Math.min(1, params.decay)));
        this.lead303.setVolume(params.volume);

        if (params.pan !== undefined) {
            this.setLead303Pan(params.pan);
        }
    }

    setBass1Drive(amount: number, audioTime?: number): void {
        if (this.bass1DryGain && this.bass1WetGain && this.audioContext) {
            const time = Math.max(this.audioContext.currentTime, audioTime ?? 0);
            this.bass1WetGain.gain.setValueAtTime(amount, time);
            this.bass1DryGain.gain.setValueAtTime(1.0 - amount, time);
        }
    }

    setBass2Drive(amount: number, audioTime?: number): void {
        if (this.bass2DryGain && this.bass2WetGain && this.audioContext) {
            const time = Math.max(this.audioContext.currentTime, audioTime ?? 0);
            this.bass2WetGain.gain.setValueAtTime(amount, time);
            this.bass2DryGain.gain.setValueAtTime(1.0 - amount, time);
        }
    }

    setLead303Drive(amount: number, audioTime?: number): void {
        if (this.lead303DryGain && this.lead303WetGain && this.audioContext) {
            const time = Math.max(this.audioContext.currentTime, audioTime ?? 0);
            this.lead303WetGain.gain.setValueAtTime(amount, time);
            this.lead303DryGain.gain.setValueAtTime(1.0 - amount, time);
        }
    }

    /**
     * Trigger note on bass1
     */
    noteOnBass1(midiNote: number, velocity: number = 100, audioTime?: number): void {
        if (this.bass1Ready && this.bass1) {
            this.bass1.noteOn(midiNote, velocity, audioTime);
        }
    }

    /**
     * Release note on bass1
     */
    noteOffBass1(midiNote: number, audioTime?: number): void {
        if (this.bass1Ready && this.bass1) {
            this.bass1.noteOff(midiNote, audioTime);
        }
    }

    /**
     * Trigger note on bass2
     */
    noteOnBass2(midiNote: number, velocity: number = 100, audioTime?: number): void {
        if (this.bass2Ready && this.bass2) {
            this.bass2.noteOn(midiNote, velocity, audioTime);
        }
    }

    /**
     * Release note on bass2
     */
    noteOffBass2(midiNote: number, audioTime?: number): void {
        if (this.bass2Ready && this.bass2) {
            this.bass2.noteOff(midiNote, audioTime);
        }
    }

    /**
     * Trigger note on lead303 (partA / SYNTH A LEAD)
     */
    noteOnLead303(midiNote: number, velocity: number = 100, audioTime?: number): void {
        if (this.lead303Ready && this.lead303) {
            this.lead303.noteOn(midiNote, velocity, audioTime);
        }
    }

    /**
     * Release note on lead303 (partA / SYNTH A LEAD)
     */
    noteOffLead303(midiNote: number, audioTime?: number): void {
        if (this.lead303Ready && this.lead303) {
            this.lead303.noteOff(midiNote, audioTime);
        }
    }

    /**
     * Set bass1 volume (mixer)
     */
    setBass1Volume(volume: number): void {
        if (this.bass1Gain) {
            this.bass1Gain.gain.setValueAtTime(volume, this.audioContext?.currentTime || 0);
        }
    }

    /**
     * Set bass2 volume (mixer)
     */
    setBass2Volume(volume: number): void {
        if (this.bass2Gain) {
            this.bass2Gain.gain.setValueAtTime(volume, this.audioContext?.currentTime || 0);
        }
    }

    /**
     * Set lead303 volume (mixer)
     */
    setLead303Volume(volume: number): void {
        if (this.lead303Gain) {
            this.lead303Gain.gain.setValueAtTime(volume, this.audioContext?.currentTime || 0);
        }
    }

    /**
     * Set bass1 pan (mixer)
     */
    setBass1Pan(pan: number): void {
        if (this.bass1Panner) {
            this.bass1Panner.pan.setValueAtTime(pan, this.audioContext?.currentTime || 0);
        }
    }

    /**
     * Set bass2 pan (mixer)
     */
    setBass2Pan(pan: number): void {
        if (this.bass2Panner) {
            this.bass2Panner.pan.setValueAtTime(pan, this.audioContext?.currentTime || 0);
        }
    }

    /**
     * Set lead303 pan (mixer)
     */
    setLead303Pan(pan: number): void {
        if (this.lead303Panner) {
            this.lead303Panner.pan.setValueAtTime(pan, this.audioContext?.currentTime || 0);
        }
    }

    /**
     * Mute/unmute bass1
     */
    setBass1Mute(muted: boolean): void {
        if (this.bass1Gain) {
            this.bass1Gain.gain.setValueAtTime(muted ? 0 : 1, this.audioContext?.currentTime || 0);
        }
    }

    /**
     * Mute/unmute bass2
     */
    setBass2Mute(muted: boolean): void {
        if (this.bass2Gain) {
            this.bass2Gain.gain.setValueAtTime(muted ? 0 : 1, this.audioContext?.currentTime || 0);
        }
    }

    /**
     * Mute/unmute lead303
     */
    setLead303Mute(muted: boolean): void {
        if (this.lead303Gain) {
            this.lead303Gain.gain.setValueAtTime(muted ? 0 : 1, this.audioContext?.currentTime || 0);
        }
    }

    /**
     * Solo bass1 (mute bass2)
     */
    soloBass1(): void {
        this.setBass1Mute(false);
        this.setBass2Mute(true);
    }

    /**
     * Solo bass2 (mute bass1)
     */
    soloBass2(): void {
        this.setBass1Mute(true);
        this.setBass2Mute(false);
    }

    /**
     * Clear solo (unmute both)
     */
    clearSolo(): void {
        this.setBass1Mute(false);
        this.setBass2Mute(false);
    }

    // ---- Open303Oscillator-compatible API (delegates to bass1) ----
    // synthPlayback.ts calls these via the Open303Oscillator interface. Routing
    // them to bass1 keeps the live-play and sequencer paths consistent.
    setWaveform(v: number) { this.bass1?.setWaveform(v); }
    setCutoff(v: number) { this.bass1?.setCutoff(v); }
    setResonance(v: number) { this.bass1?.setResonance(v); }
    setFilterMode(v: number) { this.bass1?.setFilterMode(v); }
    setDecay(v: number) { this.bass1?.setDecay(v); }
    setEnvMod(v: number) { this.bass1?.setEnvMod(v); }
    setAccent(v: number) { this.bass1?.setAccent(v); }
    setVolume(v: number) { this.bass1?.setVolume(v); }
    noteOn(note: number, velocity: number = 100, audioTime?: number) { this.noteOnBass1(note, velocity, audioTime); }
    noteOff(note: number, audioTime?: number) { this.noteOffBass1(note, audioTime); }

    /**
     * Get bass1 ready state
     */
    isBass1Ready(): boolean {
        return this.bass1Ready;
    }

    /**
     * Get bass2 ready state
     */
    isBass2Ready(): boolean {
        return this.bass2Ready;
    }

    /**
     * Get lead303 ready state (partA / SYNTH A LEAD)
     */
    isLead303Ready(): boolean {
        return this.lead303Ready;
    }

    /**
     * Cleanup all three instances
     */
    cleanup(): void {
        this.bass1?.cleanup();
        this.bass2?.cleanup();
        this.lead303?.cleanup();

        if (this.bass1Drive) {
            this.bass1Drive.disconnect();
            this.bass1Drive = null;
        }
        if (this.bass2Drive) {
            this.bass2Drive.disconnect();
            this.bass2Drive = null;
        }
        if (this.lead303Drive) {
            this.lead303Drive.disconnect();
            this.lead303Drive = null;
        }

        if (this.bass1Gain) {
            this.bass1Gain.disconnect();
            this.bass1Gain = null;
        }
        if (this.bass2Gain) {
            this.bass2Gain.disconnect();
            this.bass2Gain = null;
        }
        if (this.lead303Gain) {
            this.lead303Gain.disconnect();
            this.lead303Gain = null;
        }
        if (this.bass1Panner) {
            this.bass1Panner.disconnect();
            this.bass1Panner = null;
        }
        if (this.bass2Panner) {
            this.bass2Panner.disconnect();
            this.bass2Panner = null;
        }
        if (this.lead303Panner) {
            this.lead303Panner.disconnect();
            this.lead303Panner = null;
        }

        this.bass1 = null;
        this.bass2 = null;
        this.lead303 = null;
        this.isReady = false;
        this.bass1Ready = false;
        this.bass2Ready = false;
        this.lead303Ready = false;
    }

    // -------------------------------------------------------------------------
    // Scheduled parameter API (used by AutomationScheduler)
    // -------------------------------------------------------------------------

    /**
     * Send a parameter change to an Open303 voice instance at the given
     * AudioContext time.
     *
     * Because Open303 params are driven through AudioWorklet `postMessage`
     * rather than native AudioParams, sample-accurate scheduling is not
     * directly available.  This method fires the postMessage at the correct
     * wall-clock time (derived from the AudioContext clock) so that the
     * worklet receives the update with minimal jitter.
     *
     * For pan/gain nodes that do have native AudioParams, this delegates to
     * the appropriate `setValueAtTime` call instead.
     *
     * @param voice     Which 303 instance to target ('bass1' | 'bass2' | 'lead303').
     * @param func      Setter name (e.g. 'setCutoff', 'setResonance', 'setDecay').
     * @param value     Normalised 0–1 value.
     * @param audioTime AudioContext time at which the change should take effect.
     *                  Pass `audioContext.currentTime` for an immediate change.
     */
    scheduleParamAtTime(
        voice: 'bass1' | 'bass2' | 'lead303',
        func: string,
        value: number,
        audioTime: number
    ): void {
        // Live A/B blend (Phase L2) — a pair of GainNodes inside the oscillator.
        if (func === 'setAbMix') {
            this.getVoice(voice)?.setLiveAbMix(value, audioTime);
            return;
        }
        // Native AudioParam setters (pan, gain) — schedule ahead of time.
        if (func === 'setDrive') {
            if (voice === 'bass1') this.setBass1Drive(value, audioTime);
            else if (voice === 'bass2') this.setBass2Drive(value, audioTime);
            else this.setLead303Drive(value, audioTime);
            return;
        }
        if (func === 'setPan') {
            const panner =
                voice === 'bass1' ? this.bass1Panner :
                voice === 'bass2' ? this.bass2Panner :
                this.lead303Panner;
            if (panner && this.audioContext) {
                panner.pan.setValueAtTime(value, Math.max(this.audioContext.currentTime, audioTime));
            }
            return;
        }
        if (func === 'setVolume') {
            const gain =
                voice === 'bass1' ? this.bass1Gain :
                voice === 'bass2' ? this.bass2Gain :
                this.lead303Gain;
            if (gain && this.audioContext) {
                gain.gain.setValueAtTime(value, Math.max(this.audioContext.currentTime, audioTime));
            }
            // Also forward to the worklet so its internal gain state stays consistent with the GainNode.
        }

        // Worklet-routed params: postMessage with audioTime to be handled by the worklet.
        const osc =
            voice === 'bass1' ? this.bass1 :
            voice === 'bass2' ? this.bass2 :
            this.lead303;
        if (!osc) return;

        osc.setParam(func, value, audioTime);
    }

    /**
     * Schedule per-step slide (portamento/legato) enable or disable at the
     * given AudioContext time.
     *
     * On authentic TB-303 hardware, when a step has the slide flag set, the
     * oscillator glides from the previous pitch to the new one rather than
     * re-triggering the envelope.  The Open303 / jc303 engines model this
     * internally via a slide detector that is primed by the note-triggering
     * sequence — a legato noteOn (without a preceding noteOff) activates the
     * portamento path.
     *
     * This method establishes the API contract used by AutomationScheduler so
     * that slide automation lanes generated from per-step RBS data can flow
     * through the same scheduling pipeline as all other parameter changes.
     *
     * @param voice      Which 303 voice to target.
     * @param enabled    `true` = slide is active for the upcoming note.
     * @param audioTime  AudioContext time at which the change should take
     *                   effect.  Pass `audioContext.currentTime` for immediate.
     */
    scheduleSlideAtTime(
        _voice: 'bass1' | 'bass2' | 'lead303',
        _enabled: boolean,
        _audioTime: number
    ): void {
        // The open303 / jc303 wasm builds do not yet expose a dedicated slide
        // parameter — portamento is triggered implicitly by sending a legato
        // noteOn (without a preceding noteOff) at the step handler level.
        // This method is intentionally a no-op today: it documents the
        // intended API and allows AutomationScheduler callers to schedule slide
        // state without code changes once a native setSlide API is available.
        //
        // When the wasm build gains setSlide / setPortamento support, replace
        // this body with:
        //   this.scheduleParamAtTime(_voice, 'setSlide', _enabled ? 1.0 : 0.0, _audioTime);
    }

    /**
     * Schedule a linear ramp for an Open303 worklet parameter from `fromValue`
     * to `toValue` between `startTime` and `endTime` (AudioContext time).
     *
     * Implemented as a series of evenly-spaced `scheduleParamAtTime` calls so
     * that the worklet receives smooth parameter updates even though it cannot
     * use native AudioParam ramp methods.
     *
     * @param voice      Which 303 instance to target.
     * @param func       Setter name (e.g. 'setCutoff').
     * @param fromValue  Starting normalised value.
     * @param toValue    Target normalised value.
     * @param startTime  AudioContext time for `fromValue`.
     * @param endTime    AudioContext time for `toValue`.
     * @param steps      Number of intermediate interpolation steps (default 8).
     */
    scheduleParamRamp(
        voice: 'bass1' | 'bass2' | 'lead303',
        func: string,
        fromValue: number,
        toValue: number,
        startTime: number,
        endTime: number,
        steps = 8
    ): void {
        if (steps < 1 || startTime >= endTime) {
            this.scheduleParamAtTime(voice, func, toValue, endTime);
            return;
        }

        // For native AudioParams (pan, gain) use a single linearRamp — it's
        // sample-accurate and cheaper than many setValueAtTime calls.
        if (func === 'setDrive') {
            const wetGain =
                voice === 'bass1' ? this.bass1WetGain :
                voice === 'bass2' ? this.bass2WetGain :
                this.lead303WetGain;
            const dryGain =
                voice === 'bass1' ? this.bass1DryGain :
                voice === 'bass2' ? this.bass2DryGain :
                this.lead303DryGain;
            if (wetGain && dryGain && this.audioContext) {
                const start = Math.max(this.audioContext.currentTime, startTime);
                wetGain.gain.setValueAtTime(fromValue, start);
                wetGain.gain.linearRampToValueAtTime(toValue, endTime);
                dryGain.gain.setValueAtTime(1.0 - fromValue, start);
                dryGain.gain.linearRampToValueAtTime(1.0 - toValue, endTime);
            }
            return;
        }
        if (func === 'setPan') {
            const panner =
                voice === 'bass1' ? this.bass1Panner :
                voice === 'bass2' ? this.bass2Panner :
                this.lead303Panner;
            if (panner && this.audioContext) {
                panner.pan.setValueAtTime(fromValue, Math.max(this.audioContext.currentTime, startTime));
                panner.pan.linearRampToValueAtTime(toValue, endTime);
            }
            return;
        }
        if (func === 'setVolume') {
            const gain =
                voice === 'bass1' ? this.bass1Gain :
                voice === 'bass2' ? this.bass2Gain :
                this.lead303Gain;
            if (gain && this.audioContext) {
                gain.gain.setValueAtTime(fromValue, Math.max(this.audioContext.currentTime, startTime));
                gain.gain.linearRampToValueAtTime(toValue, endTime);
            }
            // Also send interpolated snapshots to the worklet (same as the worklet path below)
            // so its internal gain state mirrors the GainNode ramp.
        }

        // Worklet params: send interpolated snapshots.
        const dur = endTime - startTime;
        for (let i = 0; i <= steps; i++) {
            const t = i / steps;
            const v = fromValue + t * (toValue - fromValue);
            const at = startTime + t * dur;
            this.scheduleParamAtTime(voice, func, v, at);
        }
    }

    /**
     * Switch the DSP engine for the bass1 (SYNTH B / partB) voice.
     *
     * 'open303' — custom synthesizer (default)
     * 'jc303'   — authentic rosic::Open303
     */
    setBass1Engine(engine: 'open303' | 'jc303'): void {
        this.bass1?.setEngine303(engine);
    }

    /**
     * Switch the DSP engine for the bass2 (BASS 2) voice.
     *
     * 'open303' — custom synthesizer (default)
     * 'jc303'   — authentic rosic::Open303
     */
    setBass2Engine(engine: 'open303' | 'jc303'): void {
        this.bass2?.setEngine303(engine);
    }

    /**
     * Switch the DSP engine for the lead303 (SYNTH A / LEAD) voice.
     *
     * 'open303' — custom synthesizer (default)
     * 'jc303'   — authentic rosic::Open303
     */
    setLead303Engine(engine: 'open303' | 'jc303'): void {
        this.lead303?.setEngine303(engine);
    }

    /**
     * Apply persisted per-voice engine303 settings after audio init or song load.
     * Without this, jc303 stays inactive until the user toggles the engine selector.
     */
    syncEngine303Settings(settings: {
        lead?: 'open303' | 'jc303';
        bass1?: 'open303' | 'jc303';
        bass2?: 'open303' | 'jc303';
    }): void {
        if (settings.lead) this.setLead303Engine(settings.lead);
        if (settings.bass1) this.setBass1Engine(settings.bass1);
        if (settings.bass2) this.setBass2Engine(settings.bass2);
    }

    // -------------------------------------------------------------------------
    // 303 voice/model selection (see engines/TB303Models.ts)
    // -------------------------------------------------------------------------

    /** Select the 303 voice/model for the bass1 (SYNTH B / partB) voice. */
    setBass1Model(model: TB303ModelId): void {
        this.bass1?.setModel303(model);
    }

    /** Select the 303 voice/model for the bass2 (BASS 2) voice. */
    setBass2Model(model: TB303ModelId): void {
        this.bass2?.setModel303(model);
    }

    /** Select the 303 voice/model for the lead303 (SYNTH A / LEAD) voice. */
    setLead303Model(model: TB303ModelId): void {
        this.lead303?.setModel303(model);
    }

    /**
     * Apply persisted per-voice model303 settings after audio init or song load.
     * The model-aware successor of syncEngine303Settings.
     */
    syncModel303Settings(settings: {
        lead?: TB303ModelId;
        bass1?: TB303ModelId;
        bass2?: TB303ModelId;
    }): void {
        if (settings.lead) this.setLead303Model(settings.lead);
        if (settings.bass1) this.setBass1Model(settings.bass1);
        if (settings.bass2) this.setBass2Model(settings.bass2);
    }

    // -------------------------------------------------------------------------
    // Live high-fid A/B (Phase L2) + diode-ladder coefficients (Phase L3)
    // -------------------------------------------------------------------------

    private getVoice(voice: 'bass1' | 'bass2' | 'lead303'): Open303Oscillator | null {
        return voice === 'bass1' ? this.bass1 : voice === 'bass2' ? this.bass2 : this.lead303;
    }

    /** Arm / blend live A/B on one voice. Engages only while it plays live-highfid. */
    setVoiceLiveAb(voice: 'bass1' | 'bass2' | 'lead303', settings: Partial<LiveAbSettings>, audioTime?: number): void {
        this.getVoice(voice)?.setLiveAb(settings, audioTime);
    }

    /** Song-stored diode-ladder coefficients for one voice; undefined = canonical. */
    setVoiceHighFidCoefficients(voice: 'bass1' | 'bass2' | 'lead303', coefficients: HighFidCoefficients | undefined): void {
        this.getVoice(voice)?.setHighFidCoefficients(coefficients);
    }

    /** Apply persisted `model303Extra` blobs after audio init or song load. */
    syncModel303Extras(settings: {
        lead?: TB303VoiceExtra;
        bass1?: TB303VoiceExtra;
        bass2?: TB303VoiceExtra;
    }): void {
        const apply = (voice: 'bass1' | 'bass2' | 'lead303', extra: TB303VoiceExtra | undefined) => {
            const osc = this.getVoice(voice);
            if (!osc) return;
            osc.setHighFidCoefficients(extra?.highFidCoefficients);
            osc.setLiveAb({ armed: extra?.ab?.armed === true, ...(extra?.ab ? { mix: extra.ab.mix } : {}) });
        };
        apply('lead303', settings.lead);
        apply('bass1', settings.bass1);
        apply('bass2', settings.bass2);
    }
}

import type { Open303Params, Open303Config } from './Open303Params';
import { DEFAULT_303_PARAMS } from './Open303Params';
import type { TB303ModelId } from './TB303Models';
import {
    isLiveHighFidModel,
    legacyEngine303ForModel,
    normalizeTB303Model,
    reportTB303ModelFallback,
    resolveRealtimeTB303Model,
    stockModelForFamily,
    tb303ModelFamily,
    type Engine303Family,
} from './TB303Models';
import { clampLiveOversample, type LiveHighFidOversample } from '../audio-worklets/liveHighFid303';
import type { HighFidCoefficients } from '../audio-worklets/liveHighFidCoefficients';
import { LiveHighFidVoiceControls, type LiveAbSettings } from './LiveHighFidAbPair';
import { engineDegradationStore } from '../stores/engineDegradationStore';
import { FallbackBassSynth } from './FallbackBassSynth';
import {
    engineTelemetry,
    loadHyphonWasmExportMap,
    logEngineFallback,
    resolvePublicAsset,
} from '../utils/engineTelemetry';
import { attachWorkletPerf } from '../utils/workletPerfBridge';
import {
    formatMissingWasmExports,
    OPEN303_REQUIRED_WASM_EXPORTS,
    open303ExportMapInsufficient,
    wasmExportNameSnapshot,
    type HyphonNativeArtifact,
} from '../audio-worklets/hyphonNativeImports';
import { hyphonNativeBackendName, resolveHyphonNativeArtifact } from './hyphonNativeVariant';
// Open303 DSP lives inside hyphon_native (see emscripten/open303_wrapper.cpp,
// integrated in commit aa4fc93), built as a pthread and a single-threaded module;
// resolveHyphonNativeArtifact picks one per audio context.

/** Maximum milliseconds to wait for the Open303 worklet to signal readiness. */
const OPEN303_INIT_TIMEOUT_MS = 8000;

export class Open303Oscillator {
    private workletNode: AudioWorkletNode | null = null;
    private gainNode: GainNode | null = null;
    private outputNode: GainNode | null = null;
    private fallbackSynth: FallbackBassSynth | null = null;
    private audioContext: AudioContext | null = null;

    private params: Open303Params = { ...DEFAULT_303_PARAMS };
    /** Persisted engine choice — applied once the worklet is ready. */
    private engine303: 'open303' | 'jc303' = 'open303';
    /** Persisted 303 voice/model choice — applied once the worklet is ready. */
    private model303: TB303ModelId = 'stock-open303';
    /**
     * Oversample factor for the live high-fid voice (Phase-L1). 1× is the
     * shipping default: 2× roughly doubles the audio-thread cost and is only
     * worth it on machines with headroom to spare.
     */
    private liveHighFidOversample: LiveHighFidOversample = 1;
    /**
     * Live A/B (Phase L2) + diode-ladder coefficients (Phase L3). Requests are
     * stored here; the crossfade gains and coefficient table are only created
     * once a live-highfid part actually needs them.
     */
    private readonly liveHighFid = new LiveHighFidVoiceControls(
        () => ({
            context: this.audioContext,
            worklet: this.workletNode,
            destination: this.gainNode,
            liveHighFidSelected: isLiveHighFidModel(this.model303) && !this.isFallback,
        }),
        (state) => {
            try { engineTelemetry.recordLiveAb(state); } catch { /* telemetry optional */ }
        },
    );
    /** Cleanup for the worklet status listener (live high-fid fallbacks). */
    private detachStatusListener: (() => void) | null = null;
    public isReady: boolean = false;
    public isFallback: boolean = false;

    /**
     * Triggers that arrived before the engine was up.
     *
     * `isReady` only turns true when the worklet reports ready or the JS fallback
     * is activated, and the fallback is only reached after worklet init fails —
     * up to OPEN303_INIT_TIMEOUT_MS per attempt. Notes the sequencer fires in that
     * window used to be discarded by a bare `if (!this.isReady) return;`: no queue,
     * no error, no telemetry. They are queued here and flushed on ready instead,
     * so a trigger is never lost in silence.
     */
    private pendingTriggers: Array<
        | { kind: 'on'; note: number; velocity: number }
        | { kind: 'off'; note: number }
    > = [];
    /** Bound on the pre-ready queue; past this we refuse loudly rather than grow. */
    private static readonly MAX_PENDING_TRIGGERS = 64;
    /** One refusal per overflow episode — the audio thread must not spam the log. */
    private pendingOverflowReported = false;

    /**
     * @param config `forceSingleThreaded` loads hyphon_native.st.wasm. Without it the
     *   single-threaded build is still chosen on WebKit and on pages that are not
     *   crossOriginIsolated; see resolveHyphonNativeArtifact.
     */
    async init(audioContext: AudioContext, workletUrl?: string, config?: Open303Config): Promise<boolean> {
        this.audioContext = audioContext;

        // Create nodes
        this.outputNode = audioContext.createGain();
        this.gainNode = audioContext.createGain();
        this.gainNode.gain.value = 1.0;
        this.gainNode.connect(this.outputNode);

        // Ensure AudioWorklet is supported and URL is provided
        if (audioContext.audioWorklet && workletUrl) {
            try {
                const { artifact, reason } = resolveHyphonNativeArtifact(audioContext, config);
                const wasmUrl = resolvePublicAsset(artifact.wasm);
                console.log(`[Open303Oscillator] Fetching WASM: ${wasmUrl} (${artifact.threading}: ${reason})`);
                const wasmResponse = await fetch(wasmUrl);

                if (!wasmResponse.ok) {
                    logEngineFallback('open303', 'wasm-worklet', `${artifact.wasm} fetch HTTP ${wasmResponse.status} (${wasmUrl})`);
                    this.activateFallback();
                    return true;
                }

                const wasmBytes = await wasmResponse.arrayBuffer();
                console.log(`[Open303Oscillator] Fetched ${wasmBytes.byteLength} bytes`);

                const exportMap = await this.fetchExportMap(wasmBytes, artifact);
                return this._initWithWasmBytes(audioContext, workletUrl, wasmBytes, artifact, exportMap);

            } catch (e) {
                logEngineFallback('open303', 'wasm-worklet', 'init exception before worklet load', e);
                this.activateFallback();
                return true; // Return true so audio doesn't die
            }
        }

        logEngineFallback(
            'open303',
            'wasm-worklet',
            !audioContext.audioWorklet ? 'AudioWorklet unavailable' : 'worklet URL missing',
        );
        this.activateFallback();
        return true;
    }

    /**
     * Complete the worklet init given pre-fetched WASM bytes.
     * Extracted so that the native/legacy retry path can reuse it.
     */
    private async fetchExportMap(
        wasmBytes: ArrayBuffer,
        artifact: HyphonNativeArtifact,
    ): Promise<Record<string, string>> {
        const map = await loadHyphonWasmExportMap(artifact.threading);
        const mapUrl = resolvePublicAsset(artifact.exportMap);
        const glueUrl = resolvePublicAsset(artifact.glue);
        const wasmModule = await WebAssembly.compile(wasmBytes);
        const rawExports = wasmExportNameSnapshot(wasmModule);

        if (Object.keys(map).length === 0) {
            logEngineFallback(
                'open303',
                'wasm-worklet',
                `${artifact.exportMap} empty and glue parse found no exports ` +
                `(tried ${mapUrl} and ${glueUrl}). ` +
                formatMissingWasmExports(rawExports, [...OPEN303_REQUIRED_WASM_EXPORTS]),
            );
            return map;
        }

        if (open303ExportMapInsufficient(wasmModule, map)) {
            logEngineFallback(
                'open303',
                'wasm-worklet',
                `export map did not resolve open303_* / jc303_* against WASM. ` +
                formatMissingWasmExports(rawExports, [...OPEN303_REQUIRED_WASM_EXPORTS]),
            );
        }

        return map;
    }

    private async _initWithWasmBytes(
        audioContext: AudioContext,
        workletUrl: string,
        wasmBytes: ArrayBuffer,
        artifact: HyphonNativeArtifact,
        exportMap: Record<string, string> = {}
    ): Promise<boolean> {
        try {
            // Add the Worklet Module and create the node
            await audioContext.audioWorklet.addModule(workletUrl);

            this.workletNode = new AudioWorkletNode(audioContext, 'open303-processor', {
                // Output 0 is the voice (stereo). Output 1 is the live A/B
                // high-fid bus (Phase L2): unconnected and never written
                // unless A/B is engaged on a live-highfid part.
                numberOfOutputs: 2,
                outputChannelCount: [2, 2],
            });

            // Both profiles import their memory, so the import table cannot tell them
            // apart (WebAssembly.Module.imports() does not report `shared`). The
            // selection is authoritative: it decides shared vs plain memory and the
            // page floor from emscripten/wasm_memory_budget.json.
            const isThreaded = artifact.sharedMemory;
            const variant = artifact.threading;
            console.log(`[Open303Oscillator] WASM variant: ${variant}`);

            this.workletNode.port.postMessage({
                type: 'init-wasm',
                data: {
                    wasmBytes,
                    sampleRate: audioContext.sampleRate,
                    isThreaded,
                    variant,
                    memoryPages: artifact.minMemoryPages,
                    exportMap,
                }
            });

            // Connect and Listen (gainNode is always set before _initWithWasmBytes is reached)
            if (!this.gainNode) throw new Error('gainNode not initialized');
            this.workletNode.connect(this.gainNode);
            attachWorkletPerf(this.workletNode, 'open303');
            this.attachStatusListener(this.workletNode);

            // Wait for worklet to confirm initialization
            const initSuccess = await new Promise<boolean>((resolve) => {
                let readyReceived = false;

                this.workletNode!.port.onmessage = (e) => {
                    if (e.data.type === 'ready') {
                        readyReceived = true;
                        try { engineTelemetry.recordHyphonNativeHeap(e.data.heap); } catch (_) {}
                        const backend = hyphonNativeBackendName(artifact.threading);
                        console.log(`[Open303] Engine Fully Operational (${backend})`);
                        try { engineTelemetry.registerResolution('jc303', backend, 'worklet-ready'); } catch (_) {}
                        resolve(true);
                    } else if (e.data.type === 'error') {
                        const payload = e.data as { error?: unknown };
                        const errDetail =
                            typeof payload.error === 'string'
                                ? payload.error
                                : payload.error != null
                                  ? String(payload.error)
                                  : 'unknown worklet error';
                        logEngineFallback(
                            'open303',
                            'wasm-worklet',
                            `worklet init-wasm error: ${errDetail}`,
                        );
                        resolve(false);
                    }
                };

                // Timeout: OPEN303_INIT_TIMEOUT_MS — 1.2 MB WASM should compile in < 3s on modern devices.
                // 20s was excessively generous and caused the second 303 instance to time out
                // when the first one failed (both share a Promise.allSettled budget).
                setTimeout(() => {
                    if (!readyReceived) {
                        logEngineFallback('open303', 'wasm-worklet', `worklet ready timeout (${OPEN303_INIT_TIMEOUT_MS}ms)`);
                        resolve(false);
                    }
                }, OPEN303_INIT_TIMEOUT_MS);
            });

            if (!initSuccess) {
                logEngineFallback('open303', 'wasm-worklet', 'worklet never reached ready state');
                this.cleanupWorklet();
                this.activateFallback();
                return true; // Return true so audio doesn't die
            }

            this.isReady = true;
            this.isFallback = false;
            this.applyModel303();
            this.applyAllParameters();
            this.liveHighFid.pushCoefficients();
            this.liveHighFid.sync();
            this.flushPendingTriggers();
            try { engineTelemetry.registerResolution('open303', hyphonNativeBackendName(artifact.threading), `worklet-ready (${artifact.wasm})`); } catch (_) {}
            return true;

        } catch (e) {
            logEngineFallback('open303', 'wasm-worklet', 'AudioWorklet.addModule or node creation failed', e);
            this.activateFallback();
            return true;
        }
    }

    private activateFallback(): void {
        if (!this.audioContext || !this.outputNode) return;

        console.warn('[Open303] Activating FallbackBassSynth (JS voice)');
        try { engineTelemetry.registerResolution('open303', 'js', 'fallback-synth-active'); } catch (_) {}
        this.fallbackSynth = new FallbackBassSynth(this.audioContext);
        this.fallbackSynth.connect(this.outputNode);
        this.isReady = true;
        this.isFallback = true;

        // Apply current params to fallback
        this.fallbackSynth.setWaveform(this.params.waveform);
        this.fallbackSynth.setCutoff(this.params.cutoff);
        this.fallbackSynth.setResonance(this.params.resonance);
        this.fallbackSynth.setDecay(this.params.decay);
        this.fallbackSynth.setVolume(this.params.volume);

        this.flushPendingTriggers();
    }

    noteOn(midiNote: number, velocity: number = 100, audioTime?: number): void {
        if (!this.isReady) {
            this.queueTrigger({ kind: 'on', note: midiNote, velocity });
            return;
        }
        this.deliverNoteOn(midiNote, velocity, audioTime);
    }

    private deliverNoteOn(midiNote: number, velocity: number, audioTime?: number): void {
        if (this.isFallback && this.fallbackSynth) {
            const t0 = performance.now();
            this.fallbackSynth.noteOn(midiNote, velocity);
            const t1 = performance.now();
            try { engineTelemetry.recordLatency('jc303', t1 - t0); } catch (_) {}
        } else if (this.workletNode) {
            const t0 = performance.now();
            this.workletNode.port.postMessage({ type: 'noteOn', data: { note: midiNote, velocity, audioTime } });
            const t1 = performance.now();
            try { engineTelemetry.recordLatency('jc303', t1 - t0); } catch (_) {}
        }
    }

    noteOff(midiNote: number, audioTime?: number): void {
        if (!this.isReady) {
            this.queueTrigger({ kind: 'off', note: midiNote });
            return;
        }
        this.deliverNoteOff(midiNote, audioTime);
    }

    private deliverNoteOff(midiNote: number, audioTime?: number): void {
        if (this.isFallback && this.fallbackSynth) {
            const t0 = performance.now();
            this.fallbackSynth.noteOff(midiNote);
            const t1 = performance.now();
            try { engineTelemetry.recordLatency('jc303', t1 - t0); } catch (_) {}
        } else if (this.workletNode) {
            const t0 = performance.now();
            this.workletNode.port.postMessage({ type: 'noteOff', data: { note: midiNote, audioTime } });
            const t1 = performance.now();
            try { engineTelemetry.recordLatency('jc303', t1 - t0); } catch (_) {}
        }
    }

    /** Hold a trigger that arrived before the engine was up, or refuse it visibly. */
    private queueTrigger(
        trigger: { kind: 'on'; note: number; velocity: number } | { kind: 'off'; note: number },
    ): void {
        if (this.pendingTriggers.length >= Open303Oscillator.MAX_PENDING_TRIGGERS) {
            if (!this.pendingOverflowReported) {
                this.pendingOverflowReported = true;
                logEngineFallback(
                    'open303',
                    'wasm-worklet',
                    `pre-ready trigger queue overflow (> ${Open303Oscillator.MAX_PENDING_TRIGGERS}); ` +
                    'dropping further notes until the engine reports ready',
                );
            }
            return;
        }
        this.pendingTriggers.push(trigger);
    }

    /**
     * Deliver everything queued while the engine was coming up.
     *
     * Queued notes carry no audioTime: the timestamps they were fired with are in
     * the past by the time the engine is ready, and scheduling into the past is
     * worse than playing them now.
     */
    private flushPendingTriggers(): void {
        if (this.pendingTriggers.length === 0) {
            this.pendingOverflowReported = false;
            return;
        }
        const queued = this.pendingTriggers;
        this.pendingTriggers = [];
        this.pendingOverflowReported = false;
        for (const trigger of queued) {
            if (trigger.kind === 'on') {
                this.deliverNoteOn(trigger.note, trigger.velocity);
            } else {
                this.deliverNoteOff(trigger.note);
            }
        }
    }

    setParam(func: string, value: number, audioTime?: number): void {
        if (this.isFallback && this.fallbackSynth) {
            // Map to fallback synth methods
            switch(func) {
                case 'setWaveform': this.fallbackSynth.setWaveform(value); break;
                case 'setCutoff': this.fallbackSynth.setCutoff(value); break;
                case 'setResonance': this.fallbackSynth.setResonance(value); break;
                case 'setDecay': this.fallbackSynth.setDecay(value); break;
                case 'setVolume': this.fallbackSynth.setVolume(value); break;
                // envMod, accent, filterMode not implemented in fallback
            }
        } else if (this.workletNode) {
            this.workletNode.port.postMessage({ type: 'param', data: { func: `jc303_${func}`, value, audioTime } });
        }
    }

    /**
     * Switch the DSP engine used by this oscillator's AudioWorklet processor.
     *
     * 'open303' — custom synthesizer (default, open303_* API in hyphon_native.wasm)
     * 'jc303'   — authentic rosic::Open303 (jc303_* multi-instance API)
     *
     * The worklet will silently ignore the request when the requested engine is
     * not available in the loaded WASM build.
     */
    setEngine303(engine: 'open303' | 'jc303'): void {
        this.engine303 = engine;
        this.model303 = stockModelForFamily(engine);
        this.applyEngine303();
    }

    private applyEngine303(): void {
        if (!this.workletNode) return;
        this.workletNode.port.postMessage({ type: 'set-engine', data: { engine: this.engine303 } });
        if (this.isReady) {
            // Params were routed to the previous engine — push them to the new one.
            this.applyAllParameters();
        }
    }

    /**
     * Select the 303 voice/model for this oscillator (see engines/TB303Models.ts).
     *
     * Unknown or not-yet-shipped models normalize to the stock voice of their
     * engine family. When the loaded WASM predates the model registry the
     * worklet falls back to plain engine-family switching, so stock voices
     * always work.
     */
    setModel303(model: TB303ModelId | string): void {
        const requested = typeof model === 'string' ? model.trim() : model;
        // Persist the catalog id when known; AudioWorklet only receives realtime-safe voices.
        const persisted = normalizeTB303Model(requested);
        const resolved = resolveRealtimeTB303Model(persisted, undefined, { reportFallback: false });
        if (requested && resolved !== requested) {
            reportTB303ModelFallback(
                requested,
                resolved,
                persisted !== requested
                    ? 'runtime apply'
                    : 'offline-only high-fid voice (realtime uses stock)',
                'open303-model',
            );
        }
        this.model303 = resolved;
        this.engine303 = legacyEngine303ForModel(this.model303);
        if (isLiveHighFidModel(this.model303)) {
            engineDegradationStore.resolve('live-highfid');
            try {
                engineTelemetry.recordLiveHighFid({
                    requested: this.model303,
                    active: true,
                    oversample: this.liveHighFidOversample,
                });
            } catch { /* telemetry optional */ }
        }
        this.applyModel303();
        this.liveHighFid.sync();
    }

    /**
     * Arm / blend live A/B (Phase L2). Engages only while this part plays
     * `live-highfid`; `audioTime` schedules a blend change (automation).
     */
    setLiveAb(settings: Partial<LiveAbSettings>, audioTime?: number): void {
        this.liveHighFid.setLiveAb(settings, audioTime);
    }

    setLiveAbMix(mix: number, audioTime?: number): void {
        this.liveHighFid.setLiveAb({ mix }, audioTime);
    }

    getLiveAb(): LiveAbSettings {
        return this.liveHighFid.liveAb;
    }

    /** Both buses are wired and the worklet renders stock + high-fid. */
    isLiveAbEngaged(): boolean {
        return this.liveHighFid.isAbEngaged;
    }

    /** Song-stored diode-ladder coefficients (Phase L3); `undefined` = canonical. */
    setHighFidCoefficients(coefficients: HighFidCoefficients | undefined): void {
        this.liveHighFid.setHighFidCoefficients(coefficients);
    }

    getHighFidCoefficients(): HighFidCoefficients | undefined {
        return this.liveHighFid.highFidCoefficients;
    }

    /**
     * Oversample factor for the live high-fid voice (1× default, 2× when the
     * CPU budget allows). Takes effect on the next model apply.
     */
    setLiveHighFidOversample(factor: number): void {
        this.liveHighFidOversample = clampLiveOversample(factor);
        if (isLiveHighFidModel(this.model303)) this.applyModel303();
    }

    /** Currently selected 303 voice/model. */
    getModel303(): TB303ModelId {
        return this.model303;
    }

    private applyModel303(): void {
        if (!this.workletNode) return;
        // The worklet routes on engine family: `highfid` selects the live
        // diode-ladder voice, the other two keep their existing meaning.
        const family: Engine303Family = tb303ModelFamily(this.model303);
        this.workletNode.port.postMessage({
            type: 'set-303-model',
            // engine is included so the worklet can route correctly even when
            // the WASM build has no native model registry (pre-voices builds).
            data: {
                model: this.model303,
                engine: family,
                oversample: this.liveHighFidOversample,
            },
        });
        if (this.isReady) {
            // Params were routed to the previous engine — push them to the new one.
            this.applyAllParameters();
        }
    }

    // Explicit setters used by the application
    setWaveform(v: number) { this.params.waveform = v; this.setParam('setWaveform', v); }
    setCutoff(v: number) { this.params.cutoff = v; this.setParam('setCutoff', v); }
    setResonance(v: number) { this.params.resonance = v; this.setParam('setResonance', v); }
    setFilterMode(v: number) { this.params.filterMode = v; this.setParam('setFilterMode', v); }
    setDecay(v: number) { this.params.decay = v; this.setParam('setDecay', v); }
    setEnvMod(v: number) { this.params.envMod = v; this.setParam('setEnvMod', v); }
    setAccent(v: number) { this.params.accent = v; this.setParam('setAccent', v); }
    setVolume(v: number) { this.params.volume = v; this.setParam('setVolume', v); }

    // Helper to sync state
    private applyAllParameters() {
        this.setWaveform(this.params.waveform);
        this.setCutoff(this.params.cutoff);
        this.setResonance(this.params.resonance);
        this.setFilterMode(this.params.filterMode);
        this.setDecay(this.params.decay);
        this.setEnvMod(this.params.envMod);
        this.setAccent(this.params.accent);
        this.setVolume(this.params.volume);
    }

    connect(dest: AudioNode) {
        if (this.outputNode) this.outputNode.connect(dest);
    }

    disconnect() {
        if (this.outputNode) this.outputNode.disconnect();
    }

    /**
     * Listen for worklet-side status messages that outlive init — today the
     * live high-fid CPU/glitch gate. Uses addEventListener so it coexists with
     * the `port.onmessage` handler the init handshake installs.
     */
    private attachStatusListener(node: AudioWorkletNode): void {
        this.detachStatusListener?.();

        const onMessage = (event: MessageEvent) => {
            const payload = event.data as { type?: string; data?: Record<string, unknown> } | null;
            if (!payload || typeof payload !== 'object') return;
            if (payload.type === 'hyphon-heap') {
                try { engineTelemetry.recordHyphonNativeHeap(payload.data); } catch { /* telemetry optional */ }
            } else if (payload.type === 'live-highfid-degraded') {
                this.handleLiveHighFidFallback(
                    String(payload.data?.reason ?? 'CPU budget exceeded'),
                    typeof payload.data?.cpuPercent === 'number' ? payload.data.cpuPercent : null,
                );
            } else if (payload.type === 'live-highfid-unavailable') {
                this.handleLiveHighFidFallback(
                    String(payload.data?.reason ?? 'live high-fid unavailable'),
                    null,
                );
            } else if (payload.type === 'live-ab-cpu') {
                const stock = payload.data?.stockPercent;
                const highFid = payload.data?.highFidPercent;
                try {
                    engineTelemetry.recordLiveAbCpu({
                        stockPercent: typeof stock === 'number' ? stock : null,
                        highFidPercent: typeof highFid === 'number' ? highFid : null,
                    });
                } catch { /* telemetry optional */ }
            }
        };

        node.port.addEventListener('message', onMessage);
        this.detachStatusListener = () => node.port.removeEventListener('message', onMessage);
    }

    /**
     * The worklet handed the live high-fid voice back to Stock Open303.
     * Mirror that on this side so the HUD, telemetry and any later param
     * pushes all agree on which path is actually audible.
     */
    private handleLiveHighFidFallback(reason: string, cpuPercent: number | null): void {
        const requested = this.model303;
        this.model303 = 'stock-open303';
        this.engine303 = 'open303';
        try {
            engineTelemetry.recordLiveHighFid({
                requested,
                active: false,
                reason,
                cpuPercent,
                oversample: this.liveHighFidOversample,
            });
        } catch { /* telemetry optional */ }
        try {
            engineDegradationStore.reportLiveHighFidFallback({ requested, reason, cpuPercent });
        } catch { /* store optional in tests */ }
        reportTB303ModelFallback(requested, 'stock-open303', reason, 'live-highfid');
        // A/B collapses to side A: output 0 (stock, untouched) goes straight
        // back to the part's gain, whatever the blend was.
        this.liveHighFid.sync();
    }

    private cleanupWorklet() {
        this.detachStatusListener?.();
        this.detachStatusListener = null;
        this.liveHighFid.detach();
        if (this.workletNode) {
            // hyphon_native is shared by every voice in the audio session: ask the
            // processor to destroy its handles before the port goes away.
            this.workletNode.port.postMessage({ type: 'dispose' });
            this.workletNode.disconnect();
            this.workletNode.port.close();
            this.workletNode = null;
        }
    }

    // Public cleanup method for external disposal
    cleanup() {
        this.cleanupWorklet();
        if (this.gainNode) {
            this.gainNode.disconnect();
            this.gainNode = null;
        }
        if (this.outputNode) {
            this.outputNode.disconnect();
            this.outputNode = null;
        }
        if (this.fallbackSynth) {
            this.fallbackSynth.cleanup();
            this.fallbackSynth = null;
        }
        this.isReady = false;
        this.isFallback = false;
    }
}

/**
 * ProphecyManager.ts
 *
 * Manages two ProphecyOscillator instances:
 *   - partA: SYNTH A / LEAD voice
 *   - partB: SYNTH B / BASS voice
 *
 * Mirrors the structure of Open303Manager so the routing code can
 * follow the same patterns.
 */

import { ProphecyOscillator } from './ProphecyOscillator';
import { logEngineFallback } from '../utils/engineTelemetry';
import type { SynthParams } from '../types';
import { PROPHECY_WAVEFORM_ID } from './ProphecyParams';

export type ProphecyAutomationParam = 'vowel' | 'portamento' | 'formantShift';

export class ProphecyManager {
    private partA: ProphecyOscillator | null = null;
    private partB: ProphecyOscillator | null = null;
    private audioContext: AudioContext | null = null;

    // ── Lifecycle ─────────────────────────────────────────────────────────────

    /**
     * Initialize both Prophecy instances.
     *
     * The browser de-dupes `addModule` calls for the same URL so both
     * instances share a single worklet load.
     */
    async init(audioContext: AudioContext, workletUrl: string): Promise<boolean> {
        this.audioContext = audioContext;
        this.partA = new ProphecyOscillator();
        this.partB = new ProphecyOscillator();

        const results = await Promise.allSettled([
            this.partA.init(audioContext, workletUrl),
            this.partB.init(audioContext, workletUrl),
        ]);

        const [aResult, bResult] = results;
        const aReady = aResult.status === 'fulfilled' && aResult.value;
        const bReady = bResult.status === 'fulfilled' && bResult.value;

        if (!aReady) logEngineFallback('prophecy', 'wasm-worklet', 'partA (SYNTH A) init failed');
        if (!bReady) logEngineFallback('prophecy', 'wasm-worklet', 'partB (SYNTH B) init failed');

        return aReady || bReady;
    }

    /** Connect both instances to a downstream audio node (e.g. master bus). */
    connect(dest: AudioNode): void {
        this.partA?.connect(dest);
        this.partB?.connect(dest);
    }

    /** Route partA → SYNTH A bus and partB → SYNTH B bus. */
    connectBuses(partADest: AudioNode, partBDest: AudioNode): void {
        this.partA?.connect(partADest);
        this.partB?.connect(partBDest);
    }

    /** Disconnect both instances. */
    disconnect(): void {
        this.partA?.disconnect();
        this.partB?.disconnect();
    }

    // ── Readiness ─────────────────────────────────────────────────────────────

    isPartAReady(): boolean { return this.partA?.isReady ?? false; }
    isPartBReady(): boolean { return this.partB?.isReady ?? false; }

    // ── Parameter application ─────────────────────────────────────────────────

    /**
     * Apply SynthParams to a Prophecy instance.
     *
     * @param osc       The target ProphecyOscillator.
     * @param params    Current SynthParams from the UI.
     * @param waveType  Waveform suffix extracted from the Waveform value
     *                  ('saw' | 'sqr' | 'tri' | 'pulse').
     */
    private static applyParams(
        osc: ProphecyOscillator,
        params: SynthParams,
        waveType: string,
    ): void {
        osc.setWaveform(PROPHECY_WAVEFORM_ID[waveType] ?? 0);
        osc.setVolume(params.volume);
        // Map ADSR: UI values are in seconds/levels; Prophecy params are 0-1
        osc.setAttack(Math.max(0, Math.min(1, params.attack / 2)));
        osc.setDecay(Math.max(0, Math.min(1, params.decay / 2)));
        osc.setSustain(Math.max(0, Math.min(1, params.sustain)));
        osc.setRelease(Math.max(0, Math.min(1, params.release / 3)));
        // Map filterResonance (0-20) → Prophecy RESONANCE (0-1, inverted: high Q = low value)
        osc.setResonance(Math.max(0, Math.min(1, 1 - params.filterResonance / 20)));
        // Prophecy-specific params
        osc.setVowel(Math.round(Math.max(0, Math.min(4, params.vowel ?? 0))));
        osc.setPortamento(Math.max(0, Math.min(1, params.portamento ?? 0)));
        osc.setFormantShift(Math.max(0, Math.min(1, params.formantShift ?? 0)));
    }

    applyPartAParams(params: SynthParams, waveType: string): void {
        if (this.partA) ProphecyManager.applyParams(this.partA, params, waveType);
    }

    applyPartBParams(params: SynthParams, waveType: string): void {
        if (this.partB) ProphecyManager.applyParams(this.partB, params, waveType);
    }

    /**
     * Schedule a Prophecy parameter at an AudioContext time (not rAF).
     * Worklet params are dispatched via a wall-clock delay derived from the audio clock.
     */
    scheduleParamAtTime(
        part: 'partA' | 'partB',
        param: ProphecyAutomationParam,
        value: number,
        audioTime: number,
    ): void {
        const osc = part === 'partA' ? this.partA : this.partB;
        if (!osc || !this.audioContext) return;

        const nowAudio = this.audioContext.currentTime;
        const delayMs = Math.max(0, (audioTime - nowAudio) * 1000);

        const apply = () => {
            switch (param) {
                case 'vowel':
                    osc.setVowel(Math.round(Math.max(0, Math.min(4, value * 4))));
                    break;
                case 'portamento':
                    osc.setPortamento(Math.max(0, Math.min(1, value)));
                    break;
                case 'formantShift':
                    osc.setFormantShift(Math.max(0, Math.min(1, value)));
                    break;
            }
        };

        if (delayMs < 1) {
            apply();
        } else {
            setTimeout(apply, delayMs);
        }
    }

    // ── Note control ─────────────────────────────────────────────────────────

    noteOnPartA(midiNote: number, velocity: number = 100, audioTime?: number): void {
        this.partA?.noteOn(midiNote, velocity);
    }

    noteOffPartA(midiNote: number, audioTime?: number): void {
        this.partA?.noteOff(midiNote);
    }

    noteOnPartB(midiNote: number, velocity: number = 100, audioTime?: number): void {
        this.partB?.noteOn(midiNote, velocity);
    }

    noteOffPartB(midiNote: number, audioTime?: number): void {
        this.partB?.noteOff(midiNote);
    }

    allNotesOff(): void {
        this.partA?.allNotesOff();
        this.partB?.allNotesOff();
    }

    allNotesOffPartA(): void {
        this.partA?.allNotesOff();
    }

    allNotesOffPartB(): void {
        this.partB?.allNotesOff();
    }

    // ── Cleanup ───────────────────────────────────────────────────────────────

    cleanup(): void {
        this.partA?.cleanup();
        this.partB?.cleanup();
        this.partA = null;
        this.partB = null;
        this.audioContext = null;
    }
}

/**
 * ProphecyOscillator.ts
 *
 * TypeScript engine class for the Korg Prophecy formant synthesizer.
 * Communicates with the `prophecy-processor` AudioWorklet which drives
 * the `prophecy_*` C API inside hyphon_native.wasm.
 *
 * Usage:
 *   const osc = new ProphecyOscillator();
 *   await osc.init(audioContext, '/prophecy-processor.js');
 *   osc.connect(audioContext.destination);
 *   osc.noteOn(60, 100);
 */

import type { ProphecyParams } from './ProphecyParams';
import { ProphecyParam, DEFAULT_PROPHECY_PARAMS } from './ProphecyParams';

import {
    engineTelemetry,
    loadHyphonWasmExportMap,
    logEngineFallback,
    resolvePublicAsset,
} from '../utils/engineTelemetry';
import {
    formatMissingWasmExports,
    PROPHECY_REQUIRED_WASM_EXPORTS,
    prophecyExportMapInsufficient,
    wasmExportNameSnapshot,
    HYPHON_NATIVE_ARTIFACTS,
    type HyphonNativeArtifact,
} from '../audio-worklets/hyphonNativeImports';
import { hyphonNativeBackendName, resolveHyphonNativeArtifact } from './hyphonNativeVariant';

/** Milliseconds to wait for the Prophecy worklet to signal readiness. */
const PROPHECY_INIT_TIMEOUT_MS = 8000;

export class ProphecyOscillator {
    private workletNode:  AudioWorkletNode | null = null;
    private gainNode:     GainNode         | null = null;
    private outputNode:   GainNode         | null = null;
    private audioContext: AudioContext     | null = null;

    /** Snapshot of the current parameter state — applied once the worklet is ready. */
    private params: ProphecyParams = { ...DEFAULT_PROPHECY_PARAMS };

    public isReady: boolean = false;

    // ── Lifecycle ─────────────────────────────────────────────────────────────

    /**
     * Initialize the engine.
     *
     * @param audioContext  The Web Audio context to attach to.
     * @param workletUrl    URL of the compiled `prophecy-processor.js` worklet module.
     * @returns             `true` when the worklet is ready; `false` on fatal failure.
     *
     * Prophecy shares the audio session's hyphon_native instance with the 303
     * voices, so it loads whichever profile (pthread / st) the context is bound to.
     */
    async init(audioContext: AudioContext, workletUrl: string): Promise<boolean> {
        this.audioContext = audioContext;

        this.outputNode = audioContext.createGain();
        this.gainNode   = audioContext.createGain();
        this.gainNode.gain.value = 1.0;
        this.gainNode.connect(this.outputNode);

        if (!audioContext.audioWorklet || !workletUrl) {
            logEngineFallback(
                'prophecy',
                'wasm-worklet',
                !audioContext.audioWorklet ? 'AudioWorklet unavailable' : 'worklet URL missing',
            );
            return false;
        }

        try {
            const { artifact, reason } = resolveHyphonNativeArtifact(audioContext);
            const wasmUrl = resolvePublicAsset(artifact.wasm);
            console.log(`[ProphecyOscillator] Fetching WASM: ${wasmUrl} (${artifact.threading}: ${reason})`);
            const response = await fetch(wasmUrl);
            if (!response.ok) {
                logEngineFallback('prophecy', 'wasm-worklet', `${artifact.wasm} fetch HTTP ${response.status} (${wasmUrl})`);
                return false;
            }

            const wasmBytes = await response.arrayBuffer();
            console.log(`[ProphecyOscillator] Fetched ${wasmBytes.byteLength} bytes`);

            const exportMap = await this.fetchExportMap(wasmBytes, artifact);
            return this._initWithWasmBytes(audioContext, workletUrl, wasmBytes, exportMap, artifact);

        } catch (e) {
            logEngineFallback('prophecy', 'wasm-worklet', 'init exception before worklet load', e);
            return false;
        }
    }

    /**
     * Complete worklet initialisation given pre-fetched WASM bytes.
     * Extracted so the init path stays testable without a real network.
     */
    private async fetchExportMap(
        wasmBytes: ArrayBuffer,
        artifact: HyphonNativeArtifact,
    ): Promise<Record<string, string>> {
        const map = await loadHyphonWasmExportMap(artifact.threading);
        const mapUrl = resolvePublicAsset(artifact.exportMap);
        const glueUrl = resolvePublicAsset(artifact.glue);
        const wasmModule = await WebAssembly.compile(wasmBytes);
        const rawExports = wasmExportNameSnapshot(wasmModule);

        if (Object.keys(map).length === 0) {
            logEngineFallback(
                'prophecy',
                'wasm-worklet',
                `${artifact.exportMap} empty and glue parse found no exports ` +
                `(tried ${mapUrl} and ${glueUrl}). ` +
                formatMissingWasmExports(rawExports, [...PROPHECY_REQUIRED_WASM_EXPORTS]),
            );
            return map;
        }

        if (prophecyExportMapInsufficient(wasmModule, map)) {
            logEngineFallback(
                'prophecy',
                'wasm-worklet',
                `export map did not resolve prophecy_* against WASM. ` +
                formatMissingWasmExports(rawExports, [...PROPHECY_REQUIRED_WASM_EXPORTS]),
            );
        }

        return map;
    }

    async _initWithWasmBytes(
        audioContext: AudioContext,
        workletUrl:   string,
        wasmBytes:    ArrayBuffer,
        exportMap:    Record<string, string> = {},
        artifact:     HyphonNativeArtifact = HYPHON_NATIVE_ARTIFACTS.pthread,
    ): Promise<boolean> {
        try {
            await audioContext.audioWorklet.addModule(workletUrl);

            this.workletNode = new AudioWorkletNode(audioContext, 'prophecy-processor', {
                outputChannelCount: [2],
            });

            // Both profiles import memory; the selection (not the import table,
            // which does not report `shared`) decides shared vs plain + page floor.
            console.log(`[ProphecyOscillator] WASM variant: ${artifact.threading}`);

            this.workletNode.port.postMessage({
                type: 'init-wasm',
                data: {
                    wasmBytes,
                    sampleRate: audioContext.sampleRate,
                    isThreaded:  artifact.sharedMemory,
                    variant:     artifact.threading,
                    memoryPages: artifact.minMemoryPages,
                    exportMap,
                },
            });

            if (!this.gainNode) throw new Error('gainNode not initialized');
            this.workletNode.connect(this.gainNode);

            const initSuccess = await new Promise<boolean>((resolve) => {
                let readyReceived = false;

                this.workletNode!.port.onmessage = (e) => {
                    if (e.data.type === 'ready') {
                        readyReceived = true;
                        console.log('[ProphecyOscillator] Engine ready');
                        try { engineTelemetry.recordHyphonNativeHeap(e.data.heap); } catch (_) {}
                        resolve(true);
                    } else if (e.data.type === 'hyphon-heap') {
                        try { engineTelemetry.recordHyphonNativeHeap(e.data.data); } catch (_) {}
                    } else if (e.data.type === 'error') {
                        const payload = e.data as { error?: unknown };
                        const errDetail =
                            typeof payload.error === 'string'
                                ? payload.error
                                : payload.error != null
                                  ? String(payload.error)
                                  : 'unknown worklet error';
                        logEngineFallback(
                            'prophecy',
                            'wasm-worklet',
                            `worklet init-wasm error: ${errDetail}`,
                        );
                        resolve(false);
                    }
                };

                setTimeout(() => {
                    if (!readyReceived) {
                        logEngineFallback('prophecy', 'wasm-worklet', `worklet ready timeout (${PROPHECY_INIT_TIMEOUT_MS}ms)`);
                        resolve(false);
                    }
                }, PROPHECY_INIT_TIMEOUT_MS);
            });

            if (!initSuccess) {
                logEngineFallback('prophecy', 'wasm-worklet', 'worklet never reached ready state');
                this.cleanupWorklet();
                return false;
            }

            this.isReady = true;
            this.applyAllParameters();
            try { engineTelemetry.registerResolution('prophecy', hyphonNativeBackendName(artifact.threading), `worklet-ready (${artifact.wasm})`); } catch (_) {}
            return true;

        } catch (e) {
            logEngineFallback('prophecy', 'wasm-worklet', 'AudioWorklet.addModule or node creation failed', e);
            this.cleanupWorklet();
            return false;
        }
    }

    // ── MIDI ──────────────────────────────────────────────────────────────────

    noteOn(midiNote: number, velocity: number = 100, audioTime?: number): void {
        if (!this.isReady || !this.workletNode) return;
        this.workletNode.port.postMessage({ type: 'noteOn', data: { note: midiNote, velocity, audioTime } });
    }

    noteOff(midiNote: number, audioTime?: number): void {
        if (!this.isReady || !this.workletNode) return;
        this.workletNode.port.postMessage({ type: 'noteOff', data: { note: midiNote, audioTime } });
    }

    allNotesOff(): void {
        if (!this.workletNode) return;
        this.workletNode.port.postMessage({ type: 'allNotesOff', data: {} });
    }

    // ── Parameters ────────────────────────────────────────────────────────────

    /**
     * Set a single synthesis parameter.
     * @param paramId  A `ProphecyParam.*` constant.
     * @param value    Normalised value (range depends on parameter — see ProphecyParams.ts).
     */
    setParam(paramId: number, value: number): void {
        if (this.workletNode)
            this.workletNode.port.postMessage({ type: 'set-param', data: { paramId, value } });
    }

    // Convenience setters that also update the internal snapshot
    setWaveform(v: number)      { this.params.waveform     = v; this.setParam(ProphecyParam.WAVEFORM,      v); }
    setVowel(v: number)         { this.params.vowel        = v; this.setParam(ProphecyParam.VOWEL,         v); }
    setVolume(v: number)        { this.params.volume       = v; this.setParam(ProphecyParam.VOLUME,        v); }
    setAttack(v: number)        { this.params.attack       = v; this.setParam(ProphecyParam.ATTACK,        v); }
    setDecay(v: number)         { this.params.decay        = v; this.setParam(ProphecyParam.DECAY,         v); }
    setSustain(v: number)       { this.params.sustain      = v; this.setParam(ProphecyParam.SUSTAIN,       v); }
    setRelease(v: number)       { this.params.release      = v; this.setParam(ProphecyParam.RELEASE,       v); }
    setPortamento(v: number)    { this.params.portamento   = v; this.setParam(ProphecyParam.PORTAMENTO,    v); }
    setFormantShift(v: number)  { this.params.formantShift = v; this.setParam(ProphecyParam.FORMANT_SHIFT, v); }
    setResonance(v: number)     { this.params.resonance    = v; this.setParam(ProphecyParam.RESONANCE,     v); }

    // ── Audio routing ─────────────────────────────────────────────────────────

    connect(dest: AudioNode): void {
        if (this.outputNode) this.outputNode.connect(dest);
    }

    disconnect(): void {
        if (this.outputNode) this.outputNode.disconnect();
    }

    // ── Cleanup ───────────────────────────────────────────────────────────────

    cleanup(): void {
        this.cleanupWorklet();
        if (this.gainNode) {
            this.gainNode.disconnect();
            this.gainNode = null;
        }
        if (this.outputNode) {
            this.outputNode.disconnect();
            this.outputNode = null;
        }
        this.isReady = false;
    }

    // ── Private helpers ───────────────────────────────────────────────────────

    private cleanupWorklet(): void {
        if (this.workletNode) {
            // hyphon_native is shared by every voice in the audio session: ask the
            // processor to destroy its handle before the port goes away.
            this.workletNode.port.postMessage({ type: 'dispose' });
            this.workletNode.disconnect();
            this.workletNode.port.close();
            this.workletNode = null;
        }
    }

    /** Re-apply all parameters after the worklet becomes ready. */
    private applyAllParameters(): void {
        this.setWaveform(this.params.waveform);
        this.setVowel(this.params.vowel);
        this.setVolume(this.params.volume);
        this.setAttack(this.params.attack);
        this.setDecay(this.params.decay);
        this.setSustain(this.params.sustain);
        this.setRelease(this.params.release);
        this.setPortamento(this.params.portamento);
        this.setFormantShift(this.params.formantShift);
        this.setResonance(this.params.resonance);
    }
}

import {
  PhonemeAligner,
  type AlignmentResult,
} from "./rubberband/PhonemeAligner";
import {
  FormantShifter,
} from "./rubberband/FormantShifter";
import type { PhonemeBufferPool } from "../services/PhonemeBufferPool";
import {
  type PitchCache,
  type SingingVoiceConfig,
  REFERENCE_FREQUENCIES,
  PITCH_RATIO_LIMITS,
  STRETCH_RATIO_LIMITS,
  clampStretchRatio,
} from "./singing-voice/constants";
import { midiToFreq, freqToMidi } from "./singing-voice/pitchUtils";
import type { SingingVoiceHost } from "./singing-voice/host";
import type { SingingVoicePublic } from "./singing-voice/types";
import { WorkletSetupMixin } from "./singing-voice/workletSetup";
import { PitchControlMixin } from "./singing-voice/pitchControl";
import { FormantControlMixin } from "./singing-voice/formantControl";
import { EffectsControlMixin } from "./singing-voice/effectsControl";
import { PlaybackMixin } from "./singing-voice/playback";

// Re-export public constants, types, and utilities
export type { PitchCache, SingingVoiceConfig };
export {
  REFERENCE_FREQUENCIES,
  PITCH_RATIO_LIMITS,
  STRETCH_RATIO_LIMITS,
  clampStretchRatio,
};
export { midiToFreq, freqToMidi };

/**
 * SingingVoice - High-fidelity vocal synthesis engine
 *
 * Part of the RUBBERBAND_ENHANCEMENT_PLAN implementation.
 * Integrates Supertonic TTS with Rubber Band for singing synthesis.
 *
 * Key features:
 * - Multi-resolution pitch caching (Section 2): Pre-render at multiple base pitches
 * - Formant preservation: Avoids "chipmunk effect"
 * - Latency compensation for MIDI sync (Section 9)
 * - Phoneme-aware time stretching (Section 3): Selective vowel/consonant stretching
 * - Formant shifting (Section 4): Independent vocal character control
 */

// Mixin methods are applied via Object.assign below; this interface exposes them on the class type.
// eslint-disable-next-line @typescript-eslint/no-empty-object-type, @typescript-eslint/no-unsafe-declaration-merging
export interface SingingVoice extends SingingVoicePublic {}

// eslint-disable-next-line @typescript-eslint/no-unsafe-declaration-merging
export class SingingVoice implements SingingVoicePublic {
  audioContext: AudioContext;
  workletNode: AudioWorkletNode | null = null;
  config: SingingVoiceConfig;

  /** Latency of the Rubber Band processor in samples */
  processorLatency: number = 0;

  /** Cache for pre-rendered TTS at different base pitches (Section 2) */
  pitchCache: PitchCache = {
    low: null,
    mid: null,
    high: null,
  };

  /** Voice pitch parameters for sampler playback */
  rootNote: number = 60; // Base MIDI note (C4 default)
  coarseTune: number = 0; // Coarse tuning in semitones (-24 to +24)
  fineTune: number = 0; // Fine tuning in cents (-50 to +50)
  pitchAttack: number = 0; // Pitch envelope attack time (0-1)
  pitchDecay: number = 0; // Pitch envelope decay time (0-1)
  pitchAmount: number = 0; // Pitch envelope amount (-24 to 24)

  /** Envelope Baseline Tracker for Phoneme-Aware Velocity */
  currentAttack: number = 0.05;
  currentDecay: number = 0.1;

  /** Phoneme aligner for Section 3 implementation */
  phonemeAligner: PhonemeAligner | null = null;

  /** Formant shifter for Section 4 implementation */
  formantShifter: FormantShifter | null = null;

  /** Current formant sidechain depth stored for audio playback retrieval */
  formantSidechainDepth: number = 0;

  /** Last alignment result for current audio */
  lastAlignment: AlignmentResult | null = null;

  /** Pre-stretched buffer pool for phoneme-aware time stretching */
  bufferPool: PhonemeBufferPool | null = null;

  /**
   * Tracks the AudioNode destinations that the worklet is currently wired to.
   * Used so AudioBufferSourceNode (pool playback path) can be connected to the
   * same output chain without re-routing through the Rubber Band worklet.
   */
  outputDestinations: Set<AudioNode> = new Set();

  isActive: boolean = false;
  currentPitch: number | null = null;

  constructor(audioContext: AudioContext, config: SingingVoiceConfig = {}) {
    this.audioContext = audioContext;
    this.config = {
      useHighQuality: config.useHighQuality ?? false,
      preserveFormants: config.preserveFormants ?? true,
      channels: config.channels ?? 1,
      bufferSize: config.bufferSize ?? 16384,
      enablePhonemeStretching: config.enablePhonemeStretching ?? false,
      enableFormantShifting: config.enableFormantShifting ?? false,
      voiceCharacter: config.voiceCharacter ?? "default",
      phonemeAlignerUrl: config.phonemeAlignerUrl,
      enableCtcAlignment: config.enableCtcAlignment ?? config.enablePhonemeStretching ?? false,
      drumSidechainSAB: config.drumSidechainSAB,
    };

    // Initialize phoneme aligner if enabled
    if (this.config.enablePhonemeStretching) {
      this.phonemeAligner = new PhonemeAligner({
        alignerServiceUrl: this.config.phonemeAlignerUrl,
        useLocalAlignment: !this.config.phonemeAlignerUrl,
        enableCtcAlignment: this.config.enableCtcAlignment ?? true,
      });
    }

    // Initialize formant shifter if enabled
    if (this.config.enableFormantShifting) {
      this.formantShifter = new FormantShifter({
        audioContext: this.audioContext,
      });
    }
  }

  /**
   * Get the current configuration.
   * Useful for checking quality settings and other parameters.
   */
  getConfig(): SingingVoiceConfig {
    return { ...this.config };
  }

  /**
   * Update configuration at runtime.
   * Note: Some settings may require re-initialization to take effect.
   */
  setConfig(updates: Partial<SingingVoiceConfig>): void {
    this.config = { ...this.config, ...updates };
  }

  /**
   * Get the output ring buffer instance.
   * Useful for visualizing output or analyzing processed audio on the main thread.
   * @deprecated RingBuffer access removed - use standard AudioWorklet output instead
   */
  get outputRingBuffer(): null {
    return null;
  }

  /**
   * Get the current processor latency in samples.
   * @returns Latency in samples
   */
  getLatency(): number {
    return this.processorLatency;
  }

  /**
   * Get latency in seconds.
   * Useful for MIDI synchronization (Section 9).
   */
  getLatencySeconds(): number {
    return this.processorLatency / this.audioContext.sampleRate;
  }

  /**
   * Get the phoneme aligner for advanced control.
   * Returns null if phoneme stretching is not enabled.
   */
  getPhonemeAligner(): PhonemeAligner | null {
    return this.phonemeAligner;
  }
}

Object.assign(
  SingingVoice.prototype,
  WorkletSetupMixin,
  PitchControlMixin,
  FormantControlMixin,
  EffectsControlMixin,
  PlaybackMixin,
);

import { SingingVoice, type SingingVoiceConfig } from './SingingVoice';
import { playbackHealthMonitor } from '../audio/playback/PlaybackHealthMonitor';
import { VoicePool } from './base/VoicePool';

export class SingingVoiceManager extends VoicePool<SingingVoice> {
    private audioContext: AudioContext;
    private loadedBanks: Map<number, string> = new Map();
    private config: SingingVoiceConfig;
    private drumSidechainSAB: SharedArrayBuffer;

    constructor(audioContext: AudioContext, maxVoices: number = 12, config: SingingVoiceConfig = {}) {
        super(maxVoices);
        this.audioContext = audioContext;
        this.drumSidechainSAB = new SharedArrayBuffer(4 * 4); // 4 floats: [triggerTime, velocity, decay, isSnare]
        this.config = {
            useHighQuality: false,
            preserveFormants: true,
            channels: 1,
            bufferSize: 16384,
            enablePhonemeStretching: true,
            drumSidechainSAB: this.drumSidechainSAB,
            ...config
        };
    }

    public getDrumSidechainSAB(): SharedArrayBuffer {
        return this.drumSidechainSAB;
    }

    async init(
        wasmBinary?: ArrayBuffer,
        onVoiceReady?: (done: number, total: number) => void,
    ): Promise<void> {
        let done = 0;
        const initPromises: Promise<void>[] = [];
        for (let i = 0; i < this.maxVoices; i++) {
            const voice = new SingingVoice(this.audioContext, this.config);
            this.voices.push(voice);
            initPromises.push(
                voice.initWorklet(false, wasmBinary).then(() => {
                    done += 1;
                    onVoiceReady?.(done, this.maxVoices);
                })
            );
        }

        await Promise.all(initPromises);
        console.log(`SingingVoiceManager: Initialized ${this.maxVoices} voices`);
    }

    /**
     * Acquire a free voice or steal the oldest one.
     * Prioritizes voices that already have the requested bank loaded to avoid redundant buffer transfers.
     * @returns The allocated SingingVoice, its index, and whether a new bank load is required.
     */
    protected override getAffinityKey(index: number): string | undefined {
        return this.loadedBanks.get(index);
    }

    protected override onStolen(voice: SingingVoice, index: number, time?: number): void {
        super.onStolen(voice, index, time);
        playbackHealthMonitor.recordVoiceSteal('singingVoice');
    }

    protected override stopVoice(voice: SingingVoice, time?: number): void {
        voice.noteOff(time ?? this.audioContext.currentTime);
    }


    /**
     * Acquire a free voice or steal the oldest one.
     * Prioritizes voices that already have the requested bank loaded to avoid redundant buffer transfers.
     * @returns The allocated SingingVoice, its index, and whether a new bank load is required.
     */
    acquireVoiceForBank(bankId: string, time?: number): { voice: SingingVoice; index: number; isNewBank: boolean } {
        const result = this.acquire({ affinityKey: bankId, steal: 'oldest', time });
        this.markActive(result.index, time);

        if (!result.affinityHit) {
            this.loadedBanks.set(result.index, bankId);
        }

        return {
            voice: result.voice,
            index: result.index,
            isNewBank: !result.affinityHit
        };
    }

    /**
     * Register a voice as active explicitly (used by playback hooks).
     * Note: This is largely redundant now that acquireVoiceForBank calls markActive directly,
     * but retained for backward compatibility with older sequencer patterns.
     */
    registerActiveVoice(index: number, noteId: string, time?: number): void {
        this.markActive(index, time);
    }

    /**
     * Backward compatibility wrapper for old acquireVoice calls.
     */
    acquireVoice(time?: number): { voice: SingingVoice; index: number; isNewBank: boolean } {
        return this.acquireVoiceForBank('__unknown__', time);
    }

    /**
     * Release a specific voice index.
     */
    releaseVoice(index: number) {
        this.markInactive(index);
    }

    /**
     * Get a specific voice by index (for direct access like params update)
     */
    getVoice(index: number): SingingVoice | undefined {
        return this.voices[index];
    }

    /**
     * Get currently active voices.
     * @param outArray Optional array to populate, avoiding transient array allocation.
     */
    getActiveVoices(outArray?: SingingVoice[]): SingingVoice[] {
        const result = outArray || new Array(this.activeIndices.size);
        if (outArray) {
            outArray.length = 0;
        }

        let i = 0;
        for (const index of this.activeIndices) {
            if (outArray) {
                result.push(this.voices[index]!);
            } else {
                result[i++] = this.voices[index]!;
            }
        }
        return result as SingingVoice[];
    }

    override stopAll(time?: number) {
        super.stopAll(time ?? this.audioContext.currentTime);
    }
}

import { type SynthParams } from '../types';
import { tunedNoteToFrequency } from '../constants';
import type { ScaleDefinition } from '../utils/musicTheory';
import { parseWaveform, shapeToOscillatorType, type ParsedWaveform } from '../utils/waveformParser';
import { logEngineFallback, logWaveformSubstitution } from '../utils/engineTelemetry';
import { playbackHealthMonitor } from '../audio/playback/PlaybackHealthMonitor';
import { getOscillatorRegistry } from './backends/BackendRegistry';
import { engineEntry } from './backends/engineCatalog';
import { TABLE_DURATION_SEC, TABLE_REF_FREQ } from './backends/OscillatorBackend';
import { VoicePool, type PoolableVoice } from './base/VoicePool';
import { getPitchOffsetSemitones, transposeFrequency } from '../utils/pitchOffset';

export class Voice implements PoolableVoice {
    context: AudioContext;
    destination: AudioNode;

    // Graph
    private source: OscillatorNode | AudioBufferSourceNode | null = null;
    private filter: BiquadFilterNode;
    private gain: GainNode;
    private dryGain: GainNode;
    private wetGain: GainNode;
    private delay: DelayNode;
    private delayGain: GainNode;
    private panner: StereoPannerNode;

    // State
    isActive: boolean = false;
    currentNote: string = '';
    currentSourceType: string = '';

    private cleanupTimer: any = null;
    private globalDelayNode?: DelayNode;
    private globalDelaySendGain?: GainNode;

    /**
     * Legacy waveform ids already reported this note-on onwards, so a saved
     * song full of retired `rust-*`/`cpp-*` notes reports the substitution once
     * rather than flooding the HUD on every note.
     */
    private static reportedLegacy = new Set<string>();

    /** Reference pitch of the table currently loaded in `source`, for slides. */
    private currentBaseFrequency = TABLE_REF_FREQ;

    constructor(
        context: AudioContext,
        destination: AudioNode,
        globalDelayNode?: DelayNode,
    ) {
        this.context = context;
        this.destination = destination;
        this.globalDelayNode = globalDelayNode;

        // Create permanent nodes
        this.filter = context.createBiquadFilter();
        this.gain = context.createGain();
        this.dryGain = context.createGain();
        this.wetGain = context.createGain();
        this.delay = context.createDelay();
        this.delayGain = context.createGain();
        this.panner = context.createStereoPanner();

        // Connect permanent graph
        this.filter.connect(this.gain);
        this.gain.connect(this.dryGain);
        this.gain.connect(this.delay);
        this.delay.connect(this.delayGain);
        this.delayGain.connect(this.delay); // feedback
        this.delay.connect(this.wetGain);
        this.dryGain.connect(this.panner);
        this.wetGain.connect(this.panner);
        this.panner.connect(destination);

        // Optional global delay send
        if (this.globalDelayNode) {
            this.globalDelaySendGain = context.createGain();
            this.globalDelaySendGain.gain.value = 0;
            this.gain.connect(this.globalDelaySendGain);
            this.globalDelaySendGain.connect(this.globalDelayNode);
        }

        this.gain.gain.value = 0; // start silent
    }

    /**
     * Start a note (attack + sustain) — supports legato sliding
     */
    startNote(
        params: SynthParams,
        note: string,
        time: number,
        slideFromFreq?: number,
        tuning: ScaleDefinition | null = null
    ): void {
        if (params.pan !== undefined) {
            this.panner.pan.setValueAtTime(params.pan, time);
        }

        // Clear any pending cleanup
        if (this.cleanupTimer) {
            clearTimeout(this.cleanupTimer);
            this.cleanupTimer = null;
        }

        const now = time;
        // Module TUNE knob (semitones) transposes the sounding pitch.
        const pitchSemis = getPitchOffsetSemitones(params);
        const freq = transposeFrequency(tunedNoteToFrequency(note, tuning), pitchSemis);
        // Slide source frequencies are computed from the untransposed note, so
        // shift them by the same amount to keep glides in tune.
        const slideFrom = slideFromFreq !== undefined
            ? transposeFrequency(slideFromFreq, pitchSemis)
            : undefined;

        const waveform = params.waveform;
        const parsed = parseWaveform(waveform);
        const canReuse = this.source &&
                        this.isActive &&
                        slideFromFreq !== undefined &&
                        this.currentSourceType === waveform;

        if (canReuse && this.source) {
            // === LEGATO / SLIDE ===
            if (this.source instanceof OscillatorNode) {
                this.source.frequency.cancelScheduledValues(now);
                this.source.frequency.setValueAtTime(slideFrom!, now);
                this.source.frequency.exponentialRampToValueAtTime(freq, now + 0.1);
            } else if (this.source instanceof AudioBufferSourceNode) {
                // The table's own reference pitch, reported by the backend that
                // rendered it — not a hardcoded C4 (Pyodide and the PCM/GPU
                // tables need not agree).
                const baseFreq = this.currentBaseFrequency;
                const startRate = slideFrom! / baseFreq;
                const endRate = freq / baseFreq;
                this.source.playbackRate.cancelScheduledValues(now);
                this.source.playbackRate.setValueAtTime(startRate, now);
                this.source.playbackRate.exponentialRampToValueAtTime(endRate, now + 0.1);
            }

            // Sustain level
            this.gain.gain.cancelScheduledValues(now);
            this.gain.gain.linearRampToValueAtTime(
                Math.max(0.001, params.volume * params.sustain),
                now + 0.05
            );
        } else {
            // === FULL NEW NOTE ===
            this.stop(now);

            let createdSource: OscillatorNode | AudioBufferSourceNode | null = null;
            let baseFrequency = freq;

            // === ENGINE SELECTION ===
            // One story: the catalog names the backend that owns this waveform
            // family, and BackendRegistry walks the single documented fallback
            // order from there, publishing every step it takes. There are no
            // per-prefix `generate()` + looped-buffer branches here any more.
            const rendered = this.renderLoop(parsed, params);
            if (rendered) {
                const src = this.context.createBufferSource();
                src.buffer = rendered.buffer;
                src.loop = true;
                src.playbackRate.value = freq / rendered.baseFrequency;
                createdSource = src;
                baseFrequency = rendered.baseFrequency;
            }

            // Final fallback: JS oscillator using the correct wave family so the
            // user at least hears the right harmonic character while the engine is absent.
            if (!createdSource) {
                const osc = this.context.createOscillator();
                osc.type = shapeToOscillatorType(parsed.shape);
                osc.frequency.value = freq;
                createdSource = osc;
            }

            this.source = createdSource;
            this.currentBaseFrequency = baseFrequency;

            this.currentSourceType = waveform;
            this.source.connect(this.filter);
            this.source.start(now);

            // Filter settings
            this.filter.type = 'lowpass';
            this.filter.frequency.setValueAtTime(params.filterCutoff, now);
            this.filter.Q.value = params.filterResonance;

            // ADSR Attack + Decay
            const attackEnd = now + params.attack;
            const decayEnd = attackEnd + params.decay;

            this.gain.gain.cancelScheduledValues(now);
            this.gain.gain.setValueAtTime(0, now);
            this.gain.gain.linearRampToValueAtTime(params.volume, attackEnd);
            this.gain.gain.exponentialRampToValueAtTime(
                Math.max(0.001, params.volume * params.sustain),
                decayEnd
            );
        }

        // Delay settings
        this.delay.delayTime.value = params.delayTime;
        this.delayGain.gain.value = params.delayFeedback;
        this.wetGain.gain.value = params.delayMix;
        this.dryGain.gain.value = 1 - params.delayMix;

        this.isActive = true;
        this.currentNote = note;
    }

    setDelaySend(amount: number, time?: number): void {
        if (this.globalDelaySendGain) {
            this.globalDelaySendGain.gain.setValueAtTime(
                amount,
                time ?? this.context.currentTime
            );
        }
    }

    stopNote(time: number, params: SynthParams): void {
        if (!this.isActive) return;
        this.scheduleRelease(params, time);
    }

    play(
        params: SynthParams,
        note: string,
        time: number,
        duration: number,
        slideFromFreq?: number,
        tuning: ScaleDefinition | null = null
    ): void {
        this.startNote(params, note, time, slideFromFreq, tuning);
        this.stopNote(time + duration, params);
    }

    private scheduleRelease(params: SynthParams, releaseStart: number): void {
        const releaseEnd = releaseStart + params.release;
        const sustainLevel = Math.max(0.001, params.volume * params.sustain);

        this.gain.gain.cancelScheduledValues(releaseStart);
        this.gain.gain.setValueAtTime(sustainLevel, releaseStart);
        this.gain.gain.exponentialRampToValueAtTime(0.001, releaseEnd);

        if (this.source) {
            try {
                this.source.stop(releaseEnd + 0.1);
            } catch {}
        }

        this.cleanupTimer = setTimeout(() => {
            this.isActive = false;
            this.cleanupTimer = null;
        }, (releaseEnd - this.context.currentTime + 0.2) * 1000);
    }


    /**
     * Render the looped table for `parsed`, entering `BackendRegistry` at the
     * backend the engine catalog names for that family.
     *
     * Returns null when nothing in the chain could service the request — the
     * caller then builds an `OscillatorNode` of the right wave family, which is
     * the documented terminal step (`js`), not a silent substitution.
     */
    private renderLoop(
        parsed: ParsedWaveform,
        params: SynthParams,
    ): { buffer: AudioBuffer; baseFrequency: number } | null {
        if (parsed.legacyFrom && !Voice.reportedLegacy.has(parsed.legacyFrom)) {
            Voice.reportedLegacy.add(parsed.legacyFrom);
            logWaveformSubstitution(
                'oscillators',
                parsed.engine,
                parsed.shape,
                parsed.shape,
                `"${parsed.legacyFrom}" was retired; rendering on ${engineEntry(parsed.engine).label}`,
            );
        }

        const entry = engineEntry(parsed.engine);
        if (entry.kind === 'native-worklet') {
            // 303 / Prophecy voices live in hyphon_native worklets owned by
            // their managers; Voice is never the right renderer for them. Say
            // so rather than quietly producing an OscillatorNode.
            logEngineFallback(
                parsed.engine,
                'wasm-worklet',
                `${entry.label} voices are owned by ${entry.owner}, not VoiceManager`,
            );
            return null;
        }

        const registry = getOscillatorRegistry();
        if (!registry) {
            logEngineFallback(
                parsed.engine,
                entry.backendId,
                'no oscillator backend registry (audio engine not initialized)',
            );
            return null;
        }

        return registry.renderLoopFrom(entry.backendId, this.context, {
            frequency: TABLE_REF_FREQ,
            duration: TABLE_DURATION_SEC,
            sampleRate: this.context.sampleRate,
            shape: parsed.shape,
            cutoff: Math.max(20, Math.min(this.context.sampleRate / 2.1, params.filterCutoff)),
            resonance: Math.max(0.1, params.filterResonance),
        });
    }

    stop(time: number): void {
        if (this.cleanupTimer) {
            clearTimeout(this.cleanupTimer);
            this.cleanupTimer = null;
        }
        if (this.source) {
            try {
                this.source.stop(time);
                this.source.disconnect();
            } catch {}
            this.source = null;
        }
        this.isActive = false;
    }
}

export class VoiceManager extends VoicePool<Voice> {
    private monophonic: boolean;

    constructor(
        context: AudioContext,
        destination: AudioNode,
        polyphony: number,
        monophonic: boolean,
        globalDelayNode?: DelayNode,
    ) {
        super(polyphony);
        this.monophonic = monophonic;
        this.voices = Array.from({ length: this.maxVoices }, () =>
            new Voice(context, destination, globalDelayNode)
        );
    }

    protected override onStolen(voice: Voice, index: number, time?: number): void {
        super.onStolen(voice, index, time);
        playbackHealthMonitor.recordVoiceSteal(this.monophonic ? 'voiceManager-monophonic' : 'voiceManager');
    }

    protected override stopVoice(voice: Voice, time?: number): void {
        voice.stop(time ?? voice.context.currentTime);
    }

    playNote(
        params: SynthParams,
        note: string | string[],
        time: number,
        duration: number,
        slideFromFreq?: number
    ): Voice {
        const noteStr = Array.isArray(note) ? note[0] ?? 'C4' : note;

        if (this.monophonic) {
            const voice = this.voices[0]!;
            voice.play(params, noteStr, time, duration, slideFromFreq);
            return voice;
        }

        const voice = this.pickVoice(time);
        voice.play(params, noteStr, time, duration, slideFromFreq);
        return voice;
    }

    noteOn(params: SynthParams, note: string, time: number, slideFromFreq?: number): Voice {
        const voice = this.pickVoice(time);
        voice.startNote(params, note, time, slideFromFreq);
        return voice;
    }

    noteOff(note: string, time: number, params: SynthParams): void {
        for (let i = 0; i < this.voices.length; i++) {
            const voice = this.voices[i]!;
            if (voice.isActive && voice.currentNote === note) {
                voice.stopNote(time, params);
                this.markInactive(i);
                break;
            }
        }
    }

    override stopAll(time?: number): void {
        super.stopAll(time ?? this.voices[0]?.context.currentTime ?? 0);
    }

    /** Prefer idle voices; stop and steal the round-robin victim when saturated. */
    private pickVoice(time: number): Voice {
        if (this.monophonic) {
            const result = this.acquire({ steal: 'round-robin', time });
            // Since it's monophonic, maxVoices is 1, so index is always 0.
            this.markActive(result.index, time);
            return result.voice;
        }

        const result = this.acquire({ steal: 'round-robin', time });
        this.markActive(result.index, time);
        return result.voice;
    }
}

// @mode: bridge
// @note-for-ai: This is the TypeScript bridge to the AssemblyScript WASM module.
// The heavy DSP logic is in assembly/oscillators.ts. This file handles:
// - WASM loading and initialization (variant selection + capability probe)
// - Memory management (copying data out of WASM memory)
// - Error handling and fallback paths

import initOscillatorsBaseline from '../wasm/oscillators.wasm?init';
import { engineTelemetry, logEngineFallback } from '@/utils/engineTelemetry';

interface OscillatorWasmExports {
    memory: WebAssembly.Memory;
    generate: (
        offset: number,
        rate: number,
        freq: number,
        dur: number,
        type: number,
        cutoff: number,
        resonance: number,
    ) => number;
}

/** Which of the two shipped builds an instance ended up running. */
export type OscillatorVariant = 'relaxed' | 'baseline';

/**
 * Minimal module that only validates on an engine with relaxed SIMD:
 *
 *   (module (func (result v128)
 *     i32.const 0  i8x16.splat
 *     i32.const 0  i8x16.splat
 *     i8x16.relaxed_swizzle))
 *
 * `i8x16.relaxed_swizzle` is 0xFD 0x80 0x02 (prefixed opcode 256).
 *
 * Feature detection has to happen here, in the engine wrapper, and not in a
 * worklet: an unsupported instruction is a `CompileError` raised by
 * `WebAssembly.compile`/`validate`, i.e. before any worklet exists to fall back.
 */
const RELAXED_SIMD_PROBE = new Uint8Array([
    0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00, // magic + version
    0x01, 0x05, 0x01, 0x60, 0x00, 0x01, 0x7b,       // type: () -> v128
    0x03, 0x02, 0x01, 0x00,                         // func 0 : type 0
    0x0a, 0x0f, 0x01, 0x0d, 0x00,                   // code section, 1 body, 0 locals
    0x41, 0x00, 0xfd, 0x0f,                         // i32.const 0; i8x16.splat
    0x41, 0x00, 0xfd, 0x0f,                         // i32.const 0; i8x16.splat
    0xfd, 0x80, 0x02,                               // i8x16.relaxed_swizzle
    0x0b,                                           // end
]);

let relaxedSimdSupport: boolean | null = null;

/**
 * Cached capability probe for relaxed SIMD. Safe to call before any AudioContext.
 *
 * Nothing selects on this today — see `loadOrder()`. It is reported to telemetry
 * so the question "is a relaxed-SIMD kernel worth building?" can be answered from
 * field data rather than guessed.
 */
export function supportsRelaxedSimd(): boolean {
    if (relaxedSimdSupport !== null) return relaxedSimdSupport;
    try {
        relaxedSimdSupport =
            typeof WebAssembly !== 'undefined' &&
            typeof WebAssembly.validate === 'function' &&
            WebAssembly.validate(RELAXED_SIMD_PROBE);
    } catch {
        relaxedSimdSupport = false;
    }
    return relaxedSimdSupport;
}

/** Test seam: forget the cached probe result. */
export function resetRelaxedSimdProbe(): void {
    relaxedSimdSupport = null;
}

type WasmInit = typeof initOscillatorsBaseline;

/**
 * Candidate builds, most-preferred first.
 *
 * There is exactly one today, and that is a measured decision, not an oversight.
 * `assembly/oscillators.ts` is scalar — it contains no SIMD intrinsics — so
 * building it a second time with `--enable relaxed-simd` produced a byte-identical
 * module (same SHA-256); asc never emits a relaxed instruction that is not written.
 * A relaxed sibling would have been a duplicate artifact and a second download for
 * no measurable win. See docs/wasm/BUILD_NOTES.md#assemblyscript-browser-matrix.
 *
 * To add one when a relaxed kernel actually exists: add a `build:wasm:*` script
 * emitting `src/wasm/oscillators.relaxed.wasm`, register it in
 * `scripts/native-worlds.mjs` (so the artifact is always built and the static
 * import below can never be a missing asset), import it, and prepend it here
 * guarded by `supportsRelaxedSimd()`. The retry loop in `init()` already handles
 * the fallback.
 */
function loadOrder(): Array<{ variant: OscillatorVariant; init: WasmInit }> {
    return [{ variant: 'baseline', init: initOscillatorsBaseline }];
}

const typeMap = { saw: 0, sqr: 1, tri: 2, sin: 3 };

export class WasmOscillator {
    private instance: WebAssembly.Instance | null = null;
    private memory: WebAssembly.Memory | null = null;
    isReady: boolean = false;
    /** Which build is live, or null until a successful init(). */
    variant: OscillatorVariant | null = null;

    async init() {
        const attempts = loadOrder();
        const failures: string[] = [];

        for (const { variant, init } of attempts) {
            try {
                this.instance = await init({ env: { abort: () => {} } });
                this.memory = this.instance.exports.memory as WebAssembly.Memory;
                this.variant = variant;
                this.isReady = true;
                try {
                    engineTelemetry.registerResolution(
                        'wam',
                        'wasm',
                        `loaded:${variant} relaxed-simd=${supportsRelaxedSimd()}`,
                    );
                } catch (_) { /* telemetry is best-effort */ }
                return;
            } catch (e) {
                // Try the next candidate rather than going silent — silence is the
                // failure mode a hard-failing feature module produces on old Safari,
                // and it is the one thing this loader exists to prevent.
                this.instance = null;
                this.memory = null;
                failures.push(`${variant}: ${e instanceof Error ? e.message : String(e)}`);
            }
        }

        logEngineFallback(
            'wam',
            'wasm',
            `AssemblyScript oscillators.wasm instantiation failed (${failures.join('; ')})`,
            failures[failures.length - 1],
        );
    }

    generate(
        freq: number,
        dur: number,
        rate: number,
        type: 'saw' | 'sqr' | 'tri' | 'sin',
        cutoff: number,
        resonance: number
    ): Float32Array | null {
        if (!this.isReady || !this.instance || !this.memory) return null;

        const exports = this.instance.exports as unknown as OscillatorWasmExports;

        // Constraints
        const safeCutoff = Math.max(20, Math.min(rate / 2.1, cutoff));
        const safeRes = Math.max(0.1, resonance);

        // Generate
        // We use offset 0 in the shared memory
        const numSamples = exports.generate(0, rate, freq, dur, typeMap[type], safeCutoff, safeRes);

        // Copy the data out safely by explicitly allocating the returned array size
        // If we don't copy, the view changes when the next note is generated!
        // Bolt Optimization: Avoiding .slice() which creates an intermediate view
        const out = new Float32Array(numSamples);
        out.set(new Float32Array(this.memory.buffer, 0, numSamples));
        return out;
    }
}

