import { describe, it, expect, beforeEach, vi } from 'vitest';
import { BackendRegistry, OSCILLATOR_SUBSYSTEM } from '../BackendRegistry';
import {
    BACKEND_FALLBACK_ORDER,
    type BackendCapabilities,
    type GenerateRequest,
    type InitResult,
    type LoopRender,
    type OscillatorBackend,
    type OscillatorBackendId,
} from '../OscillatorBackend';
import { JsOscillatorBackend } from '../adapters';
import { engineTelemetry } from '../../../utils/engineTelemetry';
import { engineDegradationStore } from '../../../stores/engineDegradationStore';
import type { WaveShape } from '../../../utils/waveformParser';

/** Configurable stub honouring the shared contract — no `as any` anywhere. */
class StubBackend implements OscillatorBackend {
    readonly label: string;
    isSupported: boolean;
    isReady: boolean;
    generateResult: Float32Array | null;
    throwOnGenerate = false;
    generateCalls = 0;

    readonly id: OscillatorBackendId;

    constructor(
        id: OscillatorBackendId,
        opts: {
            supported?: boolean;
            ready?: boolean;
            shapes?: readonly WaveShape[];
            result?: Float32Array | null;
        } = {},
    ) {
        this.id = id;
        this.label = id;
        this.isSupported = opts.supported ?? true;
        this.isReady = opts.ready ?? true;
        this.capabilities = {
            simd: false,
            threads: false,
            offline: true,
            polyphony: 8,
            shapes: opts.shapes ?? ['saw', 'sqr', 'tri', 'sin'],
        };
        this.generateResult = opts.result !== undefined ? opts.result : new Float32Array([1, -1, 1, -1]);
    }

    capabilities: BackendCapabilities;

    async init(): Promise<InitResult> {
        return { ok: this.isReady, backendId: this.id };
    }

    supportsShape(shape: WaveShape): boolean {
        return this.capabilities.shapes.includes(shape);
    }

    async generate(_req: GenerateRequest): Promise<Float32Array | null> {
        this.generateCalls++;
        if (this.throwOnGenerate) throw new Error('boom');
        return this.generateResult;
    }

    renderLoopCalls = 0;

    renderLoop(ctx: BaseAudioContext, _req: GenerateRequest): LoopRender | null {
        this.renderLoopCalls++;
        if (this.throwOnGenerate) throw new Error('boom');
        if (!this.generateResult || !this.generateResult.length) return null;
        const buffer = ctx.createBuffer(1, this.generateResult.length, 44100);
        buffer.getChannelData(0).set(this.generateResult);
        return { buffer, baseFrequency: 261.63 };
    }

    dispose(): void {
        this.isReady = false;
    }
}

const REQ: GenerateRequest = {
    frequency: 261.63,
    duration: 0.05,
    sampleRate: 44100,
    shape: 'saw',
    cutoff: 8000,
    resonance: 1,
};

describe('BackendRegistry ordering', () => {
    beforeEach(() => {
        engineDegradationStore.clear('oscillator-backend');
        vi.restoreAllMocks();
    });

    it('exposes the documented WebGPU → wam → rust → wav → js chain', () => {
        expect(BACKEND_FALLBACK_ORDER).toEqual(['webgpu', 'wam', 'pyodide', 'wav', 'js']);
    });

    it('orders registered backends by preference, not registration order', () => {
        const registry = new BackendRegistry();
        registry.register(new StubBackend('js'));
        registry.register(new StubBackend('webgpu'));
        registry.register(new StubBackend('pyodide'));
        expect(registry.ordered().map((b) => b.id)).toEqual(['webgpu', 'pyodide', 'js']);
    });

    it('selects the highest-preference backend that is supported and ready', () => {
        const registry = new BackendRegistry();
        registry.register(new StubBackend('webgpu', { supported: false }));
        registry.register(new StubBackend('wam', { ready: false }));
        registry.register(new StubBackend('pyodide'));
        registry.register(new JsOscillatorBackend());

        const resolution = registry.resolve();
        expect(resolution.active).toBe('pyodide');
        expect(resolution.requested).toBe('webgpu');
        expect(resolution.degraded).toBe(true);
        expect(resolution.reason).toContain('webgpu: unsupported in this environment');
        expect(resolution.reason).toContain('wam: not initialized');
    });

    it('is not degraded when the preferred backend is usable', () => {
        const registry = new BackendRegistry();
        registry.register(new StubBackend('webgpu'));
        registry.register(new JsOscillatorBackend());
        const resolution = registry.resolve();
        expect(resolution.active).toBe('webgpu');
        expect(resolution.degraded).toBe(false);
        expect(resolution.reason).toBeUndefined();
    });

    it('skips backends that cannot render the requested shape natively', () => {
        const registry = new BackendRegistry();
        registry.register(new StubBackend('pyodide', { shapes: ['saw', 'sqr'] }));
        registry.register(new JsOscillatorBackend());

        expect(registry.resolve('saw').active).toBe('pyodide');

        const tri = registry.resolve('tri');
        expect(tri.active).toBe('js');
        expect(tri.reason).toContain('does not render "tri" natively');
    });

    it('always resolves to js rather than returning nothing', () => {
        const registry = new BackendRegistry();
        registry.register(new StubBackend('webgpu', { supported: false }));
        registry.register(new JsOscillatorBackend());
        expect(registry.resolve().active).toBe('js');
    });
});

describe('BackendRegistry fallback is always logged and surfaced', () => {
    beforeEach(() => {
        engineDegradationStore.clear('oscillator-backend');
    });

    it('records a telemetry resolution and a degradation store issue on fallback', () => {
        const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
        const registry = new BackendRegistry();
        registry.register(new StubBackend('webgpu', { supported: false }));
        registry.register(new JsOscillatorBackend());

        const resolution = registry.resolveAndPublish();
        expect(resolution.active).toBe('js');

        const snapshot = engineTelemetry.snapshot();
        expect(snapshot[OSCILLATOR_SUBSYSTEM]?.resolution?.backend).toBe('js');
        expect(snapshot[OSCILLATOR_SUBSYSTEM]?.resolution?.reason).toContain('webgpu');

        const issue = engineDegradationStore.getIssue('oscillator-backend');
        expect(issue).toBeDefined();
        expect(issue?.activeBackend).toBe('js');
        expect(issue?.requestedBackend).toBe('webgpu');
        expect(issue?.status).toBe('active');

        expect(warn).toHaveBeenCalled();
        expect(warn.mock.calls.some(([msg]) => String(msg).includes('fell back'))).toBe(true);
        warn.mockRestore();
    });

    it('clears the degradation issue when the preferred backend is active', () => {
        const registry = new BackendRegistry();
        registry.register(new StubBackend('webgpu'));
        registry.register(new JsOscillatorBackend());
        registry.resolveAndPublish();
        expect(engineDegradationStore.getIssue('oscillator-backend')?.status).not.toBe('active');
    });
});

describe('BackendRegistry.generate', () => {
    beforeEach(() => {
        engineDegradationStore.clear('oscillator-backend');
    });

    it('falls through to the next backend when one returns no samples', async () => {
        const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
        const gpu = new StubBackend('webgpu', { result: new Float32Array(0) });
        const fallbackBackend = new StubBackend('pyodide');
        const registry = new BackendRegistry();
        registry.register(gpu);
        registry.register(fallbackBackend);

        const out = await registry.generate(REQ);
        expect(out?.backendId).toBe('pyodide');
        expect(gpu.generateCalls).toBe(1);
        expect(fallbackBackend.generateCalls).toBe(1);
        expect(engineDegradationStore.getIssue('oscillator-backend')?.activeBackend).toBe('pyodide');
        warn.mockRestore();
    });

    it('falls through when a backend throws, and records the error', async () => {
        const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
        const gpu = new StubBackend('webgpu');
        gpu.throwOnGenerate = true;
        const registry = new BackendRegistry();
        registry.register(gpu);
        registry.register(new StubBackend('js'));

        const out = await registry.generate(REQ);
        expect(out?.backendId).toBe('js');
        expect(engineTelemetry.snapshot()[OSCILLATOR_SUBSYSTEM]?.errors.count).toBeGreaterThan(0);
        warn.mockRestore();
    });

    it('reports null (loudly) when nothing can render the request', async () => {
        const err = vi.spyOn(console, 'error').mockImplementation(() => {});
        const registry = new BackendRegistry();
        registry.register(new StubBackend('pyodide', { shapes: ['saw'] }));
        const out = await registry.generate({ ...REQ, shape: 'tri' });
        expect(out).toBeNull();
        expect(err).toHaveBeenCalled();
        err.mockRestore();
    });
});


/**
 * `renderLoopFrom` is the realtime entry point that replaced VoiceManager's
 * per-prefix ladder (#1294) — it must honour the same single fallback order.
 */
describe('BackendRegistry.renderLoopFrom', () => {
    // Minimal BaseAudioContext: renderLoopFrom only ever needs createBuffer.
    const ctx = {
        sampleRate: 44100,
        createBuffer: (channels: number, length: number, sampleRate: number) => {
            const data = new Float32Array(length);
            return {
                length,
                numberOfChannels: channels,
                sampleRate,
                getChannelData: () => data,
            } as unknown as AudioBuffer;
        },
    } as unknown as BaseAudioContext;

    beforeEach(() => {
        engineDegradationStore.clear('oscillator-backend');
    });

    it('enters the chain at the requested backend and never climbs back up', () => {
        const gpu = new StubBackend('webgpu');
        const wav = new StubBackend('wav');
        const registry = new BackendRegistry();
        registry.register(gpu);
        registry.register(wav);
        registry.register(new JsOscillatorBackend());

        expect(registry.renderLoopFrom('wav', ctx, REQ)).not.toBeNull();
        // Selecting wav-* must not silently promote the note to the GPU engine.
        expect(gpu.renderLoopCalls).toBe(0);
        expect(wav.renderLoopCalls).toBe(1);
    });

    it('drops to the next backend down and reports the degradation', () => {
        const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
        const wam = new StubBackend('wam', { ready: false });
        const wav = new StubBackend('wav');
        const registry = new BackendRegistry();
        registry.register(wam);
        registry.register(wav);

        expect(registry.renderLoopFrom('wam', ctx, REQ)).not.toBeNull();
        const issue = engineDegradationStore.getIssue('oscillator-backend');
        expect(issue?.requestedBackend).toBe('wam');
        expect(issue?.activeBackend).toBe('wav');
        warn.mockRestore();
    });

    it('returns null for the terminal js step, and still publishes it', () => {
        const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
        const registry = new BackendRegistry();
        registry.register(new StubBackend('wam', { ready: false }));
        registry.register(new JsOscillatorBackend());

        // js has no renderLoop: the caller builds an OscillatorNode instead.
        expect(registry.renderLoopFrom('wam', ctx, REQ)).toBeNull();
        expect(engineDegradationStore.getIssue('oscillator-backend')?.activeBackend).toBe('js');
        warn.mockRestore();
    });

    it('survives a backend that throws and keeps walking', () => {
        const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
        const wam = new StubBackend('wam');
        wam.throwOnGenerate = true;
        const wav = new StubBackend('wav');
        const registry = new BackendRegistry();
        registry.register(wam);
        registry.register(wav);

        expect(registry.renderLoopFrom('wam', ctx, REQ)).not.toBeNull();
        expect(wav.renderLoopCalls).toBe(1);
        warn.mockRestore();
    });
});

/**
 * Integration coverage for the oscillator fallback path (#1034).
 *
 * Uses the real adapters and the real registry — only the concrete engines are
 * stubbed, because WebGPU/WASM cannot run under jsdom. It proves the whole
 * chain end to end: engines fail to init → registry drops down the preference
 * order → the fallback is logged, recorded in telemetry, and raised in the
 * degradation store that feeds the HUD and banner.
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { BackendRegistry, OSCILLATOR_SUBSYSTEM } from '../BackendRegistry';
import {
    JsOscillatorBackend,
    PyodideBackend,
    WamWasmBackend,
    WavPcmBackend,
    WebGpuBackend,
} from '../adapters';
import type { WebGpuOscillator } from '../../WebGpuOscillator';
import type { WasmOscillator } from '../../WasmOscillator';
import type { PyodideLike } from '../../../utils/pyodideBuffers';
import { engineTelemetry } from '../../../utils/engineTelemetry';
import { engineDegradationStore } from '../../../stores/engineDegradationStore';
import type { GenerateRequest } from '../OscillatorBackend';

function stubGpu(supported: boolean): WebGpuOscillator {
    const engine = {
        isSupported: false,
        init: vi.fn(async () => {
            engine.isSupported = supported;
        }),
        generate: vi.fn(async () => new Float32Array([0.5, -0.5, 0.5, -0.5])),
        destroy: vi.fn(),
    };
    return engine as unknown as WebGpuOscillator;
}

function stubWasm(ready: boolean): WasmOscillator {
    const engine = {
        isReady: false,
        init: vi.fn(async () => {
            engine.isReady = ready;
        }),
        generate: vi.fn(() => new Float32Array([0.25, -0.25, 0.25, -0.25])),
    };
    return engine as unknown as WasmOscillator;
}

/** A Pyodide runtime whose `generate_loop_buffer` returns a short saw. */
function stubPyodide(): PyodideLike {
    return {
        globals: {
            get: (name: string) =>
                name === 'set_sample_rate'
                    ? () => undefined
                    : () => ({
                          toJs: () => new Float32Array([0.1, -0.1, 0.1, -0.1]),
                          destroy: () => undefined,
                      }),
        },
    } as unknown as PyodideLike;
}

/** Mirrors how engineLifecycle assembles the chain. */
/** A BaseAudioContext stub good enough for the GPU pre-render and PCM tables. */
function makeCtx(): AudioContext {
    return {
        sampleRate: 44100,
        createBuffer: (channels: number, length: number, sampleRate: number) => {
            const data = new Float32Array(length);
            return {
                length,
                numberOfChannels: channels,
                sampleRate,
                getChannelData: () => data,
            } as unknown as AudioBuffer;
        },
    } as unknown as AudioContext;
}

/** Mirrors how engineLifecycle assembles the chain. */
async function buildChain(opts: {
    gpu: boolean;
    wam: boolean;
    pyodide?: boolean;
    wavBuffer?: AudioBuffer | null;
}) {
    const registry = new BackendRegistry();
    const ctx = makeCtx();
    const gpuBackend = new WebGpuBackend(stubGpu(opts.gpu));
    const wamBackend = new WamWasmBackend(stubWasm(opts.wam));
    const pyodideBackend = new PyodideBackend(opts.pyodide ? stubPyodide() : null);
    const wavBackend = new WavPcmBackend({ saw: opts.wavBuffer ?? null });

    registry.register(gpuBackend);
    registry.register(wamBackend);
    registry.register(pyodideBackend);
    registry.register(wavBackend);
    registry.register(new JsOscillatorBackend());

    await registry.initAll(ctx);
    return { registry, ctx, gpuBackend, wamBackend, pyodideBackend, wavBackend };
}

const REQ: GenerateRequest = {
    frequency: 220,
    duration: 0.02,
    sampleRate: 44100,
    shape: 'saw',
    cutoff: 6000,
    resonance: 1.2,
};

describe('oscillator backend fallback (integration)', () => {
    let warn: ReturnType<typeof vi.spyOn>;

    beforeEach(() => {
        engineDegradationStore.clear('oscillator-backend');
        warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
    });

    it('selects WebGPU when the GPU device initializes', async () => {
        const { registry } = await buildChain({ gpu: true, wam: true });
        const resolution = registry.resolveAndPublish();

        expect(resolution.active).toBe('webgpu');
        expect(resolution.degraded).toBe(false);
        expect(engineDegradationStore.getIssue('oscillator-backend')?.status).not.toBe('active');
    });

    it('falls back GPU → AS WASM when only the GPU is unavailable, and says so', async () => {
        const { registry } = await buildChain({ gpu: false, wam: true });
        const resolution = registry.resolveAndPublish();

        expect(resolution.active).toBe('wam');
        expect(resolution.degraded).toBe(true);
        expect(resolution.reason).toContain('webgpu');

        const issue = engineDegradationStore.getIssue('oscillator-backend');
        expect(issue?.status).toBe('active');
        expect(issue?.activeBackend).toBe('wam');
        expect(issue?.message).toContain('WASM OSC');
    });

    it('walks the full chain to the JS oscillator when every engine fails', async () => {
        const { registry } = await buildChain({ gpu: false, wam: false });
        const resolution = registry.resolveAndPublish();

        expect(resolution.active).toBe('js');
        expect(resolution.attempts.map((a) => a.id)).toEqual(['webgpu', 'wam', 'pyodide', 'wav', 'js']);
        for (const id of ['webgpu', 'wam', 'pyodide', 'wav']) {
            expect(resolution.attempts.find((a) => a.id === id)?.reason).toBeTruthy();
        }

        // Logged …
        expect(warn.mock.calls.some(([m]) => String(m).includes('fell back'))).toBe(true);
        // … recorded in telemetry …
        const snapshot = engineTelemetry.snapshot();
        expect(snapshot[OSCILLATOR_SUBSYSTEM]?.resolution?.backend).toBe('js');
        // … and shown to the user via the degradation store (HUD + banner source).
        expect(engineDegradationStore.getIssue('oscillator-backend')?.activeBackend).toBe('js');
    });

    it('still produces audible samples of the right wave family on the fallback path', async () => {
        const { registry } = await buildChain({ gpu: false, wam: false });
        const out = await registry.generate(REQ);

        expect(out).not.toBeNull();
        expect(out!.backendId).toBe('js');
        expect(out!.samples.length).toBe(Math.ceil(REQ.sampleRate * REQ.duration));
        // A saw ramps monotonically inside a cycle and spans roughly [-1, 1].
        expect(Math.max(...out!.samples)).toBeGreaterThan(0.9);
        expect(Math.min(...out!.samples)).toBeLessThan(-0.9);
    });

    it('skips the PCM backend for shapes it has no asset for, rather than substituting', async () => {
        const table = {
            length: 4,
            numberOfChannels: 1,
            sampleRate: 44100,
            getChannelData: () => new Float32Array([1, -1, 1, -1]),
        } as unknown as AudioBuffer;
        const { registry, wavBackend } = await buildChain({ gpu: false, wam: false, wavBuffer: table });

        expect(registry.resolve('saw').active).toBe('wav');

        const tri = registry.resolve('tri');
        expect(tri.active).toBe('js');
        expect(tri.reason).toContain('wav: does not render "tri" natively');
        expect(await wavBackend.generate({ ...REQ, shape: 'tri' })).toBeNull();
    });

    /**
     * The realtime entry point (#1294): a family enters the chain at its own
     * backend and can only ever fall *down*.
     */
    it('renders a wav-* note from the PCM backend without touching the GPU', async () => {
        const table = {
            length: 4,
            numberOfChannels: 1,
            sampleRate: 44100,
            getChannelData: () => new Float32Array([1, -1, 1, -1]),
        } as unknown as AudioBuffer;
        const { registry, ctx, gpuBackend } = await buildChain({
            gpu: true,
            wam: true,
            wavBuffer: table,
        });

        const render = registry.renderLoopFrom('wav', ctx, REQ);
        expect(render?.buffer).toBe(table);
        expect(gpuBackend.renderLoop(ctx, REQ)).not.toBeNull(); // GPU was usable …
        expect(registry.getLastResolution()?.active).not.toBe('webgpu'); // … but unused.
    });

    it('keeps voices audible when the session WebGPU probe fails', async () => {
        const { probeWebGPU, resetWebGpuProbeForTests, getLastWebGpuProbe } = await import('../webgpuProbe');
        resetWebGpuProbeForTests();
        vi.stubGlobal('navigator', { gpu: undefined });
        const probe = await probeWebGPU();
        expect(probe.ok).toBe(false);

        const { registry } = await buildChain({ gpu: false, wam: true });
        const out = await registry.generate(REQ);

        expect(getLastWebGpuProbe()?.ok).toBe(false);
        expect(out).not.toBeNull();
        expect(out!.backendId).toBe('wam');
        expect(out!.samples.length).toBeGreaterThan(0);
        vi.unstubAllGlobals();
    });
});

/**
 * Adapters wrapping each concrete oscillator engine in the shared
 * `OscillatorBackend` contract (#1034).
 *
 * The adapters own no DSP — they normalize readiness, capabilities and the
 * generate signature so lifecycle/selection code has exactly one shape to
 * talk to. Engines keep their existing public API for direct callers
 * (VoiceManager still calls `wasmEngine.generate(...)` on the hot path).
 */

import type { WebGpuOscillator } from '../WebGpuOscillator';
import type { WasmOscillator } from '../WasmOscillator';
import { shapeToOscillatorType, type WaveShape } from '../../utils/waveformParser';
import { engineTelemetry } from '../../utils/engineTelemetry';
import {
    PYODIDE_REF_FREQ,
    generatePyodideLoopBuffer,
    type PyodideLike,
} from '../../utils/pyodideBuffers';
import type {
    BackendCapabilities,
    GenerateRequest,
    InitResult,
    LoopRender,
    OscillatorBackend,
    OscillatorBackendId,
} from './OscillatorBackend';
import { BACKEND_LABELS, TABLE_DURATION_SEC, TABLE_REF_FREQ } from './OscillatorBackend';

const ALL_SHAPES: readonly WaveShape[] = ['saw', 'sqr', 'tri', 'sin'];


/** Shared plumbing: id/label, init bookkeeping, telemetry-safe helpers. */
abstract class BaseBackend implements OscillatorBackend {
    abstract readonly id: OscillatorBackendId;
    abstract readonly capabilities: BackendCapabilities;

    protected initialized = false;
    protected failureReason: string | null = null;

    get label(): string {
        return BACKEND_LABELS[this.id];
    }

    abstract get isSupported(): boolean;

    get isReady(): boolean {
        return this.initialized && this.isSupported;
    }

    supportsShape(shape: WaveShape): boolean {
        return this.capabilities.shapes.includes(shape);
    }

    abstract init(ctx: AudioContext): Promise<InitResult>;
    abstract generate(req: GenerateRequest): Promise<Float32Array | null>;

    dispose(): void {
        this.initialized = false;
    }

    protected ok(reason?: string): InitResult {
        this.initialized = true;
        this.failureReason = null;
        return { ok: true, backendId: this.id, reason };
    }

    protected fail(reason: string): InitResult {
        this.initialized = false;
        this.failureReason = reason;
        return { ok: false, backendId: this.id, reason };
    }

    /** Latency recording must never break audio init. */
    protected timed<T>(fn: () => T): T {
        const t0 = typeof performance !== 'undefined' ? performance.now() : 0;
        const out = fn();
        try {
            if (typeof performance !== 'undefined') {
                engineTelemetry.recordLatency(`oscillator-${this.id}`, performance.now() - t0);
            }
        } catch {
            /* telemetry is best-effort */
        }
        return out;
    }
}

export class WebGpuBackend extends BaseBackend {
    readonly id = 'webgpu' as const;
    readonly capabilities: BackendCapabilities = {
        simd: false,
        threads: true,
        offline: true,
        polyphony: 64,
        shapes: ALL_SHAPES,
    };

    private readonly engine: WebGpuOscillator;
    /**
     * GPU rendering is async and the note path is not, so the four shape tables
     * are pre-rendered once during `init()` and looped from cache afterwards.
     * Before this, `VoiceManager` read a `wgslBuffers` dependency that nothing
     * ever populated — every `wgsl-*` note fell through to `OscillatorNode`.
     */
    private tables: Partial<Record<WaveShape, AudioBuffer>> = {};

    constructor(engine: WebGpuOscillator) {
        super();
        this.engine = engine;
    }

    /** Exposed so lifecycle code can keep handing the raw engine to consumers. */
    get raw(): WebGpuOscillator {
        return this.engine;
    }

    get isSupported(): boolean {
        return this.engine.isSupported;
    }

    /** Only ready once at least one table is actually on hand. */
    get isReady(): boolean {
        return this.initialized && this.isSupported && ALL_SHAPES.some((s) => !!this.tables[s]);
    }

    supportsShape(shape: WaveShape): boolean {
        return !!this.tables[shape];
    }

    async init(ctx?: AudioContext): Promise<InitResult> {
        try {
            await this.engine.init();
        } catch (e) {
            return this.fail(`WebGpuOscillator.init() threw: ${e instanceof Error ? e.message : String(e)}`);
        }
        if (!this.engine.isSupported) {
            return this.fail('WebGPU unavailable (no adapter/device)');
        }
        if (!ctx) {
            return this.fail('no AudioContext — cannot pre-render GPU wavetables');
        }
        const rendered = await this.prerenderTables(ctx);
        return rendered > 0
            ? this.ok(`device-ready (${rendered}/${ALL_SHAPES.length} tables)`)
            : this.fail('GPU device ready but no wavetable could be rendered');
    }

    /** Render every shape once; returns how many succeeded. */
    private async prerenderTables(ctx: AudioContext): Promise<number> {
        let count = 0;
        for (const shape of ALL_SHAPES) {
            try {
                const samples = await this.engine.generate(
                    TABLE_REF_FREQ,
                    TABLE_DURATION_SEC,
                    ctx.sampleRate,
                    shape,
                );
                if (samples && samples.length) {
                    const buffer = ctx.createBuffer(1, samples.length, ctx.sampleRate);
                    buffer.getChannelData(0).set(samples);
                    this.tables[shape] = buffer;
                    count++;
                }
            } catch (e) {
                console.warn(`[WebGpuBackend] pre-render of "${shape}" failed`, e);
            }
        }
        return count;
    }

    renderLoop(_ctx: BaseAudioContext, req: GenerateRequest): LoopRender | null {
        if (!this.isReady) return null;
        const buffer = this.tables[req.shape];
        return buffer ? { buffer, baseFrequency: TABLE_REF_FREQ } : null;
    }

    async generate(req: GenerateRequest): Promise<Float32Array | null> {
        if (!this.isReady) return null;
        const t0 = typeof performance !== 'undefined' ? performance.now() : 0;
        const out = await this.engine.generate(req.frequency, req.duration, req.sampleRate, req.shape);
        try {
            if (typeof performance !== 'undefined') {
                engineTelemetry.recordLatency('oscillator-webgpu', performance.now() - t0);
            }
        } catch {
            /* best-effort */
        }
        return out;
    }

    dispose(): void {
        super.dispose();
        this.tables = {};
        this.engine.destroy();
    }
}

export class WamWasmBackend extends BaseBackend {
    readonly id = 'wam' as const;
    readonly capabilities: BackendCapabilities = {
        simd: true,
        threads: false,
        offline: true,
        polyphony: 16,
        shapes: ALL_SHAPES,
    };

    private readonly engine: WasmOscillator;

    constructor(engine: WasmOscillator) {
        super();
        this.engine = engine;
    }

    get raw(): WasmOscillator {
        return this.engine;
    }

    get isSupported(): boolean {
        return typeof WebAssembly !== 'undefined';
    }

    async init(_ctx?: AudioContext): Promise<InitResult> {
        if (!this.isSupported) return this.fail('WebAssembly unavailable');
        try {
            await this.engine.init();
        } catch (e) {
            return this.fail(`WasmOscillator.init() threw: ${e instanceof Error ? e.message : String(e)}`);
        }
        return this.engine.isReady
            ? this.ok('loaded')
            : this.fail('oscillators.wasm instantiation failed');
    }

    get isReady(): boolean {
        return this.initialized && this.engine.isReady;
    }

    generate(req: GenerateRequest): Promise<Float32Array | null> {
        return Promise.resolve(this.generateSync(req));
    }

    /** The AS kernel is synchronous, so the realtime path can call it inline. */
    private generateSync(req: GenerateRequest): Float32Array | null {
        if (!this.isReady) return null;
        return this.timed(() =>
            this.engine.generate(
                req.frequency,
                req.duration,
                req.sampleRate,
                req.shape,
                req.cutoff,
                req.resonance,
            ),
        );
    }

    renderLoop(ctx: BaseAudioContext, req: GenerateRequest): LoopRender | null {
        // Render one table at the reference pitch and resample via playbackRate,
        // rather than re-rendering per note.
        const samples = this.generateSync({
            ...req,
            frequency: TABLE_REF_FREQ,
            duration: TABLE_DURATION_SEC,
        });
        return samples ? toLoopBuffer(ctx, samples, TABLE_REF_FREQ) : null;
    }
}

/**
 * Pre-decoded WAV/PCM single-cycle tables. Only saw and square exist as assets,
 * matching the buffers loaded in engineLifecycle.
 */
export class WavPcmBackend extends BaseBackend {
    readonly id = 'wav' as const;
    readonly capabilities: BackendCapabilities = {
        simd: false,
        threads: false,
        offline: true,
        polyphony: Number.POSITIVE_INFINITY,
        shapes: ['saw', 'sqr'],
    };

    private buffers: Partial<Record<WaveShape, AudioBuffer | null>> = {};

    constructor(buffers: Partial<Record<WaveShape, AudioBuffer | null>> = {}) {
        super();
        this.buffers = buffers;
    }

    setBuffers(buffers: Partial<Record<WaveShape, AudioBuffer | null>>): void {
        this.buffers = { ...this.buffers, ...buffers };
    }

    get isSupported(): boolean {
        return this.capabilities.shapes.some((s) => !!this.buffers[s]);
    }

    async init(_ctx?: AudioContext): Promise<InitResult> {
        return this.isSupported ? this.ok('pcm-tables-loaded') : this.fail('no WAV tables decoded');
    }

    supportsShape(shape: WaveShape): boolean {
        return this.capabilities.shapes.includes(shape) && !!this.buffers[shape];
    }

    async generate(req: GenerateRequest): Promise<Float32Array | null> {
        if (!this.isReady || !this.supportsShape(req.shape)) return null;
        const buf = this.buffers[req.shape];
        if (!buf) return null;
        // PCM tables are fixed-rate assets; hand back the raw channel data and
        // let the caller resample via playbackRate (as Voice already does).
        return buf.getChannelData(0).slice();
    }

    renderLoop(_ctx: BaseAudioContext, req: GenerateRequest): LoopRender | null {
        if (!this.isReady || !this.supportsShape(req.shape)) return null;
        const buffer = this.buffers[req.shape];
        // Decoded asset — reused as-is, no per-note copy.
        return buffer ? { buffer, baseFrequency: TABLE_REF_FREQ } : null;
    }
}

/**
 * NumPy/SciPy oscillators running in the vendored CPython (`usePyodideEngine`).
 *
 * Registered as a first-class backend so `pyodide-*` waveforms go through the
 * same selection and fallback path as everything else — previously this lived
 * as its own branch of the `VoiceManager` ladder and was invisible to the
 * registry. It is never a *preferred* backend: it sits below `wam` in
 * `BACKEND_FALLBACK_ORDER` and only becomes ready once the runtime is loaded,
 * so nothing drags Pyodide onto the entry graph (#1257).
 */
export class PyodideBackend extends BaseBackend {
    readonly id = 'pyodide' as const;
    readonly capabilities: BackendCapabilities = {
        simd: false,
        threads: false,
        offline: true,
        polyphony: 8,
        // `tri` is rendered as a sine by generate_wave(); PYODIDE_OSC_TYPE maps
        // it, so the family is declared here and the substitution is the
        // Python side's, not a silent one made by selection code.
        shapes: ALL_SHAPES,
    };

    private engine: PyodideLike | null = null;
    private tables: Partial<Record<WaveShape, AudioBuffer>> = {};
    /** Needed to allocate buffers on the async `generate()` path. */
    private ctx: BaseAudioContext | null = null;

    constructor(engine: PyodideLike | null = null) {
        super();
        this.engine = engine;
    }

    /** Pyodide loads lazily and long after audio init, so the handle is late-bound. */
    setEngine(engine: PyodideLike | null): void {
        this.engine = engine;
        this.initialized = !!engine;
        if (!engine) this.tables = {};
    }

    /** Pre-rendered tables from the idle-time warm-up, when there are any. */
    setTables(tables: Partial<Record<WaveShape, AudioBuffer | null>>): void {
        for (const [shape, buf] of Object.entries(tables)) {
            if (buf) this.tables[shape as WaveShape] = buf;
        }
    }

    get isSupported(): boolean {
        return !!this.engine;
    }

    init(ctx?: AudioContext): Promise<InitResult> {
        if (ctx) this.ctx = ctx;
        return Promise.resolve(
            this.engine ? this.ok('pyodide-runtime-attached') : this.fail('Pyodide runtime not loaded'),
        );
    }

    generate(req: GenerateRequest): Promise<Float32Array | null> {
        if (!this.ctx) return Promise.resolve(null);
        const rendered = this.renderLoop(this.ctx, req);
        return Promise.resolve(rendered ? rendered.buffer.getChannelData(0).slice() : null);
    }

    renderLoop(ctx: BaseAudioContext, req: GenerateRequest): LoopRender | null {
        if (!this.isReady || !this.engine) return null;
        this.ctx = ctx;
        const cached = this.tables[req.shape];
        if (cached) return { buffer: cached, baseFrequency: PYODIDE_REF_FREQ };
        const buffer = this.timed(() =>
            generatePyodideLoopBuffer(this.engine!, ctx, req.shape, req.cutoff, req.resonance),
        );
        if (!buffer) return null;
        this.tables[req.shape] = buffer;
        return { buffer, baseFrequency: PYODIDE_REF_FREQ };
    }

    dispose(): void {
        super.dispose();
        this.engine = null;
        this.ctx = null;
        this.tables = {};
    }
}

/**
 * Terminal backend. Always supported, always ready — renders the correct wave
 * family analytically so the fallback path is never silence and never the
 * wrong harmonic character.
 */
export class JsOscillatorBackend extends BaseBackend {
    readonly id = 'js' as const;
    readonly capabilities: BackendCapabilities = {
        simd: false,
        threads: false,
        offline: true,
        polyphony: Number.POSITIVE_INFINITY,
        shapes: ALL_SHAPES,
    };

    get isSupported(): boolean {
        return true;
    }

    get isReady(): boolean {
        return true;
    }

    async init(_ctx?: AudioContext): Promise<InitResult> {
        return this.ok('always-available');
    }

    /** Native Web Audio type for the shape — used when driving an OscillatorNode. */
    oscillatorTypeFor(shape: WaveShape): OscillatorType {
        return shapeToOscillatorType(shape);
    }

    async generate(req: GenerateRequest): Promise<Float32Array | null> {
        const n = Math.max(1, Math.ceil(req.sampleRate * req.duration));
        const out = new Float32Array(n);
        const inc = req.frequency / req.sampleRate;
        let phase = 0;
        for (let i = 0; i < n; i++) {
            out[i] = sampleShape(req.shape, phase);
            phase += inc;
            if (phase >= 1) phase -= 1;
        }
        return out;
    }
}

/**
 * Wrap rendered samples in an `AudioBuffer` for the looped realtime path.
 * Kept in one place so every generator backend allocates identically.
 */
function toLoopBuffer(
    ctx: BaseAudioContext,
    samples: Float32Array,
    baseFrequency: number,
): LoopRender | null {
    if (!samples.length) return null;
    const buffer = ctx.createBuffer(1, samples.length, ctx.sampleRate);
    buffer.getChannelData(0).set(samples);
    return { buffer, baseFrequency };
}

/** Naive (non-bandlimited) shape evaluation — matches the JS oscillator family. */
function sampleShape(shape: WaveShape, phase: number): number {
    switch (shape) {
        case 'saw':
            return 2 * phase - 1;
        case 'sqr':
            return phase < 0.5 ? 1 : -1;
        case 'tri':
            return 2 * Math.abs(2 * phase - 1) - 1;
        case 'sin':
            return Math.sin(2 * Math.PI * phase);
    }
}

/// <reference types="@webgpu/types" />
/**
 * Session-wide WebGPU probe: one adapter, one GPUDevice.
 * Voice backends may still fall back WASM/JS via BackendRegistry when this fails.
 * GPU viz/chores must hard-fail — never open a WebGL context.
 */
import { engineTelemetry } from '../../utils/engineTelemetry';

export type WebGpuAdapterSnapshot = {
    vendor?: string;
    architecture?: string;
    device?: string;
    description?: string;
};

export type WebGpuBrowserSnapshot = {
    brands?: unknown;
    platform?: string;
    engineHint: string;
};

/** JSON-safe probe result (no live GPU handles). HUD / engine reports. */
export type WebGpuProbeSnapshot = {
    ok: boolean;
    reason: string | null;
    browser: WebGpuBrowserSnapshot;
    adapter: WebGpuAdapterSnapshot | null;
    ts: number;
};

export type WebGpuProbe = WebGpuProbeSnapshot & {
    device: GPUDevice | null;
    adapterHandle: GPUAdapter | null;
};

let last: WebGpuProbe | null = null;
let inflight: Promise<WebGpuProbe> | null = null;

export function getLastWebGpuProbe(): WebGpuProbe | null {
    return last;
}

/** Clear cached probe (unit tests, or after GPU device-lost so a retry can run). */
export function resetWebGpuProbeForTests(): void {
    last = null;
    inflight = null;
}

export async function probeWebGPU(): Promise<WebGpuProbe> {
    if (last) return last;
    if (inflight) return inflight;
    inflight = runProbe().finally(() => {
        inflight = null;
    });
    return inflight;
}

function publish(probe: WebGpuProbe): void {
    last = probe;
    try {
        engineTelemetry.recordWebGpuProbe({
            ok: probe.ok,
            reason: probe.reason,
            browser: probe.browser,
            adapter: probe.adapter,
            ts: probe.ts,
        });
    } catch {
        /* telemetry must never break GPU init */
    }
}

function fail(
    browser: WebGpuBrowserSnapshot,
    ts: number,
    reason: string,
    adapter: WebGpuAdapterSnapshot | null = null,
): WebGpuProbe {
    return {
        ok: false,
        reason,
        browser,
        adapter,
        device: null,
        adapterHandle: null,
        ts,
    };
}

async function runProbe(): Promise<WebGpuProbe> {
    const browser = readBrowser();
    const ts = Date.now();
    const gpu = typeof navigator !== 'undefined' ? navigator.gpu : undefined;
    if (!gpu) {
        const probe = fail(browser, ts, 'navigator.gpu unavailable (browser lacks WebGPU)');
        publish(probe);
        return probe;
    }

    try {
        const adapter = await gpu.requestAdapter();
        if (!adapter) {
            const probe = fail(
                browser,
                ts,
                'requestAdapter() returned null (no compatible GPU adapter)',
            );
            publish(probe);
            return probe;
        }

        const adapterSnap = await readAdapterInfo(adapter);
        const device = await adapter.requestDevice();
        if (device.lost) {
            void device.lost.then(() => {
                if (last?.device === device) {
                    last = null;
                }
            });
        }

        const probe: WebGpuProbe = {
            ok: true,
            reason: null,
            browser,
            adapter: adapterSnap,
            device,
            adapterHandle: adapter,
            ts,
        };
        publish(probe);
        return probe;
    } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        const probe = fail(browser, ts, `GPUDevice or adapter request failed: ${msg}`);
        publish(probe);
        return probe;
    }
}

function readBrowser(): WebGpuBrowserSnapshot {
    const nav = typeof navigator !== 'undefined' ? navigator : undefined;
    const uad = nav
        ? (nav as Navigator & { userAgentData?: { brands?: unknown; platform?: string } })
              .userAgentData
        : undefined;
    return {
        brands: uad?.brands,
        platform: uad?.platform,
        engineHint: inferEngineHint(uad?.brands, nav?.userAgent),
    };
}

function inferEngineHint(brands: unknown, userAgent: string | undefined): string {
    const brandList: string[] = [];
    if (Array.isArray(brands)) {
        for (const b of brands) {
            if (b && typeof b === 'object' && 'brand' in b) {
                brandList.push(String((b as { brand: unknown }).brand).toLowerCase());
            } else {
                brandList.push(String(b).toLowerCase());
            }
        }
    }
    const ua = (userAgent ?? '').toLowerCase();
    const joined = brandList.join(' ');
    if (joined.includes('edg') || ua.includes('edg/')) return 'edge';
    if (joined.includes('firefox') || ua.includes('firefox')) return 'firefox';
    if (joined.includes('safari') && !joined.includes('chrome') && ua.includes('safari') && !ua.includes('chrome')) {
        return 'safari';
    }
    if (joined.includes('google chrome') || joined.includes('chromium') || ua.includes('chrome')) {
        return 'chromium';
    }
    if (ua.includes('safari')) return 'safari';
    return 'unknown';
}

async function readAdapterInfo(adapter: GPUAdapter): Promise<WebGpuAdapterSnapshot | null> {
    const withInfo = adapter as GPUAdapter & {
        info?: GPUAdapterInfo;
        requestAdapterInfo?: () => Promise<GPUAdapterInfo>;
    };
    const fromInfo = snapshotAdapterInfo(withInfo.info);
    if (fromInfo) return fromInfo;
    if (typeof withInfo.requestAdapterInfo === 'function') {
        try {
            return snapshotAdapterInfo(await withInfo.requestAdapterInfo());
        } catch {
            return null;
        }
    }
    return null;
}

function snapshotAdapterInfo(info: GPUAdapterInfo | undefined): WebGpuAdapterSnapshot | null {
    if (!info) return null;
    return {
        vendor: info.vendor || undefined,
        architecture: info.architecture || undefined,
        device: info.device || undefined,
        description: info.description || undefined,
    };
}

export type StealPolicy = 'round-robin' | 'oldest';

export interface AcquireOptions {
    affinityKey?: string;
    steal?: StealPolicy;
    time?: number;
}

export interface AcquireResult<T> {
    voice: T;
    index: number;
    stole: boolean;
    affinityHit: boolean;
}

export interface PoolableVoice {
    isActive: boolean;
}

export abstract class VoicePool<TVoice extends PoolableVoice> {
    protected voices: TVoice[] = [];
    protected maxVoices: number;

    protected activeIndices: Set<number> = new Set();
    protected startTimes: Map<number, number> = new Map();
    protected roundRobinIndex: number = 0;

    constructor(maxVoices: number) {
        this.maxVoices = Math.max(1, maxVoices);
    }

    /**
     * Get all voices in the pool (active or inactive).
     */
    public getAllVoices(): TVoice[] {
        return this.voices;
    }

    /**
     * Synchronizes the pool's internal active tracking with the actual state of the voices.
     * Useful if voices can go inactive internally (e.g. self-terminating envelopes).
     */
    public syncActiveState(): void {
        for (let i = 0; i < this.maxVoices; i++) {
            if (this.voices[i] && !this.voices[i]!.isActive && this.activeIndices.has(i)) {
                this.markInactive(i);
            }
        }
    }

    /**
     * Core allocation logic. Finds an idle voice, optionally matching an affinity key,
     * or steals one based on the specified policy.
     */
    protected acquire(options: AcquireOptions = {}): AcquireResult<TVoice> {
        this.syncActiveState();

        const { affinityKey, steal = 'round-robin', time } = options;

        // 1. Find free voice with affinity match
        if (affinityKey !== undefined) {
            for (let i = 0; i < this.maxVoices; i++) {
                if (!this.activeIndices.has(i)) {
                    if (this.getAffinityKey(i) === affinityKey) {
                        return { voice: this.voices[i]!, index: i, stole: false, affinityHit: true };
                    }
                }
            }
        }

        // 2. Find any free voice
        for (let i = 0; i < this.maxVoices; i++) {
            // For round-robin, we check starting from the roundRobinIndex
            const checkIndex = steal === 'round-robin'
                ? (this.roundRobinIndex + i) % this.maxVoices
                : i;

            if (!this.activeIndices.has(checkIndex)) {
                if (steal === 'round-robin') {
                    this.roundRobinIndex = (checkIndex + 1) % this.maxVoices;
                }
                return { voice: this.voices[checkIndex]!, index: checkIndex, stole: false, affinityHit: false };
            }
        }

        // 3. Steal
        let victimIndex = 0;

        if (steal === 'oldest') {
            let oldestTime = Infinity;
            victimIndex = -1;

            for (const index of this.activeIndices) {
                const startTime = this.startTimes.get(index) ?? Infinity;
                if (startTime < oldestTime) {
                    oldestTime = startTime;
                    victimIndex = index;
                }
            }
            if (victimIndex === -1) victimIndex = 0; // Fallback
        } else {
            // round-robin steal
            victimIndex = this.roundRobinIndex;
            this.roundRobinIndex = (this.roundRobinIndex + 1) % this.maxVoices;
        }

        const victimVoice = this.voices[victimIndex]!;

        // Trigger steal hook
        this.onStolen(victimVoice, victimIndex, time);

        // Ensure it's removed from active set
        this.markInactive(victimIndex);

        return { voice: victimVoice, index: victimIndex, stole: true, affinityHit: false };
    }

    /**
     * Mark a voice as active.
     */
    protected markActive(index: number, startTime: number = 0): void {
        this.activeIndices.add(index);
        this.startTimes.set(index, startTime);
    }

    /**
     * Mark a voice as inactive.
     */
    protected markInactive(index: number): void {
        this.activeIndices.delete(index);
        this.startTimes.delete(index);
    }

    /**
     * Stop all active voices immediately.
     */
    public stopAll(time?: number): void {
        const indices = Array.from(this.activeIndices);
        for (const index of indices) {
            this.stopVoice(this.voices[index]!, time);
            this.markInactive(index);
        }
    }

    // --- Hooks ---

    /**
     * Optional: Return the current affinity key (e.g. loaded bank ID) for a slot.
     */
    protected getAffinityKey(index: number): string | undefined {
        return undefined;
    }

    /**
     * Hook called when a voice is stolen.
     */
    protected onStolen(voice: TVoice, index: number, time?: number): void {
        this.stopVoice(voice, time);
    }

    /**
     * Adapter to stop a voice.
     */
    protected abstract stopVoice(voice: TVoice, time?: number): void;
}

