/** Vowel types for sample library */
export type VowelType = 'ah' | 'ee' | 'eh' | 'oh' | 'oo' | 'ih' | 'uh';

/** Sample entry in the vowel library */
export interface VowelSample {
    /** Vowel type identifier */
    vowel: VowelType;
    /** MIDI note number the sample was recorded at */
