import type { SingingVoiceHost } from "./host";

function setWorkletParam(
  host: SingingVoiceHost,
  name: string,
  value: number,
  time?: number,
): void {
  if (host.workletNode) {
    host.workletNode.parameters
      .get(name)
      ?.setValueAtTime(value, time || host.audioContext.currentTime);
  }
}

