   * Set amplitude envelope decay time.
   * @param decay Decay time in seconds
   * @param time Optional time to apply the change (default: now)
   */
  setDecay(this: SingingVoiceHost, decay: number, time?: number): void {
    this.currentDecay = decay;
    setWorkletParam(this, "decay", decay, time);
  },

  /**
   * Set amplitude envelope sustain level.
   * @param sustain Sustain level (0-1)
   * @param time Optional time to apply the change (default: now)
   */
  setSustain(this: SingingVoiceHost, sustain: number, time?: number): void {
    setWorkletParam(this, "sustain", sustain, time);
  },

  /**
   * Set amplitude envelope release time.
   * @param release Release time in seconds
   * @param time Optional time to apply the change (default: now)
   */
  setRelease(this: SingingVoiceHost, release: number, time?: number): void {
    setWorkletParam(this, "release", release, time);
  },

  /**
   * Trigger release phase of the amplitude envelope.
   * @param time Optional time to trigger the release
   */
  noteOff(this: SingingVoiceHost, time?: number): void {
    if (this.workletNode) {
      this.workletNode.port.postMessage({
        type: "noteOff",
        data: {
          time: time || this.audioContext.currentTime,
        },
      });
    }
    this.isActive = false;
  },

  /**
   * Set spectral compression amount.
   * @param amount Spectral compression amount (0-1)
   * @param time Optional time to apply the change
   */
  setSpectralCompression(this: SingingVoiceHost, amount: number, time?: number): void {
    setWorkletParam(this, "spectralCompression", amount, time);
  },

  /**
   * Set phoneme filter mod amount.
   * @param amount Phoneme filter mod amount (0-1)
   * @param time Optional time to apply the change
   */
  setPhonemeFilterMod(this: SingingVoiceHost, amount: number, time?: number): void {
    setWorkletParam(this, "phonemeFilterMod", amount, time);
  },

  /**
   * Set bitcrush amount.
   * @param amount Bitcrush amount (0-1)
   * @param time Optional time to apply the change
   */
  setBitcrush(this: SingingVoiceHost, amount: number, time?: number): void {
    setWorkletParam(this, "bitcrush", amount, time);
  },

  /**
   * Set spectral compression amount.
   * @param amount Spectral compression amount (0-1)
   * @param time Optional time to apply the change
   */
  setSpectralComp(this: SingingVoiceHost, amount: number, time?: number): void {
    setWorkletParam(this, "spectralComp", amount, time);
  },

  /**
   * Set sub-harmonics amount.
   * @param amount Sub-harmonics amount (0-1)
   * @param time Optional time to apply the change
   */
  setSubHarmonics(this: SingingVoiceHost, amount: number, time?: number): void {
    setWorkletParam(this, "subHarmonics", amount, time);
  },

  /**
   * Set vocal stack chorus amount.
   * @param amount Chorus amount (0-1)
   * @param time Optional time to apply the change
   */
  setVocalChorus(this: SingingVoiceHost, amount: number, time?: number): void {
    setWorkletParam(this, "vocalChorus", amount, time);
  },
  setTransientExtraction(this: SingingVoiceHost, amount: number, time?: number): void {
    setWorkletParam(this, "transientExtraction", amount, time);
  },

  /**
   * Set downsample factor.
   * @param factor Downsample factor (1-32)
   * @param time Optional time to apply the change
   */
  setDownsample(this: SingingVoiceHost, factor: number, time?: number): void {
    setWorkletParam(this, "downsample", factor, time);
  },

  /**
   * Set syllable volume filter modulation depth.
   * @param depth Modulation depth (0-1)
   * @param time Optional time to apply the change
   */
  setVolumeFilterMod(this: SingingVoiceHost, depth: number, time?: number): void {
    setWorkletParam(this, "volumeFilterMod", depth, time);
  },

  /**
   * Set custom shape for granular synthesis windowing.
   * @param shape Array of normalized values (0.0 to 1.0)
   * @param time Optional time to apply the change (default: now)
   */
  setCustomWindowShape(
    this: SingingVoiceHost,
    shape: number[] | undefined,
    time?: number,
  ): void {
    if (this.workletNode) {
      this.workletNode.port.postMessage({
        type: "setCustomWindowShape",
        data: { shape },
      });
    }
  },

  /**
   * Set the window shape for granular synthesis.
   * @param shape Window shape (0=Hann, 1=Hamming, 2=Blackman, 3=Rectangular)
   * @param time Optional time to apply the change
   */
  setWindowShape(this: SingingVoiceHost, shape: number, time?: number): void {
    setWorkletParam(this, "windowShape", shape, time);
  },

  /**
   * Set the grain panning spread for spectral pan
   * @param spread Spread amount (0-1)
   * @param time Optional time to apply the change
   */
  setGrainPanSpread(this: SingingVoiceHost, spread: number, time?: number): void {
    setWorkletParam(this, "grainPanSpread", spread, time);
  },

  /**
   * Set a custom envelope shape for granular synthesis.
   * @param shape Array of normalized values (0.0 to 1.0)
   */
  setCustomGrainEnvelope(this: SingingVoiceHost, shape: number[] | undefined): void {
    if (this.workletNode && this.workletNode.port) {
      this.workletNode.port.postMessage({
        type: 'setCustomGrainEnvelope',
        shape: shape,
      });
    }
  },
};

import type { VoiceCharacter } from "../rubberband/FormantShifter";
import type { SingingVoiceHost } from "./host";

export const FormantControlMixin = {
  /**
   * Set custom LFO shape for formant shifting.
   * @param shape Array of normalized values (0.0 to 1.0)
   */
  setFormantLfoShape(
    this: SingingVoiceHost,
    shape: number[] | undefined,
  ): void {
    if (this.formantShifter && this.config.enableFormantShifting) {
      this.formantShifter.setCustomLfoShape(shape);
    }
  },

  /**
   * Set voice character for formant shifting (Section 4).
   *
   * @param character Target voice character
   * @param sourceCharacter Source voice character (default: 'default')
   */
  setVoiceCharacter(
    this: SingingVoiceHost,
    character: VoiceCharacter,
    sourceCharacter: VoiceCharacter = "default",
  ): void {
    if (!this.formantShifter) {
      console.warn(
        "FormantShifter not enabled. Set enableFormantShifting: true in config.",
      );
      return;
    }

    this.formantShifter.createCharacterFilterChain(character, sourceCharacter);
    this.config.voiceCharacter = character;
  },

  /**
   * Get the formant shifter for advanced control.
   * Returns null if formant shifting is not enabled.
   */
  getFormantShifter(this: SingingVoiceHost) {
    return this.formantShifter;
  },

  /**
   * Set formant LFO rate in Hz.
   * @param rate LFO rate in Hz
   * @param time Optional time to apply the change (default: now)
   */
  setFormantLfoRate(
    this: SingingVoiceHost,
    rate: number,
    time?: number,
  ): void {
    if (this.formantShifter && this.config.enableFormantShifting) {
      this.formantShifter.setLfoRate(rate, time);
    }
  },

  /**
   * Set formant LFO depth.
   * @param depth LFO depth (0-1)
   * @param time Optional time to apply the change (default: now)
   */
  setFormantLfoDepth(
    this: SingingVoiceHost,
    depth: number,
    time?: number,
  ): void {
    if (this.formantShifter && this.config.enableFormantShifting) {
      this.formantShifter.setLfoDepth(depth, time);
    }
  },

  /**
   * Set formant shift in semitones.
   * @param semitones Formant shift in semitones (e.g., -12 to 12)
   * @param time Optional time to apply the change (default: now)
   * @param rampTime Optional duration to ramp to the new formant value smoothly
   */
  setFormantShift(
    this: SingingVoiceHost,
    semitones: number,
    time?: number,
    rampTime: number = 0.05,
  ): void {
    if (this.formantShifter && this.config.enableFormantShifting) {
      const shift = {
        f1Shift: semitones,
        f2Shift: semitones,
        f3Shift: semitones,
        f4Shift: semitones,
      };
      this.formantShifter.updateFilterChain(shift, rampTime);
    }
  },

  /**
   * Glide formant shift from a starting value to an end value.
   */
  setFormantGlide(
    this: SingingVoiceHost,
    startSemitones: number,
    endSemitones: number,
    startTime: number,
    duration: number,
  ): void {
    if (this.formantShifter && this.config.enableFormantShifting) {
      // First jump to start without ramping
      const startShift = {
        f1Shift: startSemitones,
        f2Shift: startSemitones,
        f3Shift: startSemitones,
        f4Shift: startSemitones,
      };
      this.formantShifter.updateFilterChain(startShift, 0, startTime);

      // Then ramp to end over duration
      const endShift = {
        f1Shift: endSemitones,
        f2Shift: endSemitones,
        f3Shift: endSemitones,
        f4Shift: endSemitones,
      };
      this.formantShifter.updateFilterChain(endShift, duration, startTime);
    }
  },

  /**
   * Set the amount of formant shift driven by the amplitude envelope follower.
   * @param amount Peak shift amount in semitones (-24 to 24)
   * @param time Optional time to apply the change
   */
  setFormantEnvFollower(
    this: SingingVoiceHost,
    amount: number,
    time?: number,
  ): void {
    if (this.formantShifter && this.config.enableFormantShifting) {
      this.formantShifter.setEnvFollowerDepth(amount, time);
    }
  },

  /**
   * Trigger a formant envelope.
   */
  setFormantEnvelope(
    this: SingingVoiceHost,
    amount: number,
    attack: number,
    decay: number,
    triggerTime: number,
  ) {
    if (this.formantShifter && this.config.enableFormantShifting) {
      this.formantShifter.triggerEnvelope(amount, attack, decay, triggerTime);
    }
  },

  /**
   * Set formant sidechain depth on the voice.
   */
  setFormantSidechainDepth(this: SingingVoiceHost, depth: number): void {
    (this as any).formantSidechainDepth = depth;
  },

  /**
   * Trigger a formant sidechain duck.
   */
  triggerFormantSidechainDuck(
    this: SingingVoiceHost,
    amount: number,
    releaseTime: number,
    triggerTime?: number,
  ) {
    if (this.formantShifter && this.config.enableFormantShifting) {
      this.formantShifter.triggerSidechainDuck(amount, releaseTime, triggerTime);
    }
  },

  /**
   * Set character morphing amount and target.
   * @param amount Morph amount (0 to 1)
   * @param target Target voice character
   * @param rampTime Optional duration to ramp to the new formant value smoothly
   */
  setCharacterMorph(
    this: SingingVoiceHost,
    amount: number,
    target: VoiceCharacter,
    rampTime: number = 0.05,
  ): void {
    if (this.formantShifter && this.config.enableFormantShifting) {
      const shift = this.formantShifter.interpolateCharacters(
        "default",
        target,
        amount,
      );
      this.formantShifter.updateFilterChain(shift, rampTime);
    }
  },
};

import type { AlignmentResult } from "../rubberband/PhonemeAligner";
import type { PhonemeBufferPool } from "../../services/PhonemeBufferPool";
import { applyMicrotonalTuning } from "../../utils/musicTheory";
import { midiToFreq } from "./pitchUtils";
import { clampStretchRatio, PITCH_RATIO_LIMITS } from "./constants";
import type { PhonemeData } from '../../types';
import type { SingingVoiceHost } from "./host";


export interface SingingVoiceTriggerOptions {
  startTime: number;
  targetMidi: number;
  baseMidi?: number;
  tuning?: import("../../utils/musicTheory").ScaleDefinition | null;
  pitchOffset?: number;
  duration?: number;
  // Legato / portamento
  legato?: boolean;
  slideFromMidi?: number;
  portamento?: number;
  slideType?: 'linear' | 'exponential';
  // Formant (pre-resolved by caller)
  formantShift?: number;
  slideFromFormant?: number;
  reverse?: boolean;
  phonemeData?: PhonemeData; // Added for isVowel check
}

export const PlaybackMixin = {
  trigger(
    this: SingingVoiceHost,
    opts: SingingVoiceTriggerOptions
  ): void {
    const { startTime, targetMidi, duration } = opts;
    const baseMidi = opts.baseMidi ?? this.rootNote;
    const tuning = opts.tuning;

    // 1. Calculate Target Pitch Ratio
    const effectiveCoarse = this.coarseTune;
    const effectiveFine = this.fineTune;
    let finalTargetMidi = applyMicrotonalTuning(targetMidi, tuning);
    const totalSemitoneOffset = effectiveCoarse + effectiveFine / 100 + (opts.pitchOffset ?? 0);
    finalTargetMidi += totalSemitoneOffset;

    const targetFreq = midiToFreq(finalTargetMidi);
    const baseFreq = midiToFreq(baseMidi);
    let targetRatio = targetFreq / baseFreq;
    targetRatio = Math.max(PITCH_RATIO_LIMITS.MIN, Math.min(PITCH_RATIO_LIMITS.MAX, targetRatio));

    // 2. Pitch Glide / Legato Logic
    const glideDur = opts.portamento !== undefined && duration !== undefined
      ? opts.portamento * duration // Or another mapping if needed, portamento is 0-1
      : opts.duration !== undefined ? Math.min(Math.max(opts.duration * 0.5, 0.15), opts.duration) : 0.15;

    // Apply Expressive Note Transitions ONLY if it's a slideFromMidi OR (it's legato AND it's a vowel/voiced phoneme)
    const vowels = ['AA', 'AE', 'AH', 'AO', 'AW', 'AY', 'EH', 'ER', 'EY', 'IH', 'IY', 'OW', 'OY', 'UH', 'UW'];
    const isVowel = opts.phonemeData ? vowels.includes(opts.phonemeData.symbol.toUpperCase()) : true; // Default to true if no phoneme data provided
    const shouldGlide = opts.slideFromMidi !== undefined || (this.isActive && opts.legato !== false && isVowel);

    if (shouldGlide && glideDur > 0) {
      let fromRatio: number;
      if (opts.slideFromMidi !== undefined) {
          let fromMidi = applyMicrotonalTuning(opts.slideFromMidi, tuning);
          fromMidi += totalSemitoneOffset;
          fromRatio = Math.max(PITCH_RATIO_LIMITS.MIN, Math.min(PITCH_RATIO_LIMITS.MAX, midiToFreq(fromMidi) / baseFreq));
      } else {
          fromRatio = this.currentPitch ?? targetRatio; // Fallback to target if null
      }
      this.glidePitchTo(targetRatio, startTime, glideDur, fromRatio, opts.slideType);
    } else {
      this.setPitchAtTime(targetRatio, startTime);
    }

    // 3. Formant Shift / Glide Logic
    if (opts.slideFromFormant !== undefined && opts.formantShift !== undefined) {
      this.setFormantGlide(
        opts.slideFromFormant,
        opts.formantShift,
        startTime,
        glideDur
      );
    } else if (opts.formantShift !== undefined) {
      this.setFormantShift(
        opts.formantShift,
        startTime,
        0
      );
    }

    // 4. Play
    this.play(undefined, undefined, 1.0, opts.reverse);

    // 5. Update State
    this.isActive = true;
    this.currentPitch = targetRatio;
  },

  /**
   * Load audio buffer into the worklet without triggering playback.
   * Useful for pre-loading or glitch effects where multiple triggers share the same buffer.
   * @param audio Float32Array of mono audio samples
   */
  loadBuffer(this: SingingVoiceHost, audio: Float32Array): void {
    if (!this.workletNode) {
      throw new Error(
        "SingingVoice not initialized. Call initWorklet() first.",
      );
    }

    this.workletNode.port.postMessage({
      type: "loadBuffer",
      data: { buffer: audio.buffer }, // Let structured clone handle it natively
    });
    this.isActive = false;
    this.currentPitch = null;
  },

  /**
   * Set reverse playback state dynamically.
   * @param reverse True for reverse playback, false for forward
   */
  setReverse(this: SingingVoiceHost, reverse: boolean): void {
    if (this.workletNode) {
      this.workletNode.port.postMessage({
        type: "setReverse",
        data: { reverse },
      });
    }
  },

  /**
   * Trigger playback of the currently loaded buffer.

   * @param startSample Optional start sample index
   * @param endSample Optional end sample index
   * @param pitch Optional pitch override (default 1.0)
   * @param reverse Optional reverse playback (default false)
   */
  play(
    this: SingingVoiceHost,
    startSample?: number,
    endSample?: number,
    pitch: number = 1.0,
    reverse: boolean = false,
    targetHz?: number,
  ): void {
    if (!this.workletNode) {
      throw new Error(
        "SingingVoice not initialized. Call initWorklet() first.",
      );
    }

    this.workletNode.port.postMessage({
      type: "noteOn",
      data: {
        pitch,
        startSample,
        endSample,
        reverse,
        targetHz,
      },
    });
  },

  /**
   * Process audio through the Rubber Band worklet.
   * @param audio Float32Array of mono audio samples
   * @param startSample Optional start sample index for slicing
   * @param endSample Optional end sample index for slicing
   * @returns Promise that resolves when processing is complete
   */
  async process(
    this: SingingVoiceHost,
    audio: Float32Array,
    startSample?: number,
    endSample?: number,
    reverse: boolean = false,
  ): Promise<void> {
    this.loadBuffer(audio);
    this.play(startSample, endSample, 1.0, reverse);
  },

  /**
   * Trigger a specific phoneme slice based on index.
   *
   * When `targetDuration`, `scheduledTime`, and `phonemeId` are provided **and**
   * the pre-stretched buffer pool has a matching buffer, playback goes through an
   * `AudioBufferSourceNode` scheduled with sample-accurate timing (zero onset
   * latency).  Otherwise, the existing Rubber Band worklet path is used as a
   * fall-back.
   *
   * @param audio          Full decoded audio buffer (Float32Array, mono)
   * @param sliceIndex     Index of the phoneme segment in `alignment.phonemes`
   * @param alignment      Alignment result containing phoneme timing info
   * @param pitch          Optional pitch ratio override (default 1.0)
   * @param reverse        Optional reverse playback flag (default false)
   * @param targetDuration Optional target step duration in seconds (for pool lookup)
   * @param scheduledTime  Optional Web Audio `currentTime` at which to schedule playback
   * @param phonemeId      Optional stable ID for pool lookup (e.g. "bank_0_slice_3")
   */
  async triggerSlice(
    this: SingingVoiceHost,
    audio: Float32Array,
    sliceIndex: number,
    alignment: AlignmentResult,
    pitch: number = 1.0,
    reverse: boolean = false,
    targetDuration?: number,
    scheduledTime?: number,
    phonemeId?: string,
    velocity: number = 1.0,
  ): Promise<void> {
    if (sliceIndex < 0 || sliceIndex >= alignment.phonemes.length) {
      console.warn(
        `Slice index ${sliceIndex} out of bounds (max ${alignment.phonemes.length - 1})`,
      );
      return;
    }

    const phoneme = alignment.phonemes[sliceIndex];
    const startSample = Math.floor(phoneme.start * alignment.sampleRate);
    const endSample = Math.floor(phoneme.end * alignment.sampleRate);

    // ------------------------------------------------------------------
    // Pool path: sample-accurate AudioBufferSourceNode playback
    // ------------------------------------------------------------------
    if (
      this.bufferPool !== null &&
      targetDuration !== undefined &&
      targetDuration > 0 &&
      phonemeId !== undefined &&
      !reverse
    ) {
      const targetMs = Math.round(targetDuration * 1000);
      const poolBuffer = this.bufferPool.getNearest(phonemeId, targetMs);

      if (poolBuffer !== null && this.outputDestinations.size > 0) {
        const when =
          scheduledTime !== undefined
            ? scheduledTime
            : this.audioContext.currentTime;
        const source = this.audioContext.createBufferSource();
        source.buffer = poolBuffer;
        // Connect to every output destination the worklet is currently wired to
        // ⚡ Bolt Optimization: Replacing forEach with for loop to prevent closure allocations on hot path
        for (const dest of this.outputDestinations) {
          source.connect(dest);
        }
        source.start(when);
        source.stop(when + targetDuration);
        return;
      }
    }

    // ------------------------------------------------------------------
    // Fall-back: existing Rubber Band worklet path
    // ------------------------------------------------------------------

    // Apply Phoneme-Aware Velocity formatting to amplitude envelope
    let scaledAttack = this.currentAttack;
    let scaledDecay = this.currentDecay;

    // Apply Phoneme-Aware Velocity scaling
    const velocityScale = velocity !== undefined ? velocity : 1.0;

    switch (phoneme.category) {
      case "plosive":
        scaledAttack = Math.max(0.001, this.currentAttack * 0.1) * (1.5 - velocityScale * 0.5); // Extremely fast attack, harder with high velocity
        scaledDecay = Math.max(0.001, this.currentDecay * 0.5) * (1.5 - velocityScale * 0.5); // Faster decay
        break;
      case "fricative":
        scaledAttack = Math.max(0.001, this.currentAttack * 0.5) * (1.5 - velocityScale * 0.5); // Fast attack
        break;
      case "liquid":
      case "nasal":
        scaledAttack = Math.min(2.0, this.currentAttack * 1.2) * (1.2 - velocityScale * 0.2); // Smoother attack
        break;
      case "vowel":
        scaledAttack = Math.min(2.0, this.currentAttack * 1.5) * (1.2 - velocityScale * 0.2); // Smooth attack
        scaledDecay = Math.min(2.0, this.currentDecay * 1.2) * (1.2 - velocityScale * 0.2); // Longer decay
        break;
      default:
        break;
    }

    if (this.workletNode) {
      this.workletNode.parameters
        .get("attack")
        ?.setValueAtTime(scaledAttack, this.audioContext.currentTime);
      this.workletNode.parameters
        .get("decay")
        ?.setValueAtTime(scaledDecay, this.audioContext.currentTime);
    }

    this.setPitch(pitch);

    // Apply phoneme-aware time-stretch to fill the target step duration.
    // When targetDuration is supplied, compute the ratio from the phoneme's
    // natural duration; otherwise reset to 1.0 (no stretch).
    if (targetDuration !== undefined && targetDuration > 0) {
      const nativeDuration = phoneme.end - phoneme.start;
      if (nativeDuration > 0) {
        const rawRatio = targetDuration / nativeDuration;
        this.setTimeRatio(clampStretchRatio(rawRatio));
      } else {
        this.setTimeRatio(1.0);
      }
    } else {
      this.setTimeRatio(1.0); // Reset time stretch for slice playback
    }

    await this.process(audio, startSample, endSample, reverse);

    // Reset envelopes immediately after trigger to avoid bleeding onto next normal note processing
    if (this.workletNode) {
      this.workletNode.parameters
        .get("attack")
        ?.setValueAtTime(
          this.currentAttack,
          this.audioContext.currentTime + 0.1,
        );
      this.workletNode.parameters
        .get("decay")
        ?.setValueAtTime(
          this.currentDecay,
          this.audioContext.currentTime + 0.1,
        );
    }
  },

  /**
   * Align phonemes in the given audio (Section 3).
   * Stores the result internally for later use with phoneme-aware stretching.
   *
   * @param audio Audio samples to align
   * @param text Text/lyrics to align
   * @returns Alignment result with phoneme segments
   */
  async alignPhonemes(
    this: SingingVoiceHost,
    audio: Float32Array,
    text: string,
    options?: { durationPriors?: number[] },
  ): Promise<AlignmentResult | null> {
    if (!this.phonemeAligner) {
      console.warn(
        "PhonemeAligner not enabled. Set enablePhonemeStretching: true in config.",
      );
      return null;
    }

    this.lastAlignment = await this.phonemeAligner.alignPhonemes(
      audio,
      text,
      this.audioContext.sampleRate,
      options,
    );

    return this.lastAlignment;
  },

  /**
   * Set the current alignment result manually.
   * Useful for multi-bank setups where alignment is pre-calculated/cached.
   *
   * @param alignment The alignment result to use
   */
  setAlignment(
    this: SingingVoiceHost,
    alignment: AlignmentResult | null,
  ): void {
    this.lastAlignment = alignment;
  },

  /**
   * Get the last phoneme alignment result.
   */
  getLastAlignment(this: SingingVoiceHost): AlignmentResult | null {
    return this.lastAlignment;
  },

  /**
   * Send phoneme boundaries to AudioWorklet for real-time processing (Section 3).
   * Call this after alignPhonemes() to enable phoneme-aware stretching.
   *
   * @param targetDuration Optional target duration for stretch calculation
   */
  schedulePhonemeFormantGlides(
    this: SingingVoiceHost,
    targetDuration: number,
    triggerTime: number,
    baseFormantShift: number,
    userPhonemes?: PhonemeData[],
  ): void {
    if (
      !this.config.enableFormantShifting ||
      !this.lastAlignment ||
      !this.phonemeAligner ||
      !userPhonemes ||
      userPhonemes.length === 0
    ) {
      return;
    }

    const phonemes = this.lastAlignment.phonemes;
    const sampleRate = this.audioContext.sampleRate;

    // We only care if there is any user phoneme with a formant shift, or if there are vowel transitions to smooth out
    const hasFormantShift = userPhonemes.some(
      (p) => p.formantShift !== undefined || p.pitchBend !== 0,
    );

    // We also want to run the loop to check for consecutive vowels for expressive transitions
    // ⚡ Bolt Optimization: Prevent array allocation and closure in hot path by avoiding .filter()
    let vowelCount = 0;
    for (let i = 0; i < phonemes.length; i++) {
      if (phonemes[i].isVowel) {
        vowelCount++;
        if (vowelCount > 1) break;
      }
    }
    const hasVowelTransitions = vowelCount > 1;

    if (!hasFormantShift && !hasVowelTransitions) {
      return;
    }

    // Calculate absolute stretch map
    const ratios = this.phonemeAligner.calculateStretchRatios(
      phonemes,
      targetDuration,
    );

    let currentTimeSeconds = triggerTime;
    let prevShift = baseFormantShift;

    for (let i = 0; i < phonemes.length; i++) {
      const p = phonemes[i];
      const ratio = ratios[i] || 1.0;
      const originalDurationSec = (p.end - p.start) / sampleRate;
      const stretchedDurationSec = originalDurationSec * ratio;

      const userP = userPhonemes[i];
      let targetShift = baseFormantShift;
      if (userP && userP.formantShift !== undefined) {
        targetShift += userP.formantShift;
      }

      // Expressive Note Transitions for Vowels
      // If this is a vowel, and the next phoneme is also a vowel, we can add a subtle portamento/glide
      if (p.isVowel && i < phonemes.length - 1) {
        const nextP = phonemes[i + 1];
        if (nextP.isVowel) {
          // Calculate a subtle formant transition to smooth out the vowel boundary
          const rampDuration = Math.min(0.1, stretchedDurationSec * 0.5);
          const transitionTime = currentTimeSeconds + stretchedDurationSec - rampDuration;

          if (prevShift === targetShift) {
             // If there's no user formant shift, we can still apply a micro-glide for expressiveness
             // Just a slight scoop to simulate vocal tract adjustments between vowels
             const scoopAmount = 0.5; // semitones
             this.setFormantGlide(
                targetShift,
                targetShift + scoopAmount,
                transitionTime,
                rampDuration
             );
             // Return to baseline at the start of next vowel
             this.setFormantGlide(
                targetShift + scoopAmount,
                targetShift,
                currentTimeSeconds + stretchedDurationSec,
                rampDuration
             );
          }
        }
      }

      if (prevShift !== targetShift) {
        // Ramp duration bounded by the segment length
        // We use a quick ramp, but bounded to the phoneme length so it doesn't bleed too far
        const rampDuration = Math.min(0.05, stretchedDurationSec);

        // Using existing setFormantGlide:
        // Note setFormantGlide ramps from startSemitones to endSemitones over duration.
        // If we want it to glide during this phoneme segment:
        this.setFormantGlide(
          prevShift,
          targetShift,
          currentTimeSeconds,
          rampDuration
        );
      } else {
        // Ensure we hold the target shift (only if we didn't just schedule an expressive scoop above)
        if (!(p.isVowel && i < phonemes.length - 1 && phonemes[i+1].isVowel && prevShift === targetShift)) {
           this.setFormantShift(targetShift, currentTimeSeconds, 0);
        }
      }

      prevShift = targetShift;
      currentTimeSeconds += stretchedDurationSec;
    }
  },

  sendPhonemeDataToWorklet(
    this: SingingVoiceHost,
    targetDuration?: number,
    userPhonemes?: PhonemeData[],
  ): void {
    if (!this.lastAlignment || !this.phonemeAligner || !this.workletNode) {
      return;
    }

    const phonemes = this.lastAlignment.phonemes;

    // Calculate stretch ratios if target duration specified
    let ratios: number[] | undefined;
    if (targetDuration !== undefined) {
      ratios = this.phonemeAligner.calculateStretchRatios(
        phonemes,
        targetDuration,
      );
    }

    // Create shared buffer with phoneme data
    const sharedBuffer = this.phonemeAligner.createSharedPhonemeBuffer(
      phonemes,
      this.audioContext.sampleRate,
      userPhonemes,
    );

    // Send to worklet
    this.workletNode.port.postMessage({
      type: "setPhonemeData",
      data: {
        sharedBuffer,
        ratios,
      },
    });
  },

  /**
   * Connect the output of this voice to an audio destination.
   * If formant shifting is enabled, routes through the formant shifter first.
   *
   * @param destination Destination audio node
   */
  connectOutput(this: SingingVoiceHost, destination: AudioNode): void {
    if (!this.workletNode) {
      throw new Error("Voice not initialized. Call initWorklet() first.");
    }

    // Track so the pool playback path can reach the same output chain.
    this.outputDestinations.add(destination);

    if (this.formantShifter && this.config.enableFormantShifting) {
      // Route through formant shifter
      this.formantShifter.connect(this.workletNode, destination);
    } else {
      // Direct connection
      this.workletNode.connect(destination);
    }
  },

  /**
   * Disconnect the output.
   */
  disconnectOutput(this: SingingVoiceHost): void {
    if (this.workletNode) {
      this.workletNode.disconnect();
    }
    if (this.formantShifter) {
      this.formantShifter.disconnect();
    }
    this.outputDestinations.clear();
    this.isActive = false;
    this.currentPitch = null;
  },

  /**
   * Attach (or detach) the pre-stretched buffer pool.
   * Call this once after the pool is initialised so that `triggerSlice`
   * can use sample-accurate `AudioBufferSourceNode` playback when a
   * pre-stretched buffer is available.
   *
   * @param pool Pool instance, or `null` to disable pool playback.
   */
  setPool(this: SingingVoiceHost, pool: PhonemeBufferPool | null): void {
    this.bufferPool = pool;
  },

  /**
   * Get the underlying AudioWorkletNode.
   * @returns The AudioWorkletNode
   */
  getSourceNode(this: SingingVoiceHost): AudioWorkletNode {
    if (this.workletNode) {
      return this.workletNode;
    }
    throw new Error("SingingVoice not initialized. Call initWorklet() first.");
  },

  /**
   * Connect the worklet to an audio destination.
   * @param destination AudioNode to connect to
   */
  connect(this: SingingVoiceHost, destination: AudioNode): void {
    if (this.workletNode) {
      this.workletNode.connect(destination);
    }
  },

  /**
   * Disconnect the worklet.
   * @param destination Optional specific destination to disconnect from
   */
  disconnect(this: SingingVoiceHost, destination?: AudioNode): void {
    if (this.workletNode) {
      if (destination) {
        this.workletNode.disconnect(destination);
      } else {
        this.workletNode.disconnect();
      }
    }
    this.isActive = false;
    this.currentPitch = null;
  },
};

