import processorUrl from "../../audio-worklets/rubberband-processor.ts?worker&url";
import type { SingingVoiceHost } from "./host";
import { attachWorkletPerf, registerRubberbandNode } from "../../utils/workletPerfBridge";

export const WorkletSetupMixin = {
  /**
   * Initialize the Rubber Band AudioWorklet processor.
   * Must be called before processing audio.
   * AudioWorklet is now the only supported path - ScriptProcessorNode fallback removed.
   * @param _forceScriptProcessor Deprecated parameter - no longer used
   * @param wasmBinary Optional pre-loaded WASM binary to avoid refetching
   */
  async initWorklet(
    this: SingingVoiceHost,
    _forceScriptProcessor: boolean = false,
    wasmBinary?: ArrayBuffer,
  ): Promise<void> {
    // Clean up existing node if reinitializing
    if (this.workletNode) {
      this.workletNode.disconnect();
      this.workletNode = null;
    }

    // AudioWorklet is the only supported path
    if (!this.audioContext.audioWorklet) {
      throw new Error(
        "AudioWorklet is not supported in this browser. SingingVoice requires AudioWorklet.",
      );
    }

    try {
      await this.audioContext.audioWorklet.addModule(processorUrl);

      // Fetch the WASM binary on the main thread to bypass worklet restrictions
      // OR use the pre-loaded one if provided (for multi-voice optimization)
      let binary = wasmBinary;
      if (!binary) {
        const response = await fetch(
          import.meta.env.BASE_URL + "rubberband.wasm",
        );
        if (!response.ok) {
          throw new Error(
            `Failed to fetch rubberband.wasm: ${response.statusText}`,
          );
        }
        binary = await response.arrayBuffer();
      }

      // Create shared buffers for ring buffers
      const inputBuffer = new SharedArrayBuffer(this.config.bufferSize! * 4);
      const outputBuffer = new SharedArrayBuffer(this.config.bufferSize! * 4);

      this.workletNode = new AudioWorkletNode(
        this.audioContext,
        "RubberBandProcessor",
        {
          outputChannelCount: [2],
        }
      );

      // Initialize the worklet with the fetched binary and buffers (flat structure)
      this.workletNode.port.postMessage({
        type: "INIT_WASM",
        inputBuffer,
        outputBuffer,
        wasmBinary: binary,
        moduleUrl: "/rubberband.js",
        baseUrl: import.meta.env.BASE_URL,
        drumSidechainSAB: this.config.drumSidechainSAB,
      });

      // Wait for ready signal.
      // IMPORTANT: use port.onmessage (not addEventListener) — setting onmessage
      // automatically calls port.start(), which is required to begin message delivery
      // on a MessagePort. addEventListener alone does NOT start delivery.
      await new Promise<void>((resolve, reject) => {
        const timeoutId = setTimeout(() => {
          reject(new Error("timeout"));
        }, 5000);
        const handler = (event: MessageEvent) => {
          clearTimeout(timeoutId);
          this.workletNode!.port.onmessage = null;
          if (event.data.type === "READY") {
            resolve();
          } else if (event.data.type === "ERROR") {
            reject(
              new Error(event.data.error || "Worklet initialization failed"),
            );
          }
        };
        this.workletNode!.port.onmessage = handler;
      });

      console.log("SingingVoice: AudioWorklet initialized successfully");
      attachWorkletPerf(this.workletNode, 'rubberband');
      registerRubberbandNode(this.workletNode);
    } catch (e) {
      console.error("SingingVoice: AudioWorklet initialization failed:", e);
      this.workletNode = null;
      throw new Error(
        `AudioWorklet initialization failed: ${e instanceof Error ? e.message : String(e)}`,
      );
    }
  },
};

import { renderHook, act, waitFor } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { useScheduler } from '../useScheduler';

// vitest.setup.ts installs a plain (non-spy) AudioContext / AudioWorkletNode mock
// on `window`. These tests need to assert on construction + port messages, so we
// swap in a spy-friendly AudioWorkletNode for the duration of this file.
class FakeWorkletNode {
    port: { postMessage: ReturnType<typeof vi.fn>; onmessage: unknown; addEventListener: ReturnType<typeof vi.fn>; removeEventListener: ReturnType<typeof vi.fn> };
    connect = vi.fn();
    disconnect = vi.fn();
    constructor(..._args: unknown[]) {
        this.port = {
            postMessage: vi.fn(),
            onmessage: null,
            addEventListener: vi.fn(),
            removeEventListener: vi.fn(),
        };
        createdNodes.push(this);
    }
}

let createdNodes: FakeWorkletNode[] = [];

function makeContext(state: AudioContextState = 'running'): AudioContext {
    const context = new (window.AudioContext as unknown as { new (): AudioContext })();
    (context as { state: AudioContextState }).state = state;
    return context;
}

describe('useScheduler', () => {
    let originalWorkletNode: unknown;
    // Tracked explicitly (rather than via `vi.restoreAllMocks()`) because that
    // would also wipe the shared `window.AudioContext` mock from
    // vitest.setup.ts — it's a plain `vi.fn()`, not a spy, so "restoring" it
    // clears its implementation and breaks every later test in this file.
    let warnSpy: ReturnType<typeof vi.spyOn> | null = null;

    beforeEach(() => {
        vi.clearAllMocks();
        createdNodes = [];
        originalWorkletNode = window.AudioWorkletNode;
        (window as unknown as { AudioWorkletNode: unknown }).AudioWorkletNode = FakeWorkletNode;
    });

    afterEach(() => {
        (window as unknown as { AudioWorkletNode: unknown }).AudioWorkletNode = originalWorkletNode;
        warnSpy?.mockRestore();
        warnSpy = null;
    });

    it('does not start the AudioWorklet clock and logs a clear warning when the engine is not ready', async () => {
        warnSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});
        const context = makeContext();
        const onStep = vi.fn();

        const { result } = renderHook(() =>
            useScheduler(120, 32, onStep, /* isAudioReady */ false, context),
        );

        act(() => {
            result.current.setIsPlaying(true);
        });

        await act(async () => {
            await Promise.resolve();
        });

        expect(createdNodes).toHaveLength(0);
        expect(warnSpy).toHaveBeenCalledWith(expect.stringContaining('[useScheduler]'));
    });

    it('starts the AudioWorklet clock and posts a start message once the engine is ready', async () => {
        const context = makeContext();
        const onStep = vi.fn();

        const { result } = renderHook(() =>
            useScheduler(120, 32, onStep, /* isAudioReady */ true, context),
        );

        act(() => {
            result.current.setIsPlaying(true);
        });

        await waitFor(() => expect(createdNodes).toHaveLength(1));

        expect(createdNodes[0].port.postMessage).toHaveBeenCalledWith({ type: 'start' });
        expect(createdNodes[0].connect).toHaveBeenCalledWith(context.destination);
        expect(result.current.isPlaying).toBe(true);
    });

    it('stops the clock and leaves no orphan node when toggled off', async () => {
        const context = makeContext();
        const onStep = vi.fn();

        const { result } = renderHook(() =>
            useScheduler(120, 32, onStep, /* isAudioReady */ true, context),
        );

        act(() => {
            result.current.setIsPlaying(true);
        });

        await waitFor(() => expect(createdNodes).toHaveLength(1));
        const node = createdNodes[0];

        act(() => {
            result.current.setIsPlaying(false);
        });

        await waitFor(() => {
            expect(node.port.postMessage).toHaveBeenCalledWith({ type: 'stop' });
        });
        expect(node.disconnect).toHaveBeenCalled();
        expect(result.current.isPlaying).toBe(false);
    });
});

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { renderHook } from '@testing-library/react';
import { useStepHandler } from '../useStepHandler';
import { trackMuteSoloStore } from '../../stores/trackMuteSoloStore';
import { TRACK_KEYS } from '../../constants';
import type { Note, Pattern, PartSequence } from '../../types';
import type { TrackKey } from '../../constants/appDefaults';

/**
 * Mute / solo gating at the trigger point.
 *
 * The gate deliberately lives in `useStepHandler`, not `useScheduler`: the
 * playhead must keep advancing through silenced tracks.
 */

const NUM_STEPS = 32;

const emptySeq = (): PartSequence => ({
  steps: Array.from({ length: NUM_STEPS }, () => null as Note | null),
});

/** A pattern with exactly one note on step 0 of every track. */
function patternArmedOnStepZero(): Pattern {
  const armed = (): PartSequence => {
    const seq = emptySeq();
    seq.steps[0] = { note: 'C3', velocity: 1, length: 1 };
    return seq;
  };
  return {
    partA: armed(),
    partB: armed(),
    bass2: armed(),
    kick: armed(),
    snare: armed(),
    closedHat: armed(),
    openHat: armed(),
    sampler: Array.from({ length: 8 }, (_, i) => (i === 0 ? armed() : emptySeq())),
  } as unknown as Pattern;
}

const ref = <T,>(current: T) => ({ current });

function makeEngine() {
  return {
    context: { currentTime: 0, sampleRate: 48000 },
    playSynth: vi.fn(),
    playDrum: vi.fn(),
    playSampler: vi.fn(),
    stopTrackNotes: vi.fn(),
    open303Engine: null,
    updateSamplerVoiceParams: vi.fn(),
  };
}

function makeOptions(engine: ReturnType<typeof makeEngine>, pattern: Pattern) {
  const trackStorage = {} as Record<TrackKey, (PartSequence | PartSequence[] | null)[]>;
  return {
    audioEngine: engine as never,
    tempo: 120,
    onParamChange: undefined,
    currentStepRef: ref(-1),
    sequencerRef: ref({ setHighlight: vi.fn() }),
    patternRef: ref(pattern),
    lastFreqRef: ref({} as Record<string, number>),
    lastSamplerMidiRef: ref({} as Record<number, number>),
    lastSamplerFormantRef: ref({} as Record<number, number>),
    synthARef: ref({ waveform: 'sawtooth' } as never),
    synthBRef: ref({ waveform: 'sawtooth' } as never),
    bass2Ref: ref({ waveform: 'sawtooth', cutoff: 0.5, resonance: 0.5, decay: 0.3, volume: 0.8 } as never),
    kickRef: ref({}),
    snareRef: ref({}),
    closedHatRef: ref({}),
    openHatRef: ref({}),
    currentScaleRef: ref(null),
    samplerRef: ref(Array.from({ length: 8 }, () => ({})) as never),
    samplerVoiceParamsRef: ref({
      drive: 0, rootNote: 60, coarseTune: 0, fineTune: 0, formantShift: 0,
      attack: 0.01, decay: 0.2, stretchProfile: 'vocal', stretchMode: 'Time',
      lockToSequencer: false,
    } as never),
    activeSamplerBankRef: ref(0),
    sliceHighlightRef: ref(null),
    isSongModeActiveRef: ref(false),
    songStructureRef: ref([]),
    songMeasureRef: ref(0),
    isFirstStepRef: ref(true),
    trackStorageRef: ref(trackStorage),
    setCurrentSongMeasure: vi.fn(),
  } as unknown as Parameters<typeof useStepHandler>[0];
}

/** Renders the hook and hands back both the handler and the options it saw. */
function setup() {
  const engine = makeEngine();
  const options = makeOptions(engine, patternArmedOnStepZero());
  const { result } = renderHook(() => useStepHandler(options));
  return { engine, options, onStep: (step: number, time: number) => result.current.onStep(step, time) };
}

const synthTracksPlayed = (engine: ReturnType<typeof makeEngine>) =>
  engine.playSynth.mock.calls.map((c) => c[6]);
const drumsPlayed = (engine: ReturnType<typeof makeEngine>) =>
  engine.playDrum.mock.calls.map((c) => c[0]);

describe('useStepHandler mute/solo gating', () => {
  beforeEach(() => {
    trackMuteSoloStore.reset();
  });

  it('does not trigger a muted synth track but still triggers the others', () => {
    const { engine, onStep } = setup();
    trackMuteSoloStore.toggleMute('partA');

    onStep(0, 1.0);

    expect(synthTracksPlayed(engine)).toEqual(expect.arrayContaining(['partB', 'bass2']));
    expect(synthTracksPlayed(engine)).not.toContain('partA');
  });

  it('does not trigger a muted drum track', () => {
    const { engine, onStep } = setup();
    trackMuteSoloStore.toggleMute('kick');

    onStep(0, 1.0);

    expect(drumsPlayed(engine)).not.toContain('kick');
    expect(drumsPlayed(engine)).toEqual(expect.arrayContaining(['snare', 'openHat']));
  });

  it('does not trigger the sampler when the sampler track is muted', () => {
    const { engine, onStep } = setup();
    trackMuteSoloStore.toggleMute('sampler');

    onStep(0, 1.0);

    expect(engine.playSampler).not.toHaveBeenCalled();
  });

  it('sounds only the soloed track', () => {
    const { engine, onStep } = setup();
    trackMuteSoloStore.toggleSolo('bass2');

    onStep(0, 1.0);

    expect(synthTracksPlayed(engine)).toEqual(['bass2']);
    expect(engine.playDrum).not.toHaveBeenCalled();
    expect(engine.playSampler).not.toHaveBeenCalled();
  });

  it('sounds a track that is both muted and soloed', () => {
    const { engine, onStep } = setup();
    trackMuteSoloStore.toggleMute('partA');
    trackMuteSoloStore.toggleSolo('partA');

    onStep(0, 1.0);

    expect(synthTracksPlayed(engine)).toEqual(['partA']);
  });

  it('sounds every soloed track when several are soloed', () => {
    const { engine, onStep } = setup();
    trackMuteSoloStore.toggleSolo('partB');
    trackMuteSoloStore.toggleSolo('kick');

    onStep(0, 1.0);

    expect(synthTracksPlayed(engine)).toEqual(['partB']);
    expect(drumsPlayed(engine)).toEqual(['kick']);
  });

  it('keeps the playhead advancing with every track muted', () => {
    const { engine, options, onStep } = setup();
    for (const key of TRACK_KEYS) trackMuteSoloStore.toggleMute(key);

    onStep(7, 1.0);

    // Playhead advanced: step ref and the sequencer highlight both moved.
    expect(options.currentStepRef.current).toBe(7);
    expect(options.sequencerRef.current!.setHighlight).toHaveBeenCalledWith(7);

    // ...and nothing sounded.
    expect(engine.playSynth).not.toHaveBeenCalled();
    expect(engine.playDrum).not.toHaveBeenCalled();
    expect(engine.playSampler).not.toHaveBeenCalled();

    onStep(8, 1.5);
    expect(options.currentStepRef.current).toBe(8);
    expect(options.sequencerRef.current!.setHighlight).toHaveBeenCalledWith(8);
  });

  it('stops the voices of a track exactly once when it becomes silenced', () => {
    const { engine, onStep } = setup();

    onStep(0, 1.0);
    expect(engine.stopTrackNotes).not.toHaveBeenCalled();

    trackMuteSoloStore.toggleMute('partA');
    onStep(1, 1.5);
    expect(engine.stopTrackNotes).toHaveBeenCalledWith('partA');
    expect(engine.stopTrackNotes).toHaveBeenCalledTimes(1);

    // A muted track never triggers, so there is nothing left to release.
    onStep(2, 2.0);
    expect(engine.stopTrackNotes).toHaveBeenCalledTimes(1);
  });

  it('stops every non-soloed track when a solo is engaged', () => {
    const { engine, onStep } = setup();

    onStep(0, 1.0);
    trackMuteSoloStore.toggleSolo('bass2');
    onStep(1, 1.5);

    const stopped = engine.stopTrackNotes.mock.calls.map((c) => c[0]);
    expect(stopped).toEqual(expect.arrayContaining(['partA', 'partB', 'kick', 'sampler']));
    expect(stopped).not.toContain('bass2');
  });
});

import { describe, it, expect, vi } from 'vitest';
import { renderHook } from '@testing-library/react';
import { useStepHandler } from '../useStepHandler';
import type { Note, Pattern, PartSequence } from '../../types';
