  const armed = (): PartSequence => {
    const seq = emptySeq();
    seq.steps[0] = { note: 'C3', velocity: 1, length: 1 };
    return seq;
  };
  return {
    partA: armed(),
    partB: armed(),
    bass2: armed(),
    kick: armed(),
    snare: armed(),
    closedHat: armed(),
    openHat: armed(),
    sampler: Array.from({ length: 8 }, (_, i) => (i === 0 ? armed() : emptySeq())),
  } as unknown as Pattern;
}

const ref = <T,>(current: T) => ({ current });

function makeEngine() {
  return {
    context: { currentTime: 0, sampleRate: 48000 },
    playSynth: vi.fn(),
    playDrum: vi.fn(),
    playSampler: vi.fn(),
    stopTrackNotes: vi.fn(),
    open303Engine: null,
    updateSamplerVoiceParams: vi.fn(),
  };
}

function makeOptions(engine: ReturnType<typeof makeEngine>, pattern: Pattern) {
  const trackStorage = {} as Record<TrackKey, (PartSequence | PartSequence[] | null)[]>;
  return {
    audioEngine: engine as never,
    tempo: 120,
    onParamChange: undefined,
    currentStepRef: ref(-1),
    sequencerRef: ref(null),
    patternRef: ref(pattern),
    lastFreqRef: ref({} as Record<string, number>),
    lastSamplerMidiRef: ref({} as Record<number, number>),
    lastSamplerFormantRef: ref({} as Record<number, number>),
    synthARef: ref({ waveform: 'sawtooth' } as never),
    synthBRef: ref({ waveform: 'sawtooth' } as never),
    bass2Ref: ref({ waveform: 'sawtooth', cutoff: 0.5, resonance: 0.5, decay: 0.3, volume: 0.8 } as never),
    kickRef: ref({}),
    snareRef: ref({}),
    closedHatRef: ref({}),
    openHatRef: ref({}),
    currentScaleRef: ref(null),
    samplerRef: ref(Array.from({ length: 8 }, () => ({})) as never),
    samplerVoiceParamsRef: ref({
      drive: 0, rootNote: 60, coarseTune: 0, fineTune: 0, formantShift: 0,
      attack: 0.01, decay: 0.2, stretchProfile: 'vocal', stretchMode: 'Time',
      lockToSequencer: false,
    } as never),
    activeSamplerBankRef: ref(0),
    sliceHighlightRef: ref(null),
    isSongModeActiveRef: ref(false),
    songStructureRef: ref([]),
    songMeasureRef: ref(0),
    isFirstStepRef: ref(true),
    trackStorageRef: ref(trackStorage),
    setCurrentSongMeasure: vi.fn(),
  } as unknown as Parameters<typeof useStepHandler>[0];
}

describe('useStepHandler trigger dispatch', () => {
  it('fires exactly one trigger per armed track on the armed step', () => {
    const engine = makeEngine();
    const { result } = renderHook(() =>
      useStepHandler(makeOptions(engine, patternArmedOnStepZero())),
    );

    result.current.onStep(0, 1.0);

    const synthTracks = engine.playSynth.mock.calls.map((c) => c[6]);
    expect(synthTracks).toEqual(expect.arrayContaining(['partA', 'partB', 'bass2']));
    expect(synthTracks).toHaveLength(3);

    const drums = engine.playDrum.mock.calls.map((c) => c[0]);
    // openHat armed on this step suppresses closedHat by design.
    expect(drums).toEqual(expect.arrayContaining(['kick', 'snare', 'openHat']));

    expect(engine.playSampler).toHaveBeenCalledTimes(1);
  });

  it('fires nothing on a step where no track is armed', () => {
    const engine = makeEngine();
    const { result } = renderHook(() =>
      useStepHandler(makeOptions(engine, patternArmedOnStepZero())),
    );

    result.current.onStep(5, 1.0);

    expect(engine.playSynth).not.toHaveBeenCalled();
    expect(engine.playDrum).not.toHaveBeenCalled();
    expect(engine.playSampler).not.toHaveBeenCalled();
  });
});

import { renderHook, act } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { useTimelineZoom } from '../useTimelineZoom';
import { MIN_ZOOM, MAX_ZOOM, DEFAULT_ZOOM } from '../../components/sequencer/constants';

function makeContainer() {
    const el = document.createElement('div');
    document.body.appendChild(el);
    return el;
}

/** Intercept a named event listener registered via addEventListener and return a fire helper. */
function captureListener(el: HTMLElement, eventType: string): (e: any) => void {
    const captured: Array<(e: any) => void> = [];
    const original = el.addEventListener.bind(el);
    vi.spyOn(el, 'addEventListener').mockImplementation((type: string, handler: any, ...rest: any[]) => {
        if (type === eventType) captured.push(handler);
        original(type, handler, ...rest);
    });
    return (e: any) => captured.forEach(h => h(e));
}

describe('useTimelineZoom', () => {
    let container: HTMLDivElement;
    let containerRef: React.RefObject<HTMLDivElement>;

    beforeEach(() => {
        container = makeContainer();
        containerRef = { current: container };
    });

    afterEach(() => {
        container.remove();
        vi.restoreAllMocks();
    });

    it('exports zoom constants with correct values', () => {
        expect(MIN_ZOOM).toBe(0.5);
        expect(MAX_ZOOM).toBe(4.0);
        expect(DEFAULT_ZOOM).toBe(1.0);
    });

    it('returns handleDoubleClick that resets zoom to DEFAULT_ZOOM', () => {
        let zoom = 2;
        vi.useFakeTimers();
        const onZoomChange = vi.fn().mockImplementation((newZoom: number) => {
            zoom = newZoom;
        });
        const { result } = renderHook(() =>
            useTimelineZoom({ containerRef, zoom, onZoomChange })
        );
        act(() => {
            result.current.handleDoubleClick();
            vi.runAllTimers();
        });
        expect(onZoomChange).toHaveBeenCalledWith(DEFAULT_ZOOM);
        expect(zoom).toBe(DEFAULT_ZOOM);
        vi.useRealTimers();
    });

    it('zooms in on Ctrl+wheel with negative deltaY', () => {
        let zoom = 1;
        vi.useFakeTimers();
        const fireWheel = captureListener(container, 'wheel');

        const onZoomChange = vi.fn().mockImplementation((newZoom: number) => {
            zoom = newZoom;
        });

        renderHook(() => useTimelineZoom({ containerRef, zoom, onZoomChange }));

        act(() => {
            fireWheel({ ctrlKey: true, metaKey: false, deltaY: -100, preventDefault: vi.fn() });
            vi.runAllTimers();
        });

        // deltaY = -100, -(−100)*0.001 = +0.1 → zoom 1.0 → 1.1
        expect(onZoomChange).toHaveBeenCalled();
        expect(zoom).toBeCloseTo(1.1, 1);
        vi.useRealTimers();
    });

    it('zooms out on Ctrl+wheel with positive deltaY', () => {
        let zoom = 2;
        vi.useFakeTimers();
        const fireWheel = captureListener(container, 'wheel');

        const onZoomChange = vi.fn().mockImplementation((newZoom: number) => {
            zoom = newZoom;
        });

        renderHook(() => useTimelineZoom({ containerRef, zoom, onZoomChange }));

        act(() => {
            fireWheel({ ctrlKey: true, metaKey: false, deltaY: 100, preventDefault: vi.fn() });
            vi.runAllTimers();
        });

        // deltaY = +100, -(100)*0.001 = -0.1 → zoom 2.0 → 1.9
        expect(onZoomChange).toHaveBeenCalled();
        expect(zoom).toBeCloseTo(1.9, 1);
        vi.useRealTimers();
    });

    it('does NOT zoom on plain wheel (no Ctrl key)', () => {
        let zoom = 1;
        vi.useFakeTimers();
        const fireWheel = captureListener(container, 'wheel');

        const onZoomChange = vi.fn().mockImplementation((newZoom: number) => {
            zoom = newZoom;
        });

        renderHook(() => useTimelineZoom({ containerRef, zoom, onZoomChange }));

        act(() => {
            fireWheel({ ctrlKey: false, metaKey: false, deltaY: -200, preventDefault: vi.fn() });
            vi.runAllTimers();
        });

        expect(onZoomChange).not.toHaveBeenCalled();
        expect(zoom).toBe(1);
        vi.useRealTimers();
    });

    it('clamps zoom to MIN_ZOOM on large outward scroll', () => {
        let zoom = 0.6;
        vi.useFakeTimers();
        const fireWheel = captureListener(container, 'wheel');

        const onZoomChange = vi.fn().mockImplementation((newZoom: number) => {
            zoom = newZoom;
        });

        renderHook(() => useTimelineZoom({ containerRef, zoom, onZoomChange }));

        act(() => {
            fireWheel({ ctrlKey: true, metaKey: false, deltaY: 10000, preventDefault: vi.fn() });
            vi.runAllTimers();
        });

        expect(zoom).toBe(MIN_ZOOM);
        vi.useRealTimers();
    });

    it('clamps zoom to MAX_ZOOM on large inward scroll', () => {
        let zoom = 3.8;
        vi.useFakeTimers();
        const fireWheel = captureListener(container, 'wheel');

        const onZoomChange = vi.fn().mockImplementation((newZoom: number) => {
            zoom = newZoom;
        });

        renderHook(() => useTimelineZoom({ containerRef, zoom, onZoomChange }));

        act(() => {
            fireWheel({ ctrlKey: true, metaKey: false, deltaY: -10000, preventDefault: vi.fn() });
            vi.runAllTimers();
        });

        expect(zoom).toBe(MAX_ZOOM);
        vi.useRealTimers();
    });

    it('resets zoom to DEFAULT_ZOOM on double pointer tap', () => {
        let zoom = 2.5;
        vi.useFakeTimers();
        const firePointerDown = captureListener(container, 'pointerdown');

        const onZoomChange = vi.fn().mockImplementation((newZoom: number) => {
            zoom = newZoom;
        });

        renderHook(() => useTimelineZoom({ containerRef, zoom, onZoomChange }));

        act(() => {
            const makeTap = () => ({ isPrimary: true, pointerId: 1, clientX: 10, clientY: 10 });
            firePointerDown(makeTap());
            firePointerDown(makeTap());
            vi.runAllTimers();
        });

        expect(zoom).toBe(DEFAULT_ZOOM);
        vi.useRealTimers();
    });
});

import type { Note, Pattern, PartSequence } from '../../types'

type StepUpdater = (s: Note | null) => Note | null;
type NonSamplerTrackKey = Exclude<keyof Pattern, 'sampler'>;

export const updateSamplerStep = (prev: Pattern, bankIdx: number, step: number, updater: StepUpdater): Pattern => {
    const newSampler = [...prev.sampler];
    const newSteps = [...newSampler[bankIdx].steps];
    newSteps[step] = updater(newSteps[step]);
    newSampler[bankIdx] = { ...newSampler[bankIdx], steps: newSteps };
    return {
        ...prev,
        sampler: newSampler,
    };
};

export const updateTrackStep = (prev: Pattern, trackKey: keyof Pattern, step: number, updater: StepUpdater): Pattern => {
    if (trackKey === 'sampler') return prev;
    const track = prev[trackKey as NonSamplerTrackKey] as PartSequence;
    const newSteps = [...track.steps];
    newSteps[step] = updater(newSteps[step]);
    return {
        ...prev,
        [trackKey]: {
            ...track,
            steps: newSteps,
        },
    };
};

export const updateSamplerRange = (prev: Pattern, bankIdx: number, low: number, high: number, updater: StepUpdater): Pattern => {
    const newSampler = [...prev.sampler];
    const newSteps = [...newSampler[bankIdx].steps];
    for (let j = low; j <= high; j++) {
        newSteps[j] = updater(newSteps[j]);
    }
    newSampler[bankIdx] = { ...newSampler[bankIdx], steps: newSteps };
    return {
        ...prev,
        sampler: newSampler,
    };
};

export const updateTrackRange = (prev: Pattern, trackKey: keyof Pattern, low: number, high: number, updater: StepUpdater): Pattern => {
    if (trackKey === 'sampler') return prev;
    const track = prev[trackKey as NonSamplerTrackKey] as PartSequence;
    const newSteps = [...track.steps];
    for (let j = low; j <= high; j++) {
        newSteps[j] = updater(newSteps[j]);
    }
    return {
        ...prev,
        [trackKey]: {
            ...track,
            steps: newSteps,
        },
    };
};

import { useCallback } from 'react'
import type { AudioEngine, Pattern, PartSequence, SamplerParams } from '../../types'

export function useAutoMix(deps: {
    patternRef: React.MutableRefObject<Pattern>;
    updateSynthA: (updates: any) => void;
    updateSynthB: (updates: any) => void;
    updateBass2: (updates: any) => void;
    updateKick: (updates: any) => void;
    updateSnare: (updates: any) => void;
    updateClosedHat: (updates: any) => void;
    updateOpenHat: (updates: any) => void;
    setSampler: React.Dispatch<React.SetStateAction<SamplerParams>>;
    setMasterVolume: React.Dispatch<React.SetStateAction<number>>;
    audioEngine: AudioEngine | null;
    synthA: { filterCutoff: number; filterResonance: number };
    synthB: { filterCutoff: number; filterResonance: number };
}) {
    const {
        patternRef, updateSynthA, updateSynthB, updateBass2, updateKick, updateSnare,
        updateClosedHat, updateOpenHat, setSampler, setMasterVolume, audioEngine,
        synthA, synthB,
    } = deps;

    const handleAutoMix = useCallback(() => {
        const pattern = patternRef.current;
        const calculateActivity = (trackSeq: PartSequence | null | undefined) => {
            if (!trackSeq || !trackSeq.steps) return 0;
            let activeSteps = 0;
            let totalVelocity = 0;
            const steps = trackSeq.steps;
            for (let i = 0; i < steps.length; i++) {
                const step = steps[i];
                if (step) {
                    activeSteps++;
                    totalVelocity += step.velocity || 1;
                }
            }
            return activeSteps === 0 ? 0 : totalVelocity / steps.length;
        };

        const synthAActivity = calculateActivity(pattern.partA);
        const synthBActivity = calculateActivity(pattern.partB);
        const bassActivity = calculateActivity(pattern.bass2);
        const kickActivity = calculateActivity(pattern.kick);
        const snareActivity = calculateActivity(pattern.snare);
        const closedHatActivity = calculateActivity(pattern.closedHat);
        const openHatActivity = calculateActivity(pattern.openHat);

        const samplerActivities = new Array(pattern.sampler.length);
        let totalSamplerActivity = 0;
        for (let i = 0; i < pattern.sampler.length; i++) {
            const activity = calculateActivity(pattern.sampler[i]);
            samplerActivities[i] = activity;
            totalSamplerActivity += activity;
        }

        let synthAPan = -0.3;
        let synthBPan = 0.3;
        if (synthAActivity > 0 && synthBActivity === 0) {
            synthAPan = 0;
        } else if (synthBActivity > 0 && synthAActivity === 0) {
            synthBPan = 0;
        }

        updateSynthA({ pan: synthAPan });
        updateSynthB({ pan: synthBPan });
        updateBass2({ pan: 0 });
        updateKick({ pan: 0 });
        updateSnare({ pan: 0 });
        updateClosedHat({ pan: 0.15 });
        updateOpenHat({ pan: 0.25 });

        setSampler(prev => {
            const next = [...prev];
            let panSpread = 0.4;
            if (totalSamplerActivity > 0.5) panSpread = 0.6;
            for (let i = 0; i < 8; i++) {
                const direction = i % 2 === 0 ? -1 : 1;
                const width = panSpread + (i * 0.05 * direction);
                next[i] = { ...next[i], pan: i === 0 ? 0 : Math.max(-1, Math.min(1, width)) };
            }
            return next;
        });

        const scaleVolume = (baseVol: number, activity: number) => {
            if (activity === 0) return baseVol;
            const reduction = Math.min(0.15, activity * 0.2);
            return Math.max(0.1, baseVol - reduction);
        };

        updateSynthA({ volume: scaleVolume(0.7, synthAActivity) });
        updateSynthB({ volume: scaleVolume(0.7, synthBActivity) });
        updateBass2({ volume: scaleVolume(0.85, bassActivity) });
        updateKick({ volume: scaleVolume(0.95, kickActivity) });
        updateSnare({ volume: scaleVolume(0.85, snareActivity) });
        updateClosedHat({ volume: scaleVolume(0.6, closedHatActivity) });
        updateOpenHat({ volume: scaleVolume(0.65, openHatActivity) });

        setSampler(prev => {
            const next = [...prev];
            for (let i = 0; i < 8; i++) {
                next[i] = { ...next[i], volume: scaleVolume(0.75, samplerActivities[i]) };
            }
            return next;
        });

        if (bassActivity > 0.1) {
            updateSynthA({ filterCutoff: Math.max(synthA.filterCutoff, 250) });
            updateSynthB({ filterCutoff: Math.max(synthB.filterCutoff, 250) });
        } else {
            if (synthA.filterCutoff > 100) updateSynthA({ filterCutoff: 100 });
            if (synthB.filterCutoff > 100) updateSynthB({ filterCutoff: 100 });
        }

        if (totalSamplerActivity > 0.3) {
            updateSynthA({ filterResonance: Math.min(synthA.filterResonance, 3) });
            updateSynthB({ filterResonance: Math.min(synthB.filterResonance, 3) });
        }

        setMasterVolume(0.85);
        if (audioEngine) {
            audioEngine.setMasterVolume(0.85);
        }

        console.log("Auto-Mix Assistant applied dynamic, content-aware mixing parameters.");
    }, [updateSynthA, updateSynthB, updateBass2, updateKick, updateSnare, updateClosedHat, updateOpenHat, audioEngine, synthA.filterCutoff, synthA.filterResonance, synthB.filterCutoff, synthB.filterResonance, setSampler, setMasterVolume, patternRef]);

    return { handleAutoMix };
}

import { useCallback, useEffect } from 'react'
import { automationStore } from '../../stores/automationStore'
import { NUM_STEPS } from '../../constants'
import type { Pattern, PartSequence, AutomationTarget } from '../../types'
import type { TrackKey } from '../../constants/appDefaults'
import { GLOBAL_ARM_PARAMS } from './constants'

type NonSamplerTrackKey = Exclude<keyof Pattern, 'sampler'>;

export function useAutomationHandlers(deps: {
    automationParam: string;
    patternRef: React.MutableRefObject<Pattern>;
    setPattern: React.Dispatch<React.SetStateAction<Pattern>>;
    activeSamplerBankRef: React.MutableRefObject<number>;
    updateStorageForTrack: (track: TrackKey, sequence: PartSequence | PartSequence[]) => void;
    currentStepRef: React.MutableRefObject<number>;
    schedPlaying: boolean;
    isAutomationRecording: boolean;
    isSongModeActive: boolean;
    activeTrackSlotsRef: React.MutableRefObject<Record<TrackKey, number>>;
    isSongModeActiveRef: React.MutableRefObject<boolean>;
}) {
    const {
        automationParam, patternRef, setPattern, activeSamplerBankRef, updateStorageForTrack,
        currentStepRef, schedPlaying, isAutomationRecording, isSongModeActive,
        activeTrackSlotsRef, isSongModeActiveRef,
    } = deps;

    const handleAutomationChange = useCallback((trackKey: TrackKey, step: number, value: number) => {
        const prev = patternRef.current;
        let newPattern = prev;

        if (trackKey === 'sampler') {
            const bankIdx = activeSamplerBankRef.current;
            const bank = prev.sampler[bankIdx];
            const nextAutomation: { [param: string]: (number | null)[] } = bank.automation ? { ...bank.automation } : {};
            const nextParamArray: (number | null)[] = nextAutomation[automationParam]
                ? [...nextAutomation[automationParam]]
                : Array<number | null>(NUM_STEPS).fill(null);

            nextParamArray[step] = value;

            nextAutomation[automationParam] = nextParamArray;
            const newSampler = [...prev.sampler];
            newSampler[bankIdx] = { ...newSampler[bankIdx], automation: nextAutomation };
            newPattern = {
                ...prev,
                sampler: newSampler
            };
            updateStorageForTrack(trackKey, newPattern.sampler);
        } else {
            const track = prev[trackKey as NonSamplerTrackKey];
            const nextAutomation: { [param: string]: (number | null)[] } = track.automation ? { ...track.automation } : {};
            const nextParamArray: (number | null)[] = nextAutomation[automationParam]
                ? [...nextAutomation[automationParam]]
                : Array<number | null>(NUM_STEPS).fill(null);

            nextParamArray[step] = value;

            nextAutomation[automationParam] = nextParamArray;
            const nextTrack = { ...track, automation: nextAutomation };
            newPattern = { ...prev, [trackKey]: nextTrack };
            updateStorageForTrack(trackKey, newPattern[trackKey]);
        }

        setPattern(newPattern);
    }, [automationParam, updateStorageForTrack, activeSamplerBankRef, patternRef, setPattern]);

    const handleKnobRecordToggle = useCallback((target: AutomationTarget, paramId: string) => {
        if (automationStore.isParameterArmed(target, paramId)) {
            if (schedPlaying) {
                const scope: 'pattern' | 'song' = isSongModeActiveRef.current ? 'song' : 'pattern';
                const patternIdx = isSongModeActiveRef.current ? undefined : (activeTrackSlotsRef.current['partA'] ?? 0);
                automationStore.stopRecording(target, paramId, { scope, patternIndex: patternIdx, name: `${target}.${paramId} (recorded)` });
            } else {
                automationStore.cancelRecording(target, paramId);
            }
            automationStore.disarmParameter(target, paramId);
        } else {
            automationStore.armParameter(target, paramId);
            if (schedPlaying) {
                automationStore.startRecording(target, paramId);
            }
        }
    }, [schedPlaying, isSongModeActiveRef, activeTrackSlotsRef]);

    useEffect(() => {
        if (isAutomationRecording && schedPlaying) {
            for (let i = 0; i < GLOBAL_ARM_PARAMS.length; i++) {
                const { target, param } = GLOBAL_ARM_PARAMS[i];
                if (!automationStore.isParameterArmed(target, param)) {
                    automationStore.armParameter(target, param);
                }
                const buf = automationStore.getState().recordingBuffers.find(b => b.target === target && b.parameter === param && b.isRecording);
                if (!buf) {
                    automationStore.startRecording(target, param);
                }
            }
        } else if (!isAutomationRecording || !schedPlaying) {
            for (let i = 0; i < GLOBAL_ARM_PARAMS.length; i++) {
                const { target, param } = GLOBAL_ARM_PARAMS[i];
                if (automationStore.isParameterArmed(target, param)) {
                    const scope: 'pattern' | 'song' = isSongModeActive ? 'song' : 'pattern';
                    const patternIdx = isSongModeActive ? undefined : (activeTrackSlotsRef.current['partA'] ?? 0);
                    automationStore.stopRecording(target, param, { scope, patternIndex: patternIdx, name: `${target}.${param} (recorded)` });
                    automationStore.disarmParameter(target, param);
                }
            }
        }
    }, [isAutomationRecording, schedPlaying, isSongModeActive, activeTrackSlotsRef]);

    const handleAutomationNudge = useCallback((target: AutomationTarget, paramId: string, value: number, step: number) => {
        const patternIdx = isSongModeActiveRef.current ? 0 : (activeTrackSlotsRef.current['partA'] ?? 0);
        const lane = automationStore.getPrimaryLaneForParam(target, paramId, patternIdx);
        if (lane) {
            automationStore.upsertLanePoint(lane.id, step, value);
        }
    }, [isSongModeActiveRef, activeTrackSlotsRef]);

    const handleAutomationPunchIn = useCallback((target: AutomationTarget, paramId: string) => {
        if (!schedPlaying) return;
        if (!automationStore.isParameterArmed(target, paramId)) {
            automationStore.armParameter(target, paramId);
            automationStore.startRecording(target, paramId);
        }
    }, [schedPlaying]);

    const handleAutomationLaneAction = useCallback((
        target: AutomationTarget,
        action: 'toggle' | 'clear',
        paramId?: string,
    ) => {
        if (!paramId) return;
        if (action === 'clear') {
            automationStore.clearLanesForParam(target, paramId);
            return;
        }
        const patternIdx = isSongModeActiveRef.current ? 0 : (activeTrackSlotsRef.current['partA'] ?? 0);
        const lane = automationStore.getPrimaryLaneForParam(target, paramId, patternIdx);
        if (lane) {
            automationStore.toggleLaneEnabled(lane.id);
        } else {
            automationStore.setLanesEnabledForParam(target, paramId, true);
        }
    }, [isSongModeActiveRef, activeTrackSlotsRef]);

    return {
        handleAutomationChange,
        handleKnobRecordToggle,
        handleAutomationNudge,
        handleAutomationPunchIn,
        handleAutomationLaneAction,
    };
}

import { useCallback, useEffect } from 'react'
import { copySteps, pasteSteps } from '../../utils/clipboardUtils'
import type { Note, Pattern } from '../../types'
import type { TrackKey } from '../../constants/appDefaults'
import type { useUndoRedo } from '../useUndoRedo'
import { updateSamplerRange, updateTrackRange } from './patternUpdates'

type UndoRedo = ReturnType<typeof useUndoRedo<Pattern>>

export function useClipboardHandlers(deps: {
    selection: { trackKey: TrackKey; startStep: number; endStep: number; } | null;
    selectedTrack: TrackKey;
    clipboard: (Note | null)[] | null;
    setClipboard: React.Dispatch<React.SetStateAction<(Note | null)[] | null>>;
    setPattern: React.Dispatch<React.SetStateAction<Pattern>>;
    setSelection: React.Dispatch<React.SetStateAction<{ trackKey: TrackKey; startStep: number; endStep: number; } | null>>;
    patternRef: React.MutableRefObject<Pattern>;
    activeSamplerBankRef: React.MutableRefObject<number>;
    undoRedo: UndoRedo;
    updateStorageForTrack: (track: TrackKey, sequence: any) => void;
    showToast: (message: string, type?: 'success' | 'error' | 'info') => void;
    handleSelectionEnd: () => void;
    audioEngine: { triggerTapeStop?: (duration: number) => void } | null | undefined;
}) {
    const {
        selection, selectedTrack, clipboard, setClipboard, setPattern, setSelection,
        patternRef, activeSamplerBankRef, undoRedo, updateStorageForTrack, showToast,
        handleSelectionEnd, audioEngine,
    } = deps;

    const handleCopy = useCallback(() => {
        if (!selection) return;
        const copied = copySteps(patternRef.current, selection, activeSamplerBankRef.current);
        if (copied) {
            setClipboard(copied);
            showToast("Copied to clipboard!", "success");
        }
    }, [selection, showToast, patternRef, activeSamplerBankRef, setClipboard]);

    const handlePaste = useCallback(() => {
        if (!clipboard) return;
        let targetTrack = selectedTrack;
        let targetStep = 0;
        if (selection) {
            targetTrack = selection.trackKey;
            targetStep = selection.startStep;
        } else {
             if (!window.confirm(`Paste from clipboard to start of ${targetTrack}?`)) return;
        }
        undoRedo.push(patternRef.current);
        const newPattern = pasteSteps(patternRef.current, clipboard, targetTrack, targetStep, activeSamplerBankRef.current);
        setPattern(newPattern);
        let changedSequence;
        if (targetTrack === 'sampler') {
            changedSequence = newPattern.sampler;
        } else {
            changedSequence = newPattern[targetTrack];
        }
        updateStorageForTrack(targetTrack, changedSequence);
        showToast("Pasted from clipboard!", "success");
    }, [clipboard, selection, selectedTrack, showToast, updateStorageForTrack, undoRedo, patternRef, activeSamplerBankRef, setPattern]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

            if ((e.ctrlKey || e.metaKey) && e.key === 'c') {
                e.preventDefault();
                handleCopy();
            }

            if ((e.ctrlKey || e.metaKey) && e.key === 'v') {
                e.preventDefault();
                handlePaste();
            }

            if ((e.key === 'Delete' || e.key === 'Backspace') && selection) {
                const { trackKey, startStep, endStep } = selection;
                const low = Math.min(startStep, endStep);
                const high = Math.max(startStep, endStep);

                setPattern(prev => {
                    let newPattern;
                    if (trackKey === 'sampler') {
                        const bankIdx = activeSamplerBankRef.current;
                        newPattern = updateSamplerRange(prev, bankIdx, low, high, () => null);
                        updateStorageForTrack(trackKey, newPattern.sampler);
                    } else {
                        newPattern = updateTrackRange(prev, trackKey, low, high, () => null);
                        updateStorageForTrack(trackKey, newPattern[trackKey]);
                    }
                    return newPattern;
                });

                setSelection(null);
            }

            if (e.key === 'Escape' && !e.ctrlKey && !e.metaKey && !e.altKey) {
                e.preventDefault();
                audioEngine?.triggerTapeStop?.(2.0);
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        window.addEventListener('mouseup', handleSelectionEnd);

        return () => {
            window.removeEventListener('keydown', handleKeyDown);
            window.removeEventListener('mouseup', handleSelectionEnd);
        };
    }, [selection, handleSelectionEnd, updateStorageForTrack, handleCopy, handlePaste, activeSamplerBankRef, setPattern, setSelection, audioEngine]);

    return { handleCopy, handlePaste };
}

