        const currentTypeA: OscillatorType = waveformToOscillatorType(
            synthA.waveform,
            legacyEngine303ForModel(realtimeA),
        );
        const panelClassesA = getOscillatorPanelClasses(currentTypeA);

        const handleSynthAVoiceChange = (m: TB303ModelId) => {
