import { useCallback, useEffect, useRef, useState } from 'react';
import type { TrackKey } from '../../constants/appDefaults';
import { useUndoRedo } from '../useUndoRedo';
import { SessionLaunchEngine } from '../../session/SessionLaunchEngine';
import { createDefaultSessionDocument } from '../../session/defaults';
import { captureEventsToSongStructure } from '../../session/capture';
import { parseSessionMidiParam } from '../../session/midiMap';
import type { LaunchQuantization, SessionDocument } from '../../session/types';
import type { SongStructure } from '../../types/songMode';
import { getSessionPack, mergePackStorage } from '../../session/packs';
import type { TrackStorageMap } from '../../utils/trackStorageUtils';

export function useSessionState() {
  const [isSessionOpen, setIsSessionOpen] = useState(false);
  const [sessionDocument, setSessionDocument] = useState<SessionDocument>(() => createDefaultSessionDocument());
  const [playingSlots, setPlayingSlots] = useState<Record<TrackKey, number | null>>(() => {
    const empty = {} as Record<TrackKey, number | null>;
    empty.partA = null;
    empty.partB = null;
    empty.bass2 = null;
    empty.kick = null;
    empty.snare = null;
    empty.closedHat = null;
    empty.openHat = null;
    empty.sampler = null;
    return empty;
  });
  const [isCapturing, setIsCapturing] = useState(false);
  const engineRef = useRef<SessionLaunchEngine | null>(null);
  if (!engineRef.current) {
    engineRef.current = new SessionLaunchEngine(sessionDocument);
  }
  const clockRef = useRef({ step: 0, audioTime: 0, tempo: 120 });
  const undo = useUndoRedo<SessionDocument>(40);
  const sessionDocumentRef = useRef(sessionDocument);
  useEffect(() => {
    sessionDocumentRef.current = sessionDocument;
  }, [sessionDocument]);

  useEffect(() => {
    engineRef.current?.setDocument(sessionDocument);
  }, [sessionDocument]);

  const replaceSession = useCallback((next: SessionDocument, recordUndo = true) => {
    if (recordUndo) undo.push(sessionDocument);
    setSessionDocument(next);
    engineRef.current?.setDocument(next);
  }, [sessionDocument, undo]);

  const launchClip = useCallback((track: TrackKey, row: number, source: 'manual' | 'midi' | 'gamepad' = 'manual', gateDown = true) => {
    const engine = engineRef.current;
    if (!engine) return;
    const clip = engine.document.columns[track]?.clips[row];
    if (!clip || clip.empty) return;
    engine.enqueue({
      kind: 'clip',
      source,
      requestAudioTime: clockRef.current.audioTime,
      requestStep: clockRef.current.step,
      track,
      clipId: clip.id,
      gateDown,
    }, {
      step: clockRef.current.step,
      audioTime: clockRef.current.audioTime || 0,
      tempo: clockRef.current.tempo,
      patternSteps: 32,
      stepsPerBeat: 4,
      stepsPerBar: 16,
      isPlaying: true,
      songModeActive: false,
    });
  }, []);

  const launchScene = useCallback((sceneIndex: number, source: 'manual' | 'midi' | 'gamepad' | 'scene' = 'scene') => {
    const engine = engineRef.current;
    if (!engine) return;
    const scene = engine.document.scenes[sceneIndex];
    if (!scene) return;
    engine.enqueue({
      kind: 'scene',
      source,
      requestAudioTime: clockRef.current.audioTime,
      requestStep: clockRef.current.step,
      sceneId: scene.id,
    }, {
      step: clockRef.current.step,
      audioTime: clockRef.current.audioTime || 0,
      tempo: clockRef.current.tempo,
      patternSteps: 32,
      stepsPerBeat: 4,
      stepsPerBar: 16,
      isPlaying: true,
      songModeActive: false,
    });
  }, []);

  const stopTrack = useCallback((track: TrackKey, source: 'manual' | 'midi' | 'gamepad' = 'manual') => {
    engineRef.current?.enqueue({
      kind: 'stop-track',
      source,
      requestAudioTime: clockRef.current.audioTime,
      requestStep: clockRef.current.step,
      track,
    }, {
      step: clockRef.current.step,
      audioTime: clockRef.current.audioTime || 0,
      tempo: clockRef.current.tempo,
      patternSteps: 32,
      stepsPerBeat: 4,
      stepsPerBar: 16,
      isPlaying: true,
      songModeActive: false,
    });
  }, []);

  const stopAll = useCallback(() => {
    engineRef.current?.enqueue({
      kind: 'stop-all',
      source: 'manual',
      requestAudioTime: clockRef.current.audioTime,
      requestStep: clockRef.current.step,
    }, {
      step: clockRef.current.step,
      audioTime: clockRef.current.audioTime || 0,
      tempo: clockRef.current.tempo,
      patternSteps: 32,
      stepsPerBeat: 4,
      stepsPerBar: 16,
      isPlaying: true,
      songModeActive: false,
    });
  }, []);

  const setQuantization = useCallback((q: LaunchQuantization) => {
    const engine = engineRef.current;
    if (!engine) return;
    undo.push(sessionDocument);
    engine.setQuantization(q);
    setSessionDocument({ ...engine.document });
  }, [sessionDocument, undo]);

  const handleSessionMidi = useCallback((param: string, normalized: number) => {
    const action = parseSessionMidiParam(param, normalized);
    if (!action) return;
    if (action.type === 'clip') launchClip(action.track, action.row, 'midi', action.down);
    else if (action.type === 'scene' && action.down) launchScene(action.sceneIndex, 'midi');
    else if (action.type === 'stop-track') stopTrack(action.track, 'midi');
    else if (action.type === 'stop-all') stopAll();
  }, [launchClip, launchScene, stopTrack, stopAll]);

  const beginCapture = useCallback(() => {
    engineRef.current?.armCapture();
    setIsCapturing(true);
  }, []);

  const finishCapture = useCallback((): SongStructure => {
    const events = engineRef.current?.disarmCapture() ?? [];
    setIsCapturing(false);
    return captureEventsToSongStructure(events);
  }, []);

  const undoSession = useCallback(() => {
    const prev = undo.undo();
    if (prev) {
      setSessionDocument(prev);
      engineRef.current?.setDocument(prev);
    }
  }, [undo]);

  const redoSession = useCallback(() => {
    const next = undo.redo();
    if (next) {
      setSessionDocument(next);
      engineRef.current?.setDocument(next);
    }
  }, [undo]);

  const loadPack = useCallback((packId: string, setTrackStorage: (s: TrackStorageMap | ((p: TrackStorageMap) => TrackStorageMap)) => void) => {
    const pack = getSessionPack(packId);
    if (!pack) return;
    undo.push(sessionDocument);
    setSessionDocument(pack.session);
    engineRef.current?.setDocument(pack.session);
    setTrackStorage((prev) => mergePackStorage(prev, pack.trackStorage));
  }, [sessionDocument, undo]);

  return {
    isSessionOpen,
    setIsSessionOpen,
    sessionDocument,
    setSessionDocument: replaceSession,
    playingSlots,
    setPlayingSlots,
    isCapturing,
    sessionEngineRef: engineRef,
    sessionClockRef: clockRef,
    sessionDocumentRef,
    launchClip,
    launchScene,
    stopTrack,
    stopAll,
    setQuantization,
    handleSessionMidi,
    beginCapture,
    finishCapture,
    undoSession,
    redoSession,
    canUndoSession: undo.canUndo,
    canRedoSession: undo.canRedo,
    loadPack,
  };
}

import { useCallback } from 'react'
import type { AudioEngine, Pattern, PartSequence, SynthParams, Bass2Params, KickParams, SnareParams, HatParams, SamplerParams } from '../../types'
import type { TrackKey, SongSnapshot } from '../../constants/appDefaults'
import type { AlignmentResult } from '../../engines/rubberband/PhonemeAligner'
import type { PyodideLike } from '../../utils/pyodideBuffers'

export function useSongHandlers(deps: {
    songStructure: ({ [key in TrackKey]: number | null })[];
    setSongStructure: React.Dispatch<React.SetStateAction<({ [key in TrackKey]: number | null })[]>>;
    setIsSongModeOpen: React.Dispatch<React.SetStateAction<boolean>>;
    patternRef: React.MutableRefObject<Pattern>;
    songStructureRef: React.MutableRefObject<({ [key in TrackKey]: number | null })[]>;
    trackStorageRef: React.MutableRefObject<Record<TrackKey, (PartSequence | PartSequence[] | null)[]>>;
    tempoRef: React.MutableRefObject<number>;
    synthARef: React.MutableRefObject<SynthParams>;
    synthBRef: React.MutableRefObject<SynthParams>;
    bass2Ref: React.MutableRefObject<Bass2Params>;
    kickRef: React.MutableRefObject<KickParams>;
    snareRef: React.MutableRefObject<SnareParams>;
    closedHatRef: React.MutableRefObject<HatParams>;
    openHatRef: React.MutableRefObject<HatParams>;
    samplerRef: React.MutableRefObject<SamplerParams>;
    audioEngine: AudioEngine | null;
    pyodide: PyodideLike | null;
    sampleBuffers: (AudioBuffer | null)[];
    showToast: (message: string, type?: 'success' | 'error' | 'info') => void;
}) {
    const {
        songStructure, setSongStructure, setIsSongModeOpen,
        patternRef, songStructureRef, trackStorageRef, tempoRef,
        synthARef, synthBRef, bass2Ref, kickRef, snareRef, closedHatRef, openHatRef, samplerRef,
        audioEngine, pyodide, sampleBuffers, showToast,
    } = deps;

    const handleSongModeToggle = useCallback(() => setIsSongModeOpen(prev => !prev), [setIsSongModeOpen]);

    const handleSongStructureUpdate = useCallback((idx: number, key: TrackKey, val: number | null) => {
        setSongStructure(prev => {
            const copy = [...prev];
            copy[idx] = { ...copy[idx], [key]: val };
            return copy;
        });
    }, [setSongStructure]);

    const handleAddMeasure = useCallback(() => {
        setSongStructure(prev => [...prev, {
            partA: null, partB: null, bass2: null, kick: null, snare: null,
            closedHat: null, openHat: null, sampler: null,
        }]);
    }, [setSongStructure]);

    const handleRemoveMeasure = useCallback(() => {
        const currentStructure = songStructure;
        if (currentStructure.length === 0) return;
        const last = currentStructure[currentStructure.length - 1];
        const hasData = Object.values(last).some(v => v !== null);
        if (hasData) {
            if (!window.confirm("The last measure contains patterns. Are you sure you want to remove it?")) return;
        }
        setSongStructure(prev => prev.slice(0, -1));
    }, [songStructure, setSongStructure]);

    const handleExportXM = useCallback(() => {
        // Dynamically imported so the XM writer (xm_save_lib) never lands in the
        // entry chunk — only an actual "Export XM" click does.
        void import('../../utils/xmExport').then(({ exportSongToXM }) => exportSongToXM(
            songStructureRef.current,
            trackStorageRef.current,
            {
                synthA: synthARef.current,
                synthB: synthBRef.current,
                bass2: bass2Ref.current,
                kick: kickRef.current,
                snare: snareRef.current,
                closedHat: closedHatRef.current,
                openHat: openHatRef.current,
                sampler: samplerRef.current,
            },
            tempoRef.current,
            patternRef.current,
            { webGpuEngine: audioEngine?.webGpuEngine, wasmEngine: audioEngine?.wasmEngine, pyodide },
            sampleBuffers,
        )).then(result => {
            // The .xm still downloaded; surface anything the format could not hold.
            if (result.truncationMessage) showToast(result.truncationMessage, 'error');
        }).catch((e: unknown) => {
            console.error('XM export failed:', e);
            showToast('XM export failed', 'error');
        });
    }, [audioEngine, pyodide, sampleBuffers, showToast, songStructureRef, trackStorageRef, tempoRef, patternRef, synthARef, synthBRef, bass2Ref, kickRef, snareRef, closedHatRef, openHatRef, samplerRef]);

    return {
        handleSongModeToggle,
        handleSongStructureUpdate,
        handleAddMeasure,
        handleRemoveMeasure,
        handleExportXM,
    };
}

export function useSampleHandlers(deps: {
    audioEngine: AudioEngine | null;
    activeSamplerBank: number;
    ttsPhrases: string[];
    setSampleBuffers: React.Dispatch<React.SetStateAction<(AudioBuffer | null)[]>>;
    setSampler: React.Dispatch<React.SetStateAction<SamplerParams>>;
    setActiveAlignment: React.Dispatch<React.SetStateAction<AlignmentResult | null>>;
}) {
    const { audioEngine, activeSamplerBank, ttsPhrases, setSampleBuffers, setSampler, setActiveAlignment } = deps;

    const handleLoadSample = useCallback(async (name: string, buffer: AudioBuffer, onProgress?: (progress: number) => void) => {
        if (!audioEngine) return;
        await audioEngine.loadSampleToEngine(name, buffer, onProgress);
        setSampleBuffers(prev => {
            const next = [...prev];
            next[activeSamplerBank] = buffer;
            return next;
        });
        const bankName = `bank_${activeSamplerBank}`;
        setSampler(prev => {
            const newParams = [...prev];
            newParams[activeSamplerBank] = { ...newParams[activeSamplerBank], sampleName: bankName };
            return newParams;
        });
        if (audioEngine.prepareVocal) {
            const text = ttsPhrases[activeSamplerBank] || "Hello World";
            void audioEngine.prepareVocal(activeSamplerBank, text).then(() => {
                if (audioEngine.getAlignment) {
                    setActiveAlignment(audioEngine.getAlignment(activeSamplerBank));
                }
            });
        }
    }, [audioEngine, activeSamplerBank, ttsPhrases, setSampleBuffers, setSampler, setActiveAlignment]);

    return { handleLoadSample };
}

import { useCallback } from 'react'
import { automationStore } from '../../stores/automationStore'
import type { AutomationTarget, SamplerBankParams, SamplerParams } from '../../types'

export function useSynthParamHandlers(deps: {
    updateSynthA: (updates: any) => void;
    updateSynthB: (updates: any) => void;
    updateBass2: (updates: any) => void;
    updateKick: (updates: any) => void;
    updateSnare: (updates: any) => void;
    updateClosedHat: (updates: any) => void;
    updateOpenHat: (updates: any) => void;
    setSampler: React.Dispatch<React.SetStateAction<SamplerParams>>;
    activeSamplerBank: number;
    currentStepRef: React.MutableRefObject<number>;
    samplerRef: React.MutableRefObject<SamplerParams>;
}) {
    const {
        updateSynthA, updateSynthB, updateBass2, updateKick, updateSnare,
        updateClosedHat, updateOpenHat, setSampler, activeSamplerBank,
        currentStepRef, samplerRef,
    } = deps;

    const handleSynthChange = useCallback((isA: boolean, id: string, val: number) => {
        const updater = isA ? updateSynthA : updateSynthB;
        let realVal = val;
        if (id === 'pitch') realVal = Math.floor(val * 48 - 24);
        else if (id === 'filterCutoff') realVal = val * 8000;
        else if (id === 'filterResonance') realVal = val * 20;
        else if (id === 'filterMode') realVal = Math.round(val);
        else if (id === 'decay') realVal = val * 2;
        else if (id === 'release') realVal = val * 2;
        else if (id === 'length') realVal = val * 2;
        updater({ [id]: realVal });
        const target: AutomationTarget = isA ? 'synthA' : 'synthB';
        if (automationStore.isParameterArmed(target, id)) {
            const step = automationStore.getState().playbackStep || currentStepRef.current || 0;
            automationStore.recordPoint(target, id, { step, value: Math.max(0, Math.min(1, val)) });
        }
    }, [updateSynthA, updateSynthB, currentStepRef]);

    const handleBass2Change = useCallback((id: string, val: number) => {
        let realVal = val;
        if (id === 'waveform') realVal = val > 0.5 ? 1 : 0;
        else if (id === 'cutoff') realVal = val * 8000;
        else if (id === 'resonance') realVal = val * 20;
        else if (id === 'filterMode') realVal = Math.round(val);
        else if (id === 'decay') realVal = val * 2;
        else if (id === 'pitch') realVal = Math.floor(val * 48 - 24);
        updateBass2({ [id]: realVal });
        if (automationStore.isParameterArmed('bass2', id)) {
            const step = automationStore.getState().playbackStep || currentStepRef.current || 0;
            automationStore.recordPoint('bass2', id, { step, value: Math.max(0, Math.min(1, val)) });
        }
    }, [updateBass2, currentStepRef]);

    const handleKickChange = useCallback((id: string, val: number) => {
        let realVal = val;
        if (id === 'pitch') realVal = val * 130 + 20;
        updateKick({ [id]: realVal });
        if (automationStore.isParameterArmed('kick', id)) {
            const step = automationStore.getState().playbackStep || currentStepRef.current || 0;
            automationStore.recordPoint('kick', id, { step, value: Math.max(0, Math.min(1, val)) });
        }
    }, [updateKick, currentStepRef]);

    const handleSnareChange = useCallback((id: string, val: number) => {
        let realVal = val;
        if (id === 'tone') realVal = val * 300 + 100;
        else if (id === 'noise') realVal = val * 7000 + 1000;
        else if (id === 'decay') realVal = val * 0.5;
        updateSnare({ [id]: realVal });
        if (automationStore.isParameterArmed('snare', id)) {
            const step = automationStore.getState().playbackStep || currentStepRef.current || 0;
            automationStore.recordPoint('snare', id, { step, value: Math.max(0, Math.min(1, val)) });
        }
    }, [updateSnare, currentStepRef]);

    const handleClosedHatChange = useCallback((id: string, val: number) => {
        updateClosedHat({ [id]: val });
        if (automationStore.isParameterArmed('closedHat', id)) {
            const step = automationStore.getState().playbackStep || currentStepRef.current || 0;
            automationStore.recordPoint('closedHat', id, { step, value: Math.max(0, Math.min(1, val)) });
        }
    }, [updateClosedHat, currentStepRef]);

    const handleOpenHatChange = useCallback((id: string, val: number) => {
        updateOpenHat({ [id]: val });
        if (automationStore.isParameterArmed('openHat', id)) {
            const step = automationStore.getState().playbackStep || currentStepRef.current || 0;
            automationStore.recordPoint('openHat', id, { step, value: Math.max(0, Math.min(1, val)) });
        }
    }, [updateOpenHat, currentStepRef]);

    const handleSamplerChange = useCallback((id: string, val: number) => {
        let realVal = val;
        if (id === 'playbackSpeed') realVal = val * 4.0;
        else if (id === 'filterCutoff') realVal = val * 20000;
        else if (id === 'filterResonance') realVal = val * 20;
        setSampler(prev => {
            const next = [...prev];
            const currentBank = next[activeSamplerBank];
            next[activeSamplerBank] = { ...currentBank, [id]: realVal };
            return next;
        });
        if (automationStore.isParameterArmed('sampler', id)) {
            const step = automationStore.getState().playbackStep || currentStepRef.current || 0;
            let norm = val;
            if (id === 'filterCutoff') norm = Math.max(0, Math.min(1, val / 20000));
            else if (id === 'filterResonance') norm = Math.max(0, Math.min(1, val / 20));
            else if (id === 'volume') norm = Math.max(0, Math.min(1, val));
            automationStore.recordPoint('sampler', id, { step, value: norm });
        }
    }, [activeSamplerBank, setSampler, currentStepRef]);

    const handleSamplerParamChange = useCallback((bankIdx: number, key: string, val: unknown) => {
        setSampler(prev => {
            const next = [...prev];
            const currentBank = next[bankIdx];
            if (currentBank) {
                const nextBank: SamplerBankParams = { ...currentBank };
                // `key` names one of many differently-typed SamplerBankParams fields;
                // the caller supplies a matching value at runtime for the given key.
                (nextBank as unknown as Record<string, unknown>)[key] = val;
                next[bankIdx] = nextBank;
            }
            samplerRef.current = next;
            return next;
        });
    }, [setSampler, samplerRef]);

    const onSynthAParamChange = useCallback((id: string, v: number) => handleSynthChange(true, id, v), [handleSynthChange]);
    const onSynthBParamChange = useCallback((id: string, v: number) => handleSynthChange(false, id, v), [handleSynthChange]);
    const onBass2ParamChange = useCallback((id: string, v: number) => handleBass2Change(id, v), [handleBass2Change]);

    return {
        handleSynthChange,
        handleBass2Change,
        handleKickChange,
        handleSnareChange,
        handleClosedHatChange,
        handleOpenHatChange,
        handleSamplerChange,
        handleSamplerParamChange,
        onSynthAParamChange,
        onSynthBParamChange,
        onBass2ParamChange,
    };
}

import { describe, expect, it, vi } from 'vitest';
