export interface EngineLifecycleUrls {
    sustainProcessorUrl: string;
    open303ProcessorUrl: string;
    prophecyProcessorUrl: string;
    drumkitProcessorUrl: string;
}

export interface EngineLifecycleResult {
    context: AudioContext;
    masterBusInput: WaveShaperNode;
}

export async function initializeAudioContextAndEngines(
    refs: EngineLifecycleRefs,
    urls: EngineLifecycleUrls,
    latencyHint: LatencyMode = getStoredLatencyMode(),
    /**
     * A context already built (and resumed) inside a user gesture — the HUD
     * "Apply" path. When omitted the context is constructed here, which is
     * only gesture-safe because nothing is awaited before `resume()` below.
     */
    precreated?: AudioContextCreation,
): Promise<EngineLifecycleResult> {
    const audioWindow = window as AudioWindow;
    loadingProgressStore.startStep('audioContext');
    const created = precreated ?? createAudioContext(latencyHint);
    const context = created.context;
    loadingProgressStore.completeStep('audioContext');
    audioWindow.audioContext = context;
    startGlitchMonitor(context, {
        latencyHint: created.latencyHint,
        requestedSampleRate: created.requestedSampleRate,
        sampleRateFallback: created.sampleRateFallback,
        renderSizeHintRequested: created.requestedRenderSizeHint,
        renderQuantumSize: created.renderQuantumSize,
        contextOptionFallback: created.optionFallback,
    });
    void applyAudioOutputSink(context).then((sink) => {
        if (sink) engineTelemetry.recordAudioOutputSink(sink);
    });

    // --- CRITICAL FIX: Ensure AudioContext is running ---
    if (context.state === 'suspended') {
        await context.resume();
        console.log("AudioContext resumed");
    }

    loadingProgressStore.startStep('masterChain');
    // The master true-peak limiter / loudness meter is an AudioWorklet, so its
    // module has to be registered before the graph is compiled. If it fails to
    // load the graph is compiled without it and playback continues unmetered.
    const loudnessStage = await createMasterLoudnessStage(context);
    setMasterLoudnessStage(loudnessStage);
    // The patch bay edits this controller's config; the engine compiles it.
    // Until a song load supplies a saved patch, it holds the stock preset.
    // A song loaded before the engine started may already have published a
    // controller holding its saved patch; otherwise start from the preset.
    const patchController =
        getActivePatchController() ?? new PatchController(buildPreset(undefined));
    setActivePatchController(patchController);

    const { masterBusInput, graph } = buildClassicElectribeGraph(context, refs, {
        masterLimiterNode: loudnessStage?.node ?? null,
        patchController,
    });
    const wamHost = new WamHost(context);
    wamHost.attachCompiledGraph(graph);
    setWamHost(wamHost);
    wamHost.publishTelemetry();
    loadingProgressStore.completeStep('masterChain');

    // Initialize oscillator backends through the shared registry. Every engine
    // is wrapped in an OscillatorBackend adapter so readiness is typed and the
    // fallback chain (WebGPU → WASM OSC → Pyodide → WAV PCM → JS) lives in one
    // place — including for the realtime note path (#1294).
    //
    // There is exactly one WASM wavetable engine: the AssemblyScript kernel
    // behind `WamWasmBackend`. The Rust `generate()` + looped-buffer duplicate
    // was removed; `rust-audio/` remains a bench crate.
    const registry = new BackendRegistry();
    const webGpuBackend = new WebGpuBackend(new WebGpuOscillator());
    const wamBackend = new WamWasmBackend(new WasmOscillator());
    const pyodideBackend = new PyodideBackend();
    const wavBackend = new WavPcmBackend();
    registry.register(webGpuBackend);
    registry.register(wamBackend);
    registry.register(pyodideBackend);
    registry.register(wavBackend);
    registry.register(new JsOscillatorBackend());
    setOscillatorRegistry(registry);

    // The WAV backend only becomes supported once its tables are decoded, and
    // Pyodide attaches later still (see `attachPyodideOscillator`); the
    // GPU/WASM backends init here.
    loadingProgressStore.startStep('webGpuEngine');
    await webGpuBackend.init(context);
    loadingProgressStore.completeStep('webGpuEngine');

    loadingProgressStore.startStep('wasmEngine');
    await wamBackend.init(context);
    loadingProgressStore.completeStep('wasmEngine');

    // Fails until a runtime attaches — the point of the call is to hand the
    // backend the AudioContext it will allocate tables in.
    await pyodideBackend.init(context);

    refs.gpuEngineRef.current = webGpuBackend.raw;
    refs.wasmEngineRef.current = wamBackend.raw;

    // Initialize Open303 Manager
    loadingProgressStore.startStep('open303Engine');
    const open303Manager = new Open303Manager();
    let open303Ready = false;

    try {
        // No config: the hyphon_native build is picked from the environment
        // (pthread when crossOriginIsolated, single-threaded on WebKit / without
        // COOP+COEP). Prophecy below joins whichever build this binds.
        open303Ready = await open303Manager.init(context, urls.open303ProcessorUrl);

        if (open303Ready) {
            open303Manager.connect(masterBusInput);
            refs.open303ManagerRef.current = open303Manager;
            console.log('[useAudioEngine] Open303Manager Ready');
            try { engineTelemetry.registerResolution('jc303','open303','ready'); } catch (e) { /* noop */ }
        } else {
            console.warn('[useAudioEngine] Open303Manager failed to initialize');
            try { engineTelemetry.registerResolution('jc303','fallback','notReady'); } catch (e) { /* noop */ }
        }
    } catch (e) {
        console.error('[useAudioEngine] Open303Manager crashed during init:', e);
        open303Ready = false;
    }

    if (!open303Ready) {
        console.log('[useAudioEngine] Open303 bypassed - using fallback bass synthesis');
        loadingProgressStore.failStep('open303Engine', new Error('Open303 not ready'), true);
    } else {
        loadingProgressStore.completeStep('open303Engine');
    }

    // Initialize Prophecy formant engine (SYNTH A / SYNTH B prophecy-* waveforms)
    loadingProgressStore.startStep('prophecyEngine');
    const prophecyManager = new ProphecyManager();
    try {
        const prophecyReady = await prophecyManager.init(context, urls.prophecyProcessorUrl);
        if (prophecyReady) {
            const partADest = refs.synthABusRef.current ?? refs.masterSaturationRef.current!;
            const partBDest = refs.synthBBusRef.current ?? refs.masterSaturationRef.current!;
            prophecyManager.connectBuses(partADest, partBDest);
            refs.prophecyManagerRef.current = prophecyManager;
            console.log('[useAudioEngine] ProphecyManager Ready');
            try { engineTelemetry.registerResolution('prophecy', 'wasm-worklet', 'ready'); } catch (e) { /* noop */ }
        } else {
            console.warn('[useAudioEngine] ProphecyManager failed to initialize');
            try { engineTelemetry.registerResolution('prophecy', 'fallback', 'notReady'); } catch (e) { /* noop */ }
        }
    } catch (e) {
        console.error('[useAudioEngine] ProphecyManager crashed during init:', e);
        loadingProgressStore.failStep(
            'prophecyEngine',
            e instanceof Error ? e : new Error(String(e)),
            true,
        );
        try { engineTelemetry.registerResolution('prophecy', 'fallback', String(e)); } catch (err) { /* noop */ }
    }
    if (refs.prophecyManagerRef.current) {
        loadingProgressStore.completeStep('prophecyEngine');
    } else if (loadingProgressStore.getState().steps.prophecyEngine.status === 'active') {
        loadingProgressStore.failStep('prophecyEngine', new Error('Prophecy not ready'), true);
    }

    loadingProgressStore.startStep('wavFiles');
    const [sawBuf, sqrBuf] = await Promise.all([
        loadWavBuffer(context, './assets/saw.wav'),
        loadWavBuffer(context, './assets/square.wav')
    ]);
    refs.wavSawBufferRef.current = sawBuf;
    refs.wavSqrBufferRef.current = sqrBuf;
    loadingProgressStore.completeStep('wavFiles');

    // Resolve the active oscillator backend from the ordered chain. The result
    // is published to telemetry + the degradation store, so any fallback is
    // logged and shows up in EngineHUD rather than degrading silently.
    wavBackend.setBuffers({ saw: sawBuf, sqr: sqrBuf });
    await wavBackend.init(context);
    registry.resolveAndPublish();

    // Initialize Voice Managers (routed through per-track monitor buses for expression LEDs)
    const synthADest = refs.synthABusRef.current ?? refs.masterSaturationRef.current!;
    const synthBDest = refs.synthBBusRef.current ?? refs.masterSaturationRef.current!;
    // Voices take no engine handles: they ask `BackendRegistry` for the family
    // they were given and it decides which backend renders it.
    refs.voiceManagerARef.current = new VoiceManager(context, synthADest, 8, false, refs.delayNodeRef.current || undefined);
    refs.voiceManagerBRef.current = new VoiceManager(context, synthBDest, 1, true, refs.delayNodeRef.current || undefined);

    if (isAppleWebKit()) {
        logEngineFallback('sustain', 'wasm-worklet', 'AudioWorklet addModule skipped on WebKit');
    } else {
        await initializeSustainProcessor(context, urls.sustainProcessorUrl, refs.sustainNodeRef, refs.masterGainRef);
    }

    // --- Singing Voice Manager Init ---
    loadingProgressStore.startStep('singingVoice');
    try {
        if (isAppleWebKit()) {
            logEngineFallback(
                'singingVoice',
                'wasm',
                'rubberband AudioWorklet aborts Playwright WebKit / Safari',
            );
            throw new Error('singing voice skipped on WebKit');
        }

        let wasmBinary: ArrayBuffer | undefined = undefined;
        try {
            const response = await fetch(import.meta.env.BASE_URL + 'rubberband.wasm');
            if (response.ok) wasmBinary = await response.arrayBuffer();
        } catch (e) {
            console.warn('Failed to pre-fetch rubberband.wasm', e);
        }

        const manager = new SingingVoiceManager(context, 12, {
            useHighQuality: false,
            preserveFormants: true,
            channels: 1,
            bufferSize: 16384,
            enablePhonemeStretching: true,
            enableFormantShifting: true,
            enableCtcAlignment: true,
        });

        await manager.init(wasmBinary);
        refs.singingVoiceManagerRef.current = manager;
        try { engineTelemetry.registerResolution('singingVoice','wasm','loaded'); } catch (e) { /* noop */ }

        const samplerDest = refs.samplerBusRef.current ?? refs.masterSaturationRef.current!;
        const voices = manager.getAllVoices();
        // ⚡ Bolt Optimization: Replacing forEach with for loop to prevent closure allocations on hot path
        for (let i = 0; i < voices.length; i++) {
            voices[i].connectOutput(samplerDest);
        }

        // Initialise the phoneme buffer pool and wire it to every voice
        const pool = new PhonemeBufferPool();
        pool.init(context);
        refs.phonemeBufferPoolRef.current = pool;
        // ⚡ Bolt Optimization: Replacing forEach with for loop to prevent closure allocations on hot path
        for (let i = 0; i < voices.length; i++) {
            voices[i].setPool(pool);
        }

        if (refs.pyodideRef.current) {
            // Pre-cache logic
        }
        loadingProgressStore.completeStep('singingVoice');
    } catch (e) {
        try { engineTelemetry.registerResolution('singingVoice','js','failed to init: ' + String(e)); } catch (err) { /* noop */ }
        console.warn('SingingVoiceManager failed to init:', e);
        loadingProgressStore.failStep(
            'singingVoice',
            e instanceof Error ? e : new Error(String(e)),
            true,
        );
    }

    initializeHarmonizer(refs.harmonizerRef);
    refs.noiseBufferRef.current = createNoiseBuffer(context);
    refs.multisampleGeneratorRef.current = new MultisampleGenerator(context);
    refs.drumKitEngineRef.current = new DrumKitEngine(DEFAULT_DRUM_KIT);
    const drumDest = refs.masterGainRef.current;
    if (drumDest && urls.drumkitProcessorUrl) {
        const drumReady = await refs.drumKitEngineRef.current.init(
            context,
            urls.drumkitProcessorUrl,
            drumDest,
        );
        if (drumReady) {
            try { engineTelemetry.registerResolution('drumkit', 'wasm-worklet', 'ready'); } catch { /* noop */ }
        } else {
            try { engineTelemetry.registerResolution('drumkit', 'webaudio', refs.drumKitEngineRef.current.fallbackReason ?? 'notReady'); } catch { /* noop */ }
        }
    }

    return { context, masterBusInput };
}

/**
 * Tear the running engine down so `initializeAudioContextAndEngines` can build
 * a fresh one (HUD "Apply" for sample rate / latency / render size / sink).
 *
 * Worklet nodes are disconnected and their ports closed before the context is
 * closed: closing the context is what actually releases the AudioWorklet
 * global scope, and with it the one hyphon_native heap the voice processors
 * share (#1229) — the next context instantiates a fresh one.
 */
export async function teardownAudioEngine(
    refs: EngineLifecycleRefs,
    context: AudioContext | null,
): Promise<void> {
    const safely = (label: string, fn: () => void): void => {
        try {
            fn();
        } catch (e) {
            console.warn(`[engineLifecycle] teardown ${label} failed:`, e);
        }
    };

    safely('open303', () => refs.open303ManagerRef.current?.cleanup());
    safely('prophecy', () => refs.prophecyManagerRef.current?.cleanup());
    safely('drumkit', () => refs.drumKitEngineRef.current?.dispose());
    safely('sustain', () => {
        const node = refs.sustainNodeRef.current;
        if (node) {
            node.disconnect();
            node.port.close();
        }
    });
    safely('loudness', () => {
        getMasterLoudnessStage()?.dispose();
        setMasterLoudnessStage(null);
    });
    safely('wam', () => setWamHost(null));
    stopGlitchMonitor();

    refs.open303ManagerRef.current = null;
    refs.prophecyManagerRef.current = null;
    refs.drumKitEngineRef.current = null;
    refs.sustainNodeRef.current = null;
    refs.singingVoiceManagerRef.current = null;
    refs.phonemeBufferPoolRef.current = null;
    refs.voiceManagerARef.current = null;
    refs.voiceManagerBRef.current = null;
    refs.multisampleGeneratorRef.current = null;

    const audioWindow = window as AudioWindow;
    if (context && audioWindow.audioContext === context) {
        audioWindow.audioContext = undefined;
    }
    if (context && context.state !== 'closed') {
        try {
            await context.close();
        } catch (e) {
            console.warn('[engineLifecycle] AudioContext.close() failed:', e);
        }
    }
}

import type { MutableRefObject } from 'react';
import { ensureBufferMatchesContext } from '../../utils/resampleAudioBuffer';
import type { AlignmentResult } from '../../engines/rubberband/PhonemeAligner';
import { MultisampleGenerator } from '../../engines/MultisampleGenerator';
import { SingingVoiceManager } from '../../engines/SingingVoiceManager';
import type { MultisampleBank, SamplerBankParams } from '../../types';

interface SampleManagementRefs {
    audioContextRef: MutableRefObject<AudioContext | null>;
    loadedSampleBuffersRef: MutableRefObject<Map<string, AudioBuffer>>;
    multisampleBanksRef: MutableRefObject<Map<string, MultisampleBank>>;
    multisampleGeneratorRef: MutableRefObject<MultisampleGenerator | null>;
    vocalAlignmentsRef: MutableRefObject<Map<string, AlignmentResult>>;
    singingVoiceManagerRef: MutableRefObject<SingingVoiceManager | null>;
}

export function createSampleLibraryControls(refs: SampleManagementRefs) {
    const loadSampleToEngine = async (
        name: string,
        buffer: AudioBuffer,
        onProgress?: (progress: number) => void,
    ): Promise<void> => {
        const context = refs.audioContextRef.current;
        const matched = context ? await ensureBufferMatchesContext(buffer, context) : buffer;
        const sampleBank: MultisampleBank = {
            baseBuffer: matched,
            pitchBank: new Map([[60, matched]]),
            isProcessing: true,
            processingProgress: 0,
            rootNote: 60,
        };

        refs.loadedSampleBuffersRef.current.set(name, matched);
        refs.multisampleBanksRef.current.set(name, sampleBank);

        if (refs.multisampleGeneratorRef.current && onProgress) {
            onProgress(0.05);

            try {
                const pitchBank = await refs.multisampleGeneratorRef.current.generateMultisamples(
                    matched,
                    {
                        rootNote: 60,
                        range: [-12, 12],
                        preserveFormants: true,
                        quality: 'Standard',
                    },
                    (progress) => {
                        sampleBank.processingProgress = progress;
                        onProgress(0.05 + progress * 0.95);
                    },
                );

                sampleBank.pitchBank = pitchBank;
                sampleBank.isProcessing = false;
                sampleBank.processingProgress = 1.0;

                onProgress(1.0);
                console.log(`Multisample generation complete for ${name}: ${pitchBank.size} pitches`);
            } catch (error) {
                console.error('Multisample generation failed:', error);
                sampleBank.isProcessing = false;
                sampleBank.error = error instanceof Error ? error.message : 'Unknown error';
                onProgress(-1); // Preserve existing UI convention: -1 marks sample-generation failure.
            }
        } else if (onProgress) {
            onProgress(1.0);
        }
    };

    const getMultisampleBank = (bankIndex: number): MultisampleBank | null => {
        const bankName = `bank_${bankIndex}`;
        return refs.multisampleBanksRef.current.get(bankName) || null;
    };

    const isMultisampleReady = (bankIndex: number): boolean => {
        const bank = getMultisampleBank(bankIndex);
        return bank ? !bank.isProcessing : false;
    };

    const prepareVocal = async (bankIndex: number, text: string, durationPriors?: number[]) => {
        if (!refs.singingVoiceManagerRef.current) {
            return;
        }

        const bankName = `bank_${bankIndex}`;
        const buffer = refs.loadedSampleBuffersRef.current.get(bankName);
        if (!buffer) {
            return;
        }

        const alignmentVoice = refs.singingVoiceManagerRef.current.getVoice(0);
        if (!alignmentVoice) {
            return;
        }

        const audio = buffer.getChannelData(0);
        try {
            const alignment = await alignmentVoice.alignPhonemes(
                audio,
                text,
                durationPriors ? { durationPriors } : undefined,
            );
            if (alignment) {
                refs.vocalAlignmentsRef.current.set(bankName, alignment);
                console.log(`Aligned phonemes for ${bankName}: ${alignment.phonemes.length}`);
            }
        } catch (error) {
            console.warn('Phoneme alignment failed:', error);
        }
    };

    const getAlignment = (bankIndex: number) => {
        const bankName = `bank_${bankIndex}`;
        return refs.vocalAlignmentsRef.current.get(bankName) || null;
    };

    const setAlignment = (bankIndex: number, alignment: AlignmentResult | null) => {
        const bankName = `bank_${bankIndex}`;
        if (alignment) {
            refs.vocalAlignmentsRef.current.set(bankName, alignment);
        } else {
            refs.vocalAlignmentsRef.current.delete(bankName);
        }
    };

    return {
        loadSampleToEngine,
        getMultisampleBank,
        isMultisampleReady,
        prepareVocal,
        getAlignment,
        setAlignment,
    };
}

interface VoiceParamUpdateOptions {
    manager: SingingVoiceManager | null;
    choirLeftGain: GainNode | null;
    choirRightGain: GainNode | null;
    currentTime: number;
    key: keyof SamplerBankParams;
    value: number;
    rampTime?: number;
}

export function applyVoiceParamUpdate({
    manager,
    choirLeftGain,
    choirRightGain,
    currentTime,
    key,
    value,
    rampTime
}: VoiceParamUpdateOptions): void {
    if (manager) {
        const voices = manager.getAllVoices();
        // ⚡ Bolt Optimization: Replacing forEach with for loop to prevent closure allocations on hot path
        for (let i = 0; i < voices.length; i++) {
            const voice = voices[i];
            switch (key) {
                case 'timeRatio':
                    voice.setTimeRatio(value);
                    break;
                case 'pitchScale':
                    voice.setPitch(value);
                    break;
                case 'formantShift':
                    voice.setFormantShift(value, undefined, rampTime);
                    break;
                case 'vibratoDepth':
                    voice.setVibratoDepth(value);
                    break;
                case 'breathIntensity':
                    voice.setBreathIntensity(value);
                    break;
                case 'freeze':
                    voice.setFreeze(value);
                    break;
                case 'freezeLfoRate':
                    voice.setFreezeLfoRate(value);
                    break;
                case 'freezeLfoDepth':
                    voice.setFreezeLfoDepth(value);
                    break;
                case 'attack':
                    voice.setAttack(value);
                    break;
                case 'release':
                    voice.setRelease(value);
                    break;
            }
        }
    }

    if (key === 'choir') {
        const gain = value * 0.7;
        choirLeftGain?.gain.setTargetAtTime(gain, currentTime, 0.05);
        choirRightGain?.gain.setTargetAtTime(gain, currentTime, 0.05);
    }
}

interface SamplerVoiceParamUpdateOptions {
    manager: SingingVoiceManager | null;
    currentTime: number;
    param: string;
    value: number | string | boolean;
}

const _lastStretchProfiles = new Map<AudioWorkletNode, string>();

export function applySamplerVoiceParamUpdate({
    manager,
    currentTime,
    param,
    value,
}: SamplerVoiceParamUpdateOptions): void {
    if (!manager) {
        return;
    }

    const voices = manager.getAllVoices();
    // ⚡ Bolt Optimization: Replacing forEach with for loop to prevent closure allocations on hot path
    for (let i = 0; i < voices.length; i++) {
        const voice = voices[i];
        switch (param) {
            case 'vibratoRate':
                voice.setVibratoRate(value as number);
                break;
            case 'rootNote':
                voice.setRootNote(value as number);
                break;
            case 'coarseTune':
                voice.setCoarseTune(value as number);
                break;
            case 'fineTune':
                voice.setFineTune(value as number);
                break;
            case 'formantShift':
                voice.setFormantShift(value as number, currentTime);
                break;
            case 'stretchProfile': {
                const node = voice.getSourceNode();
                if (node && 'port' in node) {
                    const profile = String(value);
                    const workletNode = node as AudioWorkletNode;
                    if (_lastStretchProfiles.get(workletNode) === profile) {
                        break;
                    }
                    _lastStretchProfiles.set(workletNode, profile);
                    workletNode.port.postMessage({
                        type: 'setStretchProfile',
                        data: { profile }
                    });
                }
                break;
            }

            case 'pitchAttack':
                voice.setPitchAttack(value as number);
                break;
            case 'pitchDecay':
                voice.setPitchDecay(value as number);
                break;
            case 'vibratoDepth':
                voice.setVibratoDepth(value as number);
                break;
            case 'tremoloDepth':
                voice.setTremoloDepth(value as number);
                break;
            case 'breathAmount':
                voice.setBreathIntensity(value as number);
                break;
            case 'characterMorph':
                voice.setCharacterMorph(value as number, 'female', 0.05);
                break;
        }
    }
}

import type { SingingVoice } from "../../../engines/SingingVoice";
import { noteToMidi } from "../../../utils/musicTheory";
import { getSyncedSeconds, getSyncedLfoHz } from "../syncUtils";
import { tunedNoteToFrequency } from "../../../utils/musicTheory";
import { makeDistortionCurve } from "../distortion";
import { resolveExpressiveness } from "./expressiveness";
import { releaseStretchFxRouting, wireStretchFxRouting } from "./samplerStretchFx";
import { performanceBudget } from "../../../utils/performanceBudget";
import type { PlaySamplerVoiceFn, SamplerPlaybackRefs } from "./types";

export function createPlaySamplerVoice(
  context: AudioContext,
  tempo: number,
  refs: SamplerPlaybackRefs,
): PlaySamplerVoiceFn {
  return (
    params,
    note,
    time,
    durationSteps = 1,
    stepTime = 0.2,
    noteParams,
    pitchOffsetSemitones = 0,
    tuning,
  ) => {
    const multisampleBank = refs.multisampleBanksRef.current.get(params.sampleName);
    const legacyBuffer = refs.loadedSampleBuffersRef.current.get(params.sampleName);
    const buffer = multisampleBank?.baseBuffer || legacyBuffer;

    if (!buffer || !refs.masterSaturationRef.current) return;

    // Apply Microtiming
    const actualTime = time + (noteParams?.microtiming ? noteParams.microtiming * stepTime : 0);

    // Retrigger Logic
    const retrigger = Math.max(1, Math.floor(noteParams?.retrigger || 1));
    const subDurationSteps = durationSteps / retrigger;

    // --- GLITCH LOGIC START ---
    const shouldGlitch = retrigger === 1 && (params.glitchChance || 0) > 0 && Math.random() < (params.glitchChance || 0);
    // --- GLITCH LOGIC END ---

    // Handle Polyphony (Chords)
    const notes = Array.isArray(note) ? note : [note];

    // Performance: Hoist expressive config resolution to avoid recalculating per note/retrigger.
    const expressiveConfig = resolveExpressiveness(params);

    // --- HOISTED PARAMETERS START ---
    // Vocoder Mix
    const vocoderMix = noteParams?.vocoderMix ?? params.vocoderMix ?? 0;
    const pVocoderFormantShift = noteParams?.vocoderFormantShift ?? params.formantShift ?? 0;
    const pVocoderPreservation = noteParams?.vocoderPreservation ?? 1.0;
    const pVocoderAttack = noteParams?.vocoderAttack ?? 0.01;
    const pVocoderRelease = noteParams?.vocoderRelease ?? 0.05;
    const pGrainPanSpreadOuter = noteParams?.spectralPanDepth !== undefined ? noteParams.spectralPanDepth : params.spectralPanDepth;

    // Spectral Panning
    const spectralPanRate = noteParams?.spectralPanRate !== undefined ? noteParams.spectralPanRate : params.spectralPanRate;
    const spectralPanDepth = noteParams?.spectralPanDepth !== undefined ? noteParams.spectralPanDepth : params.spectralPanDepth;
    const spectralPanLfoRate = (spectralPanRate || 1) * (tempo / 60);

    // Reverb
    const reverbSendAmount = noteParams?.reverbSend !== undefined ? noteParams.reverbSend : 0;
    const currentReverbType = noteParams?.reverbType || refs.reverbTypeRef.current;
    const targetReverbNode = refs.reverbNodesRef.current[currentReverbType] || refs.reverbNodesRef.current['plate'];

    const baseShift = params.formantShift || 0;
    const currentShift = noteParams?.formantShift !== undefined ? (baseShift + noteParams.formantShift) : baseShift;
    const characterMorph = noteParams?.characterMorph !== undefined ? noteParams.characterMorph : (params.characterMorph ?? 0);
    const morphTarget = params.morphTarget || 'female';

    const normalizedShift = Math.max(-12, Math.min(12, currentShift)) / 12;
    let reverbEqCutoff = 6000 - (normalizedShift * 4000);
    reverbEqCutoff -= (characterMorph * 1000);
    reverbEqCutoff = Math.max(1000, Math.min(12000, reverbEqCutoff));

    const revLfoRate = noteParams?.reverbLfoRate !== undefined ? noteParams.reverbLfoRate : (params.reverbLfoRate || 0.1);
    const revLfoDepth = noteParams?.reverbLfoDepth !== undefined ? noteParams.reverbLfoDepth : (params.reverbLfoDepth || 0);

    // Delay
    const delaySendAmount = noteParams?.delaySend !== undefined ? noteParams.delaySend : (params.delaySend || 0);

    // Timbre Modulation
    let targetFormantShift = baseShift;
    if (noteParams?.formantShift !== undefined) {
      targetFormantShift = baseShift + noteParams.formantShift;
    } else if (noteParams?.timbre !== undefined) {
      targetFormantShift = baseShift + (noteParams.timbre * 12) - 6;
    }
    const startFormantShift = noteParams?.slideFromFormant !== undefined ? (baseShift + noteParams.slideFromFormant) : undefined;

    // General Params
    const pVibratoDepth = noteParams?.vibratoDepth;
    const pTremoloDepth = noteParams?.tremoloDepth !== undefined ? noteParams.tremoloDepth : params.tremoloDepth;
    const pTremoloRate = noteParams?.tremoloRate !== undefined ? noteParams.tremoloRate : params.tremoloRate;
    const pGateDepth = noteParams?.gateDepth !== undefined ? noteParams.gateDepth : params.gateDepth;
    const pGateRateHz = noteParams?.gateRate !== undefined
      ? (tempo / 60) * (noteParams.gateRate / 4)
      : (params.gateRate !== undefined ? (tempo / 60) * (params.gateRate / 4) : undefined);
    const pAttack = params.attack;
    const pDecay = params.decay;
    const pSustain = params.sustain;
    const pRelease = params.release;

    // Freeze
    const pFreeze = noteParams?.freeze !== undefined ? noteParams.freeze : params.freeze;
    const freezeRateSync = noteParams?.freezeLfoSync !== undefined ? noteParams.freezeLfoSync : params.freezeLfoSync;
    let pFreezeLfoRate: number | undefined;
    if (noteParams?.freezeLfoRate !== undefined) {
      pFreezeLfoRate = freezeRateSync ? getSyncedLfoHz(noteParams.freezeLfoRate, tempo) : noteParams.freezeLfoRate;
    } else if (params.freezeLfoRate !== undefined) {
      pFreezeLfoRate = freezeRateSync ? getSyncedLfoHz(params.freezeLfoRate, tempo) : params.freezeLfoRate;
    }
    const pFreezeLfoDepth = noteParams?.freezeLfoDepth !== undefined ? noteParams.freezeLfoDepth : params.freezeLfoDepth;
    const pGrainLfoRate = noteParams?.grainLfoRate !== undefined ? noteParams.grainLfoRate : params.grainLfoRate;
    const pGrainLfoDepth = noteParams?.grainLfoDepth !== undefined ? noteParams.grainLfoDepth : params.grainLfoDepth;
    const pGrainPosLfoDepth = noteParams?.grainPosLfoDepth !== undefined ? noteParams.grainPosLfoDepth : params.grainPosLfoDepth;

    // Envelopes
    const pFreezeEnvDepth = noteParams?.freezeEnvDepth !== undefined ? noteParams.freezeEnvDepth : params.freezeEnvDepth;
    const pTimeStretchEnvDepth = noteParams?.timeStretchEnvDepth !== undefined ? noteParams.timeStretchEnvDepth : params.timeStretchEnvDepth;
    const pGrainEnvDepth = noteParams?.grainEnvDepth !== undefined ? noteParams.grainEnvDepth : params.grainEnvDepth;
    const pGrainPitchEnvDepth = noteParams?.grainPitchEnvDepth !== undefined ? noteParams.grainPitchEnvDepth : params.grainPitchEnvDepth;
    const pGrainJitter = noteParams?.grainJitter !== undefined ? noteParams.grainJitter : params.grainJitter;
    const pGrainPitchQuantize = noteParams?.grainPitchQuantize !== undefined ? noteParams.grainPitchQuantize : params.grainPitchQuantize;

    // Effects
    const pGranularPitchShift = noteParams?.granularPitchShift !== undefined ? noteParams.granularPitchShift : params.granularPitchShift;
    const pBitcrush = noteParams?.bitcrush !== undefined ? noteParams.bitcrush : params.bitcrush;
    const pSpectralComp = noteParams?.spectralComp !== undefined ? noteParams.spectralComp : params.spectralComp;
    const pDownsample = noteParams?.downsample !== undefined ? noteParams.downsample : params.downsample;
    const pSpectralCompression = noteParams?.spectralCompression !== undefined ? noteParams.spectralCompression : params.spectralCompression;
    const pSubHarmonics = noteParams?.subHarmonics !== undefined ? noteParams.subHarmonics : params.subHarmonics;
    const pVocalChorus = noteParams?.vocalChorus !== undefined ? noteParams.vocalChorus : params.vocalChorus;
    const pTransientExtraction = noteParams?.transientExtraction !== undefined ? noteParams.transientExtraction : params.transientExtraction;
    const pAutoTune = noteParams?.autoTune !== undefined ? noteParams.autoTune : params.autoTune;
    const pDrumDuckDepth = noteParams?.drumDuckDepth !== undefined ? noteParams.drumDuckDepth : params.drumDuckDepth;
    const pPhonemeFilterMod = noteParams?.phonemeFilterMod !== undefined ? noteParams.phonemeFilterMod : params.phonemeFilterMod;
    const pTranceGate = noteParams?.tranceGate;
    const pVolumeFilterMod = noteParams?.volumeFilterMod !== undefined ? noteParams.volumeFilterMod : params.volumeFilterMod;

    // Formant LFO
    const useFmtLfoSync = noteParams?.formantLfoSync ?? params.formantLfoSync ?? false;
    const rawFmtLfoRate = noteParams?.formantLfoRate !== undefined ? noteParams.formantLfoRate : params.formantLfoRate;
    const pFormantLfoRateHz = rawFmtLfoRate !== undefined ? (useFmtLfoSync ? ((tempo / 60) / (rawFmtLfoRate * 4)) : rawFmtLfoRate) : undefined;
    const pFormantLfoDepth = noteParams?.formantLfoDepth !== undefined ? noteParams.formantLfoDepth : params.formantLfoDepth;
    let pFormantLfoShape = noteParams?.customLfoShape !== undefined ? noteParams.customLfoShape : params.customLfoShape;
    if (pFormantLfoShape === undefined) {
      pFormantLfoShape = noteParams?.customLfoShape !== undefined ? noteParams.customLfoShape : params.customLfoShape;
    }
    const pCustomWindowShape = noteParams?.customWindowShape !== undefined ? noteParams.customWindowShape : params.customWindowShape;

    // Formant Envelope
    const envSync = noteParams?.formantEnvSync ?? params.formantEnvSync ?? false;
    let pEnvAttack = noteParams?.formantEnvAttack ?? params.formantEnvAttack ?? 0;
    let pEnvDecay = noteParams?.formantEnvDecay ?? params.formantEnvDecay ?? 0;
    const pEnvAmount = noteParams?.formantEnvAmount ?? params.formantEnvAmount ?? 0;
    const pFormantEnvFollower = noteParams?.formantEnvFollower ?? params.formantEnvFollower ?? 0;
    if (envSync) {
      pEnvAttack = getSyncedSeconds(pEnvAttack as number, tempo);
      pEnvDecay = getSyncedSeconds(pEnvDecay as number, tempo);
    }

    const pPitchAttack = noteParams?.pitchAttack ?? params.pitchAttack ?? 0;
    const pPitchDecay = noteParams?.pitchDecay ?? params.pitchDecay ?? 0;
    const pPitchAmount = noteParams?.pitchAmount ?? params.pitchAmount ?? 0;

    const pFilterCutoff = noteParams?.filterCutoff !== undefined
      ? Math.max(20, noteParams.filterCutoff * 20000)
      : params.filterCutoff;
    const pFilterResonance = noteParams?.filterResonance !== undefined
      ? noteParams.filterResonance * 20
      : params.filterResonance;
    const pDriveAmount = noteParams?.drive !== undefined
      ? noteParams.drive
      : params.drive;
    // --- HOISTED PARAMETERS END ---


    // If Singing/Stretch Mode
    if (params.mode === 'stretch' && refs.singingVoiceManagerRef.current) {
      const manager = refs.singingVoiceManagerRef.current;
      const alignment = refs.vocalAlignmentsRef.current.get(params.sampleName);

      const triggerVoice = (noteStr: string, voice: SingingVoice, pitchOffset: number, overrideTime?: number, overrideDuration?: number, destination?: AudioNode, isNewBank: boolean = true) => {
        const targetDuration = overrideDuration !== undefined ? overrideDuration : (durationSteps * stepTime);
        const originalDuration = buffer.duration;
        const triggerTime = overrideTime !== undefined ? overrideTime : actualTime;

        // Ensure voice connected to correct output (reuse FX strip — no per-trigger node leak)
        voice.disconnectOutput();
        releaseStretchFxRouting(voice);

        const mainDest = destination || refs.masterSaturationRef.current!;
        const driveAmount = noteParams?.drive !== undefined ? noteParams.drive : params.drive ?? 0;
        const stretchReverbNode =
          reverbSendAmount > 0 && targetReverbNode ? targetReverbNode : null;
        const stretchDelayNode =
          delaySendAmount > 0 && refs.delayNodeRef.current ? refs.delayNodeRef.current : null;

        const { strip, voiceEntry } = wireStretchFxRouting(
          voice,
          context,
          mainDest,
          stretchReverbNode,
          stretchDelayNode,
          driveAmount,
          makeDistortionCurve,
        );

        const filterCutoff =
          noteParams?.filterCutoff !== undefined
            ? Math.max(20, noteParams.filterCutoff * 20000)
            : (params.filterCutoff !== undefined ? Math.max(20, params.filterCutoff * 20000) : 20000);
        const filterResonance =
          noteParams?.filterResonance !== undefined
            ? noteParams.filterResonance * 20
            : (params.filterResonance ?? 0);
        strip.updateFilter(filterCutoff, filterResonance, triggerTime);

        const rawSpectralDepth =
          noteParams?.spectralPanDepth !== undefined ? noteParams.spectralPanDepth : spectralPanDepth;
        const spectralDepth =
          rawSpectralDepth !== undefined && rawSpectralDepth > 0
            ? rawSpectralDepth * performanceBudget.getSpectralPanMultiplier()
            : 0;
        // Disable VoiceFXStrip LFO pan if the worklet is handling grain-locked spectral panning
        const workletSpectralPan = pGrainPanSpreadOuter !== undefined && pGrainPanSpreadOuter > 0;
        if (!workletSpectralPan) {
          strip.updateSpectralPanning(spectralDepth, spectralPanLfoRate, triggerTime);
        } else {
          strip.updateSpectralPanning(0, 0, triggerTime); // Turn off strip LFO panning
        }

        strip.updateReverbSend(
          reverbSendAmount,
          revLfoRate,
          revLfoDepth,
          reverbEqCutoff,
          triggerTime,
        );
        strip.updateDelaySend(delaySendAmount, triggerTime);

        voice.connectOutput(voiceEntry);

        // Apply Timbre Modulation (Formant Shift)
        const baseShift = params.formantShift || 0;
        if (noteParams?.formantShift !== undefined) {
          voice.setFormantShift(baseShift + noteParams.formantShift, triggerTime);
        } else if (noteParams?.timbre !== undefined) {
          const mod = (noteParams.timbre * 12) - 6; // +/- 6 semitones
          voice.setFormantShift(baseShift + mod, triggerTime);
        } else if (params.formantShift !== undefined) {
          voice.setFormantShift(params.formantShift, triggerTime);
        }

        // Apply Character Morphing
        const morphAmount = noteParams?.characterMorph !== undefined ? noteParams.characterMorph : (params.characterMorph ?? 0);
        const morphTarget = params.morphTarget || 'female';
        voice.setCharacterMorph(morphAmount, morphTarget, 0.05); // Use short ramp time

        // Sync other params
        if (noteParams?.vibratoDepth !== undefined) {
          voice.setVibratoDepth(noteParams.vibratoDepth, triggerTime);
        } else if (params.vibratoDepth !== undefined) {
          voice.setVibratoDepth(params.vibratoDepth, triggerTime);
        }

        if (noteParams?.gateDepth !== undefined) {
          voice.setGateDepth(noteParams.gateDepth, triggerTime);
        } else if (params.gateDepth !== undefined) {
          voice.setGateDepth(params.gateDepth, triggerTime);
        }

        if (noteParams?.gateRate !== undefined) {
          const rateHz = (tempo / 60) * (noteParams.gateRate / 4);
          voice.setGateRate(rateHz, triggerTime);
        } else if (params.gateRate !== undefined) {
          const rateHz = (tempo / 60) * (params.gateRate / 4);
          voice.setGateRate(rateHz, triggerTime);
        }
        if (params.tremoloDepth !== undefined) voice.setTremoloDepth(params.tremoloDepth, triggerTime);
        if (params.tremoloRate !== undefined) voice.setTremoloRate(params.tremoloRate, triggerTime);

        if (noteParams?.gateDepth !== undefined) {
          voice.setGateDepth(noteParams.gateDepth, triggerTime);
        } else if (params.gateDepth !== undefined) {
          voice.setGateDepth(params.gateDepth, triggerTime);
        }

        if (noteParams?.gateRate !== undefined) {
          voice.setGateRate(noteParams.gateRate, triggerTime);
        } else if (params.gateRate !== undefined) {
          voice.setGateRate(params.gateRate, triggerTime);
        }

        if (noteParams?.breathIntensity !== undefined) {
          voice.setBreathIntensity(noteParams.breathIntensity, triggerTime);
        } else if (params.breathIntensity !== undefined) {
          voice.setBreathIntensity(params.breathIntensity, triggerTime);
        }
        if (params.attack !== undefined) voice.setAttack(params.attack, triggerTime);
        if (params.decay !== undefined) voice.setDecay(params.decay, triggerTime);
        if (params.sustain !== undefined) voice.setSustain(params.sustain, triggerTime);
        if (params.release !== undefined) voice.setRelease(params.release, triggerTime);

        // Apply per-step or global freeze
        if (noteParams?.freeze !== undefined) {
          voice.setFreeze(noteParams.freeze, triggerTime);
        } else if (params.freeze !== undefined) {
          voice.setFreeze(params.freeze, triggerTime);
        }

        // Apply Envelope Follower depths (global only)
        if (params.freezeEnvDepth !== undefined) voice.setFreezeEnvDepth(params.freezeEnvDepth, triggerTime);
        if (params.grainEnvDepth !== undefined) voice.setGrainEnvDepth(params.grainEnvDepth, triggerTime);
        if (noteParams?.grainPitchQuantize !== undefined) {
          voice.setGrainPitchQuantize(noteParams.grainPitchQuantize, triggerTime);
        } else if (params.grainPitchQuantize !== undefined) {
          voice.setGrainPitchQuantize(params.grainPitchQuantize, triggerTime);
        }

        if (noteParams?.tranceGate !== undefined) {
          voice.setTranceGate(noteParams.tranceGate, triggerTime);
        }

        // Apply Character Morphing
        voice.setCharacterMorph(characterMorph, morphTarget, 0.05); // Use short ramp time

        // Sync other params
        if (pVibratoDepth !== undefined) voice.setVibratoDepth(pVibratoDepth, triggerTime);
        if (pTremoloDepth !== undefined) voice.setTremoloDepth(pTremoloDepth * 100, triggerTime); // setTremoloDepth expects percentage 0-100
        if (pTremoloRate !== undefined) voice.setTremoloRate(pTremoloRate, triggerTime);
        if (pGateDepth !== undefined) voice.setGateDepth(pGateDepth, triggerTime);
        if (pGateRateHz !== undefined) voice.setGateRate(pGateRateHz, triggerTime);

        if (pAttack !== undefined) voice.setAttack(pAttack, triggerTime);
        if (pDecay !== undefined) voice.setDecay(pDecay, triggerTime);
        if (pSustain !== undefined) voice.setSustain(pSustain, triggerTime);
        if (pRelease !== undefined) voice.setRelease(pRelease, triggerTime);

        if (pFreeze !== undefined) voice.setFreeze(pFreeze, triggerTime);
        if (pFreezeLfoRate !== undefined) voice.setFreezeLfoRate(pFreezeLfoRate, triggerTime);
        if (pFreezeLfoDepth !== undefined) voice.setFreezeLfoDepth(pFreezeLfoDepth, triggerTime);
        if (pGrainLfoRate !== undefined) voice.setGrainLfoRate(pGrainLfoRate, triggerTime);
        if (pGrainLfoDepth !== undefined) voice.setGrainLfoDepth(pGrainLfoDepth, triggerTime);
        if (pGrainPosLfoDepth !== undefined) voice.setGrainPosLfoDepth(pGrainPosLfoDepth, triggerTime);

        if (pFreezeEnvDepth !== undefined) voice.setFreezeEnvDepth(pFreezeEnvDepth, triggerTime);
        if (pTimeStretchEnvDepth !== undefined) voice.setTimeStretchEnvDepth(pTimeStretchEnvDepth, triggerTime);
        if (pGrainEnvDepth !== undefined) voice.setGrainEnvDepth(pGrainEnvDepth, triggerTime);
        if (pGrainPitchEnvDepth !== undefined) voice.setGrainPitchEnvDepth(pGrainPitchEnvDepth, triggerTime);
        if (pGrainJitter !== undefined) voice.setGrainJitter(pGrainJitter, triggerTime);
        if (pGrainPitchQuantize !== undefined) voice.setGrainPitchQuantize(pGrainPitchQuantize, triggerTime);
        if (pGrainPanSpreadOuter !== undefined && voice.setGrainPanSpread) voice.setGrainPanSpread(pGrainPanSpreadOuter, triggerTime);

        if (pGranularPitchShift !== undefined) voice.setGranularPitchShift(pGranularPitchShift, triggerTime);
        if (pBitcrush !== undefined) voice.setBitcrush(pBitcrush, triggerTime);
        if (pSpectralComp !== undefined) voice.setSpectralComp(pSpectralComp, triggerTime);
        if (pDownsample !== undefined) voice.setDownsample(pDownsample, triggerTime);
        if (pSpectralCompression !== undefined) voice.setSpectralCompression(pSpectralCompression, triggerTime);
        if (pSubHarmonics !== undefined && voice.setSubHarmonics) voice.setSubHarmonics(pSubHarmonics, triggerTime);
        if (pVocalChorus !== undefined && voice.setVocalChorus) voice.setVocalChorus(pVocalChorus, triggerTime);
        if (pTransientExtraction !== undefined && voice.setTransientExtraction) voice.setTransientExtraction(pTransientExtraction, triggerTime);
        if (pAutoTune !== undefined && (voice as any).setAutoTune) (voice as any).setAutoTune(pAutoTune, triggerTime);
        if (pDrumDuckDepth !== undefined && (voice as any).setDrumDuckDepth) (voice as any).setDrumDuckDepth(pDrumDuckDepth, triggerTime);
        if (pPhonemeFilterMod !== undefined) voice.setPhonemeFilterMod(pPhonemeFilterMod, triggerTime);
        if (pTranceGate !== undefined) voice.setTranceGate(pTranceGate, triggerTime);
        if (pVolumeFilterMod !== undefined && (voice as any).setVolumeFilterMod) (voice as any).setVolumeFilterMod(pVolumeFilterMod, triggerTime);

        voice.setCustomWindowShape(pCustomWindowShape, triggerTime);

        if (pFormantLfoRateHz !== undefined) voice.setFormantLfoRate(pFormantLfoRateHz, triggerTime);
        if (pFormantLfoDepth !== undefined) voice.setFormantLfoDepth(pFormantLfoDepth, triggerTime);
        voice.setFormantLfoShape(pFormantLfoShape);

        if (pEnvAmount !== 0) voice.setFormantEnvelope(pEnvAmount, pEnvAttack as number, pEnvDecay as number, triggerTime);
        voice.setFormantEnvFollower(pFormantEnvFollower as number, triggerTime);

        // Load buffer only if the voice doesn't already have it
        if (isNewBank) {
          voice.loadBuffer(buffer.getChannelData(0));
        }

        // CHECK FOR SLICE TRIGGER MODE
        if (params.sliceMode === 'phoneme' && alignment) {
          let sliceIndex = -1;
          let pitchRatio = 1.0;

          if (noteParams?.sliceIndex !== undefined) {
            sliceIndex = noteParams.sliceIndex;
            const targetMidi = noteToMidi(noteStr);
            const baseMidi = 60;
            pitchRatio = Math.pow(2, (targetMidi - baseMidi + pitchOffset + pitchOffsetSemitones) / 12);
          } else {
            const targetMidi = noteToMidi(noteStr);
            sliceIndex = targetMidi - 60;
            pitchRatio = Math.pow(2, (pitchOffset + pitchOffsetSemitones) / 12);
          }

          if (sliceIndex >= 0) {
            const phonemeId = `${params.sampleName}_${sliceIndex}`;
            void voice.triggerSlice(
              buffer.getChannelData(0),
              sliceIndex,
              alignment,
              pitchRatio,
              noteParams?.reverse,
              targetDuration,
              triggerTime,
              phonemeId,
              noteParams?.velocity !== undefined ? noteParams.velocity : 1.0,
            );
            return;
          }
        }

        // 1. Calculate Time Ratio
        const timeRatio = targetDuration / originalDuration;
        voice.setTimeRatio(timeRatio, triggerTime);

        // 2. Pitch Shift (with offset for harmonizer and slide support)
        const targetMidi = noteToMidi(noteStr) + pitchOffsetSemitones;
        const targetHz = tunedNoteToFrequency(noteStr, tuning ?? null) * Math.pow(2, (pitchOffset + pitchOffsetSemitones) / 12);

        if (noteParams?.slideFromMidi !== undefined) {
          const startMidi = noteParams.slideFromMidi + pitchOffsetSemitones;
          voice.setPitchFromMidi(startMidi + pitchOffset, 60, triggerTime, undefined, undefined, tuning);
          // Glide over half the target duration or a minimum of 0.15s, bounded by actual duration
          const glideDuration = Math.min(Math.max(targetDuration * 0.5, 0.15), targetDuration);

          if (noteParams?.slideType === 'exponential' || params.portamentoType === 'exponential') {
            voice.exponentialRampPitchFromMidi(targetMidi + pitchOffset, 60, triggerTime + glideDuration, undefined, undefined, tuning);
          } else {
            voice.linearRampPitchFromMidi(targetMidi + pitchOffset, 60, triggerTime + glideDuration, undefined, undefined, tuning);
          }
        } else {
          voice.setPitchFromMidi(targetMidi + pitchOffset, 60, triggerTime, undefined, undefined, tuning);
        }

        // 3. Phoneme Awareness (from Jules branch)
        if (alignment) {
          voice.setAlignment(alignment);
          voice.sendPhonemeDataToWorklet(targetDuration);
        }

        // 4. Play

        // Pitch Envelope
        let finalPitchAmount = pPitchAmount;
        let finalPitchAttack = pPitchAttack;
        let finalPitchDecay = pPitchDecay;

        // Auto-pitch envelope on high velocity (e.g., > 0.85) if not manually overridden
        const velocity = noteParams?.velocity !== undefined ? noteParams.velocity : 1.0;
        if (velocity > 0.85 && finalPitchAmount === 0) {
            finalPitchAmount = 2.0; // 2 semitones
            finalPitchAttack = 0.01; // Fast attack
            finalPitchDecay = 0.08; // Fast decay
        }

        if (voice.setPitchAttack) {
          voice.setPitchAttack(finalPitchAttack, triggerTime);
        }
        if (voice.setPitchDecay) {
          voice.setPitchDecay(finalPitchDecay, triggerTime);
        }
        if (voice.setPitchAmount) {
          voice.setPitchAmount(finalPitchAmount, triggerTime);
        }

        voice.play(undefined, undefined, 1.0, noteParams?.reverse, targetHz);

        const releaseTime = triggerTime + targetDuration;
        // ⚡ Bolt Optimization: Replace main-thread setTimeout with worklet-scheduled noteOff
        voice.noteOff(releaseTime);
      };

      const runVoices = (noteStr: string, timeOffset: number, duration: number) => {
        const t = actualTime + timeOffset;

        const mainVoiceData = manager.acquireVoiceForBank(params.sampleName);
                triggerVoice(noteStr, mainVoiceData.voice, 0, t, duration, undefined, mainVoiceData.isNewBank);

        const effectiveChoir = noteParams?.choir !== undefined ? noteParams.choir : (params.choir || 0);

        if (effectiveChoir > 0 && pitchOffsetSemitones === 0) {
          const detune = 0.15;
          const gain = effectiveChoir * 0.7;

          if (refs.choirLeftGainRef.current) refs.choirLeftGainRef.current.gain.setTargetAtTime(gain, t, 0.02);
          if (refs.choirRightGainRef.current) refs.choirRightGainRef.current.gain.setTargetAtTime(gain, t, 0.02);

          const leftVoiceData = manager.acquireVoiceForBank(params.sampleName);
          if (leftVoiceData.index !== mainVoiceData.index) {
                        triggerVoice(noteStr, leftVoiceData.voice, detune, t, duration, refs.choirLeftGainRef.current!, leftVoiceData.isNewBank);
          }

          const rightVoiceData = manager.acquireVoiceForBank(params.sampleName);
          if (rightVoiceData.index !== mainVoiceData.index && rightVoiceData.index !== leftVoiceData.index) {
                        triggerVoice(noteStr, rightVoiceData.voice, -detune, t, duration, refs.choirRightGainRef.current!, rightVoiceData.isNewBank);
          }
        } else if (pitchOffsetSemitones === 0) {
          if (refs.choirLeftGainRef.current) refs.choirLeftGainRef.current.gain.setTargetAtTime(0, t, 0.02);
          if (refs.choirRightGainRef.current) refs.choirRightGainRef.current.gain.setTargetAtTime(0, t, 0.02);
        }
      };

      // For each note in the chord
      // ⚡ Bolt Optimization: Replacing forEach with for...of to prevent closure allocations on hot path
      for (const noteStr of notes) {
        if (shouldGlitch) {
          const numStutters = Math.floor(Math.random() * 3) + 2;
          const totalDur = durationSteps * stepTime;
          const stutterLen = Math.min(0.06, totalDur / numStutters);

          for (let i = 0; i < numStutters; i++) {
            runVoices(noteStr, i * stutterLen, stutterLen);
          }
          const played = numStutters * stutterLen;
          if (totalDur > played) {
            runVoices(noteStr, played, totalDur - played);
          }
        } else {
          for (let r = 0; r < retrigger; r++) {
            const offset = r * (subDurationSteps * stepTime);
            runVoices(noteStr, offset, subDurationSteps * stepTime);
          }
        }
      }
      return;
    }

    // Buffer playback mode (non-stretch)
    const playBufferSource = (startTime: number, duration: number, pitchSemitones: number) => {
      const source = context.createBufferSource();

      const targetMidi = pitchSemitones;
      let playbackBuffer: AudioBuffer;
      let pitchRatio = 1.0;

      if (multisampleBank?.pitchBank.has(targetMidi)) {
        playbackBuffer = multisampleBank.pitchBank.get(targetMidi)!;
        pitchRatio = params.playbackSpeed;
      } else {
        playbackBuffer = multisampleBank?.baseBuffer || buffer;
        const rootMidi = multisampleBank?.rootNote ?? 60;
        const speed = params.playbackSpeed;
        pitchRatio = speed * Math.pow(2, (targetMidi - rootMidi) / 12);
      }

      if (noteParams?.reverse) {
        const clonedBuffer = context.createBuffer(
          playbackBuffer.numberOfChannels,
          playbackBuffer.length,
          playbackBuffer.sampleRate
        );
        for (let i = 0; i < playbackBuffer.numberOfChannels; i++) {
          const srcData = playbackBuffer.getChannelData(i);
          const destData = clonedBuffer.getChannelData(i);
          for (let j = 0; j < srcData.length; j++) {
            destData[j] = srcData[srcData.length - 1 - j];
          }
        }
        source.buffer = clonedBuffer;
      } else {
        source.buffer = playbackBuffer;
      }

      source.playbackRate.value = pitchRatio;

      const gain = context.createGain();
      gain.gain.value = params.volume;

      const filter = context.createBiquadFilter();
      filter.type = 'lowpass';
      const cutoff = noteParams?.filterCutoff !== undefined
        ? Math.max(20, noteParams.filterCutoff * 20000)
        : params.filterCutoff;
      filter.frequency.value = cutoff;

      const resonance = noteParams?.filterResonance !== undefined
        ? noteParams.filterResonance * 20
        : params.filterResonance;
      filter.Q.value = resonance;

      const shaper = context.createWaveShaper();
      const driveAmount = noteParams?.drive !== undefined ? noteParams.drive : params.drive;
      if (driveAmount > 0) {
        shaper.curve = makeDistortionCurve(driveAmount * 100);
      } else {
        shaper.curve = null;
      }

      let finalDestination: AudioNode = refs.masterSaturationRef.current!;
      if (params.pan !== undefined && params.pan !== 0) {
        const panner = context.createStereoPanner();
        panner.pan.value = params.pan;
        panner.connect(refs.masterSaturationRef.current!);
        finalDestination = panner;
      }

      source.connect(filter);
      filter.connect(shaper);
      shaper.connect(gain);
      gain.connect(finalDestination);

      source.start(startTime);
      if (duration > 0) {
        source.stop(startTime + duration);
      }
    };

    // ⚡ Bolt Optimization: Replacing forEach with for...of to prevent closure allocations on hot path
    for (const noteStr of notes) {
      const midi = noteToMidi(noteStr);

      if (shouldGlitch) {
        const numStutters = Math.floor(Math.random() * 3) + 2;
        const stutterLen = 0.06;

        for (let i = 0; i < numStutters; i++) {
          playBufferSource(actualTime + i * stutterLen, stutterLen, midi);
        }
        playBufferSource(actualTime + numStutters * stutterLen, 0, midi);
      } else {
        for (let r = 0; r < retrigger; r++) {
          const offset = r * (subDurationSteps * stepTime);
          playBufferSource(actualTime + offset, subDurationSteps * stepTime, midi);
        }
      }
    }
  };
}

import type { SamplerBankParams } from "../../../types";
import { noteToMidi } from "../../../utils/musicTheory";
import type { PlaySamplerFn, PlaySamplerVoiceFn, SamplerPlaybackRefs } from "./types";

export function createPlaySampler(
  playSamplerVoice: PlaySamplerVoiceFn,
  refs: Pick<SamplerPlaybackRefs, "harmonizerRef">,
): PlaySamplerFn {
  return (params, note, time, durationSteps = 1, stepTime = 0.2, noteParams, tuning) => {
    // Harmonize support - if harmonizer is active, generate multiple harmony voices
    const harmonizer = refs.harmonizerRef.current;
    if (harmonizer?.getIsActive()) {
      const voices = harmonizer.generateVoices();

      // Play base voice (index 0) - the original note
      playSamplerVoice(params, note, time, durationSteps, stepTime, noteParams as any, 0, tuning);

      // Play each harmony voice (skip index 0 which is base)
      // ⚡ Bolt Optimization: Replacing forEach with for...of to prevent closure allocations on hot path
      for (const voice of voices) {
        if (voice.index === 0) continue; // Skip base voice, already played above

        // Create modified params for this harmony voice
        const config = harmonizer.getConfig();
        const voiceParams: SamplerBankParams = {
          ...params,
          pan: Math.max(-1, Math.min(1, (params.pan || 0) + (voice.pan || 0))),
          volume: params.volume * voice.gain * 0.85,
          formantShift: (params.formantShift || 0) + voice.formantShift,
          fineTune: (params.fineTune || 0) + voice.detuneCents
        };
        if (config.harmonyAttack !== undefined) {
          voiceParams.attack = config.harmonyAttack;
        }
        if (config.harmonyRelease !== undefined) {
          voiceParams.release = config.harmonyRelease;
        }

        // Play this voice with pitch offset and slight delay for natural ensemble effect
        const delayMs = voice.index * 5;
        // ⚡ Bolt Optimization: Replace main-thread setTimeout with worklet/API-scheduled delayed start time
        playSamplerVoice(voiceParams, note, time + (delayMs / 1000), durationSteps, stepTime, noteParams as any, voice.pitchOffset, tuning);
      }
      return;
    }

    playSamplerVoice(params, note, time, durationSteps, stepTime, noteParams as any, 0, tuning);
  };
}

export type NoteOnSamplerFn = (
  params: SamplerBankParams,
  note: string,
  time?: number,
  tuning?: any,
) => number | null;

export function createNoteOnSampler(
  context: AudioContext,
  refs: Pick<
    SamplerPlaybackRefs,
    | "multisampleBanksRef"
    | "loadedSampleBuffersRef"
    | "masterSaturationRef"
    | "nextSamplerNoteId"
    | "activeSamplerNotes"
  >,
): NoteOnSamplerFn {
  return (params, note, time, _tuning) => {
    const now = time || context.currentTime;

    const multisampleBank = refs.multisampleBanksRef.current.get(params.sampleName);
    const legacyBuffer = refs.loadedSampleBuffersRef.current.get(params.sampleName);
    const buffer = multisampleBank?.baseBuffer || legacyBuffer;

    if (!buffer || !refs.masterSaturationRef.current) return null;

    const rootNote = params.rootNote ?? 60;
    const coarseTune = params.coarseTune ?? 0;
    const fineTune = params.fineTune ?? 0;

    const targetMidi = noteToMidi(note);
    const source = context.createBufferSource();

    let playbackBuffer: AudioBuffer;
    let pitchRatio: number;

    if (multisampleBank?.pitchBank.has(targetMidi)) {
      playbackBuffer = multisampleBank.pitchBank.get(targetMidi)!;
      pitchRatio = params.playbackSpeed;
    } else {
      playbackBuffer = multisampleBank?.baseBuffer || buffer;
      const rootMidi = multisampleBank?.rootNote ?? rootNote;
      const effectivePitchOffset = coarseTune + (fineTune / 100);
      pitchRatio = params.playbackSpeed * Math.pow(2, (targetMidi - rootMidi + effectivePitchOffset) / 12);
    }

    source.buffer = playbackBuffer;
    source.playbackRate.value = pitchRatio;

    const gain = context.createGain();
    gain.gain.value = params.volume;

    source.connect(gain);
    gain.connect(refs.masterSaturationRef.current);
    source.start(now);

    const id = refs.nextSamplerNoteId.current++;
    refs.activeSamplerNotes.current.set(id, { source, envGain: gain });
    return id;
  };
}

export function createNoteOffSampler(
  context: AudioContext,
  refs: Pick<SamplerPlaybackRefs, "activeSamplerNotes">,
) {
  return (id: number) => {
    const note = refs.activeSamplerNotes.current.get(id);
    if (note) {
      const now = context.currentTime;
      note.envGain.gain.cancelScheduledValues(now);
      note.envGain.gain.linearRampToValueAtTime(0, now + 0.1);
      note.source.stop(now + 0.1);
      refs.activeSamplerNotes.current.delete(id);
    }
  };
}

import { useEffect, useRef } from 'react';
import { engineDegradationStore } from '../../stores/engineDegradationStore';
import { probeWebGPU } from '../../engines/backends/webgpuProbe';
import type { AutomationLanePoint } from '../../types';

// The compute shader takes the list of points and interpolation mode,
// and outputs the y values for the line strip.
const COMPUTE_SHADER_CODE = `
struct Params {
  pointCount: u32,
  interpolation: u32, // 0: step, 1: linear, 2: smooth
  totalSteps: f32,
  padding: f32,
}

struct Point {
  step: f32,
  value: f32,
  accent: u32,
  slide: u32,
}

struct OutputPoint {
  position: vec2<f32>,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> pointsBuffer: array<Point>;
@group(0) @binding(2) var<storage, read_write> outputBuffer: array<OutputPoint>;

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
  let index = global_id.x;
  let totalOutputPoints = 1024u;

  if (index >= totalOutputPoints) { return; }

  let xNormalized = f32(index) / f32(totalOutputPoints - 1u);
  let stepPosition = xNormalized * params.totalSteps;

  var y = 0.0;

  if (params.pointCount > 0u) {
    var p0 = pointsBuffer[0];
    if (stepPosition <= p0.step) {
      y = p0.value;
    } else {
      var found = false;
      for (var i = 1u; i < params.pointCount; i++) {
        let p1 = pointsBuffer[i];
        if (stepPosition <= p1.step) {
           p0 = pointsBuffer[i - 1u];
           if (params.interpolation == 0u) {
             y = p0.value;
           } else if (params.interpolation == 1u) {
             let t = (stepPosition - p0.step) / (p1.step - p0.step);
             y = mix(p0.value, p1.value, t);
           } else if (params.interpolation == 2u) {
             let t = (stepPosition - p0.step) / (p1.step - p0.step);
             let smoothT = t * t * (3.0 - 2.0 * t);
             y = mix(p0.value, p1.value, smoothT);
           }
           found = true;
           break;
        }
      }
      if (!found) {
        y = pointsBuffer[params.pointCount - 1u].value;
      }
    }
  }

  // Write to Storage Buffer
  // X range: -1 to 1, Y range: -1 to 1
  outputBuffer[index].position = vec2<f32>(xNormalized * 2.0 - 1.0, y * 2.0 - 1.0);
}
`;

const VERTEX_FRAGMENT_SHADER = `
struct Point {
  position: vec2<f32>,
}

@group(0) @binding(1) var<storage, read> inputBuffer: array<Point>;

struct VertexOutput {
  @builtin(position) Position : vec4<f32>,
  @location(0) color : vec4<f32>,
}

@group(0) @binding(2) var<uniform> accentColor: vec4<f32>;

@vertex
fn vs_main(@builtin(vertex_index) vertexIndex : u32) -> VertexOutput {
  let point = inputBuffer[vertexIndex];
  var output : VertexOutput;
  output.Position = vec4<f32>(point.position.x, point.position.y, 0.0, 1.0);
  output.color = accentColor;
  return output;
}

@fragment
fn fs_main(@location(0) color : vec4<f32>) -> @location(0) vec4<f32> {
  return color;
}
`;

export const useWebGPUCurveEditor = (
  canvasRef: React.RefObject<HTMLCanvasElement | null>,
  points: AutomationLanePoint[],
  interpolation: string,
  totalSteps: number,
  width: number,
  height: number
) => {
  const deviceRef = useRef<GPUDevice | null>(null);
  const pipelineRef = useRef<GPUComputePipeline | null>(null);
  const renderPipelineRef = useRef<GPURenderPipeline | null>(null);
  const uniformBufferRef = useRef<GPUBuffer | null>(null);
  const pointsBufferRef = useRef<GPUBuffer | null>(null);
  const storageBufferRef = useRef<GPUBuffer | null>(null);
  const accentColorBufferRef = useRef<GPUBuffer | null>(null);
  const bindGroupRef = useRef<GPUBindGroup | null>(null);

  const pointsRef = useRef(points);
  const interpolationRef = useRef(interpolation);
  const totalStepsRef = useRef(totalSteps);

  const WORKGROUP_SIZE = 64;
  const NUM_POINTS = 1024;
  const MAX_INPUT_POINTS = 256;

  useEffect(() => {
    pointsRef.current = points;
    interpolationRef.current = interpolation;
    totalStepsRef.current = totalSteps;
  }, [points, interpolation, totalSteps]);

  useEffect(() => {
    let isCleanedUp = false;

    const initWebGPU = async () => {
      if (!canvasRef.current) return;

      const probe = await probeWebGPU();
      if (!probe.ok || !probe.device || isCleanedUp) {
        if (!probe.ok) {
          engineDegradationStore.report({
            id: 'webgpu-curve-editor',
            subsystem: 'webgpu-curve-editor',
            category: 'gpu',
            message: 'Curve Editor using SVG fallback',
            reason: probe.reason ?? 'WebGPU unavailable',
            status: 'active',
            activeBackend: 'static',
            requestedBackend: 'webgpu',
            retryable: false,
          });
        }
        return;
      }

      const device = probe.device;
      deviceRef.current = device;

      const context = canvasRef.current.getContext('webgpu') as GPUCanvasContext | null;
      if (!context) return;

      const format = navigator.gpu?.getPreferredCanvasFormat?.() ?? 'bgra8unorm';
      context.configure({ device, format });

      const computeModule = device.createShaderModule({ code: COMPUTE_SHADER_CODE });
      const renderModule = device.createShaderModule({ code: VERTEX_FRAGMENT_SHADER });

      const bindGroupLayout = device.createBindGroupLayout({
        entries: [
          { binding: 0, visibility: GPUShaderStage.COMPUTE, buffer: { type: 'uniform' } },
          { binding: 1, visibility: GPUShaderStage.COMPUTE, buffer: { type: 'read-only-storage' } },
          { binding: 2, visibility: GPUShaderStage.COMPUTE | GPUShaderStage.VERTEX, buffer: { type: 'storage' } },
          { binding: 3, visibility: GPUShaderStage.VERTEX, buffer: { type: 'uniform' } },
        ],
      });

      const pipelineLayout = device.createPipelineLayout({ bindGroupLayouts: [bindGroupLayout] });

      pipelineRef.current = device.createComputePipeline({
        layout: pipelineLayout,
        compute: { module: computeModule, entryPoint: 'main' },
      });

      renderPipelineRef.current = device.createRenderPipeline({
        layout: pipelineLayout,
        vertex: { module: renderModule, entryPoint: 'vs_main' },
        fragment: { module: renderModule, entryPoint: 'fs_main', targets: [{ format }] },
        primitive: { topology: 'line-strip' },
      });

      uniformBufferRef.current = device.createBuffer({
        size: 16, // 4 u32s
        usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
      });

      pointsBufferRef.current = device.createBuffer({
        size: MAX_INPUT_POINTS * 4 * 4, // 256 points * 4 floats/u32s * 4 bytes
        usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
      });

      storageBufferRef.current = device.createBuffer({
        size: NUM_POINTS * 2 * 4,
        usage: GPUBufferUsage.STORAGE | GPUBufferUsage.VERTEX,
      });

      accentColorBufferRef.current = device.createBuffer({
        size: 16,
        usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
      });

      bindGroupRef.current = device.createBindGroup({
        layout: bindGroupLayout,
        entries: [
          { binding: 0, resource: { buffer: uniformBufferRef.current } },
          { binding: 1, resource: { buffer: pointsBufferRef.current } },
          { binding: 2, resource: { buffer: storageBufferRef.current } },
          { binding: 3, resource: { buffer: accentColorBufferRef.current } },
        ],
      });

      let animationFrameId: number;

      const renderFrame = () => {
        if (isCleanedUp || !deviceRef.current) return;
        const device = deviceRef.current;
        const currentPoints = pointsRef.current;
        const currentInterp = interpolationRef.current;
        const currentTotalSteps = totalStepsRef.current;

        let interpMode = 0;
        if (currentInterp === 'linear') interpMode = 1;
        else if (currentInterp === 'smooth') interpMode = 2;

        const uniformData = new Uint32Array(4);
        uniformData[0] = Math.min(currentPoints.length, MAX_INPUT_POINTS);
        uniformData[1] = interpMode;
        const uniformDataFloat = new Float32Array(uniformData.buffer);
        uniformDataFloat[2] = currentTotalSteps;

        device.queue.writeBuffer(uniformBufferRef.current!, 0, uniformData);

        const pointsData = new Float32Array(MAX_INPUT_POINTS * 4);
        const pointsDataUint = new Uint32Array(pointsData.buffer);

        for (let i = 0; i < Math.min(currentPoints.length, MAX_INPUT_POINTS); i++) {
          const p = currentPoints[i];
          pointsData[i * 4] = p.step;
          pointsData[i * 4 + 1] = p.value;
          pointsDataUint[i * 4 + 2] = p.accent ? 1 : 0;
          pointsDataUint[i * 4 + 3] = p.slide ? 1 : 0;
        }

        device.queue.writeBuffer(pointsBufferRef.current!, 0, pointsData);

        // Update accent color
        const colorData = new Float32Array([0.0, 0.898, 1.0, 1.0]); // cyan-400
        device.queue.writeBuffer(accentColorBufferRef.current!, 0, colorData);

        const commandEncoder = device.createCommandEncoder();

        const computePass = commandEncoder.beginComputePass();
        computePass.setPipeline(pipelineRef.current!);
        computePass.setBindGroup(0, bindGroupRef.current!);
        computePass.dispatchWorkgroups(Math.ceil(NUM_POINTS / WORKGROUP_SIZE));
        computePass.end();

        const context = canvasRef.current!.getContext('webgpu') as GPUCanvasContext | null;
        if (context) {
            const textureView = context.getCurrentTexture().createView();
            const renderPass = commandEncoder.beginRenderPass({
            colorAttachments: [{
                view: textureView,
                clearValue: { r: 0, g: 0, b: 0, a: 0 },
                loadOp: 'clear',
                storeOp: 'store',
            }],
            });

            renderPass.setPipeline(renderPipelineRef.current!);
            renderPass.setBindGroup(0, bindGroupRef.current!);
            renderPass.draw(NUM_POINTS);
            renderPass.end();
            device.queue.submit([commandEncoder.finish()]);
        }

        animationFrameId = requestAnimationFrame(renderFrame);
      };

      renderFrame();

      return () => {
         cancelAnimationFrame(animationFrameId);
      }
    };

    const cleanupPromise = initWebGPU();

    return () => {
      isCleanedUp = true;
      deviceRef.current = null;
    };
  }, [canvasRef]);
};

/**
 * Composes the app's ~25 state/handler sub-hooks into one object, currently
 * handed to a single React context (`AppStateContext`) with no memo boundary
 * or selector. Every field returned here is folded into one flat object that
 * is a fresh reference on every render, so any state change anywhere — a
 * knob turn, a step toggle, a transport tick — re-renders every component
 * that reads *anything* off `useAppStateContext()`, regardless of which
 * field it actually needs. See docs/PERFORMANCE_BUDGET.md's "React render
 * budget" section for the measured cost of this.
 *
 * Migration plan (mirrors the repo's existing `useSyncExternalStore` slice
 * stores under src/stores/, e.g. automationStore.ts, midiMapStore.ts,
 * transportSyncStore.ts — each lets a component subscribe to exactly the
 * slice it needs via `useXStore(selector)`, independent of everything else):
 *
 *   1. UI modals       → src/stores/uiModalsStore.ts (done, #1259)
 *   2. Transport/mix   → src/stores/transportMixStore.ts (done, #1284) —
 *      wrapped by src/hooks/appState/useTransportMixState.ts so this
 *      function keeps returning the same field names.
 *   3. Sampler banks   → active bank, track storage, TTS phrases. Currently
 *      src/hooks/appState/useSamplerBanksState.ts (plain useState); target
 *      src/stores/samplerBanksStore.ts.
 *   4. Pattern edit    → selection, clipboard, scale, zoom. Currently
 *      src/hooks/appState/usePatternEditState.ts (plain useState); target
 *      src/stores/patternEditStore.ts.
 *   5. Instrument state → synthA/B, bass2, kick/snare/hats, sampler params.
 *      Currently src/hooks/appState/useInstrumentState.ts (plain useState);
 *      target src/stores/instrumentStateStore.ts.
 *   6. Session/song    → song structure, session launcher state. Currently
 *      src/hooks/appState/useSongModeState.ts and
 *      src/hooks/appState/useSessionState.ts (plain useState); target
 *      src/stores/songModeStore.ts and src/stores/sessionStore.ts.
 *
 * Each phase lands as its own PR: extract the sub-hook's `useState` calls
 * into an external store class + `useXStore(selector)` hook, keep this
 * function returning the same field names so `AppStateContext` keeps working
 * as a compatibility shim, and move any component that can read the new
 * store directly off `useAppStateContext()` for that slice (see
 * `TransportHeader.tsx` / `RackNode.tsx` / `App.tsx`'s `is3DMode` reads for
 * the pattern to follow). Once every phase lands, stable `handle*` callbacks
 * should move to a separate, never-changing actions context, and
 * `AppStateContext` can be deleted once nothing destructures from it anymore.
 */
import { useCallback, useEffect, useRef, useState, useMemo } from 'react'
import { useAudioEngine } from './useAudioEngine'
import { usePyodideEngine } from './usePyodideEngine'
import { useScheduler } from './useScheduler'
import { useStepHandler } from './useStepHandler'
import { useUndoRedo } from './useUndoRedo'
import { useGamepad } from './useGamepad'
import { useMidi } from './useMidi'
import { useTransportSyncStore } from '../stores/transportSyncStore'
import { useStableKnobConfig } from './useStableKnobConfig'
import { useSongStorage } from './useSongStorage'
import { useProjectAutosave } from './useProjectAutosave'
import { useTTSPreloader } from './useTTSPreloader'
import { SupertonicService } from '../services/Supertonic'
import { loadingProgressStore } from '../stores/loadingProgressStore'
import { automationStore } from '../stores/automationStore';
import { AutomationScheduler } from '../audio/automation/AutomationScheduler';
import { getWamHost } from '../audio/wam';
import type { PcfEffect } from '../engines/PcfEffect';
import { resolveRealtimeTB303Model } from '../engines/TB303Models';
import { applyTrackParamSlotToEngine } from '../importers/rbs/applyImportedEngineState';
import { Open303Manager } from '../engines/Open303Manager';
import type { MainSequencerHandle } from '../components/MainSequencer'

import {
    NUM_STEPS,
} from '../constants'
import type { Pattern, ResolvedTrakEvent } from '../types'
import {
    UPDATED_INITIAL_PATTERN,
} from '../constants/appDefaults'
import {
    getBass2Controls, getSynthControls, getKickControls, getSnareControls,
    getClosedHatControls, getOpenHatControls, getSamplerControls,
} from '../utils/knobConfigs'

import { useSelectionHandlers } from './appState/useSelectionHandlers'
import { useClipboardHandlers } from './appState/useClipboardHandlers'
import { usePatternHandlers } from './appState/usePatternHandlers'
import { useAutomationHandlers } from './appState/useAutomationHandlers'
import { useKeyboardHandlers } from './appState/useKeyboardHandlers'
import { useLyricHandlers } from './appState/useLyricHandlers'
import { useSynthParamHandlers } from './appState/useSynthParamHandlers'
import { useMasterHandlers } from './appState/useMasterHandlers'
import { useTransportHandlers } from './appState/useTransportHandlers'
import { useAutoMix } from './appState/useAutoMix'
import { useSongHandlers, useSampleHandlers } from './appState/useSongHandlers'
import { useHardwarePanels } from './appState/useHardwarePanels'
import { useInstrumentState } from './appState/useInstrumentState'
import { useSamplerVoiceState } from './appState/useSamplerVoiceState'
import { useUIModalsState } from './appState/useUIModalsState'
import { useSongModeState } from './appState/useSongModeState'
import { useSessionState } from './appState/useSessionState'
import { useSongStructureEditor } from './useSongStructureEditor'
import { usePatternEditState } from './appState/usePatternEditState'
import { useSamplerBanksState } from './appState/useSamplerBanksState'
import { useTransportMixState } from './appState/useTransportMixState'

export function useAppState() {

    const { pyodide, isPyodideReady, pyodideStatus } = usePyodideEngine()

    const {
        isVoiceEditorOpen, setIsVoiceEditorOpen,
        isCloudLibraryOpen, setIsCloudLibraryOpen,
        isAISongModalOpen, setIsAISongModalOpen,
        isRbsImportModalOpen, setIsRbsImportModalOpen,
        isSmfImportModalOpen, setIsSmfImportModalOpen,
        isExportModalOpen, setIsExportModalOpen,
        isLyricTrackVisible, setIsLyricTrackVisible,
        isShortcutsHelpOpen, setIsShortcutsHelpOpen,
        showGamepadDebug, setShowGamepadDebug,
        isGenerating, setIsGenerating,
        hasStarted, setHasStarted,
        forceScriptProcessorFallback, setForceScriptProcessorFallback,
        is3DMode, setIs3DMode,
        toast, setToast,
        showToast,
    } = useUIModalsState();

    useGamepad();

    const {
        tempo, setTempo, tempoRef,
        swing, setSwing,
        lastFreqRef,
        ambianceUrl, setAmbianceUrl,
        backgroundImage, setBackgroundImage,
        masterVolume, setMasterVolume,
        masterSaturation, setMasterSaturation,
        globalPan, setGlobalPan,
        reverbType, setReverbType,
    } = useTransportMixState();

    const { audioEngine, isReady, initializeAudio, onParamChange, drumKitEngineRef, prophecyManagerRef } = useAudioEngine(pyodide, tempo)
    // Core sequencer transport only needs the Web Audio engine — it never touches
    // Pyodide ("Spectral Puppet"), so gating playback on Python readiness left the
    // clock permanently blocked whenever Pyodide was slow or failed to load.
    const isEngineReady = isReady

    useTTSPreloader()

    const [viewMode, setViewMode] = useState<'notes' | 'automation'>('notes');
    const [automationParam, setAutomationParam] = useState('formantShift');

    const [melodicMode, setMelodicMode] = useState(false);

    const {
        trackStorage, setTrackStorage, trackStorageRef,
        activeTrackSlots, setActiveTrackSlots, activeTrackSlotsRef,
        songStorage, setSongStorage,
        activeSongSlot, setActiveSongSlot,
        activeSamplerBank, setActiveSamplerBank, activeSamplerBankRef,
        activeAlignment, setActiveAlignment,
        sampleBuffers, setSampleBuffers,
        loadedBanks,
        multisampleReady,
        multisampleProcessing,
        ttsPhrases, setTtsPhrases,
        lastSamplerMidiRef,
        lastSamplerFormantRef,
        sliceHighlightRef,
    } = useSamplerBanksState(audioEngine);

    const handleStart = async () => {
        console.log("Initialization sequence started...");
        setHasStarted(true);
        try {
            // WebKit can hang inside AudioWorklet addModule; don't leave the
            // INITIALIZING overlay up forever (Playwright then waits 120s).
            await Promise.race([
                initializeAudio(),
                new Promise<void>((resolve) => {
                    window.setTimeout(resolve, 45_000);
                }),
            ]);
        } catch (e) {
            console.error("Failed to start system:", e);
        } finally {
            setIsInitialized(true);
            console.log("Audio Engine Initialized");
        }
        loadingProgressStore.startStep('ttsEngine');
        void SupertonicService.getInstance().init().then(() => {
            loadingProgressStore.completeStep('ttsEngine');
        }).catch((e: unknown) => {
            console.warn('Supertonic TTS failed to init:', e);
            loadingProgressStore.failStep(
                'ttsEngine',
                e instanceof Error ? e : new Error(String(e)),
                true,
            );
        });
    };

    const [pattern, setPattern] = useState<Pattern>(UPDATED_INITIAL_PATTERN)
    const undoRedo = useUndoRedo<Pattern>(50)
    const [isInitialized, setIsInitialized] = useState(false)
    const [isPlaying, setIsPlaying] = useState(false)
    const [isRecording, setIsRecording] = useState(false)
    const [isAutomationRecording, setIsAutomationRecording] = useState(false)

    const {
        selectedTrack, setSelectedTrack,
        contextMenu, setContextMenu,
        isNoteDragging, setIsNoteDragging,
        noteDragRef,
        currentScale, setCurrentScale,
        currentScaleRef,
        selection, setSelection,
        isSelecting, setIsSelecting,
        clipboard, setClipboard,
        isDrawing, setIsDrawing,
        drawMode, setDrawMode,
        zoomLevel, setZoomLevel,
    } = usePatternEditState();

    const {
        isSongModeOpen, setIsSongModeOpen,
        isSongModeActive, setIsSongModeActive,
        songStructure, setSongStructure,
        currentSongMeasure, setCurrentSongMeasure,
        songStructureRef,
        isSongModeActiveRef,
        songMeasureRef,
        isFirstStepRef,
        rbsArrangementExtrasRef,
    } = useSongModeState();

    const session = useSessionState();

    const {
        editSongStructure: handleEditSongStructure,
        undoSongStructure,
        redoSongStructure,
        canUndoSong,
        canRedoSong,
        clearSongUndo,
    } = useSongStructureEditor(songStructureRef, setSongStructure);

    const {
        synthA, setSynthA, synthARef, updateSynthA,
        synthB, setSynthB, synthBRef, updateSynthB,
        bass2, setBass2, bass2Ref, updateBass2,
        kick, setKick, kickRef, updateKick,
        snare, setSnare, snareRef, updateSnare,
        closedHat, setClosedHat, closedHatRef, updateClosedHat,
        openHat, setOpenHat, openHatRef, updateOpenHat,
        drumKit, drumKitRef, updateDrumKit,
        sampler, setSampler, samplerRef, updateSampler,
    } = useInstrumentState(drumKitEngineRef);

    const patternRef = useRef(pattern);
    useEffect(() => { patternRef.current = pattern; }, [pattern]);

    const sequencerRef = useRef<MainSequencerHandle>(null);
    const currentStepRef = useRef(-1);

    const {
        samplerVoiceParamsRef,
        samplerVoiceParams,
        setSamplerVoiceParams,
        harmonizerConfig,
        setHarmonizerConfig,
        isHarmonizeActive,
        setIsHarmonizeActive,
        handleHarmonizerConfigChange,
        handleSamplerVoiceChange,
    } = useSamplerVoiceState({
        audioEngine, sampler, activeSamplerBank, activeSamplerBankRef,
        samplerRef, setSampler, currentStepRef,
    });

    const automationSchedulerRef = useRef<AutomationScheduler | null>(null);
    const trakEventsRef = useRef<ResolvedTrakEvent[] | null>(null);
    useEffect(() => {
        const ctx = audioEngine?.context;
        const open303Engine = audioEngine?.open303Engine;
        const mgr = open303Engine instanceof Open303Manager ? open303Engine : null;
        const pcf: PcfEffect | null = audioEngine?.pcfEffect ?? null;
        if (ctx) {
            if (!automationSchedulerRef.current) {
                automationSchedulerRef.current = new AutomationScheduler(ctx, mgr ?? null, { ppq: 192 });
            } else {
                automationSchedulerRef.current.setOpen303Manager(mgr ?? null);
            }
            automationSchedulerRef.current.setPcfEffect(pcf);
            if (prophecyManagerRef) {
                automationSchedulerRef.current.setProphecyManager(prophecyManagerRef.current ?? null);
            }
            automationSchedulerRef.current.setWamHost(getWamHost());
        }
    }, [audioEngine, prophecyManagerRef]);

    useEffect(() => {
        const mgr = audioEngine?.open303Engine;
        if (!(mgr instanceof Open303Manager)) return;
        // normalize + realtime resolve: persist high-fid ids in song state, but
        // AudioWorklet always gets a realtime-safe voice (stock for offline-only).
        if (typeof mgr.syncModel303Settings === 'function') {
            mgr.syncModel303Settings({
                lead: resolveRealtimeTB303Model(synthA.model303, synthA.engine303, {
                    reportFallback: true,
                    subsystem: 'synthA-model303',
                }),
                bass1: resolveRealtimeTB303Model(synthB.model303, synthB.engine303, {
                    reportFallback: true,
                    subsystem: 'synthB-model303',
                }),
                bass2: resolveRealtimeTB303Model(bass2.model303, bass2.engine303, {
                    reportFallback: true,
                    subsystem: 'bass2-model303',
                }),
            });
        } else if (typeof mgr.syncEngine303Settings === 'function') {
            mgr.syncEngine303Settings({
                lead: synthA.engine303 ?? 'open303',
                bass1: synthB.engine303 ?? 'open303',
                bass2: bass2.engine303 ?? 'open303',
            });
        }
    }, [audioEngine, synthA.engine303, synthB.engine303, bass2.engine303, synthA.model303, synthB.model303, bass2.model303]);

    // Live high-fid A/B + diode-ladder coefficients (L2/L3). Runs after the
    // model sync above so A/B engages against the voice that was just set.
    useEffect(() => {
        const mgr = audioEngine?.open303Engine;
        if (!(mgr instanceof Open303Manager) || typeof mgr.syncModel303Extras !== 'function') return;
        mgr.syncModel303Extras({
            lead: synthA.model303Extra,
            bass1: synthB.model303Extra,
            bass2: bass2.model303Extra,
        });
    }, [audioEngine, synthA.model303Extra, synthB.model303Extra, bass2.model303Extra, synthA.model303, synthB.model303, bass2.model303]);

    const activeKeyboardNotesRef = useRef<Map<string, number>>(new Map());

    const {
        updateStorageForTrack,
        handlePatternChange,
        handleStepToggle,
        handlePitchChange,
        handlePhonemeUpdate,
        handleNoteSelect,
        handleNoteLengthChange,
        handleNotePropertyChange,
        handleClearPattern,
        handleTrackSlotClick,
        handleSelectRow,
        handleEditLength,
    } = usePatternHandlers({
        patternRef, setPattern, undoRedo, activeSamplerBankRef,
        contextMenu, setContextMenu, setSelection,
        trackStorageRef, activeTrackSlotsRef, setTrackStorage, setActiveTrackSlots,
        setSelectedTrack,
        onTrackSlotRecall: (track, slotIndex) => {
            if (track !== 'partA' && track !== 'partB' && track !== 'bass2') return;
            const storage = rbsArrangementExtrasRef.current?.trackParamStorage;
            if (!storage) return;
            const open303 = audioEngine?.open303Engine instanceof Open303Manager
                ? audioEngine.open303Engine
                : null;
            const applied = applyTrackParamSlotToEngine(
                storage,
                track,
                slotIndex,
                open303,
                {
                    synthA: synthARef.current,
                    synthB: synthBRef.current,
                    bass2: bass2Ref.current,
                },
            );
            if (applied.synthA) {
                synthARef.current = applied.synthA;
                setSynthA(applied.synthA);
            }
            if (applied.synthB) {
                synthBRef.current = applied.synthB;
                setSynthB(applied.synthB);
            }
            if (applied.bass2) {
                bass2Ref.current = applied.bass2;
                setBass2(applied.bass2);
            }
        },
    });

    const { handleSelectionStart, handleSelectionEnter, handleSelectionEnd } = useSelectionHandlers(
        selection, isSelecting, setSelection, setIsSelecting,
    );

    const { handleCopy, handlePaste } = useClipboardHandlers({
        selection, selectedTrack, clipboard, setClipboard, setPattern, setSelection,
        patternRef, activeSamplerBankRef, undoRedo, updateStorageForTrack, showToast,
        handleSelectionEnd, audioEngine,
    });

    const { onStep } = useStepHandler({
        audioEngine,
        tempo,
        onParamChange,
        currentStepRef,
        sequencerRef,
        patternRef,
        lastFreqRef,
        lastSamplerMidiRef,
        lastSamplerFormantRef,
        synthARef,
        synthBRef,
        bass2Ref,
        kickRef,
        snareRef,
        closedHatRef,
        openHatRef,
        samplerRef,
        samplerVoiceParamsRef,
        activeSamplerBankRef,
        sliceHighlightRef,
        isSongModeActiveRef,
        songStructureRef,
        currentScaleRef,
        songMeasureRef,
        isFirstStepRef,
        trackStorageRef,
        setCurrentSongMeasure,
        automationSchedulerRef,
        trakEventsRef,
        rbsArrangementExtrasRef,
        setSynthA,
        setSynthB,
        setBass2,
        sessionEngineRef: session.sessionEngineRef,
        sessionClockRef: session.sessionClockRef,
        setIsSongModeActive,
        onSessionTick: session.setPlayingSlots,
    })

    const { isPlaying: schedPlaying, setIsPlaying: setSchedPlaying } = useScheduler(tempo, NUM_STEPS, onStep, isEngineReady, audioEngine?.context ?? null, swing)

    useEffect(() => {
        session.sessionClockRef.current.tempo = tempo;
    }, [tempo, session.sessionClockRef]);
    useEffect(() => setIsPlaying(schedPlaying), [schedPlaying])

    useEffect(() => {
        if (!schedPlaying) {
            songMeasureRef.current = 0;
            setCurrentSongMeasure(0);
            isFirstStepRef.current = true;
            if (sequencerRef.current) sequencerRef.current.setHighlight(-1);
            currentStepRef.current = -1;
            session.sessionEngineRef.current?.resetTransport();
            automationStore.clearLiveValues();
            automationSchedulerRef.current?.cancelAll();
        }
    }, [schedPlaying, songMeasureRef, setCurrentSongMeasure, isFirstStepRef, session.sessionEngineRef]);

    const {
        adjustTempo,
        handleTempoHoldStart,
        handleTempoHoldEnd,
        handleTempoKeyDown,
        handlePanic,
        handlePlayToggle,
        tempoHoldIntervalRef,
        tempoHoldTimeoutRef,
    } = useTransportHandlers({
        isInitialized, isReady, initializeAudio, setIsInitialized,
        audioEngine, setSchedPlaying, setTempo, undoRedo, setPattern,
        activeKeyboardNotesRef,
    });

    const { handleAutomationChange, handleKnobRecordToggle, handleAutomationNudge, handleAutomationPunchIn, handleAutomationLaneAction } = useAutomationHandlers({
        automationParam, patternRef, setPattern, activeSamplerBankRef,
        updateStorageForTrack, currentStepRef, schedPlaying,
        isAutomationRecording, isSongModeActive, activeTrackSlotsRef, isSongModeActiveRef,
    });

    const {
        handleMasterVolume,
        handleMasterVolumeKeyDown,
        handleMasterVolumeReset,
        handleMasterSaturation,
        handleMasterSaturationKeyDown,
        handleMasterSaturationReset,
        handleGlobalPan,
        handleGlobalPanKeyDown,
        handleGlobalPanReset,
        handleReverbType,
    } = useMasterHandlers({
        setMasterVolume, setMasterSaturation, setGlobalPan, setReverbType,
        audioEngine, currentStepRef,
    });

    const {
        handleSynthChange,
        handleBass2Change,
        handleKickChange,
        handleSnareChange,
        handleClosedHatChange,
        handleOpenHatChange,
        handleSamplerChange,
        handleSamplerParamChange,
        onSynthAParamChange,
        onSynthBParamChange,
        onBass2ParamChange,
    } = useSynthParamHandlers({
        updateSynthA, updateSynthB, updateBass2, updateKick, updateSnare,
        updateClosedHat, updateOpenHat, setSampler, activeSamplerBank,
        currentStepRef, samplerRef,
    });

    const midiHandlers = useMemo(
        () => ({
            handleSynthChange,
            handleBass2Change,
            handleKickChange,
            handleSnareChange,
            handleClosedHatChange,
            handleOpenHatChange,
            handleSamplerChange,
            setMasterVolume,
            setMasterSaturation,
            setGlobalPan,
            setAudioMasterVolume: (v: number) => audioEngine?.setMasterVolume?.(v),
            setAudioMasterSaturation: (v: number) => audioEngine?.setMasterSaturation?.(v),
            setAudioGlobalPan: (v: number) => audioEngine?.setGlobalPan?.(v),
            getCurrentStep: () => currentStepRef.current,
            handleSessionControl: session.handleSessionMidi,
        }),
        [
            handleSynthChange, handleBass2Change, handleKickChange, handleSnareChange,
            handleClosedHatChange, handleOpenHatChange, handleSamplerChange,
