import { useEffect, useRef } from 'react';
import { midiPortManager } from '../midi/MidiPortManager';
import { midiMapStore } from '../stores/midiMapStore';
import type { MidiBinding, MidiControlTarget } from '../types/midi';
import { formatMidiBindingLabel, makeMidiControlId, midiValueToNormalized } from '../types/midi';
import { applyMidiControlValue, type MidiParamHandlers } from '../utils/midiParamDispatch';
import { midiMessageToBinding, parseMidiMessage } from '../utils/midiMessageParse';

export { parseMidiMessage } from '../utils/midiMessageParse';

export interface UseMidiOptions {
  handlers: MidiParamHandlers;
  showToast?: (message: string, type: 'success' | 'error' | 'info') => void;
}

function handleRawMidiMessage(
  data: Uint8Array,
  deviceId: string | undefined,
  handlers: MidiParamHandlers,
  showToast?: (message: string, type: 'success' | 'error' | 'info') => void,
): void {
  const parsed = parseMidiMessage(data);
  if (!parsed) return;
  const bindingInput = midiMessageToBinding(parsed);
  if (!bindingInput) return;

  const { key, value } = bindingInput;
  const state = midiMapStore.getState();

  if (state.learnMode && state.lastTouchedControl) {
    const binding: MidiBinding = {
      key,
      controlId: state.lastTouchedControl,
      deviceId: deviceId || undefined,
    };
    midiMapStore.addBinding(binding);
    midiMapStore.setLearnMode(false);
    showToast?.(
      `MIDI: ${formatMidiBindingLabel(key)} → ${state.lastTouchedControl}`,
      'success',
    );
    applyMidiControlValue(state.lastTouchedControl, midiValueToNormalized(value), handlers);
    midiMapStore.flashControl(state.lastTouchedControl);
    return;
  }

  const binding = midiMapStore.findBinding(key, deviceId);
  if (!binding) return;

  const normalized = midiValueToNormalized(value);
  applyMidiControlValue(binding.controlId, normalized, handlers);
  midiMapStore.flashControl(binding.controlId);
}

/**
 * Web MIDI input: learn mode, mapping persistence, and live CC routing.
 * Uses shared MidiPortManager — channel messages only (clock routed separately).
 */
export function useMidi({ handlers, showToast }: UseMidiOptions): void {
  const handlersRef = useRef(handlers);
  handlersRef.current = handlers;

  useEffect(() => {
    const refreshInputs = () => {
      const inputs = midiPortManager.getInputs();
      midiMapStore.setInputAvailable(
        inputs.length > 0,
        inputs.map((i) => i.name),
      );
    };

    const unsubChannel = midiPortManager.onChannelMessage((deviceId, data) => {
      handleRawMidiMessage(data, deviceId || undefined, handlersRef.current, showToast);
    });

    const unsubState = midiPortManager.onStateChange(refreshInputs);

    void midiPortManager.ensureAccess().then((access) => {
      if (access) refreshInputs();
      else midiMapStore.setInputAvailable(false);
    });

    return () => {
      unsubChannel();
      unsubState();
    };
  }, [showToast]);
}

/** Register a control touch for MIDI learn (knob drag, slider focus, long-press). */
export function registerMidiControlTouch(target: MidiControlTarget, param: string): void {
  midiMapStore.touchControl(makeMidiControlId(target, param));
}

/** Long-press on a control: arm learn mode for that parameter. */
export function startMidiLearnForControl(target: MidiControlTarget, param: string): void {
  midiMapStore.touchControl(makeMidiControlId(target, param));
  midiMapStore.setLearnMode(true);
}

import { useState, useEffect } from 'react';
import { engineTelemetry, logEngineFallback } from '../utils/engineTelemetry';
import type { PyodideLike } from '../utils/pyodideBuffers';

const PYODIDE_BOOTSTRAP_TIMEOUT_MS = 180_000;

// This hook encapsulates the "Spectral Puppet" engine
export const usePyodideEngine = () => {
    // Check global state initially
    const [pyodide, setPyodide] = useState<PyodideLike | null>(
        (globalThis.hyphonPyodide as PyodideLike | undefined) ?? null,
    );
    const [isPyodideReady, setIsPyodideReady] = useState(!!globalThis.hyphonPyodideReady);
    const [pyodideStatus, setPyodideStatus] = useState(
        globalThis.hyphonPyodideReady ? 'Python Engine Ready!' : 'Waiting for C++ Orchestrator...'
    );

    useEffect(() => {
        if (isPyodideReady) return;

        const handleReady = () => {
            setPyodide(globalThis.hyphonPyodide as PyodideLike);
            setIsPyodideReady(true);
            setPyodideStatus('Python Engine Ready!');
            try { engineTelemetry.registerResolution('pyodide', 'pyodide', 'bootstrap-ready'); } catch (e) { /* noop */ }
        };

        const handleError = (ev: Event) => {
            const detail = (ev as CustomEvent<{ reason?: string; error?: string }>).detail;
            const reason = detail?.reason ?? 'hyphon-pyodide-error event';
            const err = detail?.error ? new Error(detail.error) : undefined;
            logEngineFallback('pyodide', 'pyodide', reason, err);
            setPyodideStatus(`Python engine failed: ${reason}`);
        };

        const timeoutId = window.setTimeout(() => {
            if (!globalThis.hyphonPyodideReady) {
                logEngineFallback(
                    'pyodide',
                    'pyodide',
                    `bootstrap timeout (${PYODIDE_BOOTSTRAP_TIMEOUT_MS}ms) — hyphon_native.js may not have loaded`,
                );
                setPyodideStatus('Python engine timed out (check hyphon_native.js + CDN)');
            }
        }, PYODIDE_BOOTSTRAP_TIMEOUT_MS);

        window.addEventListener('hyphon-pyodide-ready', handleReady);
        window.addEventListener('hyphon-pyodide-error', handleError);

        return () => {
            window.clearTimeout(timeoutId);
            window.removeEventListener('hyphon-pyodide-ready', handleReady);
            window.removeEventListener('hyphon-pyodide-error', handleError);
        };
    }, [isPyodideReady]);

    useEffect(() => {
        if (isPyodideReady) {
            try { engineTelemetry.registerResolution('pyodide','pyodide','ready'); } catch (e) { /* noop */ }
        }
    }, [isPyodideReady]);

    return { pyodide, isPyodideReady, pyodideStatus };
};

