    activeTrackSlotsRef: MutableRefObject<Record<TrackKey, number>>;
    songStructureRef: MutableRefObject<({ [key in TrackKey]: number | null })[]>;
    sessionDocumentRef?: MutableRefObject<import('../session/types').SessionDocument>;
