import { getWamHost } from '../audio/wam';

// Module-level scratch buffers for single-threaded main-thread use to avoid GC on hot path
const _midiScratch: number[] = [];
const _noteScratch: string[] = [];
const _liveValuesKeys: string[] = [];
const _liveValuesScratch: Record<string, number> = {};
const _continuousSamplerParams = new Set([
    'formantShift', 'vibratoRate', 'rootNote', 'coarseTune', 'fineTune',
    'pitchAttack', 'pitchDecay', 'vibratoDepth', 'tremoloDepth', 'breathAmount', 'characterMorph'
]);
const _schedulerLanesScratch: UnifiedAutomationLane[] = [];
const _bankParamsScratch: Partial<SamplerBankParams> = {};
const _chordScratch: string[] = [];

function applyInversion(notes: string | string[], inversionVal: number): string | string[] {
    const isArray = Array.isArray(notes);
    const len = isArray ? (notes as string[]).length : 1;
    if (len <= 1) return notes;

    const maxInversions = len - 1;
    const numInversions = Math.round(inversionVal * maxInversions);
    if (numInversions === 0) return notes;

    // Fill + convert in one pass (no .map allocation)
    _midiScratch.length = len;
    if (isArray) {
        for (let i = 0; i < len; i++) {
            _midiScratch[i] = noteToMidi((notes as string[])[i]);
        }
    } else {
        _midiScratch[0] = noteToMidi(notes as string);
    }

    // Sort ascending in place
    _midiScratch.sort((a, b) => a - b);

    // Rotate without shift() — O(n) total instead of O(n²)
    for (let inv = 0; inv < numInversions; inv++) {
        const lowest = _midiScratch[0];
        for (let i = 0; i < len - 1; i++) {
            _midiScratch[i] = _midiScratch[i + 1];
        }
        _midiScratch[len - 1] = lowest + 12;
    }

    // Convert back — return a fresh array so callers can keep it
    _noteScratch.length = len;
    for (let i = 0; i < len; i++) {
        _noteScratch[i] = midiToNote(_midiScratch[i]);
    }
    return _noteScratch;
}

export interface UseStepHandlerOptions {
    audioEngine: AudioEngine | null;
    tempo: number;
    onParamChange: ((bankIdx: number, key: keyof SamplerBankParams, value: number, rampTime?: number) => void) | undefined;
    currentStepRef: React.MutableRefObject<number>;
    sequencerRef: React.RefObject<MainSequencerHandle | null>;
    patternRef: React.MutableRefObject<Pattern>;
    lastFreqRef: React.MutableRefObject<Record<string, number>>;
    lastSamplerMidiRef: React.MutableRefObject<Record<number, number>>;
    lastSamplerFormantRef: React.MutableRefObject<Record<number, number>>;
    synthARef: React.MutableRefObject<SynthParams>;
    synthBRef: React.MutableRefObject<SynthParams>;
    bass2Ref: React.MutableRefObject<Bass2Params>;
    kickRef: React.MutableRefObject<any>;
    snareRef: React.MutableRefObject<any>;
    closedHatRef: React.MutableRefObject<any>;
    openHatRef: React.MutableRefObject<any>;
    currentScaleRef: React.MutableRefObject<ScaleDefinition | null>;
    samplerRef: React.MutableRefObject<SamplerParams>;
    samplerVoiceParamsRef: React.MutableRefObject<{
        drive: number;
        rootNote: number;
        coarseTune: number;
        fineTune: number;
        formantShift: number;
        attack: number;
        decay: number;
        stretchProfile: 'vocal' | 'harmonic' | 'fast';
        stretchMode: 'Time' | 'Pitch' | 'Formant';
        lockToSequencer: boolean;
        pan?: number;
    }>;
    activeSamplerBankRef: React.MutableRefObject<number>;
    sliceHighlightRef: React.MutableRefObject<((slice: number) => void) | null>;
    isSongModeActiveRef: React.MutableRefObject<boolean>;
    songStructureRef: React.MutableRefObject<({ [key in TrackKey]: number | null })[]>;
    songMeasureRef: React.MutableRefObject<number>;
    isFirstStepRef: React.MutableRefObject<boolean>;
    trackStorageRef: React.MutableRefObject<Record<TrackKey, (PartSequence | PartSequence[] | null)[]>>;
    setCurrentSongMeasure: (measure: number) => void;
    /** Optional automation scheduler for AudioParam-scheduled 303/synth automation. */
    automationSchedulerRef?: React.MutableRefObject<AutomationScheduler | null>;
    /** Resolved TRAK events from an imported RBS song for sub-step automation scheduling. */
    trakEventsRef?: React.MutableRefObject<ResolvedTrakEvent[] | null>;
    rbsArrangementExtrasRef?: React.MutableRefObject<import('./appState/useSongModeState').RbsArrangementExtras | null>;
    setSynthA?: React.Dispatch<React.SetStateAction<SynthParams>>;
    setSynthB?: React.Dispatch<React.SetStateAction<SynthParams>>;
    setBass2?: React.Dispatch<React.SetStateAction<Bass2Params>>;
    sessionEngineRef?: React.MutableRefObject<import('../session/SessionLaunchEngine').SessionLaunchEngine | null>;
    sessionClockRef?: React.MutableRefObject<{ step: number; audioTime: number; tempo: number }>;
    setIsSongModeActive?: (active: boolean) => void;
    onSessionTick?: (playing: Record<TrackKey, number | null>) => void;
}

export const useStepHandler = ({
    audioEngine,
    tempo,
    onParamChange,
    currentStepRef,
    sequencerRef,
    patternRef,
    lastFreqRef,
    lastSamplerMidiRef,
    lastSamplerFormantRef,
    synthARef,
    synthBRef,
    bass2Ref,
    kickRef,
    snareRef,
    closedHatRef,
    openHatRef,
    currentScaleRef,
    samplerRef,
    samplerVoiceParamsRef,
    activeSamplerBankRef,
    sliceHighlightRef,
    isSongModeActiveRef,
    songStructureRef,
    songMeasureRef,
    isFirstStepRef,
    trackStorageRef,
    setCurrentSongMeasure,
    automationSchedulerRef,
    trakEventsRef,
    rbsArrangementExtrasRef,
    setSynthA,
    setSynthB,
    setBass2,
    sessionEngineRef,
    sessionClockRef,
    setIsSongModeActive,
    onSessionTick,
}: UseStepHandlerOptions) => {
    const lastHandledStepRef = useRef({ step: -1, audioTime: 0 });
    const lastTrakBarRef = useRef(-1);
    const lastParamSlotsRef = useRef<{ partA: number | null; partB: number | null; bass2: number | null }>({
        partA: null, partB: null, bass2: null,
    });
    // Tracks the previous mute/solo audibility so a track that has just been
    // silenced flushes its voices exactly once instead of every step.
    const prevAudibleRef = useRef<Record<TrackKey, boolean>>({
        partA: true, partB: true, bass2: true, kick: true,
        snare: true, closedHat: true, openHat: true, sampler: true,
    });

    const onStep = useCallback((step: number, audioTime?: number) => {
        currentStepRef.current = step;
        automationStore.setPlaybackStep(step);
        if (isE2eMode()) setE2eTransportStep(step);
        if (sequencerRef.current) sequencerRef.current.setHighlight(step);
        if (!audioEngine) return;

        // Use the sample-accurate audioTime from the AudioWorklet clock when available.
        // This ensures notes are scheduled at the exact moment the step fires on the
        // audio thread, not at the moment the main-thread message is processed (~1-5ms later).
        const time = audioTime ?? audioEngine.context.currentTime;

        const lastHandled = lastHandledStepRef.current;
        if (
            step === lastHandled.step &&
            (time - lastHandled.audioTime) * 1000 < PLAYBACK_THRESHOLDS.stepDuplicateGuardMs
        ) {
            playbackHealthMonitor.recordStepBurst(step);
            return;
        }
        lastHandledStepRef.current = { step, audioTime: time };

        // Mute/solo: a track that has just been silenced releases its voices once.
        // Because a silenced track never triggers, it cannot accumulate notes.
        const prevAudible = prevAudibleRef.current;
        for (let i = 0; i < TRACK_KEYS.length; i++) {
            const key = TRACK_KEYS[i];
            const audible = trackMuteSoloStore.isAudible(key);
            if (prevAudible[key] && !audible) {
                audioEngine.stopTrackNotes?.(key);
                lastFreqRef.current[key] = 0;
            }
            prevAudible[key] = audible;
        }

        let activePattern = patternRef.current;

        if (sessionClockRef) {
            sessionClockRef.current = { step, audioTime: time, tempo };
        }
        const sessionEngine = sessionEngineRef?.current;
        if (sessionEngine) {
            const tick = sessionEngine.tick({
                step,
                audioTime: time,
                tempo,
                patternSteps: 32,
                stepsPerBeat: 4,
                stepsPerBar: 16,
                isPlaying: true,
                songModeActive: isSongModeActiveRef.current,
            });
            if (tick.preemptSongMode) setIsSongModeActive?.(false);
            for (const track of tick.flushTracks) {
                audioEngine.stopTrackNotes?.(track);
                lastFreqRef.current[track] = 0;
            }
            onSessionTick?.(sessionEngine.playingSlots());
            if (isE2eMode()) {
                let pCount = 0;
                for (let i = 0; i < TRACK_KEYS.length; i++) {
                    if (sessionEngine.playingSlot(TRACK_KEYS[i]) != null) {
                        pCount++;
                    }
                }
                setE2eSessionState({
                    playingCount: pCount,
                    lastApplyStep: tick.applied[0]?.step ?? (typeof window !== 'undefined' ? window.__HYPHON_E2E_SESSION__?.lastApplyStep ?? -1 : -1),
                    captureCount: sessionEngine.captureEvents.length,
                });
            }
        }

        // Session clip playback overlays the live pattern (stopped tracks are silent).
        if (sessionEngine?.hasPlaying()) {
            const slots = sessionEngine.playingSlots();
            const getSessionSeq = (key: TrackKey) => {
                const slot = slots[key];
                if (slot === null) return key === 'sampler' ? EMPTY_SAMPLER_SEQUENCE : EMPTY_SEQ;
                const stored = trackStorageRef.current[key][slot];
                return stored ?? (key === 'sampler' ? EMPTY_SAMPLER_SEQUENCE : EMPTY_SEQ);
            };
            activePattern = {
                partA: getSessionSeq('partA'),
                partB: getSessionSeq('partB'),
                bass2: getSessionSeq('bass2'),
                kick: getSessionSeq('kick'),
                snare: getSessionSeq('snare'),
                closedHat: getSessionSeq('closedHat'),
                openHat: getSessionSeq('openHat'),
                sampler: getSessionSeq('sampler'),
            } as Pattern;
        } else if (isSongModeActiveRef.current) {
            if (step === 0) {
                if (isFirstStepRef.current) {
                    isFirstStepRef.current = false;
                    lastTrakBarRef.current = -1;
                } else {
                    const nextM = songMeasureRef.current + 1;
                    songMeasureRef.current = nextM < songStructureRef.current.length ? nextM : 0;
                    requestAnimationFrame(() => setCurrentSongMeasure(songMeasureRef.current));
                }

                // Schedule sub-step trakEvents for the current bar (RBS imported songs).
                if (trakEventsRef?.current?.length && automationSchedulerRef?.current) {
                    const mIdx = songMeasureRef.current;
                    if (lastTrakBarRef.current !== mIdx) {
                        lastTrakBarRef.current = mIdx;
                        const fromTick = mIdx * TICKS_PER_BAR;
                        const toTick = fromTick + TICKS_PER_BAR;
                        automationSchedulerRef.current.scheduleFromTrakEvents(
                            trakEventsRef.current,
                            tempo,
                            time,
                            fromTick,
                            toTick,
                        );
                    }
                }
            }

            const currentMeasureIdx = songMeasureRef.current;
            const measureData = songStructureRef.current[currentMeasureIdx];

            if (measureData) {
                const getSeq = (key: TrackKey) => {
                    const slot = measureData[key];
                    if (slot === null) return key === 'sampler' ? EMPTY_SAMPLER_SEQUENCE : EMPTY_SEQ;
                    const stored = trackStorageRef.current[key][slot];
                    return stored ?? (key === 'sampler' ? EMPTY_SAMPLER_SEQUENCE : EMPTY_SEQ);
                };

                activePattern = {
                    partA: getSeq('partA'),
                    partB: getSeq('partB'),
                    bass2: getSeq('bass2'),
                    kick: getSeq('kick'),
                    snare: getSeq('snare'),
                    closedHat: getSeq('closedHat'),
                    openHat: getSeq('openHat'),
                    sampler: getSeq('sampler'),
                } as Pattern;

                const storage = rbsArrangementExtrasRef?.current?.trackParamStorage;
                if (storage) {
                    const open303 = audioEngine.open303Engine instanceof Open303Manager
                        ? audioEngine.open303Engine
                        : null;
                    const last = lastParamSlotsRef.current;
                    const recall = (track: 'partA' | 'partB' | 'bass2', slot: number | null) => {
                        if (slot === null || slot === last[track]) return;
                        last[track] = slot;
                        const applied = applyTrackParamSlotToEngine(
                            storage,
                            track,
                            slot,
                            open303,
                            {
                                synthA: synthARef.current,
                                synthB: synthBRef.current,
                                bass2: bass2Ref.current,
                            },
                        );
                        if (applied.synthA) {
                            synthARef.current = applied.synthA;
                            setSynthA?.(applied.synthA);
                        }
                        if (applied.synthB) {
                            synthBRef.current = applied.synthB;
                            setSynthB?.(applied.synthB);
                        }
                        if (applied.bass2) {
                            bass2Ref.current = applied.bass2;
                            setBass2?.(applied.bass2);
                        }
                    };
                    recall('partA', measureData.partA ?? null);
                    recall('partB', measureData.partB ?? null);
                    recall('bass2', measureData.bass2 ?? null);
                }
            }
        }

        const p = activePattern;
        const stepTime = 60 / tempo / 4;
        const currentScale = currentScaleRef.current;

        const triggerSynth = (trackKey: 'partA' | 'partB', params: SynthParams) => {
            if (!trackMuteSoloStore.isAudible(trackKey)) return;
            const stepData = p[trackKey].steps[step];
            if (!stepData) return;

            if (stepData.probability !== undefined && Math.random() > stepData.probability) return;

            let rawNotes: string | string[] = stepData.note;
            if (stepData.chord) {
                _chordScratch.length = 0;
                _chordScratch.push(stepData.note);
                for (let i = 0; i < stepData.chord.length; i++) {
                    _chordScratch.push(stepData.chord[i]);
                }
                rawNotes = _chordScratch;
            }
            const invVal = activePattern[trackKey].automation?.['chordInversion']?.[step] ?? 0;
            const notes = invVal > 0 ? applyInversion(rawNotes, invVal) : rawNotes;

            const slideFrom = stepData.slide && lastFreqRef.current[trackKey] > 0
                ? lastFreqRef.current[trackKey]
                : undefined;

            // Build per-step note params from stepData (including Prophecy params).
            // Note: previously `currentScale` was passed here but `SynthNoteParams` has no scale
            // properties — it was never consumed by createPlaySynth. Microtonal slide tracking
            // continues to use `tunedNoteToFrequency` below. VoiceManager handles scale tuning
            // independently when it plays the note string.
            const noteParams: SynthNoteParams = {};
            if (stepData.velocity !== undefined) noteParams.velocity = stepData.velocity;
            if (stepData.timbre !== undefined) noteParams.timbre = stepData.timbre;
            if (stepData.microtiming !== undefined) noteParams.microtiming = stepData.microtiming;
            if (stepData.retrigger !== undefined) noteParams.retrigger = stepData.retrigger;
            if (stepData.formantShift !== undefined) noteParams.formantShift = stepData.formantShift;
            if (stepData.reverbSend !== undefined) noteParams.reverbSend = stepData.reverbSend;
            if (stepData.reverbType !== undefined) noteParams.reverbType = stepData.reverbType;
            if (stepData.delaySend !== undefined) noteParams.delaySend = stepData.delaySend;
            if (stepData.vowel !== undefined) noteParams.vowel = stepData.vowel;
            if (stepData.portamento !== undefined) noteParams.portamento = stepData.portamento;
            if (stepData.drive !== undefined) noteParams.drive = stepData.drive;
            // Apply per-lane automation overrides for prophecy params
            const automation = activePattern[trackKey]?.automation;
            const autoVowel = automation?.['vowel']?.[step];
            if (autoVowel !== undefined && autoVowel !== null) noteParams.vowel = autoVowel;
            const autoPortamento = automation?.['portamento']?.[step];
            if (autoPortamento !== undefined && autoPortamento !== null) noteParams.portamento = autoPortamento;
            const autoFormantShift = automation?.['formantShift']?.[step];
            if (autoFormantShift !== undefined && autoFormantShift !== null) noteParams.formantShift = autoFormantShift;

            // Unified automation lanes (recorded + imported RBS) for filter cutoff/resonance on this synth track
            // These override per-step; values are already 0-1 normalized (playSynth scales to Hz/Q)
            const targetForLane: 'synthA' | 'synthB' = trackKey === 'partA' ? 'synthA' : 'synthB';
            const cutoffVal = getAutomationValue(targetForLane, 'filterCutoff', step);
            if (cutoffVal !== undefined) noteParams.filterCutoff = cutoffVal;
            const resVal = getAutomationValue(targetForLane, 'filterResonance', step);
            if (resVal !== undefined) noteParams.filterResonance = resVal;
            const driveVal = getAutomationValue(targetForLane, 'drive', step);
            if (driveVal !== undefined) noteParams.drive = driveVal;

            const durationSeconds = (stepData.length ?? 1) * stepTime;
            const wamHost = getWamHost();
            if (wamHost?.takesOverTrack(trackKey)) {
                const velocity = stepData.velocity ?? 1;
                wamHost.scheduleTrackNotes(trackKey, notes, time, durationSeconds, velocity);
            } else {
                audioEngine.playSynth(params, notes, time, stepData.length, stepTime, slideFrom, trackKey, currentScale, noteParams);
            }

            // Update last frequency for future slides
            lastFreqRef.current[trackKey] = tunedNoteToFrequency(stepData.note, currentScale);
        };

        // === Bass 2 (TB-303) ===
        const triggerBass2 = () => {
            if (!trackMuteSoloStore.isAudible('bass2')) return;
            const stepData = p.bass2.steps[step];
            if (!stepData) return;
            if (stepData.probability !== undefined && Math.random() > stepData.probability) return;

            let rawNotes: string | string[] = stepData.note;
            if (stepData.chord) {
                _chordScratch.length = 0;
                _chordScratch.push(stepData.note);
                for (let i = 0; i < stepData.chord.length; i++) {
                    _chordScratch.push(stepData.chord[i]);
                }
                rawNotes = _chordScratch;
            }
            const invVal = activePattern.bass2.automation?.['chordInversion']?.[step] ?? 0;
            const notes = invVal > 0 ? applyInversion(rawNotes, invVal) : rawNotes;

            const bass2Params: SynthParams = {
                waveform: bass2Ref.current.waveform,
                pitch: bass2Ref.current.pitch,
                filterCutoff: bass2Ref.current.cutoff,
                filterResonance: bass2Ref.current.resonance,
                filterMode: bass2Ref.current.filterMode,
                attack: 0.01,
                decay: bass2Ref.current.decay,
                sustain: 0,
                release: 0.1,
                length: (stepData.length ?? 1) * stepTime,
                volume: bass2Ref.current.volume,
                delayTime: 0,
                delayFeedback: 0,
                delayMix: 0,
                drive: bass2Ref.current.drive ?? 0,
            };

            if (audioEngine.open303Engine) {
                (audioEngine.open303Engine as any).applyBass2Params?.(bass2Ref.current);
            }

            // Bass2 filter automation from unified lanes (RBS tb303Bcutoff etc maps to bass2)
            const bass2NoteParams: any = {};
            if (stepData.drive !== undefined) bass2NoteParams.drive = stepData.drive;
            const b2Cutoff = getAutomationValue('bass2', 'filterCutoff', step);
            if (b2Cutoff !== undefined) bass2NoteParams.filterCutoff = b2Cutoff;
            const b2Res = getAutomationValue('bass2', 'filterResonance', step);
            if (b2Res !== undefined) bass2NoteParams.filterResonance = b2Res;
            const b2Drive = getAutomationValue('bass2', 'drive', step);
            if (b2Drive !== undefined) bass2NoteParams.drive = b2Drive;

            const wamBass = getWamHost();
            if (wamBass?.takesOverTrack('bass2')) {
                const durationSeconds = (stepData.length ?? 1) * stepTime;
                wamBass.scheduleTrackNotes('bass2', notes, time, durationSeconds, stepData.velocity ?? 1);
            } else {
                audioEngine.playSynth(bass2Params, notes, time, stepData.length, stepTime, undefined, 'bass2' as any, currentScale, bass2NoteParams.drive !== undefined || bass2NoteParams.filterCutoff !== undefined || bass2NoteParams.filterResonance !== undefined ? bass2NoteParams : undefined);
            }
        };

        // Trigger synths
        triggerSynth('partA', synthARef.current);
        triggerSynth('partB', synthBRef.current);
        triggerBass2();

        // === Drums ===
        const playDrumIfActive = (trackKey: 'kick' | 'snare' | 'closedHat' | 'openHat', sound: any, params: any) => {
            if (!trackMuteSoloStore.isAudible(trackKey)) return;
            const stepData = p[trackKey].steps[step];
            if (stepData && !(stepData.probability !== undefined && Math.random() > stepData.probability)) {
                audioEngine.playDrum(sound, params, time, currentScale, stepTime, stepData.note);
            }
        };

        playDrumIfActive('kick', 'kick', kickRef.current);
        playDrumIfActive('snare', 'snare', snareRef.current);
        playDrumIfActive('openHat', 'openHat', openHatRef.current);
        if (!p.openHat.steps[step]) {
            playDrumIfActive('closedHat', 'closedHat', closedHatRef.current);
        }

        // === Sampler ===
        // Track-level mute/solo only — per-bank muting is a separate concern.
        // ⚡ Bolt Optimization: Replacing forEach with for loop to prevent closure allocations on hot path
        const samplerAudible = trackMuteSoloStore.isAudible('sampler');
        for (let bankIdx = 0; samplerAudible && bankIdx < p.sampler.length; bankIdx++) {
            const seq = p.sampler[bankIdx];
            const stepData = seq.steps[step];
            if (!stepData) continue;
            if (stepData.probability !== undefined && Math.random() > stepData.probability) continue;

            const slideFromMidi = stepData.slide ? lastSamplerMidiRef.current[bankIdx] : undefined;
            const slideFromFormant = (stepData.slide || stepData.slideFormant) ? lastSamplerFormantRef.current[bankIdx] : undefined;

            let rawNotes: string | string[] = stepData.note;
            if (stepData.chord) {
                _chordScratch.length = 0;
                _chordScratch.push(stepData.note);
                for (let i = 0; i < stepData.chord.length; i++) {
                    _chordScratch.push(stepData.chord[i]);
                }
                rawNotes = _chordScratch;
            }

            // Lock to sequencer logic
            let finalNotes = rawNotes;
            const voiceParams = samplerVoiceParamsRef.current;
            if (voiceParams.lockToSequencer && typeof rawNotes === 'string') {
                let targetStep = -1;
                let firstActiveStep = -1;
                for (let i = 0; i < seq.steps.length; i++) {
                    if (seq.steps[i]) {
                        if (firstActiveStep === -1) firstActiveStep = i;
                        if (i >= step) {
                            targetStep = i;
                            break;
                        }
                    }
                }

                if (targetStep === -1 && firstActiveStep !== -1) {
                    targetStep = firstActiveStep;
                }

                if (targetStep !== -1) {
                    const targetData = seq.steps[targetStep];
                    if (targetData?.note) {
                        if (targetData.chord) {
                            _chordScratch.length = 0;
                            _chordScratch.push(targetData.note);
                            for (let i = 0; i < targetData.chord.length; i++) {
                                _chordScratch.push(targetData.chord[i]);
                            }
                            finalNotes = _chordScratch;
                        } else {
                            finalNotes = targetData.note;
                        }
                    }
                }
            }

            const baseSampler = samplerRef.current[bankIdx];
            const bankParams = Object.assign(_bankParamsScratch, baseSampler);
            bankParams.rootNote = voiceParams.rootNote;
            bankParams.coarseTune = voiceParams.coarseTune;
            bankParams.fineTune = voiceParams.fineTune;
            bankParams.pan = stepData.pan ?? voiceParams.pan;
            bankParams.formantShift = voiceParams.formantShift;
            bankParams.attack = voiceParams.attack;
            bankParams.decay = voiceParams.decay;
            bankParams.stretchProfile = voiceParams.stretchProfile;
            bankParams.stretchMode = voiceParams.stretchMode;
            bankParams.lockToSequencer = voiceParams.lockToSequencer;

            // Sampler track automation (filter, volume) from lanes - complements the Voice Designer ramping below
            const sampCutoff = getAutomationValue('sampler', 'filterCutoff', step);
            if (sampCutoff !== undefined) (bankParams as any).filterCutoff = Math.max(20, sampCutoff * 20000);
            const sampRes = getAutomationValue('sampler', 'filterResonance', step);
            if (sampRes !== undefined) (bankParams as any).filterResonance = sampRes * 20;
            const sampVol = getAutomationValue('sampler', 'volume', step);
            if (sampVol !== undefined) (bankParams as any).volume = sampVol;

            audioEngine.playSampler(bankParams as SamplerBankParams, finalNotes, time, stepData.length, stepTime, { ...stepData, slideFromMidi, slideFromFormant }, currentScale);

            lastSamplerMidiRef.current[bankIdx] = noteToMidi(stepData.note);
            lastSamplerFormantRef.current[bankIdx] = stepData.formantShift !== undefined ? stepData.formantShift : (voiceParams.formantShift || 0);
        }

        // Visual feedback for phoneme slices
        if (sliceHighlightRef.current && samplerRef.current[activeSamplerBankRef.current]?.sliceMode === 'phoneme') {
            // ... (your existing slice highlight logic - unchanged)
        }

        // === UNIFIED AUTOMATION PLAYBACK (builds on Issue #652 store) ===
        // Apply recorded/imported RBS/AI automation lanes with interpolation.
        // High-priority: Voice Designer params (formantShift, drive, attack, decay) via ramping path.
        // This enables full expressive RBS song playback with parameter movement.
        const autoState = automationStore.getState();
        const playbackEnabled = autoState.playbackEnabled;
        if (playbackEnabled && audioEngine) {
            const automationPatternIndex = isSongModeActiveRef.current ? (songMeasureRef.current % 8) : 0;
            const lanes = autoState.lanes;
            const rampDuration = Math.max(0.01, stepTime * 0.85);

            // Collect live values for UI display (keyed "target:parameter")
            const liveValues = _liveValuesScratch;
            let hasLiveValues = false;
            // Clear scratch object
            for (let i = 0; i < _liveValuesKeys.length; i++) {
                delete liveValues[_liveValuesKeys[i]];
            }
            _liveValuesKeys.length = 0;

            const schedulerLanes = _schedulerLanesScratch;
            schedulerLanes.length = 0;

            // First pass: collect scheduler lanes and evaluate active non-scheduler lanes without array methods
            for (let i = 0; i < lanes.length; i++) {
                const lane = lanes[i];
                if (!lane.enabled) continue;
                if (lane.scope === 'pattern' && lane.patternIndex !== automationPatternIndex) continue;

                const isSchedulerTarget = lane.target === 'synthA' || lane.target === 'synthB' || lane.target === 'bass2' || lane.target === 'master';

                if (automationSchedulerRef?.current && isSchedulerTarget) {
                    schedulerLanes.push(lane);
                    continue;
                }

                const normVal = automationStore.getValueAtStep(lane, step);
                if (normVal === null) continue;

                // Track for UI automation indicators
                const cacheKey = `${lane.target}:${lane.parameter}`;
                if (liveValues[cacheKey] === undefined) _liveValuesKeys.push(cacheKey);
                liveValues[cacheKey] = normVal;
                hasLiveValues = true;

                // Denormalize using originalRange if present (from RBS import), else heuristics for voice params
                let realVal = normVal;
                if (lane.originalRange && Array.isArray(lane.originalRange)) {
                    const [min, max] = lane.originalRange;
                    realVal = min + normVal * (max - min);
                } else if (lane.parameter === 'formantShift') {
                    realVal = (normVal - 0.5) * 2.0; // 0-1 -> -1..+1
                } else if (['drive', 'attack', 'decay', 'vibratoDepth', 'tremoloDepth', 'breathAmount', 'characterMorph'].includes(lane.parameter)) {
                    realVal = normVal; // assume 0-1 or pass-through
                }

                if (lane.target === 'sampler') {
                    if (!_continuousSamplerParams.has(lane.parameter)) continue;

                    if (audioEngine.updateSamplerVoiceParams) {
                        // Apply to the currently active sampler bank during playback (MVP; future: bank-specific lanes)
                        try {
                            audioEngine.updateSamplerVoiceParams(activeSamplerBankRef.current, lane.parameter, realVal);
                        } catch (e) {
                            // ignore per-param errors
                        }
                    } else if (onParamChange) {
                        // Fallback to singing voice path for formant etc if no direct sampler updater
                        try {
                            onParamChange(activeSamplerBankRef.current, lane.parameter as any, realVal, rampDuration);
                        } catch (e) {}
                    }
                }
            }

            // --- 303 / synth automation via AudioParam-aligned scheduler ---
            if (automationSchedulerRef?.current && schedulerLanes.length > 0) {
                automationSchedulerRef.current.scheduleFromLanes(
                    schedulerLanes,
                    step,
                    1,          // schedule one step ahead
                    stepTime,
                    time
                );
                // Collect live values from these lanes for UI indicators.
                for (let i = 0; i < schedulerLanes.length; i++) {
                    const lane = schedulerLanes[i];
                    const normVal = automationStore.getValueAtStep(lane, step);
                    if (normVal === null) continue;
                    const cacheKey = `${lane.target}:${lane.parameter}`;
                if (liveValues[cacheKey] === undefined) _liveValuesKeys.push(cacheKey);
                liveValues[cacheKey] = normVal;
                    hasLiveValues = true;
                }
            }

            // Notify UI with all live values in a single batched update (one re-render per step)
            if (hasLiveValues) {
                automationStore.setLiveValues(liveValues);
            }
        }
    }, [audioEngine, tempo, onParamChange, currentScaleRef, automationSchedulerRef, activeSamplerBankRef, bass2Ref, closedHatRef, currentStepRef, isFirstStepRef, isSongModeActiveRef, kickRef, lastFreqRef, lastSamplerFormantRef, lastSamplerMidiRef, onSessionTick, openHatRef, patternRef, rbsArrangementExtrasRef, samplerRef, samplerVoiceParamsRef, sequencerRef, sessionClockRef, sessionEngineRef, setBass2, setCurrentSongMeasure, setIsSongModeActive, setSynthA, setSynthB, sliceHighlightRef, snareRef, songMeasureRef, songStructureRef, synthARef, synthBRef, trackStorageRef, trakEventsRef]);

    return { onStep };
};

import { useCallback, useEffect, useState, useSyncExternalStore } from 'react';

export type SurfaceTexture = 'off' | 'grain' | 'circuit';

const STORAGE_KEY = 'hyphon-surface-texture';

const BODY_CLASSES: Record<SurfaceTexture, string> = {
  off: '',
  grain: 'hyphon-texture-grain',
  circuit: 'hyphon-texture-circuit',
};

function readStoredTexture(): SurfaceTexture {
  if (typeof localStorage === 'undefined') return 'off';
  const raw = localStorage.getItem(STORAGE_KEY);
  if (raw === 'grain' || raw === 'circuit') return raw;
  return 'off';
}

function applyBodyTexture(texture: SurfaceTexture) {
  if (typeof document === 'undefined') return;
  const body = document.body;
  body.classList.remove('hyphon-texture-grain', 'hyphon-texture-circuit');
  const cls = BODY_CLASSES[texture];
  if (cls) body.classList.add(cls);
}

let currentTexture: SurfaceTexture = readStoredTexture();
const listeners = new Set<() => void>();

function emitTextureChange() {
  listeners.forEach((l) => l());
}

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function getSnapshot(): SurfaceTexture {
  return currentTexture;
}

function setGlobalTexture(next: SurfaceTexture) {
  currentTexture = next;
  if (typeof localStorage !== 'undefined') {
    localStorage.setItem(STORAGE_KEY, next);
  }
  applyBodyTexture(next);
  emitTextureChange();
}

/** Optional film-grain / circuit overlay toggle (CSS-only, perf-conscious). */
export function useSurfaceTexture() {
  const texture = useSyncExternalStore(subscribe, getSnapshot, () => 'off' as SurfaceTexture);

  useEffect(() => {
    applyBodyTexture(texture);
  }, [texture]);

  const setTexture = useCallback((next: SurfaceTexture) => {
    setGlobalTexture(next);
  }, []);

  const cycleTexture = useCallback(() => {
    setGlobalTexture(texture === 'off' ? 'grain' : texture === 'grain' ? 'circuit' : 'off');
  }, [texture]);

  return { texture, setTexture, cycleTexture };
}

// hooks/useWebGPUScope.ts
import { useEffect, useRef } from 'react';
import type { SynthParams } from '../types';
import { noteToFrequency } from '../constants';
import { engineDegradationStore } from '../stores/engineDegradationStore';
import { probeWebGPU } from '../engines/backends/webgpuProbe';

// ---------------------------------------------------------
// 1. WGSL Shader Code
// ---------------------------------------------------------
const COMPUTE_SHADER_CODE = `
struct Params {
  waveform: u32,       // 0: saw, 1: square, 2: tri, 3: sine
  frequency: f32,      // normalized frequency for viz
  filterCutoff: f32,   // Hz value (typically 20–20000)
  sustain: f32,        // sustain level 0-1 (was filterRes)
  attack: f32,
  decay: f32,
  volume: f32,
  time: f32,           // animation time
}

struct Point {
  position: vec2<f32>,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> outputBuffer: array<Point>;

const PI: f32 = 3.14159265359;

// Helper: Basic Oscillators (matching WebGpuOscillator.ts for visual accuracy)
fn saw(t: f32) -> f32 { return 2.0 * fract(t) - 1.0; }
fn square(t: f32) -> f32 { return select(-1.0, 1.0, fract(t) < 0.5); }
fn tri(t: f32) -> f32 { return 2.0 * abs(2.0 * fract(t) - 1.0) - 1.0; }
fn sine(t: f32) -> f32 { return sin(2.0 * PI * t); }

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
  let index = global_id.x;
  let totalPoints = 1024u; // Must match WORKGROUP_SIZE * dispatch count

  if (index >= totalPoints) { return; }

  // Normalized X (0.0 to 1.0)
  let x = f32(index) / f32(totalPoints);

  // Calculate Waveform
  // We zoom out a bit to show a few cycles based on frequency
  let t = x * (1.0 + params.frequency * 10.0) + params.time; 

  var amplitude: f32 = 0.0;
  // Note: switch case works with u32 in WGSL
  switch (params.waveform) {
    case 0u: { amplitude = saw(t); }
    case 1u: { amplitude = square(t); }
    case 2u: { amplitude = tri(t); }
    case 3u: { amplitude = sine(t); }
    default: { amplitude = 0.0; }
  }

  // Simple Filter Simulation (Visual approximation)
  // Low cutoff blends signal towards sine; uses Hz value normalized by Nyquist (20 kHz)
  let cutoffFactor = clamp(params.filterCutoff / 20000.0, 0.0, 1.0);
  amplitude = mix(sine(t) * 0.5, amplitude, clamp(cutoffFactor * 2.0, 0.0, 1.0));

  // Envelope Simulation (Visual ADSR)
  // X axis represents time; each phase occupies a proportional segment
  var env: f32 = 0.0;
  let attackEnd = params.attack * 0.3;
  let decayEnd = attackEnd + params.decay * 0.25;
  let sustainEnd = decayEnd + 0.25; // fixed sustain window for display
  let sustainLevel = clamp(params.sustain, 0.0, 1.0);

  if (attackEnd > 0.0 && x < attackEnd) {
    env = x / attackEnd;
  } else if (x < decayEnd) {
    let decaySpan = decayEnd - attackEnd;
    env = select(1.0, 1.0 - ((x - attackEnd) / decaySpan) * (1.0 - sustainLevel), decaySpan > 0.0);
  } else if (x < sustainEnd) {
    env = sustainLevel;
  } else {
    // Release: fade from sustain to 0 over remaining x range
    let releaseSpan = 1.0 - sustainEnd;
    env = select(0.0, sustainLevel * (1.0 - (x - sustainEnd) / releaseSpan), releaseSpan > 0.0);
  }

  // Apply Volume and Envelope
  let y = amplitude * params.volume * env;

  // Write to Storage Buffer (Mapped to Vertex Shader input)
  // X range: -1 to 1, Y range: -1 to 1
  outputBuffer[index].position = vec2<f32>(x * 2.0 - 1.0, y * 0.9);
}
`;

const VERTEX_FRAGMENT_SHADER = `
struct Point {
  position: vec2<f32>,
}

@group(0) @binding(1) var<storage, read> inputBuffer: array<Point>;

struct VertexOutput {
  @builtin(position) Position : vec4<f32>,
  @location(0) color : vec4<f32>,
}

@group(0) @binding(2) var<uniform> accentColor: vec4<f32>;

@vertex
fn vs_main(@builtin(vertex_index) vertexIndex : u32) -> VertexOutput {
  let point = inputBuffer[vertexIndex];
  var output : VertexOutput;
  output.Position = vec4<f32>(point.position, 0.0, 1.0);
  output.color = accentColor; 
  return output;
}

@fragment
fn fs_main(@location(0) color : vec4<f32>) -> @location(0) vec4<f32> {
  return color;
}
`;

// ---------------------------------------------------------
// 2. The Hook
// ---------------------------------------------------------
export const useWebGPUScope = (
  canvasRef: React.RefObject<HTMLCanvasElement>,
  params: SynthParams,
  accentColor: 'cyan' | 'pink',
  initDelay: number = 0
) => {
  const deviceRef = useRef<GPUDevice | null>(null);
  const pipelineRef = useRef<GPUComputePipeline | null>(null);
  const renderPipelineRef = useRef<GPURenderPipeline | null>(null);
  const uniformBufferRef = useRef<GPUBuffer | null>(null);
  const storageBufferRef = useRef<GPUBuffer | null>(null);
  const accentColorBufferRef = useRef<GPUBuffer | null>(null);
  const bindGroupRef = useRef<GPUBindGroup | null>(null);
  const animationRef = useRef<number>(0);
  const startTimeRef = useRef<number>(0);

  // PERFORMANCE: Use refs to hold latest params/color to avoid re-running the effect loop
  // This allows the animation loop to persist while parameters update.
  const paramsRef = useRef(params);
  const accentColorRef = useRef(accentColor);

  const WORKGROUP_SIZE = 64;
  const NUM_POINTS = 1024;

  // Sync props to refs
  useEffect(() => {
    paramsRef.current = params;
    accentColorRef.current = accentColor;
  }, [params, accentColor]);

  useEffect(() => {
    let isCleanedUp = false;

    const initWebGPU = async () => {
      if (!canvasRef.current) return;

      const probe = await probeWebGPU();
      if (!probe.ok || !probe.device || isCleanedUp) {
        if (!probe.ok) {
          engineDegradationStore.report({
            id: 'webgpu-scope',
            subsystem: 'webgpu-scope',
            category: 'gpu',
            message: 'Oscilloscope using static fallback',
            reason: probe.reason ?? 'WebGPU unavailable',
            status: 'active',
            activeBackend: 'static',
            requestedBackend: 'webgpu',
            retryable: false,
          });
        }
        return;
      }
      const device = probe.device;
      deviceRef.current = device;

      const context = canvasRef.current.getContext('webgpu') as GPUCanvasContext | null;
      if (!context) return;

      const format = navigator.gpu?.getPreferredCanvasFormat?.() ?? 'bgra8unorm';
      context.configure({ device, format });

      // 1. Create Layouts & Pipelines
      const computeModule = device.createShaderModule({ code: COMPUTE_SHADER_CODE });
      const renderModule = device.createShaderModule({ code: VERTEX_FRAGMENT_SHADER });

      const bindGroupLayout = device.createBindGroupLayout({
        entries: [
          { binding: 0, visibility: GPUShaderStage.COMPUTE, buffer: { type: 'uniform' } },
          { binding: 1, visibility: GPUShaderStage.COMPUTE | GPUShaderStage.VERTEX, buffer: { type: 'storage' } },
          { binding: 2, visibility: GPUShaderStage.VERTEX, buffer: { type: 'uniform' } },
        ],
      });

      const pipelineLayout = device.createPipelineLayout({ bindGroupLayouts: [bindGroupLayout] });

      pipelineRef.current = device.createComputePipeline({
        layout: pipelineLayout,
        compute: { module: computeModule, entryPoint: 'main' },
      });

      renderPipelineRef.current = device.createRenderPipeline({
        layout: pipelineLayout,
        vertex: { module: renderModule, entryPoint: 'vs_main' },
        fragment: { module: renderModule, entryPoint: 'fs_main', targets: [{ format }] },
        primitive: { topology: 'line-strip' },
      });

      // 2. Create Buffers
      // Param Buffer: 32 bytes (8 floats/u32s) aligned
      uniformBufferRef.current = device.createBuffer({
        size: 32,
        usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
      });

      // Storage Buffer: 1024 points * 2 floats (vec2) * 4 bytes = 8192 bytes
      storageBufferRef.current = device.createBuffer({
        size: NUM_POINTS * 2 * 4,
        usage: GPUBufferUsage.STORAGE | GPUBufferUsage.VERTEX,
      });

      // Accent Color Buffer: 16 bytes (vec4)
      accentColorBufferRef.current = device.createBuffer({
        size: 16,
        usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
      });

      // 3. Create Bind Group
      bindGroupRef.current = device.createBindGroup({
        layout: bindGroupLayout,
        entries: [
          { binding: 0, resource: { buffer: uniformBufferRef.current } },
          { binding: 1, resource: { buffer: storageBufferRef.current } },
          { binding: 2, resource: { buffer: accentColorBufferRef.current } },
        ],
      });

      // ---------------------------------------------------------
      // 3. Render Loop
      // ---------------------------------------------------------
      const paramData = new Float32Array(8);
      const uintView = new Uint32Array(paramData.buffer);
      const colorDataCyan = new Float32Array([0.2, 0.9, 1.0, 1.0]);
      const colorDataPink = new Float32Array([1.0, 0.2, 0.8, 1.0]);

      const renderFrame = () => {
        if (isCleanedUp || !deviceRef.current) return;

        const device = deviceRef.current;
        const currentParams = paramsRef.current;
        const currentAccent = accentColorRef.current;

        // Map Waveform string to int
        // Handle other waveform types by defaulting to basic ones
        let waveIndex = 0;
        if (currentParams.waveform.includes('saw')) waveIndex = 0;
        else if (currentParams.waveform.includes('squ') || currentParams.waveform.includes('sqr')) waveIndex = 1;
        else if (currentParams.waveform.includes('tri')) waveIndex = 2;
        else if (currentParams.waveform.includes('sin')) waveIndex = 3;

        // Normalize frequency purely for visualization scale
        const freq = noteToFrequency('C4') / 1000.0;

        // WRITE PARAMS TO GPU
        // Structure must match WGSL struct Params exactly
        // slot 3: sustain level derived from volume (0-1 range) — filterResonance repurposed
        const sustainLevel = Math.max(0, Math.min(1, currentParams.volume));

        paramData[1] = freq;
        paramData[2] = currentParams.filterCutoff;
        paramData[3] = sustainLevel;
        paramData[4] = currentParams.attack;
        paramData[5] = currentParams.decay;
        paramData[6] = currentParams.volume;
        paramData[7] = (Date.now() - startTimeRef.current) / 1000.0;

        // Cast to uint32 for the first slot
        uintView[0] = waveIndex;

        // UPDATE ACCENT COLOR
        const colorData = currentAccent === 'cyan' ? colorDataCyan : colorDataPink;

        // Check refs before writing to avoid null access if something went wrong
        if (accentColorBufferRef.current) {
             device.queue.writeBuffer(accentColorBufferRef.current, 0, colorData);
        }
        if (uniformBufferRef.current) {
            device.queue.writeBuffer(uniformBufferRef.current, 0, paramData);
        }

        const commandEncoder = device.createCommandEncoder();

        // COMPUTE PASS
        const computePass = commandEncoder.beginComputePass();
        computePass.setPipeline(pipelineRef.current!);
        computePass.setBindGroup(0, bindGroupRef.current!);
        computePass.dispatchWorkgroups(Math.ceil(NUM_POINTS / WORKGROUP_SIZE));
        computePass.end();

        // RENDER PASS
        const textureView = context.getCurrentTexture().createView();
        const renderPass = commandEncoder.beginRenderPass({
          colorAttachments: [{
            view: textureView,
            clearValue: { r: 0.05, g: 0.05, b: 0.07, a: 1.0 }, // bg-gray-900 equivalent
            loadOp: 'clear',
            storeOp: 'store',
          }],
        });

        renderPass.setPipeline(renderPipelineRef.current!);
        renderPass.setBindGroup(0, bindGroupRef.current!);
        renderPass.draw(NUM_POINTS);
        renderPass.end();

        device.queue.submit([commandEncoder.finish()]);
        animationRef.current = requestAnimationFrame(renderFrame);
      };

      startTimeRef.current = Date.now();
      renderFrame();
    };

    // Use setTimeout to stagger WebGPU initialization between components
    const initTimeoutId = setTimeout(() => {
      void initWebGPU();
    }, initDelay);

    return () => {
      // cleanup
      isCleanedUp = true;
      clearTimeout(initTimeoutId);
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
      deviceRef.current = null;
    };
  }, [initDelay, canvasRef]);
};

import type {
  SavedSongData, Pattern, PartSequence, Note, SynthParams, Bass2Params,
  SamplerParams, AutomationPoint, UnifiedAutomationLane, AutomationTarget
} from '../../types';
import { generateLaneId } from '../../stores/automationStore';
import { AISongStorage, type AISongUploadOptions, type AISongMetadata } from '../../services/AISongStorage';
import { validateAISongData } from './types';
import {
  type AISongData, type AIImportResultType, type AIAutomationTarget,
  type AIInterpolationMode, type AITrackData, type AISamplerBankData,
  type AIHarmonizerConfig, type AIPhonemePainterConfig, type AIUploadResultType
} from './types';

/** Time signature applied when a song does not declare one. */
const DEFAULT_TIME_SIGNATURE: [number, number] = [4, 4];

/** Swing applied when a song does not declare one (50 = straight). */
const DEFAULT_SWING = 50;

export function isValidNote(note: string): boolean {
  return /^[A-G][#b]?[0-8]$/.test(note);
}

// ============================================================================
// CONVERTER CLASS
// ============================================================================

/**
 * AI Song Importer
 * 
 * Usage:
 * ```typescript
 * const importer = new AISongImporter();
 * const result = importer.convert(aiSongData);
 * if (result.success) {
 *   loadSong(result.song);
 * }
 * 
 * // Upload to cloud
 * const uploadResult = await importer.uploadToCloud(aiSongData, result.song);
 * if (uploadResult.success) {
 *   console.log('Uploaded:', uploadResult.publicUrl);
 * }
 * ```
 */
export class AISongImporter {
  private warnings: string[] = [];
  private mappedParams: Array<{ source: string; target: string; value: unknown }> = [];

  /**
   * Main entry point: convert AISongData to SavedSongData
   * 
   * @param aiSong - The AI-generated song data
   * @returns AIImportResultType with converted song or error details
   */
  convert(aiSong: AISongData): AIImportResultType {
    this.warnings = [];
    this.mappedParams = [];

    // Validate input
    const validation = validateAISongData(aiSong);
    if (!validation.valid) {
      return { success: false, error: validation.error };
    }

    try {
      // Convert pattern
      const pattern = this.convertPattern(aiSong);

      // Convert params
      const params = this.convertParams(aiSong);

      // Convert automation lanes into the unified store format
      const automationLanes = this.buildAutomationLanes(aiSong);

      // Build SavedSongData
      const song: SavedSongData = {
        version: 1,
        pattern,
        params,
        trackStorage: this.generateTrackStorage(pattern),
        activeTrackSlots: { partA: 0, partB: 0, bass2: 0, kick: 0, snare: 0, closedHat: 0, openHat: 0, sampler: 0 },
        songStructure: [],
        tempo: aiSong.globals.tempo,
        timeSignature: aiSong.globals.timeSignature ?? DEFAULT_TIME_SIGNATURE,
        swing: aiSong.globals.swing ?? DEFAULT_SWING,
        ambianceUrl: '',
        backgroundImage: '',
        ...(automationLanes.length > 0 ? { automationLanes } : {})
      };

      // Count converted elements
      const notesConverted = this.countNotes(aiSong);

      return {
        success: true,
        song,
        report: {
          tracksConverted: Object.keys(aiSong.tracks).length,
          notesConverted,
          warnings: this.warnings,
          mappedParams: this.mappedParams
        }
      };

    } catch (error) {
      return {
        success: false,
        error: {
          type: 'CONVERSION_ERROR',
          track: 'unknown',
          details: error instanceof Error ? error.message : 'Unknown conversion error'
        }
      };
    }
  }

  /**
   * Convert AI tracks to Hyphon Pattern
   */
  private convertPattern(aiSong: AISongData): Pattern {
    const numSteps = 32; // Hyphon uses 32 steps

    // Convert synth tracks
    const partA = aiSong.tracks.synthA 
      ? this.convertAITrack(aiSong.tracks.synthA, numSteps, 'synthA')
      : { steps: Array(numSteps).fill(null) };

    const partB = aiSong.tracks.synthB
      ? this.convertAITrack(aiSong.tracks.synthB, numSteps, 'synthB')
      : { steps: Array(numSteps).fill(null) };

    const bass2 = aiSong.tracks.bass2
      ? this.convertAITrack(aiSong.tracks.bass2, numSteps, 'bass2')
      : { steps: Array(numSteps).fill(null) };

    // Convert drum tracks
    const kick = this.convertDrumPattern(aiSong.tracks.kick, numSteps, 'C2');
    const snare = this.convertDrumPattern(aiSong.tracks.snare, numSteps, 'D2');
    const closedHat = this.convertDrumPattern(aiSong.tracks.closedHat, numSteps, 'F#2');
    const openHat = this.convertDrumPattern(aiSong.tracks.openHat, numSteps, 'A#2');

    // Convert sampler to PartSequence[] for Pattern
    const sampler = this.convertSamplerToSequences(aiSong.tracks.sampler, numSteps);

    return { partA, partB, bass2, kick, snare, closedHat, openHat, sampler };
  }

  /**
   * Convert AI track data to PartSequence
   */
  private convertAITrack(trackData: AITrackData, numSteps: number, trackName: string): PartSequence {
    const steps: (Note | null)[] = Array(numSteps).fill(null);

    for (const event of trackData.notes) {
      if (event.step < 0 || event.step >= numSteps) {
        this.warnings.push(`Note step ${event.step} out of range in ${trackName}`);
        continue;
      }

      if (!isValidNote(event.note)) {
        this.warnings.push(`Invalid note "${event.note}" in ${trackName}`);
        continue;
      }

      steps[event.step] = {
        note: event.note,
        velocity: event.velocity ?? 0.8,
        length: event.length ?? 1,
        slide: event.slide,
        timbre: event.accent ? 1.0 : 0.5
      };
    }

    return { steps };
  }

  /**
   * Convert boolean drum pattern to PartSequence
   */
  private convertDrumPattern(pattern: boolean[] | undefined, numSteps: number, defaultNote: string): PartSequence {
    const steps: (Note | null)[] = Array(numSteps).fill(null);

    if (!pattern) {
      return { steps };
    }

    // Extend 16-step patterns to 32 by duplicating
    const extendedPattern = pattern.length === 16 && numSteps === 32
      ? [...pattern, ...pattern]
      : pattern;

    for (let i = 0; i < extendedPattern.length && i < numSteps; i++) {
      if (extendedPattern[i]) {
        steps[i] = {
          note: defaultNote,
          velocity: 1.0,
          length: 1,
          timbre: 0.5
        };
      }
    }

    return { steps };
  }

  /**
   * Convert sampler bank data to PartSequence[] for Pattern
   */
  private convertSamplerToSequences(banks: AISamplerBankData[] | undefined, numSteps: number): PartSequence[] {
    // Create 8 sampler sequences (one per bank)
    const sequences: PartSequence[] = Array(8).fill(null).map(() => ({
      steps: Array(numSteps).fill(null) as (Note | null)[]
    }));

    if (!banks) {
      return sequences;
    }

    for (const bank of banks) {
      if (bank.bankIndex < 0 || bank.bankIndex > 7) {
        this.warnings.push(`Sampler bank index ${bank.bankIndex} out of range`);
        continue;
      }

      // Convert steps
      const steps: (Note | null)[] = Array(numSteps).fill(null);
      for (const event of bank.steps) {
        if (event.step >= 0 && event.step < numSteps) {
          steps[event.step] = {
            note: event.note,
            velocity: event.velocity ?? 0.8,
            length: event.length ?? 1
          };
        }
      }

      sequences[bank.bankIndex] = { steps };
    }

    return sequences;
  }

  /**
   * Convert sampler bank data to SamplerParams for SavedSongData['params']
   */
  private convertSamplerTracks(banks: AISamplerBankData[] | undefined): SamplerParams {
    const sampler: SamplerParams = Array.from({ length: 8 }, () => ({
      sampleName: 'empty',
      playbackSpeed: 1.0,
      volume: 1.0,
      filterCutoff: 20000,
      filterResonance: 0,
      drive: 0,
      delaySend: 0
    }));

    if (!banks) {
      return sampler;
    }

    for (const bank of banks) {
      if (bank.bankIndex < 0 || bank.bankIndex > 7) {
        this.warnings.push(`Sampler bank index ${bank.bankIndex} out of range`);
        continue;
      }

      // Note steps live on the Pattern (see convertSamplerToSequences);
      // SamplerBankParams carries voice settings only.
      sampler[bank.bankIndex] = {
        ...sampler[bank.bankIndex],
        ...bank.params,
        sampleName: bank.ttsText || bank.sampleUrl || `bank_${bank.bankIndex}`
      };
    }

    return sampler;
  }

  /**
   * Convert AI params to Hyphon params
   */
  private convertParams(aiSong: AISongData): SavedSongData['params'] {
    const defaultSynth: SynthParams = {
      waveform: '303-saw',
      pitch: 0,
      filterCutoff: 3000,
      filterResonance: 8,
      filterMode: 1,
      attack: 0.01,
      decay: 0.3,
      sustain: 0.5,
      release: 0.3,
      length: 0.25,
      volume: 0.9,
      delayTime: 0.3,
      delayFeedback: 0.2,
      delayMix: 0.0
    };

    const mapSynthParams = (trackData?: AITrackData): SynthParams => {
      if (!trackData?.params) return defaultSynth;

      this.mappedParams.push({
        source: 'AI.params',
        target: 'SynthParams',
        value: trackData.params
      });

      return { ...defaultSynth, ...trackData.params };
    };

    const mapBass2Params = (trackData?: AITrackData): Bass2Params => {
      const synth = mapSynthParams(trackData);
      return {
        waveform: synth.waveform === '303-sqr' ? '303-sqr' : '303-saw',
        pitch: synth.pitch,
        cutoff: synth.filterCutoff,
        resonance: synth.filterResonance,
        filterMode: synth.filterMode ?? 1,
        decay: synth.decay,
        accent: 0.7,
        envMod: 0.5,
        volume: synth.volume
      };
    };

    return {
      synthA: mapSynthParams(aiSong.tracks.synthA),
      synthB: mapSynthParams(aiSong.tracks.synthB),
      bass2: mapBass2Params(aiSong.tracks.bass2),
      kick: { pitch: 60, decay: 0.4, tone: 0.6, volume: 1.0 },
      snare: { decay: 0.3, tone: 250, noise: 3000, volume: 0.9 },
      closedHat: { pitch: 10000, decay: 0.1, volume: 0.8 },
      openHat: { pitch: 8000, decay: 0.4, volume: 0.8 },
      sampler: this.convertSamplerTracks(aiSong.tracks.sampler)
    };
  }

  /**
   * Generate track storage from pattern
   */
  private generateTrackStorage(pattern: Pattern): Record<string, unknown> {
    return {
      partA: Array(8).fill(null).map((_, i) => i === 0 ? pattern.partA : null),
      partB: Array(8).fill(null).map((_, i) => i === 0 ? pattern.partB : null),
      bass2: Array(8).fill(null).map((_, i) => i === 0 ? pattern.bass2 : null),
      kick: Array(8).fill(null).map((_, i) => i === 0 ? pattern.kick : null),
      snare: Array(8).fill(null).map((_, i) => i === 0 ? pattern.snare : null),
      closedHat: Array(8).fill(null).map((_, i) => i === 0 ? pattern.closedHat : null),
      openHat: Array(8).fill(null).map((_, i) => i === 0 ? pattern.openHat : null),
      sampler: Array(8).fill(null).map((_, i) => i === 0 ? pattern.sampler : null)
    };
  }

  /**
   * Count total notes in AI song
   */
  private countNotes(aiSong: AISongData): number {
    let count = 0;
    if (aiSong.tracks.synthA) count += aiSong.tracks.synthA.notes.length;
    if (aiSong.tracks.synthB) count += aiSong.tracks.synthB.notes.length;
    if (aiSong.tracks.bass2) count += aiSong.tracks.bass2.notes.length;
    if (aiSong.tracks.sampler) {
      for (const bank of aiSong.tracks.sampler) {
        count += bank.steps.length;
      }
    }
    return count;
  }

  /**
   * Convert AI automation lanes to Hyphon automation format.
   * 
   * Maps per-step automation values to the Hyphon automation system.
   * Each non-null step value creates an automation point.
   * 
   * @param aiSong - The AI song data containing automation lanes
   * @returns Array of KnobAutomation-compatible objects for Hyphon
   * 
   * @example
   * ```typescript
   * const automation = this.convertAutomation(aiSong);
   * // Returns: [{ paramId: 'filterCutoff', trackKey: 'partA', points: [...], isRecording: false }]
   * ```
   */
  convertAutomation(aiSong: AISongData): Array<{
    paramId: string;
    target: AIAutomationTarget;
    trackKey: string;
    points: AutomationPoint[];
    isRecording: boolean;
    interpolation: AIInterpolationMode;
  }> {
    if (!aiSong.automation || aiSong.automation.length === 0) {
      return [];
    }

    const results: ReturnType<typeof this.convertAutomation> = [];

    for (const lane of aiSong.automation) {
      // Map AI target to Hyphon track key
      const trackKey = this.mapAutomationTargetToTrackKey(lane.target);

      // Convert steps to automation points
      const points: AutomationPoint[] = [];

      for (let step = 0; step < lane.steps.length; step++) {
        const value = lane.steps[step];
        if (value !== null) {
          // Convert 0-127 to 0-1 range for Hyphon.
          // AutomationLanePoint.value is normalized to [0, 1] for every lane
          // source; clamp so a lane can never break that invariant.
          points.push({
            step,
            value: Math.max(0, Math.min(1, value / 127))
          });
        }
      }

      // Only add if we have automation points
      if (points.length > 0) {
        results.push({
          paramId: lane.parameter,
          target: lane.target,
          trackKey,
          points,
          isRecording: false,
          interpolation: lane.interpolation || 'step'
        });

        this.mappedParams.push({
          source: `automation.${lane.target}.${lane.parameter}`,
          target: `${trackKey}.${lane.parameter}`,
          value: `${points.length} points`
        });
      }
    }

    return results;
  }

  /**
   * Build store-ready automation lanes from the AI song.
   *
   * Wraps {@link convertAutomation} in the `UnifiedAutomationLane` shape that
   * `SavedSongData.automationLanes` carries, so lanes survive the save/load
   * round trip and reach `automationStore.importLanes` on import.
   *
   * The AI target vocabulary (`synthA`, `master`, …) is already the
   * `AutomationTarget` vocabulary, so targets pass through unmapped — the
   * `partA`/`partB` track keys from {@link mapAutomationTargetToTrackKey} are
   * for the legacy KnobAutomation shape, not for the store.
   *
   * @param aiSong - The AI song data containing automation lanes
   * @returns Lanes whose point values are normalized to [0, 1]
   */
  private buildAutomationLanes(aiSong: AISongData): UnifiedAutomationLane[] {
    return this.convertAutomation(aiSong).map((converted) => ({
      id: generateLaneId(),
      target: converted.target as AutomationTarget,
      parameter: converted.paramId,
      name: `${converted.target} ${converted.paramId}`,
      points: converted.points.map((point) => ({ step: point.step, value: point.value })),
      interpolation: converted.interpolation,
      source: 'ai' as const,
      scope: 'song' as const,
      enabled: true,
      // Display metadata only: the AI format expresses lane values as MIDI
      // 0-127, while `points[].value` above is already normalized.
      originalRange: [0, 127] as [number, number],
    }));
  }

  /**
   * Map AI automation target to Hyphon track key
   * @param target - AI automation target
   * @returns Hyphon track key
   */
  private mapAutomationTargetToTrackKey(target: AIAutomationTarget): string {
    const mapping: Record<AIAutomationTarget, string> = {
      synthA: 'partA',
      synthB: 'partB',
      bass2: 'bass2',
      kick: 'kick',
      snare: 'snare',
      closedHat: 'closedHat',
      openHat: 'openHat',
      sampler: 'sampler',
      master: 'master'
    };
    return mapping[target];
  }

  /**
   * Get automation summary for display purposes.
   * Returns a human-readable summary of automation lanes.
   * 
   * @param aiSong - The AI song data
   * @returns Summary object with lane count and details
   */
  getAutomationSummary(aiSong: AISongData): {
    laneCount: number;
    lanes: Array<{
      target: string;
      parameter: string;
      pointCount: number;
      interpolation: AIInterpolationMode;
    }>;
  } {
    if (!aiSong.automation) {
      return { laneCount: 0, lanes: [] };
    }

    return {
      laneCount: aiSong.automation.length,
      lanes: aiSong.automation.map(lane => ({
        target: lane.target,
        parameter: lane.parameter,
        pointCount: lane.steps.filter(s => s !== null).length,
        interpolation: lane.interpolation || 'step'
      }))
    };
  }

  /**
   * Convert harmonizer configuration
   */
  convertHarmonizer(trackData: AITrackData): AIHarmonizerConfig | null {
    if (!trackData.harmonizer?.enabled) {
      return null;
    }

    const config = trackData.harmonizer;

    // Validate and clamp values
    return {
      enabled: true,
      voices: this.validateHarmonizerVoices(config.voices),
      harmonyType: config.harmonyType,
      intervals: config.intervals,
      formantShift: this.clamp(config.formantShift, -12, 12),
      detune: this.clamp(config.detune, -50, 50),
      spread: this.clamp(config.spread, 0, 100)
    };
  }

  /**
   * Convert phoneme painter configuration
   */
  convertPhonemePainter(bankData: AISamplerBankData): AIPhonemePainterConfig | null {
    if (!bankData.phonemePainter?.enabled) {
      return null;
    }

    const config = bankData.phonemePainter;

    // Validate mappings
    const validMappings = config.mapping.filter(m => 
      typeof m.step === 'number' && 
      m.step >= 0 && 
      m.step < 32 &&
      typeof m.phoneme === 'string' &&
      m.phoneme.length > 0
    );

    if (validMappings.length === 0) {
      this.warnings.push(`Phoneme painter enabled but no valid mappings for bank ${bankData.bankIndex}`);
      return null;
    }

    return {
      enabled: true,
      text: config.text,
      phonemes: config.phonemes,
      mapping: validMappings
    };
  }

  // ============================================================================
  // VALIDATION HELPERS
  // ============================================================================

  private clamp(value: number, min: number, max: number): number {
    return Math.max(min, Math.min(max, value));
  }

  private validateHarmonizerVoices(voices: number): 2 | 3 | 4 {
    if (voices === 2 || voices === 3 || voices === 4) {
      return voices;
    }
    return 3; // Default to 3 voices
  }

  /**
   * Upload AI song to Hugging Face storage using AISongStorage
   * 
   * @param aiSong - Original AI song data
   * @param hyphonSong - Converted Hyphon song data
   * @param options - Optional upload options (folder, tags)
   * @returns AIUploadResultType with upload metadata or error
   * 
   * @example
   * ```typescript
   * const result = await importer.uploadToCloud(aiData, hyphonSong, {
   *   folder: 'my-songs',
   *   tags: ['funky', 'bass']
   * });
   * 
   * if (result.success) {
   *   console.log('Uploaded:', result.publicUrl);
   * } else {
   *   console.error('Upload failed:', result.error);
   *   if (result.error.storageError?.retryable) {
   *     // Can retry
   *   }
   * }
   * ```
   */
  async uploadToCloud(
    aiSong: AISongData,
    hyphonSong: SavedSongData,
    options?: AISongUploadOptions
  ): Promise<AIUploadResultType> {
    console.log('[AISongImporter] Uploading to cloud storage...');

    const result = await AISongStorage.uploadAISong(aiSong, hyphonSong, options);

    if (!result.success || !result.data) {
      console.error('[AISongImporter] Upload failed:', result.error);
      return {
        success: false,
        error: {
          type: 'STORAGE_ERROR',
          message: result.error?.message || 'Upload failed',
          storageError: result.error
        }
      };
    }

    console.log('[AISongImporter] Upload successful:', result.data.id);

    // Fetch metadata for the uploaded song
    const metadataResult = await AISongStorage.getAISong(result.data.id);

    return {
      success: true,
      id: result.data.id,
      url: result.data.url,
      publicUrl: result.data.publicUrl,
      timestamp: result.data.timestamp,
      version: result.data.version,
      generator: result.data.generator,
      metadata: metadataResult.success && metadataResult.data 
        ? metadataResult.data.metadata 
        : {
            id: result.data.id,
            name: aiSong.meta.title,
            author: aiSong.meta.author,
            date: result.data.timestamp,
            type: 'ai-generated',
            generator: result.data.generator,
            prompt: aiSong.meta.prompt,
            version: result.data.version,
            aiTags: [result.data.generator, 'ai-generated', ...(aiSong.meta.tags || [])]
          }
    };
  }

  /**
   * Check for duplicate songs before uploading
   * 
   * @param aiSong - AI song data to check
   * @returns Whether a duplicate exists and its ID
   * 
   * @example
   * ```typescript
   * const duplicate = await importer.checkDuplicate(aiSong);
   * if (duplicate.exists) {
   *   // Prompt user to overwrite or create new version
   * }
   * ```
   */
  async checkDuplicate(aiSong: AISongData): Promise<{ exists: boolean; id?: string; song?: AISongMetadata }> {
    const result = await AISongStorage.checkDuplicate(aiSong.meta.title, aiSong.meta.author);

    if (result.success && result.data) {
      return {
        exists: result.data.exists,
        id: result.data.id,
        song: result.data.song
      };
    }

    return { exists: false };
  }

  /**
   * Get import warnings from the last conversion
   */
  getWarnings(): string[] {
    return [...this.warnings];
  }

  /**
   * Get mapped params from the last conversion
   */
  getMappedParams(): Array<{ source: string; target: string; value: unknown }> {
    return [...this.mappedParams];
  }
}

/**
 * Convenience function for direct conversion
 * 
 * @param aiSong - AI-generated song data
 * @returns Conversion result with Hyphon song or error
 * 
 * @example
 * ```typescript
 * const result = convertAISong(aiData);
 * if (result.success) {
 *   loadSong(result.song);
 * }
 * ```
 */
export function convertAISong(aiSong: AISongData): AIImportResultType {
  const importer = new AISongImporter();
  return importer.convert(aiSong);
}

/**
 * Parse and validate JSON string
 * 
 * @param jsonString - JSON string to parse
 * @returns Parse result with AISongData or error message
 * 
 * @example
 * ```typescript
 * const parsed = parseAISongJSON(jsonString);
 * if (parsed.success) {
 *   const result = convertAISong(parsed.data);
 * }
 * ```
 */
export function parseAISongJSON(jsonString: string): { 
  success: true; 
  data: AISongData 
} | { 
  success: false; 
  error: string 
} {
  try {
    const parsed = JSON.parse(jsonString);
    return { success: true, data: parsed };
  } catch (error) {
    return { 
      success: false, 
      error: `Invalid JSON: ${error instanceof Error ? error.message : 'Parse error'}` 
    };
  }
}

/**
 * Upload AI song directly without conversion
 * 
 * @param aiSong - Original AI song data
 * @param hyphonSong - Converted Hyphon song data
 * @param options - Upload options
 * @returns Upload result with metadata
 * 
 * @example
 * ```typescript
 * const result = await uploadAISong(aiData, hyphonData);
 * if (result.success) {
 *   console.log('Public URL:', result.publicUrl);
 * }
 * ```
 */
export async function uploadAISong(
  aiSong: AISongData,
  hyphonSong: SavedSongData,
  options?: AISongUploadOptions
): Promise<AIUploadResultType> {
  const importer = new AISongImporter();
  return importer.uploadToCloud(aiSong, hyphonSong, options);
}

export default AISongImporter;

/**
 * Automation Lane Support for AI Song Importer
 *
 * Handles conversion, validation, and manipulation of automation lanes
 * from AI-generated song data.
 *
 * @example
 * ```typescript
 * import { validateAutomation, convertAutomationToPoints } from './automation';
 *
 * // Validate automation lanes
 * const result = validateAutomation(aiSong.automation, aiSong.tracks);
 * if (!result.valid) {
 *   console.error(result.error);
 * }
 *
 * // Convert to Hyphon format
 * const points = convertAutomationToPoints(automationLane);
 * ```
 */

import type { 
  AIAutomationLane, 
  AIAutomationTarget, 
  AITargetedParameter, 
  AIInterpolationMode,
  AISongData 
} from './types';
import type { AutomationPoint } from '../../types';

// ============================================================================
// CONSTANTS
// ============================================================================

/** Valid automation targets */
export const VALID_AUTOMATION_TARGETS: readonly AIAutomationTarget[] = [
  'synthA', 'synthB', 'bass2', 'kick', 'snare', 
  'closedHat', 'openHat', 'sampler', 'master'
] as const;

/** Valid parameters for each target */
export const VALID_PARAMETERS_BY_TARGET: Readonly<Record<AIAutomationTarget, readonly AITargetedParameter[]>> = {
  synthA: ['filterCutoff', 'filterResonance', 'filterMode', 'decay', 'accent', 'envMod', 'waveform', 'pitch', 'volume', 'drive', 'delayTime', 'delayFeedback', 'delayMix'],
  synthB: ['filterCutoff', 'filterResonance', 'filterMode', 'decay', 'accent', 'envMod', 'waveform', 'pitch', 'volume', 'drive', 'delayTime', 'delayFeedback', 'delayMix'],
  bass2: ['filterCutoff', 'filterResonance', 'filterMode', 'decay', 'accent', 'envMod', 'waveform', 'pitch', 'volume', 'drive'],
  kick: ['pitch', 'decay', 'tone', 'volume'],
  snare: ['decay', 'tone', 'noise', 'volume'],
  closedHat: ['pitch', 'decay', 'volume'],
  openHat: ['pitch', 'decay', 'volume'],
  sampler: ['filterCutoff', 'filterResonance', 'drive', 'volume', 'playbackSpeed', 'pitch'],
  master: ['tempo', 'swing', 'masterVolume']
} as const;

/** Valid interpolation modes */
export const VALID_INTERPOLATION_MODES: readonly AIInterpolationMode[] = ['step', 'linear', 'smooth'] as const;

/** Default pattern length for Hyphon */
export const DEFAULT_PATTERN_LENGTH = 32;

/** MIDI value range for automation (0-127) */
export const MIDI_VALUE_RANGE = { min: 0, max: 127 } as const;

// ============================================================================
// VALIDATION
// ============================================================================

/**
 * Validation error details
 */
export interface AutomationValidationError {
  type: 'VALIDATION_ERROR';
  field: string;
  message: string;
}

/**
 * Validation result type
 */
export type AutomationValidationResult = 
  | { valid: true }
  | { valid: false; error: AutomationValidationError };

/**
 * Validate automation lanes against the AISongData schema.
 * 
 * Checks:
 * - Automation is an array
 * - Each lane has valid target and parameter
 * - Step count matches pattern length
 * - Step values are in valid range (0-127 or null)
 * - Interpolation mode is valid
 * 
 * @param automation - Array of automation lanes to validate
 * @param tracks - Tracks object to determine pattern length
 * @returns Validation result
 * 
 * @example
 * ```typescript
 * const result = validateAutomation(aiSong.automation, aiSong.tracks);
 * if (!result.valid) {
 *   console.error(`Validation failed: ${result.error.message}`);
 * }
 * ```
 */
export function validateAutomation(
  automation: unknown, 
  tracks: AISongData['tracks']
): AutomationValidationResult {
  if (!Array.isArray(automation)) {
    return { 
      valid: false, 
      error: { type: 'VALIDATION_ERROR', field: 'automation', message: 'automation must be an array' } 
    };
  }

  // Determine expected step count from tracks (default to 32)
  const expectedSteps = determinePatternLength(tracks);

  for (let i = 0; i < automation.length; i++) {
    const lane = automation[i] as Partial<AIAutomationLane>;
    const lanePrefix = `automation[${i}]`;

    // Check target
    if (!lane.target || !VALID_AUTOMATION_TARGETS.includes(lane.target as AIAutomationTarget)) {
      return {
        valid: false,
        error: { 
          type: 'VALIDATION_ERROR', 
          field: `${lanePrefix}.target`, 
          message: `Invalid target "${lane.target}". Must be one of: ${VALID_AUTOMATION_TARGETS.join(', ')}` 
        }
      };
    }

    const target = lane.target as AIAutomationTarget;

    // Check parameter is valid for target
    if (!lane.parameter || !VALID_PARAMETERS_BY_TARGET[target].includes(lane.parameter as AITargetedParameter)) {
      return {
        valid: false,
        error: { 
          type: 'VALIDATION_ERROR', 
          field: `${lanePrefix}.parameter`, 
          message: `Invalid parameter "${lane.parameter}" for target "${target}". Valid: ${[...VALID_PARAMETERS_BY_TARGET[target]].join(', ')}` 
        }
      };
    }

    // Validate steps array
    if (!Array.isArray(lane.steps)) {
      return {
        valid: false,
        error: { type: 'VALIDATION_ERROR', field: `${lanePrefix}.steps`, message: 'steps must be an array' }
      };
    }

    if (lane.steps.length !== expectedSteps) {
      return {
        valid: false,
        error: { 
          type: 'VALIDATION_ERROR', 
          field: `${lanePrefix}.steps`, 
          message: `steps length (${lane.steps.length}) must match pattern length (${expectedSteps})` 
        }
      };
    }

    // Validate step values (0-127 or null)
    for (let s = 0; s < lane.steps.length; s++) {
      const value = lane.steps[s];
      if (value !== null && (typeof value !== 'number' || value < MIDI_VALUE_RANGE.min || value > MIDI_VALUE_RANGE.max)) {
        return {
          valid: false,
          error: { 
            type: 'VALIDATION_ERROR', 
            field: `${lanePrefix}.steps[${s}]`, 
            message: `Step values must be ${MIDI_VALUE_RANGE.min}-${MIDI_VALUE_RANGE.max} or null, got ${value}` 
          }
        };
      }
    }

    // Validate interpolation if provided
    if (lane.interpolation !== undefined && !VALID_INTERPOLATION_MODES.includes(lane.interpolation)) {
      return {
        valid: false,
        error: { 
          type: 'VALIDATION_ERROR', 
          field: `${lanePrefix}.interpolation`, 
          message: `Invalid interpolation "${lane.interpolation}". Must be: ${VALID_INTERPOLATION_MODES.join(', ')}` 
        }
      };
    }
  }

  return { valid: true };
}

/**
 * Check if a target+parameter combination is valid.
 * 
 * @param target - The automation target
 * @param parameter - The parameter to automate
 * @returns True if the combination is valid
 * 
 * @example
 * ```typescript
 * if (isValidAutomationTarget('synthA', 'filterCutoff')) {
 *   // Valid combination
 * }
 * ```
 */
export function isValidAutomationTarget(
  target: AIAutomationTarget, 
  parameter: AITargetedParameter
): boolean {
  if (!VALID_AUTOMATION_TARGETS.includes(target)) {
    return false;
  }
  return VALID_PARAMETERS_BY_TARGET[target].includes(parameter);
}

// ============================================================================
// CONVERSION
// ============================================================================

/**
 * Convert an AI automation lane to Hyphon automation points.
 * 
 * Maps per-step values (0-127) to Hyphon's normalized range (0-1).
 * Only non-null steps create automation points.
 * 
 * @param lane - The automation lane to convert
 * @returns Array of automation points ready for Hyphon
 * 
 * @example
 * ```typescript
 * const lane: AIAutomationLane = {
 *   target: 'synthA',
 *   parameter: 'filterCutoff',
 *   steps: [64, null, 127, 32],
 *   interpolation: 'linear'
 * };
 * const points = convertAutomationToPoints(lane);
 * // Returns: [{ step: 0, value: 0.5 }, { step: 2, value: 1.0 }, { step: 3, value: 0.25 }]
 * ```
 */
export function convertAutomationToPoints(lane: AIAutomationLane): AutomationPoint[] {
  const points: AutomationPoint[] = [];

  for (let step = 0; step < lane.steps.length; step++) {
    const value = lane.steps[step];
    if (value !== null) {
      // Convert 0-127 to 0-1 range for Hyphon
      points.push({
        step,
        value: value / MIDI_VALUE_RANGE.max
      });
    }
  }

  return points;
}

/**
 * Map AI automation target to Hyphon track key.
 * 
 * @param target - AI automation target
 * @returns Hyphon track key
 * 
 * @example
 * ```typescript
 * const trackKey = mapTargetToTrackKey('synthA'); // Returns: 'partA'
 * ```
 */
export function mapTargetToTrackKey(target: AIAutomationTarget): string {
  const mapping: Record<AIAutomationTarget, string> = {
    synthA: 'partA',
    synthB: 'partB',
    bass2: 'bass2',
    kick: 'kick',
    snare: 'snare',
    closedHat: 'closedHat',
    openHat: 'openHat',
    sampler: 'sampler',
    master: 'master'
  };
  return mapping[target];
}

// ============================================================================
// SUMMARY & METADATA
// ============================================================================

/**
 * Automation lane summary for UI display.
 */
export interface AutomationLaneSummary {
  target: AIAutomationTarget;
  parameter: AITargetedParameter;
  pointCount: number;
  interpolation: AIInterpolationMode;
  minValue: number | null;
  maxValue: number | null;
}

/**
 * Get a human-readable summary of automation lanes.
 * 
 * @param automation - Array of automation lanes
 * @returns Summary with lane count and details
 * 
 * @example
 * ```typescript
 * const summary = getAutomationSummary(aiSong.automation);
 * console.log(`${summary.laneCount} automation lanes`);
 * summary.lanes.forEach(lane => {
 *   console.log(`${lane.target}.${lane.parameter}: ${lane.pointCount} points`);
 * });
 * ```
 */
export function getAutomationSummary(
  automation: AIAutomationLane[] | undefined
): {
  laneCount: number;
  totalPoints: number;
  lanes: AutomationLaneSummary[];
} {
  if (!automation || automation.length === 0) {
    return { laneCount: 0, totalPoints: 0, lanes: [] };
  }

  let totalPoints = 0;
  const lanes: AutomationLaneSummary[] = automation.map(lane => {
    const values = lane.steps.filter((s): s is number => s !== null);
    const pointCount = values.length;
    totalPoints += pointCount;

    // ⚡ Bolt Optimization: Replace Math.max(...array) with standard O(n) loop
    // This avoids "Maximum call stack size exceeded" errors on large datasets and reduces GC overhead.
    let minValue: number | null = null;
    let maxValue: number | null = null;
    if (values.length > 0) {
      minValue = Infinity;
      maxValue = -Infinity;
      for (let i = 0; i < values.length; i++) {
        const val = values[i];
        if (val < minValue) minValue = val;
        if (val > maxValue) maxValue = val;
      }
    }

    return {
      target: lane.target,
      parameter: lane.parameter,
      pointCount,
      interpolation: lane.interpolation || 'step',
      minValue,
      maxValue
    };
  });

  return {
    laneCount: automation.length,
    totalPoints,
    lanes
  };
}

/**
 * Get all valid parameters for a target.
 * 
 * @param target - The automation target
 * @returns Array of valid parameters, or empty array if target is invalid
 * 
 * @example
 * ```typescript
 * const params = getValidParametersForTarget('synthA');
 * // Returns: ['filterCutoff', 'filterResonance', ...]
 * ```
 */
export function getValidParametersForTarget(target: AIAutomationTarget): readonly AITargetedParameter[] {
  return VALID_PARAMETERS_BY_TARGET[target] || [];
}

// ============================================================================
// UTILITIES
// ============================================================================

/**
 * Determine pattern length from track data.
 * 
 * Checks drum track lengths to infer pattern size.
 * Defaults to 32 steps (Hyphon standard).
 * 
 * @param tracks - Tracks object from AISongData
 * @returns Pattern length (16 or 32)
 */
export function determinePatternLength(tracks: AISongData['tracks']): number {
  // Check drum tracks for length
  const drumTracks: (boolean[] | undefined)[] = [
    tracks.kick, 
    tracks.snare, 
    tracks.closedHat, 
    tracks.openHat
  ];

  for (const track of drumTracks) {
    if (track && track.length > 0) {
      return track.length <= 16 ? 16 : 32;
    }
  }

  // Default to 32 steps for Hyphon compatibility
  return DEFAULT_PATTERN_LENGTH;
}

/**
 * Create an empty automation lane.
 * 
 * @param target - The automation target
 * @param parameter - The parameter to automate
 * @param length - Number of steps (default: 32)
 * @returns New automation lane with all null steps
 * 
 * @example
 * ```typescript
 * const lane = createEmptyAutomationLane('synthA', 'filterCutoff', 32);
 * ```
 */
export function createEmptyAutomationLane(
  target: AIAutomationTarget,
  parameter: AITargetedParameter,
  length: number = DEFAULT_PATTERN_LENGTH
): AIAutomationLane {
  return {
    target,
    parameter,
    steps: Array(length).fill(null),
    interpolation: 'step'
  };
}

/**
 * Interpolate automation values between points.
 * 
 * @param points - Array of automation points
 * @param length - Total pattern length
 * @param mode - Interpolation mode
 * @returns Array of interpolated values
 * 
 * @example
 * ```typescript
 * const interpolated = interpolateAutomation(
 *   [{ step: 0, value: 0 }, { step: 4, value: 1 }],
 *   8,
 *   'linear'
 * );
 * // Returns: [0, 0.25, 0.5, 0.75, 1, 1, 1, 1]
 * ```
 */
export function interpolateAutomation(
  points: AutomationPoint[],
  length: number,
  mode: AIInterpolationMode = 'linear'
): number[] {
  if (points.length === 0) {
    return Array(length).fill(0);
  }

  const result: number[] = [];
  let currentPointIdx = 0;

  for (let step = 0; step < length; step++) {
    // Find the current segment
    while (currentPointIdx < points.length - 1 && points[currentPointIdx + 1].step <= step) {
      currentPointIdx++;
    }

    if (currentPointIdx >= points.length - 1) {
      // Past last point, hold value
      result.push(points[points.length - 1].value);
    } else if (points[currentPointIdx].step === step) {
      // Exact point
      result.push(points[currentPointIdx].value);
    } else {
      // Interpolate between current and next point
      const current = points[currentPointIdx];
      const next = points[currentPointIdx + 1];

      if (mode === 'step') {
        result.push(current.value);
      } else {
        const t = (step - current.step) / (next.step - current.step);
        const easedT = mode === 'smooth' ? easeInOutCubic(t) : t;
        result.push(current.value + (next.value - current.value) * easedT);
      }
    }
  }

  return result;
}

/**
 * Cubic ease-in-out function for smooth interpolation.
 */
function easeInOutCubic(t: number): number {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

