/**
 * Serialize version history for storage
 *
 * @param history - Version history
 * @returns JSON-serializable object
 */
export function serializeVersionHistory(history: VersionHistory): unknown {
  return JSON.parse(JSON.stringify(history));
}

/**
 * Deserialize version history from storage
 *
 * @param data - Stored data
 * @returns Version history or null if invalid
 */
export function deserializeVersionHistory(data: unknown): VersionHistory | null {
  try {
    const parsed = data as VersionHistory;
    if (
      parsed &&
      typeof parsed.currentVersionId === 'string' &&
      Array.isArray(parsed.versions) &&
      parsed.versions.every(
        (v: VersionEntry) =>
          typeof v.id === 'string' &&
          typeof v.timestamp === 'string' &&
          typeof v.author === 'string' &&
          typeof v.changes === 'string'
      )
    ) {
      return parsed;
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * RBS Exporter — write ReBirth RB-338 compatible `.rbs` files from Hyphon songs.
 *
 * Supports IFF CAT RB40 pattern-mode and song-mode (GLOB + DEVL + TRKL/TRAK) export.
 */

import type { HyphonAutomationLane, HyphonSong, RbsTrakEvent } from './types';
import type { PartSequence, ResolvedTrakEvent, SavedSongData, UnifiedAutomationLane } from '../../types';
import type { TrackKey } from '../../constants/appDefaults';
import { resolveTrakEventKind } from './trakControllers';
import { MAX_TRACK_PATTERN_SLOTS } from '../../constants';
import { buildIffRbsFile } from './iffBuilder';
import {
  buildDrumPatternFromHyphon,
  buildDrumPatternsFromTrackStorage,
  collectExportWarnings,
  partSequenceToTb303Steps,
  pcfSettingsToDevlPayload,
  synthParamsToTb303DeviceParams,
} from './rbsEncoders';
import {
  buildSongModeTrakTracks,
  countUsedPatternSlots,
  summarizePatternSelectUsage,
} from './trakExport';
import {
  DEFAULT_RBS_EXPORT_OPTIONS,
  type RbsExportOptions,
  type RbsExportResult,
} from './exporter-types';
import type { Tb303Step, DrumPattern } from './types';

export class RbsExporter {
  private options: RbsExportOptions;

  constructor(options: Partial<RbsExportOptions> = {}) {
    this.options = { ...DEFAULT_RBS_EXPORT_OPTIONS, ...options };
  }

  setOptions(options: Partial<RbsExportOptions>): void {
    this.options = { ...this.options, ...options };
  }

  getOptions(): RbsExportOptions {
    return { ...this.options };
  }

  /** Export HyphonSong to raw `.rbs` bytes. */
  exportToBytes(song: HyphonSong, options?: Partial<RbsExportOptions>): { bytes: Uint8Array; warnings: string[] } {
    const opts = { ...this.options, ...options };
    const warnings = collectExportWarnings(song);

    if (opts.versionTarget === '1.5') {
      warnings.push('v1.5 export uses IFF DEVL with a single TB-303 device.');
    }

    const collapse = opts.collapse32Steps;
    const arrangement = song.songArrangement;
    const isSongExport = opts.mode === 'song' && arrangement?.mode === 'song';

    if (opts.mode === 'song' && !isSongExport) {
      warnings.push('Song-mode export requested but no song arrangement present — writing pattern mode.');
    }

    const drumKit = opts.drumKit === 'auto'
      ? (song.params.drumKit ?? '808')
      : opts.drumKit;

    const include303B = opts.versionTarget === '2.0' && opts.include303B;

    let tb303ASteps: Tb303Step[] | Tb303Step[][] | undefined;
    let tb303BSteps: Tb303Step[] | Tb303Step[][] | undefined;
    let drumPattern: DrumPattern | DrumPattern[] | undefined;

    if (isSongExport && arrangement) {
      const slotCount = Math.min(
        MAX_TRACK_PATTERN_SLOTS,
        countUsedPatternSlots(arrangement.trackStorage),
      );

      if (slotCount > MAX_TRACK_PATTERN_SLOTS) {
        warnings.push(
          `Song uses ${slotCount} pattern slots; Hyphon supports ${MAX_TRACK_PATTERN_SLOTS} per track — exporting first ${MAX_TRACK_PATTERN_SLOTS} slots.`,
        );
      }

      const exportSlots = Math.min(MAX_TRACK_PATTERN_SLOTS, slotCount);

      tb303ASteps = arrangement.trackStorage.partA
        .slice(0, exportSlots)
        .map((seq) => partSequenceToTb303Steps(seq ?? { steps: Array(16).fill(null) }, collapse));

      const partBSource = opts.tb303BSource === 'bass2' ? arrangement.trackStorage.bass2 : arrangement.trackStorage.partB;
      tb303BSteps = include303B
        ? partBSource
          .slice(0, exportSlots)
          .map((seq) => partSequenceToTb303Steps(seq ?? { steps: Array(16).fill(null) }, collapse))
        : undefined;

      drumPattern = buildDrumPatternsFromTrackStorage(
        arrangement.trackStorage,
        exportSlots,
        collapse,
        drumKit,
      );
    } else {
      const partA = this.resolvePartSequence(song, opts.tb303ASource);
      const partB = this.resolvePartSequence(song, opts.tb303BSource);
      tb303ASteps = partSequenceToTb303Steps(partA, collapse);
      tb303BSteps = include303B ? partSequenceToTb303Steps(partB, collapse) : undefined;
      drumPattern = buildDrumPatternFromHyphon(song.pattern, collapse, drumKit);
    }

    const metaA = song.rbsMetadata?.tb303AParams;
    const metaB = song.rbsMetadata?.tb303BParams;

    const tb303AParams = synthParamsToTb303DeviceParams(song.params.synthA, metaA);
    const tb303BParams = synthParamsToTb303DeviceParams(
      song.params.bass2 ?? song.params.synthB,
      metaB,
    );

    let pcfPayload: ReturnType<typeof pcfSettingsToDevlPayload> | undefined;
    if (opts.includePcf) {
      const pcf = song.rbsMetadata?.pcfSettings ?? (song.pcfFilter ? {
        enabled: song.pcfFilter.enabled,
        cutoff: song.pcfFilter.cutoff,
        resonance: song.pcfFilter.resonance,
        envAmount: song.pcfFilter.envAmount,
        decay: song.pcfFilter.decay,
        filterType: song.pcfFilter.filterType === 'lp' ? 'lp' as const : 'bp' as const,
        pattern: [...song.pcfFilter.pattern],
        target: { ...song.pcfFilter.target },
        waveIndex: 1,
      } : undefined);

      if (pcf) {
        pcfPayload = pcfSettingsToDevlPayload(pcf);
      } else {
        warnings.push('PCF filter data not available — exporting disabled PCF chunk.');
        pcfPayload = { enabled: false };
      }
    } else {
      pcfPayload = { enabled: false };
    }

    const headVersion = opts.versionTarget === '1.5'
      ? 'ReBirth RB-338 v1.5'
      : 'ReBirth RB-338 v2.0';

    const playMode: 0 | 1 = isSongExport ? 1 : 0;
    const loopStartBars = isSongExport ? (arrangement!.loopStart ?? 0) : 0;
    const loopEndBars = isSongExport
      ? (arrangement!.loopEnd ?? Math.max(1, arrangement!.songStructure.length))
      : 1;

    const trakTracks = isSongExport
      ? buildSongModeTrakTracks(song)
      : undefined;

    if (isSongExport && arrangement?.trakEvents?.length) {
      const usage = summarizePatternSelectUsage(arrangement.trakEvents);
      if (usage.maxPatternIndex >= MAX_TRACK_PATTERN_SLOTS) {
        warnings.push(
          `Arrangement references pattern index ${usage.maxPatternIndex}; Hyphon maps to ${MAX_TRACK_PATTERN_SLOTS} slots per track.`,
        );
      }
    }

    const bytes = buildIffRbsFile({
      playMode,
      tempoBpm: song.tempo,
      shuffle: Math.round(song.swing ?? 64),
      loopStartBars,
      loopEndBars,
      headVersionString: headVersion,
      songName: opts.songName ?? song.metadata.name,
      devl: {
        tb303ASteps,
        tb303BSteps: include303B ? tb303BSteps : undefined,
        tb303AParams,
        tb303BParams: include303B ? tb303BParams : undefined,
        drumPattern,
        drumKit,
        include303B,
        pcf: pcfPayload,
        mixrPcfId: 0,
      },
      trakTracks,
    });

    return { bytes, warnings };
  }

  exportToBlob(song: HyphonSong, options?: Partial<RbsExportOptions>): RbsExportResult {
    try {
      const { bytes, warnings } = this.exportToBytes(song, options);
      const blob = new Blob([new Uint8Array(bytes)], { type: 'application/octet-stream' });
      return { success: true, blob, bytes, warnings };
    } catch (err) {
      return {
        success: false,
        warnings: [],
        error: err instanceof Error ? err.message : String(err),
      };
    }
  }

  private resolvePartSequence(song: HyphonSong, track: TrackKey) {
    const pattern = song.pattern;
    if (track === 'sampler') {
      return { steps: Array(16).fill(null) };
    }
    const seq = pattern[track];
    if (Array.isArray(seq)) {
      return seq[0] ?? { steps: Array(16).fill(null) };
    }
    return seq ?? { steps: Array(16).fill(null) };
  }
}

/** Export HyphonSong as a downloadable `.rbs` Blob. */
export function exportRbsFile(
  song: HyphonSong,
  options?: Partial<RbsExportOptions>,
): Blob {
  const exporter = new RbsExporter(options);
  const result = exporter.exportToBlob(song);
  if (!result.success || !result.blob) {
    throw new Error(result.error ?? 'RBS export failed');
  }
  return result.blob;
}

const HYPHON_LANE_TARGETS = new Set<HyphonAutomationLane['target']>([
  'synthA', 'synthB', 'bass2', 'kick', 'snare', 'closedHat', 'openHat', 'master',
]);

function asPartSlots(raw: unknown): (PartSequence | null)[] {
  if (!Array.isArray(raw)) return [];
  return raw.map((slot) => {
    if (slot && typeof slot === 'object' && 'steps' in slot) {
      return slot as PartSequence;
    }
    return null;
  });
}

function unifiedLanesToHyphon(lanes?: UnifiedAutomationLane[]): HyphonAutomationLane[] | undefined {
  if (!lanes?.length) return undefined;
  const converted: HyphonAutomationLane[] = [];
  for (const lane of lanes) {
    if (!HYPHON_LANE_TARGETS.has(lane.target as HyphonAutomationLane['target'])) continue;
    converted.push({
      target: lane.target as HyphonAutomationLane['target'],
      parameter: lane.parameter,
      name: lane.name,
      points: lane.points.map((p) => [p.step, p.value]),
      interpolation: lane.interpolation,
      originalRange: lane.originalRange ?? [0, 1],
    });
  }
  return converted.length > 0 ? converted : undefined;
}

export function resolvedTrakToRbsEvents(events: ResolvedTrakEvent[]): RbsTrakEvent[] {
  return events.map((ev) => ({
    deltaTicks: 0,
    absoluteTicks: ev.tick,
    trackIndex: ev.trackIndex,
    controllerId: ev.ctrlId,
    value: ev.value,
    eventKind: ev.eventKind ?? resolveTrakEventKind(ev.trackIndex, ev.ctrlId),
  }));
}

/** True when song mode is active or the arrangement uses more than slot 0. */
export function shouldExportRbsSongMode(
  data: SavedSongData,
  isSongModeActive?: boolean,
): boolean {
  if (isSongModeActive) return true;
  const structure = data.songStructure as Array<Record<string, number | null>> | undefined;
  if (!structure?.length) return false;
  for (const measure of structure) {
    if (!measure) continue;
    for (const value of Object.values(measure)) {
      if (typeof value === 'number' && value > 0) return true;
    }
  }
  return false;
}

export interface HyphonSongFromSavedExtras {
  trakEvents?: ResolvedTrakEvent[] | null;
  isSongModeActive?: boolean;
}

/** Build a HyphonSong from saved project data for export (includes arrangement when present). */
export function hyphonSongFromSavedData(
  data: SavedSongData,
  extras: HyphonSongFromSavedExtras = {},
): HyphonSong {
  const ts = data.trackStorage as Record<string, unknown> | undefined;
  const structure = (data.songStructure ?? []) as Array<Record<string, number | null>>;
  const trakFromData = data.rbsTrakEvents?.length
    ? resolvedTrakToRbsEvents(data.rbsTrakEvents)
    : undefined;
  const trakFromRef = extras.trakEvents?.length
    ? resolvedTrakToRbsEvents(extras.trakEvents)
    : undefined;
  const trakEvents = trakFromRef ?? trakFromData;

  const isSong = shouldExportRbsSongMode(data, extras.isSongModeActive);

  const song: HyphonSong = {
    version: 1,
    metadata: {
      name: data.pattern ? 'Hyphon Song' : 'Untitled',
      importedFrom: 'rbs',
      importedAt: new Date(),
    },
    tempo: data.tempo,
    timeSignature: [4, 4],
    swing: 64,
    pattern: data.pattern,
    params: {
      synthA: data.params.synthA,
      synthB: data.params.synthB,
      bass2: data.params.bass2,
      kick: data.params.kick,
      snare: data.params.snare,
      closedHat: data.params.closedHat,
      openHat: data.params.openHat,
      drumKit: data.params.kick ? '808' : undefined,
    },
    automation: unifiedLanesToHyphon(data.automationLanes),
    pcfFilter: data.pcfFilter,
  };

  if (ts && structure.length > 0) {
    song.songArrangement = {
      mode: isSong ? 'song' : 'pattern',
      trackStorage: {
        partA: asPartSlots(ts.partA),
        partB: asPartSlots(ts.partB),
        bass2: asPartSlots(ts.bass2),
        kick: asPartSlots(ts.kick),
        snare: asPartSlots(ts.snare),
        closedHat: asPartSlots(ts.closedHat),
        openHat: asPartSlots(ts.openHat),
      },
      songStructure: structure,
      activeTrackSlots: data.activeTrackSlots,
      loopStart: data.rbsLoopStart,
      loopEnd: data.rbsLoopEnd,
      trakEvents,
      trackParamStorage: data.trackParamStorage,
    };
  }

  return song;
}

export default RbsExporter;

import type { RawRbsData } from './types';
import { isV15SubsetVersion } from './parser-types';
import type { RbsParserResult, RbsParserError } from './parser-types';
import { MIN_FILE_SIZE, SUPPORTED_VERSIONS } from './parser-types';
import { inferDevicesPresent, isTb303PatternSilent } from './deviceInference';
import type { ParserBinaryContext } from './parser/parserContext';
import {
  parseHeader,
  parseTb303PatternA,
  parseTb303PatternB,
  parseDrumPatterns,
  parsePcfSettings,
  parseAutomation,
} from './parser/legacyParse';
import {
  validateVersion,
  detectIffTruncation,
  parseIffChunks,
  parseIffSongData,
  parseIffHead,
} from './parser/iffParse';
import {
  generateEmptyTb303PatternB,
  generateMockTb303Pattern,
  generateMockTb303PatternB,
  generateMockDrumPattern,
  generateMockPcfSettings,
  generateMockAutomation,
} from './parser/mockData';

export class RbsParser {
  /** Parse progress callback (0-100) */
  onProgress?: (percent: number) => void;

  private dataView!: DataView;
  private rawBytes!: Uint8Array;
  private fileSize!: number;

  private ctx(): ParserBinaryContext {
    return {
      dataView: this.dataView,
      rawBytes: this.rawBytes,
      fileSize: this.fileSize,
      onProgress: this.onProgress,
    };
  }

  /**
   * Parse raw bytes (test / programmatic entry point).
   * Never throws — all failures are returned as `{ success: false, error }`.
   */
  async parseBytes(
    bytes: Uint8Array,
    options: { filename?: string; requireExtension?: boolean } = {},
  ): Promise<RbsParserResult> {
    const filename = options.filename ?? 'input.rbs';
    const requireExtension = options.requireExtension ?? true;

    this.onProgress?.(0);

    try {
      if (requireExtension && !filename.toLowerCase().endsWith('.rbs')) {
        return {
          success: false,
          error: {
            type: 'INVALID_FORMAT',
            message: `File "${filename}" does not have .rbs extension`,
          },
        };
      }

      this.fileSize = bytes.byteLength;
      if (this.fileSize < MIN_FILE_SIZE) {
        return {
          success: false,
          error: {
            type: 'CORRUPTED_DATA',
            section: 'header',
            details: `File too small (${this.fileSize} bytes, min ${MIN_FILE_SIZE})`,
          },
        };
      }

      if (this.fileSize > 10 * 1024 * 1024) {
        return {
          success: false,
          error: {
            type: 'INVALID_FORMAT',
            message: 'File too large (max 10MB for RBS files)',
          },
        };
      }

      const arrayBuffer = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
      this.dataView = new DataView(arrayBuffer);
      this.rawBytes = new Uint8Array(arrayBuffer);

      this.onProgress?.(5);

      const ctx = this.ctx();
      const iffChunks = parseIffChunks(ctx);
      if (iffChunks.length > 0) {
        const truncationError = detectIffTruncation(ctx, iffChunks);
        if (truncationError) {
          return { success: false, error: truncationError };
        }

        const headChunk = iffChunks.find((c) => c.id === 'HEAD');
        if (headChunk) {
          const iffVersion = parseIffHead(ctx, headChunk);
          const versionError = validateVersion(iffVersion);
          if (versionError) {
            return { success: false, error: versionError };
          }
        }

        console.info(`[RbsParser] Detected full IFF CAT RB40 structure with ${iffChunks.length} top-level chunks. Attempting full song parse.`);
        const iffResult = parseIffSongData(ctx, iffChunks);
        if (iffResult) {
          this.onProgress?.(100);
          return { success: true, data: iffResult };
        }
        console.info('[RbsParser] IFF song data incomplete, falling back to legacy single-pattern extraction.');
      }

      const headerResult = parseHeader(ctx);
      if (!headerResult.success) {
        return { success: false, error: (headerResult as { success: false; error: RbsParserError }).error };
      }
      const header = headerResult.data;
      const versionError = validateVersion(header.version);
      if (versionError) {
        return { success: false, error: versionError };
      }
      this.onProgress?.(10);

      const tb303A = parseTb303PatternA(ctx);
      this.onProgress?.(40);

      let tb303B = parseTb303PatternB(ctx);
      if (isV15SubsetVersion(header.version) || isTb303PatternSilent(tb303B)) {
        tb303B = generateEmptyTb303PatternB();
      }
      this.onProgress?.(70);

      const drums = parseDrumPatterns(ctx);
      this.onProgress?.(85);

      const pcf = parsePcfSettings(ctx);
      this.onProgress?.(95);

      const automation = parseAutomation(ctx);
      this.onProgress?.(100);

      const baseName = filename.replace(/\.rbs$/i, '');

      const rawData: RawRbsData = {
        version: header.version,
        project: {
          name: header.songName || baseName,
          author: 'Imported from RBS',
          tempo: header.tempo,
          timeSignatureNum: header.timeSignatureNum,
          timeSignatureDen: header.timeSignatureDen,
          swing: header.swing,
          patternLength: header.patternLength,
          createdAt: new Date(),
          sourceSoftware: 'ReBirth RB-338',
        },
        tb303PatternA: tb303A,
        tb303PatternB: tb303B,
        drums,
        pcf,
        automation,
        rawHeader: header,
        parsePath: 'legacy',
      };
      rawData.devicesPresent = inferDevicesPresent(rawData);

      return { success: true, data: rawData };
    } catch (error) {
      return {
        success: false,
        error: {
          type: 'READ_ERROR',
          message: error instanceof Error ? error.message : 'Unknown error reading file',
        },
      };
    }
  }

  /** Main entry point: parse an .rbs file */
  async parseRbsFile(file: File): Promise<RbsParserResult> {
    const arrayBuffer = await file.arrayBuffer();
    return this.parseBytes(new Uint8Array(arrayBuffer), { filename: file.name, requireExtension: true });
  }

  /** Generate mock RBS data for UI development/testing */
  generateMockData(filename: string): RawRbsData {
    const baseName = filename.replace(/\.rbs$/i, '');

    return {
      version: '2.0',
      project: {
        name: baseName,
        author: 'Imported from RBS',
        tempo: 128,
        timeSignatureNum: 4,
        timeSignatureDen: 4,
        swing: 50,
        patternLength: 16,
        createdAt: new Date(),
        sourceSoftware: 'ReBirth RB-338',
      },
      tb303PatternA: generateMockTb303Pattern(),
      tb303PatternB: generateMockTb303PatternB(),
      drums: generateMockDrumPattern(),
      pcf: generateMockPcfSettings(),
      automation: generateMockAutomation(),
    };
  }

  static isVersionSupported(version: string): boolean {
    return SUPPORTED_VERSIONS.includes(version);
  }

  static getSupportedVersions(): string[] {
    return [...SUPPORTED_VERSIONS];
  }
}

/** Convenience function for simple parsing */
export async function parseRbsFile(file: File, onProgress?: (percent: number) => void): Promise<RbsParserResult> {
  const parser = new RbsParser();
  parser.onProgress = onProgress;
  return parser.parseRbsFile(file);
}

export default RbsParser;

/**
 * RebirthRBSParser
 *
 * Version-aware parser for Rebirth RB-338 .rbs song files (v1.5, 2.0, 2.0.1).
 * Follows the technical spec provided for this task.
 *
 * Designed to be the canonical entry point for .rbs import.
 * Uses DataView exclusively for all binary reads (little-endian per spec).
 *
 * Architecture:
 * - Delegates to the existing robust RbsParser for binary extraction.
 * - Exposes the spec-recommended clean API: parseHeader(), parsePatterns(),
 *   parseSynthParameters(synthIndex), parseSongArrangement(), parseAutomation().
 * - Each method returns a fully typed result; no raw `any` in the public API.
 *
 * Notes on real-world format:
 * - The provided spec gives a simplified linear view.
 * - Actual files are often IFF CAT "RB40" containers (see RBS42.txt research).
 * - This class is resilient: RbsParser already handles IFF detection and falls
 *   back to fixed-offset extraction for compatibility.
 */

import type {
  RawRbsData,
  Tb303PatternA,
  Tb303PatternB,
  AutomationLane,
  RbsTrakEvent,
  RbsSongData,
  Tb303Step,
} from './types';
import { TRAK_TRACK_INDEX, TICKS_PER_BAR } from './types';
import { isTrakPatternSelectEvent } from './trakControllers';
import { RbsParser } from './RbsParser';
import type { RbsParserError } from './parser-types';

// ============================================================================
// Public return-type interfaces for each spec method
// ============================================================================

/** Structured header as returned by parseHeader() */
export interface RbsHeaderData {
  /** File magic – "RB338" for authentic files */
  magic: string;
  /** Full version string (e.g. "2.0", "1.5", "2.0.1") */
  version: string;
  /** Major version component */
  versionMajor: number;
  /** Minor version component */
  versionMinor: number;
  /**
   * Patch version component (e.g. 1 for "2.0.1", 0 when absent).
   * Versions like "2.0.1" carry meaningful patch information in ReBirth.
   */
  versionPatch: number;
  /** Tempo in BPM (40-250) */
  bpm: number;
  /** Swing amount (0-100, 50 = no swing) */
  swing: number;
  /** Song / pattern name, null-terminated ASCII from header */
  songName: string;
  /** Number of steps per pattern (typically 16) */
  patternLength: number;
  /** Time-signature numerator */
  timeSignatureNum: number;
  /** Time-signature denominator */
  timeSignatureDen: number;
}

/** Single pattern entry returned by parsePatterns() */
export interface RbsPatternData {
  /** 0-based pattern index within the device */
  patternIndex: number;
  /** Which device this pattern belongs to */
  device: 'tb303A' | 'tb303B' | 'drums';
  /** Step data (Tb303Step array for 303 devices, boolean array for drums) */
  steps: Tb303Step[] | boolean[];
  /** Number of active steps (16 or 32) */
  length: number;
}

/** TB-303 synthesizer parameters returned by parseSynthParameters() */
export interface RbsSynthParameters {
  /** Synth index: 1 = TB-303 A, 2 = TB-303 B */
  synthIndex: 1 | 2;
  /** Cutoff frequency (0-127) */
  cutoff: number;
  /** Resonance amount (0-127) */
  resonance: number;
  /** Envelope modulation amount (0-127) */
  envMod: number;
  /** Decay time (0-127) */
  decay: number;
  /** Accent intensity (0-127) */
  accent: number;
  /** Waveform: 0 = sawtooth, 1 = square */
  waveform: 0 | 1;
  /** Distortion amount (0-127), if present in file */
  distortion?: number;
  /** Delay send (0-127), if present in file */
  delaySend?: number;
  /** Transpose in semitones (-12 to +12); only populated for synthIndex 2 */
  transpose?: number;
}

/** Song arrangement data returned by parseSongArrangement() */
export interface RbsSongArrangement {
  /** Play mode detected from file ("pattern" single-pattern loop, "song" multi-pattern) */
  mode: 'pattern' | 'song';
  /** Ordered list of pattern slots in the arrangement (may be empty for pattern mode) */
  patternSlots: Array<{ patternIndex: number; repeats: number }>;
  /** Loop start pattern slot index (undefined when not set) */
  loopStart?: number;
  /** Loop end pattern slot index (undefined when not set) */
  loopEnd?: number;
}

/** Automation lane data returned by parseAutomation() */
export interface RbsAutomationData {
  /** Parameter identifier string (e.g. "tb303Acutoff") */
  parameter: string;
  /** Human-readable display name */
  name: string;
  /** Automation points: [stepIndex, value] */
  points: [number, number][];
  /** Value interpolation type */
  interpolation: 'step' | 'linear' | 'smooth';
  /** Expected value range [min, max] */
  range: [number, number];
}

/** Top-level result from parseFile() */
export interface RebirthParseResult {
  success: boolean;
  /** Full raw RBS data tree (populated on success) */
  data?: RawRbsData;
  /** Error message (populated on failure) */
  error?: string;
  /** Version string detected from the file */
  versionDetected?: string;
  /** Structured header (populated on success) */
  header?: RbsHeaderData;
  /** Synth A parameters (populated on success) */
  synthA?: RbsSynthParameters;
  /** Synth B parameters (populated on success) */
  synthB?: RbsSynthParameters;
  /** All patterns for all devices (populated on success) */
  patterns?: RbsPatternData[];
  /** Song arrangement info (populated on success) */
  arrangement?: RbsSongArrangement;
  /** Automation lanes (populated on success) */
  automationLanes?: RbsAutomationData[];
}

// ============================================================================
// Module-level helpers
// ============================================================================

/**
 * Convert a typed RbsParserError into a human-readable string.
 * Each variant of the discriminated union carries different fields.
 */
function extractErrorMessage(err: RbsParserError): string {
  switch (err.type) {
    case 'INVALID_FORMAT':
    case 'READ_ERROR':
      return err.message;
    case 'UNSUPPORTED_VERSION':
      return `Unsupported version "${err.version}" (supported: ${err.supported.join(', ')})`;
    case 'CORRUPTED_DATA':
      return `Corrupted data in section "${err.section}"${err.details ? `: ${err.details}` : ''}`;
    default:
      // Exhaustiveness guard – should never be reached with current error types
      return JSON.stringify(err);
  }
}

// ============================================================================
// RebirthRBSParser class
// ============================================================================

export class RebirthRBSParser {
  /** Underlying engine – carries out the real binary extraction */
  private engine: RbsParser;

  /** Cached raw data from the last successful parseFile() call */
  private rawData: RawRbsData | null = null;

  constructor() {
    this.engine = new RbsParser();
  }

  /**
   * Main entry-point.  Reads the file, runs the full parse pipeline, and
   * returns a rich result object including all sub-section data.
   */
  async parseFile(file: File): Promise<RebirthParseResult> {
    if (!file.name.toLowerCase().endsWith('.rbs')) {
      return { success: false, error: 'File must have .rbs extension' };
    }

    const buffer = await file.arrayBuffer();
    return this.parseBuffer(new Uint8Array(buffer), file.name);
  }

  /**
   * Parse from raw bytes (programmatic / test entry point).
   * Never throws — failures are returned in the result object.
   */
  async parseBuffer(bytes: Uint8Array, filename = 'input.rbs'): Promise<RebirthParseResult> {
    const engineResult = await this.engine.parseBytes(bytes, { filename, requireExtension: false });
    if (!engineResult.success) {
      return { success: false, error: extractErrorMessage(engineResult.error) };
    }

    this.rawData = engineResult.data;
    const raw = this.rawData;

    // Build the full result using the spec-recommended method calls
    const header = this.parseHeader();
    const synthA = this.parseSynthParameters(1);
    const synthB = this.parseSynthParameters(2);
    const patterns = this.parsePatterns();
    const arrangement = this.parseSongArrangement();
    const automationLanes = this.parseAutomation();

    console.log(
      `[RebirthRBSParser] Parsed "${filename}" – version ${header.version}, ` +
      `${patterns.length} pattern entries, ${automationLanes.length} automation lane(s).`
    );

    return {
      success: true,
      versionDetected: header.version,
      data: raw,
      header,
      synthA,
      synthB,
      patterns,
      arrangement,
      automationLanes,
    };
  }

  // ============================================================================
  // Spec-recommended public methods
  // ============================================================================

  /**
   * Return structured header information.
   * Reads from the cached rawData populated by parseFile(); call parseFile() first.
   */
  parseHeader(): RbsHeaderData {
    const raw = this.requireRawData('parseHeader');
    const rh = raw.rawHeader;

    // Use rawHeader when available (populated by RbsParser); fall back to project fields.
    const magic = rh?.magic ?? 'RB338';
    const version = rh?.version ?? raw.version;

    // Parse all three version components to avoid losing the patch part (e.g. "2.0.1" → 2, 0, 1).
    const versionParts = version.split('.');
    const versionMajor = parseInt(versionParts[0] ?? '2', 10);
    const versionMinor = parseInt(versionParts[1] ?? '0', 10);
    const versionPatch = parseInt(versionParts[2] ?? '0', 10);

    return {
      magic,
      version,
      versionMajor,
      versionMinor,
      versionPatch,
      bpm: rh?.tempo ?? raw.project.tempo,
      swing: rh?.swing ?? raw.project.swing,
      songName: rh?.songName ?? raw.project.name,
      patternLength: rh?.patternLength ?? raw.project.patternLength,
      timeSignatureNum: rh?.timeSignatureNum ?? raw.project.timeSignatureNum,
      timeSignatureDen: rh?.timeSignatureDen ?? raw.project.timeSignatureDen,
    };
  }

  /**
   * Return all pattern data blocks for all devices.
   * When songData is present (full IFF file), returns patterns from all banks.
   * Otherwise returns the single pattern from legacy extraction.
   */
  parsePatterns(): RbsPatternData[] {
    const raw = this.requireRawData('parsePatterns');
    const results: RbsPatternData[] = [];

    if (raw.songData) {
      // Multi-pattern: return all patterns from banks
      const { patternBanks } = raw.songData;

      for (let i = 0; i < patternBanks.tb303A.length; i++) {
        results.push({
          patternIndex: i,
          device: 'tb303A',
          steps: patternBanks.tb303A[i].steps,
          length: patternBanks.tb303A[i].steps.length,
        });
      }

      for (let i = 0; i < patternBanks.tb303B.length; i++) {
        results.push({
          patternIndex: i,
          device: 'tb303B',
          steps: patternBanks.tb303B[i].steps,
          length: patternBanks.tb303B[i].steps.length,
        });
      }

      const drumBank = patternBanks.drums808.length > 0 ? patternBanks.drums808 : patternBanks.drums909;
      for (let i = 0; i < drumBank.length; i++) {
        results.push({
          patternIndex: i,
          device: 'drums',
          steps: drumBank[i].kick,
          length: drumBank[i].kick.length,
        });
      }

      return results;
    }

    // Legacy single-pattern mode
    // TB-303 A
    results.push({
      patternIndex: 0,
      device: 'tb303A',
      steps: raw.tb303PatternA.steps,
      length: raw.tb303PatternA.steps.length,
    });

    // TB-303 B
    results.push({
      patternIndex: 0,
      device: 'tb303B',
      steps: raw.tb303PatternB.steps,
      length: raw.tb303PatternB.steps.length,
    });

    // Drums (kick as representative)
    results.push({
      patternIndex: 0,
      device: 'drums',
      steps: raw.drums.kick,
      length: raw.drums.kick.length,
    });

    return results;
  }

  /**
   * Return synthesizer parameters for a given synth index.
   *
   * @param synthIndex 1 for TB-303 A (lead/bass), 2 for TB-303 B (counter-melody)
   */
  parseSynthParameters(synthIndex: 1 | 2): RbsSynthParameters {
    const raw = this.requireRawData('parseSynthParameters');

    if (synthIndex === 1) {
      const a: Tb303PatternA = raw.tb303PatternA;
      return {
        synthIndex: 1,
        cutoff: a.cutoff,
        resonance: a.resonance,
        envMod: a.envMod,
        decay: a.decay,
        accent: a.accent,
        waveform: a.waveform,
        distortion: a.distortion,
        delaySend: a.delaySend,
      };
    }

    const b: Tb303PatternB = raw.tb303PatternB;
    return {
      synthIndex: 2,
      cutoff: b.cutoff,
      resonance: b.resonance,
      envMod: b.envMod,
      decay: b.decay,
      accent: b.accent,
      waveform: b.waveform,
      distortion: b.distortion,
      delaySend: b.delaySend,
      transpose: b.transpose,
    };
  }

  /**
   * Return song arrangement information.
   *
   * When the file contains full IFF CAT RB40 GLOB + TRKL data (songData present),
   * this returns the actual arrangement with pattern slots derived from TRAK events.
   * Otherwise returns a safe pattern-mode placeholder for single-pattern files.
   */
  parseSongArrangement(): RbsSongArrangement {
    const raw = this.requireRawData('parseSongArrangement');

    // If songData is present, extract real arrangement from GLOB + TRAK events
    if (raw.songData) {
      const { glob, tracks } = raw.songData;
      const mode: 'pattern' | 'song' = glob.playMode === 1 ? 'song' : 'pattern';

      // Extract pattern slots from TRAK pattern-select events on TB-303 #1.
      const patternSlots: Array<{ patternIndex: number; repeats: number }> = [];

      const mainTrack = tracks.find(t => t.trackIndex === TRAK_TRACK_INDEX.TB303_1) || tracks[0];
      if (mainTrack) {
        let lastPattern = 0;
        let lastTick = 0;

        for (const evt of mainTrack.events) {
          if (!isTrakPatternSelectEvent(evt.trackIndex, evt.controllerId, evt.eventKind)) {
            continue;
          }
          if (patternSlots.length > 0 || evt.absoluteTicks > 0) {
            const durationTicks = evt.absoluteTicks - lastTick;
            const repeats = Math.max(1, Math.round(durationTicks / TICKS_PER_BAR));
            if (patternSlots.length === 0 && evt.absoluteTicks > 0) {
              patternSlots.push({ patternIndex: lastPattern, repeats });
            } else if (patternSlots.length > 0) {
              patternSlots[patternSlots.length - 1].repeats = repeats;
            }
          }
          lastPattern = evt.value;
          lastTick = evt.absoluteTicks;
          patternSlots.push({ patternIndex: evt.value, repeats: 1 });
        }

        // If no pattern select events found, use pattern 0
        if (patternSlots.length === 0) {
          patternSlots.push({ patternIndex: 0, repeats: 1 });
        }
      } else {
        patternSlots.push({ patternIndex: 0, repeats: 1 });
      }

      return {
        mode,
        patternSlots,
        loopStart: glob.loopStart || undefined,
        loopEnd: glob.loopEnd || undefined,
      };
    }

    // Placeholder: single-pattern arrangement (pattern 0, plays once).
    return {
      mode: 'pattern',
      patternSlots: [{ patternIndex: 0, repeats: 1 }],
    };
  }

  /**
   * Return automation lane data extracted from the file.
   * Maps directly to the AutomationLane entries produced by RbsParser.
   */
  parseAutomation(): RbsAutomationData[] {
    const raw = this.requireRawData('parseAutomation');

    return raw.automation.map((lane: AutomationLane): RbsAutomationData => ({
      parameter: lane.parameter,
      name: lane.name,
      points: lane.points,
      interpolation: lane.interpolation,
      range: lane.range,
    }));
  }

  // ============================================================================
  // Private helpers
  // ============================================================================

  /**
   * Assert that rawData is populated (i.e. parseFile() succeeded) and return it.
   * Throws a descriptive error if called before a successful parseFile().
   */
  private requireRawData(callerName: string): RawRbsData {
    if (!this.rawData) {
      throw new Error(
        `[RebirthRBSParser] ${callerName}() called before a successful parseFile(). ` +
        'Call parseFile(file) first and check result.success.'
      );
    }
    return this.rawData;
  }
}

// ============================================================================
// Convenience export
// ============================================================================

export async function parseRebirthRBSFile(file: File): Promise<RebirthParseResult> {
  const parser = new RebirthRBSParser();
  return parser.parseFile(file);
}

/**
 * RBS42 / rbs.h aligned DEVL device chunk layouts.
 * Ref: Propellerhead RBSFormat42.txt, nsauzede/jsynth rbs.h
 */

import type { DrumPattern, Tb303PatternA, Tb303PatternB, Tb303Step, PcfSettings } from './types';

/** DEVL nested chunk IDs (4-char ASCII, trailing space where specified). */
export const DEVL_CHUNK_IDS = {
  MIXR: 'MIXR',
  DELY: 'DELY',
  PCF: 'PCF ',
  DIST: 'DIST',
  COMP: 'COMP',
  TB303: '303 ',
  TR808: '808 ',
  TR909: '909 ',
} as const;

/** Expected payload sizes per RBS42. */
export const TB303_CHUNK_PAYLOAD_SIZE = 1097;
export const TR808_CHUNK_PAYLOAD_SIZE = 6238;
export const TR909_CHUNK_PAYLOAD_SIZE = 6239;

export const TB303_PATTERN_COUNT = 32;
export const TB303_PATTERN_SIZE = 34;
export const TB303_PATTERN_DATA_OFFSET = 9;
export const TB303_STEP_SIZE = 2;
export const TB303_STEP_OFFSET_IN_PATTERN = 2;

export const TR808_PATTERN_COUNT = 32;
export const TR808_PATTERN_SIZE = 194;
export const TR808_PATTERN_DATA_OFFSET = 30;
export const TR808_STEP_INSTRUMENT_COUNT = 12;
export const TR808_STEP_OFFSET_IN_PATTERN = 2;

export const TR909_PATTERN_COUNT = 32;
export const TR909_PATTERN_SIZE = 194;
export const TR909_PATTERN_DATA_OFFSET = 30;
export const TR909_STEP_INSTRUMENT_COUNT = 12;
export const TR909_STEP_OFFSET_IN_PATTERN = 2;

/** TB-303 step flag bits (RBS42 "303 " chunk). */
export const TB303_FLAG_SLIDE = 0x01;
export const TB303_FLAG_ACCENT = 0x02;
export const TB303_FLAG_TRANSPOSE_UP = 0x04;
export const TB303_FLAG_TRANSPOSE_DOWN = 0x08;
export const TB303_FLAG_NOTE = 0x10;

function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

function readTb303Params(bytes: Uint8Array, offset: number): Omit<Tb303PatternA, 'steps'> {
  return {
    cutoff: clamp(bytes[offset + 3] ?? 64, 0, 127),
    resonance: clamp(bytes[offset + 4] ?? 48, 0, 127),
    envMod: clamp(bytes[offset + 5] ?? 64, 0, 127),
    decay: clamp(bytes[offset + 6] ?? 48, 0, 127),
    accent: clamp(bytes[offset + 7] ?? 80, 0, 127),
    waveform: (bytes[offset + 8] ?? 0) === 0 ? 0 : 1,
    distortion: 0,
    delaySend: 0,
  };
}

/**
 * Parse one TB-303 step from DEVL pattern data (2 bytes: pitch + flags).
 */
export function parseDevlTb303Step(stepIndex: number, pitch: number, flags: number): Tb303Step {
  const isNote = (flags & TB303_FLAG_NOTE) !== 0;
  const accent = (flags & TB303_FLAG_ACCENT) !== 0;
  const slide = (flags & TB303_FLAG_SLIDE) !== 0;
  const transposeUp = (flags & TB303_FLAG_TRANSPOSE_UP) !== 0;
  const transposeDown = (flags & TB303_FLAG_TRANSPOSE_DOWN) !== 0;

  if (!isNote) {
    return {
      index: stepIndex,
      note: -1,
      octave: 3,
      accent,
      slide,
      tie: false,
      gate: 100,
    };
  }

  let octave = 3;
  if (transposeUp) octave = clamp(octave + 1, 1, 5);
  if (transposeDown) octave = clamp(octave - 1, 1, 5);

  return {
    index: stepIndex,
    note: pitch % 12,
    octave,
    accent,
    slide,
    tie: false,
    gate: 100,
  };
}

/**
 * Parse all 32 patterns from a DEVL "303 " device chunk payload.
 */
export function parseTb303DeviceChunk(
  bytes: Uint8Array,
  offset: number,
  size: number = TB303_CHUNK_PAYLOAD_SIZE,
): Tb303PatternA[] {
  if (size < TB303_PATTERN_DATA_OFFSET) return [];

  const params = readTb303Params(bytes, offset);
  const patterns: Tb303PatternA[] = [];

  for (let p = 0; p < TB303_PATTERN_COUNT; p++) {
    const patternOffset = offset + TB303_PATTERN_DATA_OFFSET + p * TB303_PATTERN_SIZE;
    if (patternOffset + TB303_PATTERN_SIZE > offset + size) break;

    const patternLength = clamp(bytes[patternOffset + 1] || 16, 1, 16);
    const steps: Tb303Step[] = [];

    for (let s = 0; s < 16; s++) {
      const stepOffset = patternOffset + TB303_STEP_OFFSET_IN_PATTERN + s * TB303_STEP_SIZE;
      const pitch = bytes[stepOffset] ?? 0;
      const flags = bytes[stepOffset + 1] ?? 0;
      const step = parseDevlTb303Step(s, pitch, flags);
      if (s >= patternLength) {
        step.note = -1;
        step.tie = false;
        step.slide = false;
        step.accent = false;
      }
      steps.push(step);
    }

    patterns.push({ steps, ...params });
  }

  return patterns;
}

function isTriggerOn(value: number): boolean {
  return value === 0x01 || value === 0x02 || value === 0x03;
}

function parseTr808Pattern(
  bytes: Uint8Array,
  patternOffset: number,
  globalTuning?: DrumPattern['tuning'],
): DrumPattern {
  const patternLength = clamp(bytes[patternOffset + 1] || 16, 1, 16);
  const kick: boolean[] = [];
  const snare: boolean[] = [];
  const closedHat: boolean[] = [];
  const openHat: boolean[] = [];
  const accent: number[] = [];

  for (let s = 0; s < 16; s++) {
    const stepBase = patternOffset + TR808_STEP_OFFSET_IN_PATTERN + s * TR808_STEP_INSTRUMENT_COUNT;
    const ac = bytes[stepBase] ?? 0;
    const bd = bytes[stepBase + 1] ?? 0;
    const sd = bytes[stepBase + 2] ?? 0;
    const oh = bytes[stepBase + 10] ?? 0;
    const ch = bytes[stepBase + 11] ?? 0;

    const active = s < patternLength;
    kick.push(active && isTriggerOn(bd));
    snare.push(active && isTriggerOn(sd));
    openHat.push(active && isTriggerOn(oh));
    closedHat.push(active && isTriggerOn(ch));
    accent.push(active && (ac === 0x02 || ac === 0x03) ? 127 : 0);
  }

  return {
    kick,
    snare,
    closedHat,
    openHat,
    accent,
    kitType: '808',
    tuning: globalTuning,
  };
}

function readTr808GlobalTuning(bytes: Uint8Array, offset: number): DrumPattern['tuning'] {
  return {
    kick: ((bytes[offset + 4] ?? 64) - 64) * 0.5,
    snare: ((bytes[offset + 7] ?? 64) - 64) * 0.5,
    closedHat: ((bytes[offset + 28] ?? 64) - 64) * 0.5,
    openHat: ((bytes[offset + 26] ?? 64) - 64) * 0.5,
  };
}

/**
 * Parse all 32 patterns from a DEVL "808 " device chunk payload.
 */
export function parseTr808DeviceChunk(
  bytes: Uint8Array,
  offset: number,
  size: number = TR808_CHUNK_PAYLOAD_SIZE,
): DrumPattern[] {
  if (size < TR808_PATTERN_DATA_OFFSET) return [];

  const tuning = readTr808GlobalTuning(bytes, offset);
  const patterns: DrumPattern[] = [];

  for (let p = 0; p < TR808_PATTERN_COUNT; p++) {
    const patternOffset = offset + TR808_PATTERN_DATA_OFFSET + p * TR808_PATTERN_SIZE;
    if (patternOffset + TR808_PATTERN_SIZE > offset + size) break;
    patterns.push(parseTr808Pattern(bytes, patternOffset, tuning));
  }

  return patterns;
}

function parseTr909Pattern(
  bytes: Uint8Array,
  patternOffset: number,
  globalTuning?: DrumPattern['tuning'],
): DrumPattern {
  const patternLength = clamp(bytes[patternOffset + 1] || 16, 1, 16);
  const kick: boolean[] = [];
  const snare: boolean[] = [];
  const closedHat: boolean[] = [];
  const openHat: boolean[] = [];
  const accent: number[] = [];

  for (let s = 0; s < 16; s++) {
    const stepBase = patternOffset + TR909_STEP_OFFSET_IN_PATTERN + s * TR909_STEP_INSTRUMENT_COUNT;
    const ac = bytes[stepBase] ?? 0;
    const bd = bytes[stepBase + 1] ?? 0;
    const sd = bytes[stepBase + 2] ?? 0;
    const oh = bytes[stepBase + 10] ?? 0;
    const ch = bytes[stepBase + 9] ?? 0;

    const active = s < patternLength;
    kick.push(active && isTriggerOn(bd));
    snare.push(active && isTriggerOn(sd));
    openHat.push(active && isTriggerOn(oh));
    closedHat.push(active && isTriggerOn(ch));
    accent.push(active && (ac === 0x02 || ac === 0x03) ? 127 : 0);
  }

  return {
    kick,
    snare,
    closedHat,
    openHat,
    accent,
    kitType: '909',
    tuning: globalTuning,
  };
}

/**
 * Parse all 32 patterns from a DEVL "909 " device chunk payload.
 */
export function parseTr909DeviceChunk(
  bytes: Uint8Array,
  offset: number,
  size: number = TR909_CHUNK_PAYLOAD_SIZE,
): DrumPattern[] {
  if (size < TR909_PATTERN_DATA_OFFSET) return [];

  const tuning: DrumPattern['tuning'] = {
    kick: ((bytes[offset + 4] ?? 64) - 64) * 0.5,
    snare: ((bytes[offset + 8] ?? 64) - 64) * 0.5,
    closedHat: ((bytes[offset + 23] ?? 64) - 64) * 0.5,
    openHat: ((bytes[offset + 24] ?? 64) - 64) * 0.5,
  };

  const patterns: DrumPattern[] = [];

  for (let p = 0; p < TR909_PATTERN_COUNT; p++) {
    const patternOffset = offset + TR909_PATTERN_DATA_OFFSET + p * TR909_PATTERN_SIZE;
    if (patternOffset + TR909_PATTERN_SIZE > offset + size) break;
    patterns.push(parseTr909Pattern(bytes, patternOffset, tuning));
  }

  return patterns;
}

/** Alias for pattern B (same layout as A in DEVL). */
export type Tb303PatternFromDevl = Tb303PatternA | Tb303PatternB;

// ── MIXR / PCF (DEVL effects chunks, RBS42) ─────────────────────────────────

export const MIXR_CHUNK_PAYLOAD_SIZE = 64;
export const PCF_CHUNK_PAYLOAD_SIZE = 12;

/** MIXR.pcf_id — which device receives PCF (pattern mode routing). */
export const MIXR_PCF_DEVICE_ID = {
  OFF: 0x00,
  TB303_1: 0x02,
  TB303_2: 0x03,
  TR808: 0x04,
  TR909: 0x05,
} as const;

export interface DevlPcfChunkData {
  enabled: boolean;
  cutoff: number;
  resonance: number;
  envAmount: number;
  /** PCF wave / pattern preset index (0–55, RBS42). */
  wave: number;
  decay: number;
  filterType: 'lp' | 'bp';
}

/**
 * Parse DEVL `PCF ` chunk (12 bytes).
 * RBS42: enabled, frequency, resonance, amount, wave, decay, mode (BP/LP).
 */
export function parseDevlPcfChunk(bytes: Uint8Array, offset: number, size = PCF_CHUNK_PAYLOAD_SIZE): DevlPcfChunkData {
  const enabled = (bytes[offset] ?? 0) !== 0;
  return {
    enabled,
    cutoff: clamp(bytes[offset + 1] ?? 64, 0, 127),
    resonance: clamp(bytes[offset + 2] ?? 48, 0, 127),
    envAmount: clamp(bytes[offset + 3] ?? 64, 0, 127),
    wave: clamp(bytes[offset + 4] ?? 0, 0, 55),
    decay: clamp(bytes[offset + 5] ?? 48, 0, 127),
    filterType: (bytes[offset + 6] ?? 0) === 1 ? 'lp' : 'bp',
  };
}

/** Map MIXR `pcf_id` to PCF routing targets. */
export function mixrPcfIdToTargets(pcfDeviceId: number): PcfSettings['target'] {
  switch (pcfDeviceId) {
    case MIXR_PCF_DEVICE_ID.TB303_1:
      return { tb303A: true, tb303B: false, drums: false };
    case MIXR_PCF_DEVICE_ID.TB303_2:
      return { tb303A: false, tb303B: true, drums: false };
    case MIXR_PCF_DEVICE_ID.TR808:
    case MIXR_PCF_DEVICE_ID.TR909:
      return { tb303A: false, tb303B: false, drums: true };
    default:
      // PCF enabled with no explicit route — default to synth A (common ReBirth default)
      return { tb303A: true, tb303B: false, drums: false };
  }
}

/**
 * Expand ReBirth PCF "wave" preset index to a 16-step modulation pattern.
 * IFF DEVL stores wave index (0–55), not per-step bytes (legacy fixed-offset has 16 steps).
 */
export function pcfWaveToStepPattern(waveIndex: number, amount: number, cutoff: number): number[] {
  const amountN = clamp(amount, 0, 127);
  const base = clamp(cutoff, 0, 127);
  const pattern: number[] = [];
  const shape = waveIndex % 8;

  for (let i = 0; i < 16; i++) {
    const t = i / 15;
    let mod: number;
    switch (shape) {
      case 0:
        mod = amountN;
        break;
      case 1:
        mod = amountN * t;
        break;
      case 2:
        mod = amountN * (1 - t);
        break;
      case 3:
        mod = amountN * (0.5 + 0.5 * Math.sin(t * Math.PI));
        break;
      case 4:
        mod = i % 2 === 0 ? amountN : Math.round(amountN * 0.25);
        break;
      case 5:
        mod = amountN * (1 - Math.abs(t - 0.5) * 2);
        break;
      default:
        mod = ((waveIndex * 11 + i * 8 + base) % 128);
        break;
    }
    pattern.push(clamp(Math.round(mod), 0, 127));
  }
  return pattern;
}

/** Build full {@link PcfSettings} from DEVL MIXR + PCF chunks. */
export function buildPcfSettingsFromDevl(
  pcf: DevlPcfChunkData,
  mixrPcfDeviceId: number,
): PcfSettings {
  const targets = pcf.enabled
    ? (mixrPcfDeviceId === MIXR_PCF_DEVICE_ID.OFF
      ? mixrPcfIdToTargets(MIXR_PCF_DEVICE_ID.TB303_1)
      : mixrPcfIdToTargets(mixrPcfDeviceId))
    : { tb303A: false, tb303B: false, drums: false };

  return {
    enabled: pcf.enabled,
    filterType: pcf.filterType,
    cutoff: pcf.cutoff,
    resonance: pcf.resonance,
    envAmount: pcf.envAmount,
    decay: pcf.decay,
    pattern: pcf.enabled
      ? pcfWaveToStepPattern(pcf.wave, pcf.envAmount, pcf.cutoff)
      : Array(16).fill(0),
    waveIndex: pcf.wave,
    target: targets,
  };
}

/** Parse MIXR chunk and return `pcf_id` routing byte. */
export function parseDevlMixrPcfDeviceId(bytes: Uint8Array, offset: number): number {
  return bytes[offset + 2] ?? 0;
}

/** Disabled PCF placeholder (not the dev mock sweep). */
export function disabledPcfSettings(): PcfSettings {
  return {
    enabled: false,
    filterType: 'lp',
    cutoff: 64,
    resonance: 48,
    envAmount: 64,
    decay: 48,
    pattern: Array(16).fill(0),
    target: { tb303A: false, tb303B: false, drums: false },
  };
}

/**
 * IFF CAT RB40 byte builders for RBS export (RBS42-aligned).
 * Shared between RbsExporter and test fixtures.
 */

import type { DrumPattern, Tb303Step } from './types';
import {
  TB303_CHUNK_PAYLOAD_SIZE,
  TB303_FLAG_ACCENT,
  TB303_FLAG_NOTE,
  TB303_FLAG_SLIDE,
  TB303_PATTERN_COUNT,
  TB303_PATTERN_DATA_OFFSET,
  TB303_PATTERN_SIZE,
  TB303_STEP_OFFSET_IN_PATTERN,
  TB303_STEP_SIZE,
  TR808_CHUNK_PAYLOAD_SIZE,
  TR808_PATTERN_COUNT,
  TR808_PATTERN_DATA_OFFSET,
  TR808_PATTERN_SIZE,
  TR808_STEP_INSTRUMENT_COUNT,
  TR808_STEP_OFFSET_IN_PATTERN,
  TR909_CHUNK_PAYLOAD_SIZE,
} from './devlLayout';
import { TRKL_TRACK_COUNT } from './trakExport';

export function writeU32BE(val: number): Uint8Array {
  const buf = new Uint8Array(4);
  new DataView(buf.buffer).setUint32(0, val >>> 0, false);
  return buf;
}

export function writeAscii(s: string, len = s.length): Uint8Array {
  const buf = new Uint8Array(len);
  for (let i = 0; i < Math.min(len, s.length); i++) {
    buf[i] = s.charCodeAt(i);
  }
  return buf;
}

export function wrapIffChunk(id: string, payload: Uint8Array): Uint8Array {
  const chunk = new Uint8Array(8 + payload.length + (payload.length % 2));
  chunk.set(writeAscii(id, 4), 0);
  chunk.set(writeU32BE(payload.length), 4);
  chunk.set(payload, 8);
  return chunk;
}

export function wrapNestedCat(formType: string, innerChunks: Uint8Array[]): Uint8Array {
  const innerSize = 4 + innerChunks.reduce((sum, c) => sum + c.length, 0);
  const cat = new Uint8Array(8 + innerSize);
  cat.set(writeAscii('CAT ', 4), 0);
  cat.set(writeU32BE(innerSize), 4);
  cat.set(writeAscii(formType, 4), 8);
  let pos = 12;
  for (const chunk of innerChunks) {
    cat.set(chunk, pos);
    pos += chunk.length;
  }
  return cat;
}

/** Encode one TB-303 step for DEVL "303 " chunk (pitch + RBS42 flags). */
export function encodeDevlTb303Step(step: Tb303Step): [number, number] {
  if (step.note < 0) {
    const flags = (step.accent ? TB303_FLAG_ACCENT : 0) | (step.slide ? TB303_FLAG_SLIDE : 0);
    return [0, flags];
  }
  const flags =
    TB303_FLAG_NOTE |
    (step.slide ? TB303_FLAG_SLIDE : 0) |
    (step.accent ? TB303_FLAG_ACCENT : 0);
  return [step.note % 12, flags];
}

export interface Tb303DeviceParams {
  cutoff?: number;
  resonance?: number;
  envMod?: number;
  decay?: number;
  accent?: number;
  waveform?: 0 | 1;
}

function normalizeTb303PatternSteps(patternSteps: Tb303Step[] = []): Tb303Step[] {
  if (patternSteps.length >= 16) {
    return patternSteps.slice(0, 16);
  }
  return [
    ...patternSteps,
    ...Array.from({ length: 16 - patternSteps.length }, (_, i) => ({
      index: patternSteps.length + i,
      note: -1,
      octave: 3,
      accent: false,
      slide: false,
      tie: false,
      gate: 100,
    })),
  ];
}

function isTb303StepArray(value: Tb303Step[] | Tb303Step[][]): value is Tb303Step[] {
  return value.length === 0 || !Array.isArray(value[0]);
}

/** Build RBS42-aligned "303 " device chunk payload (1097 bytes). Supports 1 or many pattern slots. */
export function buildDevl303ChunkPayload(
  patternSteps: Tb303Step[] | Tb303Step[][] = [],
  params: Tb303DeviceParams = {},
): Uint8Array {
  const payload = new Uint8Array(TB303_CHUNK_PAYLOAD_SIZE);
  payload[0] = 1;
  payload[3] = params.cutoff ?? 90;
  payload[4] = params.resonance ?? 64;
  payload[5] = params.envMod ?? 64;
  payload[6] = params.decay ?? 48;
  payload[7] = params.accent ?? 80;
  payload[8] = params.waveform ?? 0;

  const patterns: Tb303Step[][] = isTb303StepArray(patternSteps)
    ? [normalizeTb303PatternSteps(patternSteps)]
    : patternSteps.map((p) => normalizeTb303PatternSteps(p));

  const patternCount = Math.min(TB303_PATTERN_COUNT, Math.max(1, patterns.length));
  for (let p = 0; p < patternCount; p++) {
    const steps = patterns[p] ?? normalizeTb303PatternSteps([]);
    const patternOffset = TB303_PATTERN_DATA_OFFSET + p * TB303_PATTERN_SIZE;
    payload[patternOffset] = 0;
    payload[patternOffset + 1] = 16;
    for (let s = 0; s < 16; s++) {
      const stepOffset = patternOffset + TB303_STEP_OFFSET_IN_PATTERN + s * TB303_STEP_SIZE;
      const [pitch, flags] = encodeDevlTb303Step(steps[s]);
      payload[stepOffset] = pitch;
      payload[stepOffset + 1] = flags;
    }
  }

  return payload;
}

export function buildDevlPcfChunkPayload(options: {
  enabled?: boolean;
  cutoff?: number;
  resonance?: number;
  envAmount?: number;
  wave?: number;
  decay?: number;
  filterType?: 'lp' | 'bp';
} = {}): Uint8Array {
  const payload = new Uint8Array(12);
  payload[0] = options.enabled === false ? 0 : 1;
  payload[1] = options.cutoff ?? 80;
  payload[2] = options.resonance ?? 40;
  payload[3] = options.envAmount ?? 60;
  payload[4] = options.wave ?? 1;
  payload[5] = options.decay ?? 40;
  payload[6] = options.filterType === 'lp' ? 1 : 0;
  return payload;
}

export function buildDevlMixrChunk(pcfDeviceId = 0): Uint8Array {
  const payload = new Uint8Array(64);
  payload[2] = pcfDeviceId;
  return payload;
}

function writeDrumPatternTo808Payload(
  payload: Uint8Array,
  patternIndex: number,
  dp: DrumPattern,
): void {
  const patternOffset = TR808_PATTERN_DATA_OFFSET + patternIndex * TR808_PATTERN_SIZE;
  payload[patternOffset + 1] = 16;
  for (let s = 0; s < 16; s++) {
    const stepBase = patternOffset + TR808_STEP_OFFSET_IN_PATTERN + s * TR808_STEP_INSTRUMENT_COUNT;
    if (dp.kick[s]) payload[stepBase + 1] = 0x01;
    if (dp.snare[s]) payload[stepBase + 2] = 0x01;
    if (dp.openHat[s]) payload[stepBase + 10] = 0x01;
    if (dp.closedHat[s]) payload[stepBase + 11] = 0x01;
  }
}

function writeDrumPatternTo909Payload(
  payload: Uint8Array,
  patternIndex: number,
  dp: DrumPattern,
): void {
  const patternOffset = TR808_PATTERN_DATA_OFFSET + patternIndex * TR808_PATTERN_SIZE;
  payload[patternOffset + 1] = 16;
  for (let s = 0; s < 16; s++) {
    const stepBase = patternOffset + TR808_STEP_OFFSET_IN_PATTERN + s * TR808_STEP_INSTRUMENT_COUNT;
    if (dp.kick[s]) payload[stepBase + 1] = 0x01;
    if (dp.snare[s]) payload[stepBase + 2] = 0x01;
    if (dp.openHat[s]) payload[stepBase + 10] = 0x01;
    if (dp.closedHat[s]) payload[stepBase + 9] = 0x01;
  }
}

/** Build TR-808 DEVL chunk from one or many DrumPatterns. */
export function buildDevl808ChunkFromPattern(dp: DrumPattern | DrumPattern[]): Uint8Array {
  const payload = new Uint8Array(TR808_CHUNK_PAYLOAD_SIZE);
  payload[0] = 1;
  const patterns = Array.isArray(dp) ? dp : [dp];
  const patternCount = Math.min(TR808_PATTERN_COUNT, Math.max(1, patterns.length));
  for (let p = 0; p < patternCount; p++) {
    writeDrumPatternTo808Payload(payload, p, patterns[p]);
  }
  return payload;
}

/** Build TR-909 DEVL chunk from one or many DrumPatterns. */
export function buildDevl909ChunkFromPattern(dp: DrumPattern | DrumPattern[]): Uint8Array {
  const payload = new Uint8Array(TR909_CHUNK_PAYLOAD_SIZE);
  payload[0] = 1;
  const patterns = Array.isArray(dp) ? dp : [dp];
  const patternCount = Math.min(TR808_PATTERN_COUNT, Math.max(1, patterns.length));
  for (let p = 0; p < patternCount; p++) {
    writeDrumPatternTo909Payload(payload, p, patterns[p]);
  }
  return payload;
}

export function buildDevlCatalogChunk(options: {
  tb303ASteps?: Tb303Step[] | Tb303Step[][];
  tb303BSteps?: Tb303Step[] | Tb303Step[][];
  tb303AParams?: Tb303DeviceParams;
  tb303BParams?: Tb303DeviceParams;
  drumPattern?: DrumPattern | DrumPattern[];
  drumKit?: '808' | '909';
  include303B?: boolean;
  pcf?: Parameters<typeof buildDevlPcfChunkPayload>[0];
  mixrPcfId?: number;
} = {}): Uint8Array {
  const {
    tb303ASteps,
    tb303BSteps,
    tb303AParams,
    tb303BParams,
    drumPattern,
    drumKit = '808',
    include303B = true,
    pcf,
    mixrPcfId = 0,
  } = options;

  const emptyDrum: DrumPattern = {
    kick: Array(16).fill(false),
    snare: Array(16).fill(false),
    closedHat: Array(16).fill(false),
    openHat: Array(16).fill(false),
    accent: Array(16).fill(0),
    kitType: drumKit,
  };

  const inner: Uint8Array[] = [
    wrapIffChunk('MIXR', buildDevlMixrChunk(mixrPcfId)),
    wrapIffChunk('DELY', new Uint8Array(8)),
    wrapIffChunk('PCF ', buildDevlPcfChunkPayload(pcf)),
    wrapIffChunk('DIST', new Uint8Array(8)),
    wrapIffChunk('COMP', new Uint8Array(8)),
    wrapIffChunk('303 ', buildDevl303ChunkPayload(tb303ASteps, tb303AParams)),
  ];
  if (include303B) {
    inner.push(wrapIffChunk('303 ', buildDevl303ChunkPayload(tb303BSteps, tb303BParams)));
  }
  const drums = drumPattern ?? emptyDrum;
  if (drumKit === '909') {
    inner.push(wrapIffChunk('808 ', new Uint8Array(TR808_CHUNK_PAYLOAD_SIZE)));
    inner.push(wrapIffChunk('909 ', buildDevl909ChunkFromPattern(drums)));
  } else {
    inner.push(wrapIffChunk('808 ', buildDevl808ChunkFromPattern(drums)));
    inner.push(wrapIffChunk('909 ', new Uint8Array(TR909_CHUNK_PAYLOAD_SIZE)));
  }
  return wrapNestedCat('DEVL', inner);
}

export function buildTrakChunkPayload(
  events: Array<{ delta: number; ctrl: number; value: number }> = [],
): Uint8Array {
  const trakPayload = new Uint8Array(4 + events.length * 4);
  const dv = new DataView(trakPayload.buffer);
  dv.setUint32(0, events.length, true);
  for (let i = 0; i < events.length; i++) {
    const offset = 4 + i * 4;
    dv.setUint16(offset, events[i].delta, true);
    trakPayload[offset + 2] = events[i].ctrl;
    trakPayload[offset + 3] = events[i].value;
  }
  return trakPayload;
}

function wrapTrakChunk(events: Array<{ delta: number; ctrl: number; value: number }>): Uint8Array {
  return wrapIffChunk('TRAK', buildTrakChunkPayload(events));
}

export function buildTrklChunk(
  trackEventLists: Array<{ events: Array<{ delta: number; ctrl: number; value: number }> }> = [],
): Uint8Array {
  const lists = trackEventLists.length > 0
    ? trackEventLists
    : Array.from({ length: TRKL_TRACK_COUNT }, () => ({ events: [] as Array<{ delta: number; ctrl: number; value: number }> }));

  const trakChunks = lists.map((t) => wrapTrakChunk(t.events));
  const trklInnerSize = 4 + trakChunks.reduce((sum, c) => sum + c.length, 0);
  const trklChunk = new Uint8Array(8 + trklInnerSize);
  trklChunk.set(writeAscii('CAT ', 4), 0);
  trklChunk.set(writeU32BE(trklInnerSize), 4);
  trklChunk.set(writeAscii('TRKL', 4), 8);
  let pos = 12;
  for (const chunk of trakChunks) {
    trklChunk.set(chunk, pos);
    pos += chunk.length;
  }
  return trklChunk;
}

export interface IffRbsFileOptions {
  playMode?: 0 | 1;
  tempoBpm?: number;
  shuffle?: number;
  loopStartBars?: number;
  loopEndBars?: number;
  headVersionString?: string;
  songName?: string;
  devl?: Parameters<typeof buildDevlCatalogChunk>[0];
  trakTracks?: Array<{ events: Array<{ delta: number; ctrl: number; value: number }> }>;
}

/** Assemble a complete IFF CAT RB40 `.rbs` file. */
export function buildIffRbsFile(options: IffRbsFileOptions = {}): Uint8Array {
  const {
    playMode = 0,
    tempoBpm = 120,
    shuffle = 64,
    loopStartBars = 0,
    loopEndBars = 1,
    headVersionString = 'ReBirth RB-338 v2.0',
    songName,
    devl = {},
    trakTracks,
  } = options;

  const headPayload = new Uint8Array(256);
  const headStr = songName
    ? `${headVersionString}\0${songName}`.slice(0, 255)
    : headVersionString;
  for (let i = 0; i < headStr.length; i++) headPayload[i] = headStr.charCodeAt(i);

  const globPayload = new Uint8Array(512);
  globPayload[0] = playMode;
  globPayload[1] = 0;
  globPayload.set(writeU32BE(Math.round(tempoBpm * 1000)), 2);
  globPayload.set(writeU32BE(loopStartBars * 768), 6);
  globPayload.set(writeU32BE(loopEndBars * 768), 10);
  globPayload[14] = shuffle;

  const headChunk = wrapIffChunk('HEAD', headPayload);
  const globChunk = wrapIffChunk('GLOB', globPayload);
  const devlCatChunk = buildDevlCatalogChunk(devl);
  const trklChunk = buildTrklChunk(trakTracks);

  const innerChunks = [headChunk, globChunk, devlCatChunk, trklChunk];
  const rootPayloadSize = 4 + innerChunks.reduce((sum, c) => sum + c.length, 0);
  const file = new Uint8Array(8 + rootPayloadSize);
  let pos = 0;
  file.set(writeAscii('CAT ', 4), pos); pos += 4;
  file.set(writeU32BE(rootPayloadSize), pos); pos += 4;
  file.set(writeAscii('RB40', 4), pos); pos += 4;
  for (const chunk of innerChunks) {
    file.set(chunk, pos);
    pos += chunk.length;
  }
  return file;
}

/**
 * RBS to Hyphon Importer
 *
 * Converts parsed RBS data into Hyphon's internal song format.
 * This is the bridge between the RBS parser and Hyphon's sequencer.
 *
 * Architecture:
 * - RbsParser → RawRbsData (format-specific)
 * - RbsImporter → HyphonSong (internal format)
 * - Hyphon App ← consumes HyphonSong
 *
 * Enhancements:
 * - 16→32 step expansion with slide/accent preservation
 * - PCF (Pattern Controlled Filter) to automation conversion
 * - Full automation lane extraction
 * - Enhanced parameter mapping with exponential curves
 * - Drum kit mapping (808 vs 909)
 * - Detailed import reporting
 */

