 *
 * `SynthParams` (partA/partB) names them `filterCutoff` / `filterResonance`;
 * `Bass2Params` names them `cutoff` / `resonance`.  The scheduler accepts both
 * spellings, but emitting the target's own key keeps lanes bindable to the
 * hardware knobs for that track.
 */
function filterParamForTarget(
  target: HyphonAutomationLane['target'],
  knob: 'cutoff' | 'resonance',
): string {
  if (target === 'bass2') return knob;
  return knob === 'cutoff' ? 'filterCutoff' : 'filterResonance';
}

/** Display label for a resolved TB-303 lane target. */
function trackLabelForTarget(target: HyphonAutomationLane['target']): string {
  switch (target) {
    case 'synthA': return 'TB-303 A';
    case 'synthB': return 'TB-303 B';
    case 'bass2': return 'Bass 2';
    default: return String(target);
  }
}

/** Convert PCF modulation pattern to automation points. */
export function convertPcfPatternToPoints(
  ctx: ImporterContext,
  pattern: number[],
  baseValue: number,
): [number, number][] {
  const points: [number, number][] = [];
  const numSteps = ctx.options.expandTo32Steps ? 32 : pattern.length;

  for (let i = 0; i < numSteps; i++) {
    const sourceIndex = i % pattern.length;
    const value = pattern[sourceIndex];
    const normalizedValue = Math.min(1.0, (value / 127) * (baseValue / 8000));

    if (ctx.options.quantizeTo16th) {
      points.push([i, normalizedValue]);
    } else {
      points.push([i, normalizedValue]);
    }
  }

  return points;
}

/** Convert PCF settings to Hyphon automation lanes. */
export function convertPcfToAutomation(
  ctx: ImporterContext,
  pcf: PcfSettings,
): HyphonAutomationLane[] {
  const automation: HyphonAutomationLane[] = [];

  if (!pcf.enabled) {
    return automation;
  }

  const baseCutoffHz = convertCutoffToHz(pcf.cutoff);

  if (pcf.target.tb303A) {
    const target = resolveTb303Target(ctx.options.tb303ATarget);
    automation.push({
      target,
      parameter: filterParamForTarget(target, 'cutoff'),
      name: `PCF → ${trackLabelForTarget(target)} Filter`,
      points: convertPcfPatternToPoints(ctx, pcf.pattern, baseCutoffHz),
      interpolation: ctx.options.interpolateAutomation ? 'smooth' : 'linear',
      originalRange: [0, 127],
    });
  }

  if (pcf.target.tb303B) {
    const target = resolveTb303Target(ctx.options.tb303BTarget);
    automation.push({
      target,
      parameter: filterParamForTarget(target, 'cutoff'),
      name: `PCF → ${trackLabelForTarget(target)} Filter`,
      points: convertPcfPatternToPoints(ctx, pcf.pattern, baseCutoffHz),
      interpolation: ctx.options.interpolateAutomation ? 'smooth' : 'linear',
      originalRange: [0, 127],
    });
  }

  // `pcf.target.drums` is intentionally not converted to a lane: Hyphon has no
  // per-drum-bus PCF endpoint, so a `master.drumPcfModulation` lane would only
  // schedule into a no-op.  The flag is preserved losslessly in
  // `song.rbsMetadata.pcfSettings` (and in `song.pcfFilter` when
  // `importPcfAsFilter` is set) for re-export and future routing.

  return automation;
}

/** Generate per-step accent and slide automation lanes from TB-303 step data. */
export function generateAccentSlideAutomation(
  ctx: ImporterContext,
  steps: Tb303Step[],
  target: HyphonAutomationLane['target'],
  baseAccentNorm: number,
): HyphonAutomationLane[] {
  const numSteps = ctx.options.expandTo32Steps ? 32 : steps.length;
  const accentPoints: [number, number][] = [];
  const slidePoints: [number, number][] = [];
  let hasAccent = false;
  let hasSlide = false;

  for (let i = 0; i < numSteps; i++) {
    const src = steps[i % steps.length];
    accentPoints.push([i, src.accent ? 1.0 : clampNormalized(baseAccentNorm)]);
    slidePoints.push([i, src.slide ? 1.0 : 0.0]);
    if (src.accent) hasAccent = true;
    if (src.slide) hasSlide = true;
  }

  const trackLabel = trackLabelForTarget(target);

  const lanes: HyphonAutomationLane[] = [];

  if (hasAccent) {
    lanes.push({
      target,
      parameter: 'accent',
      name: `${trackLabel} Accent`,
      points: accentPoints,
      interpolation: 'step',
      originalRange: [0, 1],
    });
  }

  if (hasSlide) {
    lanes.push({
      target,
      parameter: 'slide',
      name: `${trackLabel} Slide`,
      points: slidePoints,
      interpolation: 'step',
      originalRange: [0, 1],
    });
  }

  return lanes;
}

/** Convert automation points to normalized Hyphon format. */
export function convertAutomationPoints(
  ctx: ImporterContext,
  points: [number, number][],
  range: [number, number],
  _interpolation: 'step' | 'linear' | 'smooth',
): [number, number][] {
  const [minVal, maxVal] = range;
  const rangeSpan = maxVal - minVal || 1;
  const numSteps = ctx.options.expandTo32Steps ? 32 : 16;

  const convertedPoints: [number, number][] = [];

  for (const [stepIndex, value] of points) {
    const normalizedValue = clampNormalized((value - minVal) / rangeSpan);
    const finalStep = ctx.options.quantizeTo16th
      ? Math.round(stepIndex)
      : stepIndex;

    if (finalStep >= 0 && finalStep < numSteps) {
      convertedPoints.push([finalStep, normalizedValue]);
    }
  }

  convertedPoints.sort((a, b) => a[0] - b[0]);

  const uniquePoints: [number, number][] = [];
  let lastStep = -1;
  for (const point of convertedPoints) {
    if (point[0] !== lastStep) {
      uniquePoints.push(point);
      lastStep = point[0];
    }
  }

  return uniquePoints;
}

/** Convert a single automation lane. */
export function convertAutomationLane(
  ctx: ImporterContext,
  lane: AutomationLane,
): HyphonAutomationLane | null {
  let target: HyphonAutomationLane['target'];
  let parameter: string;
  let name: string;

  // TB-303 lanes follow the same routing option as the notes for that voice.
  const tb303A = resolveTb303Target(ctx.options.tb303ATarget);
  const tb303B = resolveTb303Target(ctx.options.tb303BTarget);

  switch (lane.parameter) {
    case 'tb303Acutoff':
      target = tb303A;
      parameter = filterParamForTarget(tb303A, 'cutoff');
      name = lane.name || `${trackLabelForTarget(tb303A)} Cutoff`;
      break;
    case 'tb303Bcutoff':
      target = tb303B;
      parameter = filterParamForTarget(tb303B, 'cutoff');
      name = lane.name || `${trackLabelForTarget(tb303B)} Cutoff`;
      break;
    case 'tb303Aresonance':
      target = tb303A;
      parameter = filterParamForTarget(tb303A, 'resonance');
      name = lane.name || `${trackLabelForTarget(tb303A)} Resonance`;
      break;
    case 'tb303Bresonance':
      target = tb303B;
      parameter = filterParamForTarget(tb303B, 'resonance');
      name = lane.name || `${trackLabelForTarget(tb303B)} Resonance`;
      break;
    case 'tb303Adecay':
      target = tb303A;
      parameter = 'decay';
      name = lane.name || `${trackLabelForTarget(tb303A)} Decay`;
      break;
    case 'tb303Bdecay':
      target = tb303B;
      parameter = 'decay';
      name = lane.name || `${trackLabelForTarget(tb303B)} Decay`;
      break;
    case 'pcfCutoff':
      target = 'master';
      // Must match the name AutomationScheduler._applyPcfParam dispatches on.
      parameter = 'pcfCutoff';
      name = lane.name || 'PCF Cutoff';
      break;
    case 'pcfResonance':
      target = 'master';
      parameter = 'pcfResonance';
      name = lane.name || 'PCF Resonance';
      break;
    case 'pcfEnvAmount':
      target = 'master';
      parameter = 'pcfEnvAmount';
      name = lane.name || 'PCF Env Amount';
      break;
    // 'tempo', 'swing' and 'masterVolume' are deliberately dropped: the
    // scheduler has no audio-clock endpoint for them (tempo/swing are transport
    // state applied from `song.tempo` / `song.swing`; master volume has no node
    // wired into AutomationScheduler), so a lane would schedule into a no-op.
    // The values remain available in `song.rbsMetadata.automation`.
    default:
      return null;
  }

  const points = convertAutomationPoints(ctx, lane.points, lane.range, lane.interpolation);

  return {
    target,
    parameter,
    name,
    points,
    interpolation: ctx.options.interpolateAutomation ? 'smooth' : lane.interpolation,
    originalRange: lane.range,
  };
}

/** Convert RBS automation lanes to Hyphon format. */
export function convertAutomationLanes(
  ctx: ImporterContext,
  lanes: AutomationLane[],
): HyphonAutomationLane[] {
  const hyphonLanes: HyphonAutomationLane[] = [];

  for (const lane of lanes) {
    const converted = convertAutomationLane(ctx, lane);
    if (converted) {
      hyphonLanes.push(converted);
    }
  }

  return hyphonLanes;
}

import type { RawRbsData, Tb303Step } from '../types';
import type { Pattern, PartSequence, Note } from '../../../types';
import { midiToNote } from '../../../utils/musicTheory';
import { convertAccentToBoost } from './parameterCurves';
import type { ImporterContext } from './importerContext';

/** Get default note for drum type. */
function getDefaultDrumNote(drumType: string): string {
  switch (drumType) {
    case 'kick': return 'C2';
    case 'snare': return 'D2';
    case 'closedHat': return 'F#2';
    case 'openHat': return 'A#2';
    default: return 'C3';
  }
}

/** Convert TB-303 pattern steps to Hyphon PartSequence. */
export function convertTb303ToPartSequence(
  ctx: ImporterContext,
  tb303: { steps: Tb303Step[] },
  numSteps: number,
  _isBassTrack: boolean,
): PartSequence {
  const steps: (Note | null)[] = Array(numSteps).fill(null);

  for (let i = 0; i < tb303.steps.length && i < numSteps; i++) {
    const step = tb303.steps[i];

    if (step.note === -1 || step.tie) {
      steps[i] = null;
      continue;
    }

    const midiNote = (step.octave + 1) * 12 + step.note;
    const noteName = midiToNote(midiNote);

    steps[i] = {
      note: noteName,
      velocity: step.accent ? 1.0 : 0.8,
      length: step.slide ? 2 : 1,
      slide: step.slide,
      timbre: 0.5,
    };

    if (step.slide) ctx.stepStats.slideCount++;
    if (step.accent) ctx.stepStats.accentCount++;
    if (step.tie) ctx.stepStats.tieCount++;
  }

  if (numSteps === 32 && tb303.steps.length === 16) {
    for (let i = 16; i < 32; i++) {
      const sourceStep = steps[i - 16];
      if (sourceStep) {
        steps[i] = { ...sourceStep };
      }
    }
  }

  ctx.stepStats.totalSteps += steps.length;
  return { steps };
}

/** Expand 16-step RBS pattern to 32-step Hyphon pattern. */
export function expandPattern16To32(
  ctx: ImporterContext,
  steps16: Tb303Step[],
  _isBassTrack: boolean,
): PartSequence {
  const steps32: (Note | null)[] = Array(32).fill(null);

  for (let i = 0; i < 16; i++) {
    const sourceStep = steps16[i];

    if (sourceStep.tie) {
      ctx.stepStats.tieCount++;
      continue;
    }

    if (sourceStep.note === -1) {
      continue;
    }

    const targetIndex1 = i * 2;

    let tieCount = 0;
    while (i + 1 + tieCount < 16 && steps16[i + 1 + tieCount].tie) {
      tieCount++;
      ctx.stepStats.tieCount++;
    }

    const midiNote = (sourceStep.octave + 1) * 12 + sourceStep.note;
    const noteName = midiToNote(midiNote);

    const baseVelocity = 0.8;
    const accentBoost = sourceStep.accent ? convertAccentToBoost(127) : 0;
    const velocity1 = Math.min(1.0, baseVelocity + accentBoost);

    if (sourceStep.slide) ctx.stepStats.slideCount++;
    if (sourceStep.accent) ctx.stepStats.accentCount++;

    if (sourceStep.slide) {
      steps32[targetIndex1] = {
        note: noteName,
        velocity: velocity1,
        length: 2,
        slide: true,
        timbre: 0.5,
      };
      steps32[targetIndex1 + 1] = null;
      continue;
    }

    const sustainSubSteps = tieCount > 0 ? (1 + tieCount) * 2 : 1;
    steps32[targetIndex1] = {
      note: noteName,
      velocity: velocity1,
      length: sustainSubSteps,
      slide: false,
      timbre: 0.5,
    };
  }

  ctx.stepStats.totalSteps += 32;
  return { steps: steps32 };
}

/** Convert drum pattern boolean array to PartSequence. */
export function convertDrumPattern(
  drumSteps: boolean[],
  numSteps: number,
  drumType: 'kick' | 'snare' | 'closedHat' | 'openHat',
): PartSequence {
  const steps: (Note | null)[] = Array(numSteps).fill(null);
  const defaultNote = getDefaultDrumNote(drumType);

  for (let i = 0; i < drumSteps.length && i < numSteps; i++) {
    if (drumSteps[i]) {
      steps[i] = {
        note: defaultNote,
        velocity: 1.0,
        length: 1,
        timbre: 0.5,
      };
    }
  }

  if (numSteps === 32 && drumSteps.length === 16) {
    for (let i = 16; i < 32; i++) {
      const sourceStep = steps[i - 16];
      if (sourceStep) {
        steps[i] = { ...sourceStep };
      }
    }
  }

  return { steps };
}

/** Convert RBS patterns to Hyphon Pattern. */
export function convertPattern(ctx: ImporterContext, raw: RawRbsData, _warnings: string[]): Pattern {
  const numSteps = ctx.options.expandTo32Steps ? 32 : raw.project.patternLength;
  const isExpansion = numSteps === 32 && raw.project.patternLength === 16;

  let partA: PartSequence;
  if (isExpansion) {
    partA = expandPattern16To32(
      ctx,
      raw.tb303PatternA.steps,
      ctx.options.tb303ATarget === 'bass2',
    );
  } else {
    partA = convertTb303ToPartSequence(
      ctx,
      raw.tb303PatternA,
      numSteps,
      ctx.options.tb303ATarget === 'bass2',
    );
  }

  let partB: PartSequence;
  if (isExpansion) {
    partB = expandPattern16To32(
      ctx,
      raw.tb303PatternB.steps,
      ctx.options.tb303BTarget === 'bass2',
    );
  } else {
    partB = convertTb303ToPartSequence(
      ctx,
      raw.tb303PatternB,
      numSteps,
      ctx.options.tb303BTarget === 'bass2',
    );
  }

  const kick = convertDrumPattern(raw.drums.kick, numSteps, 'kick');
  const snare = convertDrumPattern(raw.drums.snare, numSteps, 'snare');
  const closedHat = convertDrumPattern(raw.drums.closedHat, numSteps, 'closedHat');
  const openHat = convertDrumPattern(raw.drums.openHat, numSteps, 'openHat');

  const pattern: Pattern = {
    partA,
    partB,
    bass2: ctx.options.tb303ATarget === 'bass2' ? partA :
      ctx.options.tb303BTarget === 'bass2' ? partB :
        { steps: Array(numSteps).fill(null) },
    kick,
    snare,
    closedHat,
    openHat,
    sampler: Array(8).fill(null).map(() => ({ steps: Array(numSteps).fill(null) })),
  };

  return pattern;
}

import type { RawRbsData, HyphonSong, RbsSongData } from '../types';
import { TICKS_PER_BAR, TRAK_TRACK_INDEX } from '../types';
import { MAX_TRACK_PATTERN_SLOTS } from '../../../constants';
import { deriveActiveTrackSlotsFromStructure } from '../../../utils/trackStorageUtils';
import { isTrakParamAutomationEvent, isTrakPatternSelectEvent } from '../trakControllers';
import type { Pattern } from '../../../types';
import {
  convertTb303ToPartSequence,
  expandPattern16To32,
  convertDrumPattern,
} from './patternConversion';
import { buildTrackParamSlots } from './synthParams';
import type { ImporterContext } from './importerContext';

/** Find the active pattern index at a given tick position for a track. */
export function findActivePatternAtTick(
  track: RbsSongData['tracks'][number] | undefined,
  tick: number,
  maxSlots: number,
): number | null {
  if (!track || track.events.length === 0) return 0;

  let activePattern = 0;
  for (const evt of track.events) {
    if (evt.absoluteTicks > tick) break;
    if (isTrakPatternSelectEvent(evt.trackIndex, evt.controllerId, evt.eventKind)) {
      activePattern = evt.value;
    }
  }

  if (activePattern >= maxSlots) {
    return maxSlots - 1;
  }
  return activePattern;
}

/** Build songArrangement data from parsed IFF song data. */
export function buildSongArrangement(
  ctx: ImporterContext,
  raw: RawRbsData,
  warnings: string[],
): HyphonSong['songArrangement'] {
  const songData = raw.songData!;
  const numSteps = ctx.options.expandTo32Steps ? 32 : raw.project.patternLength;
  const isExpansion = numSteps === 32 && raw.project.patternLength === 16;

  const maxSlots = MAX_TRACK_PATTERN_SLOTS;
  const partASlots: (Pattern['partA'] | null)[] = Array(maxSlots).fill(null);
  const partBSlots: (Pattern['partB'] | null)[] = Array(maxSlots).fill(null);
  const bass2Slots: (Pattern['bass2'] | null)[] = Array(maxSlots).fill(null);
  const kickSlots: (Pattern['kick'] | null)[] = Array(maxSlots).fill(null);
  const snareSlots: (Pattern['snare'] | null)[] = Array(maxSlots).fill(null);
  const closedHatSlots: (Pattern['closedHat'] | null)[] = Array(maxSlots).fill(null);
  const openHatSlots: (Pattern['openHat'] | null)[] = Array(maxSlots).fill(null);

  const numA = Math.min(maxSlots, songData.patternBanks.tb303A.length);
  for (let i = 0; i < numA; i++) {
    const pat = songData.patternBanks.tb303A[i];
    if (isExpansion) {
      partASlots[i] = expandPattern16To32(ctx, pat.steps, false);
    } else {
      partASlots[i] = convertTb303ToPartSequence(ctx, pat, numSteps, false);
    }
  }

  const numB = Math.min(maxSlots, songData.patternBanks.tb303B.length);
  for (let i = 0; i < numB; i++) {
    const pat = songData.patternBanks.tb303B[i];
    if (isExpansion) {
      partBSlots[i] = expandPattern16To32(ctx, pat.steps, false);
    } else {
      partBSlots[i] = convertTb303ToPartSequence(ctx, pat, numSteps, false);
    }
    if (ctx.options.tb303BTarget === 'bass2') {
      if (isExpansion) {
        bass2Slots[i] = expandPattern16To32(ctx, pat.steps, true);
      } else {
        bass2Slots[i] = convertTb303ToPartSequence(ctx, pat, numSteps, true);
      }
    }
  }

  const drumBank = songData.patternBanks.drums808.length > 0
    ? songData.patternBanks.drums808
    : songData.patternBanks.drums909;
  const numDrums = Math.min(maxSlots, drumBank.length);
  for (let i = 0; i < numDrums; i++) {
    const dp = drumBank[i];
    kickSlots[i] = convertDrumPattern(dp.kick, numSteps, 'kick');
    snareSlots[i] = convertDrumPattern(dp.snare, numSteps, 'snare');
    closedHatSlots[i] = convertDrumPattern(dp.closedHat, numSteps, 'closedHat');
    openHatSlots[i] = convertDrumPattern(dp.openHat, numSteps, 'openHat');
  }

  const songStructure: Array<Record<string, number | null>> = [];
  const totalBars = Math.max(1, songData.totalLengthBars);

  const tb303_1Track = songData.tracks.find(t => t.trackIndex === TRAK_TRACK_INDEX.TB303_1);
  const tb303_2Track = songData.tracks.find(t => t.trackIndex === TRAK_TRACK_INDEX.TB303_2);
  const drumsTrack = songData.tracks.find(t => t.trackIndex === TRAK_TRACK_INDEX.TR808)
    || songData.tracks.find(t => t.trackIndex === TRAK_TRACK_INDEX.TR909);

  for (let bar = 0; bar < totalBars; bar++) {
    const barStart = bar * TICKS_PER_BAR;
    const barEnd = barStart + TICKS_PER_BAR;

    const partAIdx = findActivePatternAtTick(tb303_1Track, barStart, maxSlots);
    const partBIdx = findActivePatternAtTick(tb303_2Track, barStart, maxSlots);
    const drumIdx = findActivePatternAtTick(drumsTrack, barStart, maxSlots);

    songStructure.push({
      partA: partAIdx,
      partB: partBIdx,
      bass2: ctx.options.tb303BTarget === 'bass2' ? partBIdx : null,
      kick: drumIdx,
      snare: drumIdx,
      closedHat: drumIdx,
      openHat: drumIdx,
      sampler: null,
    });
  }

  const allTrakEvents = songData.tracks.flatMap((t) => t.events);
  const trakParamEvents = allTrakEvents.filter((ev) =>
    isTrakParamAutomationEvent(ev.trackIndex, ev.controllerId, ev.eventKind),
  );

  if (songData.usedPatternCount > maxSlots) {
    warnings.push(
      `Song uses ${songData.usedPatternCount} patterns but Hyphon supports ${maxSlots} slots. Excess patterns truncated.`,
    );
  }

  return {
    mode: songData.glob.playMode === 1 ? 'song' : 'pattern',
    trackStorage: {
      partA: partASlots,
      partB: partBSlots,
      bass2: bass2Slots,
      kick: kickSlots,
      snare: snareSlots,
      closedHat: closedHatSlots,
      openHat: openHatSlots,
    },
    trackParamStorage: {
      synthA: buildTrackParamSlots(songData.patternBanks.tb303A, maxSlots, false),
      synthB: buildTrackParamSlots(songData.patternBanks.tb303B, maxSlots, false),
      bass2: ctx.options.tb303BTarget === 'bass2'
        ? buildTrackParamSlots(songData.patternBanks.tb303B, maxSlots, true)
        : Array(maxSlots).fill(null),
    },
    songStructure,
    activeTrackSlots: deriveActiveTrackSlotsFromStructure(songStructure),
    loopStart: songData.glob.loopStart || undefined,
    loopEnd: songData.glob.loopEnd || undefined,
    trakEvents: allTrakEvents.length > 0 ? allTrakEvents : undefined,
    trakParamEvents: trakParamEvents.length > 0 ? trakParamEvents : undefined,
  };
}

import type {
  RawRbsData, HyphonSong, DetailedParameterMapping, Tb303PatternA,
} from '../types';
import type {
  SynthParams, KickParams, SnareParams, HatParams, Bass2Params, Waveform,
} from '../../../types';
import { clampNormalized, TB303_DEFAULT_SLIDE_TIME } from '../importer-types';
import { inferDevicesPresent, drumBankHasTriggers } from '../deviceInference';
import {
  convertCutoffToHz,
  convertResonance,
  convertDecayToSeconds,
  convertAccentToBoost,
  mapRange,
} from './parameterCurves';
import type { ImporterContext } from './importerContext';
import { DEFAULT_TB303_VOICE_FIELDS } from '../../../engines/TB303Models';

/** Persisted 303 voice defaults for RBS imports (ReBirth hardware → stock Hyphon voice). */
const RBS_TB303_VOICE_FIELDS = DEFAULT_TB303_VOICE_FIELDS;

/** Convert TB-303 params to Bass2Params (Open303 format). */
export function convertToBass2Params(
  tb303: {
    cutoff: number;
    resonance: number;
    decay: number;
    accent: number;
    waveform: 0 | 1;
    envMod?: number;
    slideTime?: number;
  },
  sourceName: string,
  mappings?: DetailedParameterMapping[],
): Bass2Params {
  const cutoff = convertCutoffToHz(tb303.cutoff);
  const resonance = convertResonance(tb303.resonance);
  const decay = convertDecayToSeconds(tb303.decay);
  const accent = 0.5 + convertAccentToBoost(tb303.accent);

  const rawSlideTime = tb303.slideTime ?? TB303_DEFAULT_SLIDE_TIME;
  const slideTime = clampNormalized(rawSlideTime / 127);

  if (mappings) {
    mappings.push({
      source: `${sourceName}.cutoff`,
      target: 'Bass2Params.cutoff',
      originalValue: tb303.cutoff,
      convertedValue: Math.round(cutoff),
      formula: '100 * 2^(cutoff / 21.17) Hz',
    });
    mappings.push({
      source: `${sourceName}.slideTime`,
      target: 'Bass2Params.slideTime',
      originalValue: rawSlideTime,
      convertedValue: parseFloat(slideTime.toFixed(3)),
      formula: 'slideTime / 127 (0-1 normalized, TB-303 default ≈ 0.33)',
    });
  }

  return {
    waveform: tb303.waveform === 0 ? '303-saw' : '303-sqr',
    ...RBS_TB303_VOICE_FIELDS,
    pitch: 0,
    cutoff,
    resonance,
    filterMode: 1,
    decay,
    accent,
    envMod: (tb303.envMod ?? 64) / 127,
    volume: 0.9,
    slideTime: (tb303.slideTime ?? TB303_DEFAULT_SLIDE_TIME) / 127,
  };
}

/** Map TB-303 pattern device params to Hyphon synth params (no mapping report noise). */
export function mapTb303PatternToSynthParams(
  tb303: Tb303PatternA,
  asBass2: boolean,
): Partial<SynthParams> | Partial<Bass2Params> {
  if (asBass2) {
    return convertToBass2Params(tb303, 'tb303B', undefined);
  }
  const waveform: Waveform = tb303.waveform === 0 ? '303-saw' : '303-sqr';
  const cutoffHz = convertCutoffToHz(tb303.cutoff);
  const resonance = convertResonance(tb303.resonance);
  const decaySeconds = convertDecayToSeconds(tb303.decay);
  const filterMode = clampNormalized(tb303.envMod / 127);
  const volume = 0.6 + convertAccentToBoost(tb303.accent);
  const portamento = clampNormalized((tb303.slideTime ?? TB303_DEFAULT_SLIDE_TIME) / 127);
  return {
    waveform,
    ...RBS_TB303_VOICE_FIELDS,
    pitch: 0,
    filterCutoff: cutoffHz,
    filterResonance: resonance,
    filterMode,
    attack: 0.01,
    decay: decaySeconds,
    sustain: 0.5,
    release: 0.1,
    volume,
    portamento,
  };
}

export function buildTrackParamSlots(
  patterns: Tb303PatternA[],
  maxSlots: number,
  asBass2: boolean,
): (Partial<SynthParams> | Partial<Bass2Params> | null)[] {
  const slots: (Partial<SynthParams> | Partial<Bass2Params> | null)[] = Array(maxSlots).fill(null);
  const count = Math.min(maxSlots, patterns.length);
  for (let i = 0; i < count; i++) {
    slots[i] = mapTb303PatternToSynthParams(patterns[i], asBass2);
  }
  return slots;
}

/** Resolve drum kit for import. */
export function resolveDrumKitType(ctx: ImporterContext, raw: RawRbsData): '808' | '909' {
  if (ctx.options.drumKitMapping !== 'auto') {
    return ctx.options.drumKitMapping;
  }

  const banks = raw.songData?.patternBanks;
  if (banks) {
    const has808 = drumBankHasTriggers(banks.drums808);
    const has909 = drumBankHasTriggers(banks.drums909);
    if (has808 && !has909) return '808';
    if (has909 && !has808) return '909';
  }

  const devices = raw.devicesPresent ?? inferDevicesPresent(raw);
  if (devices.includes('808') && !devices.includes('909')) return '808';
  if (devices.includes('909') && !devices.includes('808')) return '909';

  return raw.drums.kitType;
}

/** Convert drum parameters with kit-specific mapping (808 vs 909). */
export function convertDrumParams(
  drums: RawRbsData['drums'],
  mappings: DetailedParameterMapping[],
  kitType: '808' | '909',
): { kick: KickParams; snare: SnareParams; closedHat: HatParams; openHat: HatParams } {
  const kickTone = kitType === '808' ? 0.6 : 0.8;
  const snareTone = kitType === '808' ? 200 : 300;
  const snareNoise = kitType === '808' ? 2000 : 4000;

  const kick: KickParams = {
    pitch: mapRange(drums.tuning?.kick ?? 0, -50, 50, 40, 80),
    decay: mapRange(drums.decay?.kick ?? 64, 0, 127, 0.1, 1.0),
    tone: kickTone,
    volume: 1.0,
  };

  mappings.push({
    source: `Drums.${kitType}.kick.tone`,
    target: 'KickParams.tone',
    originalValue: kitType,
    convertedValue: kickTone,
    formula: kitType === '808' ? '808: more body (0.6)' : '909: tighter (0.8)',
  });

  const snare: SnareParams = {
    decay: mapRange(drums.decay?.snare ?? 48, 0, 127, 0.1, 0.8),
    tone: snareTone,
    noise: snareNoise,
    volume: 0.9,
  };

  mappings.push({
    source: `Drums.${kitType}.snare.tone`,
    target: 'SnareParams.tone',
    originalValue: kitType,
    convertedValue: snareTone,
    formula: kitType === '808' ? '808: lower pitch (200)' : '909: higher pitch (300)',
  });
  mappings.push({
    source: `Drums.${kitType}.snare.noise`,
    target: 'SnareParams.noise',
    originalValue: kitType,
    convertedValue: snareNoise,
    formula: kitType === '808' ? '808: less snap (2000)' : '909: more snap (4000)',
  });

  const closedHat: HatParams = {
    pitch: mapRange(drums.tuning?.closedHat ?? 0, -50, 50, 8000, 12000),
    decay: mapRange(drums.decay?.closedHat ?? 32, 0, 127, 0.05, 0.3),
    volume: 0.8,
  };

  const openHat: HatParams = {
    pitch: mapRange(drums.tuning?.openHat ?? 0, -50, 50, 6000, 10000),
    decay: mapRange(drums.decay?.openHat ?? 64, 0, 127, 0.2, 0.8),
    volume: 0.8,
  };

  return { kick, snare, closedHat, openHat };
}

/** Convert synth parameters from RBS to Hyphon. */
export function convertSynthParams(
  ctx: ImporterContext,
  raw: RawRbsData,
  mappings: DetailedParameterMapping[],
): HyphonSong['params'] {
  const map303ToSynthParams = (
    tb303: {
      cutoff: number;
      resonance: number;
      envMod: number;
      decay: number;
      accent: number;
      waveform: 0 | 1;
      slideTime?: number;
    },
    sourceName: string,
  ): SynthParams => {
    const waveform: Waveform = tb303.waveform === 0 ? '303-saw' : '303-sqr';
    const cutoffHz = convertCutoffToHz(tb303.cutoff);
    const resonance = convertResonance(tb303.resonance);
    const decaySeconds = convertDecayToSeconds(tb303.decay);
    const filterMode = clampNormalized(tb303.envMod / 127);
    const accentBoost = convertAccentToBoost(tb303.accent);
    const volume = 0.6 + accentBoost;
    const rawSlideTime = tb303.slideTime ?? TB303_DEFAULT_SLIDE_TIME;
    const portamento = clampNormalized(rawSlideTime / 127);

    mappings.push({
      source: `${sourceName}.cutoff`,
      target: 'SynthParams.filterCutoff',
      originalValue: tb303.cutoff,
      convertedValue: Math.round(cutoffHz),
      formula: '100 * 2^(cutoff / 21.17) Hz',
    });
    mappings.push({
      source: `${sourceName}.resonance`,
      target: 'SynthParams.filterResonance',
      originalValue: tb303.resonance,
      convertedValue: parseFloat(resonance.toFixed(2)),
      formula: 'resonance / 6.35',
    });
    mappings.push({
      source: `${sourceName}.envMod`,
      target: 'SynthParams.filterMode',
      originalValue: tb303.envMod,
      convertedValue: parseFloat(filterMode.toFixed(3)),
      formula: 'envMod / 127 (0-1 normalized)',
    });
    mappings.push({
      source: `${sourceName}.decay`,
      target: 'SynthParams.decay',
      originalValue: tb303.decay,
      convertedValue: parseFloat(decaySeconds.toFixed(3)),
      formula: '0.05 * 40^(decay / 127) seconds',
    });
    mappings.push({
      source: `${sourceName}.accent`,
      target: 'SynthParams.volume',
      originalValue: tb303.accent,
      convertedValue: parseFloat(volume.toFixed(2)),
      formula: '0.6 + (accent / 317.5)',
    });
    mappings.push({
      source: `${sourceName}.waveform`,
      target: 'SynthParams.waveform',
      originalValue: tb303.waveform,
      convertedValue: waveform,
    });
    mappings.push({
      source: `${sourceName}.slideTime`,
      target: 'SynthParams.portamento',
      originalValue: rawSlideTime,
      convertedValue: parseFloat(portamento.toFixed(3)),
      formula: 'slideTime / 127 (0-1 normalized, TB-303 default ≈ 0.33)',
    });

    return {
      waveform,
      ...RBS_TB303_VOICE_FIELDS,
      pitch: 0,
      filterCutoff: cutoffHz,
      filterResonance: resonance,
      filterMode,
      attack: 0.01,
      decay: decaySeconds,
      sustain: 0.5,
      release: decaySeconds * 0.5,
      length: 0.25,
      volume,
      delayTime: 0.3,
      delayFeedback: 0.2,
      delayMix: 0.0,
      portamento,
    };
  };

  const synthA = map303ToSynthParams(raw.tb303PatternA, 'TB-303A');
  const synthB = map303ToSynthParams(raw.tb303PatternB, 'TB-303B');

  const bass2Params: Bass2Params | undefined =
    ctx.options.tb303ATarget === 'bass2' ? convertToBass2Params(raw.tb303PatternA, 'TB-303A', mappings) :
      ctx.options.tb303BTarget === 'bass2' ? convertToBass2Params(raw.tb303PatternB, 'TB-303B', mappings) :
        undefined;

  let drumKit = resolveDrumKitType(ctx, raw);
  if (ctx.options.drumKitMapping !== 'auto') {
    drumKit = ctx.options.drumKitMapping;
  }
  const { kick, snare, closedHat, openHat } = convertDrumParams(raw.drums, mappings, drumKit);

  return {
    synthA,
    synthB,
    bass2: bass2Params,
    kick,
    snare,
    closedHat,
    openHat,
    drumKit,
  };
}

/**
 * RBS File Parser
 *
 * Parses .rbs files from ReBirth RB-338 (v1.5, 2.0, 2.0.1) and compatible sequencers.
 *
 * Architecture:
 * - Current implementation: Fixed-offset parser for single-pattern data (HEAD + TB303 A/B + DRUMS + PCF + basic automation).
 *   Already handles 16-step patterns, param extraction, accent/slide/tie flags, PCF, basic automation lanes, drum kit/tuning/decay.
 * - Next evolution (see GitHub #671): Full IFF "CAT RB40" chunk-based parser (per definitive RBS42.txt + rbs.h from nsauzede/jsynth reverse engineering).
 *   Required for real multi-pattern song files: 32 patterns per device in DEVL catalog, GLOB (play mode song vs pattern), TRKL/TRAK event lists (delta-tick + ctrlID + value) for song arrangement + continuous automation.
 * - Version handling: v2.0+ (RB40) is the documented full format; v1.5 is a simpler subset (often 1x303 + 808 only).
 *
 * Automation Precision Notes (critical for accurate ReBirth playback + future authentic RBS song creation):
 * - TRAK events use sub-step / tick resolution (~24 PPQ, 768 ticks/bar). Requires 1/96+ sub-step support in lanes + AudioParam scheduling (setValueAtTime + linearRampToValueAtTime) rather than pure per-step JS updates.
 * - Hybrid: Step-based (pattern step bitmasks for accent/slide/note) + continuous curves (knob automation events).
 * - Must reproduce ReBirth accent intensity, slide/portamento timing, PCF sweeps, 303 env/decay/wave changes with low jitter and tight clock sync (no drift over long songs).
 * - Recording must capture with temporal accuracy aligned to scheduler/audio clock.
 * - The system (lanes + scheduler + Open303 wiring) must be expressive enough to *author* new ReBirth-style songs inside Hyphon.
 * See updated issues #669, #670, #654, and new #671 for details and requirements.
 *
 * Primary external reference: https://github.com/nsauzede/jsynth (RBS42.txt, songfilev4.txt, rbs.h/c with exact packed structs, controller IDs, event encoding).
 *
 * Comprehensive error handling with detailed offset information.
 */

import type {
  RawRbsData,
  RbsProject,
  Tb303PatternA,
  Tb303PatternB,
  DrumPattern,
  PcfSettings,
  AutomationLane,
  RbsBinaryHeader,
  RbsRawStep,
  RbsRawAutomationLane,
  RbsGlobData,
  RbsTrakEvent,
  RbsTrakData,
  RbsSongData,
} from './types';
import { AUTOMATION_PARAMETER_MAP, TICKS_PER_BAR, TRAK_TRACK_INDEX } from './types';

/** Parser error types for granular error handling */
export type RbsParserError =
  | { type: 'INVALID_FORMAT'; message: string }
  | { type: 'UNSUPPORTED_VERSION'; version: string; supported: string[] }
  | { type: 'CORRUPTED_DATA'; section: string; details?: string; offset?: number }
  | { type: 'READ_ERROR'; message: string };

/**
 * Stable, testable error codes for the RBS parse pipeline.
 * Maps from {@link RbsParserError} discriminated variants.
 */
export type RbsErrorCode =
  | 'RBS_ERROR_UNKNOWN_FORMAT'
  | 'RBS_ERROR_TRUNCATED_CHUNK'
  | 'RBS_ERROR_UNSUPPORTED_VERSION'
  | 'RBS_ERROR_CORRUPTED_DATA'
  | 'RBS_ERROR_READ_ERROR'
  | 'RBS_ERROR_FILE_TOO_SMALL'
  | 'RBS_ERROR_FILE_TOO_LARGE'
  | 'RBS_ERROR_INVALID_EXTENSION';

/** All failure codes returned by {@link classifyParserError}. */
export const RBS_ERROR_CODES: readonly RbsErrorCode[] = [
  'RBS_ERROR_UNKNOWN_FORMAT',
  'RBS_ERROR_TRUNCATED_CHUNK',
  'RBS_ERROR_UNSUPPORTED_VERSION',
  'RBS_ERROR_CORRUPTED_DATA',
  'RBS_ERROR_READ_ERROR',
  'RBS_ERROR_FILE_TOO_SMALL',
  'RBS_ERROR_FILE_TOO_LARGE',
  'RBS_ERROR_INVALID_EXTENSION',
] as const;

/**
 * Classify a parser error into a stable `RBS_ERROR_*` code for UI and tests.
 */
export function classifyParserError(error: RbsParserError): RbsErrorCode {
  switch (error.type) {
    case 'INVALID_FORMAT':
      if (error.message.includes('.rbs extension') || error.message.includes('does not have .rbs')) {
        return 'RBS_ERROR_INVALID_EXTENSION';
      }
      if (error.message.toLowerCase().includes('too large')) {
        return 'RBS_ERROR_FILE_TOO_LARGE';
      }
      return 'RBS_ERROR_UNKNOWN_FORMAT';
    case 'UNSUPPORTED_VERSION':
      return 'RBS_ERROR_UNSUPPORTED_VERSION';
    case 'CORRUPTED_DATA': {
      const details = error.details?.toLowerCase() ?? '';
      if (details.includes('truncated') || details.includes('past eof') || details.includes('chunk')) {
        return 'RBS_ERROR_TRUNCATED_CHUNK';
      }
      if (details.includes('too small') || error.section === 'header' && details.includes('min')) {
        return 'RBS_ERROR_FILE_TOO_SMALL';
      }
      return 'RBS_ERROR_CORRUPTED_DATA';
    }
    case 'READ_ERROR':
      return 'RBS_ERROR_READ_ERROR';
    default:
      return 'RBS_ERROR_CORRUPTED_DATA';
  }
}

/** Parser result with discriminated union for type safety */
export type RbsParserResult =
  | { success: true; data: RawRbsData }
  | { success: false; error: RbsParserError };

/** Supported RBS format versions (current parser accepts common ones; full IFF path will detect RB40 / v4.x) */
export const SUPPORTED_VERSIONS = ['1.0', '1.5', '2.0', '2.0.1', '4.0', '4.2'];

/** Versions that use the v1.5 device subset (often single 303 + TR-808, no 909). */
export const V15_SUBSET_VERSIONS = ['1.0', '1.5'] as const;

/** Versions that use the full IFF CAT RB40 multi-device layout. */
export const IFF_FULL_FORMAT_VERSIONS = ['2.0', '2.0.1', '4.0', '4.2'] as const;

export function isV15SubsetVersion(version: string): boolean {
  return (V15_SUBSET_VERSIONS as readonly string[]).includes(version);
}

export function isIffFullFormatVersion(version: string): boolean {
  return (IFF_FULL_FORMAT_VERSIONS as readonly string[]).includes(version);
}

/** Minimum valid RBS file size (header + minimal patterns) */
export const MIN_FILE_SIZE = 0x300; // 768 bytes minimum

/** File offset constants (legacy fixed-offset path for single-pattern / current parser) */
export const OFFSETS = {
  HEADER: 0x00,
  HEADER_SIZE: 0x40,           // 64 bytes (legacy view)
  TB303_A: 0x40,
  TB303_A_SIZE: 0x100,         // 256 bytes
  TB303_B: 0x140,
  TB303_B_SIZE: 0x100,         // 256 bytes
  DRUMS: 0x240,
  DRUMS_SIZE: 0x80,            // 128 bytes
  PCF: 0x2C0,
  PCF_SIZE: 0x40,              // 64 bytes
  AUTOMATION: 0x300,
} as const;

/**
 * IFF chunk header (parsed from CAT RB40 files).
 * ReBirth uses big-endian for chunk sizes in the IFF container.
 */
export interface IffChunk {
  id: string;      // 4-char ID (e.g. "HEAD", "GLOB", "DEVL", "TRAK")
  size: number;    // payload size (big-endian uint32 after ID)
  offset: number;  // absolute file offset of payload start
}

/** Step structure size in bytes */
export const STEP_SIZE = 15;

/** Number of steps per pattern */
export const STEP_COUNT = 16;

/** Special note value: rest (no note plays) */
export const NOTE_REST = 255;

/** Special note value: tie (sustain previous note) */
export const NOTE_TIE = 254;

/** Maximum number of TRAK events to parse (safety cap) */
export const MAX_TRAK_EVENTS = 100000;

/** Maximum song length in measures for arrangement import */
const MAX_SONG_BARS = 64;

/**
 * IFF DEVL device chunk layouts (RBS42 / rbs.h).
 * Ref: Propellerhead RBSFormat42.txt, nsauzede/jsynth `rbs.h`.
 *
 * DEVL catalog order (fixed): MIXR, DELY, PCF, DIST, COMP, `303 `, `303 `, `808 `, `909 `.
 * Implementation: `devlLayout.ts` (`parseTb303DeviceChunk`, `parseTr808DeviceChunk`, …).
 */
export const DEVL_LAYOUT = {
  /** `303 ` chunk payload size (bytes). */
  TB303_CHUNK_SIZE: 1097,
  /** Bytes per pattern slot inside `303 ` (shuffle + length + 16×2 step bytes). */
  TB303_PATTERN_SIZE: 34,
  TB303_PATTERN_COUNT: 32,
  /** First pattern slot offset within `303 ` payload (after 9-byte device header). */
  TB303_PATTERN_DATA_OFFSET: 9,
  /** `808 ` chunk payload size. */
  TR808_CHUNK_SIZE: 6238,
  /** Bytes per pattern slot inside `808 ` (shuffle + length + 16×12 trigger bytes). */
  TR808_PATTERN_SIZE: 194,
  TR808_PATTERN_DATA_OFFSET: 30,
  /** `909 ` chunk payload size (+1 vs 808 for extra global param). */
  TR909_CHUNK_SIZE: 6239,
  TR909_PATTERN_SIZE: 194,
  TR909_PATTERN_DATA_OFFSET: 30,
} as const;

/**
 * TB-303 `303 ` device header offsets (pattern-mode globals, RBS42).
 * Pattern banks begin at {@link DEVL_LAYOUT.TB303_PATTERN_DATA_OFFSET}.
 */
export const DEVL_TB303_DEVICE = {
  ENABLED: 0,
  SELECTED_PATTERN: 1,
  TUNE: 2,
  CUTOFF: 3,
  RESONANCE: 4,
  ENV_MOD: 5,
  DECAY: 6,
  ACCENT: 7,
  WAVEFORM: 8,
} as const;

/**
 * One TB-303 pattern block inside the 32×{@link DEVL_LAYOUT.TB303_PATTERN_SIZE} bank region.
 * Step *n* starts at `patternBase + STEP_DATA + n * STEP_BYTES`.
 */
export const DEVL_TB303_PATTERN = {
  SHUFFLE: 0,
  LENGTH: 1,
  STEP_DATA: 2,
  STEP_BYTES: 2,
  /** Step flag bit 0 — slide. */
  FLAG_SLIDE: 0x01,
  /** Step flag bit 1 — accent. */
  FLAG_ACCENT: 0x02,
  /** Step flag bit 4 — note on (clear = rest). */
  FLAG_NOTE: 0x10,
} as const;

/**
 * TR-808 / TR-909 pattern step layout: 12 trigger bytes per step (AC, BD, SD, …).
 * See RBS42 `808 ` / `909 ` chunk sections.
 */
export const DEVL_DRUM_STEP = {
  INSTRUMENT_COUNT: 12,
  OFFSET_IN_PATTERN: 2,
  TRIGGER_ON: 0x01,
  TRIGGER_ACCENT: 0x02,
} as const;

/**
 * DEVL `PCF ` chunk byte offsets (12-byte payload, RBS42).
 */
export const DEVL_PCF_CHUNK = {
  SIZE: 12,
  ENABLED: 0,
  FREQUENCY: 1,
  RESONANCE: 2,
  AMOUNT: 3,
  WAVE: 4,
  DECAY: 5,
  MODE: 6,
} as const;

/** DEVL `MIXR` — PCF device routing byte. */
export const DEVL_MIXR_PCF_DEVICE_ID_OFFSET = 2;

/**
 * RBS Parser class
 *
 * Usage:
 * ```typescript
 * const parser = new RbsParser();
 * const result = await parser.parseRbsFile(file);
 * if (result.success) {
 *   console.log(result.data.project.name);
 * } else {
 *   console.error(result.error.message);
 * }
 * ```
 */

import type {
  RawRbsData, RbsGlobData, RbsTrakEvent, RbsTrakData, RbsSongData, PcfSettings,
} from '../types';
import { TICKS_PER_BAR } from '../types';
import { isTrakPatternSelectEvent, resolveTrakEventKind } from '../trakControllers';
import type { RbsParserError, IffChunk } from '../parser-types';
import { MAX_TRAK_EVENTS, SUPPORTED_VERSIONS } from '../parser-types';
import { inferDevicesPresent } from '../deviceInference';
import {
  DEVL_CHUNK_IDS,
  parseTb303DeviceChunk,
  parseTr808DeviceChunk,
  parseTr909DeviceChunk,
  parseDevlPcfChunk,
  parseDevlMixrPcfDeviceId,
  buildPcfSettingsFromDevl,
  disabledPcfSettings,
} from '../devlLayout';
import type { ParserBinaryContext } from './parserContext';
import { readAsciiString, readNullTerminatedString } from './binaryIO';
import {
  generateEmptyTb303Pattern,
  generateEmptyTb303PatternB,
  generateEmptyDrumPattern,
} from './mockData';

export function validateVersion(version: string): RbsParserError | null {
  if (!SUPPORTED_VERSIONS.includes(version)) {
    return {
      type: 'UNSUPPORTED_VERSION',
      version,
      supported: [...SUPPORTED_VERSIONS],
    };
  }
  return null;
}

export function detectIffTruncation(ctx: ParserBinaryContext, chunks: IffChunk[]): RbsParserError | null {
  for (const chunk of chunks) {
    const paddedSize = chunk.size + (chunk.size % 2);
    const end = chunk.offset + paddedSize;
    if (end > ctx.fileSize) {
      return {
        type: 'CORRUPTED_DATA',
        section: 'iff',
        details: `Truncated chunk "${chunk.id}" (payload ends at ${end}, file size ${ctx.fileSize})`,
        offset: chunk.offset,
      };
    }
  }
  return null;
}

export function parseIffChunks(ctx: ParserBinaryContext): IffChunk[] {
  const chunks: IffChunk[] = [];
  if (ctx.fileSize < 12) return chunks;

  const magic = readAsciiString(ctx, 0, 4);
  if (magic !== 'CAT ') {
    return chunks;
  }

  const rootSize = ctx.dataView.getUint32(4, false);
  let pos = 12;

  const formType = readAsciiString(ctx, 8, 4);
  console.debug(`[RbsParser] IFF CAT form detected: ${formType}, root size ${rootSize}`);

  const maxPos = Math.min(ctx.fileSize, 8 + rootSize);
  while (pos + 8 <= maxPos) {
    const id = readAsciiString(ctx, pos, 4);
    if (!id || id.charCodeAt(0) < 32) break;
    const size = ctx.dataView.getUint32(pos + 4, false);
    const payloadEnd = pos + 8 + size + (size % 2);
    if (payloadEnd > ctx.fileSize) {
      chunks.push({ id, size, offset: pos + 8 });
      break;
    }
    chunks.push({ id, size, offset: pos + 8 });
    pos += 8 + size;
    if (size % 2 === 1) pos++;
  }

  return chunks;
}

export function parseNestedChunks(
  ctx: ParserBinaryContext,
  parentOffset: number,
  parentSize: number,
): IffChunk[] {
  const chunks: IffChunk[] = [];
  let pos = parentOffset + 4;
  const maxPos = parentOffset + parentSize;

  while (pos + 8 <= maxPos) {
    const id = readAsciiString(ctx, pos, 4);
    if (!id || id.charCodeAt(0) < 32) break;
    const size = ctx.dataView.getUint32(pos + 4, false);
    const payloadEnd = pos + 8 + size + (size % 2);
    if (payloadEnd > parentOffset + parentSize && payloadEnd > ctx.fileSize) {
      chunks.push({ id, size, offset: pos + 8 });
      break;
    }
    chunks.push({ id, size, offset: pos + 8 });
    pos += 8 + size;
    if (size % 2 === 1) pos++;
  }

  return chunks;
}

export function parseIffHead(ctx: ParserBinaryContext, chunk: IffChunk): string {
  const offset = chunk.offset;
  const sig = readNullTerminatedString(ctx, offset, Math.min(chunk.size, 64));

  const versionMatch = sig.match(/(\d+\.\d+(?:\.\d+)?)/);
  if (versionMatch) return versionMatch[1];

  if (sig.includes('RB40') || sig.includes('RB-338')) return '2.0';
  if (sig.includes('RB15') || sig.includes('v1.5') || sig.includes('1.5')) return '1.5';
  if (sig.includes('v1.0') || sig.includes('1.0')) return '1.0';

  return '2.0';
}

export function parseIffGlob(ctx: ParserBinaryContext, chunk: IffChunk): RbsGlobData {
  const o = chunk.offset;
  const playMode = ctx.rawBytes[o] === 1 ? 1 : 0;
  const tempoRaw = ctx.dataView.getUint32(o + 2, false);
  const tempo = tempoRaw > 0 ? tempoRaw / 1000 : 120;
  const loopStartTicks = ctx.dataView.getUint32(o + 6, false);
  const loopEndTicks = ctx.dataView.getUint32(o + 10, false);
  const shuffle = ctx.rawBytes[o + 14] ?? 64;
  const vintage = ctx.rawBytes[o + 0x1ea] || 0;

  return {
    playMode,
    tempo,
    shuffle,
    loopStart: Math.floor(loopStartTicks / TICKS_PER_BAR),
    loopEnd: Math.floor(loopEndTicks / TICKS_PER_BAR),
    vintage,
  };
}

export function defaultGlob(): RbsGlobData {
  return { playMode: 0, tempo: 120, shuffle: 64, loopStart: 0, loopEnd: 0, vintage: 0 };
}

export function parseDevlPatterns(
  ctx: ParserBinaryContext,
  devlChunks: IffChunk[],
  _hasDevlCatalog: boolean,
): RbsSongData['patternBanks'] {
  const banks: RbsSongData['patternBanks'] = {
    tb303A: [],
    tb303B: [],
    drums808: [],
    drums909: [],
  };

  let tb303DeviceIndex = 0;

  for (const chunk of devlChunks) {
    const chunkId = chunk.id;

    if (chunkId === DEVL_CHUNK_IDS.TB303) {
      const patterns = parseTb303DeviceChunk(ctx.rawBytes, chunk.offset, chunk.size);
      if (tb303DeviceIndex === 0) {
        banks.tb303A.push(...patterns);
      } else {
        banks.tb303B.push(...patterns);
      }
      tb303DeviceIndex++;
      continue;
    }

    if (chunkId === DEVL_CHUNK_IDS.TR808) {
      banks.drums808.push(...parseTr808DeviceChunk(ctx.rawBytes, chunk.offset, chunk.size));
      continue;
    }

    if (chunkId === DEVL_CHUNK_IDS.TR909) {
      banks.drums909.push(...parseTr909DeviceChunk(ctx.rawBytes, chunk.offset, chunk.size));
    }
  }

  if (banks.tb303A.length === 0) {
    const legacyA = devlChunks.find((c) => c.id === '3031' || c.id === '303A');
    if (legacyA) {
      banks.tb303A.push(...parseTb303DeviceChunk(ctx.rawBytes, legacyA.offset, legacyA.size));
    }
  }
  if (banks.tb303B.length === 0) {
    const legacyB = devlChunks.find((c) => c.id === '3032' || c.id === '303B');
    if (legacyB) {
      banks.tb303B.push(...parseTb303DeviceChunk(ctx.rawBytes, legacyB.offset, legacyB.size));
    }
  }

  return banks;
}

export function parseDevlPcfSettings(ctx: ParserBinaryContext, devlChunks: IffChunk[]): PcfSettings {
  const pcfChunk = devlChunks.find((c) => c.id === DEVL_CHUNK_IDS.PCF);
  const mixrChunk = devlChunks.find((c) => c.id === DEVL_CHUNK_IDS.MIXR);

  if (!pcfChunk) {
    return disabledPcfSettings();
  }

  const pcfData = parseDevlPcfChunk(ctx.rawBytes, pcfChunk.offset, pcfChunk.size);
  const mixrPcfId = mixrChunk
    ? parseDevlMixrPcfDeviceId(ctx.rawBytes, mixrChunk.offset)
    : 0;

  return buildPcfSettingsFromDevl(pcfData, mixrPcfId);
}

export function parseSingleTrak(
  ctx: ParserBinaryContext,
  chunk: IffChunk,
  index: number,
  name: string,
): RbsTrakData {
  const offset = chunk.offset;
  const events: RbsTrakEvent[] = [];

  if (chunk.size < 4) {
    return { trackIndex: index, trackName: name, eventCount: 0, events: [] };
  }

  const eventCount = ctx.dataView.getUint32(offset, true);
  let pos = offset + 4;
  let absoluteTicks = 0;

  const maxEvents = Math.min(eventCount, MAX_TRAK_EVENTS);
  for (let e = 0; e < maxEvents; e++) {
    if (pos + 4 > offset + chunk.size) break;

    const deltaTicks = ctx.dataView.getUint16(pos, true);
    const controllerId = ctx.rawBytes[pos + 2];
    const value = ctx.rawBytes[pos + 3];
    pos += 4;

    absoluteTicks += deltaTicks;
    const eventKind = resolveTrakEventKind(index, controllerId);
    events.push({
      deltaTicks,
      absoluteTicks,
      trackIndex: index,
      controllerId,
      value,
      eventKind,
    });
  }

  return { trackIndex: index, trackName: name, eventCount: events.length, events };
}

export function parseTrklTracks(ctx: ParserBinaryContext, trklChunks: IffChunk[]): RbsTrakData[] {
  const trackNames = [
    'Mixer',
    'TB-303 #1',
    'TB-303 #2',
    'TR-808',
    'TR-909',
    'Delay',
    'Distortion',
    'PCF',
    'Compressor',
  ];
  const tracks: RbsTrakData[] = [];

  for (let i = 0; i < trklChunks.length; i++) {
    const chunk = trklChunks[i];
    if (chunk.id !== 'TRAK') continue;

    const trackIndex = tracks.length;
    const track = parseSingleTrak(
      ctx,
      chunk,
      trackIndex,
      trackNames[trackIndex] || `Track ${trackIndex}`,
    );
    tracks.push(track);
  }

  return tracks;
}

export function parseIffSongData(ctx: ParserBinaryContext, topChunks: IffChunk[]): RawRbsData | null {
  const headChunk = topChunks.find(c => c.id === 'HEAD');
  const globChunk = topChunks.find(c => c.id === 'GLOB');
  const catChunks = topChunks.filter(c => c.id === 'CAT ');

  if (!headChunk) return null;

  ctx.onProgress?.(10);

  const version = parseIffHead(ctx, headChunk);
  const glob = globChunk ? parseIffGlob(ctx, globChunk) : defaultGlob();

  ctx.onProgress?.(20);

  let devlChunks: IffChunk[] = [];
  let trklChunks: IffChunk[] = [];
  for (const cat of catChunks) {
    const formType = readAsciiString(ctx, cat.offset, 4);
    if (formType === 'DEVL') {
      devlChunks = parseNestedChunks(ctx, cat.offset, cat.size);
    } else if (formType === 'TRKL') {
      trklChunks = parseNestedChunks(ctx, cat.offset, cat.size);
    }
  }

  ctx.onProgress?.(40);

  const hasDevlCatalog = devlChunks.length > 0;
  const patternBanks = parseDevlPatterns(ctx, devlChunks, hasDevlCatalog);

  ctx.onProgress?.(70);

  const tracks = parseTrklTracks(ctx, trklChunks);

  ctx.onProgress?.(90);

  let maxTick = 0;
  const usedPatterns = new Set<number>();
  for (const track of tracks) {
    for (const evt of track.events) {
      if (evt.absoluteTicks > maxTick) maxTick = evt.absoluteTicks;
      if (isTrakPatternSelectEvent(evt.trackIndex, evt.controllerId, evt.eventKind)) {
        usedPatterns.add(evt.value);
      }
    }
  }
  const totalLengthBars = Math.ceil(maxTick / TICKS_PER_BAR) || 1;

  const songData: RbsSongData = {
    glob,
    patternBanks,
    tracks,
    totalLengthTicks: maxTick,
    totalLengthBars,
    usedPatternCount: usedPatterns.size || 1,
  };

  const tb303PatternA = patternBanks.tb303A[0] ?? generateEmptyTb303Pattern();
  const tb303PatternB = patternBanks.tb303B[0] ?? generateEmptyTb303PatternB();
  const drums = patternBanks.drums808[0] ?? patternBanks.drums909[0] ?? generateEmptyDrumPattern();

  const pcf = hasDevlCatalog
    ? parseDevlPcfSettings(ctx, devlChunks)
    : disabledPcfSettings();

  const baseName = `RBS Song (${version})`;
  const rawData: RawRbsData = {
    version,
    project: {
      name: baseName,
      author: 'Imported from RBS',
      tempo: glob.tempo || 120,
      timeSignatureNum: 4,
      timeSignatureDen: 4,
      swing: glob.shuffle,
      patternLength: 16,
      createdAt: new Date(),
      sourceSoftware: 'ReBirth RB-338',
    },
    tb303PatternA,
    tb303PatternB,
    drums,
    pcf,
    automation: [],
    songData,
    parsePath: 'iff',
  };
  rawData.devicesPresent = inferDevicesPresent(rawData);

  return rawData;
}

