  return {
    steps,
    cutoff: 64,
    resonance: 48,
    envMod: 64,
    decay: 48,
    accent: 80,
    waveform: 1,
    distortion: 0,
    delaySend: 0,
  };
}

export function generateMockTb303PatternB(): Tb303PatternB {
