/**
 * Hyphon → ReBirth RBS encoders (inverse of RbsImporter mapping).
 */

import type { Note, PartSequence, SynthParams, Bass2Params } from '../../types';
import type { DrumPattern, HyphonSong, PcfSettings, Tb303PatternA, Tb303Step } from './types';
import { noteToMidi } from '../../utils/musicTheory';
import type { Tb303DeviceParams } from './iffBuilder';

function clampByte(value: number): number {
  return Math.max(0, Math.min(127, Math.round(value)));
}

/** Inverse of RbsImporter.convertCutoffToHz */
export function hzToRbsCutoff(hz: number): number {
  const clamped = Math.max(100, Math.min(8000, hz));
  return clampByte(21.17 * Math.log2(clamped / 100));
}

/** Inverse of RbsImporter.convertResonance */
export function hyphonResonanceToRbs(resonance: number): number {
  return clampByte(resonance * 6.35);
}

/** Inverse of RbsImporter.convertDecayToSeconds */
export function hyphonDecayToRbs(decaySeconds: number): number {
  const clamped = Math.max(0.05, Math.min(2.0, decaySeconds));
  return clampByte((127 * Math.log(clamped / 0.05)) / Math.log(40));
}

/** Inverse of RbsImporter.convertAccentToBoost (volume knob → accent byte). */
export function hyphonVolumeToRbsAccent(volume: number): number {
  return clampByte((volume - 0.6) * 317.5);
}

export function hyphonFilterModeToEnvMod(filterMode: number): number {
  return clampByte((filterMode ?? 0) * 127);
}

export function hyphonWaveformToRbs(waveform: string): 0 | 1 {
  return waveform === '303-sqr' || waveform === 'square' ? 1 : 0;
}

/** Collapse 32 Hyphon steps to 16 ReBirth steps (first sub-step of each 16th). */
export function collapseHyphonStepsTo16(steps: (Note | null)[]): (Note | null)[] {
  if (steps.length <= 16) {
    return steps.slice(0, 16).concat(Array(Math.max(0, 16 - steps.length)).fill(null));
  }
  const out: (Note | null)[] = [];
  for (let i = 0; i < 16; i++) {
    out.push(steps[i * 2] ?? steps[i] ?? null);
  }
  return out;
}

export function hyphonNoteToTb303Step(note: Note | null, index: number): Tb303Step {
  if (!note) {
    return {
      index,
      note: -1,
      octave: 3,
      accent: false,
      slide: false,
      tie: false,
      gate: 100,
    };
  }

  const midi = noteToMidi(note.note);
  const noteNum = midi % 12;
  const octave = Math.max(1, Math.min(5, Math.floor(midi / 12) - 1));

  return {
    index,
    note: noteNum,
    octave,
    accent: note.velocity >= 0.9,
    slide: !!note.slide || (note.length ?? 1) >= 2,
    tie: false,
    gate: 100,
  };
}

export function partSequenceToTb303Steps(
  seq: PartSequence,
  collapse32: boolean,
): Tb303Step[] {
  const raw = collapse32 ? collapseHyphonStepsTo16(seq.steps) : seq.steps.slice(0, 16);
  return raw.map((note, index) => hyphonNoteToTb303Step(note, index));
}

export function partSequenceToDrumBooleans(
  seq: PartSequence,
  collapse32: boolean,
): boolean[] {
  const raw = collapse32 ? collapseHyphonStepsTo16(seq.steps) : seq.steps.slice(0, 16);
  return raw.map((n) => n !== null);
}

export function synthParamsToTb303DeviceParams(
  params: SynthParams | Bass2Params,
  metadata?: Omit<Tb303PatternA, 'steps'>,
): Tb303DeviceParams {
  if (metadata?.cutoff !== undefined) {
    return {
      cutoff: metadata.cutoff,
      resonance: metadata.resonance ?? 64,
      envMod: metadata.envMod ?? 64,
      decay: metadata.decay ?? 48,
      accent: metadata.accent ?? 80,
      waveform: metadata.waveform ?? 0,
    };
  }

  const isBass2 = 'cutoff' in params && !('filterCutoff' in params);
  const cutoffHz = isBass2
    ? (params as Bass2Params).cutoff
    : (params as SynthParams).filterCutoff;
  const resonanceVal = isBass2
    ? (params as Bass2Params).resonance
    : (params as SynthParams).filterResonance;

  return {
    cutoff: hzToRbsCutoff(cutoffHz),
    resonance: hyphonResonanceToRbs(resonanceVal),
    envMod: hyphonFilterModeToEnvMod(params.filterMode ?? 0),
    decay: hyphonDecayToRbs(params.decay),
    accent: hyphonVolumeToRbsAccent(params.volume),
    waveform: hyphonWaveformToRbs(params.waveform),
  };
}

export function buildDrumPatternFromHyphon(
  pattern: HyphonSong['pattern'],
  collapse32: boolean,
  kitType: '808' | '909',
): DrumPattern {
  return {
    kick: partSequenceToDrumBooleans(pattern.kick, collapse32),
    snare: partSequenceToDrumBooleans(pattern.snare, collapse32),
    closedHat: partSequenceToDrumBooleans(pattern.closedHat, collapse32),
    openHat: partSequenceToDrumBooleans(pattern.openHat, collapse32),
    accent: Array(16).fill(0),
    kitType,
  };
}

/** Build drum pattern bank from per-slot track storage (song mode). */
export function buildDrumPatternsFromTrackStorage(
  trackStorage: {
    kick: (PartSequence | null)[];
    snare: (PartSequence | null)[];
    closedHat: (PartSequence | null)[];
    openHat: (PartSequence | null)[];
  },
  slotCount: number,
  collapse32: boolean,
  kitType: '808' | '909',
): DrumPattern[] {
  const patterns: DrumPattern[] = [];
  for (let i = 0; i < slotCount; i++) {
    const kick = trackStorage.kick[i];
    const snare = trackStorage.snare[i];
    const closedHat = trackStorage.closedHat[i];
    const openHat = trackStorage.openHat[i];
    if (!kick && !snare && !closedHat && !openHat) {
      patterns.push({
        kick: Array(16).fill(false),
        snare: Array(16).fill(false),
        closedHat: Array(16).fill(false),
        openHat: Array(16).fill(false),
        accent: Array(16).fill(0),
        kitType,
      });
      continue;
    }
    patterns.push({
      kick: partSequenceToDrumBooleans(kick ?? { steps: Array(16).fill(null) }, collapse32),
      snare: partSequenceToDrumBooleans(snare ?? { steps: Array(16).fill(null) }, collapse32),
      closedHat: partSequenceToDrumBooleans(closedHat ?? { steps: Array(16).fill(null) }, collapse32),
      openHat: partSequenceToDrumBooleans(openHat ?? { steps: Array(16).fill(null) }, collapse32),
      accent: Array(16).fill(0),
      kitType,
    });
  }
  return patterns;
}

export function pcfSettingsToDevlPayload(pcf: PcfSettings): {
  enabled?: boolean;
  cutoff?: number;
  resonance?: number;
  envAmount?: number;
  wave?: number;
  decay?: number;
  filterType?: 'lp' | 'bp';
} {
  return {
    enabled: pcf.enabled,
    cutoff: pcf.cutoff,
    resonance: pcf.resonance,
    envAmount: pcf.envAmount,
    wave: pcf.waveIndex ?? 1,
    decay: pcf.decay,
    filterType: pcf.filterType === 'lp' ? 'lp' : 'bp',
  };
}

const PROPHECY_PREFIX = 'prophecy-';
/** Waveform prefixes with no ReBirth equivalent — exported as a TB-303 saw. */
const UNSUPPORTED_WAVEFORM_PREFIXES = ['wav-', 'wgsl-', 'wam-', 'pyodide-'];

export function collectExportWarnings(song: HyphonSong): string[] {
  const warnings: string[] = [];

  warnings.push('Sampler banks are not exported to ReBirth format.');
  warnings.push('Prophecy formant waveforms are not exported — TB-303 saw/square used instead.');

  const checkWave = (wf: string, label: string) => {
    if (wf.startsWith(PROPHECY_PREFIX)) {
      warnings.push(`${label} uses Prophecy waveform "${wf}" — exported as TB-303 saw.`);
    } else if (UNSUPPORTED_WAVEFORM_PREFIXES.some((p) => wf.startsWith(p))) {
      warnings.push(`${label} waveform "${wf}" is not supported in ReBirth — exported as TB-303 saw.`);
    }
  };

  checkWave(song.params.synthA.waveform, 'Synth A');
  checkWave(song.params.synthB.waveform, 'Synth B');
  if (song.params.bass2) {
    checkWave(song.params.bass2.waveform, 'Bass 2');
  }

  return warnings;
}

/**
 * SMF → Hyphon importer.
 *
 * Converts a `ParsedSmf` (raw ticks/channels, format-agnostic) into a
 * `HyphonSmfSong`: quantized 32-step patterns keyed by Hyphon `TrackKey`,
 * routed by channel, with an `ImportReport` describing anything that
 * couldn't be represented losslessly.
 *
 * Grid convention (see issue): one Hyphon pattern is 32 steps = **2 bars**
 * of 4/4 16th notes, i.e. `ticksPerStep = ppq / 4` and
 * `ticksPerPattern = ticksPerStep * 32`. This is not simply "1 MIDI bar =
 * 1 pattern" — it only lines up that way when the file is 4/4.
 */

import type {
  HyphonSmfSong,
  ParsedSmf,
  SmfAutomationLane,
  SmfImportOptions,
  SmfImportReport,
  SmfImportResult,
  SmfNoteEvent,
} from './types';
import { DEFAULT_SMF_CHANNEL_MAP, DEFAULT_SMF_IMPORT_OPTIONS, GM_DRUM_NOTE_MAP } from './types';
import type { Note, Pattern, PartSequence } from '../../types';
import type { TrackKey } from '../../constants/appDefaults';
import { EMPTY_PATTERN } from '../../constants/appDefaults';
import { NUM_STEPS, TRACK_KEYS } from '../../constants';
import { MAX_TRACK_PATTERN_SLOTS, createEmptyTrackStorage } from '../../utils/trackStorageUtils';
import { midiToNote } from '../../utils/musicTheory';

const DRUM_MIDI_CHANNEL = 9; // MIDI channel 10, 0-based
const MELODIC_TRACK_KEYS: TrackKey[] = ['partA', 'partB', 'bass2'];

function clamp01(v: number): number {
  return Math.max(0, Math.min(1, v));
}

function emptyPartSequence(): PartSequence {
  return { steps: Array.from({ length: NUM_STEPS }, (): null => null) };
}

interface QuantizedNote {
  patternIndex: number;
  stepInPattern: number;
  note: Note;
}

function quantizeNote(ev: SmfNoteEvent, ticksPerStep: number, quantize: boolean): QuantizedNote {
  const rawStep = ev.startTick / ticksPerStep;
  const stepIndex = quantize ? Math.round(rawStep) : Math.floor(rawStep);
  const microtiming = quantize ? clampMicrotiming(rawStep - stepIndex) : 0;
  const patternIndex = Math.floor(stepIndex / NUM_STEPS);
  const stepInPattern = ((stepIndex % NUM_STEPS) + NUM_STEPS) % NUM_STEPS;

  const stepLength = Math.max(1, Math.round((ev.endTick - ev.startTick) / ticksPerStep));

  const note: Note = {
    note: midiToNote(ev.note),
    velocity: clamp01(ev.velocity / 127),
  };
  if (stepLength > 1) note.length = stepLength;
  if (microtiming !== 0) note.microtiming = microtiming;

  return { patternIndex, stepInPattern, note };
}

function clampMicrotiming(v: number): number {
  return Math.max(-0.5, Math.min(0.5, v));
}

/** Route a non-drum note's channel to a TrackKey + "lane" (0 = primary, 1+ = extra/appended section). */
function resolveMelodicRoute(
  channel: number,
  options: SmfImportOptions,
): { target: TrackKey; lane: number } {
  const explicit = options.channelMap[channel];
  if (explicit && explicit !== 'extra' && (explicit as TrackKey) !== 'sampler') {
    return { target: explicit as TrackKey, lane: 0 };
  }
  const primary = DEFAULT_SMF_CHANNEL_MAP[channel];
  if (primary && primary !== 'extra') {
    return { target: primary as TrackKey, lane: 0 };
  }
  // Extra channel: round-robin across the 3 melodic tracks, appended as its own lane
  // (extra pattern slots on that track) rather than inventing a new track.
  const roundRobinIndex = channel % MELODIC_TRACK_KEYS.length;
  return { target: MELODIC_TRACK_KEYS[roundRobinIndex], lane: 1 + Math.floor(channel / MELODIC_TRACK_KEYS.length) };
}

interface LaneBuild {
  target: TrackKey;
  lane: number;
  channel: number;
  patterns: Map<number, PartSequence>;
  patternCount: number;
}

/**
 * Convert a parsed SMF into a HyphonSmfSong + import report.
 * Never throws — a file with no notes still returns a (loud) report rather
 * than crashing.
 */
export function convertToHyphonSong(
  parsed: ParsedSmf,
  optionsIn: Partial<SmfImportOptions> = {},
): SmfImportResult {
  const options: SmfImportOptions = { ...DEFAULT_SMF_IMPORT_OPTIONS, ...optionsIn };
  const warnings: string[] = [...parsed.warnings];

  const ppq = parsed.ppq;
  const ticksPerStep = ppq / 4; // 16th-note grid
  const bpm = parsed.tempoMap[0]?.bpm ?? 120;

  const timeSig = parsed.timeSignatures[0] ?? { tick: 0, numerator: 4, denominator: 4 };
  const timeSignatureMismatch = timeSig.numerator !== 4 || timeSig.denominator !== 4;
  if (timeSignatureMismatch) {
    warnings.push(
      `Time signature ${timeSig.numerator}/${timeSig.denominator} is not 4/4 — the 32-step grid assumes 4/4 16th notes, so timing will drift from the original bars.`,
    );
  }

  const tempoChangesAfterBar1 = parsed.tempoMap.filter((t) => t.tick > ticksPerStep * NUM_STEPS).length;
  if (tempoChangesAfterBar1 > 0) {
    warnings.push(`${tempoChangesAfterBar1} tempo change(s) after the first pattern were ignored (Hyphon has a single song BPM, taken from the first Set Tempo event).`);
  }

  const channelsUsed = Array.from(new Set(parsed.notes.map((n) => n.channel))).sort((a, b) => a - b);

  // ---- Route every note into a lane keyed by (trackKey, laneIndex). ----
  const laneKey = (target: TrackKey, lane: number): string => `${target}:${lane}`;
  const lanes = new Map<string, LaneBuild>();
  let notesUnmapped = 0;
  let drumGmMisses = 0;

  const samplerPatterns = new Map<number, PartSequence>();
  let samplerPatternCount = 0;

  for (const ev of parsed.notes) {
    if (ev.channel === DRUM_MIDI_CHANNEL) {
      const drumTrack = GM_DRUM_NOTE_MAP[ev.note];
      if (!drumTrack) {
        // Unmapped GM drum note → sampler bank 0, sharing the drum-channel timeline.
        drumGmMisses += 1;
        const q = quantizeNote(ev, ticksPerStep, options.quantize);
        if (q.patternIndex >= MAX_TRACK_PATTERN_SLOTS) {
          warnings.push(`Dropped a note past pattern slot ${MAX_TRACK_PATTERN_SLOTS} on the sampler bank (channel 10, GM note ${ev.note}).`);
          continue;
        }
        let seq = samplerPatterns.get(q.patternIndex);
        if (!seq) {
          seq = emptyPartSequence();
          samplerPatterns.set(q.patternIndex, seq);
          samplerPatternCount = Math.max(samplerPatternCount, q.patternIndex + 1);
        }
        seq.steps[q.stepInPattern] = q.note;
        continue;
      }
      const key = laneKey(drumTrack, 0);
      let lane = lanes.get(key);
      if (!lane) {
        lane = { target: drumTrack, lane: 0, channel: ev.channel, patterns: new Map(), patternCount: 0 };
        lanes.set(key, lane);
      }
      const q = quantizeNote(ev, ticksPerStep, options.quantize);
      if (q.patternIndex >= MAX_TRACK_PATTERN_SLOTS) {
        warnings.push(`Dropped a note past pattern slot ${MAX_TRACK_PATTERN_SLOTS} on ${drumTrack} (channel 10).`);
        continue;
      }
      let seq = lane.patterns.get(q.patternIndex);
      if (!seq) {
        seq = emptyPartSequence();
        lane.patterns.set(q.patternIndex, seq);
        lane.patternCount = Math.max(lane.patternCount, q.patternIndex + 1);
      }
      seq.steps[q.stepInPattern] = q.note;
      continue;
    }

    const route = resolveMelodicRoute(ev.channel, options);
    const key = laneKey(route.target, route.lane);
    let lane = lanes.get(key);
    if (!lane) {
      lane = { target: route.target, lane: route.lane, channel: ev.channel, patterns: new Map(), patternCount: 0 };
      lanes.set(key, lane);
    }
    const q = quantizeNote(ev, ticksPerStep, options.quantize);
    if (q.patternIndex >= MAX_TRACK_PATTERN_SLOTS) {
      warnings.push(`Dropped a note past pattern slot ${MAX_TRACK_PATTERN_SLOTS} on ${route.target} (channel ${ev.channel + 1}).`);
      notesUnmapped += 1;
      continue;
    }
    let seq = lane.patterns.get(q.patternIndex);
    if (!seq) {
      seq = emptyPartSequence();
      lane.patterns.set(q.patternIndex, seq);
      lane.patternCount = Math.max(lane.patternCount, q.patternIndex + 1);
    }
    if (seq.steps[q.stepInPattern] != null) {
      // Two notes landed on the same step (chord, or quantize collision) — stack as a chord.
      const existing = seq.steps[q.stepInPattern] as Note;
      existing.chord = [...(existing.chord ?? [existing.note]), q.note.note];
    } else {
      seq.steps[q.stepInPattern] = q.note;
    }
  }

  // ---- Assemble trackStorage + songStructure from lanes. ----
  const trackStorage = createEmptyTrackStorage(MAX_TRACK_PATTERN_SLOTS);

  // Primary lanes (lane 0) share one timeline; extra lanes are appended as additional
  // sequential measures on their target track (their own section, not overlapped).
  const primaryLaneEntries = Array.from(lanes.values()).filter((l) => l.lane === 0);
  const extraLaneEntries = Array.from(lanes.values())
    .filter((l) => l.lane > 0)
    .sort((a, b) => a.lane - b.lane || a.channel - b.channel);

  let primaryPatternCount = Math.max(1, samplerPatternCount, ...primaryLaneEntries.map((l) => l.patternCount), 0);
  primaryPatternCount = Math.min(primaryPatternCount, MAX_TRACK_PATTERN_SLOTS);

  for (const lane of primaryLaneEntries) {
    for (let p = 0; p < primaryPatternCount; p++) {
      trackStorage[lane.target][p] = lane.patterns.get(p) ?? emptyPartSequence();
    }
  }
  if (samplerPatternCount > 0) {
    for (let p = 0; p < primaryPatternCount; p++) {
      const bank0 = samplerPatterns.get(p) ?? emptyPartSequence();
      trackStorage.sampler[p] = [bank0, ...Array.from({ length: 7 }, () => emptyPartSequence())];
    }
  }

  const songStructure: Array<Record<TrackKey, number | null>> = [];
  const emptyMeasure = (): Record<TrackKey, number | null> => {
    const m = {} as Record<TrackKey, number | null>;
    for (const k of TRACK_KEYS) m[k] = null;
    return m;
  };

  for (let p = 0; p < primaryPatternCount; p++) {
    const measure = emptyMeasure();
    for (const lane of primaryLaneEntries) measure[lane.target] = p;
    if (samplerPatternCount > 0) measure.sampler = p;
    songStructure.push(measure);
  }

  let patternsCreated = primaryLaneEntries.length + (samplerPatternCount > 0 ? 1 : 0);

  for (const lane of extraLaneEntries) {
    const slotBase = songStructure.length; // append as new measures, own slot range on `lane.target`
    const count = Math.min(lane.patternCount, MAX_TRACK_PATTERN_SLOTS - primaryPatternCount);
    if (count < lane.patternCount) {
      warnings.push(`Channel ${lane.channel + 1} (extra) truncated to ${count} pattern slot(s) on ${lane.target} — track storage is capped at ${MAX_TRACK_PATTERN_SLOTS} slots.`);
    }
    if (count <= 0) continue;
    warnings.push(`Channel ${lane.channel + 1} had no default track — routed to ${lane.target} as ${count} extra pattern slot(s) appended after the main song (measures ${slotBase}-${slotBase + count - 1}).`);
    for (let i = 0; i < count; i++) {
      const slot = primaryPatternCount + i;
      trackStorage[lane.target][slot] = lane.patterns.get(i) ?? emptyPartSequence();
      const measure = emptyMeasure();
      measure[lane.target] = slot;
      songStructure.push(measure);
    }
    primaryPatternCount = Math.min(MAX_TRACK_PATTERN_SLOTS, primaryPatternCount + count);
    patternsCreated += count;
  }

  const notesImported = parsed.notes.length - notesUnmapped;

  // ---- Primary pattern (slot 0) for non-song-mode load. ----
  const pattern: Pattern = {
    ...EMPTY_PATTERN,
    partA: trackStorage.partA[0] as PartSequence ?? emptyPartSequence(),
    partB: trackStorage.partB[0] as PartSequence ?? emptyPartSequence(),
    bass2: trackStorage.bass2[0] as PartSequence ?? emptyPartSequence(),
    kick: trackStorage.kick[0] as PartSequence ?? emptyPartSequence(),
    snare: trackStorage.snare[0] as PartSequence ?? emptyPartSequence(),
    closedHat: trackStorage.closedHat[0] as PartSequence ?? emptyPartSequence(),
    openHat: trackStorage.openHat[0] as PartSequence ?? emptyPartSequence(),
    sampler: (trackStorage.sampler[0] as PartSequence[] | null) ?? EMPTY_PATTERN.sampler,
  };

  // ---- CC74 → filter cutoff automation on synth tracks (pattern 0 only, v1). ----
  const automation: SmfAutomationLane[] = [];
  let automationLanesConverted = 0;
  if (options.importCC74Automation) {
    for (const lane of primaryLaneEntries) {
      if (lane.target !== 'partA' && lane.target !== 'partB' && lane.target !== 'bass2') continue;
      const cc74 = parsed.controlChanges.filter((cc) => cc.channel === lane.channel && cc.controller === 74 && cc.tick < ticksPerStep * NUM_STEPS);
      if (cc74.length === 0) continue;
      const points: [number, number][] = cc74.map((cc) => {
        const step = Math.max(0, Math.min(NUM_STEPS - 1, cc.tick / ticksPerStep));
        return [step, clamp01(cc.value / 127)];
      });
      const automationTarget = lane.target === 'partA' ? 'synthA' : lane.target === 'partB' ? 'synthB' : 'bass2';
      automation.push({
        target: automationTarget,
        parameter: lane.target === 'bass2' ? 'cutoff' : 'filterCutoff',
        name: `SMF CC74 (ch ${lane.channel + 1})`,
        points,
        interpolation: 'linear',
        originalRange: [0, 127],
      });
      automationLanesConverted += 1;
    }
    const skippedCc74Channels = new Set(
      parsed.controlChanges
        .filter((cc) => cc.controller === 74 && cc.channel !== DRUM_MIDI_CHANNEL)
        .map((cc) => cc.channel),
    );
    for (const lane of primaryLaneEntries) skippedCc74Channels.delete(lane.channel);
    if (skippedCc74Channels.size > 0) {
      warnings.push(`CC74 on channel(s) ${Array.from(skippedCc74Channels).map((c) => c + 1).join(', ')} skipped — no synth track routed to that channel.`);
    }
  }

  const song: HyphonSmfSong = {
    version: 1,
    metadata: { name: 'Imported MIDI', importedFrom: 'smf', importedAt: new Date() },
    tempo: Math.round(bpm),
    timeSignature: [timeSig.numerator, timeSig.denominator],
    pattern,
    ...(automation.length > 0 ? { automation } : {}),
    ...(songStructure.length > 1 || samplerPatternCount > 1
      ? { songArrangement: { trackStorage, songStructure } }
      : {}),
  };

  if (notesImported === 0) {
    warnings.push('No notes found in this file — check the channel routing, or the file may only contain automation/meta events.');
  }

  const report: SmfImportReport = {
    notesImported,
    notesUnmapped,
    patternsCreated,
    tracksInFile: parsed.trackCount,
    channelsUsed,
    tempoChangesAfterBar1,
    timeSignatureMismatch,
    drumGmMisses,
    automationLanesConverted,
    warnings,
    formatVersion: parsed.format,
    ppq,
    bpm: Math.round(bpm),
  };

  return { success: true, song, report };
}

/**
 * Standard MIDI File (SMF) parser.
 *
 * Reads format 0 / format 1 `.mid` files: `MThd`/`MTrk` chunks, running
 * status, note on/off (incl. velocity-0-as-note-off), sustain pedal (CC64)
 * note-length extension, tempo map, time-signature meta events, and ignores
 * SysEx. Format 2 (independent multi-track) is rejected — Hyphon has one
 * transport, not several independent ones.
 *
 * Mirrors `RbsParser`'s API shape (`parseBytes(bytes, options)`, never
 * throws, discriminated `{ success, ... }` result) so the SMF path reads
 * the same way as the RBS path elsewhere in the app.
 */

import type {
  ParsedSmf,
  SmfControlChangeEvent,
  SmfNoteEvent,
  SmfParserError,
  SmfParserResult,
  SmfProgramChangeEvent,
  SmfTempoEvent,
  SmfTimeSignatureEvent,
  SmfTrackMeta,
} from './types';

export const MIN_SMF_FILE_SIZE = 14; // MThd header (8) + minimum length field (6)
export const MAX_SMF_FILE_SIZE = 10 * 1024 * 1024;
export const DEFAULT_PPQ = 480;
const DEFAULT_MICROSECONDS_PER_QUARTER = 500000; // 120 BPM
const DEFAULT_TIME_SIGNATURE: SmfTimeSignatureEvent = { tick: 0, numerator: 4, denominator: 4 };

function microsecondsPerQuarterToBpm(us: number): number {
  if (us <= 0) return 120;
  return 60000000 / us;
}

/** Cursor over a DataView with the primitives SMF track data needs. */
class ByteReader {
  pos = 0;
  private view: DataView;
  readonly length: number;

  constructor(view: DataView, length: number) {
    this.view = view;
    this.length = length;
  }

  get eof(): boolean {
    return this.pos >= this.length;
  }

  u8(): number {
    const v = this.view.getUint8(this.pos);
    this.pos += 1;
    return v;
  }

  u16(): number {
    const v = this.view.getUint16(this.pos, false);
    this.pos += 2;
    return v;
  }

  u32(): number {
    const v = this.view.getUint32(this.pos, false);
    this.pos += 4;
    return v;
  }

  bytes(n: number): Uint8Array {
    const out = new Uint8Array(this.view.buffer, this.view.byteOffset + this.pos, n);
    this.pos += n;
    return out;
  }

  skip(n: number): void {
    this.pos += n;
  }

  string(n: number): string {
    const bytes = this.bytes(n);
    let s = '';
    for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
    return s;
  }

  /** MIDI variable-length quantity: 7 bits per byte, MSB = continuation flag. */
  varint(): number {
    let value = 0;
    for (let i = 0; i < 5; i++) {
      const byte = this.u8();
      value = (value << 7) | (byte & 0x7f);
      if ((byte & 0x80) === 0) return value;
    }
    throw new Error('Malformed variable-length quantity (no terminating byte within 5 bytes)');
  }
}

interface ChannelSustainState {
  sustainOn: boolean;
  /** Notes still physically held (note-on received, no note-off yet). */
  active: Map<number, { startTick: number; velocity: number }>;
  /** Notes released while sustain was held — finalized when sustain lifts. */
  sustainedReleases: Map<number, { startTick: number; velocity: number }>;
}

function newChannelState(): ChannelSustainState {
  return { sustainOn: false, active: new Map(), sustainedReleases: new Map() };
}

/**
 * Parse a Standard MIDI File.
 * Never throws — all failures are returned as `{ success: false, error }`.
 */
export function parseSmfBytes(
  bytes: Uint8Array,
  options: { filename?: string; requireExtension?: boolean } = {},
): SmfParserResult {
  const filename = options.filename ?? 'input.mid';
  const requireExtension = options.requireExtension ?? true;

  try {
    if (requireExtension) {
      const lower = filename.toLowerCase();
      if (!lower.endsWith('.mid') && !lower.endsWith('.midi')) {
        return {
          success: false,
          error: { type: 'INVALID_FORMAT', message: `File "${filename}" does not have a .mid/.midi extension` },
        };
      }
    }

    if (bytes.byteLength < MIN_SMF_FILE_SIZE) {
      return {
        success: false,
        error: { type: 'CORRUPTED_DATA', section: 'header', details: `File too small (${bytes.byteLength} bytes, min ${MIN_SMF_FILE_SIZE})` },
      };
    }
    if (bytes.byteLength > MAX_SMF_FILE_SIZE) {
      return {
        success: false,
        error: { type: 'INVALID_FORMAT', message: 'File too large (max 10MB for SMF files)' },
      };
    }

    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    const reader = new ByteReader(view, bytes.byteLength);

    const magic = reader.string(4);
    if (magic !== 'MThd') {
      return {
        success: false,
        error: { type: 'INVALID_FORMAT', message: `Not a Standard MIDI File: expected "MThd" magic, got "${magic}"` },
      };
    }

    const headerLength = reader.u32();
    if (headerLength < 6 || reader.pos + headerLength > reader.length) {
      return {
        success: false,
        error: { type: 'CORRUPTED_DATA', section: 'MThd', details: `Invalid header chunk length (${headerLength})`, offset: reader.pos },
      };
    }

    const headerEnd = reader.pos + headerLength;
    const format = reader.u16();
    const ntrks = reader.u16();
    const division = reader.u16();
    reader.pos = headerEnd; // skip any header padding beyond the 6 documented bytes

    if (format !== 0 && format !== 1 && format !== 2) {
      return { success: false, error: { type: 'UNSUPPORTED_FORMAT', format } };
    }
    if (format === 2) {
      return { success: false, error: { type: 'UNSUPPORTED_FORMAT', format: 2 } };
    }

    if ((division & 0x8000) !== 0) {
      // SMPTE (frames/ticks) division — not a ticks-per-quarter-note grid.
      return {
        success: false,
        error: { type: 'CORRUPTED_DATA', section: 'MThd', details: 'SMPTE time division is not supported (only ticks-per-quarter-note files)' },
      };
    }
    const ppq = division === 0 ? DEFAULT_PPQ : division;

    const warnings: string[] = [];
    const tracks: SmfTrackMeta[] = [];
    const notes: SmfNoteEvent[] = [];
    const controlChanges: SmfControlChangeEvent[] = [];
    const programChanges: SmfProgramChangeEvent[] = [];
    const tempoMap: SmfTempoEvent[] = [];
    const timeSignatures: SmfTimeSignatureEvent[] = [];
    let totalTicks = 0;
    let trackIndex = 0;

    while (!reader.eof && trackIndex < ntrks) {
      if (reader.pos + 8 > reader.length) {
        warnings.push(`Truncated file: expected ${ntrks} tracks, only found ${trackIndex}`);
        break;
      }
      const chunkId = reader.string(4);
      const chunkLength = reader.u32();
      const chunkStart = reader.pos;
      const chunkEnd = chunkStart + chunkLength;

      if (chunkEnd > reader.length) {
        return {
          success: false,
          error: { type: 'CORRUPTED_DATA', section: `MTrk[${trackIndex}]`, details: 'Track chunk length runs past end of file', offset: chunkStart },
        };
      }

      if (chunkId !== 'MTrk') {
        // Unknown/vendor chunk — skip it (not a track).
        reader.pos = chunkEnd;
        continue;
      }

      const trackMeta: SmfTrackMeta = { index: trackIndex, endTick: 0 };
      const channelStates: ChannelSustainState[] = Array.from({ length: 16 }, () => newChannelState());
      let tick = 0;
      let runningStatus = 0;
      let trackEnded = false;

      const finalizeNote = (channel: number, note: number, startTick: number, velocity: number, endTick: number): void => {
        notes.push({ trackIndex, channel, note, velocity, startTick, endTick: Math.max(endTick, startTick) });
      };

      const noteOn = (channel: number, note: number, velocity: number, atTick: number): void => {
        const state = channelStates[channel];
        const existing = state.active.get(note);
        if (existing) {
          // Retrigger without a note-off: close the previous instance here.
          finalizeNote(channel, note, existing.startTick, existing.velocity, atTick);
          state.active.delete(note);
        }
        state.sustainedReleases.delete(note);
        state.active.set(note, { startTick: atTick, velocity });
      };

      const noteOff = (channel: number, note: number, atTick: number): void => {
        const state = channelStates[channel];
        const existing = state.active.get(note);
        if (!existing) return; // stray note-off, ignore
        state.active.delete(note);
        if (state.sustainOn) {
          state.sustainedReleases.set(note, existing);
        } else {
          finalizeNote(channel, note, existing.startTick, existing.velocity, atTick);
        }
      };

      const controlChange = (channel: number, controller: number, value: number, atTick: number): void => {
        controlChanges.push({ trackIndex, channel, controller, value, tick: atTick });
        if (controller !== 64) return; // sustain pedal only
        const state = channelStates[channel];
        const nowOn = value >= 64;
        if (nowOn && !state.sustainOn) {
          state.sustainOn = true;
        } else if (!nowOn && state.sustainOn) {
          state.sustainOn = false;
          for (const [note, held] of state.sustainedReleases) {
            finalizeNote(channel, note, held.startTick, held.velocity, atTick);
          }
          state.sustainedReleases.clear();
        }
      };

      while (reader.pos < chunkEnd && !trackEnded) {
        const delta = reader.varint();
        tick += delta;

        let statusByte = reader.u8();
        if (statusByte < 0x80) {
          // Running status: this byte is actually the first data byte.
          if (runningStatus === 0) {
            return {
              success: false,
              error: { type: 'CORRUPTED_DATA', section: `MTrk[${trackIndex}]`, details: 'Data byte encountered with no prior status byte (invalid running status)', offset: reader.pos - 1 },
            };
          }
          reader.pos -= 1;
          statusByte = runningStatus;
        } else if (statusByte < 0xf0) {
          runningStatus = statusByte;
        }

        if (statusByte === 0xff) {
          // Meta event.
          runningStatus = 0;
          const metaType = reader.u8();
          const len = reader.varint();
          const dataStart = reader.pos;
          switch (metaType) {
            case 0x51: {
              // Set Tempo: 3-byte microseconds-per-quarter-note.
              const us = (reader.u8() << 16) | (reader.u8() << 8) | reader.u8();
              tempoMap.push({ tick, microsecondsPerQuarter: us, bpm: microsecondsPerQuarterToBpm(us) });
              break;
            }
            case 0x58: {
              // Time Signature: nn dd cc bb (dd = power-of-2 denominator).
              const numerator = reader.u8();
              const denomPow = reader.u8();
              reader.skip(2); // MIDI clocks/click, 32nds/quarter — unused
              timeSignatures.push({ tick, numerator, denominator: 2 ** denomPow });
              break;
            }
            case 0x03: {
              trackMeta.name = reader.string(len).replace(/\0/g, '');
              break;
            }
            case 0x2f: {
              trackEnded = true;
              break;
            }
            default:
              // Unknown/uninteresting meta event (lyrics, marker, etc.) — skip.
              break;
          }
          reader.pos = dataStart + len;
        } else if (statusByte === 0xf0 || statusByte === 0xf7) {
          // SysEx (or continuation) — ignore payload entirely.
          const len = reader.varint();
          reader.skip(len);
        } else if (statusByte >= 0x80 && statusByte <= 0xef) {
          const channel = statusByte & 0x0f;
          const kind = statusByte & 0xf0;
          if (kind === 0x80) {
            const note = reader.u8();
            reader.u8(); // release velocity, unused
            noteOff(channel, note, tick);
          } else if (kind === 0x90) {
            const note = reader.u8();
            const velocity = reader.u8();
            if (velocity === 0) {
              noteOff(channel, note, tick);
            } else {
              noteOn(channel, note, velocity, tick);
            }
          } else if (kind === 0xa0) {
            reader.u8();
            reader.u8(); // polyphonic key pressure — unused
          } else if (kind === 0xb0) {
            const controller = reader.u8();
            const value = reader.u8();
            controlChange(channel, controller, value, tick);
          } else if (kind === 0xc0) {
            const program = reader.u8();
            programChanges.push({ trackIndex, channel, program, tick });
          } else if (kind === 0xd0) {
            reader.u8(); // channel pressure — unused
          } else if (kind === 0xe0) {
            reader.u8();
            reader.u8(); // pitch bend — unused in v1
          }
        } else {
          return {
            success: false,
            error: { type: 'CORRUPTED_DATA', section: `MTrk[${trackIndex}]`, details: `Unexpected status byte 0x${statusByte.toString(16)}`, offset: reader.pos - 1 },
          };
        }
      }

      // Close out any notes still active (or held by sustain) at end of track.
      for (let channel = 0; channel < 16; channel++) {
        const state = channelStates[channel];
        for (const [note, held] of state.active) {
          notes.push({ trackIndex, channel, note, velocity: held.velocity, startTick: held.startTick, endTick: tick, truncated: true });
        }
        for (const [note, held] of state.sustainedReleases) {
          notes.push({ trackIndex, channel, note, velocity: held.velocity, startTick: held.startTick, endTick: tick, truncated: true });
        }
      }

      trackMeta.endTick = tick;
      tracks.push(trackMeta);
      totalTicks = Math.max(totalTicks, tick);
      reader.pos = chunkEnd; // resync even if EOT was missing/short
      trackIndex += 1;
    }

    if (tracks.length === 0) {
      return { success: false, error: { type: 'CORRUPTED_DATA', section: 'MTrk', details: 'File contains no MTrk chunks' } };
    }

    if (tempoMap.length === 0 || tempoMap[0].tick !== 0) {
      tempoMap.unshift({ tick: 0, microsecondsPerQuarter: DEFAULT_MICROSECONDS_PER_QUARTER, bpm: 120 });
    }
    tempoMap.sort((a, b) => a.tick - b.tick);

    if (timeSignatures.length === 0) {
      timeSignatures.push({ ...DEFAULT_TIME_SIGNATURE });
    }
    timeSignatures.sort((a, b) => a.tick - b.tick);

    notes.sort((a, b) => a.startTick - b.startTick);

    const data: ParsedSmf = {
      format: format as 0 | 1,
      ppq,
      trackCount: tracks.length,
      tracks,
      notes,
      controlChanges,
      programChanges,
      tempoMap,
      timeSignatures,
      totalTicks,
      warnings,
    };

    return { success: true, data };
  } catch (err) {
    return {
      success: false,
      error: { type: 'READ_ERROR', message: err instanceof Error ? err.message : String(err) },
    };
  }
}

export class SmfParser {
  onProgress?: (percent: number) => void;

  async parseBytes(
    bytes: Uint8Array,
    options: { filename?: string; requireExtension?: boolean } = {},
  ): Promise<SmfParserResult> {
    this.onProgress?.(0);
    const result = parseSmfBytes(bytes, options);
    this.onProgress?.(100);
    return result;
  }
}

export async function parseSmfFile(file: File): Promise<SmfParserResult> {
  const buffer = await file.arrayBuffer();
  return parseSmfBytes(new Uint8Array(buffer), { filename: file.name });
}

import { attachWorkletPerf } from '../../utils/workletPerfBridge';
import { isAppleWebKit, logEngineFallback } from '../../utils/engineTelemetry';
import type { StepCallback, TransportClock, TransportSyncTelemetry } from './types';

let clockModulePromise: Promise<void> | null = null;

function ensureClockModule(context: AudioContext): Promise<void> {
  if (!clockModulePromise) {
    clockModulePromise = import('../../audio-worklets/clock-processor.ts?worker&url')
      .then(({ default: url }) => context.audioWorklet.addModule(url))
      .catch((err) => {
        clockModulePromise = null;
        throw err;
      });
  }
  return clockModulePromise;
}

/**
 * Internal AudioWorklet-backed transport clock (existing Hyphon behavior).
 */
export class InternalClockAdapter implements TransportClock {
  private context: AudioContext;
  private tempo: number;
  private swing: number;
  private steps: number;
  private clockNode: AudioWorkletNode | null = null;
  private running = false;
  private stepListeners = new Set<StepCallback>();
  private startPromise: Promise<void> | null = null;
  private mainThreadTimer: ReturnType<typeof setTimeout> | null = null;
  private mainThreadNextStep = 0;
  private mainThreadNextAt = 0;

  constructor(context: AudioContext, tempo: number, swing: number, steps: number) {
    this.context = context;
    this.tempo = tempo;
    this.swing = swing;
    this.steps = steps;
  }

  async ensureStarted(): Promise<void> {
    if (this.running && this.clockNode) return;
    if (this.startPromise) return this.startPromise;

    this.startPromise = (async () => {
      if (this.context.state === 'suspended') {
        await this.context.resume();
      }

      if (isAppleWebKit()) {
        logEngineFallback(
          'clock',
          'wasm-worklet',
          'clock-processor AudioWorklet skipped on WebKit; using main-thread timer',
        );
        this.stopMainThreadClock();
        this.running = true;
        this.mainThreadNextStep = 0;
        this.mainThreadNextAt = this.context.currentTime;
        this.tickMainThreadClock();
        return;
      }

      await ensureClockModule(this.context);

      if (this.clockNode) {
        this.clockNode.port.postMessage({ type: 'stop' });
        this.clockNode.disconnect();
        this.clockNode = null;
      }

      const node = new AudioWorkletNode(this.context, 'clock-processor', {
        numberOfInputs: 0,
        numberOfOutputs: 1,
        outputChannelCount: [1],
      });

      node.port.onmessage = (e: MessageEvent) => {
        if (e.data?.type === 'step') {
          const { step, audioTime } = e.data as { step: number; audioTime: number };
          for (const cb of this.stepListeners) cb(step, audioTime);
        }
      };

      attachWorkletPerf(node, 'clock');

      node.port.postMessage({ type: 'setTempo', tempo: this.tempo });
      node.port.postMessage({ type: 'setSwing', swing: this.swing });
      node.port.postMessage({ type: 'setSteps', steps: this.steps });
      node.port.postMessage({ type: 'start' });

      node.connect(this.context.destination);
      this.clockNode = node;
      this.running = true;
    })().finally(() => {
      this.startPromise = null;
    });

    return this.startPromise;
  }

  start(): void {
    void this.ensureStarted();
  }

  stop(): void {
    this.stopMainThreadClock();
    if (this.clockNode) {
      this.clockNode.port.postMessage({ type: 'stop' });
      this.clockNode.disconnect();
      this.clockNode = null;
    }
    this.running = false;
  }

  setTempo(bpm: number): void {
    this.tempo = bpm;
    this.clockNode?.port.postMessage({ type: 'setTempo', tempo: bpm });
  }

  setSwing(swing: number): void {
    this.swing = swing;
    this.clockNode?.port.postMessage({ type: 'setSwing', swing });
  }

  setSteps(steps: number): void {
    this.steps = steps;
    this.clockNode?.port.postMessage({ type: 'setSteps', steps });
  }

  resync(): void {
    /* Internal clock resets on start/stop only. */
  }

  private stepDurationSec(parity: 0 | 1): number {
    const base = 60 / (this.tempo * 4);
    const shift = this.swing * base * 0.5;
    return parity === 0 ? base + shift : base - shift;
  }

  private tickMainThreadClock(): void {
    if (!this.running) return;
    const now = this.context.currentTime;
    while (this.mainThreadNextAt <= now + 0.002) {
      const audioTime = this.mainThreadNextAt;
      const step = this.mainThreadNextStep;
      for (const cb of this.stepListeners) cb(step, audioTime);
      const parity = (step % 2) as 0 | 1;
      this.mainThreadNextAt += this.stepDurationSec(parity);
      this.mainThreadNextStep = (step + 1) % this.steps;
    }
    this.mainThreadTimer = setTimeout(() => this.tickMainThreadClock(), 8);
  }

  private stopMainThreadClock(): void {
    if (this.mainThreadTimer != null) {
      clearTimeout(this.mainThreadTimer);
      this.mainThreadTimer = null;
    }
  }

  onStep(cb: StepCallback): () => void {
    this.stepListeners.add(cb);
    return () => this.stepListeners.delete(cb);
  }

  getTelemetry(): TransportSyncTelemetry {
    return {
      mode: 'internal',
      state: this.running ? 'synced' : 'stopped',
      deviceName: null,
      measuredBpm: this.tempo,
      phaseErrorMs: 0,
      jitterMs: 0,
      droppedClocks: 0,
      isPlaying: this.running,
    };
  }

  isRunning(): boolean {
    return this.running;
  }

  dispose(): void {
    this.stop();
    this.stepListeners.clear();
  }
}

import { midiPortManager } from '../MidiPortManager';
import { PLAYBACK_THRESHOLDS } from '../../audio/playback/PlaybackHealthMonitor';
import { AudioTimeMap } from './audioTimeMap';
import { parseMidiRealtime, sppToStep } from './midiRealtime';
import { TempoEstimator } from './tempoEstimator';
import {
  AUDIO_SCHEDULE_LOOKAHEAD_MS,
  HOLDOVER_BEAT_PERIODS,
  HOLDOVER_STOP_BEATS,
  MIDI_TICKS_PER_STEP,
  type StepCallback,
  type TransportClock,
  type TransportSyncState,
  type TransportSyncTelemetry,
} from './types';

/**
 * Slave mode: follow external MIDI clock on selected input.
 */
export class SlaveClockAdapter implements TransportClock {
  private context: AudioContext;
  private tempo = 120;
  private swing = 0;
  private steps = 32;
  private inputDeviceId: string | null;
  private timeMap: AudioTimeMap;
  private estimator = new TempoEstimator();
  private running = false;
  private armed = false;
  private syncState: TransportSyncState = 'stopped';
  private totalTicks = 0;
  private currentStep = 0;
  private lastEmittedStep = -1;
  private lastStepAudio = 0;
  private resyncPending = false;
  private holdoverStartDom: number | null = null;
  private holdoverTimer: ReturnType<typeof setInterval> | null = null;
  private lossCheckTimer: ReturnType<typeof setInterval> | null = null;
  private lastClockDom: number | null = null;
  private stepListeners = new Set<StepCallback>();
  private unsubRealtime: (() => void) | null = null;
  private onStopExternal: (() => void) | null = null;

  constructor(
    context: AudioContext,
    tempo: number,
    swing: number,
    steps: number,
    inputDeviceId: string | null,
  ) {
    this.context = context;
    this.tempo = tempo;
    this.swing = swing;
    this.steps = steps;
    this.inputDeviceId = inputDeviceId;
    this.timeMap = new AudioTimeMap(context);
    this.estimator.seedPeriodFromBpm(tempo);
    midiPortManager.selectInput(inputDeviceId);
  }

  /** Arm listening without external start yet. */
  setArmed(armed: boolean): void {
    this.armed = armed;
    if (armed && !this.unsubRealtime) {
      this.attachRealtime();
      this.syncState = 'armed';
    } else if (!armed && !this.running) {
      this.syncState = 'stopped';
    }
  }

  setOnStopExternal(cb: () => void): void {
    this.onStopExternal = cb;
  }

  start(): void {
    this.setArmed(true);
  }

  stop(): void {
    this.running = false;
    this.armed = false;
    this.syncState = 'stopped';
    this.clearHoldover();
    this.detachRealtime();
  }

  setTempo(_bpm: number): void {
    /* Slave tempo comes from external clock. */
  }

  setSwing(swing: number): void {
    this.swing = swing;
  }

  setSteps(steps: number): void {
    this.steps = steps;
  }

  resync(): void {
    this.resyncPending = true;
  }

  onStep(cb: StepCallback): () => void {
    this.stepListeners.add(cb);
    return () => this.stepListeners.delete(cb);
  }

  getTelemetry(): TransportSyncTelemetry {
    const snap = this.estimator.getSnapshot();
    const inputs = midiPortManager.getInputs();
    const device = inputs.find((i) => i.id === this.inputDeviceId);
    return {
      mode: 'slave',
      state: this.syncState,
      deviceName: device?.name ?? (this.inputDeviceId ? 'device not found' : null),
      measuredBpm: snap.measuredBpm,
      phaseErrorMs: snap.phaseErrorMs,
      jitterMs: snap.jitterMs,
      droppedClocks: snap.droppedClocks,
      isPlaying: this.running,
    };
  }

  dispose(): void {
    this.stop();
    this.stepListeners.clear();
  }

  private attachRealtime(): void {
    if (this.unsubRealtime) return;
    void midiPortManager.ensureAccess();
    this.unsubRealtime = midiPortManager.onRealtimeMessage((deviceId, data, domTime) => {
      if (this.inputDeviceId && deviceId !== this.inputDeviceId) return;
      this.handleRealtime(data, domTime);
    });
  }

  private detachRealtime(): void {
    this.unsubRealtime?.();
    this.unsubRealtime = null;
  }

  private handleRealtime(data: Uint8Array, domTime: number): void {
    const msg = parseMidiRealtime(data);
    if (!msg) return;

    switch (msg.type) {
      case 'start':
        this.handleStart(domTime);
        break;
      case 'continue':
        this.handleContinue(domTime);
        break;
      case 'stop':
        this.handleStop();
        break;
      case 'songPosition':
        this.handleSpp(msg.sixteenthNotes);
        break;
      case 'clock':
        if (this.running || this.armed) this.handleClock(domTime);
        break;
    }
  }

  private handleStart(domTime: number): void {
    this.running = true;
    this.armed = true;
    this.syncState = 'synced';
    this.totalTicks = 0;
    this.currentStep = 0;
    this.estimator.reset();
    this.estimator.observeClock(domTime);
    this.lastClockDom = domTime;
    this.holdoverStartDom = null;
    this.clearHoldover();
    this.attachRealtime();
    this.emitStep(0, domTime);
  }

  private handleContinue(domTime: number): void {
    this.running = true;
    this.syncState = 'synced';
    this.estimator.observeClock(domTime);
    this.lastClockDom = domTime;
    this.holdoverStartDom = null;
    this.clearHoldover();
    this.attachRealtime();
  }

  private handleStop(): void {
    this.running = false;
    this.syncState = 'stopped';
    this.clearHoldover();
    this.onStopExternal?.();
  }

  private handleSpp(sixteenthNotes: number): void {
    const step = sppToStep(sixteenthNotes, this.steps);
    if (step >= this.currentStep) {
      this.currentStep = step;
      this.totalTicks = step * MIDI_TICKS_PER_STEP;
    }
  }

  private handleClock(domTime: number): void {
    if (!this.running) return;

    this.lastClockDom = domTime;
    this.holdoverStartDom = null;
    if (this.syncState === 'holdover') this.syncState = 'synced';

    const accepted = this.estimator.observeClock(domTime);
    if (!accepted && this.estimator.getSnapshot().droppedClocks > 0) {
      /* Still advance on clock even if interval rejected — external master is authoritative. */
    }

    this.totalTicks++;

    if (this.resyncPending && this.currentStep === 0 && this.totalTicks % 24 === 0) {
      this.resyncPending = false;
      this.timeMap.reanchor(this.context);
    }

    if (this.totalTicks % MIDI_TICKS_PER_STEP !== 0) return;

    const step = this.currentStep;
    this.currentStep = (this.currentStep + 1) % this.steps;

    // Start already emitted step 0; skip duplicate at first 16th boundary.
    if (this.totalTicks === MIDI_TICKS_PER_STEP && step === 0) return;

    this.emitStep(step, domTime);
    this.startLossWatch();
  }

  private emitStep(step: number, domTime: number): void {
    const nowAudio = this.context.currentTime;
    let audioTime =
      this.timeMap.domToAudio(domTime) + AUDIO_SCHEDULE_LOOKAHEAD_MS / 1000;
    audioTime = Math.max(nowAudio + 0.001, audioTime);

    const dupMs = (audioTime - this.lastStepAudio) * 1000;
    if (
      step === this.lastEmittedStep &&
      dupMs < PLAYBACK_THRESHOLDS.stepDuplicateGuardMs
    ) {
      return;
    }

    this.lastEmittedStep = step;
    this.lastStepAudio = audioTime;

    for (const cb of this.stepListeners) cb(step, audioTime);
  }

  private startLossWatch(): void {
    if (this.lossCheckTimer) return;
    this.lossCheckTimer = setInterval(() => {
      if (!this.running || this.lastClockDom == null) return;
      const snap = this.estimator.getSnapshot();
      const period = snap.periodMs ?? (60_000 / this.tempo) / 24;
      const nowDom = typeof performance !== 'undefined' ? performance.now() : Date.now();
      const sinceLast = nowDom - this.lastClockDom;

      if (sinceLast > period * 24 * HOLDOVER_BEAT_PERIODS) {
        if (this.syncState !== 'holdover') {
          this.syncState = 'holdover';
          this.holdoverStartDom = nowDom;
          this.startHoldover(period);
        } else if (
          this.holdoverStartDom != null &&
          nowDom - this.holdoverStartDom > period * 24 * HOLDOVER_STOP_BEATS
        ) {
          this.syncState = 'degraded';
          this.handleStop();
        }
      }
    }, 50);
  }

  private startHoldover(periodMs: number): void {
    this.clearHoldover();
    this.holdoverTimer = setInterval(() => {
      if (!this.running || this.syncState !== 'holdover') return;
      const dom = typeof performance !== 'undefined' ? performance.now() : Date.now();
      this.handleClock(dom);
    }, periodMs);
  }

  private clearHoldover(): void {
    if (this.holdoverTimer) {
      clearInterval(this.holdoverTimer);
      this.holdoverTimer = null;
    }
    if (this.lossCheckTimer) {
      clearInterval(this.lossCheckTimer);
      this.lossCheckTimer = null;
    }
  }
}

