// Project storage over the Origin Private File System (OPFS), with an
// IndexedDB fallback for browsers that expose `navigator.storage.getDirectory`
// only partially (or not at all) and an in-memory fallback for SSR/tests.
//
// Unlike `utils/projectPersistence.ts` (localStorage, 512 KB cap, strips
// samples/background image before saving), a project here is a directory:
//   hyphon-projects/<id>/project.json       — SavedSongData minus blobs
//   hyphon-projects/<id>/samples/<hash>.wav — content-addressed sample banks
//   hyphon-projects/<id>/assets/<hash>.ext  — content-addressed background image
//   hyphon-projects/<id>/shutdown.json      — { clean, at } crash-recovery marker
// Duplicate sample content (same bank re-saved, or shared across projects)
// is written once and referenced by hash, so autosaving repeatedly does not
// multiply storage use.
//
// There is no size cap: OPFS/IndexedDB quotas are origin-wide and much larger
// than localStorage (typically a meaningful fraction of free disk), and
// `requestPersistence()` asks the browser not to evict the origin under
// storage pressure.

import type { SavedSongData } from '@/types';
import {
    AUTOSAVE_KEY,
    loadSessionFromLocalStorage,
    clearSessionFromLocalStorage,
    type StorageBackend,
} from '@/utils/projectPersistence';

export const PROJECT_STORE_VERSION = 1;
export const AUTOSAVE_PROJECT_ID = 'autosave';

const PROJECTS_ROOT = 'hyphon-projects';

export interface ProjectMeta {
    id: string;
    updatedAt: number;
    /** false when the last session touching this project did not shut down cleanly. */
    cleanShutdown: boolean;
}

export interface SaveProjectResult {
    ok: boolean;
    error?: string;
}

// ── File backend abstraction (directory paths use '/', no leading/trailing slash) ─

export interface ProjectFileBackend {
    readonly kind: 'opfs' | 'idb' | 'memory';
    writeFile(path: string, data: Uint8Array | string): Promise<void>;
    readFile(path: string): Promise<Uint8Array | null>;
    readText(path: string): Promise<string | null>;
    exists(path: string): Promise<boolean>;
    deleteFile(path: string): Promise<void>;
    /** Immediate child directory names under `dirPath` (no trailing slash). */
    listDirs(dirPath: string): Promise<string[]>;
    /** Recursively delete everything under (and including) `dirPath`. */
    deleteDir(dirPath: string): Promise<void>;
}

// ── content addressing / encoding helpers ──────────────────────────────────────

/** Non-cryptographic content hash (FNV-1a/64). Good enough for local dedup keys. */
export function contentHash(bytes: Uint8Array): string {
    let hash = 0xcbf29ce484222325n;
    const prime = 0x100000001b3n;
    for (let i = 0; i < bytes.length; i++) {
        hash ^= BigInt(bytes[i]);
        hash = (hash * prime) & 0xffffffffffffffffn;
    }
    return hash.toString(16).padStart(16, '0');
}

function base64ToBytes(base64: string): Uint8Array {
    if (typeof atob === 'function') {
        const bin = atob(base64);
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        return bytes;
    }
    return new Uint8Array(Buffer.from(base64, 'base64'));
}

function bytesToBase64(bytes: Uint8Array): string {
    if (typeof btoa === 'function') {
        let bin = '';
        for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
        return btoa(bin);
    }
    return Buffer.from(bytes).toString('base64');
}

function parseDataUrl(url: string): { mime: string; base64: string } | null {
    const match = /^data:([^;,]*)(?:;charset=[^;,]+)?;base64,([\s\S]*)$/.exec(url);
    if (!match) return null;
    return { mime: match[1] || 'application/octet-stream', base64: match[2] };
}

function toDataUrl(mime: string, bytes: Uint8Array): string {
    return `data:${mime};base64,${bytesToBase64(bytes)}`;
}

const MIME_TO_EXT: Record<string, string> = {
    'image/png': 'png',
    'image/jpeg': 'jpg',
    'image/webp': 'webp',
    'image/gif': 'gif',
    'audio/wav': 'wav',
    'audio/wave': 'wav',
    'audio/x-wav': 'wav',
};

function mimeToExt(mime: string): string {
    return MIME_TO_EXT[mime] ?? 'bin';
}

// ── in-memory backend (SSR / tests / last-resort fallback) ─────────────────────

class MemoryBackend implements ProjectFileBackend {
    readonly kind = 'memory' as const;
    private files = new Map<string, Uint8Array>();

    writeFile(path: string, data: Uint8Array | string): Promise<void> {
        this.files.set(path, typeof data === 'string' ? new TextEncoder().encode(data) : data);
        return Promise.resolve();
    }
    readFile(path: string): Promise<Uint8Array | null> {
        return Promise.resolve(this.files.get(path) ?? null);
    }
    readText(path: string): Promise<string | null> {
        const bytes = this.files.get(path);
        return Promise.resolve(bytes ? new TextDecoder().decode(bytes) : null);
    }
    exists(path: string): Promise<boolean> {
        return Promise.resolve(this.files.has(path));
    }
    deleteFile(path: string): Promise<void> {
        this.files.delete(path);
        return Promise.resolve();
    }
    listDirs(dirPath: string): Promise<string[]> {
        const prefix = `${dirPath}/`;
        const names = new Set<string>();
        for (const key of this.files.keys()) {
            if (!key.startsWith(prefix)) continue;
            const seg = key.slice(prefix.length).split('/')[0];
            if (seg) names.add(seg);
        }
        return Promise.resolve([...names]);
    }
    deleteDir(dirPath: string): Promise<void> {
        const prefix = `${dirPath}/`;
        for (const key of [...this.files.keys()]) {
            if (key === dirPath || key.startsWith(prefix)) this.files.delete(key);
        }
        return Promise.resolve();
    }
}

// ── IndexedDB backend ────────────────────────────────────────────────────────

const IDB_NAME = 'hyphon-project-store';
const IDB_STORE = 'files';

interface StoredRecord {
    path: string;
    bytes: Uint8Array;
}

class IdbBackend implements ProjectFileBackend {
    readonly kind = 'idb' as const;
    private dbPromise: Promise<IDBDatabase> | null = null;

    private db(): Promise<IDBDatabase> {
        if (!this.dbPromise) {
            this.dbPromise = new Promise((resolve, reject) => {
                const req = indexedDB.open(IDB_NAME, 1);
                req.onupgradeneeded = () => {
                    const db = req.result;
                    if (!db.objectStoreNames.contains(IDB_STORE)) {
                        db.createObjectStore(IDB_STORE, { keyPath: 'path' });
                    }
                };
                req.onsuccess = () => resolve(req.result);
                req.onerror = () => reject(req.error);
            });
        }
        return this.dbPromise;
    }

    /**
     * Issues a single request against a fresh transaction's object store and
     * resolves with its `.result` once the transaction actually commits
     * (`oncomplete`), not merely once the request itself reports success. A
     * request can succeed and then have its transaction abort (a quota
     * error, another request in the same transaction failing); waiting for
     * `oncomplete` is the only way to know the write is durable.
     */
    private async runRequest<T>(
        mode: IDBTransactionMode,
        fn: (store: IDBObjectStore) => IDBRequest<T>,
    ): Promise<T> {
        const db = await this.db();
        return new Promise<T>((resolve, reject) => {
            const tx = db.transaction(IDB_STORE, mode);
            let request: IDBRequest<T>;
            try {
                request = fn(tx.objectStore(IDB_STORE));
            } catch (err) {
                reject(err as Error);
                return;
            }
            tx.oncomplete = () => resolve(request.result);
            tx.onerror = () => reject(tx.error ?? request.error ?? new Error('IndexedDB transaction failed'));
            tx.onabort = () => reject(tx.error ?? new Error('IndexedDB transaction aborted'));
        });
    }

    async writeFile(path: string, data: Uint8Array | string): Promise<void> {
        const bytes = typeof data === 'string' ? new TextEncoder().encode(data) : data;
        await this.runRequest('readwrite', (store) => store.put({ path, bytes } satisfies StoredRecord));
    }
    async readFile(path: string): Promise<Uint8Array | null> {
        const rec = await this.runRequest(
            'readonly',
            (store) => store.get(path) as IDBRequest<StoredRecord | undefined>,
        );
        return rec?.bytes ?? null;
    }
    async readText(path: string): Promise<string | null> {
        const bytes = await this.readFile(path);
        return bytes ? new TextDecoder().decode(bytes) : null;
    }
    async exists(path: string): Promise<boolean> {
        const key = await this.runRequest('readonly', (store) => store.getKey(path));
        return key !== undefined;
    }
    async deleteFile(path: string): Promise<void> {
        await this.runRequest('readwrite', (store) => store.delete(path));
    }
    async listDirs(dirPath: string): Promise<string[]> {
        const prefix = `${dirPath}/`;
        const range = IDBKeyRange.bound(prefix, `${prefix}￿`);
        const keys = await this.runRequest('readonly', (store) => store.getAllKeys(range));
        const names = new Set<string>();
        for (const key of keys) {
            const seg = String(key).slice(prefix.length).split('/')[0];
            if (seg) names.add(seg);
        }
        return [...names];
    }
    async deleteDir(dirPath: string): Promise<void> {
        const prefix = `${dirPath}/`;
        const range = IDBKeyRange.bound(prefix, `${prefix}￿`);
        const db = await this.db();
        // getAllKeys() and every delete() it triggers are issued within one
        // readwrite transaction, all synchronously inside getAllKeys'
        // onsuccess handler — no `await` between them, so the transaction
        // cannot go inactive mid-sequence (the classic IDB async/await
        // pitfall this backend otherwise avoids by resolving on oncomplete).
        await new Promise<void>((resolve, reject) => {
            const tx = db.transaction(IDB_STORE, 'readwrite');
            const store = tx.objectStore(IDB_STORE);
            const getKeysReq = store.getAllKeys(range);
            getKeysReq.onsuccess = () => {
                for (const key of getKeysReq.result) store.delete(key);
            };
            tx.oncomplete = () => resolve();
            tx.onerror = () => reject(tx.error ?? getKeysReq.error ?? new Error('deleteDir transaction failed'));
            tx.onabort = () => reject(tx.error ?? new Error('deleteDir transaction aborted'));
        });
    }
}

// ── OPFS backend ─────────────────────────────────────────────────────────────
// Typed locally (not via the DOM lib) so this file compiles regardless of
// whether the project's TS `lib` includes the File System Access API.

interface OpfsWritable {
    write(data: Uint8Array | string): Promise<void>;
    close(): Promise<void>;
}
interface OpfsFileHandle {
    kind: 'file';
    getFile(): Promise<{ arrayBuffer(): Promise<ArrayBuffer> }>;
    createWritable(): Promise<OpfsWritable>;
}
interface OpfsDirectoryHandle {
    kind: 'directory';
    getDirectoryHandle(name: string, options?: { create?: boolean }): Promise<OpfsDirectoryHandle>;
    getFileHandle(name: string, options?: { create?: boolean }): Promise<OpfsFileHandle>;
    removeEntry(name: string, options?: { recursive?: boolean }): Promise<void>;
    entries(): AsyncIterableIterator<[string, OpfsDirectoryHandle | OpfsFileHandle]>;
}

class OpfsBackend implements ProjectFileBackend {
    readonly kind = 'opfs' as const;
    private readonly root: OpfsDirectoryHandle;
    constructor(root: OpfsDirectoryHandle) {
        this.root = root;
    }

    private async getDir(segments: string[], create: boolean): Promise<OpfsDirectoryHandle | null> {
        let dir = this.root;
        for (const seg of segments) {
            try {
                dir = await dir.getDirectoryHandle(seg, { create });
            } catch {
                return null;
            }
        }
        return dir;
    }

    private split(path: string): { dirs: string[]; name: string } {
        const parts = path.split('/').filter(Boolean);
        return { dirs: parts.slice(0, -1), name: parts[parts.length - 1] };
    }

    async writeFile(path: string, data: Uint8Array | string): Promise<void> {
        const { dirs, name } = this.split(path);
        const dir = await this.getDir(dirs, true);
        if (!dir) throw new Error(`OPFS: could not create directory for ${path}`);
        const fileHandle = await dir.getFileHandle(name, { create: true });
        const writable = await fileHandle.createWritable();
        await writable.write(typeof data === 'string' ? new TextEncoder().encode(data) : data);
        await writable.close();
    }
    async readFile(path: string): Promise<Uint8Array | null> {
        const { dirs, name } = this.split(path);
        const dir = await this.getDir(dirs, false);
        if (!dir) return null;
        try {
            const fileHandle = await dir.getFileHandle(name);
            const file = await fileHandle.getFile();
            return new Uint8Array(await file.arrayBuffer());
        } catch {
            return null;
        }
    }
    async readText(path: string): Promise<string | null> {
        const bytes = await this.readFile(path);
        return bytes ? new TextDecoder().decode(bytes) : null;
    }
    async exists(path: string): Promise<boolean> {
        return (await this.readFile(path)) !== null;
    }
    async deleteFile(path: string): Promise<void> {
        const { dirs, name } = this.split(path);
        const dir = await this.getDir(dirs, false);
        if (!dir) return;
        try {
            await dir.removeEntry(name);
        } catch {
            /* already gone */
        }
    }
    async listDirs(dirPath: string): Promise<string[]> {
        const segments = dirPath.split('/').filter(Boolean);
        const dir = await this.getDir(segments, false);
        if (!dir) return [];
        const names: string[] = [];
        for await (const [childName, handle] of dir.entries()) {
            if (handle.kind === 'directory') names.push(childName);
        }
        return names;
    }
    async deleteDir(dirPath: string): Promise<void> {
        const segments = dirPath.split('/').filter(Boolean);
        const name = segments.pop();
        if (!name) return;
        const parent = await this.getDir(segments, false);
        if (!parent) return;
        try {
            await parent.removeEntry(name, { recursive: true });
        } catch {
            /* already gone */
        }
    }
}

async function detectBackend(): Promise<ProjectFileBackend> {
    if (typeof navigator !== 'undefined') {
        const storage = navigator.storage as unknown as {
            getDirectory?: () => Promise<OpfsDirectoryHandle>;
        };
        if (typeof storage?.getDirectory === 'function') {
            try {
                const root = await storage.getDirectory();
                // Probe write access — some embedders expose the API but throw
                // (private browsing, permission policy) on first real use.
                const probe = await root.getDirectoryHandle('.hyphon-opfs-probe', { create: true });
                void probe;
                await root.removeEntry('.hyphon-opfs-probe', { recursive: true });
                return new OpfsBackend(root);
            } catch {
                /* fall through to IndexedDB */
            }
        }
    }
    if (typeof indexedDB !== 'undefined') {
        return new IdbBackend();
    }
    return new MemoryBackend();
}

// ── stored project.json shape ────────────────────────────────────────────────

interface StoredProjectJson extends Omit<SavedSongData, 'embeddedSamples' | 'backgroundImage'> {
    schemaVersion: number;
    updatedAt: number;
    sampleRefs?: Record<string, string>;
    backgroundImageRef?: string;
    backgroundImageMime?: string;
    /** Background image was a plain (non-data:) URL — stored verbatim, nothing to content-address. */
    backgroundImageUrl?: string;
}

interface ShutdownMeta {
    clean: boolean;
    at: number;
}

// ── ProjectStore ─────────────────────────────────────────────────────────────

export class ProjectStore {
    private backendPromise: Promise<ProjectFileBackend> | null = null;
    private readonly backendOverride?: ProjectFileBackend;

    /** Pass a backend to bypass auto-detection (tests, or a forced fallback). */
    constructor(backendOverride?: ProjectFileBackend) {
        this.backendOverride = backendOverride;
    }

    private getBackend(): Promise<ProjectFileBackend> {
        if (this.backendOverride) return Promise.resolve(this.backendOverride);
        if (!this.backendPromise) this.backendPromise = detectBackend();
        return this.backendPromise;
    }

    async backendKind(): Promise<ProjectFileBackend['kind']> {
        return (await this.getBackend()).kind;
    }

    private path(id: string, ...segments: string[]): string {
        return [PROJECTS_ROOT, id, ...segments].join('/');
    }

    async saveProject(id: string, data: SavedSongData): Promise<SaveProjectResult> {
        try {
            const backend = await this.getBackend();
            const { embeddedSamples, backgroundImage, ...rest } = data;

            let sampleRefs: Record<string, string> | undefined;
            if (embeddedSamples) {
                sampleRefs = {};
                for (const [bankIdx, dataUrl] of Object.entries(embeddedSamples)) {
                    const parsed = parseDataUrl(dataUrl);
                    if (!parsed) continue;
                    const bytes = base64ToBytes(parsed.base64);
                    const hash = contentHash(bytes);
                    const samplePath = this.path(id, 'samples', `${hash}.wav`);
                    if (!(await backend.exists(samplePath))) {
                        await backend.writeFile(samplePath, bytes);
                    }
                    sampleRefs[bankIdx] = hash;
                }
                if (Object.keys(sampleRefs).length === 0) sampleRefs = undefined;
            }

            let backgroundImageRef: string | undefined;
            let backgroundImageMime: string | undefined;
            let backgroundImageUrl: string | undefined;
            if (backgroundImage) {
                const parsed = parseDataUrl(backgroundImage);
                if (parsed) {
                    const bytes = base64ToBytes(parsed.base64);
                    const hash = contentHash(bytes);
                    const assetPath = this.path(id, 'assets', `${hash}.${mimeToExt(parsed.mime)}`);
                    if (!(await backend.exists(assetPath))) {
                        await backend.writeFile(assetPath, bytes);
                    }
                    backgroundImageRef = hash;
                    backgroundImageMime = parsed.mime;
                } else {
                    backgroundImageUrl = backgroundImage;
                }
            }

            const stored: StoredProjectJson = {
                ...rest,
                schemaVersion: PROJECT_STORE_VERSION,
                updatedAt: Date.now(),
                sampleRefs,
                backgroundImageRef,
                backgroundImageMime,
                backgroundImageUrl,
            };
            // Written *before* project.json: a save implies the session is
            // mid-edit, and if the app dies between these two writes, the
            // next boot should still see "dirty" rather than a stale "clean"
            // from a previous, no-longer-accurate save. Only an explicit
            // markCleanShutdown() flips this back.
            const dirtyMeta: ShutdownMeta = { clean: false, at: Date.now() };
            await backend.writeFile(this.path(id, 'shutdown.json'), JSON.stringify(dirtyMeta));
            await backend.writeFile(this.path(id, 'project.json'), JSON.stringify(stored));
            return { ok: true };
        } catch (err) {
            return { ok: false, error: err instanceof Error ? err.message : String(err) };
        }
    }

    async loadProject(id: string): Promise<SavedSongData | null> {
        const backend = await this.getBackend();
        const text = await backend.readText(this.path(id, 'project.json'));
        if (!text) return null;

        let stored: StoredProjectJson;
        try {
            stored = JSON.parse(text) as StoredProjectJson;
        } catch {
            return null;
        }

        const { sampleRefs, backgroundImageRef, backgroundImageMime, backgroundImageUrl, schemaVersion: _sv, updatedAt: _u, ...rest } = stored;
        void _sv;
        void _u;

        const embeddedSamples: Record<number, string> = {};
        if (sampleRefs) {
            for (const [bankIdx, hash] of Object.entries(sampleRefs)) {
                const bytes = await backend.readFile(this.path(id, 'samples', `${hash}.wav`));
                if (bytes) embeddedSamples[Number(bankIdx)] = toDataUrl('audio/wav', bytes);
            }
        }

        let backgroundImage: string | undefined = backgroundImageUrl;
        if (backgroundImageRef && backgroundImageMime) {
            const bytes = await backend.readFile(
                this.path(id, 'assets', `${backgroundImageRef}.${mimeToExt(backgroundImageMime)}`),
            );
            if (bytes) backgroundImage = toDataUrl(backgroundImageMime, bytes);
        }

        return {
            ...(rest as Omit<SavedSongData, 'embeddedSamples' | 'backgroundImage'>),
            ...(Object.keys(embeddedSamples).length ? { embeddedSamples } : {}),
            ...(backgroundImage ? { backgroundImage } : {}),
        } as SavedSongData;
    }

    async hasProject(id: string): Promise<boolean> {
        const backend = await this.getBackend();
        return backend.exists(this.path(id, 'project.json'));
    }

    async deleteProject(id: string): Promise<void> {
        const backend = await this.getBackend();
        await backend.deleteDir(this.path(id));
    }

    async listProjects(): Promise<ProjectMeta[]> {
        const backend = await this.getBackend();
        const ids = await backend.listDirs(PROJECTS_ROOT);
        const metas: ProjectMeta[] = [];
        for (const id of ids) {
            const text = await backend.readText(this.path(id, 'project.json'));
            if (!text) continue;
            let updatedAt = 0;
            try {
                updatedAt = (JSON.parse(text) as { updatedAt?: number }).updatedAt ?? 0;
            } catch {
                /* corrupt project.json — still list it so it can be inspected/deleted */
            }
            const shutdown = await this.readShutdownMeta(backend, id);
            metas.push({ id, updatedAt, cleanShutdown: shutdown?.clean ?? true });
        }
        return metas.sort((a, b) => b.updatedAt - a.updatedAt);
    }

    private async readShutdownMeta(backend: ProjectFileBackend, id: string): Promise<ShutdownMeta | null> {
        const text = await backend.readText(this.path(id, 'shutdown.json'));
        if (!text) return null;
        try {
            return JSON.parse(text) as ShutdownMeta;
        } catch {
            return null;
        }
    }

    async markCleanShutdown(id: string): Promise<void> {
        const backend = await this.getBackend();
        if (!(await backend.exists(this.path(id, 'project.json')))) return;
        const cleanMeta: ShutdownMeta = { clean: true, at: Date.now() };
        await backend.writeFile(this.path(id, 'shutdown.json'), JSON.stringify(cleanMeta));
    }

    /**
     * True/false = whether the project's last session shut down cleanly.
     * Null = the project does not exist (nothing to recover).
     */
    async wasCleanShutdown(id: string): Promise<boolean | null> {
        const backend = await this.getBackend();
        if (!(await backend.exists(this.path(id, 'project.json')))) return null;
        const meta = await this.readShutdownMeta(backend, id);
        // No shutdown.json yet (older data, or first-ever save mid-flight) — assume clean.
        return meta ? meta.clean : true;
    }

    /** Ask the browser not to evict this origin's storage under pressure. */
    async requestPersistence(): Promise<boolean> {
        if (typeof navigator === 'undefined' || !navigator.storage?.persist) return false;
        try {
            return await navigator.storage.persist();
        } catch {
            return false;
        }
    }

    async getQuota(): Promise<{ usage: number; quota: number } | null> {
        if (typeof navigator === 'undefined' || !navigator.storage?.estimate) return null;
        try {
            const { usage, quota } = await navigator.storage.estimate();
            return { usage: usage ?? 0, quota: quota ?? 0 };
        } catch {
            return null;
        }
    }

    /**
     * Lift a legacy `hyphon:autosave:v1` localStorage payload (see
     * utils/projectPersistence.ts) into the autosave project on first run,
     * then clear the old key. No-op (but still clears the key) when a newer
     * OPFS/IndexedDB autosave already exists, so a stale localStorage blob
     * never clobbers fresher data. Returns true when a legacy payload was found.
     * The localStorage key is cleared only once the data is durably migrated
     * (or was already superseded) — never on a failed save, which would
     * otherwise delete the only copy.
     */
    async migrateLegacyAutosave(storage?: StorageBackend): Promise<boolean> {
        const legacy = loadSessionFromLocalStorage(storage);
        if (!legacy) return false;
        if (!(await this.hasProject(AUTOSAVE_PROJECT_ID))) {
            const { autosaveVersion: _av, savedAt: _sa, samplesStripped: _ss, ...rest } = legacy;
            void _av;
            void _sa;
            void _ss;
            const result = await this.saveProject(AUTOSAVE_PROJECT_ID, rest as SavedSongData);
            if (!result.ok) {
                throw new Error(result.error ?? 'Legacy autosave migration failed');
            }
        }
        clearSessionFromLocalStorage(storage);
        return true;
    }
}

export const projectStore = new ProjectStore();

export { AUTOSAVE_KEY as LEGACY_AUTOSAVE_KEY };

// ONNX Runtime is loaded through the shared `ortRuntime` helper, which owns the
// dynamic import (so ORT never lands in the entry chunk) and is the single
// writer of `ort.env` — see src/services/ortRuntime.ts.
import type * as ort from 'onnxruntime-web';
import { loadOrt, type Ort } from './ortRuntime';

interface StyleData {
    style_ttl: { data: number[], dims: number[] };
    style_dp: { data: number[], dims: number[] };
}

export class Style {
    ttl: ort.Tensor;
    dp: ort.Tensor;

    constructor(ttlTensor: ort.Tensor, dpTensor: ort.Tensor) {
        this.ttl = ttlTensor;
        this.dp = dpTensor;
    }
}

class UnicodeProcessor {
    indexer: number[];

    constructor(indexer: number[]) {
        this.indexer = indexer;
    }

    call(textList: string[]) {
        const processedTexts = textList.map(text => this.preprocessText(text));
        const textIdsLengths = processedTexts.map(text => text.length);
        const maxLen = Math.max(...textIdsLengths);

        const textIds = processedTexts.map(text => {
            const row = new Array(maxLen).fill(0);
            for (let j = 0; j < text.length; j++) {
                const codePoint = text.codePointAt(j);
                row[j] = (codePoint !== undefined && codePoint < this.indexer.length) ? this.indexer[codePoint] : -1;
            }
            return row;
        });

        const textMask = this.getTextMask(textIdsLengths);
        return { textIds, textMask };
    }

    preprocessText(text: string) {
        return text.normalize('NFKD').trim() + '.'; // Simple normalization
    }

    getTextMask(textIdsLengths: number[]) {
        const maxLen = Math.max(...textIdsLengths);
        return textIdsLengths.map(len => {
            const row = new Array(maxLen).fill(0.0);
            for (let j = 0; j < Math.min(len, maxLen); j++) {
                row[j] = 1.0;
            }
            return [row];
        });
    }
}

interface Models {
    dp?: ort.InferenceSession;
    textEnc?: ort.InferenceSession;
    vecEst?: ort.InferenceSession;
    vocoder?: ort.InferenceSession;
}

interface TTSConfig {
    ae: {
        sample_rate: number;
        base_chunk_size: number;
    };
    ttl: {
        latent_dim: number;
        chunk_compress_factor: number;
    };
}

export class SupertonicService {
    private static instance: SupertonicService;
    private isReady = false;
    private ortMod: Ort | null = null;
    private models: Models = {};
    private textProcessor: UnicodeProcessor | null = null;
    private cfgs: TTSConfig | null = null;
    private currentStyle: Style | null = null;
    private preloadManifest: boolean[] = new Array(8).fill(false);
    private isPreloading = false;
    private lastTokenDurations: number[] | null = null;

    private constructor() { }

    public static getInstance(): SupertonicService {
        if (!SupertonicService.instance) {
            SupertonicService.instance = new SupertonicService();
        }
        return SupertonicService.instance;
    }

    async init() {
        if (this.isReady) return;
        try {
            const ort = await loadOrt();
            this.ortMod = ort;

            console.log("Supertonic: Loading Config...");

            // Helper to handle relative paths correctly in deployment
            const getAssetUrl = (path: string) => {
                const cleanPath = path.startsWith('/') ? path.slice(1) : path;
                return import.meta.env.BASE_URL + cleanPath;
            };

            const cfgRes = await fetch(getAssetUrl('assets/onnx/tts.json'));
            if (!cfgRes.ok) {
                throw new Error(`Failed to load tts.json: ${cfgRes.status} ${cfgRes.statusText}`);
            }
            this.cfgs = await cfgRes.json();

            const idxRes = await fetch(getAssetUrl('assets/onnx/unicode_indexer.json'));
            if (!idxRes.ok) {
                throw new Error(`Failed to load unicode_indexer.json: ${idxRes.status} ${idxRes.statusText}`);
            }
            const indexer = await idxRes.json();
            this.textProcessor = new UnicodeProcessor(indexer);

            console.log("Supertonic: Loading Models with WebGPU...");

            // OPTIMIZATION 2: WebGPU Execution Provider
            // We attempt 'webgpu' first. If the browser doesn't support it,
            // ORT falls back to 'wasm' automatically.
            // annotations are removed because the type is not exported by ort
            const sessionOptions: any = {
                executionProviders: [{ name: 'webgpu' }, { name: 'wasm' }],
                graphOptimizationLevel: 'all'
            };

            // Parallel loading is faster than sequential await
            const [dp, textEnc, vecEst, vocoder] = await Promise.all([
                // @ts-ignore - signature mismatch in current type defs
                ort.InferenceSession.create(getAssetUrl('assets/onnx/duration_predictor.onnx'), sessionOptions),
                // @ts-ignore
                ort.InferenceSession.create(getAssetUrl('assets/onnx/text_encoder.onnx'), sessionOptions),
                // @ts-ignore
                ort.InferenceSession.create(getAssetUrl('assets/onnx/vector_estimator.onnx'), sessionOptions),
                // @ts-ignore
                ort.InferenceSession.create(getAssetUrl('assets/onnx/vocoder.onnx'), sessionOptions)

            ]);

            this.models.dp = dp;
            this.models.textEnc = textEnc;
            this.models.vecEst = vecEst;
            this.models.vocoder = vocoder;

            // Load Default Style
            try {
                await this.loadStyle(getAssetUrl('assets/voice_styles/F1.json'));
                console.log('✓ Loaded default voice style: F1');
            } catch (e) {
                console.warn('Could not load default style F1.json', e);
            }

            this.isReady = true;
            console.log("Supertonic: Ready (WebGPU Enabled)");
        } catch (e) {
            console.error("❌ Supertonic Init Failed:", e);
            this.isReady = false;
        }
    }

    async loadStyle(url: string) {
        const ort = this.ortMod ?? await loadOrt();
        this.ortMod = ort;

        const res = await fetch(url);
        const json: StyleData = await res.json();

        const ttlFlat = new Float32Array(json.style_ttl.data.flat(Infinity) as number[]);
        const dpFlat = new Float32Array(json.style_dp.data.flat(Infinity) as number[]);

        const ttlTensor = new ort.Tensor('float32', ttlFlat, [1, json.style_ttl.dims[1], json.style_ttl.dims[2]]);
        const dpTensor = new ort.Tensor('float32', dpFlat, [1, json.style_dp.dims[1], json.style_dp.dims[2]]);

        this.currentStyle = new Style(ttlTensor, dpTensor);
    }

    isServiceReady(): boolean {
        return this.isReady;
    }

    /**
     * Warms up the ONNX session with a dummy inference to avoid cold-start lag during initial playback.
     */
    async preload(): Promise<void> {
        if (!this.isReady || this.isPreloading) return;
        this.isPreloading = true;
        try {
            if (import.meta.env.DEV) { console.log("Supertonic: Warming ONNX session with dummy inference..."); }
            // Minimal dummy inference to warm GPU kernels for all banks
            await this.generate("a", 1, 1.0);
            this.preloadManifest.fill(true);
            if (import.meta.env.DEV) { console.log("Supertonic: ONNX session warmed."); }
        } catch (e) {
            if (import.meta.env.DEV) { console.warn("Supertonic: Preload dummy inference failed (non-critical):", e); }
        } finally {
            this.isPreloading = false;
        }
    }

    /**
     * Devtool helper: Releases all InferenceSessions and resets service readiness to test cache misses.
     * @example
     * // Dev mode only
     * window.__devtools.purgeTTSCache()
     */
    purgeCache(): void {
        if (import.meta.env.DEV) { console.log("Supertonic: Purging ONNX session cache..."); }
        (Object.keys(this.models) as (keyof Models)[]).forEach((key) => {
            const session = this.models[key];
            if (session && typeof session.release === 'function') {
                try {
                    session.release();
                } catch (e) {
                    console.warn(`Supertonic: Failed to release ${key}:`, e);
                }
            }
        });
        this.models = {};
        this.isReady = false;
        this.preloadManifest.fill(false);
        if (import.meta.env.DEV) { console.log("Supertonic: ONNX cache purged. isReady=false"); }
    }

    /**
     * Returns an array mapping which TTS banks are currently warmed up in the ONNX cache.
     */
    getPreloadManifest(): boolean[] {
        return [...this.preloadManifest];
    }

    async generate(text: string, steps: number = 5, speed: number = 1.0): Promise<Float32Array> {
        if (!this.isReady || !this.currentStyle || !this.textProcessor || !this.cfgs) {
            throw new Error("Supertonic service not ready.");
        }

        if (!this.models.dp || !this.models.textEnc || !this.models.vecEst || !this.models.vocoder) {
            throw new Error("Models not loaded");
        }

        const ort = this.ortMod;
        if (!ort) {
            throw new Error("Supertonic service not ready.");
        }

        // 1. Process Text
        const { textIds, textMask } = this.textProcessor.call([text]);
        const bsz = 1;

        const textIdsTensor = new ort.Tensor('int64', new BigInt64Array(textIds.flat().map(BigInt)), [bsz, textIds[0].length]);
        const textMaskTensor = new ort.Tensor('float32', new Float32Array(textMask.flat(2)), [bsz, 1, textMask[0][0].length]);

        // 2. Duration Predictor
        const dpOut = await this.models.dp.run({
            text_ids: textIdsTensor,
            style_dp: this.currentStyle.dp,
            text_mask: textMaskTensor
        });
        const duration = Array.from(dpOut.duration.data as Float32Array).map(d => d / speed);
        this.lastTokenDurations = duration;

        // OPTIMIZATION 3: Dispose Tensors
        // Running on GPU consumes VRAM. We must explicitly dispose intermediate tensors.
        // However, JS GC usually handles Tensor objects, but in tight loops with WebGPU backends,
        // it's safer to let them go if they hold large GPU buffers.
        // Note: ORT-Web handles most cleanup, but keep an eye on memory if looping heavily.

        // 3. Text Encoder
        const encOut = await this.models.textEnc.run({
            text_ids: textIdsTensor,
            style_ttl: this.currentStyle.ttl,
            text_mask: textMaskTensor
        });
        const textEmb = encOut.text_emb;

        // 4. Latent Sampling
        const sampleRate = this.cfgs.ae.sample_rate;
        const wavLenMax = Math.floor(Math.max(...duration) * sampleRate);
        const chunkSize = this.cfgs.ae.base_chunk_size * this.cfgs.ttl.chunk_compress_factor;
        const latentLen = Math.floor((wavLenMax + chunkSize - 1) / chunkSize);
        const latentDim = this.cfgs.ttl.latent_dim * this.cfgs.ttl.chunk_compress_factor;

        const totalSize = bsz * latentDim * latentLen;
        const noise = new Float32Array(totalSize);
        for (let i = 0; i < totalSize; i++) noise[i] = (Math.random() * 2 - 1);

        let xtTensor: ort.Tensor = new ort.Tensor('float32', noise, [bsz, latentDim, latentLen]);

        const latentMaskVals = new Float32Array(bsz * 1 * latentLen).fill(1.0);
        const latentMaskTensor = new ort.Tensor('float32', latentMaskVals, [bsz, 1, latentLen]);

        // 5. Diffusion Loop
        // This is the heavy part. WebGPU shines here.
        const totalStepTensor = new ort.Tensor('float32', new Float32Array([steps]), [bsz]);

        for (let s = 0; s < steps; s++) {
            const currentStepTensor = new ort.Tensor('float32', new Float32Array([s]), [bsz]);

            const vecOut = await this.models.vecEst.run({
                noisy_latent: xtTensor,
                text_emb: textEmb,
                style_ttl: this.currentStyle.ttl,
                latent_mask: latentMaskTensor,
                text_mask: textMaskTensor,
                current_step: currentStepTensor,
                total_step: totalStepTensor
            });

            // Swap and Cleanup
            // If we are strictly checking memory, we might want to verify if dispose() is needed
            // depending on exact ORT version, but JS GC is usually enough for object references.
            xtTensor = vecOut.denoised_latent as ort.Tensor;
        }

        // 6. Vocoder
        const vocOut = await this.models.vocoder.run({ latent: xtTensor });

        // Return raw data
        return vocOut.wav_tts.data as Float32Array;
    }

    getLastTokenDurations(): number[] | null {
        return this.lastTokenDurations ? [...this.lastTokenDurations] : null;
    }

    getOutputSampleRate(): number {
        return this.cfgs?.ae.sample_rate ?? 44100;
    }

    getStyle(): Style | null {
        return this.currentStyle;
    }

    updateStyleFromRaw(ttlData: Float32Array, dpData: Float32Array, ttlDims: number[], dpDims: number[]) {
        if (!this.isReady || !this.ortMod) return;
        const ort = this.ortMod;

        const ttlTensor = new ort.Tensor('float32', ttlData, ttlDims);
        const dpTensor = new ort.Tensor('float32', dpData, dpDims);

        this.currentStyle = new Style(ttlTensor, dpTensor);
        console.log("Supertonic: Style Updated from Mixer");
    }
}

import { Style } from './Supertonic';
import { WebGpuBackend } from './WebGpuBackend';

export class VoiceDesigner {
    private currentTtl: Float32Array | null = null;
    private currentDp: Float32Array | null = null;
    private ttlDims = [1, 50, 256];
    private dpDims = [1, 8, 16];
    private originalTtl: Float32Array | null = null;

    private canvas: HTMLCanvasElement | null = null;
    private ctx: CanvasRenderingContext2D | null = null;
    private gpu: WebGpuBackend;

    constructor() {
        this.gpu = new WebGpuBackend();
        this.gpu.init(); // Fire and forget
    }

    setCanvas(canvas: HTMLCanvasElement) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
    }

    loadFromStyle(style: Style) {
        this.currentTtl = new Float32Array(style.ttl.data as Float32Array);
        this.currentDp = new Float32Array(style.dp.data as Float32Array);
        this.originalTtl = new Float32Array(this.currentTtl);
        if (this.canvas) this.renderHeatmap();
    }

    getRawData() {
        return {
            ttl: this.currentTtl,
            dp: this.currentDp,
            ttlDims: this.ttlDims,
            dpDims: this.dpDims
        };
    }

    reset() {
        if (this.originalTtl) {
            this.currentTtl = new Float32Array(this.originalTtl);
            this.renderHeatmap();
        }
    }

    renderHeatmap() {
        if (!this.canvas || !this.ctx || !this.currentTtl) return;

        const rows = this.ttlDims[1];
        const cols = this.ttlDims[2];
        const data = this.currentTtl;

        this.canvas.width = cols;
        this.canvas.height = rows;

        const imageData = this.ctx.createImageData(cols, rows);
        const buf = imageData.data;

        let min = Infinity, max = -Infinity;
        for (let i = 0; i < data.length; i++) {
            if (data[i] < min) min = data[i];
            if (data[i] > max) max = data[i];
        }
        const range = max - min || 1;

        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                const idx = r * cols + c;
                const val = (data[idx] - min) / range;

                let red = 0, green = 0, blue = 0;
                if (val < 0.5) {
                    const t = val * 2;
                    green = Math.floor(128 * t);
                    blue = Math.floor(128 + 127 * t);
                } else {
                    const t = (val - 0.5) * 2;
                    red = Math.floor(255 * t);
                    green = Math.floor(128 + 127 * t);
                    blue = Math.floor(255 * (1 - t) * 0.2);
                }

                const pixelIdx = (r * cols + c) * 4;
                buf[pixelIdx] = red;
                buf[pixelIdx + 1] = green;
                buf[pixelIdx + 2] = blue;
                buf[pixelIdx + 3] = 255;
            }
        }
        this.ctx.putImageData(imageData, 0, 0);
    }

    // --- Helper for GPU Execution ---
    async _runGpuOp(opName: string, params: Record<string, number> = {}) {
        if (this.gpu.ready && this.currentTtl) {
            console.time(`GPU ${opName}`);
            const result = await this.gpu.runOp(opName, this.currentTtl, this.ttlDims, params);
            if (result) {
                this.currentTtl = result;
            }
            console.timeEnd(`GPU ${opName}`);
        } else {
            console.warn(`WebGPU not ready, running ${opName} on CPU fallback.`);
            // Fallback map
            const map: Record<string, (params?: Record<string, number>) => void> = {
                'sharpen': () => this._cpu_sharpen(params),
                'quantize': () => this._cpu_quantize(params),
                'echo': () => this._cpu_echo(),
                'tremolo': () => this._cpu_tremolo(),
                'jitter': () => this._cpu_jitter(),
                'multiply': () => this._cpu_multiply(params),
                'add': () => this._cpu_add(params)
            };
            if (map[opName]) map[opName]();
        }
        this.renderHeatmap();
    }

    // Run a sequence of GPU ops as a single GPU-resident chain (one readback).
    // Falls back to applying each op via the per-op CPU path if WebGPU is down.
    async _runGpuChain(ops: { name: string; params?: Record<string, number> }[]) {
        if (ops.length === 0) return;
        if (this.gpu.ready && this.currentTtl) {
            console.time(`GPU chain [${ops.map(o => o.name).join('>')}]`);
            const result = await this.gpu.runChain(
                ops.map(o => o.name),
                this.currentTtl,
                this.ttlDims,
                ops.map(o => o.params ?? {}),
            );
            if (result) this.currentTtl = result;
            console.timeEnd(`GPU chain [${ops.map(o => o.name).join('>')}]`);
            if (result) {
                this.renderHeatmap();
                return;
            }
            // result === null → fall through to per-op CPU fallback below.
        }
        for (const op of ops) {
            await this._runGpuOp(op.name, op.params ?? {});
        }
    }

    // --- Operations ---

    async mirrorX() {
        if (!this.currentTtl) return;
        const rows = this.ttlDims[1];
        const cols = this.ttlDims[2];
        const newData = new Float32Array(this.currentTtl.length);
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                newData[r * cols + c] = this.currentTtl[r * cols + (cols - 1 - c)];
            }
        }
        this.currentTtl = newData;
        this.renderHeatmap();
    }

    async mirrorY() {
        if (!this.currentTtl) return;
        const rows = this.ttlDims[1];
        const cols = this.ttlDims[2];
        const newData = new Float32Array(this.currentTtl.length);
        for (let r = 0; r < rows; r++) {
            const startSrc = (rows - 1 - r) * cols;
            const startDst = r * cols;
            for (let c = 0; c < cols; c++) {
                newData[startDst + c] = this.currentTtl[startSrc + c];
            }
        }
        this.currentTtl = newData;
        this.renderHeatmap();
    }

    async invertSign() { await this.multiplyScalar(-1.0); }
    async addScalar(val: number) { await this._runGpuOp('add', { factor: val }); }
    async multiplyScalar(val: number) { await this._runGpuOp('multiply', { factor: val }); }
    async dspSharpen() { await this._runGpuOp('sharpen', { factor: 1.5 }); }
    async dspQuantize() { await this._runGpuOp('quantize', { factor: 5.0 }); }
    async dspEcho() { await this._runGpuOp('echo'); }
    async dspTremolo() { await this._runGpuOp('tremolo'); }
    async dspJitter() { await this._runGpuOp('jitter'); }

    // Composite "mangle" effect — three ops chained GPU-resident (no intermediate
    // readback between sharpen → quantize → tremolo).
    async dspMangle() {
        await this._runGpuChain([
            { name: 'sharpen', params: { factor: 1.5 } },
            { name: 'quantize', params: { factor: 5.0 } },
            { name: 'tremolo' },
        ]);
    }

    async randomShift() {
        if (!this.currentTtl) return;
        const rows = this.ttlDims[1];
        const cols = this.ttlDims[2];
        const shiftR = Math.floor(Math.random() * rows);
        const shiftC = Math.floor(Math.random() * cols);
        const newData = new Float32Array(this.currentTtl.length);

        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                const srcR = (r - shiftR + rows) % rows;
                const srcC = (c - shiftC + cols) % cols;
                newData[r * cols + c] = this.currentTtl[srcR * cols + srcC];
            }
        }
        this.currentTtl = newData;
        this.renderHeatmap();
    }

    // --- CPU Fallbacks ---
    _cpu_add(params: Record<string, number>) { if (this.currentTtl) for (let i = 0; i < this.currentTtl.length; i++) this.currentTtl[i] += params.factor; }
    _cpu_multiply(params: Record<string, number>) { if (this.currentTtl) for (let i = 0; i < this.currentTtl.length; i++) this.currentTtl[i] *= params.factor; }

    _cpu_sharpen(params: Record<string, number>) {
        if (!this.currentTtl) return;
        const rows = this.ttlDims[1];
        const cols = this.ttlDims[2];
        const factor = params.factor || 1.5;
        const newData = new Float32Array(this.currentTtl);
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                const prev = (c > 0) ? this.currentTtl[r * cols + c - 1] : this.currentTtl[r * cols + c];
                const next = (c < cols - 1) ? this.currentTtl[r * cols + c + 1] : this.currentTtl[r * cols + c];
                const grad = (next - prev) / 2.0;
                newData[r * cols + c] += grad * factor;
            }
        }
        this.currentTtl = newData;
    }

    _cpu_quantize(params: Record<string, number>) {
        if (!this.currentTtl) return;
        const factor = params.factor || 5.0;
        for (let i = 0; i < this.currentTtl.length; i++) {
            this.currentTtl[i] = Math.round(this.currentTtl[i] * factor) / factor;
        }
    }

    _cpu_echo() {
        if (!this.currentTtl) return;
        const rows = this.ttlDims[1];
        const cols = this.ttlDims[2];
        const newData = new Float32Array(this.currentTtl);
        const shift = 2;
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                let srcC = (c - shift);
                if (srcC < 0) srcC += cols;
                newData[r * cols + c] += this.currentTtl[r * cols + srcC] * 0.5;
            }
        }
        this.currentTtl = newData;
    }

    _cpu_tremolo() {
        if (!this.currentTtl) return;
        const rows = this.ttlDims[1];
        const cols = this.ttlDims[2];
        const envelope = new Float32Array(cols);
        for (let c = 0; c < cols; c++) {
            const t = (c / (cols - 1)) * 2 * Math.PI;
            envelope[c] = 1.0 + 0.5 * Math.sin(t);
        }
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                this.currentTtl[r * cols + c] *= envelope[c];
            }
        }
    }

    _cpu_jitter() {
        if (!this.currentTtl) return;
        for (let i = 0; i < this.currentTtl.length; i++) {
            this.currentTtl[i] *= (0.8 + Math.random() * 0.4);
        }
    }
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { WebGpuBackend } from './WebGpuBackend';
import { resetWebGpuProbeForTests } from '../engines/backends/webgpuProbe';

// Minimal WebGPU mock that records how buffers are wired through a chain.
function installGpuMock() {
  const createdBuffers: any[] = [];
  const computePasses: any[] = [];
  const bindGroups: any[] = [];

  const makeBuffer = () => {
    const buf = {
      destroy: vi.fn(),
      mapAsync: vi.fn().mockResolvedValue(undefined),
      getMappedRange: vi.fn(() => new Float32Array(4096).buffer),
      unmap: vi.fn(),
    };
    createdBuffers.push(buf);
    return buf;
  };

  const mockQueue = { writeBuffer: vi.fn(), submit: vi.fn() };

  const mockDevice: any = {
    createShaderModule: vi.fn().mockReturnValue({}),
    createComputePipeline: vi.fn(() => ({ getBindGroupLayout: vi.fn().mockReturnValue({}) })),
    createBuffer: vi.fn(makeBuffer),
    createBindGroup: vi.fn((d: any) => {
      bindGroups.push(d);
      return {};
    }),
    createCommandEncoder: vi.fn(() => ({
      beginComputePass: vi.fn(() => {
        const pass = {
          setPipeline: vi.fn(),
          setBindGroup: vi.fn(),
          dispatchWorkgroups: vi.fn(),
          end: vi.fn(),
        };
        computePasses.push(pass);
        return pass;
      }),
      copyBufferToBuffer: vi.fn(),
      finish: vi.fn(),
    })),
    queue: mockQueue,
  };

  // @ts-ignore
  global.navigator.gpu = {
    requestAdapter: vi.fn().mockResolvedValue({ requestDevice: vi.fn().mockResolvedValue(mockDevice) }),
  };
  // @ts-ignore
  global.GPUBufferUsage = { STORAGE: 1, COPY_SRC: 2, MAP_READ: 4, COPY_DST: 8, UNIFORM: 16 };
  // @ts-ignore
  global.GPUMapMode = { READ: 1 };

  return { mockDevice, mockQueue, createdBuffers, computePasses, bindGroups };
}

describe('WebGpuBackend.runChain', () => {
  let backend: WebGpuBackend;
  let mocks: ReturnType<typeof installGpuMock>;

  beforeEach(async () => {
    vi.clearAllMocks();
    resetWebGpuProbeForTests();
    mocks = installGpuMock();
    backend = new WebGpuBackend();
    await backend.init();
  });

  it('returns null before init / when unavailable', async () => {
    const fresh = new WebGpuBackend();
    const r = await fresh.runChain(['multiply'], new Float32Array([1, 2]), [1, 1, 2]);
    expect(r).toBeNull();
  });

  it('returns a copy of the input when ops is empty', async () => {
    const data = new Float32Array([1, 2, 3, 4]);
    const r = await backend.runChain([], data, [1, 2, 2]);
    expect(r).toBeInstanceOf(Float32Array);
    expect(Array.from(r!)).toEqual([1, 2, 3, 4]);
    expect(r).not.toBe(data); // copy, not the same reference
  });

  it('dispatches one compute pass per op and reads back exactly once', async () => {
    const data = new Float32Array(16);
    const r = await backend.runChain(['sharpen', 'quantize', 'tremolo'], data, [1, 4, 4]);

    expect(r).toBeInstanceOf(Float32Array);
    expect(mocks.computePasses).toHaveLength(3); // one pass per op
    // submit once, mapAsync once → single readback
    expect(mocks.mockQueue.submit).toHaveBeenCalledTimes(1);
    const mapped = mocks.createdBuffers.filter((b) => b.mapAsync.mock.calls.length > 0);
    expect(mapped).toHaveLength(1);
  });

  it('ping-pongs: the input of op N+1 is the output of op N', async () => {
    const data = new Float32Array(16);
    await backend.runChain(['multiply', 'add', 'multiply'], data, [1, 4, 4]);

    // binding 1 (output) of pass i must equal binding 0 (input) of pass i+1.
    const bg = mocks.bindGroups;
    expect(bg.length).toBeGreaterThanOrEqual(3);
    for (let i = 0; i < 2; i++) {
      const out = bg[i].entries.find((e: any) => e.binding === 1).resource.buffer;
      const nextIn = bg[i + 1].entries.find((e: any) => e.binding === 0).resource.buffer;
      expect(nextIn).toBe(out);
    }
  });

  it('returns null on an unknown op without leaving pool buffers mapped', async () => {
    const r = await backend.runChain(['multiply', 'bogus'], new Float32Array(16), [1, 4, 4]);
    expect(r).toBeNull();
  });

  it('reuses pooled buffers across calls (no unbounded allocation)', async () => {
    const data = new Float32Array(16);
    await backend.runChain(['multiply'], data, [1, 4, 4]);
    const afterFirst = mocks.mockDevice.createBuffer.mock.calls.length;
    await backend.runChain(['multiply'], data, [1, 4, 4]);
    const afterSecond = mocks.mockDevice.createBuffer.mock.calls.length;
    // Second call should only allocate the per-op uniform buffer; the 2 storage
    // buffers + 1 readback buffer come back from the pool.
    expect(afterSecond - afterFirst).toBeLessThan(afterFirst);
  });
});

/// <reference types="@webgpu/types" />
import { engineTelemetry, logEngineFallback } from '../utils/engineTelemetry';
import { probeWebGPU } from '../engines/backends/webgpuProbe';

export class WebGpuBackend {
    device: GPUDevice | null = null;
    adapter: GPUAdapter | null = null;
    pipelines: Record<string, GPUComputePipeline> = {};
    ready: boolean = false;

    // Persistent 16-byte uniform buffer reused across all runOp() calls
    private uniformBuffer: GPUBuffer | null = null;

    // ── Pooled, size-bucketed buffer allocator (mirrors WebGpuOscillator.ts) ──
    // Ping-pong STORAGE buffers (STORAGE | COPY_SRC | COPY_DST) keyed by bucket.
    private storagePool: Map<number, GPUBuffer[]> = new Map();
    // Readback buffers (MAP_READ | COPY_DST) keyed by bucket.
    private readPool: Map<number, GPUBuffer[]> = new Map();
    private readonly MAX_POOL_SIZE_PER_BUCKET = 4;
    private readonly SIZE_BUCKET_BYTES = 4096; // Quantize to 4KB buckets
    private readonly MAX_BUFFER_SIZE = 64 * 1024 * 1024; // 64MB guard against OOM

    async init(): Promise<boolean> {
        const probe = await probeWebGPU();
        if (!probe.ok || !probe.device || !probe.adapterHandle) {
            console.warn("WebGPU not supported on this browser.");
            logEngineFallback(
                'webgpu-compute',
                'webgpu',
                probe.reason ?? 'navigator.gpu unavailable (browser lacks WebGPU)',
            );
            return false;
        }

        try {
            this.adapter = probe.adapterHandle;
            this.device = probe.device;
            this.initShaders();
            // Allocate persistent uniform buffer (16 bytes: rows, cols, factor, seed)
            this.uniformBuffer = this.device.createBuffer({
                size: 16,
                usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
            });
            this.ready = true;
            console.log("WebGPU Backend Initialized 🚀");
            try { engineTelemetry.registerResolution('webgpu-compute', 'webgpu', 'device-ready'); } catch (_) {}
            return true;
        } catch (e) {
            console.error("WebGPU Init Failed:", e);
            logEngineFallback('webgpu-compute', 'webgpu', 'GPUDevice or compute pipeline creation failed', e);
            return false;
        }
    }

    initShaders() {
        if (!this.device) return;

        const shaderCode = `
        struct Params {
            rows: f32,
            cols: f32,
            factor: f32,
            seed: f32,
        };

        @group(0) @binding(0) var<storage, read> inputBuf : array<f32>;
        @group(0) @binding(1) var<storage, read_write> outputBuf : array<f32>;
        @group(0) @binding(2) var<uniform> params : Params;

        // Simple hash for randomness
        fn hash(u: u32) -> f32 {
            var x = u + u32(params.seed);
            x = ((x >> 16u) ^ x) * 0x45d9f3bu;
            x = ((x >> 16u) ^ x) * 0x45d9f3bu;
            x = (x >> 16u) ^ x;
            return f32(x) / 4294967295.0;
        }

        @compute @workgroup_size(64)
        fn sharpen(@builtin(global_invocation_id) global_id : vec3<u32>) {
            let idx = global_id.x;
            let total = u32(params.rows * params.cols);
            if (idx >= total) { return; }

            let cols = u32(params.cols);
            let r = idx / cols;
            let c = idx % cols;

            // Gradient across features (columns)
            let c_prev = select(c - 1u, 0u, c == 0u);
            let c_next = select(c + 1u, cols - 1u, c == cols - 1u);

            let val_prev = inputBuf[r * cols + c_prev];
            let val_next = inputBuf[r * cols + c_next];

            let grad = (val_next - val_prev) / 2.0;

            outputBuf[idx] = inputBuf[idx] + (grad * params.factor);
        }

        @compute @workgroup_size(64)
        fn quantize(@builtin(global_invocation_id) global_id : vec3<u32>) {
            let idx = global_id.x;
            if (idx >= u32(params.rows * params.cols)) { return; }

            let val = inputBuf[idx];
            let f = params.factor;
            outputBuf[idx] = round(val * f) / f;
        }

        @compute @workgroup_size(64)
        fn echo(@builtin(global_invocation_id) global_id : vec3<u32>) {
            let idx = global_id.x;
            if (idx >= u32(params.rows * params.cols)) { return; }

            let cols = u32(params.cols);
            let r = idx / cols;
            let c = idx % cols;

            // Roll right by 2
            let shift = 2u;
            var srcC = c;
            if (c >= shift) { srcC = c - shift; } 
            else { srcC = c + cols - shift; }

            let echoVal = inputBuf[r * cols + srcC] * 0.5;
            outputBuf[idx] = inputBuf[idx] + echoVal;
        }

        @compute @workgroup_size(64)
        fn tremolo(@builtin(global_invocation_id) global_id : vec3<u32>) {
            let idx = global_id.x;
            if (idx >= u32(params.rows * params.cols)) { return; }

            let cols = u32(params.cols);
            let c = idx % cols;
            let pi = 3.14159265;

            let t = (f32(c) / f32(cols - 1u)) * 2.0 * pi;
            let envelope = 1.0 + 0.5 * sin(t);

            outputBuf[idx] = inputBuf[idx] * envelope;
        }

        @compute @workgroup_size(64)
        fn jitter(@builtin(global_invocation_id) global_id : vec3<u32>) {
            let idx = global_id.x;
            if (idx >= u32(params.rows * params.cols)) { return; }

            let rnd = hash(idx); 
            let factor = 0.8 + (rnd * 0.4);

            outputBuf[idx] = inputBuf[idx] * factor;
        }

        @compute @workgroup_size(64)
        fn multiply(@builtin(global_invocation_id) global_id : vec3<u32>) {
            let idx = global_id.x;
            if (idx >= u32(params.rows * params.cols)) { return; }
            outputBuf[idx] = inputBuf[idx] * params.factor;
        }

        @compute @workgroup_size(64)
        fn add(@builtin(global_invocation_id) global_id : vec3<u32>) {
            let idx = global_id.x;
            if (idx >= u32(params.rows * params.cols)) { return; }
            outputBuf[idx] = inputBuf[idx] + params.factor;
        }
        `;

        const module = this.device.createShaderModule({ code: shaderCode });

        const ops = ['sharpen', 'quantize', 'echo', 'tremolo', 'jitter', 'multiply', 'add'];

        ops.forEach(op => {
            this.pipelines[op] = this.device!.createComputePipeline({
                layout: 'auto',
                compute: { module: module, entryPoint: op }
            });
        });
    }

    async runOp(opName: string, data: Float32Array, dims: number[], params: { factor?: number } = {}): Promise<Float32Array | null> {
        if (!this.ready || !this.device || !this.uniformBuffer) return null;

        const rows = dims[1];
        const cols = dims[2];
        const size = rows * cols;
        const bufferSize = size * 4;

        // 1. Buffers
        const inputBuffer = this.device.createBuffer({
            size: bufferSize,
            usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
            mappedAtCreation: true
        });
        new Float32Array(inputBuffer.getMappedRange()).set(data);
        inputBuffer.unmap();

        const outputBuffer = this.device.createBuffer({
            size: bufferSize,
            usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC
        });

        // 2. Uniforms — reuse persistent buffer, just write new values
        const factor = params.factor !== undefined ? params.factor : 1.0;
        const seed = Math.random() * 10000;
        const uniformData = new Float32Array([rows, cols, factor, seed]);
        this.device.queue.writeBuffer(this.uniformBuffer, 0, uniformData);
        const uniformBuffer = this.uniformBuffer;

        // 3. Bind Group
        const pipeline = this.pipelines[opName];
        const bindGroup = this.device.createBindGroup({
            layout: pipeline.getBindGroupLayout(0),
            entries: [
                { binding: 0, resource: { buffer: inputBuffer } },
                { binding: 1, resource: { buffer: outputBuffer } },
                { binding: 2, resource: { buffer: uniformBuffer } }
            ]
        });

        // 4. Dispatch
        const commandEncoder = this.device.createCommandEncoder();
        const passEncoder = commandEncoder.beginComputePass();
        passEncoder.setPipeline(pipeline);
        passEncoder.setBindGroup(0, bindGroup);
        passEncoder.dispatchWorkgroups(Math.ceil(size / 64));
        passEncoder.end();

        // 5. Readback
        const readbackBuffer = this.device.createBuffer({
            size: bufferSize,
            usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ
        });
        commandEncoder.copyBufferToBuffer(outputBuffer, 0, readbackBuffer, 0, bufferSize);
        this.device.queue.submit([commandEncoder.finish()]);

        await readbackBuffer.mapAsync(GPUMapMode.READ);
        const result = new Float32Array(readbackBuffer.getMappedRange());
        const finalData = new Float32Array(result);
        readbackBuffer.unmap();

        // Cleanup — uniformBuffer is persistent and must NOT be destroyed here
        inputBuffer.destroy();
        outputBuffer.destroy();
        readbackBuffer.destroy();

        return finalData;
    }

    // ── Pooled buffer allocator ───────────────────────────────────────────────
    // Quantize a byte size up to the nearest bucket so differently-sized chains
    // can still share buffers.
    private getSizeBucket(size: number): number {
        return Math.ceil(size / this.SIZE_BUCKET_BYTES) * this.SIZE_BUCKET_BYTES;
    }

    private acquire(
        pool: Map<number, GPUBuffer[]>,
        bucket: number,
        usage: GPUBufferUsageFlags,
    ): GPUBuffer | null {
        if (!this.device) return null;
        const free = pool.get(bucket);
        if (free && free.length > 0) return free.pop()!;
        try {
            return this.device.createBuffer({ size: bucket, usage });
        } catch (e) {
            logEngineFallback('webgpu-compute', 'webgpu', 'GPUBuffer allocation failed', e);
            return null;
        }
    }

    private release(pool: Map<number, GPUBuffer[]>, bucket: number, buffer: GPUBuffer) {
        let free = pool.get(bucket);
        if (!free) {
            free = [];
            pool.set(bucket, free);
        }
        if (free.length < this.MAX_POOL_SIZE_PER_BUCKET) {
            free.push(buffer);
        } else {
            buffer.destroy();
        }
    }

    /**
     * GPU-resident op chaining. Runs `ops` in sequence, ping-ponging between two
     * persistent STORAGE buffers so intermediate results never leave the GPU —
     * only the final result is read back (one mapAsync, one submit).
     *
     * Returns null when WebGPU is unavailable so callers fall back to CPU,
     * matching runOp()'s contract. Offline/precompute only — never await this
     * on the audio worklet thread.
     */
    async runChain(
        ops: string[],
        data: Float32Array,
        dims: number[],
        params: { factor?: number }[] = [],
    ): Promise<Float32Array | null> {
        if (!this.ready || !this.device) return null;
        if (ops.length === 0) return new Float32Array(data); // nothing to do

        const rows = dims[1];
        const cols = dims[2];
        const size = rows * cols;
        const bufferSize = size * 4;

        if (bufferSize > this.MAX_BUFFER_SIZE) {
            logEngineFallback(
                'webgpu-compute',
                'webgpu',
                `chain buffer ${bufferSize}B exceeds max ${this.MAX_BUFFER_SIZE}B`,
            );
            return null;
        }

        const t0 = (typeof performance !== 'undefined' ? performance.now() : Date.now());
        const bucket = this.getSizeBucket(bufferSize);
        const storageUsage = GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST;

        // Two persistent ping-pong buffers + one readback buffer from the pool.
        const bufA = this.acquire(this.storagePool, bucket, storageUsage);
        const bufB = this.acquire(this.storagePool, bucket, storageUsage);
        const readback = this.acquire(this.readPool, bucket, GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST);
        if (!bufA || !bufB || !readback) {
            if (bufA) this.release(this.storagePool, bucket, bufA);
            if (bufB) this.release(this.storagePool, bucket, bufB);
            if (readback) this.release(this.readPool, bucket, readback);
            return null;
        }

        // Seed the chain: upload input into bufA.
        this.device.queue.writeBuffer(bufA, 0, data.buffer, data.byteOffset, data.byteLength);

        // One uniform buffer per op — all passes coexist in a single submit, so
        // they cannot share one mutable uniform buffer.
        const uniformBuffers: GPUBuffer[] = [];
        const commandEncoder = this.device.createCommandEncoder();

        let src = bufA;
        let dst = bufB;
        try {
            for (let i = 0; i < ops.length; i++) {
                const pipeline = this.pipelines[ops[i]];
                if (!pipeline) {
                    throw new Error(`unknown op "${ops[i]}"`);
                }

                const factor = params[i]?.factor !== undefined ? params[i]!.factor! : 1.0;
                const seed = Math.random() * 10000;
                const uniformBuffer = this.device.createBuffer({
                    size: 16,
                    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
                });
                this.device.queue.writeBuffer(uniformBuffer, 0, new Float32Array([rows, cols, factor, seed]));
                uniformBuffers.push(uniformBuffer);

                const bindGroup = this.device.createBindGroup({
                    layout: pipeline.getBindGroupLayout(0),
                    entries: [
                        { binding: 0, resource: { buffer: src } },
                        { binding: 1, resource: { buffer: dst } },
                        { binding: 2, resource: { buffer: uniformBuffer } },
                    ],
                });

                const pass = commandEncoder.beginComputePass();
                pass.setPipeline(pipeline);
                pass.setBindGroup(0, bindGroup);
                pass.dispatchWorkgroups(Math.ceil(size / 64));
                pass.end();

                // Ping-pong: this op's output becomes the next op's input.
                const tmp = src;
                src = dst;
                dst = tmp;
            }

            // After the loop the freshest result lives in `src`.
            commandEncoder.copyBufferToBuffer(src, 0, readback, 0, bufferSize);
            this.device.queue.submit([commandEncoder.finish()]);

            await readback.mapAsync(GPUMapMode.READ);
            const mapped = new Float32Array(readback.getMappedRange(), 0, size);
            const finalData = new Float32Array(mapped); // copy out before unmap
            readback.unmap();

            try { engineTelemetry.recordLatency('webgpu-compute', (typeof performance !== 'undefined' ? performance.now() : Date.now()) - t0); } catch (_) {}

            // Return all pooled buffers for reuse.
            this.release(this.storagePool, bucket, bufA);
            this.release(this.storagePool, bucket, bufB);
            this.release(this.readPool, bucket, readback);
            uniformBuffers.forEach(b => b.destroy());

            return finalData;
        } catch (e) {
            logEngineFallback('webgpu-compute', 'webgpu', 'runChain dispatch/readback failed', e);
            // Don't return buffers to the pool on error — destroy them.
            bufA.destroy();
            bufB.destroy();
            readback.destroy();
            uniformBuffers.forEach(b => b.destroy());
            return null;
        }
    }

    // Release all pooled buffers (call on teardown).
    destroy() {
        for (const free of this.storagePool.values()) free.forEach(b => b.destroy());
        for (const free of this.readPool.values()) free.forEach(b => b.destroy());
        this.storagePool.clear();
        this.readPool.clear();
    }
}

import { describe, it, expect, beforeEach } from 'vitest';
import {
    ProjectStore,
    contentHash,
    AUTOSAVE_PROJECT_ID,
    type ProjectFileBackend,
} from '@/services/ProjectStore';
import { AUTOSAVE_KEY } from '@/utils/projectPersistence';
import type { SavedSongData } from '@/types';

// ── in-memory backend, mirrors ProjectStore's own MemoryBackend fallback ──────

function makeMemoryBackend(): ProjectFileBackend {
    const files = new Map<string, Uint8Array>();
    return {
        kind: 'memory',
        writeFile(path, data) {
            files.set(path, typeof data === 'string' ? new TextEncoder().encode(data) : data);
            return Promise.resolve();
        },
        readFile(path) {
            return Promise.resolve(files.get(path) ?? null);
        },
        readText(path) {
            const bytes = files.get(path);
            return Promise.resolve(bytes ? new TextDecoder().decode(bytes) : null);
        },
        exists(path) {
            return Promise.resolve(files.has(path));
        },
        deleteFile(path) {
            files.delete(path);
            return Promise.resolve();
        },
        listDirs(dirPath) {
            const prefix = `${dirPath}/`;
            const names = new Set<string>();
            for (const key of files.keys()) {
                if (!key.startsWith(prefix)) continue;
                const seg = key.slice(prefix.length).split('/')[0];
                if (seg) names.add(seg);
            }
            return Promise.resolve([...names]);
        },
        deleteDir(dirPath) {
            const prefix = `${dirPath}/`;
            for (const key of [...files.keys()]) {
                if (key === dirPath || key.startsWith(prefix)) files.delete(key);
            }
            return Promise.resolve();
        },
    };
}

const EMPTY_SEQUENCE = { steps: Array(32).fill(null) };
function makeSong(overrides: Partial<SavedSongData> = {}): SavedSongData {
    return {
        version: 1,
        pattern: {
            partA: EMPTY_SEQUENCE,
            partB: EMPTY_SEQUENCE,
            bass2: EMPTY_SEQUENCE,
            kick: EMPTY_SEQUENCE,
            snare: EMPTY_SEQUENCE,
            closedHat: EMPTY_SEQUENCE,
            openHat: EMPTY_SEQUENCE,
            sampler: Array(8).fill(EMPTY_SEQUENCE),
        },
        params: {
            synthA: { waveform: 'sawtooth', pitch: 0, filterCutoff: 2000, filterResonance: 1, attack: 0.01, decay: 0.3, sustain: 0.7, release: 0.3, length: 1, volume: 0.8, delayTime: 0, delayFeedback: 0, delayMix: 0 } as any,
            synthB: { waveform: 'square', pitch: 0, filterCutoff: 2000, filterResonance: 1, attack: 0.01, decay: 0.3, sustain: 0.7, release: 0.3, length: 1, volume: 0.8, delayTime: 0, delayFeedback: 0, delayMix: 0 } as any,
            kick: { pitch: 0, decay: 0.5, tone: 0.5, volume: 0.8 } as any,
            snare: { decay: 0.3, tone: 0.5, noise: 0.5, volume: 0.8 } as any,
            closedHat: { pitch: 0, decay: 0.1, volume: 0.8 } as any,
            openHat: { pitch: 0, decay: 0.4, volume: 0.8 } as any,
            sampler: Array(8).fill({ sampleName: '', playbackSpeed: 1, volume: 1, filterCutoff: 20000, filterResonance: 0, drive: 0, delaySend: 0 }) as any,
        },
        trackStorage: {},
        activeTrackSlots: { partA: 0, partB: 0, bass2: 0, kick: 0, snare: 0, closedHat: 0, openHat: 0, sampler: 0 },
        songStructure: [],
        tempo: 120,
        ...overrides,
    };
}

function wavDataUrl(bytes: number[]): string {
    const raw = new Uint8Array(bytes);
    let bin = '';
    for (const b of raw) bin += String.fromCharCode(b);
    return `data:audio/wav;base64,${btoa(bin)}`;
}

describe('contentHash', () => {
    it('is deterministic for identical bytes', () => {
        const a = new Uint8Array([1, 2, 3, 4, 5]);
        const b = new Uint8Array([1, 2, 3, 4, 5]);
        expect(contentHash(a)).toBe(contentHash(b));
    });

    it('differs for different bytes', () => {
        expect(contentHash(new Uint8Array([1, 2, 3]))).not.toBe(contentHash(new Uint8Array([3, 2, 1])));
    });
});

describe('ProjectStore', () => {
    let backend: ProjectFileBackend;
    let store: ProjectStore;

    beforeEach(() => {
        backend = makeMemoryBackend();
        store = new ProjectStore(backend);
        localStorage.clear();
    });

    it('round-trips a project without samples', async () => {
        const song = makeSong({ tempo: 140 });
        const result = await store.saveProject('p1', song);
        expect(result.ok).toBe(true);

        const loaded = await store.loadProject('p1');
        expect(loaded).not.toBeNull();
        expect(loaded!.tempo).toBe(140);
        expect(loaded!.embeddedSamples).toBeUndefined();
    });

    it('round-trips embedded samples byte-for-byte via content-addressed storage', async () => {
        const sampleBytes = [82, 73, 70, 70, 0, 1, 2, 3, 255, 254];
        const song = makeSong({
            embeddedSamples: { 0: wavDataUrl(sampleBytes) },
        });
        await store.saveProject('p2', song);

        const loaded = await store.loadProject('p2');
        expect(loaded!.embeddedSamples).toBeDefined();
        const restoredUrl = loaded!.embeddedSamples![0];
        expect(restoredUrl.startsWith('data:audio/wav;base64,')).toBe(true);

        // decode both to compare raw bytes
        const decode = (url: string) => {
            const b64 = url.split(',')[1];
            const bin = atob(b64);
            return Uint8Array.from(bin, (c) => c.charCodeAt(0));
        };
        expect(Array.from(decode(restoredUrl))).toEqual(sampleBytes);
    });

    it('does not lose samples over 512KB — unlike the legacy localStorage autosave', async () => {
        const bigBytes = Array.from({ length: 600 * 1024 }, (_, i) => i % 256);
        const song = makeSong({ embeddedSamples: { 0: wavDataUrl(bigBytes) } });
        const result = await store.saveProject('big', song);
        expect(result.ok).toBe(true);
        const loaded = await store.loadProject('big');
        expect(loaded!.embeddedSamples![0]).toBeDefined();
    });

    it('dedupes identical sample content across saves (content-addressed)', async () => {
        const sampleBytes = [1, 2, 3, 4, 5, 6, 7, 8];
        const song1 = makeSong({ embeddedSamples: { 0: wavDataUrl(sampleBytes) } });
        await store.saveProject('dedupe', song1);
        const written1 = await backend.listDirs('hyphon-projects/dedupe/samples');
        expect(written1.length).toBe(1);

        // Save again with the same sample content — no new file should appear.
        await store.saveProject('dedupe', song1);
        const written2 = await backend.listDirs('hyphon-projects/dedupe/samples');
        expect(written2.length).toBe(1);
        expect(written2).toEqual(written1);
    });

    it('hasProject / deleteProject', async () => {
        await store.saveProject('del-me', makeSong());
        expect(await store.hasProject('del-me')).toBe(true);
        await store.deleteProject('del-me');
        expect(await store.hasProject('del-me')).toBe(false);
        expect(await store.loadProject('del-me')).toBeNull();
    });

    it('loadProject returns null for a project that was never saved', async () => {
        expect(await store.loadProject('nope')).toBeNull();
    });

    it('listProjects sorts by updatedAt descending', async () => {
        await store.saveProject('older', makeSong());
        await new Promise((r) => setTimeout(r, 5));
        await store.saveProject('newer', makeSong());
        const list = await store.listProjects();
        expect(list.map((p) => p.id)).toEqual(['newer', 'older']);
    });

    describe('clean shutdown tracking', () => {
        it('marks a project dirty on save and clean after markCleanShutdown', async () => {
            await store.saveProject(AUTOSAVE_PROJECT_ID, makeSong());
            expect(await store.wasCleanShutdown(AUTOSAVE_PROJECT_ID)).toBe(false);

            await store.markCleanShutdown(AUTOSAVE_PROJECT_ID);
            expect(await store.wasCleanShutdown(AUTOSAVE_PROJECT_ID)).toBe(true);
        });

        it('returns null when there is no project to recover', async () => {
            expect(await store.wasCleanShutdown('never-saved')).toBeNull();
        });
    });

    describe('migrateLegacyAutosave', () => {
        it('lifts a legacy localStorage payload into the store and clears the key', async () => {
            const legacy = {
                autosaveVersion: 1,
                savedAt: Date.now(),
                samplesStripped: false,
                pattern: makeSong().pattern,
                params: makeSong().params,
                trackStorage: {},
                activeTrackSlots: {},
                songStructure: [],
                tempo: 133,
            };
            localStorage.setItem(AUTOSAVE_KEY, JSON.stringify(legacy));

            const migrated = await store.migrateLegacyAutosave();
            expect(migrated).toBe(true);
            expect(localStorage.getItem(AUTOSAVE_KEY)).toBeNull();

            const loaded = await store.loadProject(AUTOSAVE_PROJECT_ID);
            expect(loaded).not.toBeNull();
            expect(loaded!.tempo).toBe(133);
        });

        it('is a no-op (but still clears the key) when a newer autosave already exists', async () => {
            await store.saveProject(AUTOSAVE_PROJECT_ID, makeSong({ tempo: 200 }));

            const legacy = {
                autosaveVersion: 1,
                savedAt: Date.now(),
                samplesStripped: false,
                pattern: makeSong().pattern,
                params: makeSong().params,
                trackStorage: {},
                activeTrackSlots: {},
                songStructure: [],
                tempo: 90,
            };
            localStorage.setItem(AUTOSAVE_KEY, JSON.stringify(legacy));

            await store.migrateLegacyAutosave();
            expect(localStorage.getItem(AUTOSAVE_KEY)).toBeNull();

            const loaded = await store.loadProject(AUTOSAVE_PROJECT_ID);
            expect(loaded!.tempo).toBe(200); // untouched — the newer save wins
        });

        it('returns false when there is nothing to migrate', async () => {
            expect(await store.migrateLegacyAutosave()).toBe(false);
        });
    });

    describe('backgroundImage', () => {
        it('round-trips a data: URL background image via content addressing', async () => {
            const bytes = [137, 80, 78, 71, 1, 2, 3];
            let bin = '';
            for (const b of bytes) bin += String.fromCharCode(b);
            const dataUrl = `data:image/png;base64,${btoa(bin)}`;
            await store.saveProject('bg', makeSong({ backgroundImage: dataUrl }));
            const loaded = await store.loadProject('bg');
            expect(loaded!.backgroundImage).toBe(dataUrl);
        });

        it('passes through a plain (non-data:) URL unchanged', async () => {
            await store.saveProject('bg2', makeSong({ backgroundImage: 'https://example.com/bg.jpg' }));
            const loaded = await store.loadProject('bg2');
            expect(loaded!.backgroundImage).toBe('https://example.com/bg.jpg');
        });
    });
});

