import { describe, expect, it, beforeEach, vi } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';

/**
 * `ort.env` is a process-wide singleton. Supertonic, HybridNeuralPipeline and
 * CtcForcedAligner each used to write it from their own init path, so the
 * consumer that happened to initialise first decided the wasm URL and thread
 * count for all three — an order-dependent global that nothing tested.
 *
 * These tests pin the invariant that replaced it: exactly one writer, and a
 * result that does not depend on which consumer got there first.
 */

const envState = () => ({
  wasmPaths: '',
  numThreads: 0,
  simd: false,
});

let wasmEnv = envState();

vi.mock('onnxruntime-web', () => ({
  get env() {
    return { wasm: wasmEnv };
  },
  Tensor: class {},
  InferenceSession: { create: vi.fn() },
}));

beforeEach(async () => {
  wasmEnv = envState();
  vi.resetModules();
});

describe('ortRuntime', () => {
  it('configures ort.env exactly once, no matter how many callers ask', async () => {
    const { loadOrt, __resetOrtRuntimeForTests } = await import('../ortRuntime');
    __resetOrtRuntimeForTests();

    await loadOrt();
    expect(wasmEnv.numThreads).toBeGreaterThanOrEqual(1);
    expect(wasmEnv.simd).toBe(true);

    // A later caller must not be able to move the global out from under the
    // consumer that already built sessions against it.
    wasmEnv.numThreads = 99;
    await loadOrt();
    expect(wasmEnv.numThreads).toBe(99);
  });

  it('memoises the module so concurrent callers share one import', async () => {
    const { loadOrt, __resetOrtRuntimeForTests } = await import('../ortRuntime');
    __resetOrtRuntimeForTests();

    const [a, b] = await Promise.all([loadOrt(), loadOrt()]);
    expect(a).toBe(b);
  });

  it('yields the same wasmPaths and numThreads in either consumer order', async () => {
    // Drive the two real consumer entry points in both orders and compare the
    // global they leave behind. This is the regression the single-writer design
    // exists to prevent.
    const orders: Array<[string, string]> = [
      ['../Supertonic', '@/engines/rubberband/alignment/ctcForcedAligner'],
      ['@/engines/rubberband/alignment/ctcForcedAligner', '../Supertonic'],
    ];

    const results: Array<{ simd: boolean; numThreads: number }> = [];

    for (const [first, second] of orders) {
      vi.resetModules();
      wasmEnv = envState();

      const { loadOrt, __resetOrtRuntimeForTests } = await import('../ortRuntime');
      __resetOrtRuntimeForTests();

      // Importing a consumer must not touch ort.env by itself — the module-scope
      // side effects that made this order-dependent are gone.
      await import(/* @vite-ignore */ first);
      await import(/* @vite-ignore */ second);
      expect(wasmEnv.numThreads).toBe(0);
      expect(wasmEnv.simd).toBe(false);

      await loadOrt();
      results.push({ simd: wasmEnv.simd, numThreads: wasmEnv.numThreads });
    }

    expect(results[0]).toEqual(results[1]);
  });

  it('never assigns wasmPaths, leaving Vite\'s self-hosted asset URL intact', async () => {
    // Vite rewrites ORT's own `new URL(...)` reference to a content-hashed
    // binary emitted from the same resolved package. Assigning wasmPaths would
    // override that with an unhashed, hand-built URL — which is how the
    // jsDelivr pin got there in the first place.
    const { loadOrt, __resetOrtRuntimeForTests } = await import('../ortRuntime');
    __resetOrtRuntimeForTests();

    await loadOrt();
    expect(wasmEnv.wasmPaths).toBe('');
  });
});

describe('ort.env has a single writer in the source tree', () => {
  /**
   * A source-level guard, because the runtime tests above can only observe the
   * writers that happen to run. This one fails the moment a new consumer adds
   * its own `ort.env.wasm.* = …` anywhere outside ortRuntime.ts.
   */
  it('assigns ort.env.wasm.* only from src/services/ortRuntime.ts', () => {
    const srcRoot = path.resolve(__dirname, '../..');
    const offenders: string[] = [];

    const walk = (dir: string) => {
      for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) {
          if (entry.name === '__tests__' || entry.name === 'node_modules') continue;
          walk(full);
        } else if (/\.tsx?$/.test(entry.name)) {
          const rel = path.relative(srcRoot, full).split(path.sep).join('/');
          if (rel === 'services/ortRuntime.ts') continue;
          const src = fs.readFileSync(full, 'utf8');
          // Assignment to the ORT wasm env, e.g. `ort.env.wasm.numThreads = 4`.
          if (/\benv\s*\.\s*wasm\s*\.\s*(numThreads|simd|wasmPaths|proxy)\s*=/.test(src)) {
            offenders.push(rel);
          }
        }
      }
    };
    walk(srcRoot);

    expect(
      offenders,
      'ort.env is a process-wide singleton: route new configuration through ' +
        'configureOrt() in src/services/ortRuntime.ts instead of writing it directly.',
    ).toEqual([]);
  });
});

import { DB_CONFIG } from './constants';
import type { CloudSongPayload, PendingUpload, StorageErrorInfo } from './types';

class IndexedDBManager {
  private db: IDBDatabase | null = null;

  async init(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_CONFIG.NAME, DB_CONFIG.VERSION);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;

        if (!db.objectStoreNames.contains(DB_CONFIG.STORES.PENDING_UPLOADS)) {
          const store = db.createObjectStore(DB_CONFIG.STORES.PENDING_UPLOADS, { keyPath: 'id' });
          store.createIndex('attempts', 'attempts', { unique: false });
          store.createIndex('lastAttempt', 'lastAttempt', { unique: false });
        }

        if (!db.objectStoreNames.contains(DB_CONFIG.STORES.SONG_ERRORS)) {
          db.createObjectStore(DB_CONFIG.STORES.SONG_ERRORS, { keyPath: 'id' });
        }

        if (!db.objectStoreNames.contains(DB_CONFIG.STORES.VERSION_HISTORY)) {
          const store = db.createObjectStore(DB_CONFIG.STORES.VERSION_HISTORY, { keyPath: 'id' });
          store.createIndex('songId', 'songId', { unique: false });
        }
      };
    });
  }

  async addPendingUpload(payload: CloudSongPayload): Promise<void> {
    await this.ensureDB();
    const pending: PendingUpload = {
      id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      payload,
      attempts: 0,
      lastAttempt: new Date().toISOString()
    };

    return new Promise((resolve, reject) => {
      const tx = this.db!.transaction([DB_CONFIG.STORES.PENDING_UPLOADS], 'readwrite');
      const store = tx.objectStore(DB_CONFIG.STORES.PENDING_UPLOADS);
      const request = store.put(pending);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async getPendingUploads(): Promise<PendingUpload[]> {
    await this.ensureDB();
    return new Promise((resolve, reject) => {
      const tx = this.db!.transaction([DB_CONFIG.STORES.PENDING_UPLOADS], 'readonly');
      const store = tx.objectStore(DB_CONFIG.STORES.PENDING_UPLOADS);
      const request = store.getAll();
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  async removePendingUpload(id: string): Promise<void> {
    await this.ensureDB();
    return new Promise((resolve, reject) => {
      const tx = this.db!.transaction([DB_CONFIG.STORES.PENDING_UPLOADS], 'readwrite');
      const store = tx.objectStore(DB_CONFIG.STORES.PENDING_UPLOADS);
      const request = store.delete(id);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async updatePendingUpload(pending: PendingUpload): Promise<void> {
    await this.ensureDB();
    return new Promise((resolve, reject) => {
      const tx = this.db!.transaction([DB_CONFIG.STORES.PENDING_UPLOADS], 'readwrite');
      const store = tx.objectStore(DB_CONFIG.STORES.PENDING_UPLOADS);
      const request = store.put(pending);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async storeSongError(songId: string, error: StorageErrorInfo): Promise<void> {
    await this.ensureDB();
    return new Promise((resolve, reject) => {
      const tx = this.db!.transaction([DB_CONFIG.STORES.SONG_ERRORS], 'readwrite');
      const store = tx.objectStore(DB_CONFIG.STORES.SONG_ERRORS);
      const request = store.put({ id: songId, error, timestamp: new Date().toISOString() });
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async getSongError(songId: string): Promise<StorageErrorInfo | null> {
    await this.ensureDB();
    return new Promise((resolve, reject) => {
      const tx = this.db!.transaction([DB_CONFIG.STORES.SONG_ERRORS], 'readonly');
      const store = tx.objectStore(DB_CONFIG.STORES.SONG_ERRORS);
      const request = store.get(songId);
      request.onsuccess = () => {
        const result = request.result;
        resolve(result ? result.error : null);
      };
      request.onerror = () => reject(request.error);
    });
  }

  private async ensureDB(): Promise<void> {
    if (!this.db) {
      await this.init();
    }
  }
}

export const dbManager = new IndexedDBManager();

import { CloudStorage } from '../CloudStorage';
import { classifyAndEnhanceError } from './errorHandling';
import { dbManager } from './indexedDbManager';
import { log } from './logging';

let isOnline = typeof navigator !== 'undefined' ? navigator.onLine : true;
const onlineListeners: ((online: boolean) => void)[] = [];
let isSyncing = false;

async function syncPendingUploadsInternal(): Promise<void> {
  if (isSyncing || !isOnline) return;

  isSyncing = true;
  log('Starting sync of pending uploads');

  try {
    const pending = await dbManager.getPendingUploads();
    log(`Found ${pending.length} pending uploads`);

    for (const upload of pending) {
      try {
        const result = await CloudStorage.uploadItem(upload.payload);

        if (result.success) {
          await dbManager.removePendingUpload(upload.id);
          log(`Synced pending upload: ${upload.id}`);
        } else {
          upload.attempts++;
          upload.lastAttempt = new Date().toISOString();
          upload.error = result.error ? classifyAndEnhanceError(result.error) : undefined;
          await dbManager.updatePendingUpload(upload);
        }
      } catch (e) {
        upload.attempts++;
        upload.lastAttempt = new Date().toISOString();
        upload.error = classifyAndEnhanceError(e);
        await dbManager.updatePendingUpload(upload);
      }
    }
  } finally {
    isSyncing = false;
  }
}

if (typeof window !== 'undefined') {
  window.addEventListener('online', () => {
    isOnline = true;
    onlineListeners.forEach(l => l(true));
    syncPendingUploadsInternal();
  });

  window.addEventListener('offline', () => {
    isOnline = false;
    onlineListeners.forEach(l => l(false));
  });
}

export function subscribeToOnlineChanges(callback: (online: boolean) => void): () => void {
  onlineListeners.push(callback);
  return () => {
    const idx = onlineListeners.indexOf(callback);
    if (idx > -1) onlineListeners.splice(idx, 1);
  };
}

export function getIsOnline(): boolean {
  return isOnline;
}

export function getIsSyncing(): boolean {
  return isSyncing;
}

export { syncPendingUploadsInternal as syncPendingUploads };

import type { AISongData } from '../../importers/ai-song/types';
import type { Pattern, PartSequence, SavedSongData } from '../../types';
import type { StorageErrorInfo } from './types';

/** True when any track sequence in the pattern holds at least one note. */
function hasAnyNote(pattern: Pattern): boolean {
  const sequences: (PartSequence | PartSequence[] | undefined)[] = Object.values(pattern);
  return sequences.some((entry) => {
    const parts = Array.isArray(entry) ? entry : entry ? [entry] : [];
    return parts.some((part) => part?.steps?.some((step) => step !== null));
  });
}

/**
 * Validate song data before upload
 * Catches issues early to prevent failed uploads
 */
export function validateBeforeUpload(
  aiData: AISongData,
  hyphonSong: SavedSongData
): StorageErrorInfo | null {
  // Validate AI data
  if (!aiData.meta?.title || aiData.meta.title.trim().length === 0) {
    return {
      category: 'VALIDATION',
      message: 'Song title is required',
      userMessage: 'Please provide a song title before uploading.',
      retryable: false,
      timestamp: new Date().toISOString(),
      field: 'title'
    };
  }

  if (!aiData.meta?.author || aiData.meta.author.trim().length === 0) {
    return {
      category: 'VALIDATION',
      message: 'Author is required',
      userMessage: 'Please provide an author name before uploading.',
      retryable: false,
      timestamp: new Date().toISOString(),
      field: 'author'
    };
  }

  if (!aiData.meta?.prompt || aiData.meta.prompt.trim().length === 0) {
    return {
      category: 'VALIDATION',
      message: 'Prompt is required for AI-generated songs',
      userMessage: 'AI prompt information is missing. Please ensure the song has generation metadata.',
      retryable: false,
      timestamp: new Date().toISOString(),
      field: 'prompt'
    };
  }

  // Validate Hyphon data.
  // SavedSongData stores note data on `pattern` (plus the per-slot
  // `trackStorage`) and the transport rate on `tempo` — there are no
  // `tracks` / `bpm` fields.
  if (!hyphonSong.pattern || !hyphonSong.trackStorage) {
    return {
      category: 'VALIDATION',
      message: 'Song must have at least one track',
      userMessage: 'Please add at least one track to the song before uploading.',
      retryable: false,
      timestamp: new Date().toISOString(),
      field: 'pattern'
    };
  }

  if (!hasAnyNote(hyphonSong.pattern)) {
    return {
      category: 'VALIDATION',
      message: 'Song must have at least one note',
      userMessage: 'This song is empty. Please add at least one note before uploading.',
      retryable: false,
      timestamp: new Date().toISOString(),
      field: 'pattern'
    };
  }

  if (!hyphonSong.tempo || hyphonSong.tempo < 1 || hyphonSong.tempo > 999) {
    return {
      category: 'VALIDATION',
      message: 'Invalid tempo value',
      userMessage: 'Please set a valid tempo (1-999 BPM) before uploading.',
      retryable: false,
      timestamp: new Date().toISOString(),
      field: 'tempo'
    };
  }

  // Check data size (rough estimate)
  const dataSize = JSON.stringify({ aiData, hyphonSong }).length;
  if (dataSize > 10 * 1024 * 1024) { // 10MB limit
    return {
      category: 'VALIDATION',
      message: 'Song data exceeds maximum size',
      userMessage: 'The song data is too large. Please reduce the number of notes or patterns.',
      retryable: false,
      timestamp: new Date().toISOString(),
      field: 'size'
    };
  }

  return null;
}

import { describe, expect, it } from 'vitest';
import fc from 'fast-check';
import { TRACK_KEYS, NUM_STEPS } from '../../constants';
