/**
 * Automation Store
 *
 * Centralized state management for automation lanes, record-arm flags,
 * recording buffers, and playback position. Supports import from .rbs,
 * live recording, and AI-generated automation.
 *
 * Uses a subscription pattern (like loadingProgressStore) for decoupled updates.
 *
 * @see Issue #652 — Core data model, store, and types for automation lanes
 */

import React from 'react';
import type {
  AutomationState,
  UnifiedAutomationLane,
  AutomationLanePoint,
  AutomationTarget,
  AutomationSource,
  AutomationInterpolation,
  AutomationScope,
  AutomationRecordArm,
  AutomationRecordingBuffer,
} from '../types';
import type { HyphonAutomationLane } from '../importers/rbs/types';
import { interpolateLaneAtStep } from '../utils/knobAutomationCurve';

const EMPTY_LANES: UnifiedAutomationLane[] = [];

// ============================================================================
// HELPERS
// ============================================================================

let nextLaneId = 1;

/** Generate a unique lane ID */
export function generateLaneId(): string {
  return `auto_lane_${nextLaneId++}_${Date.now().toString(36)}`;
}

/** Reset ID counter (for testing) */
export function resetLaneIdCounter(): void {
  nextLaneId = 1;
}

// ============================================================================
// CONVERSION UTILITIES
// ============================================================================

/**
 * Convert a HyphonAutomationLane (from .rbs import) to a UnifiedAutomationLane.
 */
export function convertHyphonLane(
  lane: HyphonAutomationLane,
  patternIndex?: number
): UnifiedAutomationLane {
  const points: AutomationLanePoint[] = lane.points.map(([step, value]) => ({
    step,
    value,
  }));

  return {
    id: generateLaneId(),
    target: lane.target,
    parameter: lane.parameter,
    name: lane.name,
    points,
    interpolation: lane.interpolation,
    source: 'rbs',
    scope: patternIndex !== undefined ? 'pattern' : 'song',
    patternIndex,
    enabled: true,
    originalRange: lane.originalRange,
  };
}

/**
 * Convert multiple HyphonAutomationLanes from an RBS import.
 */
export function convertHyphonLanes(
  lanes: HyphonAutomationLane[],
  patternIndex?: number
): UnifiedAutomationLane[] {
  return lanes.map((lane) => convertHyphonLane(lane, patternIndex));
}

// ============================================================================
// STORE
// ============================================================================

type AutomationListener = (state: AutomationState) => void;

function createInitialState(): AutomationState {
  return {
    lanes: [],
    recordArms: [],
    recordingBuffers: [],
    playbackStep: 0,
    playbackEnabled: true,
    liveAutomatedValues: {},
    showHardwareAutomation: false,
  };
}

class AutomationStore {
  private state: AutomationState;
  private listeners: Set<AutomationListener> = new Set();

  // Cache to map "target:parameter" to pre-filtered lanes for O(1) lookups during playback
  private lanesCache: { ref: UnifiedAutomationLane[]; map: Map<string, UnifiedAutomationLane[]> } = {
    ref: [],
    map: new Map(),
  };

  constructor() {
    this.state = createInitialState();
  }

  // --------------------------------------------------------------------------
  // Subscriptions
  // --------------------------------------------------------------------------

  subscribe(listener: AutomationListener): () => void {
    this.listeners.add(listener);
    listener(this.getState());
    return () => this.listeners.delete(listener);
  }

  private notify(): void {
    const state = this.getState();
    this.listeners.forEach((listener) => listener(state));
  }

  getState(): AutomationState {
    return { ...this.state };
  }

  // --------------------------------------------------------------------------
  // Lane Management
  // --------------------------------------------------------------------------

  /** Add a single lane */
  addLane(lane: UnifiedAutomationLane): void {
    this.state = {
      ...this.state,
      lanes: [...this.state.lanes, lane],
    };
    this.notify();
  }

  /** Add multiple lanes (e.g. from RBS import) */
  addLanes(lanes: UnifiedAutomationLane[]): void {
    if (lanes.length === 0) return;
    this.state = {
      ...this.state,
      lanes: [...this.state.lanes, ...lanes],
    };
    this.notify();
  }

  /** Remove a lane by ID */
  removeLane(laneId: string): void {
    this.state = {
      ...this.state,
      lanes: this.state.lanes.filter((l) => l.id !== laneId),
    };
    this.notify();
  }

  /** Update a lane's points */
  updateLanePoints(laneId: string, points: AutomationLanePoint[]): void {
    this.state = {
      ...this.state,
      lanes: this.state.lanes.map((l) =>
        l.id === laneId ? { ...l, points: [...points].sort((a, b) => a.step - b.step) } : l
      ),
    };
    this.notify();
  }

  /** Update a lane's interpolation mode */
  updateLaneInterpolation(laneId: string, interpolation: AutomationInterpolation): void {
    this.state = {
      ...this.state,
      lanes: this.state.lanes.map((l) =>
        l.id === laneId ? { ...l, interpolation } : l
      ),
    };
    this.notify();
  }

  /** Update a lane's name */
  updateLaneName(laneId: string, name: string): void {
    this.state = {
      ...this.state,
      lanes: this.state.lanes.map((l) =>
        l.id === laneId ? { ...l, name } : l
      ),
    };
    this.notify();
  }

  /** Toggle lane enabled state */
  toggleLaneEnabled(laneId: string): void {
    this.state = {
      ...this.state,
      lanes: this.state.lanes.map((l) =>
        l.id === laneId ? { ...l, enabled: !l.enabled } : l
      ),
    };
    this.notify();
  }

  setLaneEnabled(laneId: string, enabled: boolean): void {
    this.state = {
      ...this.state,
      lanes: this.state.lanes.map((l) =>
        l.id === laneId ? { ...l, enabled } : l
      ),
    };
    this.notify();
  }

  /** Enable/disable all lanes for a target+parameter pair. */
  setLanesEnabledForParam(target: AutomationTarget, parameter: string, enabled: boolean): void {
    this.state = {
      ...this.state,
      lanes: this.state.lanes.map((l) =>
        l.target === target && l.parameter === parameter ? { ...l, enabled } : l
      ),
    };
    this.notify();
  }

  /** Remove all lanes targeting a parameter. */
  clearLanesForParam(target: AutomationTarget, parameter: string): void {
    this.state = {
      ...this.state,
      lanes: this.state.lanes.filter(
        (l) => !(l.target === target && l.parameter === parameter),
      ),
    };
    this.notify();
  }

  /** Primary enabled lane for a parameter in the current pattern scope. */
  getPrimaryLaneForParam(
    target: AutomationTarget,
    parameter: string,
    patternIndex = 0,
  ): UnifiedAutomationLane | null {
    const lanes = this.getLanesForParam(target, parameter).filter((l) => {
      if (!l.enabled) return false;
      return l.scope === 'song' || (l.scope === 'pattern' && l.patternIndex === patternIndex);
    });
    return lanes[0] ?? null;
  }

  /** Add or replace a point at the given step on a lane. */
  upsertLanePoint(laneId: string, step: number, value: number): void {
    const lane = this.state.lanes.find((l) => l.id === laneId);
    if (!lane) return;
    const clamped = Math.max(0, Math.min(1, value));
    const next = [...lane.points];
    const idx = next.findIndex((p) => p.step === step);
    if (idx >= 0) {
      next[idx] = { ...next[idx], value: clamped };
    } else {
      next.push({ step, value: clamped });
    }
    this.updateLanePoints(laneId, next);
  }

  setShowHardwareAutomation(show: boolean): void {
    if (this.state.showHardwareAutomation === show) return;
    this.state = { ...this.state, showHardwareAutomation: show };
    this.notify();
  }

  toggleShowHardwareAutomation(): void {
    this.setShowHardwareAutomation(!this.state.showHardwareAutomation);
  }

  /** Get lanes for a specific target and parameter */
  getLanesForParam(target: AutomationTarget, parameter: string): UnifiedAutomationLane[] {
    if (this.lanesCache.ref !== this.state.lanes) {
      const map = new Map<string, UnifiedAutomationLane[]>();
      const lanes = this.state.lanes;
      for (let i = 0; i < lanes.length; i++) {
        const lane = lanes[i];
        const key = `${lane.target}:${lane.parameter}`;
        let bucket = map.get(key);
        if (!bucket) {
          bucket = [];
          map.set(key, bucket);
        }
        bucket.push(lane);
      }
      this.lanesCache = { ref: lanes, map };
    }
    const key = `${target}:${parameter}`;
    return this.lanesCache.map.get(key) || EMPTY_LANES;
  }

  /** Get lanes targeting a specific sampler bank (0–7) */
  getLanesForSamplerBank(bankIndex: number, parameter?: string): UnifiedAutomationLane[] {
    const bankTarget = `sampler${bankIndex}` as AutomationTarget;
    return this.state.lanes.filter((l) => {
      // Match explicit per-bank target (e.g. 'sampler0')
      const matchesTarget = l.target === bankTarget ||
        (l.target === 'sampler' && l.samplerBank === bankIndex);
      if (!matchesTarget) return false;
      if (parameter) return l.parameter === parameter;
      return true;
    });
  }

  /** Get all enabled lanes for a given pattern index */
  getActiveLanesForPattern(patternIndex: number): UnifiedAutomationLane[] {
    return this.state.lanes.filter(
      (l) =>
        l.enabled &&
        (l.scope === 'song' || (l.scope === 'pattern' && l.patternIndex === patternIndex))
    );
  }

  /** Clear all lanes (e.g. when loading a new song) */
  clearAllLanes(): void {
    this.state = {
      ...this.state,
      lanes: [],
    };
    this.notify();
  }

  /** Clear lanes from a specific source */
  clearLanesBySource(source: AutomationSource): void {
    this.state = {
      ...this.state,
      lanes: this.state.lanes.filter((l) => l.source !== source),
    };
    this.notify();
  }

  // --------------------------------------------------------------------------
  // Record-Arm
  // --------------------------------------------------------------------------

  /** Arm a parameter for recording */
  armParameter(target: AutomationTarget, parameter: string): void {
    const existing = this.state.recordArms.find(
      (a) => a.target === target && a.parameter === parameter
    );
    if (existing?.armed) return; // already armed

    const newArms = this.state.recordArms.filter(
      (a) => !(a.target === target && a.parameter === parameter)
    );
    newArms.push({ target, parameter, armed: true });

    this.state = { ...this.state, recordArms: newArms };
    this.notify();
  }

  /** Disarm a parameter */
  disarmParameter(target: AutomationTarget, parameter: string): void {
    this.state = {
      ...this.state,
      recordArms: this.state.recordArms.map((a) =>
        a.target === target && a.parameter === parameter ? { ...a, armed: false } : a
      ),
    };
    this.notify();
  }

  /** Check if a parameter is armed */
  isParameterArmed(target: AutomationTarget, parameter: string): boolean {
    return this.state.recordArms.some(
      (a) => a.target === target && a.parameter === parameter && a.armed
    );
  }

  /** Disarm all parameters */
  disarmAll(): void {
    this.state = {
      ...this.state,
      recordArms: this.state.recordArms.map((a) => ({ ...a, armed: false })),
    };
    this.notify();
  }

  // --------------------------------------------------------------------------
  // Recording Buffers
  // --------------------------------------------------------------------------

  /** Start recording for an armed parameter */
  startRecording(target: AutomationTarget, parameter: string): void {
    // Remove existing buffer for this target/param
    const buffers = this.state.recordingBuffers.filter(
      (b) => !(b.target === target && b.parameter === parameter)
    );
    buffers.push({
      target,
      parameter,
      points: [],
      startTime: performance.now(),
      isRecording: true,
    });
    this.state = { ...this.state, recordingBuffers: buffers };
    this.notify();
  }

  /**
   * Record a point during active recording.
   * NOTE: Does not notify subscribers on each point for performance reasons —
   * recording can produce 60+ points/sec. Consumers needing live feedback
   * should poll getState() or use a separate RAF-based display loop.
   */
  recordPoint(target: AutomationTarget, parameter: string, point: AutomationLanePoint): void {
    this.state = {
      ...this.state,
      recordingBuffers: this.state.recordingBuffers.map((b) =>
        b.target === target && b.parameter === parameter && b.isRecording
          ? { ...b, points: [...b.points, point] }
          : b
      ),
    };
  }

  /** Stop recording and commit buffer to a new lane */
  stopRecording(
    target: AutomationTarget,
    parameter: string,
    options?: { name?: string; scope?: AutomationScope; patternIndex?: number }
  ): UnifiedAutomationLane | null {
    const buffer = this.state.recordingBuffers.find(
      (b) => b.target === target && b.parameter === parameter && b.isRecording
    );
    if (!buffer || buffer.points.length === 0) {
      // Remove buffer without creating a lane
      this.state = {
        ...this.state,
        recordingBuffers: this.state.recordingBuffers.filter(
          (b) => !(b.target === target && b.parameter === parameter)
        ),
      };
      this.notify();
      return null;
    }

    const newLane: UnifiedAutomationLane = {
      id: generateLaneId(),
      target,
      parameter,
      name: options?.name || `${target}.${parameter} (recorded)`,
      points: [...buffer.points].sort((a, b) => a.step - b.step),
      interpolation: 'linear',
      source: 'recorded',
      scope: options?.scope || 'pattern',
      patternIndex: options?.patternIndex,
      enabled: true,
    };

    this.state = {
      ...this.state,
      lanes: [...this.state.lanes, newLane],
      recordingBuffers: this.state.recordingBuffers.filter(
        (b) => !(b.target === target && b.parameter === parameter)
      ),
    };
    this.notify();
    return newLane;
  }

  /** Cancel recording without committing */
  cancelRecording(target: AutomationTarget, parameter: string): void {
    this.state = {
      ...this.state,
      recordingBuffers: this.state.recordingBuffers.filter(
        (b) => !(b.target === target && b.parameter === parameter)
      ),
    };
    this.notify();
  }

  // --------------------------------------------------------------------------
  // Playback
  // --------------------------------------------------------------------------

  /**
   * Update the current playback step position.
   * NOTE: Does not notify subscribers — called on every 16th-note tick.
   * The playback scheduler reads this via getState() directly.
   */
  setPlaybackStep(step: number): void {
    this.state = { ...this.state, playbackStep: step };
  }

  /** Toggle global automation playback */
  setPlaybackEnabled(enabled: boolean): void {
    this.state = { ...this.state, playbackEnabled: enabled };
    this.notify();
  }

  // Keep track of pending rAF to debounce UI updates for live values
  private _liveValuesRaf: number | null = null;

  /**
   * Update live automated values for UI display.
   * Called once per step tick with all values collected during that step.
   * Merges into existing map so stale entries remain visible until cleared.
   * Employs rAF coalescing to prevent main-thread UI contention.
   */
  setLiveValues(values: Record<string, number>): void {
    let changed = false;
    for (const key in values) {
      if (this.state.liveAutomatedValues[key] !== values[key]) {
        changed = true;
        break;
      }
    }
    if (!changed) return;

    const merged: Record<string, number> = {};
    const oldValues = this.state.liveAutomatedValues;
    for (const key in oldValues) {
      merged[key] = oldValues[key];
    }
    for (const key in values) {
      merged[key] = values[key];
    }

    this.state = { ...this.state, liveAutomatedValues: merged };

    // Coalesce React notify() into the next animation frame
    if (this._liveValuesRaf === null) {
      this._liveValuesRaf = requestAnimationFrame(() => {
        this.notify();
        this._liveValuesRaf = null;
      });
    }
  }

  /**
   * Clear all live automated values (e.g. when playback stops).
   * No-op if already empty.
   */
  clearLiveValues(): void {
    if (Object.keys(this.state.liveAutomatedValues).length === 0) return;
    this.state = { ...this.state, liveAutomatedValues: {} };
    if (this._liveValuesRaf !== null) {
      cancelAnimationFrame(this._liveValuesRaf);
      this._liveValuesRaf = null;
    }
    this.notify();
  }

  /**
   * Get the interpolated value for a lane at a given step.
   * Returns null if no points cover that step.
   */
  getValueAtStep(lane: UnifiedAutomationLane, step: number): number | null {
    return interpolateLaneAtStep(lane, step);
  }

  // --------------------------------------------------------------------------
  // Serialization (for song save/load)
  // --------------------------------------------------------------------------

  /** Export lanes for saving in SavedSongData */
  exportLanes(): UnifiedAutomationLane[] {
    return this.state.lanes.map((lane) => ({ ...lane }));
  }

  /** Import lanes from saved song data */
  importLanes(lanes: UnifiedAutomationLane[]): void {
    this.state = {
      ...this.state,
      lanes: lanes.map((l) => ({ ...l })),
    };
    this.notify();
  }

  /** Import lanes from RBS HyphonAutomationLanes */
  importFromRbs(hyphonLanes: HyphonAutomationLane[], patternIndex?: number): void {
    const converted = convertHyphonLanes(hyphonLanes, patternIndex);
    this.addLanes(converted);
  }

  // --------------------------------------------------------------------------
  // Reset
  // --------------------------------------------------------------------------

  /** Full reset to initial state */
  reset(): void {
    this.state = createInitialState();
    this.notify();
  }
}

// Singleton instance
export const automationStore = new AutomationStore();

// ============================================================================
// React Hook
// ============================================================================

/**
 * React hook for consuming automation state in components.
 */
export function useAutomationStore(): AutomationState {
  const [state, setState] = React.useState<AutomationState>(automationStore.getState());

  React.useEffect(() => {
    return automationStore.subscribe(setState);
  }, []);

  return state;
}

/**
 * Loading Progress Store
 * Manages initialization state across the audio engine startup sequence.
 * Uses a subscription pattern for decoupled updates.
 */

import React from 'react';

export type LoadingStep =
  | 'audioContext'
  | 'masterChain'
  | 'webGpuEngine'
  | 'wasmEngine'
  | 'open303Engine'
  | 'prophecyEngine'
  | 'wavFiles'
  | 'singingVoice'
  | 'ambianceBuffers'
  | 'ttsEngine'
  | 'complete';

export interface LoadingStepInfo {
  id: LoadingStep;
  label: string;
  weight: number; // Progress weight (0-100 total)
  status: 'pending' | 'active' | 'completed' | 'error';
  errorMessage?: string;
  startTime?: number;
  endTime?: number;
}

export interface LoadingState {
  isLoading: boolean;
  totalProgress: number; // 0-100
  currentStep: LoadingStep | null;
  steps: Record<LoadingStep, LoadingStepInfo>;
  errors: string[];
  /** Runtime degradations after boot (GPU/WASM/worklet fallbacks). */
  runtimeDegradations: RuntimeDegradationEntry[];
  startTime: number | null;
  estimatedTimeRemaining: number | null;
}

export interface RuntimeDegradationEntry {
  subsystem: string;
  message: string;
  reason: string;
  ts: number;
}

type ProgressListener = (state: LoadingState) => void;

class LoadingProgressStore {
  private state: LoadingState;
  private listeners: Set<ProgressListener> = new Set();
  private animationFrame: number | null = null;

  // Step weights — calibrated to typical wall-clock cost during initializeAudio().
  // Supertonic (ttsEngine) and ambiance buffers load AFTER the overlay closes, so
  // they're weighted 0 and only present for backward compatibility.
  // Total of active weights must = 100.
  private static readonly STEP_WEIGHTS: Record<LoadingStep, number> = {
    audioContext: 3,        // createContext + resume, ~10ms
    masterChain: 4,         // gain/saturation/reverb/delay nodes, ~10ms
    webGpuEngine: 8,        // GPU detection / adapter request, ~100-300ms
    wasmEngine: 5,          // WASM oscillator init
    open303Engine: 15,      // WASM fetch + worklet × 2 (was 20; reduced by 5 to fit prophecyEngine)
    prophecyEngine: 10,     // Prophecy formant WASM worklet init
    wavFiles: 5,            // fetch + decodeAudioData for saw/square
    singingVoice: 45,       // 12 SingingVoice worklets, dominant cost (was 50; reduced by 5 to fit prophecyEngine)
    ambianceBuffers: 0,     // lazy-loaded, not part of init
    ttsEngine: 0,           // Supertonic, loads after overlay closes
    complete: 5,            // final wiring
  };

  private static readonly STEP_LABELS: Record<LoadingStep, string> = {
    audioContext: 'Initializing Audio Context',
    masterChain: 'Setting up Master Audio Chain',
    webGpuEngine: 'Initializing WebGPU Oscillator',
    wasmEngine: 'Loading WASM Oscillator',
    open303Engine: 'Loading TB-303 Bass Engine',
    prophecyEngine: 'Loading Prophecy Formant Engine',
    wavFiles: 'Loading Waveform Samples',
    singingVoice: 'Initializing Singing Voice Pool',
    ambianceBuffers: 'Preparing Ambiance Tracks',
    ttsEngine: 'Loading TTS Voice Engine',
    complete: 'Finalizing Setup',
  };

  constructor() {
    this.state = this.createInitialState();
  }

  private createInitialState(): LoadingState {
    const steps = {} as Record<LoadingStep, LoadingStepInfo>;

    (Object.keys(LoadingProgressStore.STEP_WEIGHTS) as LoadingStep[]).forEach((step) => {
      steps[step] = {
        id: step,
        label: LoadingProgressStore.STEP_LABELS[step],
        weight: LoadingProgressStore.STEP_WEIGHTS[step],
        status: 'pending',
      };
    });

    return {
      isLoading: false,
      totalProgress: 0,
      currentStep: null,
      steps,
      errors: [],
      runtimeDegradations: [],
      startTime: null,
      estimatedTimeRemaining: null,
    };
  }

  // Subscribe to progress updates
  subscribe(listener: ProgressListener): () => void {
    this.listeners.add(listener);
    // Immediately call with current state
    listener(this.getState());
    return () => this.listeners.delete(listener);
  }

  private notify(): void {
    if (this.animationFrame) {
      cancelAnimationFrame(this.animationFrame);
    }
    this.animationFrame = requestAnimationFrame(() => {
      const state = this.getState();
      this.listeners.forEach((listener) => listener(state));
    });
  }

  getState(): LoadingState {
    return { ...this.state };
  }

  // Start loading sequence
  startLoading(): void {
    this.state = {
      ...this.createInitialState(),
      isLoading: true,
      startTime: performance.now(),
      runtimeDegradations: [],
    };
    this.logDebug('🚀 Loading sequence started');
    this.notify();
  }

  // Mark a step as active (started)
  startStep(step: LoadingStep): void {
    if (!this.state.isLoading) return;

    this.state.steps[step] = {
      ...this.state.steps[step],
      status: 'active',
      startTime: performance.now(),
    };
    this.state.currentStep = step;
    this.logDebug(`▶️  Starting: ${this.state.steps[step].label}`);
    this.notify();
  }

  // Mark a step as completed
  completeStep(step: LoadingStep): void {
    if (!this.state.isLoading) return;

    const endTime = performance.now();
    const duration = this.state.steps[step].startTime
      ? Math.round(endTime - this.state.steps[step].startTime)
      : 0;

    this.state.steps[step] = {
      ...this.state.steps[step],
      status: 'completed',
      endTime,
    };

    this.updateTotalProgress();
    this.logDebug(`✅ Completed: ${this.state.steps[step].label} (${duration}ms)`);
    this.notify();
  }

  // Mark a step as failed (non-fatal)
  failStep(step: LoadingStep, error: Error, isRecoverable = true): void {
    if (!this.state.isLoading) return;

    this.state.steps[step] = {
      ...this.state.steps[step],
      status: 'error',
      errorMessage: error.message,
    };

    if (!isRecoverable) {
      this.state.errors.push(`${this.state.steps[step].label}: ${error.message}`);
    }

    this.updateTotalProgress();
    this.logDebug(
      `${isRecoverable ? '⚠️' : '❌'} Failed: ${this.state.steps[step].label} - ${error.message}`,
    );
    this.notify();
  }

  // Update progress for a step (for fine-grained updates like file loading)
  updateStepProgress(step: LoadingStep, percent: number): void {
    if (!this.state.isLoading) return;

    // Calculate weighted contribution
    const stepWeight = this.state.steps[step].weight;
    const weightedProgress = (percent / 100) * stepWeight;

    // Update total progress (completed steps + current step partial)
    const completedSteps = (Object.keys(this.state.steps) as LoadingStep[])
      .filter((s) => this.state.steps[s].status === 'completed' && s !== step)
      .reduce((sum, s) => sum + this.state.steps[s].weight, 0);

    this.state.totalProgress = Math.min(99, completedSteps + weightedProgress);
    this.notify();
  }

  private updateTotalProgress(): void {
    const completedWeight = (Object.keys(this.state.steps) as LoadingStep[])
      .filter((s) => this.state.steps[s].status === 'completed')
      .reduce((sum, s) => sum + this.state.steps[s].weight, 0);

    this.state.totalProgress = Math.min(99, completedWeight);
  }

  // Complete loading sequence
  finishLoading(): void {
    this.state.isLoading = false;
    this.state.totalProgress = 100;
    this.state.currentStep = 'complete';

    const totalTime = this.state.startTime
      ? Math.round(performance.now() - this.state.startTime)
      : 0;

    this.logDebug(`🎉 Loading complete! Total time: ${totalTime}ms`);
    this.notify();
  }

  // Add an error message
  addError(message: string): void {
    this.state.errors.push(message);
    this.logDebug(`❌ Error: ${message}`);
    this.notify();
  }

  /** Record a post-boot runtime degradation (GPU context lost, WASM fallback, etc.). */
  recordRuntimeDegradation(subsystem: string, message: string, reason: string): void {
    const entry: RuntimeDegradationEntry = {
      subsystem,
      message,
      reason,
      ts: Date.now(),
    };
    const existingIdx = this.state.runtimeDegradations.findIndex((d) => d.subsystem === subsystem);
    if (existingIdx >= 0) {
      this.state.runtimeDegradations[existingIdx] = entry;
    } else {
      this.state.runtimeDegradations.push(entry);
    }
    this.logDebug(`⚠️ Runtime degradation: ${subsystem} — ${message}`);
    this.notify();
  }

  clearRuntimeDegradation(subsystem: string): void {
    this.state.runtimeDegradations = this.state.runtimeDegradations.filter((d) => d.subsystem !== subsystem);
    this.notify();
  }

  // Debug logging with structured output
  private logDebug(message: string): void {
    const timestamp = new Date().toISOString().split('T')[1].split('.')[0];
    const prefix = `[${timestamp}] [AudioLoader]`;

    // Structured log for debugging
    if (typeof window !== 'undefined' && (window as any).__AUDIO_LOADER_DEBUG__) {
      console.log(`${prefix} ${message}`);
    }
  }

  // Enable debug logging
  enableDebug(): void {
    if (typeof window !== 'undefined') {
      (window as any).__AUDIO_LOADER_DEBUG__ = true;
    }
  }

  // Get timing report for performance analysis
  getTimingReport(): Record<string, number> {
    const report: Record<string, number> = {};
    (Object.keys(this.state.steps) as LoadingStep[]).forEach((step) => {
      const info = this.state.steps[step];
      if (info.startTime && info.endTime) {
        report[step] = Math.round(info.endTime - info.startTime);
      }
    });
    return report;
  }
}

// Singleton instance
export const loadingProgressStore = new LoadingProgressStore();

// Hook for React components
export function useLoadingProgress(): LoadingState {
  const [state, setState] = React.useState<LoadingState>(loadingProgressStore.getState());

  React.useEffect(() => {
    return loadingProgressStore.subscribe(setState);
  }, []);

  return state;
}

/**
 * MIDI Learn / mapping store.
 * User prefs persist in localStorage; song-level mappings ride in SavedSongData.
 */

import React from 'react';
import type { MidiBinding, MidiControlId, MidiMessageKey } from '../types/midi';
import { midiKeyToString } from '../types/midi';

const USER_PREFS_KEY = 'hyphon-midi-mappings';

export interface MidiMapState {
  learnMode: boolean;
  /** Last UI control touched while learn mode is active (or via long-press). */
  lastTouchedControl: MidiControlId | null;
  mappings: MidiBinding[];
  /** Controls currently receiving MIDI (for activity flash). */
  activeControls: Record<MidiControlId, number>;
  /** Web MIDI available and at least one input connected. */
  inputAvailable: boolean;
  connectedInputs: string[];
  /** Panel visibility */
  panelOpen: boolean;
}

type MidiMapListener = (state: MidiMapState) => void;

function loadUserMappings(): MidiBinding[] {
  if (typeof localStorage === 'undefined') return [];
  try {
    const raw = localStorage.getItem(USER_PREFS_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function saveUserMappings(mappings: MidiBinding[]): void {
  if (typeof localStorage === 'undefined') return;
  try {
    localStorage.setItem(USER_PREFS_KEY, JSON.stringify(mappings));
  } catch {
    // Quota or private browsing — ignore
  }
}

function createInitialState(): MidiMapState {
  return {
    learnMode: false,
    lastTouchedControl: null,
    mappings: loadUserMappings(),
    activeControls: {},
    inputAvailable: false,
    connectedInputs: [],
    panelOpen: false,
  };
}

class MidiMapStore {
  private state: MidiMapState = createInitialState();
  private listeners = new Set<MidiMapListener>();
  private activityTimers = new Map<MidiControlId, ReturnType<typeof setTimeout>>();

  getState(): MidiMapState {
    return this.state;
  }

  subscribe(listener: MidiMapListener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  private notify(): void {
    this.listeners.forEach((l) => l(this.state));
  }

  private setState(patch: Partial<MidiMapState>): void {
    this.state = { ...this.state, ...patch };
    this.notify();
  }

  setLearnMode(enabled: boolean): void {
    this.setState({
      learnMode: enabled,
      lastTouchedControl: enabled ? this.state.lastTouchedControl : null,
    });
  }

  toggleLearnMode(): void {
    this.setLearnMode(!this.state.learnMode);
  }

  setPanelOpen(open: boolean): void {
    this.setState({ panelOpen: open });
  }

  touchControl(controlId: MidiControlId): void {
    this.setState({ lastTouchedControl: controlId });
  }

  setInputAvailable(available: boolean, names: string[] = []): void {
    this.setState({ inputAvailable: available, connectedInputs: names });
  }

  /** Merge song mappings over user prefs (song wins on duplicate keys). */
  importSongMappings(songMappings: MidiBinding[] | undefined): void {
    const user = loadUserMappings();
    const merged = mergeBindings(user, songMappings ?? []);
    this.setState({ mappings: merged });
  }

  /** Export current mappings for song save. */
  exportMappings(): MidiBinding[] {
    return this.state.mappings.map((m) => ({ ...m }));
  }

  addBinding(binding: MidiBinding): void {
    const keyStr = midiKeyToString(binding.key);
    const next = this.state.mappings.filter((m) => midiKeyToString(m.key) !== keyStr);
    next.push(binding);
    this.setState({ mappings: next });
    saveUserMappings(next);
  }

  removeBinding(key: MidiMessageKey, deviceId?: string): void {
    const keyStr = midiKeyToString(key);
    const next = this.state.mappings.filter(
      (m) => midiKeyToString(m.key) !== keyStr || m.deviceId !== deviceId,
    );
    this.setState({ mappings: next });
    saveUserMappings(next);
  }

  clearBindingsForControl(controlId: MidiControlId): void {
    const next = this.state.mappings.filter((m) => m.controlId !== controlId);
    this.setState({ mappings: next });
    saveUserMappings(next);
  }

  clearAllBindings(): void {
    this.setState({ mappings: [] });
    saveUserMappings([]);
  }

  findBinding(key: MidiMessageKey, deviceId?: string): MidiBinding | undefined {
    const keyStr = midiKeyToString(key);
    const exact = this.state.mappings.find(
      (m) => midiKeyToString(m.key) === keyStr && (!m.deviceId || m.deviceId === deviceId),
    );
    if (exact) return exact;
    return this.state.mappings.find((m) => midiKeyToString(m.key) === keyStr && !m.deviceId);
  }

  isControlMapped(controlId: MidiControlId): boolean {
    return this.state.mappings.some((m) => m.controlId === controlId);
  }

  flashControl(controlId: MidiControlId): void {
    const prev = this.activityTimers.get(controlId);
    if (prev) clearTimeout(prev);
    this.setState({
      activeControls: { ...this.state.activeControls, [controlId]: Date.now() },
    });
    const timer = setTimeout(() => {
      const { [controlId]: _, ...rest } = this.state.activeControls;
      this.setState({ activeControls: rest as Record<MidiControlId, number> });
      this.activityTimers.delete(controlId);
    }, 120);
    this.activityTimers.set(controlId, timer);
  }

  reset(): void {
    this.activityTimers.forEach((t) => clearTimeout(t));
    this.activityTimers.clear();
    this.state = createInitialState();
    this.notify();
  }
}

function mergeBindings(base: MidiBinding[], overrides: MidiBinding[]): MidiBinding[] {
  const map = new Map<string, MidiBinding>();
  for (const b of base) {
    map.set(`${midiKeyToString(b.key)}|${b.deviceId ?? ''}`, b);
  }
  for (const b of overrides) {
    map.set(`${midiKeyToString(b.key)}|${b.deviceId ?? ''}`, b);
  }
  return Array.from(map.values());
}

export const midiMapStore = new MidiMapStore();

export function useMidiMapStore(): MidiMapState {
  const [state, setState] = React.useState<MidiMapState>(midiMapStore.getState());
  React.useEffect(() => midiMapStore.subscribe(setState), []);
  return state;
}

/**
 * Transport & Mix Store
 *
 * External, `useSyncExternalStore`-backed home for the app's transport and
 * master mix properties (tempo, swing, master volume, etc.).
 *
 * These flags used to live as `useState` calls inside `useAppState()`, which meant
 * every one of them was folded into the single object handed to `AppStateContext`.
 * Moving them here lets a component subscribe to exactly the flag it cares
 * about via `useTransportMixStore(selector)`.
 *
 * `useTransportMixState()` (src/hooks/appState/useTransportMixState.ts) still wraps
 * this store so `useAppState()` and `AppStateContext` keep working
 * unchanged for consumers that haven't migrated off the shared context yet.
 */

import { useSyncExternalStore } from 'react';
import { DEFAULT_TEMPO } from '../constants';
import type { ReverbType } from '../types';

export interface TransportMixState {
  tempo: number;
  swing: number;
  masterVolume: number;
  masterSaturation: number;
  globalPan: number;
  reverbType: ReverbType;
  ambianceUrl: string;
  backgroundImage: string;
}

type Listener = () => void;

function createInitialState(): TransportMixState {
  return {
    tempo: DEFAULT_TEMPO,
    swing: 0,
    masterVolume: 0.8,
    masterSaturation: 0,
    globalPan: 0,
    reverbType: 'plate',
    ambianceUrl: '',
    backgroundImage: '',
  };
}

class TransportMixStore {
  private state: TransportMixState = createInitialState();
  private listeners = new Set<Listener>();

  // Expose refs for audio code to read without a render
  public tempoRef: { current: number } = { current: DEFAULT_TEMPO };
  public lastFreqRef: { current: Record<string, number> } = { current: { partA: 0, partB: 0 } };

  subscribe = (listener: Listener): (() => void) => {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  };

  getSnapshot = (): TransportMixState => this.state;

  private notify(): void {
    this.listeners.forEach((listener) => listener());
  }

  private setField<K extends keyof TransportMixState>(key: K, action: TransportMixState[K] | ((prev: TransportMixState[K]) => TransportMixState[K])): void {
    const prev = this.state[key];
    const next = typeof action === 'function' ? (action as any)(prev) : action;
    if (next === prev) return;
    this.state = { ...this.state, [key]: next };

    // Sync ref for tempo
    if (key === 'tempo') {
        this.tempoRef.current = next as number;
    }

    this.notify();
  }

  setTempo = (v: number | ((prev: number) => number)): void => this.setField('tempo', v);
  setSwing = (v: number | ((prev: number) => number)): void => this.setField('swing', v);
  setMasterVolume = (v: number | ((prev: number) => number)): void => this.setField('masterVolume', v);
  setMasterSaturation = (v: number | ((prev: number) => number)): void => this.setField('masterSaturation', v);
  setGlobalPan = (v: number | ((prev: number) => number)): void => this.setField('globalPan', v);
  setReverbType = (v: ReverbType | ((prev: ReverbType) => ReverbType)): void => this.setField('reverbType', v);
  setAmbianceUrl = (v: string | ((prev: string) => string)): void => this.setField('ambianceUrl', v);
  setBackgroundImage = (v: string | ((prev: string) => string)): void => this.setField('backgroundImage', v);

  /** Full reset to initial state (used in tests). */
  reset = (): void => {
    this.state = createInitialState();
    this.tempoRef.current = this.state.tempo;
    this.lastFreqRef.current = { partA: 0, partB: 0 };
    this.notify();
  };
}

export const transportMixStore = new TransportMixStore();

const identitySelector = (state: TransportMixState): TransportMixState => state;

export function useTransportMixStore<T = TransportMixState>(
  selector: (state: TransportMixState) => T = identitySelector as unknown as (state: TransportMixState) => T,
): T {
  return useSyncExternalStore(
    transportMixStore.subscribe,
    () => selector(transportMixStore.getSnapshot()),
  );
}

import { expect } from 'vitest';
import { engineTelemetry } from '@/utils/engineTelemetry';
import { engineDegradationStore } from '@/stores/engineDegradationStore';

type BackendKind = 'wasm' | 'js-fallback' | 'webgpu' | 'rust-wasm' | string;

/**
 * Assert the telemetry resolution for a subsystem matches the expected backend.
 */
export function expectActiveBackend(subsystem: string, expected: BackendKind): void {
  const snap = engineTelemetry.snapshot();
  const report = snap[subsystem];
  const history = report?.resolutionHistory ?? [];
  const latest = history[history.length - 1] ?? report?.resolution;
  const issues = engineDegradationStore.getIssues().filter(
    (i) =>
      i.subsystem === subsystem ||
      i.message?.toLowerCase().includes(subsystem.toLowerCase()),
  );

  const activeFromStore = issues.find((i) => i.activeBackend)?.activeBackend;
  const resolved = activeFromStore ?? latest?.backend;

  expect(
    resolved,
    `Expected backend "${expected}" for ${subsystem}, got ${String(resolved)} (issues: ${JSON.stringify(issues)})`,
  ).toBe(expected);
}

/**
 * Fail when a subsystem fell back to JS or logged a degradation issue.
 */
export function expectNotFallback(subsystem: string): void {
  const issues = engineDegradationStore.getIssues().filter(
    (i) =>
      i.subsystem === subsystem ||
      i.message?.toLowerCase().includes(subsystem.toLowerCase()),
  );

  const fallbackIssue = issues.find(
    (i) =>
      i.activeBackend === 'js-fallback' ||
      /fallback/i.test(i.message ?? '') ||
      /js fallback/i.test(i.message ?? ''),
  );

  expect(
    fallbackIssue,
    `Unexpected fallback for ${subsystem}: ${JSON.stringify(fallbackIssue ?? issues)}`,
  ).toBeUndefined();
}

/**
 * Assert an engine object reports ready and not on fallback path.
 */
export function expectEngineReady(
  engine: { isReady?: boolean; isFallback?: boolean },
  label: string,
): void {
  expect(engine.isReady, `${label} should be ready`).toBe(true);
  if ('isFallback' in engine) {
    expect(engine.isFallback, `${label} should not be on fallback`).toBe(false);
  }
}

/**
 * Hermetic stub for WebAssembly imports (`*.wasm?init`) during unit tests.
 * This ensures unit tests can run without building actual WASM binaries.
 * It attempts to call `WebAssembly.instantiate` so tests that spy on it can
 * inject their mocks (e.g., WasmOscillator.test.ts).
 */
export default async function initWasmStub(): Promise<WebAssembly.Instance> {
  const dummyBuffer = new Uint8Array(8);
  try {
    const result = await WebAssembly.instantiate(dummyBuffer);
    return result.instance;
  } catch (e) {
    return {
      exports: {
        memory: new WebAssembly.Memory({ initial: 1 })
      },
    } as unknown as WebAssembly.Instance;
  }
}

