import type { WaveShape } from './waveformParser';

/** Map VoiceManager wave shapes to generate_wave() osc_type strings. */
export const PYODIDE_OSC_TYPE: Record<WaveShape, string> = {
  saw: 'saw',
  sqr: 'square',
  sin: 'sine',
  tri: 'sine',
};

export type PyodideLike = {
  globals: {
    get: (name: string) => (...args: unknown[]) => unknown;
  };
};

const REF_FREQ = 261.63;
const LOOP_DURATION_SEC = 2.0;
const DEFAULT_CUTOFF = 8000;
const DEFAULT_RESONANCE = 0.5;

function pyodideSamplesToFloat32(pyProxy: {
  toJs: (opts: { array_buffer_type: 'float32' }) => Float32Array;
  destroy: () => void;
}): Float32Array | null {
  try {
    const samples = pyProxy.toJs({ array_buffer_type: 'float32' });
    pyProxy.destroy();
    return samples?.length ? samples : null;
  } catch {
    try {
      pyProxy.destroy();
    } catch {
      /* noop */
    }
    return null;
  }
}

/** Synchronous one-shot buffer for a single note (used when pre-render cache misses). */
export function generatePyodideLoopBuffer(
  pyodide: PyodideLike,
  context: BaseAudioContext,
  shape: WaveShape,
  filterCutoff = DEFAULT_CUTOFF,
  filterResonance = DEFAULT_RESONANCE,
): AudioBuffer | null {
  try {
    pyodide.globals.get('set_sample_rate')(context.sampleRate);
    const generate = pyodide.globals.get('generate_loop_buffer') ?? pyodide.globals.get('generate_wave');
    const pyProxy = generate(
      REF_FREQ,
      LOOP_DURATION_SEC,
      PYODIDE_OSC_TYPE[shape],
      Math.max(20, Math.min(context.sampleRate / 2.1, filterCutoff)),
      Math.max(0.1, filterResonance),
    ) as {
      toJs: (opts: { array_buffer_type: 'float32' }) => Float32Array;
      destroy: () => void;
    };
    const float = pyodideSamplesToFloat32(pyProxy);
    if (!float) return null;
    const buf = context.createBuffer(1, float.length, context.sampleRate);
    buf.getChannelData(0).set(float);
    return buf;
  } catch {
    return null;
  }
}

/** Pre-render C4 loop buffers for live VoiceManager playback. */
export async function prerenderPyodideBuffers(
  pyodide: PyodideLike,
  context: BaseAudioContext,
): Promise<Partial<Record<WaveShape, AudioBuffer | null>>> {
  const shapes: WaveShape[] = ['saw', 'sqr', 'sin'];
  const out: Partial<Record<WaveShape, AudioBuffer | null>> = {};
  for (const shape of shapes) {
    out[shape] = generatePyodideLoopBuffer(pyodide, context, shape);
  }
  return out;
}

export const PYODIDE_REF_FREQ = REF_FREQ;

// @mode: typescript
// @note-for-ai: Audio rendering utilities with hybrid engine support.
// Already uses WebGPU/WASM/Pyodide engines when available.
// The skipFilter logic prevents double-filtering when WASM/Pyodide handle it.
// See engines directory for the actual performance-critical implementations.

import type { SynthParams, KickParams, SnareParams, HatParams } from '@/types';
import { getTunedFrequency, type ScaleDefinition } from '@/utils/musicTheory';
import type { PyodideLike } from '@/utils/pyodideBuffers';
import { resolveExportSampleRate } from '@/utils/audioContextPolicy';

type PyodideResultProxy = {
    toJs: (opts: { array_buffer_type: 'float32' }) => Float32Array;
    destroy: () => void;
};

interface WebGpuEngineLike {
    isSupported: boolean;
    generate(
        freq: number,
        dur: number,
        rate: number,
        type: 'saw' | 'sqr' | 'tri' | 'sin',
    ): Float32Array | null | Promise<Float32Array | null>;
}

interface WasmEngineLike {
    isReady: boolean;
    generate(
        freq: number,
        dur: number,
        rate: number,
        type: 'saw' | 'sqr' | 'tri' | 'sin',
        cutoff: number,
        resonance: number,
    ): Float32Array | null;
}

interface RenderSynthEngines {
    webGpuEngine?: WebGpuEngineLike | null;
    wasmEngine?: WasmEngineLike | null;
    pyodide?: PyodideLike | null;
}

export type { RenderSynthEngines, WebGpuEngineLike, WasmEngineLike };

/**
 * Renders a synth sound to an AudioBuffer.
 * Useful for exporting to XM samples.
 *
 * `sampleRate` defaults to whatever the user sample-rate policy resolves to
 * (#1233) rather than a hardcoded 44.1 kHz — a one-shot baked for XM should be
 * recorded at the rate the voice is auditioned at.
 */
export async function renderSynthToBuffer(
    params: SynthParams,
    note: string = 'C4',
    duration: number = 2.0,
    engines?: RenderSynthEngines,
    sampleRate: number = resolveExportSampleRate(),
): Promise<AudioBuffer> {
    const offlineCtx = new OfflineAudioContext(1, Math.ceil(sampleRate * duration), sampleRate);

    const time = 0;
    const baseFreq = getTunedFrequency(note, '12-TET', 'C'); // default for offline rendering
    // Apply pitch shift from params
    const freqWithPitch = baseFreq * Math.pow(2, params.pitch / 12);

    let sourceNode: AudioScheduledSourceNode | null = null;
    let customBuffer: AudioBuffer | null = null;
    let skipFilter = false; // Engines like Wasm might apply filter internally

    // Check for Custom Engines first
    if (params.waveform.startsWith('wgsl-') && engines?.webGpuEngine?.isSupported) {
        // WebGPU
        try {
            const type = params.waveform.split('-')[1] as 'saw' | 'sqr' | 'tri' | 'sin';
            const rawData = await engines.webGpuEngine.generate(
                freqWithPitch,
                duration,
                sampleRate,
                type
            );
            if (rawData) {
                customBuffer = offlineCtx.createBuffer(1, rawData.length, sampleRate);
                customBuffer.getChannelData(0).set(rawData);
            }
        } catch(e) { console.error("WebGPU Export Error", e); }
    }
    else if (params.waveform.startsWith('wam-') && engines?.wasmEngine?.isReady) {
        // WASM
        try {
            const type = params.waveform.split('-')[1] as 'saw' | 'sqr' | 'tri' | 'sin';
            const rawData = engines.wasmEngine.generate(
                freqWithPitch,
                duration,
                sampleRate,
                type,
                params.filterCutoff,
                params.filterResonance
            );
            if (rawData) {
                customBuffer = offlineCtx.createBuffer(1, rawData.length, sampleRate);
                customBuffer.getChannelData(0).set(rawData);
                skipFilter = true; // WASM engine applies filter
            }
        } catch(e) { console.error("WASM Export Error", e); }
    }
    else if (params.waveform.startsWith('pyodide-') && engines?.pyodide) {
        // Pyodide
        try {
            engines.pyodide.globals.get('set_sample_rate')(sampleRate);
            const pyOscType = params.waveform.split('-')[1];
            const pyProxy = engines.pyodide.globals.get('generate_wave')(
                freqWithPitch,
                duration,
                pyOscType,
                params.filterCutoff,
                params.filterResonance
            ) as PyodideResultProxy;
            const audioSamples = pyProxy.toJs({ array_buffer_type: "float32" });
            pyProxy.destroy();

            if (audioSamples) {
                customBuffer = offlineCtx.createBuffer(1, audioSamples.length, sampleRate);
                customBuffer.getChannelData(0).set(audioSamples);
                skipFilter = true; // Pyodide engine applies filter
            }
        } catch(e) { console.error("Pyodide Export Error", e); }
    }

    if (customBuffer) {
        const bufferSource = offlineCtx.createBufferSource();
        bufferSource.buffer = customBuffer;
        sourceNode = bufferSource;
    }
    // Handle Sample-Based Waveforms
    else if (params.waveform === 'wav-saw' || params.waveform === 'wav-sqr') {
        const bufferSource = offlineCtx.createBufferSource();
        const url = params.waveform === 'wav-saw' ? './assets/saw.wav' : './assets/square.wav';
        const rootFreq = params.waveform === 'wav-saw' ? 32.86 : 65.72;

        try {
            const response = await fetch(url);
            const arrayBuffer = await response.arrayBuffer();
            const audioBuffer = await offlineCtx.decodeAudioData(arrayBuffer);

            bufferSource.buffer = audioBuffer;
            bufferSource.loop = true;

            // Calculate playback rate
            const playbackRate = freqWithPitch / rootFreq;
            bufferSource.playbackRate.setValueAtTime(playbackRate, time);

            sourceNode = bufferSource;
        } catch (e) {
            console.error(`Failed to load wav buffer for ${params.waveform}`, e);
            // Fallback
            const osc = offlineCtx.createOscillator();
            osc.type = params.waveform === 'wav-saw' ? 'sawtooth' : 'square';
            osc.frequency.setValueAtTime(freqWithPitch, time);
            sourceNode = osc;
        }
    } else {
        // Standard Waveforms Fallback
        const osc = offlineCtx.createOscillator();
        let type: OscillatorType = 'sawtooth';
        if (params.waveform.includes('sqr')) type = 'square';
        else if (params.waveform.includes('tri')) type = 'triangle';
        else if (params.waveform.includes('sin')) type = 'sine';
        osc.type = type;
        osc.frequency.setValueAtTime(freqWithPitch, time);
        sourceNode = osc;
    }

    // Connect Graph
    // Source -> (Filter?) -> VCA -> Dest

    // Filter
    let nextNode: AudioNode = sourceNode;

    if (!skipFilter) {
        const filter = offlineCtx.createBiquadFilter();
        filter.type = 'lowpass';
        filter.frequency.setValueAtTime(params.filterCutoff, time);
        filter.Q.setValueAtTime(params.filterResonance, time);
        sourceNode.connect(filter);
        nextNode = filter;
    }

    // VCA (Envelope)
    const gain = offlineCtx.createGain();
    const attack = params.attack;
    const decay = params.decay;
    const sustain = params.sustain;
    const release = params.release;

    gain.gain.setValueAtTime(0, time);
    gain.gain.linearRampToValueAtTime(1.0, time + attack); // Normalize to 1.0 for sample
    gain.gain.linearRampToValueAtTime(sustain, time + attack + decay);
    // Hold sustain
    gain.gain.setValueAtTime(sustain, duration - release);
    gain.gain.linearRampToValueAtTime(0, duration);

    nextNode.connect(gain);
    gain.connect(offlineCtx.destination);

    sourceNode.start(time);
    // For buffer sources we don't strictly need stop if buffer matches duration, but safe practice
    if (sourceNode instanceof OscillatorNode) {
        sourceNode.stop(time + duration);
    } else if (customBuffer) {
        // Stop is implied by buffer length usually, but just in case
    }

    return await offlineCtx.startRendering();
}

/**
 * Renders a drum sound to an AudioBuffer.
 */
export async function renderDrumToBuffer(
    sound: 'kick' | 'snare' | 'closedHat' | 'openHat',
    params: KickParams | SnareParams | HatParams,
    pyodide?: PyodideLike | null,
    sampleRate: number = resolveExportSampleRate(),
): Promise<AudioBuffer> {
    // Estimate duration based on params or defaults
    let duration = sound === 'snare' ? 0.5 : (sound === 'kick' ? 0.5 : 0.3);

    // If we have decay param, use it to ensure buffer is long enough
    if (params.decay) {
        duration = Math.max(duration, params.decay * (sound === 'snare' ? 1.5 : 1.2));
    }

    // Try Pyodide Generation first
    if (pyodide) {
        try {
            let pyProxy: PyodideResultProxy;
            if (sound === 'kick') {
                const p = params as KickParams;
                pyProxy = pyodide.globals.get('generate_kick')(p.pitch, p.decay, p.tone, p.volume) as PyodideResultProxy;
            } else if (sound === 'snare') {
                const p = params as SnareParams;
                pyProxy = pyodide.globals.get('generate_snare')(p.decay, p.tone, p.noise, p.volume) as PyodideResultProxy;
            } else {
                const p = params as HatParams;
                pyProxy = pyodide.globals.get('generate_hat')(p.pitch, p.decay, p.volume) as PyodideResultProxy;
            }

            const audioSamples = pyProxy.toJs({ array_buffer_type: "float32" });
            pyProxy.destroy();

            if (audioSamples && audioSamples.length > 0) {
                 // Return directly (Offline context not strictly needed if we just want the buffer,
                 // but existing code returns Promise<AudioBuffer>)
                 // We can construct an AudioBuffer from the float array.
                 // We need an AudioContext to createBuffer. Since we are in browser, we can use offline one or main one.
                 // Let's use OfflineAudioContext just to create the buffer object cleanly.
                 const ctx = new OfflineAudioContext(1, audioSamples.length, sampleRate);
                 const buffer = ctx.createBuffer(1, audioSamples.length, sampleRate);
                 buffer.getChannelData(0).set(audioSamples);
                 return buffer;
            }
        } catch (e) {
            console.error(`Pyodide drum export error (${sound}):`, e);
            // Fallthrough to approximation
        }
    }

    // Fallback Approximation (Existing Code)
    const offlineCtx = new OfflineAudioContext(1, Math.ceil(sampleRate * duration), sampleRate);
    const time = 0;

    const gain = offlineCtx.createGain();
    gain.connect(offlineCtx.destination);

    if (sound === 'kick') {
        const p = params as KickParams;
        const osc = offlineCtx.createOscillator();
        // Use params.pitch if available (KickParams has pitch)
        osc.frequency.setValueAtTime(p.pitch, time);
        osc.frequency.exponentialRampToValueAtTime(0.01, time + p.decay);

        const env = offlineCtx.createGain();
        env.gain.setValueAtTime(p.volume, time);
        env.gain.exponentialRampToValueAtTime(0.01, time + p.decay);

        osc.connect(env);
        env.connect(gain);
        osc.start(time);
        osc.stop(time + p.decay);
    }
    else if (sound === 'snare') {
        const p = params as SnareParams;
        // Noise
        const bufferSize = sampleRate * duration;
        const buffer = offlineCtx.createBuffer(1, bufferSize, sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        const noiseSrc = offlineCtx.createBufferSource();
        noiseSrc.buffer = buffer;

        const noiseEnv = offlineCtx.createGain();
        // Mix noise based on p.noise
        const noiseMix = Math.min(1, Math.max(0, (p.noise - 1000) / 7000));

        noiseEnv.gain.setValueAtTime(p.volume * noiseMix, time);
        noiseEnv.gain.exponentialRampToValueAtTime(0.01, time + p.decay);

        // Tone
        const osc = offlineCtx.createOscillator();
        osc.type = 'triangle';
        // Use p.tone for frequency
        osc.frequency.setValueAtTime(p.tone, time);

        const toneEnv = offlineCtx.createGain();
        // Tone volume inverse to noise? Or independent?
        toneEnv.gain.setValueAtTime(p.volume * (1 - noiseMix * 0.5), time);
        toneEnv.gain.exponentialRampToValueAtTime(0.01, time + p.decay * 0.5);

        noiseSrc.connect(noiseEnv);
        noiseEnv.connect(gain);

        osc.connect(toneEnv);
        toneEnv.connect(gain);

        noiseSrc.start(time);
        osc.start(time);
    }
    else {
        // Hats
        const p = params as HatParams;
         // Noise
        const bufferSize = sampleRate * duration;
        const buffer = offlineCtx.createBuffer(1, bufferSize, sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        const noiseSrc = offlineCtx.createBufferSource();
        noiseSrc.buffer = buffer;

        // Highpass
        const filter = offlineCtx.createBiquadFilter();
        filter.type = 'highpass';
        filter.frequency.value = Math.max(1000, 8000 + (p.pitch || 0));

        const env = offlineCtx.createGain();
        env.gain.setValueAtTime(p.volume, time);
        env.gain.exponentialRampToValueAtTime(0.01, time + p.decay);

        noiseSrc.connect(filter);
        filter.connect(env);
        env.connect(gain);

        noiseSrc.start(time);
    }

    return await offlineCtx.startRendering();
}

import type { TrackKey } from '../constants/appDefaults';
import { TRACK_KEYS } from '../constants';
import { MAX_TRACK_PATTERN_SLOT_INDEX } from './trackStorageUtils';
import type { SongCellCoord, SongMeasure, SongSegmentClipboard, SongStructure, SongModeTrackKey } from '../types/songMode';

export const SONG_MODE_TRACKS: { key: SongModeTrackKey; label: string; color: string }[] = [
    { key: 'partA', label: 'LEAD', color: '#06b6d4' },
    { key: 'partB', label: 'BASS', color: '#d946ef' },
    { key: 'bass2', label: 'BASS2', color: '#ff0066' },
    { key: 'kick', label: 'KICK', color: '#f97316' },
    { key: 'snare', label: 'SNARE', color: '#22c55e' },
    { key: 'closedHat', label: 'CH', color: '#eab308' },
    { key: 'openHat', label: 'OH', color: '#eab308' },
    { key: 'sampler', label: 'SMP', color: '#a855f7' },
];

export function cellId(measure: number, track: SongModeTrackKey): string {
    return `${track}@${measure}`;
}

export function parseCellId(id: string): SongCellCoord | null {
    const at = id.indexOf('@');
    if (at <= 0) return null;
    const track = id.slice(0, at) as SongModeTrackKey;
    const measure = Number(id.slice(at + 1));
    if (!Number.isFinite(measure)) return null;
    return { track, measure };
}

export function createEmptyMeasure(): SongMeasure {
    const row = {} as SongMeasure;
    for (const key of TRACK_KEYS) {
        row[key] = null;
    }
    return row;
}

export function cloneStructure(structure: SongStructure): SongStructure {
    return structure.map((m) => ({ ...m }));
}

export function clampSlot(value: number | null): number | null {
    if (value === null) return null;
    if (value < 0) return null;
    return Math.min(MAX_TRACK_PATTERN_SLOT_INDEX, Math.max(0, value));
}

export function cycleSlot(value: number | null, delta: number): number | null {
    if (value === null) return delta > 0 ? 0 : null;
    const next = value + delta;
    if (next < 0) return null;
    if (next > MAX_TRACK_PATTERN_SLOT_INDEX) return MAX_TRACK_PATTERN_SLOT_INDEX;
    return next;
}

/** Contiguous run of the same pattern slot on one track (for repeat badges). */
export function getPatternRun(
    structure: SongStructure,
    measure: number,
    track: SongModeTrackKey,
): { start: number; length: number; value: number } | null {
    const val = structure[measure]?.[track] ?? null;
    if (val === null) return null;
    let start = measure;
    while (start > 0 && structure[start - 1]?.[track] === val) start--;
    let end = measure;
    while (end < structure.length - 1 && structure[end + 1]?.[track] === val) end++;
    return { start, length: end - start + 1, value: val };
}

export function selectSingle(coord: SongCellCoord): Set<string> {
    return new Set([cellId(coord.measure, coord.track)]);
}

export function toggleCellSelection(selection: Set<string>, coord: SongCellCoord): Set<string> {
    const id = cellId(coord.measure, coord.track);
    const next = new Set(selection);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    return next;
}

/** Range on one track between anchor and target (inclusive). */
export function selectTrackRange(anchor: SongCellCoord, target: SongCellCoord): Set<string> {
    if (anchor.track !== target.track) return selectSingle(target);
    const lo = Math.min(anchor.measure, target.measure);
    const hi = Math.max(anchor.measure, target.measure);
    const next = new Set<string>();
    for (let m = lo; m <= hi; m++) next.add(cellId(m, anchor.track));
    return next;
}

/** All tracks across a measure range (column selection). */
export function selectMeasureColumns(anchorMeasure: number, targetMeasure: number): Set<string> {
    const lo = Math.min(anchorMeasure, targetMeasure);
    const hi = Math.max(anchorMeasure, targetMeasure);
    const next = new Set<string>();
    for (let m = lo; m <= hi; m++) {
        for (const { key } of SONG_MODE_TRACKS) next.add(cellId(m, key));
    }
    return next;
}

/** Rectangle selection in measure × track space. */
export function selectRectangle(anchor: SongCellCoord, target: SongCellCoord): Set<string> {
    const trackOrder = SONG_MODE_TRACKS.map((r) => r.key);
    const aTrack = trackOrder.indexOf(anchor.track);
    const bTrack = trackOrder.indexOf(target.track);
    const loM = Math.min(anchor.measure, target.measure);
    const hiM = Math.max(anchor.measure, target.measure);
    const loT = Math.min(aTrack, bTrack);
    const hiT = Math.max(aTrack, bTrack);
    const next = new Set<string>();
    for (let m = loM; m <= hiM; m++) {
        for (let t = loT; t <= hiT; t++) next.add(cellId(m, trackOrder[t]));
    }
    return next;
}

export function applyToSelection(
    structure: SongStructure,
    selection: Set<string>,
    updater: (value: number | null, coord: SongCellCoord) => number | null,
): SongStructure {
    if (selection.size === 0) return structure;
    const next = cloneStructure(structure);
    for (const id of selection) {
        const coord = parseCellId(id);
        if (!coord || !next[coord.measure]) continue;
        const current = next[coord.measure][coord.track] ?? null;
        next[coord.measure] = {
            ...next[coord.measure],
            [coord.track]: clampSlot(updater(current, coord)),
        };
    }
    return next;
}

export function bulkSetPattern(structure: SongStructure, selection: Set<string>, slot: number | null): SongStructure {
    return applyToSelection(structure, selection, () => clampSlot(slot));
}

export function bulkClear(structure: SongStructure, selection: Set<string>): SongStructure {
    return bulkSetPattern(structure, selection, null);
}

export function bulkCycle(structure: SongStructure, selection: Set<string>, delta: number): SongStructure {
    return applyToSelection(structure, selection, (v) => cycleSlot(v, delta));
}

export function swapCells(structure: SongStructure, a: SongCellCoord, b: SongCellCoord): SongStructure {
    if (a.measure === b.measure && a.track === b.track) return structure;
    const next = cloneStructure(structure);
    const va = next[a.measure]?.[a.track] ?? null;
    const vb = next[b.measure]?.[b.track] ?? null;
    next[a.measure] = { ...next[a.measure], [a.track]: vb };
    next[b.measure] = { ...next[b.measure], [b.track]: va };
    return next;
}

export function moveCellValue(structure: SongStructure, from: SongCellCoord, to: SongCellCoord): SongStructure {
    if (from.measure === to.measure && from.track === to.track) return structure;
    const next = cloneStructure(structure);
    const val = next[from.measure]?.[from.track] ?? null;
    next[from.measure] = { ...next[from.measure], [from.track]: null };
    next[to.measure] = { ...next[to.measure], [to.track]: val };
    return next;
}

export function insertMeasure(structure: SongStructure, index: number, template?: SongMeasure): SongStructure {
    const row = template ? { ...template } : createEmptyMeasure();
    const i = Math.max(0, Math.min(structure.length, index));
    return [...structure.slice(0, i), row, ...structure.slice(i)];
}

export function duplicateMeasure(structure: SongStructure, index: number): SongStructure {
    if (index < 0 || index >= structure.length) return structure;
    return insertMeasure(structure, index + 1, { ...structure[index] });
}

export function removeMeasureAt(structure: SongStructure, index: number): SongStructure {
    if (structure.length <= 1) return structure;
    if (index < 0 || index >= structure.length) return structure;
    return structure.filter((_, i) => i !== index);
}

/** Duplicate one track's pattern across the next measure (row-aware extend). */
export function duplicateTrackMeasure(
    structure: SongStructure,
    measureIndex: number,
    track: SongModeTrackKey,
): SongStructure {
    if (measureIndex < 0 || measureIndex >= structure.length) return structure;
    const val = structure[measureIndex][track];
    const insertAt = measureIndex + 1;
    const next = insertMeasure(structure, insertAt);
    next[insertAt] = { ...next[insertAt], [track]: val };
    return next;
}

export function copySegment(structure: SongStructure, selection: Set<string>): SongSegmentClipboard | null {
    if (selection.size === 0) return null;
    const coords = [...selection].map((id) => parseCellId(id)).filter(Boolean) as SongCellCoord[];
    if (coords.length === 0) return null;

    // ⚡ Bolt: Use a single pass loop instead of spreading .map() arrays to prevent call stack exceeded errors and array allocations
    const trackOrder = SONG_MODE_TRACKS.map((r) => r.key);
    let minM = Infinity;
    let maxM = -Infinity;
    let minT = Infinity;
    let maxT = -Infinity;

    for (let i = 0; i < coords.length; i++) {
        const c = coords[i];
        if (c.measure < minM) minM = c.measure;
        if (c.measure > maxM) maxM = c.measure;

        const tIdx = trackOrder.indexOf(c.track);
        if (tIdx < minT) minT = tIdx;
        if (tIdx > maxT) maxT = tIdx;
    }

    const cells = coords.map((c) => ({
        dMeasure: c.measure - minM,
        track: c.track,
        value: structure[c.measure]?.[c.track] ?? null,
    }));
    return { cells, width: maxM - minM + 1, height: maxT - minT + 1 };
}

export function pasteSegment(
    structure: SongStructure,
    clipboard: SongSegmentClipboard,
    anchor: SongCellCoord,
): SongStructure {
    let next = cloneStructure(structure);
    const neededMeasures = anchor.measure + clipboard.width;
    while (next.length < neededMeasures) {
        next = [...next, createEmptyMeasure()];
    }
    for (const cell of clipboard.cells) {
        const m = anchor.measure + cell.dMeasure;
        if (m < 0 || m >= next.length) continue;
        next[m] = { ...next[m], [cell.track]: clampSlot(cell.value) };
    }
    return next;
}

export function updateCell(
    structure: SongStructure,
    measure: number,
    track: SongModeTrackKey,
    value: number | null,
): SongStructure {
    if (measure < 0 || measure >= structure.length) return structure;
    const next = cloneStructure(structure);
    next[measure] = { ...next[measure], [track]: clampSlot(value) };
    return next;
}

/** Ensure every measure row includes all track keys (RBS / legacy roundtrip). */
export function normalizeSongStructure(structure: SongStructure): SongStructure {
    return structure.map((row) => {
        const normalized = createEmptyMeasure();
        for (const key of TRACK_KEYS) {
            normalized[key] = row[key] ?? null;
        }
        return normalized;
    });
}

export function isEmptySong(structure: SongStructure): boolean {
    return structure.every((m) => TRACK_KEYS.every((k) => m[k] === null));
}

import { NUM_STEPS } from '@/constants';
import type { Pattern, PartSequence } from '@/types';
import type { TrackKey } from '@/constants/appDefaults';

export interface ResolvedTimeline {
    /** Number of 32-step measures in the export. */
    measureCount: number;
    /** Total step count (measureCount * NUM_STEPS). */
    totalSteps: number;
    /** Per-track concatenated step sequences across all measures. */
    sequences: Record<Exclude<TrackKey, 'sampler'>, PartSequence> & {
        sampler: PartSequence[];
    };
}

function emptyPartSequence(): PartSequence {
    return { steps: Array.from({ length: NUM_STEPS }, (): null => null) };
}

function concatPartSequences(parts: PartSequence[]): PartSequence {
    const steps = parts.flatMap((p) => p?.steps ?? Array(NUM_STEPS).fill(null));
    return { steps };
}

function resolveMeasureSequence(
    trackKey: TrackKey,
    measure: { [key in TrackKey]: number | null },
    trackStorage: Record<TrackKey, (PartSequence | PartSequence[] | null)[]>,
    fallbackPattern: Pattern,
): PartSequence | PartSequence[] | null {
    const slotIndex = measure[trackKey];
    if (slotIndex !== null) {
        const stored = trackStorage[trackKey]?.[slotIndex];
        if (stored) return stored;
    }
    return fallbackPattern[trackKey] ?? null;
}

/**
 * Resolves the full timeline for stem export from song arrangement or current pattern.
 */
export function resolveSongTimeline(
    songStructure: { [key in TrackKey]: number | null }[],
    trackStorage: Record<TrackKey, (PartSequence | PartSequence[] | null)[]>,
    currentPattern: Pattern,
    useSongMode: boolean,
): ResolvedTimeline {
    const synthTracks = ['partA', 'partB', 'bass2', 'kick', 'snare', 'closedHat', 'openHat'] as const;

    let lastActiveMeasure = -1;
    if (useSongMode) {
        for (let i = songStructure.length - 1; i >= 0; i--) {
            const measure = songStructure[i];
            if (Object.values(measure).some((slot) => slot !== null)) {
                lastActiveMeasure = i;
                break;
            }
        }
    }

    const useFallbackPattern = !useSongMode || lastActiveMeasure === -1;
    const measureCount = useFallbackPattern ? 1 : Math.max(1, lastActiveMeasure + 1);

    const sequences = {
        partA: [] as PartSequence[],
        partB: [] as PartSequence[],
        bass2: [] as PartSequence[],
        kick: [] as PartSequence[],
        snare: [] as PartSequence[],
        closedHat: [] as PartSequence[],
        openHat: [] as PartSequence[],
        sampler: Array.from({ length: 8 }, () => [] as PartSequence[]),
    };

    for (let m = 0; m < measureCount; m++) {
        const measure = useFallbackPattern
            ? ({} as { [key in TrackKey]: number | null })
            : songStructure[m];

        for (const trackKey of synthTracks) {
            const resolved = resolveMeasureSequence(trackKey, measure, trackStorage, currentPattern);
            if (resolved) {
                sequences[trackKey].push(resolved as PartSequence);
            } else {
                sequences[trackKey].push(emptyPartSequence());
            }
        }

        const samplerResolved = resolveMeasureSequence('sampler', measure, trackStorage, currentPattern);
        if (samplerResolved && Array.isArray(samplerResolved)) {
            const banks = samplerResolved as PartSequence[];
            for (let b = 0; b < 8; b++) {
                sequences.sampler[b].push(banks[b] ?? emptyPartSequence());
            }
        } else {
            const banks = currentPattern.sampler;
            for (let b = 0; b < 8; b++) {
                sequences.sampler[b].push(banks[b] ?? emptyPartSequence());
            }
        }
    }

    return {
        measureCount,
        totalSteps: measureCount * NUM_STEPS,
        sequences: {
            partA: concatPartSequences(sequences.partA),
            partB: concatPartSequences(sequences.partB),
            bass2: concatPartSequences(sequences.bass2),
            kick: concatPartSequences(sequences.kick),
            snare: concatPartSequences(sequences.snare),
            closedHat: concatPartSequences(sequences.closedHat),
            openHat: concatPartSequences(sequences.openHat),
            sampler: sequences.sampler.map((bankParts) => concatPartSequences(bankParts)),
        },
    };
}

export function stepDurationSeconds(tempo: number): number {
    return 60 / tempo / 4;
}

export function timelineDurationSeconds(totalSteps: number, tempo: number): number {
    return totalSteps * stepDurationSeconds(tempo);
}

/**
 * Track Freezer Utility
 * Renders complex synth/drum patterns to simple audio buffers for CPU savings
 */
// @mode: bridge
// @migrate-target: assemblyscript
// @perf-bottleneck: Loop analysis in findLoopPoints scans entire buffer
// @future-plan: Move findLoopPoints and audioBufferToMono to WASM for large buffer processing

import type { PartSequence, SynthParams, KickParams, SnareParams, HatParams } from '@/types';
// @ts-ignore
const initTrackFreezer = async () => {
    const m = await import('../wasm/trackFreezer.wasm?init');
    return m.default;
};
import { engineTelemetry } from '@/utils/engineTelemetry';
import type { PyodideLike } from '@/utils/pyodideBuffers';
import { resolveExportSampleRate, type SampleRatePref } from '@/utils/audioContextPolicy';
import {
    renderThroughOfflineGraph,
    type CompiledOfflineGraph,
    type OfflineGraphRenderResult,
} from '@/audio/offline/compileOfflineGraph';

// WASM Module Loader
interface WasmExports {
    memory: WebAssembly.Memory;
    findLoopPoints: (bufferPtr: number, length: number, minLoopLength: number) => bigint;
    mixToMono: (leftPtr: number, rightPtr: number, outputPtr: number, length: number) => void;
    __new: (size: number, classId: number) => number;
    __pin: (ptr: number) => number;
    __unpin: (ptr: number) => void;
    __collect: () => void;
}

let wasmInstance: WasmExports | null = null;

// Allow external injection for testing
export const setWasmInstance = (instance: WasmExports) => {
    wasmInstance = instance;
};

const loadWasm = async () => {
    if (wasmInstance) return;
    try {
        const initFn = await initTrackFreezer();
        const instance = await initFn({
            env: {
                abort: () => console.error("WASM Abort")
            }
        });
        wasmInstance = instance.exports as unknown as WasmExports;
        try { engineTelemetry.registerResolution('trackFreezer','wasm','loaded'); } catch (e) { /* noop */ }
    } catch (e) {
        try { engineTelemetry.registerResolution('trackFreezer','js','failed to load wasm: ' + String(e)); } catch (err) { /* noop */ }
        console.warn("Failed to load trackFreezer.wasm, using JS fallback", e);
    }
};

// Initialize WASM in background
if (typeof window !== 'undefined') {
    void loadWasm();
}

export interface FreezeOptions {
    bpm: number;
    /** Defaults to the user sample-rate policy (#1136 / #1233). */
    sampleRate?: number;
    /** Policy to resolve when `sampleRate` is omitted. */
    sampleRatePref?: SampleRatePref;
    /** `AudioContext.sampleRate` of the running engine, for the `native` pref. */
    liveSampleRate?: number | null;
}

/** Rate a freeze renders at: explicit, else the live policy. */
function freezeSampleRate(options: FreezeOptions): number {
    return options.sampleRate ?? resolveExportSampleRate(options.sampleRatePref, options.liveSampleRate);
}

type PyodideResultProxy = {
    toJs: (opts: { array_buffer_type: 'float32' }) => Float32Array;
    destroy: () => void;
};

function callPyodideFreeze(
    pyodide: PyodideLike,
    functionName: string,
    ...args: unknown[]
): Float32Array {
    const freezeFunc = pyodide.globals.get(functionName);
    const pyResult = freezeFunc(...args) as PyodideResultProxy;
    const audioData = pyResult.toJs({ array_buffer_type: 'float32' });
    pyResult.destroy();
    return audioData;
}

/**
 * Freezes a synth track using Python's offline rendering
 */
export const freezeSynthTrack = async (
    pyodide: PyodideLike,
    sequence: PartSequence,
    params: SynthParams,
    options: FreezeOptions
): Promise<AudioBuffer> => {
    if (!pyodide) throw new Error('Pyodide not initialized');

    const sampleRate = freezeSampleRate(options);

    // Prepare params for Python
    const pythonParams = {
        bpm: options.bpm,
        waveform: params.waveform,
        filterCutoff: params.filterCutoff,
        filterResonance: params.filterResonance,
        attack: params.attack,
        decay: params.decay,
        sustain: params.sustain,
        release: params.release,
        volume: params.volume,
    };

    // Call Python freezer
    const audioData = callPyodideFreeze(
        pyodide,
        'freeze_synth_track',
        JSON.stringify(sequence.steps),
        JSON.stringify(pythonParams),
    );

    // Create AudioBuffer from result
    const audioContext = new OfflineAudioContext(1, audioData.length, sampleRate);
    const buffer = audioContext.createBuffer(1, audioData.length, sampleRate);
    buffer.getChannelData(0).set(audioData);

    return buffer;
};

/**
 * Freezes a drum track using Python's offline rendering
 */
export const freezeDrumTrack = async (
    pyodide: PyodideLike,
    sequence: PartSequence,
    params: KickParams | SnareParams | HatParams,
    drumType: 'kick' | 'snare' | 'closedHat' | 'openHat',
    options: FreezeOptions
): Promise<AudioBuffer> => {
    if (!pyodide) throw new Error('Pyodide not initialized');

    const sampleRate = freezeSampleRate(options);

    // Map drum type to simpler Python type
    const pyDrumType = drumType === 'kick' ? 'kick' :
        drumType === 'snare' ? 'snare' : 'hat';

    // Prepare params for Python
    const pythonParams = {
        bpm: options.bpm,
        ...params
    };

    // Call Python freezer
    const audioData = callPyodideFreeze(
        pyodide,
        'freeze_drum_track',
        JSON.stringify(sequence.steps),
        JSON.stringify(pythonParams),
        pyDrumType,
    );

    // Create AudioBuffer from result
    const audioContext = new OfflineAudioContext(1, audioData.length, sampleRate);
    const buffer = audioContext.createBuffer(1, audioData.length, sampleRate);
    buffer.getChannelData(0).set(audioData);

    return buffer;
};

/**
 * Freezes a track using Web Audio's OfflineAudioContext.
 *
 * Bare context: the caller owns the whole graph, so nothing of the live patch
 * is applied. Use {@link freezeThroughPatch} when the freeze has to sound like
 * what the user is monitoring.
 */
export const freezeWithOfflineContext = async (
    setupCallback: (ctx: OfflineAudioContext) => void,
    durationSeconds: number,
    sampleRate: number = resolveExportSampleRate(),
): Promise<AudioBuffer> => {
    const lengthSamples = Math.ceil(durationSeconds * sampleRate);
    const offlineCtx = new OfflineAudioContext(2, lengthSamples, sampleRate);

    // Let user build their audio graph
    setupCallback(offlineCtx);

    // Render
    console.log('Rendering audio offline...');
    const renderedBuffer = await offlineCtx.startRendering();
    console.log('Render complete:', renderedBuffer.duration, 'seconds');

    return renderedBuffer;
};

export interface FreezeThroughPatchOptions extends Omit<FreezeOptions, 'bpm'> {
    durationSeconds: number;
    /** Schedule the sources; `input` is the live patch's master FX entry. */
    schedule: (compiled: CompiledOfflineGraph) => void | Promise<void>;
}

/**
 * Freeze a track through the live patch bay (#1233).
 *
 * This is the freeze consumer of `compileOfflineGraph`: the same compiler,
 * patch, sample-rate policy and master loudness stage the stem export and the
 * AI preview use, so a frozen track and a bounced stem cannot drift apart. The
 * returned report says which WAM2 inserts were rendered and which were bypassed
 * as offline-unsupported.
 */
export const freezeThroughPatch = async (
    options: FreezeThroughPatchOptions,
): Promise<OfflineGraphRenderResult> => {
    const { durationSeconds, schedule, ...freezeOptions } = options;
    return renderThroughOfflineGraph({
        durationSeconds,
        schedule,
        sampleRate: freezeOptions.sampleRate,
        sampleRatePref: freezeOptions.sampleRatePref,
        liveSampleRate: freezeOptions.liveSampleRate ?? null,
    });
};

/**
 * Converts an AudioBuffer to mono Float32Array (for loading into SustainProcessor)
 */
export const audioBufferToMono = (buffer: AudioBuffer): Float32Array => {
    if (buffer.numberOfChannels === 1) {
        return buffer.getChannelData(0);
    }

    // Attempt WASM optimization (Only supports standard Stereo -> Mono mix)
    if (wasmInstance && buffer.numberOfChannels === 2) {
        let leftPtr = 0;
        let rightPtr = 0;
        let outPtr = 0;

        try {
            const length = buffer.length;
            const leftData = buffer.getChannelData(0);
            const rightData = buffer.getChannelData(1);

            // Allocate and Pin to prevent GC during subsequent allocations
            leftPtr = wasmInstance.__new(length * 4, 0);
            wasmInstance.__pin(leftPtr);

            rightPtr = wasmInstance.__new(length * 4, 0);
            wasmInstance.__pin(rightPtr);

            outPtr = wasmInstance.__new(length * 4, 0);
            wasmInstance.__pin(outPtr);

            // Copy data to WASM
            const wasmMemoryBuffer = wasmInstance.memory.buffer;
            new Float32Array(wasmMemoryBuffer, leftPtr, length).set(leftData);
            new Float32Array(wasmMemoryBuffer, rightPtr, length).set(rightData);

            // Exec
            wasmInstance.mixToMono(leftPtr, rightPtr, outPtr, length);

            // Copy back
            const result = new Float32Array(length);
            result.set(new Float32Array(wasmMemoryBuffer, outPtr, length));

            return result;
        } catch (e) {
            console.warn("WASM audioBufferToMono failed, falling back to JS", e);
            // Fallthrough to JS
        } finally {
            // Clean up memory
            if (leftPtr) wasmInstance.__unpin(leftPtr);
            if (rightPtr) wasmInstance.__unpin(rightPtr);
            if (outPtr) wasmInstance.__unpin(outPtr);
        }
    }

    // Mix down to mono (JS Fallback)
    const mono = new Float32Array(buffer.length);
    const numChannels = buffer.numberOfChannels;

    for (let ch = 0; ch < numChannels; ch++) {
        const channelData = buffer.getChannelData(ch);
        for (let i = 0; i < buffer.length; i++) {
            mono[i] += channelData[i] / numChannels;
        }
    }

    return mono;
};

/**
 * Finds optimal loop points in an audio buffer
 * Uses zero-crossing detection for clean loops
 */
export const findLoopPoints = (
    buffer: Float32Array,
    minLoopLength: number = 4410 // ~100ms at 44.1kHz
): { start: number, end: number } => {
    // Attempt WASM optimization
    if (wasmInstance) {
        let bufferPtr = 0;
        try {
            const length = buffer.length;

            // Allocate & Pin
            bufferPtr = wasmInstance.__new(length * 4, 0);
            wasmInstance.__pin(bufferPtr);

            // Copy
            new Float32Array(wasmInstance.memory.buffer, bufferPtr, length).set(buffer);

            // Exec
            const packedResult = wasmInstance.findLoopPoints(bufferPtr, length, minLoopLength);

            // Unpack u64
            const start = Number((packedResult >> 32n) & 0xFFFFFFFFn);
            const end = Number(packedResult & 0xFFFFFFFFn);

            return { start, end };
        } catch (e) {
            console.warn("WASM findLoopPoints failed, falling back to JS", e);
        } finally {
            // Clean up
            if (bufferPtr) wasmInstance.__unpin(bufferPtr);
        }
    }

    /* --- OLD LOGIC (PRESERVED / ACTIVE FALLBACK) --- */
    const length = buffer.length;

    // Find a zero-crossing near the start (after ~10ms to avoid attack transient)
    const searchStart = Math.min(441, length - minLoopLength); // 10ms at 44.1kHz
    let loopStart = searchStart;

    for (let i = searchStart; i < length / 2; i++) {
        if (buffer[i] >= 0 && buffer[i - 1] < 0) {
            loopStart = i;
            break;
        }
    }

    // Find a zero-crossing near the end
    let loopEnd = length - 1;
    for (let i = length - 1; i > loopStart + minLoopLength; i--) {
        if (buffer[i] >= 0 && buffer[i - 1] < 0) {
            loopEnd = i;
            break;
        }
    }

    return { start: loopStart, end: loopEnd };
};

