    decay: number;
    sustain: number;  // 0-1 level
    release: number;  // seconds
    length: number;   // gate time in seconds
    volume: number;
    delayTime: number;
    delayFeedback: number;
    delayMix: number;
}

interface Note {
    note: string;
    velocity: number;
}

