    steps: (Note | null)[];
}

const noteFrequencies: { [key: string]: number } = {
    'C2': 65.41, 'C#2': 69.30, 'D2': 73.42, 'D#2': 77.78, 'E2': 82.41, 'F2': 87.31, 'F#2': 92.50, 'G2': 98.00, 'G#2': 103.83, 'A2': 110.00, 'A#2': 116.54, 'B2': 123.47,
    'C3': 130.81, 'C#3': 138.59, 'D3': 146.83, 'D#3': 155.56, 'E3': 164.81, 'F3': 174.61, 'F#3': 185.00, 'G3': 196.00, 'G#3': 207.65, 'A3': 220.00, 'A#3': 233.08, 'B3': 246.94,
    'C4': 261.63, 'C#4': 277.18, 'D4': 293.66, 'D#4': 311.13, 'E4': 329.63, 'F4': 349.23, 'F#4': 369.99, 'G4': 392.00, 'G#4': 415.30, 'A4': 440.00, 'A#4': 466.16, 'B4': 493.88,
    'C5': 523.25, 'C#5': 554.37, 'D5': 587.33, 'D#5': 622.25, 'E5': 659.25, 'F5': 698.46, 'F#5': 739.99, 'G5': 783.99, 'G#5': 830.61, 'A5': 880.00, 'A#5': 932.33, 'B5': 987.77,
};


const NOTES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const noteToMidi = (note: string): number => {
    if (!note) return 0;
    const match = note.match(/([A-G]#?)(\d+)/);
    if (!match) return 0;
    return (parseInt(match[2], 10) + 1) * 12 + NOTES.indexOf(match[1]);
};
const getTunedFrequency = (note: string, tuning: string = '12-TET', rootNote: string = 'C'): number => {
    if (!note) return 0;
    const midi = noteToMidi(note);
    if (tuning === '12-TET') return 440 * Math.pow(2, (midi - 69) / 12);
    if (tuning === '24-TET') return 440 * Math.pow(2, (midi - 69) / 24);
    const rootMidi = noteToMidi(rootNote.replace(/\d+$/, '') + '4');
    const rootFreq = 440 * Math.pow(2, (rootMidi - 69) / 12);
    const distance = midi - rootMidi;
    if (tuning === 'Bohlen-Pierce') return rootFreq * Math.pow(3, distance / 13);
    const octave = Math.floor(distance / 12);
    const semitone = ((distance % 12) + 12) % 12;
    if (tuning === 'Just Intonation') return rootFreq * [1/1, 16/15, 9/8, 6/5, 5/4, 4/3, 45/32, 3/2, 8/5, 5/3, 9/5, 15/8][semitone] * Math.pow(2, octave);
    if (tuning === 'Pythagorean') return rootFreq * [1/1, 256/243, 9/8, 32/27, 81/64, 4/3, 729/512, 3/2, 128/81, 27/16, 16/9, 243/128][semitone] * Math.pow(2, octave);
    return 440 * Math.pow(2, (midi - 69) / 12);
};
const playSynthForRender = (context: OfflineAudioContext, params: SynthParams, note: string, time: number, tuningSystem?: string, rootNote?: string) => {
    const destination = context.destination;
    const baseFreq = getTunedFrequency(note, tuningSystem, rootNote);
    const freqWithPitch = baseFreq * Math.pow(2, params.pitch / 12);

    // ADSR timing - use length as gate time, fallback to attack+decay if not set
    const gateTime = params.length || (params.attack + params.decay + 0.1);
    const totalDuration = gateTime + params.release;

    const osc = context.createOscillator();
    osc.type = params.waveform;
    osc.frequency.setValueAtTime(freqWithPitch, time);

    const filter = context.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(params.filterCutoff, time);
    filter.Q.setValueAtTime(params.filterResonance, time);

    // --- PROPER ADSR ENVELOPE ---
    const gain = context.createGain();
    const sustainLevel = params.volume * (params.sustain ?? 0.5);

    // Attack: 0 → volume
    gain.gain.setValueAtTime(0, time);
    gain.gain.linearRampToValueAtTime(params.volume, time + params.attack);

    // Decay: volume → sustain level
    gain.gain.linearRampToValueAtTime(sustainLevel, time + params.attack + params.decay);

    // Sustain: hold at sustain level until gate ends
    gain.gain.setValueAtTime(sustainLevel, time + gateTime);

    // Release: sustain → 0
    gain.gain.linearRampToValueAtTime(0, time + gateTime + params.release);

    osc.connect(filter);
    filter.connect(gain);

    if (params.delayMix > 0 && params.delayTime > 0) {
        const dryGain = context.createGain();
        const wetGain = context.createGain();
        const delay = context.createDelay(1.0);
        const feedback = context.createGain();

        dryGain.gain.setValueAtTime(1.0 - params.delayMix, time);
        wetGain.gain.setValueAtTime(params.delayMix, time);
        delay.delayTime.setValueAtTime(params.delayTime, time);
        feedback.gain.setValueAtTime(params.delayFeedback, time);

        gain.connect(dryGain);
        dryGain.connect(destination);

        gain.connect(delay);
        delay.connect(feedback);
        feedback.connect(delay);
        delay.connect(wetGain);
        wetGain.connect(destination);
    } else {
        gain.connect(destination);
    }

    osc.start(time);
    osc.stop(time + totalDuration + 0.05);
};

let cancelled = false;

self.onmessage = async (event: MessageEvent<{
    type?: 'render' | 'cancel';
    params?: SynthParams;
    sequence?: PartSequence;
    tempo?: number;
    sampleRate?: number;
    numSteps?: number;
    currentScale?: any;
}>) => {
    if (event.data.type === 'cancel') {
        cancelled = true;
        return;
    }

    cancelled = false;
    const { params, sequence, tempo, sampleRate, numSteps, currentScale } = event.data;
    if (!params || !sequence || tempo === undefined || sampleRate === undefined || numSteps === undefined) {
        return;
    }

    if (cancelled) {
        self.postMessage({ type: 'cancelled' });
        return;
    }

    const stepDuration = 60 / tempo / 4;
    const totalDuration = numSteps * stepDuration;
    const offlineContext = new OfflineAudioContext(2, Math.ceil(sampleRate * totalDuration), sampleRate);

    sequence.steps.forEach((note, step) => {
        if (note && !cancelled) {
            const time = step * stepDuration;
            playSynthForRender(offlineContext, params, note.note, time, currentScale?.tuningSystem || '12-TET', currentScale?.root || 'C');
        }
    });

    if (cancelled) {
        self.postMessage({ type: 'cancelled' });
        return;
    }

    const renderedBuffer = await offlineContext.startRendering();
    if (cancelled) {
        self.postMessage({ type: 'cancelled' });
        return;
    }

    self.postMessage({ type: 'complete', buffer: renderedBuffer }, {
        transfer: [renderedBuffer.getChannelData(0).buffer, renderedBuffer.getChannelData(1).buffer]
    });
};

import { expect, type Page, type Locator } from '@playwright/test';

/**
 * Shared Hyphon E2E boot helper (#1036).
 *
 * - Navigates with ?e2e=1 so window.__HYPHON_E2E__ introspection is registered.
 * - Dismisses StartOverlay via data-testid with a real click (AudioContext unlock).
 * - Waits for LoadingOverlay + transport before returning.
 * - Optionally asserts no hard AudioContext / WebGPU init failures during boot.
 *
 * Rack modules: use {@link openRackModule} — Rack mounts only `selectedTrack`.
 */

/**
 * Fail boot on real AudioContext / WebGPU *init* failures — not expected
 * EngineFallback messages when the VM/CI runner has no GPU adapter.
 */
const CONSOLE_FAIL_RE =
  /Failed to (start|create|resume).*AudioContext|AudioContext.*(not allowed|suspended permanently)|InvalidStateError.*AudioContext|WebGPU.*(device lost|validation error|uncaptured)/i;
const CONSOLE_IGNORE_RE =
  /Download the React DevTools|\[devtools\]|Supertonic TTS failed|EngineFallback|requestAdapter\(\) returned null|worklet ready timeout/i;

export type BootOptions = {
  /** Extra query string without leading `?`. Default: `e2e=1`. */
  query?: string;
  /** Skip console-error assertion. */
  allowConsoleNoise?: boolean;
};

export async function initializeHyphonAudio(
  page: Page,
  options: BootOptions = {},
): Promise<void> {
  const errors: string[] = [];
  const onConsole = (msg: { type: () => string; text: () => string }) => {
    if (msg.type() !== 'error') return;
    const text = msg.text();
    if (CONSOLE_IGNORE_RE.test(text)) return;
    if (CONSOLE_FAIL_RE.test(text)) errors.push(text);
  };
  const onPageError = (err: Error) => {
    if (CONSOLE_IGNORE_RE.test(err.message)) return;
    errors.push(err.message);
  };

  if (!options.allowConsoleNoise) {
    page.on('console', onConsole);
    page.on('pageerror', onPageError);
  }

  const qs = options.query ?? 'e2e=1';
  await page.goto(`/?${qs}`);

  const overlay = page.getByTestId('start-overlay');
  const startBtn = page.getByTestId('initialize-system');

  // Overlay paints as soon as React mounts; the button stays disabled until
  // hyphon_native + vendored Pyodide (numpy/scipy) finish. Firefox/WebKit on a
  // loaded runner take ~70s+ — 90s was racing the scipy wheel.
  await overlay.waitFor({ state: 'visible', timeout: 90_000 });
  await expect(startBtn).toBeEnabled({ timeout: 180_000 });

  // Real gesture required for AudioContext.resume() — especially WebKit.
  await startBtn.click();

  await overlay.waitFor({ state: 'hidden', timeout: 30_000 });

  // LoadingOverlay covers the rack until initializeAudio finishes. Waiting only
  // for Start Playback is insufficient (header stays mounted under the overlay).
  await expect(page.getByText('INITIALIZING AUDIO ENGINE')).toBeHidden({
    timeout: 120_000, // cold WASM / worklet warm-up on CI
  });

  await expect(
    page.getByRole('button', { name: 'Start Playback', exact: true }),
  ).toBeVisible({ timeout: 30_000 });

  // Dismiss non-blocking UI chrome that can steal clicks / confuse snapshots.
  const dismissWhatsNew = page.getByRole('button', { name: /Dismiss what's new/i });
  if (await dismissWhatsNew.isVisible().catch(() => false)) {
    await dismissWhatsNew.click().catch(() => undefined);
  }
  // HelpTip first-use pins (pointer-events-auto) sit over rack controls.
  await dismissHelpTips(page);
  const closeToast = page.getByRole('button', { name: 'Close notification' });
  while (await closeToast.count()) {
    await closeToast.first().click().catch(() => undefined);
    if (!(await closeToast.count())) break;
  }

  if (!options.allowConsoleNoise && errors.length > 0) {
    throw new Error(
      `Boot console/page errors (AudioContext/WebGPU):\n${errors.join('\n')}`,
    );
  }
}

/** Dismiss any pinned HelpTip / What's New "Dismiss" buttons. */
export async function dismissHelpTips(page: Page): Promise<void> {
  for (let i = 0; i < 8; i++) {
    try {
      const dismiss = page.getByRole('button', { name: 'Dismiss', exact: true });
      const n = await dismiss.count();
      if (n === 0) break;
      await dismiss.first().click({ force: true }).catch(() => undefined);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      if (/Target (crashed|page|closed)|browser has been closed/i.test(msg)) return;
      throw err;
    }
  }
}

/**
 * Native DOM click — bypasses Playwright hit-testing entirely.
 *
 * Kept for the rare control that is genuinely occluded, but prefer a real
 * `click()`: HardwareModule no longer swallows pointerdowns aimed at its DOM
 * overlays (#1035), so module controls respond to real user input and the specs
 * should exercise that path rather than a synthetic event a user cannot produce.
 */
export async function domClick(locator: Locator): Promise<void> {
  await locator.evaluate((el) => {
    if (el instanceof HTMLElement) el.click();
  });
}

/**
 * Sequencer row labels → rack modules. The Rack mounts ONLY `modules[selectedTrack]`,
